window.KURAN_MEALS=window.KURAN_MEALS||{};window.KURAN_MEALS["ibnkesir"]=[[{"n":1,"t":"Rahman, Rahim olan Allah’ın adıyla"},{"n":2,"t":"Hamd; alemlerin Rabbı Allah’a mahsustur."},{"n":3,"t":"Rahman’dır, Rahimdir."},{"n":4,"t":"Din gününün malikidir."},{"n":5,"t":"Yalnız Sana ibadet ederiz ve yalnız Senden yardım dileriz."},{"n":6,"t":"Bizi dosdoğru yola ilet."},{"n":7,"t":"Nimete erdirdiklerinin yoluna, gazaba uğrayanların ve dalalete düşenlerinkine değil."}],[{"n":1,"t":"Elif, Lam, Mim"},{"n":2,"t":"İşte bu kitab, onda hiç bir şüphe yoktur, müttekiler için hidayettir."},{"n":3,"t":"Onlar ki gayba inanırlar. Namazı kılarlar ve kendilerine rızık olarak verdiğimiz şeylerden de infak ederler."},{"n":4,"t":"Onlar ki sana indirilene de, senden önce indirilmiş olanlara da inanırlar. Ve onlar ahireti de yakınen tanırlar."},{"n":5,"t":"İşte onlar, rablarından bir hidayet üzeredirler ve işte onlar, felaha erenlerdir."},{"n":6,"t":"Şüphesiz ki o küfretmiş olanları uyarsan da uyarmasan da birdir, inanmazlar."},{"n":7,"t":"Allah onların kalblerini ve kulaklarını mühürlemiştir. Gözlerinin üzerinde bir perde vardır ve onlar için büyük bir azab vardır."},{"n":8,"t":"İnsanlardan öyleleri vardır ki inanmadıkları halde Allah’a ve ahiret gününe inandık, derler."},{"n":9,"t":"Allah’ı da, iman edenleri de aldatmaya çalışırlar. Oysa kendilerinden başkasını aldatamazlar da, bunun farkında değiller."},{"n":10,"t":"Kalblerinde hastalık vardır. Allah da hastalıklarını artırdı. Yalan söylemekte olduklarından dolayı onlara elem verici bir azab vardır."},{"n":11,"t":"Kendilerine: yeryüzünde bozgun çıkarmayın, denildiğinde, biz ancak ıslah edicileriz, derler."},{"n":12,"t":"Bilesin ki onlar, fesadçıların ta kendileridir de bunun farında değiller."},{"n":13,"t":"Onlara; insanların inandıkları gibi siz de inanın, denilince; o beyinsizlerin inandığı gibi mi biz de inanacağız? derler. Bilesin ki asıl beyinsizler onlardır da bunu bilmezler."},{"n":14,"t":"Mü’minlere rastlayınca; inandık, derler. Şeytanları ile başbaşa kalınca da; biz sizinle beraberiz, onlarla sadece istihza etmekteyiz, derler."},{"n":15,"t":"Allah da onlarla istihza eder ve azgınlıklarında şaşkın bir halde dolaştırır."},{"n":16,"t":"Onlar; hidayet karşılığı sapıklığı satın almış kimselerdir. Ticaretleri kendilerine kar sağlamamıştır. Ve onlar hidayete ermişlerden değildirler."},{"n":17,"t":"Onların misali; ateş yakan kimsenin misali gibidir ki, ateş çevresindekileri aydınlatınca, Allah onların ışığını giderdi. Karanlıkların içerisinde görmez halde bırakıverdi."},{"n":18,"t":"Sağırdırlar, dilsizdirler, kördürler. Onlar artık dönmezler."},{"n":19,"t":"Yahut gökten inen sağnağa tutulmuş gibilerdir ki; onda karanlıklar, gök gürültüsü ve şimşek vardır. Yıldırımlardan ölmek korkusuyla parmaklarını kulaklarına tıkarlar. Allah kafirleri çepeçevre kuşatıcıdır."},{"n":20,"t":"Az kalsın şimşek gözlerini alıverecek. Onları aydınlattıkça ışığında yürürler. Üzerlerine karanlık basınca dikilip kalıverirler. Şayet Allah, dileseydi onların işitmelerini de, görmelerini de giderirdi. Muhakkak ki Allah, her şeye Kadir’dir."},{"n":21,"t":"Ey insanlar; sizi de, sizden öncekileri de yaratan Rabbınıza ibadet edin, ta ki, takva sahibi olasınız."},{"n":22,"t":"O ki; yeryüzünü sizin için bir döşek, göğü de bir bina yaptı. Gökten su indirip onunla türlü türlü meyvelerden sizin için rızık çıkardı. O halde bile bile Allah’a eşler koşmayınız."},{"n":23,"t":"Eğer siz, kulumuza indirdiğimizden şüphede iseniz, haydin ona benzer bir sure getirin. Allah’dan başka şahidlerinizi de çapırın; eğer doğru sözlüler iseniz..."},{"n":24,"t":"Fakat yapamazsınız-ki yapamayacaksınız-o halde yakıtı insanlarla taşlar olan ateşten sakının. O kafirler için hazırlanmıştır."},{"n":25,"t":"İman eden, salih ameller işleyenlere; altından ırmaklar akan cennetlerin kendileri için olduğunu müjdele. Onlara ne zaman bunlardan bir meyve rızık olarak verilirse bu, evvelce rızıklandığımız şeydi, derler. Onlara birbirine benzeyen (böyle nimetler) verilecek. Onlar için orada temiz eşler de vardır. Hem onlar orada temelli kalıcıdırlar."},{"n":26,"t":"Şüphe yok ki, Allah, bir sivri sineği ve ondan küçük bir şeyi misal getirmekten çekinmez. İman etmiş olanlar bunun Rablarından bir gerçek olduğunu bilirler. Kafirler ise; Allah bu misali vermekle ne murad etmiş? derler. Allah onunla bir çoğunu sapıtır, bir çoğunu da hidayete erdirir. Bununla fasıklardan başkasını saptırmaz."},{"n":27,"t":"Allah’ın ahdini pekiştirdikten sonra bozanlar, birleştirilmesini emrettiği şeyi koparanlar, yeryüzünde fesad çıkaranlar, işte onlar hüsrana uğrayanların ta kendileridir."},{"n":28,"t":"Nasıl oluyor da Allah’ı inkar ediyorsunuz? Halbuki siz ölüler iken O diriltti. Sonra sizi öldürecek, sonra tekrar diriltecek, en sonunda yalnız O’na döndürüleceksiniz."},{"n":29,"t":"Yerde ne varsa hepsini sizin için yaratan, sonra göğe yönelip onları yedi gök halinde düzenleyen O’dur. O, her şeyi bilendir."},{"n":30,"t":"Hani Rabbın meleklere: Ben, yeryüznde bir halife yaratacağım, demişti de melekler: Biz seni hamd ile tesbih, takdis eder dururken yeryüzünde fesad çıkarıp, kanlar dökecek kimse mi yaratacaksın? demişlerdi. Allah da: Sizin bilmediklerinizi ben bilirim, buyurmuştu."},{"n":31,"t":"Allah, Adem’e bütün isimleri öğretmiş, sonra onları meleklere göstererek: Eğer sadıklardan iseniz, bunların adlarını bana söyleyin, buyurmuştur."},{"n":32,"t":"Melekler ise: Sana tesbih ederiz, bize öğrettiğinden başka bilgimiz yok. Alim, Hakim Sensin Sen, demişlerdi."},{"n":33,"t":"Allah: Ey Adem, onları’adları ile kendilerine bildir, dedi. Adem, adlarını söyleyince; Size demedim mi ki ben, göklerin de, yerin de gizliliklerini muhakkak bilirim. Ve sizlerin neyi açıklayıp neyi gizler olduğunuzu da bilirim, buyurdu."},{"n":34,"t":"Hani meleklere: Adem’e secde edin demiştik de onlar hemen secde edivermişlerdi. Sadece şeytan kaçınmış, büyüklük taslamış ve kafirlerden olmuştu."},{"n":35,"t":"Ve demiştik ki: Ey Adem, sen, eşinle birlikte cennette otur. Dilediğiniz O’na döndürüleceksiniz."},{"n":36,"t":"Nihayet şeytan onları cennetten kaydırdı. Onları bulundukları yerden çıkardı. Biz de: Kiminiz kiminize düşman olarak inin. Yeryüzünde sizin için bir zamana kadar yerleşim ve faydalanma vardır, dedik."},{"n":37,"t":"Adem, Rabbından kelimeler belleyip aldı. Bunun üzerine onun tevbesini kabul etti. Şüphesiz ki Tevvab, Rahim O’dur, O."},{"n":38,"t":"Dedik ki; hepiniz oradan inin. Eğer, tarafımdan size bir hidayet gelir de, kim benim hidayetime uyarsa, artık onlar için hiçbir korku yoktur. Ve onlar mahzun da olacak değillerdir."},{"n":39,"t":"Küfredenler, ayetlerimizi yalanlamış olanlar, işte onlar cehennemliklerdir. Ve onlar ateşte temelli kalıcıdırlar."},{"n":40,"t":"Ey İsrailoğulları, size verdiğim nimetimi hatırlayın. Bana verdiğiniz sözü yerine getirin ki, ben de size olan sözümü yerine getireyim. Ve yalnız Ben’den korkun."},{"n":41,"t":"Yanınızdaki Tevrat’ı tasdik edici olarak indirdiğime iman edin. Onu inkar edenlerin ilki olmayın. Ayetlerimizi az bir paha ile satmayın. Ve yalnız Ben’den sakının."},{"n":42,"t":"Hakkı batıla karıştırıp da, bile bile siz gerçeği gizlemeyin."},{"n":43,"t":"Namazı kılın, zekatı verin, rüku’ edenlerle birlikte rüku edin."},{"n":44,"t":"Siz; insanlara iyiliği emreder de, kendinizi unutur musunuz? Halbuki kitabı da okuyorsunuz, hiç aklınızı başınıza almayacak mısınız?"},{"n":45,"t":"Sabır ve namazla (Allah’tan) yardım isteyin. Gerçi bu, ağır gelir ama, huşu duyanlara değil."},{"n":46,"t":"Onlar ki; Rablarına kavuşacaklarını, O’na döneceklerini kesinlikle bilirler."},{"n":47,"t":"Ey israiloğulları, size verdiğim nimetimi ve sizi alemlere üstün kıldığımı hatırlayın."},{"n":48,"t":"Ve öyle bir günden korkun ki; o günde kimse, kimse için bir şey ödeyemez. Şefaat kabul edilmez. Fidye alınmaz ve onlara yardım da edilmez."},{"n":49,"t":"Hani, sizi oğullarınızı boğazlayıp, kadınlarınızı sağ bırakarak en kötü işkenceye tabi tutan Firavun hanedanından kurtarmıştık. Bu da sizin için Rabbınız tarafından büyük bir imtihandı."},{"n":50,"t":"Hani, bir de sizin için denizi yarmış, ve sizi kurtarmıştık. Firavun hanedanını da, siz bakıp dururken suda boğmuştuk."},{"n":51,"t":"Ve hani, Musa ile kırk geceyi vaidleşmiştik. Yine siz zalimler olarak onun arkasından buzağıyı (tanrı) edinmiştiniz."},{"n":52,"t":"Bundan sonra sizi, şükredersiniz diye affetmiştik."},{"n":53,"t":"Hani, Musa’ya; hidayete eresiniz diye kitab ve furkan vermiştik."},{"n":54,"t":"Hani, Musa, kavmine: Ey kavmim, buzağıya tapınmakla nefsinize zulmetmiş oldunuz. Hemen yaradanınıza tevbe edip nefislerinizi öldürün. Bu yaradanınızın katında sizin için daha hayırlıdır, demişti. Allah da tevbenizi kabul etmişti. Muhakkak ki Tevvab, Rahim O’dur, O."},{"n":55,"t":"Bir de, hani siz: Ey Musa, biz Allah’ı apaşikar görünceye kadar sana inanmayacağız, demiştiniz de, bakıp dururken sizi yıldırım çarpmıştı."},{"n":56,"t":"Sonra sizi, ölümünüzün arkasından şükredersiniz diye diriltmiştik."},{"n":57,"t":"Ve üstünüze bulutları gölge yaptık. Kudret helvası ve bıldırcın indirdik. Size rızık olarak verdiğimiz şeylerin iyilerinden, güzellerinden yeyin. Onlar bize değil ancak kendi nefislerine zulmekteydiler."},{"n":58,"t":"Hani; şu kasabaya girin, dilediğiniz yerde istediğinizi bol bol yeyin, kapısından secde ederek girin, affet deyin, kusurlarınızı örtelim. İyilik"},{"n":59,"t":"Zulmedenler, sözü; kendilerine söylenenden başkasıyla değiştirdiler. Biz de fasıklık etmelerinden dolayı o zalimlerin üstüne gökten korkunç bir azab indirdik."},{"n":60,"t":"Hani, bir vakit Musa, kavmi için su arayınca; asanla taşa vur, demiştik de, taştan oniki çeşme fışkırmış, her zümre su alacağı yeri öğrenmişti. Allah’ın rızkında yeyin, için, yalnız yeryüzünde bozgunculuk yaparak, karışıklık çıkarmayın."},{"n":61,"t":"Hani; siz, Ey Musa, biz bir çeşit yemeğe elbette dayanamayız. Rabbına dua et de bizim için yerde yetişen samısak, sebze, acur, mercimek ve soğan bitirsin, demiştiniz, Musa da; siz bayağı olan şeyle hayırlı olanı değiştirmek mi istiyorsunuz? Öyleyse bir şehre inin, istediğiniz şeyler vardır, demişti."},{"n":62,"t":"Şüphesiz ki Mü’minler, Yahudiler, Nasrani ve Sabiilerden; kim Allah’a ve ahiret gününe inanıp, salih amelde bulunursa, elbette onların Rabları katında mükafaatları vardır. Hem onlara bir korku yoktur, mahzun da olacak değildirler."},{"n":63,"t":"Hani sizden sapasağlam söz almıştık. Tur’u da üstünüze kaldırmıştık. Size veridğimize sımsıkı sarılın, onda olanları hatırlayın ki sakınmış olasınız."},{"n":64,"t":"Sonra o sözü müteakip yine yüz çevirdiniz. Eğer üstünüzde Allah’ın fazlu rahmeti olmasaydı hüsrana uğrayanlardan olurdunuz."},{"n":65,"t":"Andolsun ki, içinizden cumartesi günü haddi aşanları elbette bilirsiniz. İşte biz onlara: Aşağılık maymunlar olun, dedik."},{"n":66,"t":"Artık bunu hem önündekilere, hem de ardındakilere ibret verici bir ceza, hem de müttakilere bir öğüt kıldık."},{"n":67,"t":"Hani, bir de Musa kavmine: Allah, herhalde bir sığır boğazlamanızı emrediyor, demişti. Onlar: Sen bizimle alay mı ediyorsun, demişlerdi. Musa da: Ben cahillerden olmaktan Allah’a sığınırım, demişti."},{"n":68,"t":"Onlar, Bizim için Rabbına dua et de onu bize iyice bildirsin, demişlerdi. Musa da: Allah, o, ne çok kart, ne de çok körpedir. İkisi ortası dinç bir sığırdır, buyuruyor. Artık emrolunduğunuz şeyi yapın, demişti."},{"n":69,"t":"Dediler ki: Bizim için Rabbına dua et de onun ne renk olduğunu bize iyice açıklasın. O da: Rabbım diyor ki: O bakanları rahatlatacak sapsarı renkli bir inektir, demişti."},{"n":70,"t":"Dediler ki: Rabbına dua et, bize açıkça niteliğnin ne olduğunu bildirsin. Çünkü bizce sığırlar birbirine benziyor. Allah dilerse biz elbette hidayete erenlerden oluruz."},{"n":71,"t":"Dedik ki: Rabbım, o, ne boyunduruğa koşulup arazi sürecek, ne de ekin sulayacak bir inektir, zillete uğramamıştır. Bütün kusurlardan uzaktır. Onun alacası da yoktur, buyuruyor. Onlar: İşte şimdi gerçeği ortaya koydun, dediler. Hemen onu boğazladılar ki az kalsın bunu yapmayacaklardı."},{"n":72,"t":"Hani, siz bir kişiyi öldürmüştünüz de; sonra o konuda birbirinizle çekişmeye başlamıştınız. Allah ise sizin gizlediğinizi açığa çıkarıcıdır."},{"n":73,"t":"Sığırın bir parçasını ölüye vurun, demiştik. İşte Allah ölüleri böyle diriltir. Ve sizlere ayetlerini gösterir ki, aklınızı başınıza alasınız."},{"n":74,"t":"Sonra bunun ardından kalbleriniz yine katılaştı. Şimdi onlar taş gibidir. Yahut daha da katı. Zira öylesi vardır ki; ondan ırmaklar kaynar, öylesi vardır ki; yarılıp ondan su fışkırır, öylesi de vardır ki; Allah korkusundan yuvarlanır. Allah, yaptıklarınızdan asla gafil değildir."},{"n":75,"t":"Onların size inanacaklarını mı umuyorsunuz? Onlardan öyle bir zümre vardı ki, Allah’ın kelamını dinlerlerdi de akılları yattıktan sonra, bile bile bunu değiştirirlerdi."},{"n":76,"t":"Mü’minlerle karşılaştıkları zaman, inandık derlerdi, birbirleriyle baş başa kaldıklarında, Rabbınızın katında, aleyhinde delil göstersinler diye mi Allah’ın size açıkladığını onlara anlatıyorsunuz, buna aklınız ermiyormu? diye birbirlerini uyarırlardı."},{"n":77,"t":"Bilmiyorlarmı ki; ne gizlerler, ne açıklarlarsa Allah hepsini bilir."},{"n":78,"t":"Onlardan bir kısmı ümmidirler, kitabı anlamazlar. Bir takım batıl şeyleri onlar sadece zanneder dururlar."},{"n":79,"t":"Vay, kitabı elleriyle yazıp da sonra az bir paha ile satabilmek için; bu, Allah katındandır, diyenlerin, ellerinin yazdıklarından dolayı vay onlara! Vay onlara. O kazanmış oldukları yüzünden."},{"n":80,"t":"Sayılı günlerden başka asla bize ateş dokunmayacaktır dediler. Deki: Siz Allah katından bir söz mü aldınız? Öyleyse Allah asla sözünden caymaz. Yoksa Allah’a karşı bilmediğiniz bir şey mi söylüyorsunuz."},{"n":81,"t":"Hayır, kötülük yapıp da günahı kendisini kuşatan kimseler, işte onlar cehennemliklerdir. Onlar orada temelli kalıcıdırlar."},{"n":82,"t":"İman edip, salih ameller işleyenler; işte onlar cennetliklerdir. Onlar orada temelli kalıcıdırlar."},{"n":83,"t":"Hani, İsrailoğullarından; Allah’tan başkasına ibadet etmeyin; anaya, babaya, akrabalara, yetimlere, yoksullara iyilik yapın. İnsanlara güzellikle söyleyin, namaz kılın zekat verin diye söz almıştık. Sonra pek azınız müstesna yüz çevirdiniz. Ve siz hala yüz çevirenlerdensiniz."},{"n":84,"t":"Hani; bir de kanınızı dökmeyin, birbirinizi yurdunuzdan sürmeyin diye söz almıştık, sonra bunu ikrar ettiniz ve şahid de oldunuz."},{"n":85,"t":"Sonra sizler; birbirinizi öldüren, aranızdan bir takımını yurtlarından süren, onlara karşı günah ve düşmanlıkla birleşen, onları (yurtlarından) çıkarmak haram kılınmışken esir olarak geldiklerinde fidyeleşmeye kalkan kimselersiniz. Yoksa kitabın bir kısmına inanıp bir kısmını inkar mı ediyorsunuz? Sizden böyle yapanın cezası; dünya hayatında rezil olmaktan başka birşey değildir. Kıyamet gününde ise onlar, azabın en şiddetlisine uğratılırlar. Allah, yaptıklarınızdan gafil değildir."},{"n":86,"t":"İşte onlar, ahirete karşı dünya hayatını satın almış olanlardır. Bu yüzden kendilerinden azab kaldırılıp, hafifletilmeyecek, yardım da yapılmayacaktır."},{"n":87,"t":"Andolsun ki, biz Musa’ya kitab verdik. Ondan sonra da birbiri ardınca peygamberler gönderdik. Meryem oğlu İsa’ya da beyyineler verdik. Ve onu ruh’ül-Kudüs ile destekledik. Demek, bir peygamber size ne zaman gönüllerinizin hoşlanmadığı bir şeyi getirirse, kibirlenmek isteyeceksiniz de; kimini yalanlayarak, kimini de öldüreceksiniz öyle mi?"},{"n":88,"t":"Dediler ki; bizim kalblerimiz perdelidir. Öyle değil, Allah küfürlerinden dolayı onları la’netlemiştir. Onların pek azı inanırlar."},{"n":89,"t":"Ne zaman ki; Allah’ın katından, kendilerinde olanı tasdik eden kitab geldi, onlar bundan önceki küfredenlere karşı kendilerine yardım gelmesini beklerlerken, bildikleri gelince onu inkar ettiler. Allah’ın la’neti kafirlerin üzerinedir."},{"n":90,"t":"Nefislerini ne kötü şeye değişip sattılar. Allah’ın kullarından dilediğine fazlından indirmesine hased ederek Allah’ın indirdiğini inkar ettiler ve gazab üstüne gazaba uğradılar. Küfredenlere alçaltıcı bir azab vardır."},{"n":91,"t":"Bir de onlara Allah’ın indirdiğine inanın, denilince; biz, bize indirilene inanırız derler. Ondan başkasını inkar ederler. Halbuki o beraberlerindekini tasdik eden bir kitabdır. De ki: İnanmış kimseler idiyseniz neden daha önce, Allah’ın peygamberlerini öldürüyordunuz?"},{"n":92,"t":"And olsun ki, Musa size apaçık delillerle geldi. Sonra ardından buzağıyı Rabb edindiniz. Ve siz zalimlersiniz."},{"n":93,"t":"Hani; size verdiğimiz şeyi kuvvetle tutun ve dinleyin, diye Tur’u tepenize dikmiş ve sizden misak almıştık. İşittik ve karşı geldik dediler ve küfürleri yüzünden buzağı sevgisi kalblerine sindirildi. Eğer inananlardansanız, inancınız size ne kötü şey emrediyor? de."},{"n":94,"t":"De ki; Allah katında ahiret yurdu başkalarının değil de yalnız sizin ise, bu iddiada samimi iseniz haydin, ölümü isteyin."},{"n":95,"t":"Önceden ellerinin kazandığından dolayı, onlar hiçbir zaman onu isteyemezler, Allah zalimleri hakkıyla bilir."},{"n":96,"t":"And olsun ki; onları, insanlardan şirk koşanlardan daha çok hayata düşkün bulacaksın. Onlardan herbiri bin yıl ömür verilmesini ister. Halbuki çok yaşatılması onu azabtan uzaklaştıracak değildir. Allah onların ne yaptığını hakkıyla görendir."},{"n":97,"t":"De ki; kim Cebrail’e düşmansa (bilsin ki;) elinin önündekileri tasdik eden, mü’minler için hidayet ve müjde olan senin kalbine Allah’ın izniyle o indirmiştir."},{"n":98,"t":"Kim Allah’a, meleklerine, peygamberlerine, Cebrail’e ve Mikail’e düşman olursa; şüphesiz ki, Allah’da kafirlerin düşmanıdır."},{"n":99,"t":"And olsun ki; biz sana apaçık ayetler indirdik. Onları fasıklardan başkası inkar etmez."},{"n":100,"t":"Onlar, ne zaman bir ahidle bağlandılarsa içlerinden bir güruh onu bozup atmadı mı? Hayır, onların bir çoğu iman etmezler."},{"n":101,"t":"Onlara, ne zaman Allah tarafından yanlarındaki kitabı tasdik edici bir peygamber geldiyse, kendilerine kitab verilenlerden bir güruh, sanki bilmiyormuş gibi, Allah’ın kitabını arkalarına atıverdi."},{"n":102,"t":"Ve onlar şeytanların Süleyman’ın mülkü aleyhine uydurdukları şeylerin ardına düştüler. Halbuki Süleyman asla küfretmedi. Sadece şeytanlar küfrettiler. Onlar, insanlara sihri ve Babil’de ki iki meleğe; Harut ile Marut a indirilenleri öğretiyorlardı. Bu iki melek ise: «Biz ancak imtihan için gönderildik, sakın küfretme. «demedikçe kimseye sihirden bir şey öğretmezlerdi. Onlardan koca ile karısının arasını ayıracak şeyler öğrendiler. Halbuki bunlar, Allah’ın izni olmadıkça o sihirle kimseye zarar verici değillerdi. Onlarsa kendilerine zarar verip fayda vermeyen şeyleri öğreniyorlardı. Andolsun ki, onlar onu satın alan kimse için ahirette hiçbir olmayacağını biliyorlardı. Ne fena birşey karşılığında nefislerini sattılar. Şayet bilmiş olsalardı?"},{"n":103,"t":"Eğer onlar inanmış ve sakınmış olsalardı; Allah katındaki sevab daha hayırlı olurdu. Keşke bilselerdi."},{"n":104,"t":"Ey iman edenler; bizi de dinle, demeyin, bizi de gözet, deyin ve dinleyin. Kafirlere elim bir azab vardır."},{"n":105,"t":"Ehl-i Kitab’dan kafir olanlar da, müşrikler de Rabbınızdan size hiç bir hayır indirilmesini istemezler. Allah, rahmetini dilediğine tahsis eder. Allah, büyük lütuf ve ihsan sahibidir."},{"n":106,"t":"Biz, bir ayeti nesheder veya unutturursak ondan daha hayırlısını, yahut da dengini getiririz. Bilmez misin ki, Allah şüphesiz her şeye kadir’dir."},{"n":107,"t":"Göklerin ve yerin mülkünün gerçekten Allah’a ait olduğunu ve sizin için Allah’dan başka bir sahib ve yardımcı olmadığını bilmez misiniz?"},{"n":108,"t":"Yoksa daha önce Musa’ya sorulduğu gibi siz de peygamberinizi sorguya çekmek mi istiyorsunuz? Kim imanı küfürle değişirse dosdoğru yoldan sapıtmış olur."},{"n":109,"t":"Kitab ehlinin çoğu, hak kendilerine apaçık belli olduktan sonra içlerindeki çekememezlikten ötürü, sizi imandan sonra küfre döndürmek isterler. Allah’ın açıklayıcı emri gelene kadar onları affedin, geçin. Şüphesiz ki Allah her şeye kadir’dir."},{"n":110,"t":"Namazı kılın, zekatı verin, kendiniz için önceden ne yollarsanız, onu Allah katında bulursunuz. Şüphesiz ki Allah, yaptığınızı hakkıyla görendir."},{"n":111,"t":"Ve dediler ki: Yahudi ve Hristiyan olanlardan başkası cennete girmeyecek. Bu onların kuruntusudur. De ki: Eğer sadıklar dan iseniz delilinizi getirin."},{"n":112,"t":"Hayır, kim ihsan edici olarak özünü tastamam Allah’a teslim ederse ona Rabbı katında mükafat vardır. Onlara korku yoktur, üzülmeyeceklerdir de."},{"n":113,"t":"Yahudiler: Hristiyanlar hiç bir şeye sahip değildir, dedi. Hristiyanlar da yahudiler hiç bir şeye sahip değildir, dedi. Halbuki hepsi de kitabı okuyorlar. Bilmeyen kimseler de onların dedikleri gibi dedi. İhtilafa düşer oldukları şeyde kıyamet günü Allah aralarında hükmünü verecektir."},{"n":114,"t":"Allah’ın mescidlerinde; O’nun isminin anılmasını men’eden, onların harab olmasına çalışandan daha zalim kim vardır? Onların oralara korka korka girmekten başka hakkı yoktur. Dünyada rüsvaylık onlarındır. Ahirette ise onlara büyük bir azab vardır."},{"n":115,"t":"Doğu da Batı da Allah’ındır. Her nereye dönerseniz vech-i ilahi oradadır. Şüphesiz ki Allah Vasi’dir, Alim’dir."},{"n":116,"t":"Dediler ki: Allah çocuk edindi. Tenzih ederiz O’nu. Doğrusu göklerde ve yerde ne varsa O’nundur. Hepsi de O’na itaat ederler."},{"n":117,"t":"Göklerin ve yerin yaratanıdır. Bir şeyin olmasını isteyince ona sadece «ol», der, o da oluverir."},{"n":118,"t":"Bilmeyenler dediler ki: Allah bizimle konuşmalı veya bize bir ayet gelmeli değil miydi? Onlardan öncekiler de onların dedikleri gibi demişlerdi. Kalbleri birbirine benzemiş. Biz yakınen bilmek isteyen bir kavme ayetlerimizi apaçık bildirdik."},{"n":119,"t":"Şüphesiz ki biz seni müjdeleyici ve korkutucu olarak hak ile gönderdik. Cehennem ashabından sen mes’ul olacak değilsin."},{"n":120,"t":"Sen, dinlerine uymadıkça Yahudiler de, Hristiyanlar da, senden asla hoşnud olmazlar. Allah’ın hidayeti asıl hidayetin ta kendisidir, de. Şayet sana gelen ilimden sonra, onların heveslerine uyacak olursan; and olsun ki senin için Allah tarafından ne bir yar bulunur, ne de bir yardımcı."},{"n":121,"t":"Kendilerine kitab verdiğimiz kimseler onu hakkıyla tilavet ederler. İşte buna onlar inanırlar. Kim ona küfrederse, hüsrana uğrayanlar da işte onlardır."},{"n":122,"t":"Ey İsrailoğulları, size ihsan etmiş olduğum nimetimi ve sizi alemlere üstün kıldığımı hatırlayın."},{"n":123,"t":"Ve öyle bir günden sakının ki, o gün kimse kimseden yana bir şey ödeyemez, kimseden bedel kabul olunmaz, şefaat fayda vermez ve yardım olunmaz."},{"n":124,"t":"Hani, İbrahim’i Rabb’ı bir takım kelimelerle imtihan etmişti de o da bunları tamamlayınca, Seni insanlara imam kılacağım, buyurmuştu. O da: Soyumdan da, demişti. Allah da; zalimler ahdime eremez buyurmuştu."},{"n":125,"t":"Hani; Biz Beyti insanlar için bir toplantı yeri ve emin bri mahal yapmıştık. Siz de İbrahim’in makamından bir namazgah edinin. İbrahim ile İsmail’e de evimi tavaf edenler, orada kalanlar rüku ve secde edenler için temizleyin, diye ahid vermiştik."},{"n":126,"t":"Hani, İbrahim demişti ki: Rabbım burasını emniyetli bir şehir yap. Ve halkından Allah’a, ahiret gününe iman etmiş olanları mahsullerle rızıklandır Allah da: Kafir olanı kısa bir zaman için geçindiririm. Sonra onu cehennem azabına zorlarım. Bu ne kötü bir sonuçtur, buyurmuştu."},{"n":127,"t":"Hani, İbrahim, Ka’be ’nin temellerini İsmail ile birlikte yükseltiyordu ve diyordu ki: Rabbımız bizden kabul buyur. Şüphesiz ki, Sensin Sen Semi’, Alim."},{"n":128,"t":"Rabbımız ikimizi de sana teslim olanlar kıl. Soyumuzdan da sana teslim olanlar yetiştir, bize ibadet edeceğimiz yerleri göster, tevbelerimizi kabul et. Çünkü Sensin Sen, Tevvab, Rahim."},{"n":129,"t":"Rabbımız, onların arasından, senin ayetlerin onlara okuyacak, kitabı, hikmeti öğretecek ve onları tezkiye edecek bir peygember gönder. Şüphesiz ki Aziz, Hakim Sensin Sen."},{"n":130,"t":"Kendini bilmezden başka kim İbrahim’in dininden yüz çevirir. And olsun ki dünyada onu seçmiştik. Muhakkak ki o, ahirette de salihlerdendir."},{"n":131,"t":"Hani, Rabbı ona; teslim ol buyurduğu zaman, o da, alemlerin Rabbına teslim oldum, demişti."},{"n":132,"t":"İbrahim bunu oğullarına da tavsiye etti. Ya’kub da: Ey oğullarım, Allah sizin için dinini seçti. Onun için siz de yalnız Müslüman olarak can verin, dedi."},{"n":133,"t":"Yoksa Ya’kub ’a ölüm geldiğinde siz orada mıydınız? Hani o, oğullarına: Benden sonra neye ibadet edeceksiniz? demişti. Onlar da: Senin İlah’ına ve ataların İbrahim’in, İshak’ın İlah’ına tek ilah olarak ibadet edeceğiz. Ve biz O’na teslim olmuşuz, demişlerdi."},{"n":134,"t":"Onlar bir ümmetti gelip geçti. Onların kazandıkları kendilerinin, sizin kazandığınız da sizin. Ve siz, onların yapmış olduklarından sorulmazsınız."},{"n":135,"t":"Yahudi veya Hristiyan olun ki hidayete eresiniz, dediler. De ki: Hayır, biz Hanif olan İbrahim’in dinine uyarız. O, müşriklerden değildi."},{"n":136,"t":"Biz; Allah’a, bize indirilmiş olana, İbrahim’e, İsmail’e, İshak’a, Ya’kub ’a, ve torunlarına indirilmiş olanlara, Musa’ya, İsa’ya verilenlere, peygamberlere Rabbları tarafından verilmiş olanlara iman ettik. Onların hiçbirinin arasını diğerinden ayırmayız. Biz ona teslim olmuşlardanız, deyin."},{"n":137,"t":"Onlar da, sizin iman ettiğiniz gibi iman ederlerse muhakkak doğru yolu bulmuşlardır. Şayet yüz çevirirlerse; şüphesiz ki onlar çekişme içerisindedirle. Onlara karşı Allah sana yetecektir. O, Semi’dir, Alim’dir."},{"n":138,"t":"Allah’ın boyası (ile boyandık). Boyası Allah’tan daha güzel olan kimdir? Biz O’na kulluk edenleriz."},{"n":139,"t":"Allah hakkında bizimle tartışıyor musunuz? Halbuki O, bizimde Rabbımız, sizim de Rabbınızdır. Bizim amellerimiz bize, sizin amelleriniz size aittir. Biz O’na muhlis kullarız, de."},{"n":140,"t":"Yoksa siz: İbrahim, İsmail, İshak, Ya’kub ve oğulları Yahudi veya Hristiyan idiler mi, diyorsunuz? Siz mi daha iyi biliyorsunuz yoksa Allah mı? Allah tarafından yanında bulunan şehadeti gizleyenden daha zalim kim vardır? Allah sizin yaptıklarınızdan gafil değildir, de."},{"n":141,"t":"Onlar bir ümmetti gelip geçti. Onların kazandıkları kendilerine, sizin kazandıklarınız da sizedir. Ve siz onların yapmış olduklarından sorulmazsınız."},{"n":142,"t":"İnsanlardan bir kısım beyinsizler diyeceklerdir ki: Onları üzerinde bulundukları kıblelerinden ne çevirdi? De ki: Doğu da Batı da Allah’ındır. O, dilediği kimseyi doğru yola iletir."},{"n":143,"t":"Böylece sizi vasat bir ümmet kıldık ki, insanların üzerine şahidler olasınız. Peygamber de sizin üzerinize şahid olsun. Ve senin üzerinde bulunduğun kıbleyi, peygambere uyanları, ayağının iki ökçesi üzerinde geri döneceklerden ayırdetmek için kıble yaptık. Gerçi bu, büyük bir şeydir. Ama Allah’ın doğru yola ilettiği kimseler için değil. Allah, elbette imanınızı zayi edecek değildir. Şüphesiz ki Allah, insanlara Rauf ve Rahim’dir."},{"n":144,"t":"Doğrusu biz, yüzünün semaya doğru çevrilip durduğunu görüyoruz. Şimdi seni hoşnud olacağın bir kıbleye çevireceğiz. Yüzünü Mescid-i Haram tarafına çevir. Nerede bulunursanız bulunun, yüzlerinizi o tarafa çevirin. Şüphesiz ki, kendilerine kitab verilenler bunun Rablarından gelen bir gerçek olduğunu bilirler. Allah, onların yaptıklarından gafil değildir."},{"n":145,"t":"Andolsun ki; sen, kendilerine kitab verilmiş olanlara her ayeti getirsen, onlar yine senin kıblene uymazlar. Sen de onların kıblesine uyacak değilsin. Onların kimi de, kiminin kıblesine uyacak değildirler. Andolsun ki; sana gelen bunca ilimden sonra şayet sen onların heveslerine uyacak olursan, o takdirde şüphesiz zalimlerden olursun."},{"n":146,"t":"Kendilerine kitab verdiklerimiz, onu oğullarını tanıdıkları gibi tanırlar. Öyle iken içlerinden bir güruh bilir oldukları halde, yine de hakkı gizlerler."},{"n":147,"t":"Hak, Rabbındandır. Öyleyse asla şüphecilerden olma!"},{"n":148,"t":"Herkesin bri yönü vardır oraya döner. Öyleyse siz hayırlı işlerde birbirinizle yarışın! Nerede bulunursanız bulunun, Allah hepinizi birden getirir. Şüphesiz ki Allah her şeye kadir’dir."},{"n":149,"t":"Nereden (yola) çıkarsan yüzünü Mescid-i Haram’a doğru çevir. Şüphesiz bu, Rabbından bir haktır. Allah, yaptıklarınızdan gafil değildir."},{"n":150,"t":"Nereden (yola) çıkarsan, yüzünü Mescid-i Haram’a doğru çevir. Siz de nerede olursanız, yüzünüzü o yana döndürün, Ta ki, zalim olanlardan başka insanların aleyhinizde bir delili bulunmasın. Artık onlardan korkmayın, Benden korkun ki, hem üzerinizdeki nimetimi tamamlayayım, hem de siz hidayeti ümid edebilesiniz."},{"n":151,"t":"Nitekim size içinizden; ayetlerimizi okuyan, sizi tezkiye eden kitabı ve hikmeti öğreten ve bilmediğiniz şeyleri bildiren bir peygamber gönderdik"},{"n":152,"t":"Öyleyse Beni zikredin ki, Ben de sizi anayım. Bir de Bana şükredin, nankörlük etmeyin."},{"n":153,"t":"Ey iman edenler, sabır ve namazla yardım isteyin. Şüphesiz ki Allah, sabredenlerle beraberdir."},{"n":154,"t":"Allah yolunda öldürülenlere; ölüler, demeyin. Bilakis onlar, diridirler, ama siz farketmezsiniz."},{"n":155,"t":"Andolsun ki sizi, biraz korku, biraz açlık, biraz da mallardan, canlardan ve mahsullerden yana eksiklikle imtihan edeceğiz, sabredenlere müjdele."},{"n":156,"t":"Ki onlara bir musibet geldiği zaman; biz Allah içiniz ve yine O’na döneceğiz, derler."},{"n":157,"t":"İşte onlar için Rabbları tarafından mağfiret ve rahmet vardır. Hidayete erenler de onlardır."},{"n":158,"t":"Şüphesiz ki Safa ile Merve Allah’ın nişanelerindendir. Artık kim hacc veya umre niyetiyle Ka’be ’yi ziyaret ederse bu ikisini de tavaf etmesinde bir beis yoktur. Kim gönüllü olarak iyilik yaparsa muhakkak ki Allah; Şakir’dir, Alim’dir."},{"n":159,"t":"İndirdiğimiz, açık delilleri ve hidayeti, kitabda insanlara açıkça beyan ettikten sonra gizleyenlere; muhakkak ki onlara, Allah la’net eder ve la’net etmek şanından olanlar da la’net eder."},{"n":160,"t":"Ancak tevbe edenler, islah edenler ve (gerçeği) söyleyenler müstesna. Ben; onların tevbelerini kabul ederim. Ve ben Tevvab, Rahim’im."},{"n":161,"t":"Muhakkak ki küfredip de, kafir olarak ölenlere Allah’ın, meleklerin ve bütün insanların la’neti işte onların üzerinedir."},{"n":162,"t":"Onun içinde temelli kalacaklardır. Onlardan ne azab hafifletilir, ne de yüzlerine bakılır."},{"n":163,"t":"Sizin İlahınız bir tek ilahtır. O’ndan başka hiçbir ilah yoktur. Rahman’dır, Rahim’dir."},{"n":164,"t":"Şüphesiz ki göklerin ve yerin yaratılışında, gece ile gündüzün değişmesinde, insanlara yararlı şeylerle denizde akan gemilerde, Allah’ın gökten indirip, yeryüzünü ölümünden sonra dirilttiği suda, her türlü canlıyı orada yaymasında, rüzgarların değiştirilmesinde, gökle yer arasında emre hazır bekleyen bulutta elbette akleden bir kavim için ayetler vardır."},{"n":165,"t":"İnsanlardan kimi de Allah’dan başkasını O’na emsal edinir, Allah’ı sever gibi onları severler. İman edenlerin, Allah sevgisi ise, daha fazladır. Zulmedenler azabı görecekleri zaman; bütün kuvvetin Allah’a ait olduğunu ve Allah’ın pek çetin azabı bulunduğunu keşki bilselerdi."},{"n":166,"t":"Hani o zaman uyulanlar, uyanlardan uzaklaşmış ve azabı görmüş oldular. Aralarındaki bütün bağlar kopmuştur."},{"n":167,"t":"Uyanlar dediler ki: Bizim için dönüş olsaydı da bizden uzaklaştıkları gibi, biz de onlardan uzaklaşsaydık. Böylece onların bütün yaptıklarını Allah hasretler halinde kendilerine gösterecektir ve onlar ateşten çıkacak değildirler."},{"n":168,"t":"Ey insanlar; yeryüzünde bulunan helal ve temiz şeylerden yeyin. Şeytanın adımlarına uymayın. Şüphesiz ki o, sizin için apaçık bir düşmandır."},{"n":169,"t":"O; size yalnız kötülüğü, hayasızlığı ve Allah’a karşı bilmeyeceğiniz şeyi söylemenizi emreder."},{"n":170,"t":"Onlara; Allah’ın indirdiğine uyun, denildiği zaman, onlar hayır, biz atalarımızın üzerinde bulunduğumuz şeye uyarız, dediler. Peki, ya ataları bir şey akledemeyen, doğruyu bulamayan kimseler olsa da mı?"},{"n":171,"t":"Küfredenlerin misali; bağırıp çağırmadan başka bir şey duymayana haykıranınki gibidir. Onlar sağırdırlar, dilsizdirler, kördürler, akledemezler."},{"n":172,"t":"Ey iman edenler; size rızık olarak veridğimiz şeylerin temiz olanlarından yeyin, Allah’a şükredin, eğer O’na kulluk ediyorsanız."},{"n":173,"t":"O, size; ölüyü, kanı, domuz etini, Allah’tan başkası için kesileni haram kılmıştır. Ancak kim mecbur kalırsa saldırmamak ve sınırı aşmamak şartıyla günah yoktur. Muhakkak ki Allah, Gafur’dur, Rahim’dir."},{"n":174,"t":"Allah’ın indirdiği kitabtan birşey gizleyip de, onu az bir pahaya satanlar; işte onlar karınlarına ateşten başka bir şey yemezler. Kıyamet günü Allah onlarla konuşmaz. Onları temize de çıkarmaz. Ve onlar için acıklı bir azab vardır."},{"n":175,"t":"Onlar, hidayet karşılığında dalaleti, mağfiret karşılığında azabı satın almışlardır. Onlar, ateşe karşı ne de sabırlıdırlar."},{"n":176,"t":"Bu, Allah’ın kitabı hak olarak indirilmiş olup, o kitabda ihtilafa düşenlerin şüphesiz ki, pek uzak bir şikak içinde olmalarındandır."},{"n":177,"t":"Yüzlerinizi Doğu ve Batı tarafına çevirmeniz «bir» değildir. Lakin asıl «bir»; Allah’a, ahiret gününe, meleklere, kitablara, peygamberlere iman eden, malını seve seve yakınlarına, yetimlere, miskinlere, yolculara, dilenenlere, kölelere, esirlere veren, namazı kılan, zekatı veren, muahede yaptıklarında ahidlerini yerine getiren, sıkıntıda, hastalıkta ve şiddetli savaş anında sabredenlerinkidir. İşte sadık olanlar da onlardır ve müttakiler de onlardır."},{"n":178,"t":"Ey iman edenler; öldürmede size kısas farz kılındı. Hür; hür ile, köle; köle ile, dişi; dişi ile. Ama kim de kardeşi tarafından affedilirse, ma’ruf olan emre ittiba etmeli ve ona güzellikle ödemelidir. Bu, Rabbınız tarafından bir hafifletme ve rahmettir. Kim, bundan sonra da tecavüzde bulunursa; onun için pek acıklı bir azab vardır."},{"n":179,"t":"Kısasta sizin için hayat vardır, ey akıl sahibleri. Ta ki, sakınasınız."},{"n":180,"t":"Sizden birinize ölüm geldiği zaman; eğer bir hayır bırakacaksa; anaya, babaya, yakın akrabaya, ma’ruf şekilde vasiyette bulunması farz kılındı. Bu, takva sahibleri üzerinde bir haktır."},{"n":181,"t":"Kim de onu işittikten sonra değiştirirse; onun günahı değiştirenlerindir. Şüphe yok ki Allah Semi’dir, Alim’dir."},{"n":182,"t":"Bununla birlikte, kim vasiyet edenin haksızlığa meylinden, günaha girmesinden korkup aralarını bulursa; ona da bir günah yoktur. Şüphesiz ki Allah, Gafur’dur. Rahim’dir."},{"n":183,"t":"Ey iman edenler; sizden öncekilere farz kılındığı gibi, size de oruç farz kılındı. Ta ki korunasınız."},{"n":184,"t":"Sayılı günler olarak. Sizden kim hasta veya seferde olursa, tutmadığı günler sayısınca diğer günlerde; gücü yetmeyenlere de bir yoksul doyumu fidye. Bununla beraber kim gönüllü olarak iyilik yaparsa bu; kendisi için"},{"n":185,"t":"Ramazan ayı; öyle bir aydır ki, insanlara doğru yolu gösteren, hak ile batılı ayıran Kur’an, o ayda indirilmiştir. Sizden her kim ayı görürse oruç tutsun. Kim de hasta olur veya seferde bulunursa, diğer günlerde o kadar oruç tutsun. Allah, sizin için kolaylık ister, güçlük istemez. Bu sayıyı tamamlamanız; size hidayet ihsan etmiş olduğundan Allah’ı tekbir ile yüceltmeniz içindir ve umulur ki şükredesiniz."},{"n":186,"t":"Kullarım, sana Beni sorarsa; şüphesiz ki Ben, çok yakınım. Bana dua edince Ben, o dua edenin duasına icabet ederim. Öyleyse onlar da Benim da’vetime icabet etsinler. Bana iman etsinler ki, doğru yola varmış olalar."},{"n":187,"t":"Oruç gecesi kadınlarınıza yaklaşmak size helal kılındı. Onlar sizin için, siz de onlar için bir elbisesiniz. Sizin nefislerinize hıyanet eder olduğunuzu Allah bildi de tevbenizi kabul edip, sizi bağışladı. Artık onlara yaklaşın ve Allah’ın hakkınızda yazdığını isteyin. Sizin için şafağın beyaz ipliği, siyah ipliğinden seçilinceye kadar yeyin, için sonra geceye kadar orucu tamamlayın. Mescidlerde i’tikafta bulunduğunuz zaman, kadınlarınıza yaklaşmayın. Bu Allah’ın hudududur. Sakın onlara yaklaşmayın. İşte Allah ayetlerini insanlara, korunsunlar diye böyle açıklar."},{"n":188,"t":"Mallarınızı aranızda batıl ile yemeyin. Ve insanların mallarından bir kısmını, siz bildiğiniz halde günahla yemek için onları hakimlere aktarmayın."},{"n":189,"t":"Sana yeni doğan aylardan soruyorlar. De ki: Onlar insanların faydası ve hacc için birer vakit ölçüleridir. Evlere arka taraflarından girmeniz «bir» değildir. Ancak «bir»; müttaki olanınkidir. Evlere kapılarından gelin. Allah’dan korkun ki, felaha eresiniz."},{"n":190,"t":"Size harb açanlarla, Allah yolunda siz de harbedin. Ancak haddi aşmayın. Şüphesiz ki Allah, haddi aşanları sevmez."},{"n":191,"t":"Ve onları nerede yakalarsanız öldürün. Sizi çıkardıkları yerden siz de onları çıkarın. Fitne, katilden beterdir. Onlar sizinle savaşmadıkça, siz de Mescid-i Haram’da onlarla savaşmayın. Ancak onlar sizinle savaşırlarsa, siz de onları öldürün. İşte kafirlerin cezası böyledir."},{"n":192,"t":"Eğer onlar vazgeçerlerse; şüphesiz ki Allah, Gafur’dur, Rahim’dir."},{"n":193,"t":"Fitne kalmayıp, din de Allah’ın oluncaya kadar onlarla savaşın. Vaz geçerlerse, artık zalimlerden başkasına düşmanlık yoktur."},{"n":194,"t":"Haram ay haram aya karşılıktır. Hürmetler karşılıklıdır. Kim size saldırırsa, siz de tıpkı onun saldırdığı gibi ona saldırın. Allah’tan korkun. Ve bilin ki Allah şüphesiz takva sahibleriyle beraberdir."},{"n":195,"t":"Allah yolunda infak edin ve ellerinizle kendinizi tehlikeye atmayın. İhsan edin, şüphesiz Allah ihsan edenleri sever."},{"n":196,"t":"Allah için haccı da; ümreyi de tamamlayın. Fakat alıkonulursanız, kurbandan kolayınıza geleni gönderin. Kurban yerine varıncaya kadar, başlarınızı tıraş etmeyin. İçinizden her kim, hasta olursa veya başında bir eziyet bulunursa; ona oruçtan, sadakadan veya kurbandan fidye. Emin olduğunuz vakitte; kim, hacc zamanına kadar umre ile faydalanmak isterse, kolayına gelen bir kurban keser. Ama bulamazsa, hacc günlerinde üç; döndüğünüz vakit yedi gün olmak üzere tam on gün oruç tutar. Bu; ailesi Mescid-i Haram’da oturmayanlar içindir. Allah’tan korkun. Ve bilin ki Allah, azabı pek şiddetli olandır."},{"n":197,"t":"Hacc, bilinen aylardır. Her kim o aylarda kendisine haccı farz ederse; artık haccda kadına yaklaşmak, günah işlemek, tartışma yoktur. Siz ne hayır yaparsanız, Allah onu bilir. Bir de azık edininiz. Şüphesiz ki, azığın en hayırlısı, takvadır. Ey akıl sahibleri; Ben’den korkun."},{"n":198,"t":"Rabbınızın lutf-u keremini aramanızda bir günah yoktur. Arafat’tan geri döndüğünüz zaman, Meş’ar-ı Haram’ın yanında Allah’ı zikredin. O, sizi hidayete ulaştırdığı gibi, siz de O’nu zikredin. Nitekim siz bundan önce, sapıklardan idiniz."},{"n":199,"t":"Sonra insanların döndüğü yerden siz de dönün. Ve Allah’tan mağfiret dileyin. Şüphesiz ki Allah Gafur’dur, Rahim’dir."},{"n":200,"t":"Hacc ibadetinizi bitirince; atalarınızı andığınız gibi, hatta daha kuvvetli bir anışla Allah’ı zikredin. İnsanlardan öylesi vardı ki; Ey Rabbımız, bize dünyada ver, der. Onun ahirette nasibi yoktur."},{"n":201,"t":"Kimi de; Ey Rabbımız, bize dünyada iyilik ver, ahirette de iyilik ver ve bizi ateş azabından koru, der."},{"n":202,"t":"İşte onların kazandıklarından nasibleri vardır. Ve Allah hesabı çabuk görendir."},{"n":203,"t":"Sayılı günlerde Allah’ı zikredin. Kim iki günde acele ederse, ona günah yoktur. Kim de geri kalırsa, ona günah yoktur. Bu; takva sahibi olanlar içindir. Allah’tan korkun ve bilin ki, şüphesiz siz, O’nun huzurunda toplanacaksınız."},{"n":204,"t":"İnsanlardan öylesi vardır ki; dünya hayatına dair sözü senin hoşuna gider. Ve Allah’ı kalbinde olana şahid tutar. Halbuki o, düşmanların en yamanıdır."},{"n":205,"t":"Ve o, yanından ayrılınca yeryüzünde fesad çıkarmaya, harsı ve nesli yok etmeye çalışır. Allah fesadı sevmez."},{"n":206,"t":"Ona; Allah’tan kork, denilince, gururu kendisini günaha sürükler. İşte ona cehennem yeter. O; ne kötü bir yataktır."},{"n":207,"t":"İnsanlardan öylesi de vardır ki; kendisini Allah’ın rızasına satar. Ve Allah, kullarına çok merhametlidir."},{"n":208,"t":"Ey iman edenler; hep birden barışa girin. Şeytanın adımlarına uymayın. Çünkü O, sizin için apaçık bri düşmandır."},{"n":209,"t":"Size apaçık deliller geldikten sonra yine kayarsanız; bilin ki Allah, şüphesiz Aziz’dir. Hakim’dir."},{"n":210,"t":"Onlar; Allah’ın buluttan gölgeler içinde, meleklerle birlikte kendilerine gelivermesini ve işlerini bitirivermesini mi bekliyorlar? Halbuki bütün işler Allah’a döndürülür."},{"n":211,"t":"Sor İsrailoğulları’na, onlara nice açık ayetler verdik. Kim, kendisine gelen Allah’ın nimetini değiştirirse, şüphesiz Allah’ın cezası pek şiddetlidir."},{"n":212,"t":"Küfredenlere dünya hayatı pek süslendi. Ve onlar, iman edenlerden kimiyle eğleniyorlar. Halbuki takvaya erenler kıyamet gününde onların üstündedirler. Allah, dilediğine hesabsız rızık verir."},{"n":213,"t":"İnsanlar bir tek ümmetti. Allah müjdeleyici ve korkutucu peygamberler gönderdi ve onlarla beraber insanların ihtilafa düştükleri şeylerde aralarında hüküm vermeleri için hak kitablar indirdi. Halbuki kitab verilmiş olanlar, kendilerinde açık deliller geldikten sonra aralarındaki ihtirastan dolayı ihtilafa düştüler. İşte Allah; kendi izniyle, iman edenleri, üzerinde ihtilafa düştükleri Hakka ulaştırdı. Allah dilediğini doğru yola ulaştırır."},{"n":214,"t":"Yoksa siz; sizden önce geçenlerin durumu başınıza gelmeden cennete girivereceğinizi mi sandınız? Onlara öyle yoksulluk, öyle sıkıntı gelmiş ve sarsıntıya uğramışlardı ki, nihayet Peygamber ve beraberindeki mü’minler: Allah’ın yardımı ne zaman? diyordu. Bilesiniz ki, Allah’ın yardımı pek yakındır."},{"n":215,"t":"Sana, ne infak edeceklerini soruyorlar. De ki: Hayırdan her ne infak ederseniz, babanın, akrabanın, yetimlerin, yoksulların, yolcuların hakkıdır. Ve her ne hayır işlerseniz, şüphesiz ki Allah, onu bilir."},{"n":216,"t":"Hoşunuza gitmediği halde, savaşı üzerinize farz kılınmıştır. Bir şey hoşunuza gitmediği halde sizin için hayırlı olabilir. Bir şey de hoşunuza gittiği halde sizin için kötü olabilir. Allah bilir, siz bilmezsiniz."},{"n":217,"t":"Sana haram aydan ve onda savaştan soruyorlar. De ki: O ayda savaşmak; büyük bir günahtır. Fakat insanları Allah yolundan alıkoymak ve O’nu inkar etmek, Mescid-i Haram’a gitmelerine engel olmak, onun ehlini oradan çıkarmak Allah katında daha büyük günahtır. Fitne, katilden de beterdir. Kafirlerin güçleri yetse, sizi dininizden döndürünceye kadar sizinle savaşa devam ederler. Sizden her kim dininden dönerde kafir olarak ölürse; onların yaptığı ameller dünyada da, ahirette de boşa gitmiştir. Ve onlar, cehennem ehlidirler. Orada temelli kalacaklardır."},{"n":218,"t":"Muhakkak ki, iman edenler, hicret edip de Allah yolunda savaşanlar; işte onlar Allah’ın rahmetini umarlar. Allah; Gafur’dur, Rahim’dir."},{"n":219,"t":"Sana içkiden ve kumardan soruyorlar. De ki: İkisinde de hem büyük günah, hem de insanlar için faydalar vardır. Günahları ise faydalarından daha büyüktür. Ve sana ne infak edeceklerini soruyorlar. De ki: İhtiyaçlarınızdan artanı. Düşünesiniz diye Allah size ayetlerini böyle açıklıyor."},{"n":220,"t":"Dünya ve ahiret konusunda. Ve sana yetimlerden soruyorlar. De ki: Onlar için islahta bulunmak hayırlıdır. Eğer kendileriyle bir arada yaşarsanız, onlar sizin kardeşlerinizdir. Allah; bozguncularla islahçı olanları bilir. Eğer Allah dileseydi; sizi muhakkak zahmete sokardı. Şüphe yok ki Allah, Aziz’dir. Hakim’dir."},{"n":221,"t":"İman edinceye kadar putperest kadınları nikahlamayın. İman eden bir cariye puta tapan bir kadındano hoşunuza gitse dedaha iyidir. İman edinceye kadar onları puta tapan erkeklerle de nikah ettirmeyin. İman eden bir köle, -hoşunuza gitse deputa tapan erkekten daha iyidir. Onlar sizi cehenneme çağırırlar. Allah ise cennete ve mağfirete çağırır ve öğüt alsınlar diye insanlara ayetlerini açıkça bildirir."},{"n":222,"t":"Sana adet halinden de soruyorlar. De ki: O, bir ezadır. Onun için adet halinde kadınlarınızdan ayrılın. Temizleninceye kadar onlara yaklaşmayın. İyice temizlendikleri vakit, Allah’ın size emrettiği yerden onlara varın. Şüphesiz ki Allah; hem çok tevbe edenleri sever, hem de çok temizlenenleri sever."},{"n":223,"t":"Kadınlarınız sizin için bir tarladır. O halde tarlanıza dilediğiniz gibi varın. Ve kendiniz için önceden iyi ameller gönderin. Bir de Allah’tan korkun. Ve bilin ki; siz, şüphesiz O’na kavuşacaksınız. İman edenleri müjdele."},{"n":224,"t":"Yeminlerinizde; Allah’ı iyilik etmenize, fenalıktan sakınmanıza ve insanların arasını bulmaya engel yapmayın. Allah Semi’dir, Alim’dir."},{"n":225,"t":"Yeminlerinizdeki lağvden dolayı Allah, sizi sorumlu tutmaz. Ancak kalblerinizin kazandığı şeyden dolayı sizi sorumlu tutar. Allah Gafur’dur, Halim’dir."},{"n":226,"t":"Kadınlarına yaklaşmamaya yemin edenler için dört ay beklemek vardır. Eğer yeminlerinden dönerlerse şüphesiz ki Allah Gafur’dur, Rahim’dir."},{"n":227,"t":"Şayet boşanmaya karar verirlerse, muhakkak Allah Semi’dir, Alim’dir."},{"n":228,"t":"Boşanmış kadınlar; kendi kendilerine, üç adt ve temizlenme müddeti beklerler. Eğer onlar, Allah’a ve ahiret gününe inanıyorlarsa, Allah’ın kendi rahimlerinde yarattığını gizlemeleri onlara helal olmaz. Eğer barışmak isterlerse; kocaları onları geri almaya daha layıktırlar. Erkeklerin kadınların üzerinde hakları olduğu, gibi, kadınların da onlar üzerinde hakları vardır. Erkekler onların üzerinde bir dereceye sahiptirler. Allah Aziz’dir, Hakim’dir."},{"n":229,"t":"Boşanma iki defadır. Ya iyilikle tutmak, ya da güzellikle salmaktır. Onlara verdiğinizden birşeyi geri almanız sizlere helal değildir. Meğer erkekle kadın Allah’ın hududunu ikame edemeyeceklerinden korkmuş olalar. Eğer siz de, onların Allah’ın hududunu ikame edemeyeceklerinden korkarsanız, o halde fidye vermelerinde bir vebal yoktur. Bunlar Allah’ın hudududur. Onları aşmyın. Kim Allah’ın hududunu aşarsa, işte onlar zalimlerin kendileridir."},{"n":230,"t":"Şayet erkek eşini bir daha boşarsa; artık ondan sonra kadın, başka bir kocaya nikahlanıp varıncaya kadar ona helal olmaz. Şayet bu koca da onu boşar ve onlar Allah’ın hududunu ikame edeceklerini zannederlerse; tekrar birbirlerine dönmelerinde her ikisi için de bir günah yoktur. Bunlar Allah’ın hudududur. Bunları, bilen bir kavim için açıklıyor."},{"n":231,"t":"Ve kadınları boşadığınız zaman; iddetlerini bitirince artık onları ya iyilikle tutun veya iyilikle salıverin. Sırf zulmedebilmeniz için zararlarına onları tutuvermeyin. Kim, böyle yaparsa; muhakkak kendi nefsine zulmetmiş olur. Allah’ın ayetlerini oyuncak yerine koymayın. Allah’ın üzerinizdeki nimetini ve size öğüt vermek için indirdiği kitabı ve hikmeti hatırlayın. Allah’tan korkun. Ve bilin ki Allah, şüphesiz her şeyi bilendir."},{"n":232,"t":"Kadınları boşadığınız vakit, onlar iddetlerini bitirdiklerinde, aralarında güzelce anlaştıkları takdirde; kocalarıyla tekrar evlenmelerine mani olmayın. İşte sizden Allah’a ve ahiret gününe inanmış olanlara, bununla öğüt veriliyor. Bu, sizin için daha iyi, daha temizdir. Allah bilir, siz bilmezsiniz."},{"n":233,"t":"Anneler çocuklarını tam iki yıl emzirirler. Bu, emzirmeyi tamamlamak isteyen içindir. Onların yiyeceği, giyeceği uygun şekilde çocuk kendisinden olana aittir. Kimse gücünün üstünde bir şeyle mükellef olmaz. Ne anne çocuğu yüzünden, ne de baba çocuğu yüzünden zarara sokulmasın. Mirasçıya düşen de bunun gibidir. Eğer kendi aralarında anlaşıp, danışarak çocuğu memeden kesmek isterlerse; ikisine de bri vebal yoktur. Çocuklarınızı emzirtmek isterseniz, vereceğinizi güzelce teslim etmek şartıyla size yine bir vebal yoktur. Allah’tan korkun ve bilin ki Allah yaptığınız şeyleri görendir."},{"n":234,"t":"İçinizden ölenlerin geriye bıraktıkları eşler; kendi kendilerine dört ay ve on gün beklerler. Müddetlerini bitirdikleri vakit onların, kendileri için uygun olanı yapmalarından dolayı size bir günah yoktur. Ve Allah, işlediklerinizden haberdardır."},{"n":235,"t":"Böyle kadınları nikahlamak isteğinizi bildirmenizden veya bir arzuyu gönüllerinizde saklamanızdan dolayı size bir vebal yoktur. Allah bilmiştir k; siz, onları mutlaka hatırlayacaksınız, fakat uygun bir sözle söylememeniz müstesna, onlarla gizlice sözleşmeyin. İddeti nihayet bulmadıkça nikah bağını bağlamaya kalkmayın. Ve bilin ki; şüphesiz Allah, gönüllerinizde olanı bilir. Artık O’ndan sakının. Ve yine bilin ki; şüphesiz Allah, Gafur’dur, Rahim’dir."},{"n":236,"t":"Temas etmediğiniz veya bir mehir kesmediğniz kadınları boşamışsanız, size vebal yoktur. Şu kadar ki, zengin olan kudretince, darda bulunan da halince ma’ruf bir fayda ile onları faydalandırmalıdır. Bu, iyilik edenlerin üzerine bir borçtur."},{"n":237,"t":"Bir mehir kestiğniz takdirde temas etmeden önce onları boşarsanız; kestiğiniz mehrin yarısı onlarındır. Meğer, kendilerini bağışlamış veya nikah düğümü elinde bulunan kimse bağışlamış ola. Bağışlamanız, takvaya daha yakındır. Aranızdaki fazileti unutmayın. Şüphesiz Allah, yaptığınız şeyleri görendir."},{"n":238,"t":"Namazlara ve orta namaza devam edin. Ve Allah’ın divanına huşu ile durun."},{"n":239,"t":"Eğer korkarsanız yaya veya binmiş olarak kılın. Emin olduğunuz vakitte de Allah’ın size bilmediğiniz şeyleri öğrettiği şekilde Allah’ı zikredin."},{"n":240,"t":"İçinizden vefat edip de eşlerini geride bırakanlar; bir seneye kadar eşlerinin evlerinden çıkarılmayarak geçimlerinin sağlanmasını vasiyyet etmiş olmalıdırlar. Şayet kendileri çıkarlarsa; artık onların ma’ruf şekilde yapacaklarından dolayı size mes’uliyet yoktur. Allah, Aziz’dir, Hakim’dir."},{"n":241,"t":"Boşanan kadınlar için uygun şekilde geçimlerini sağlamak vardır. Bu, müttakiler için bir vazifedir."},{"n":242,"t":"İşte Allah, aklınız ersin diye ayetlerini bu şekilde beyan ediyor."},{"n":243,"t":"Binlerce oldukları halde ölüm korkusuyla yurtlarından çıkanları görmedin mi? Allh onlara; (ölün) dedi. Sonra da onları diriltti. Şüphesiz ki, Allah insanlara karşı lutuf sahibidir. Ama insanların pek çoğu şükretmezler."},{"n":244,"t":"Allah yolunda savaşın ve bilin ki Allah Semi’dir, Alim’dir."},{"n":245,"t":"Kimdir o ki; Allah’a güzel bir borç versin de Allah onu kat kat fazlasıyla ödesin. Allah, hem darlaştırır, hem de bollaştırır. Ve O’na döndürüleceksiniz."},{"n":246,"t":"Musa’dan sonra İsrailoğullarından bir cemaate bakmadın mı? Hani, onlar peygamberlerine bize bir hükümdar gönder ki, Allah yolunda savaşalım, dediler. Peygamberleri de: Üzerinize savaş farz edilir de ya savaşmazsanız? dedi. Onlar dediler ki: Biz Allah yolunda neden savaşmayalım? Hem yurtlarımızdan çıkarıldık, hem de oğullarımızdan (ayrıldık). Fakat onların üzerine savaş farz edildiği vakit, içlerinden pek azı müstesna hep geri döndüler. Allah, zalimleri çok iyi bilendir."},{"n":247,"t":"Peygamberleri onlara dedi ki: İşte Allah hükümdar olarak size Talut’u gönderdi. Onlar: Biz hükümdarlığa ondan daha layık iken ve ona malca bolluk da verilmemişken nasıl olur da bizim başımıza hükümdar olabilir? dediler. Peygamberleri de dedi ki: Allah onu sizin üstünüzde beğenip seçmiştir. O’na bilgice ve vücutça da bir üstünlük vermiştir. Şüphesiz ki Allah; mülkünü dilediğine verir. Ve Allah, Vasi’dir, Alim’dir."},{"n":248,"t":"Peygamberi onlara dedi ki: Gerçekten onun hükümdarlığının alameti size Tabut’un gelmesidir ki, onda Rabbınızdan bir «Sekine» ve Musa hanedanıyla Harun hanedanının terkettiklerinden bir kalıntı vardır. Melekler onu yüklenecektir. Şayet inananlardan iseniz; elbette bunda, sizin için kesin bir ayet vardır."},{"n":249,"t":"Talut orduyla birlikte ayrılıp çıktığı vakit dedi ki: Allah, sizi bir ırmakla deneyecektir. Kim ondan içerse benden değildir. Kim de ondan tatmazsa şüphesiz ki bendendir. Eliyle bir avuç alanlar başka. Derken onlardan birazı müstesna olmak üzere hepsi de ondan içiverdiler. Talut ve beraberindeki mü’minler ırmağı geçtikleri vakit; bizim bugün Calut ve ordusuna karşı gücümüz yoktur, dediler. Mutlaka Allah’a kavuşacaklarını bilenlerse dediler ki: Nice az topluluk, Allah’ın izniyle pek çok topluluğu yenmiştir. Allah sabredenlerle beraberdir."},{"n":250,"t":"Calut ve askerlerine karşı çıktıkları zaman, dediler ki: Ey Rabbımız, üzerimize sabır yağdır, ayaklarımıza sebat ver ve bizi kafirler güruhuna karşı muzaffer kıl."},{"n":251,"t":"Allah’ın izniyle onları hemen hezimete uğrattılar. Davud da Calut’u öldürdü. Allah ona mülk ve hikmet verdi. Dilemekte olduğunu da ona öğretti. Şayet Allah’ın insanları birbiriyle def’edip savması olmasaydı yeryüzü muhakkak fesada uğrardı. Ancak Allah, alemler üzerinde lutuf sahibidir."},{"n":252,"t":"İşte bunlar Allah’ın ayetleridir. Onları sana hak olarak okuyoruz. Şüphesiz ki sen elçilerdensin."},{"n":253,"t":"Şu peygamberler onlardan kimini kiminden üstün kıldık. Allah, onlardan kimiyle söyleşmiş, kimini de derecelerle yükseltmiştir. Meryem oğlu İsa’ya da açık deliller verdik. Ve onu Ruh’ul-Kudüs ile destekledik. Eğer Allah dilesydi; onların arkasındakiler; kendilerine apaçık deliller geldikten sonra birbirlerini öldürmezlerdi. Fakat ihtilafa düştüler, sonra onlardan kimi inandı, kimi de inkar etti. Allah dileseydi; birbirlerini öldürmezlerdi. Ancak Allah, istediğini yapar."},{"n":254,"t":"Ey iman edenler, alış verişin, dostluğun ve şefaatin olmadığı gün gelmezden evvel, size verdiğim rızıklardan infak edin. Kafirler işte zalimlerin kendileridir."},{"n":255,"t":"Allah O’ndan başka hiçbir ilah yoktur. Hayy ve Kayyum’dur. O’nu dalgınlık ve uyku tutmaz. Göklerde ve yerde olanların hepsi de O’nundur. O’nun izni olmadan katında şefaat edecek kimdir? Önlerinde ve arkalarında ne varsa bilir. Dilediği kadarından başka O’nun ilminden hiçbir şey kavrayamazlar. Kürsi’si gökleri ve yeri kaplamıştır. Onları koruyup gözetmek O’na ağırlık vermez. O, öyle ulu, öyle yücedir."},{"n":256,"t":"Dinde zorlama yoktur. Gerçekten hak, batıldan iyice ayrılmıştır. Tağut’u inkar edip, Allah’a inanan kimse kopmak bilmeyen sağlam bir kulpa sarılmıştır. Ve Allah, Semi’dir, Alim’dir."},{"n":257,"t":"Allah, inananların dostudur. Onları karanlıktan aydınlığa çıkarır. Küfredenlerin dostları ise Tağut’tur. Onları aydınlıktan karanlıklara çıkarırlar. İşte onlar ateş yaranıdır. Onlar orada temelli kalacaklardır."},{"n":258,"t":"Allah kendisine mülk verdiği için, Rabbı hakkında İbrahim ile tartışanı görmedin mi? Hani Rabbım öldüren ve diriltendir, deyince, o; ben de diriltir ve öldürürüm, demişti. İbrahim: Allah güneşi doğudan getirir. Haydi sen de onu batıdan getir, deyince o küfreden herif, apışıp kaldı. Allah, zalimler güruhunu hidayete erdirmez."},{"n":259,"t":"Yahut altı üstüne gelmiş bir kasabaya uğrayan kimse gibisini görmedin mi? Allah, bunu ölümünden sonra nasıl diriltecek? dedi. Bunun üzerine Allah, onu yüz sene ölü bıraktı, sonra diriltti. Na kadar kaldın? dedi. O da: Bir gün veya bir günden daha az kaldım, dedi. Hayır, yüz yıl kaldın. Öyle iken yiyeceğine içeçeğine bak; henüz bozulmamış, bir de merkebine bak. Hem seni insanlara bir ibret kılacağız. Kemiklere bak, onları nasıl birleştirip yerli yerine koyuyor ve sonra onlara nasıl et giydiriyoruz? dedi. Bu hal ona apaçık belli olunca: Artık Allah’ın herşeye Kadir olduğunu biliyorum, dedi."},{"n":260,"t":"Hani İbrahim: Rabbım, ölüleri nasıl dirilttiğini bana göster, deyince. İnanmıyor musun? demişti. O da: Hayır öyle değil, ama kalbim iyice mutmain olsun, demişti. Öyleyse dört çeşit kuş al; onları kendine alıştır, sonra her dağ başına onlardan birer parça koy. Sonra onları, çağır, koşarak sana gelirler. Ve bil ki şüphesiz Allah, Aziz’dir, Hakim’dir."},{"n":261,"t":"Mallarını Allah yolunda infak edenlerin durumu, her başağında yüz tane olmak üzere yedi başak veren tanenin durumu gibidir. Allah, dilediğine kat kat verir. Ve Allah, Vasi’dir, Alim’dir."},{"n":262,"t":"Mallarını Allah yolunda infak edip de, sonra infak ettikleri şeyin ardından başa kakmayan ve eziyet etmeyenlerin mükafaatı, Rabbları katındadır. Onlara korku yoktur. Ve mahzun da olacak değillerdir."},{"n":263,"t":"Bir tatlı dil, bir af, peşinden eziyet gelecek sadakadan daha hayırlıdır. Ve Allah Gani’dir, Halim’dir."},{"n":264,"t":"Ey iman edenler; Allah’a ve ahiret gününe inanmayıp, insanlara gösteriş için malını harcayan kimse gibi sadakalarınızı başa kakma ve eziyet etmekle heder etmeyin, O gösteriş yapanın hali; üzerinde toprak bulunan kayanınki gibidir. Şiddetli bir yağmur isabet ettiğnde onu katı bir taş halinde bırakır. Onlar kazandıklarından hiç bir şey elde edemezler. Allah kafirler güruhunu hidayete erdirmez."},{"n":265,"t":"Allah’ın rızasını kazanmak ve kalblerindekini sağlamlaştırmak için mallarını infak edenlerin hali, bir tepedeki güzel bir bahçenin haline benzer. Kuvvetli bir sağanak düşünce; yemişlerini iki kat verir. Bol yağmur yağmasa bile bir çisenti bulunur ve Allah işlediklerinizi görür."},{"n":266,"t":"Biriniz ister mi ki; hurmalardan ve üzümlerden bir bahçesi olsun, altından ırmaklar aksın, içinde her çeşit meyve bulunsun da; kendisi ihtiyarlamış, çocukları da güçsüz kalmışken; bahçesi ateşli bir kasırga ile yanıversin. Düşünesiniz diye Allah, size ayetlerini böyle açıklar."},{"n":267,"t":"Ey iman edenler; kazandıklarınızın iyilerden ve size yerden çıkardıklarımızdan infak edin. Kendiniz göz yummadan alıcısı olmadığınız bayağı şeyleri vermeye yeltenmeyin. Ve bilin ki; Allah, Gani’dir, Hamid’dir."},{"n":268,"t":"Şeytan sizi fakirlik ile korkutarak, çirkin şeyleri emreder. Allah ise size mağfiret ve bolluk vaadeder. Allah, Vasi’dir, Alim’dir."},{"n":269,"t":"Hikmeti dilediğine verir. Kime de hikmet verilmişse şüphesiz ki, ona pek çok hayır verilmiştir. Bunu ancak akıl sahibleri anlar."},{"n":270,"t":"Nafakadan ne harcadınız ise veya adaktan ne adadınızsa; şüphesiz ki Allah onları bilir. Zulmedenlerin hiç yardımcıları yoktur."},{"n":271,"t":"Sadakaları açıktan verirseniz ne güzel. Eğer onları gizler de fakirlere öyle verirseniz bu, sizin için daha hayırlıdır. Ve onunla günahlarınızdan bir kısmını yarlığar. Allah, her ne yaparsanız haberdardır."},{"n":272,"t":"Onları hidayete erdirmek sana düşmez. ALlah, dilediğini hidayete erdirir. Hayır namına ne infak ederseniz kendinizedir. Zaten yalnız Allah rızasını kazanmak için infak edersiniz. Verdiğiniz her hayır tam olarak size ödenir. Ve siz, haksızlığa uğratılmazsınız."},{"n":273,"t":"Sadakalarınızı, kendilerini Allah yoluna vermiş olup da yeryüzünde dolaşmayan ve tanımayanların; hayalarından dolayı onları zengin zannettikleri yoksullara verin. Onları yüzlerinden tanırsın. Yüzsüzlük ederek insanlardan bir şey istemezler. Hayırdan ne infak ederseniz şüphesiz Allah onu bilir."},{"n":274,"t":"Onlar ki; mallarını gece ve gündüz, gizli ve açık infak ederler. İşte onların mükaafatı Rabbları katındadır. Onlar için korku da yoktur, üzülecek de değillerdir."},{"n":275,"t":"Faiz yiyenler ancak, şeytan çarpan kimsenin kalktığı gibi kalkarlar. Bu, onların: Zaten alış-veriş faiz gibidir, demelerinden dolayıdır. Halbuki Allah, alış-verişi helal, faizi haram kılmıştır. Kime Rabbından bir öğüt gelir de faizcilikten vazgeçerse, geçmiş olanlar kendisine ve hakkındaki hüküm Allah’a aittir. Kim de dönerse, onlar cehennem yaranıdırlar, orada temelli kalacaklardır."},{"n":276,"t":"Allah faizi mahveder, sadakaları artırır. Ve Allah hiçbir günahkar kafiri sevmez."},{"n":277,"t":"İman edip salih amel işleyenlerin, namaz kılıp zekat verenlerin Rabbları katında mükafaatları vardır. Onlar için korku yoktur ve üzülecek de değillerdir."},{"n":278,"t":"Ey iman edenler; Allah’tan korkun. Eğer mü’minlerden iseniz, faizden kalanı bırakın."},{"n":279,"t":"Böyle yapmazsanız, bunun Allah’a ve peygambere karşı bir harb olduğunu bilin. Şayet tevbe ederseniz, sermayeniz sizindir. Hem haksızlık yapmamış, hem de haksızlığa uğratılmamış olursunuz."},{"n":280,"t":"Borçlu darda ise, kolaylığa kadar beklemelidir. Eğer bilirseniz, sadaka olarak bağışlamanız sizin için daha hayırlıdır."},{"n":281,"t":"Hem öyle bir günden sakının ki; o gün, Allah’a döndürüleceksiniz. Sonra herkese kazandığı tamamıyle ödenecek. Onlara haksızlık edilmeyecektir."},{"n":282,"t":"Ey iman edenler; muayyen bir vaad ile borçlandığınız zaman, onu yazın. Aranızda bir katib de doğrulukla yazsın. Yazan; Allah’ın kendisine öğrettiği gibi yazmaktan çekinmesin, yazsın. Hak kendi üzerinde olan da yazdırsın. Rabbı olan Allah’tan korksun da ondan bir şey eksiltmesin. Şayet borçlu sefih, küçük veya kendisi söyleyip yazdıramayacak durumda ise; velisi dosdoğru yazdırsın. Erkeklerinizden iki de şahid yapın. Eğer ki erkek bulamazsa şahidlerden razı olacağınız bir erkek, biri unuttuğunda diğeri ona hatırlatacak iki kadın olabilir. Şahidler çağrıldıklarında çekinmesinler. Borç, büyük veya küçük olsun onu müddeti ile beraber yazmaktan üşenmesin. Bu, Allah yanında adalete daha uygun, şahidlik için daha sağlam, şüpheye düşmemenize de daha yakındır. Ancak aranızda peşin alış-veriş olursa onu yazmamanızda size bir günah yoktur. Alış-veriş yaptığınızda şahid tutun. Yazana da şehadet edene de zarar verilmesin. Şayet zarar verecek olursasanız; o zaman, kendinize dokunacak bir kötülük olur. Allah’tan korkun. Allah size öğretiyor. Allah her şeyi bilir."},{"n":283,"t":"Eğer seferde olur da yazacak kimse bulamazsanız; alınan rehinler yeter. Şayet birbirinize güvenirseniz güvenilen kimse Rabbı olan Allah’tan korksun da borcunu ödesin. Bir de şehadeti gizlemeyin. Onu gizleyenin kalbi günahkardır. Allah yaptıklarınızı bilir."},{"n":284,"t":"Göklerde ve yerde olanların hepsi Allah’ındır. İçinizdekini açıklasanız da, gizleseniz de Allah sizi onunla hesaba çeker. Sonra dilediğini bağışlar dilediğini azablandırır. Ve Allah, herşeye Kadir’dir."},{"n":285,"t":"Peygamber de, iman edenler de O’na indirilene inandı. Hepsi de Allah’a, meleklerine, kitablarına, peygamberlerine iman etti. O’nun peygamberlerinden hiçbirinin arasını tefrik etmeyiz. İşittik ve itaat ettik. Affını dileriz, ey Rabbımız. Dönüş Sana’dır, dediler."},{"n":286,"t":"Allah, kimseye gücünün yeteceğinden fazlasını yüklemez. Kazandığı lehine, yüklendiği aleyhinedir. Ey Rabbımız, unuttuk veya yanıldıysak sorumlu tutma bizi. Ey Rabbımız, bizden öncekilere yüklediğin gibi bize de ağır yük yükleme. Ey Rabbımız, bize gücümüzün yetmeyeceğini yükleme. Affet bizi, bağışla bizi. Sen Mevlamızsın. Kafirler güruhuna karşı yardım et bize."}],[{"n":1,"t":"Elif, Lam, Mim."},{"n":2,"t":"Allah, O’ndan başka hiç bir İlah yoktur. Hayy ve Kayyum’dur."},{"n":3,"t":"Sana kitabı hak ile ve kendisinden öncekileri doğrulayıcı olarak indirdi. Ve Tevart’ı ve İncil’i indirdi."},{"n":4,"t":"Daha önce. İnsanlara yol gösterici olarak. Furkan’ı da indirdi. Muhakkak ki Allah’ın ayetlerini inkar edenler için, gerçekten şiddetli azab vardır. Allah, Aziz’dir, intikam sahibidir."},{"n":5,"t":"Şüphesiz ki; gökte ve yerde hiç bir şey Allah’a gizli kalmaz."},{"n":6,"t":"Sizi rahimlerde dilediği gibi şekillendiren O’dur. O’ndan başka hiç bir ilah yoktur. O, Aziz’dir, Hakim’dir."},{"n":7,"t":"Sana kitabı indiren O’dur. O’nun bazı ayetleri muhkemdir ki bunlar; kitabın anasıdır. Diğer bir kısmı da müteşabihlerdir. İşte kalblerinde eğrilik bulunanlar; fitne çıkarmak ve te’vile yeltenmek için müteşabih olanlara uyarlar. Halbuki onun gerçek te’vilini, ancak Allah bilir. İlimde derinleşmiş olanlar: Biz ona inandık, hepsi Rabbımızın katındadır, derler. Ancak akıl sahibleri düşünebilirler."},{"n":8,"t":"Ey Rabbımız; bizi, hidayetine erdirdikten sonra kalblerimizi eğriltme. Katında bize rehmet lutfet. Şüphesiz en çok lütfeden Sen’sin Sen."},{"n":9,"t":"Ey Rabbımız; muhakkak ki geleceğinden şüphe olmayan bir günde insanları toplayacak Sen’sin. Şüphesiz ki Allah vaadinden dönmez."},{"n":10,"t":"Doğrusu küfredenlerin; malları ve çocukları Allah’a karşı onlara bir şey sağlamaz. Ve onlar ateşin yakıtıdırlar."},{"n":11,"t":"Tıpkı Firavun hanedanının ve onlardan öncekilerin yaptığı gibi. Onlar ayetlerimizi yalanladılar da Allah günahlarından dolayı onları yakalayıverdi. Allah azabı çok şiddetli olandır."},{"n":12,"t":"Küfredenlere: Siz, mutlaka yenileceksiniz. Ve toplanıp cehenneme sürüleceksiniz, orası ne kötü döşektir, de."},{"n":13,"t":"Karşılaşan iki topluluğun durumlarında sizin için ibret vardır. Biri, Allah yolunda döğüşüyordu. Diğeri ise, kafirdi. Onlar, öbürlerinin kendilerinin iki katı olduklarını gözleriyle görüyorlardı. Allah, dilediğini yardımıyla destekler. Görebilenler için bunda ibret vardır."},{"n":14,"t":"Kadınlarından oğullarından, kantar kantar altın ve gümüşten, nişanlı atlardan, develerden ve ekinlerden gelen zevklere aşırı düşkünlük; insanlar için süslenip hoş göründü. Bunlar dünya hayatının geçimidir. Oysa gidilecek yerin güzel olanı Allah katındadır."},{"n":15,"t":"De ki: Size bunlardan daha hayırlısını haber vereyim mi? Takvaya erenler için, altından ırmaklar akan cennetler vardır. Orada devamlı kalacaklardır. Tertemiz eşler ve Allah’ın rızası vardır. Ve Allah kullarını hakkıyla görendir."},{"n":16,"t":"Onlar ki: Ey Rabbımız; biz gerçekten iman ettik, artık günahlarımızı bize bağışla ve o ateş azabından bizleri koru diyenler,"},{"n":17,"t":"Sabredenler, doğru olanlar, gönülden ibadet edenler, infak edenler ve seherlerde Allah’tan mağfiret dileyenlerdir."},{"n":18,"t":"Allah, şehadet etti ki: Gerçekten O’ndan başka ilah yoktur. Melekler ve ilim sahibleri de adaleti ayakta tutarak buna şehadet ettiler; O’ndan başka ilah yoktur. O, Aziz’dir, Hakim’dir."},{"n":19,"t":"Gerçekte Allah katında din, İslam’dır. Ancak kitab verilenler, kendilerine ilim geldikten sonra aralarındaki ihtirastan dolayı ayrılığa düştüler. Kim, Allah’ın ayetlerini inkar ederse; şüphesiz ki Allah, hesabı çabuk görendir."},{"n":20,"t":"Seninle tartışmaya girişirlerse: Ben, bana uyanlarla birlikte kendimi Allah’a teslim ettim, de. Kendilerine kitab verilenler ve ümmilere: Siz de İslam oldunuz mu? de. Eğer İslam olurlarsa; doğru yola girmişlerdir. Şayet yüz çevirirlerse; sana, yalnız tebliğ etmek düşer. Ve Allah, kullarını görendir."},{"n":21,"t":"Allah’ın ayetlerini inkar edenlere ve haksız yere peygamberleri öldürenlere, insanlardan adaleti emredenleri öldürenlere, işte onlara; elem verici bir azabı müjdele."},{"n":22,"t":"İşte bunlar, o kimselerdir ki; dünya ve ahirette amelleri boşa gitmiştir. Ve onların hiç yardımcıları yoktur."},{"n":23,"t":"Kendilerine Kitab’tan bir pay verilmiş olanları görmedin mi ki; aralarında hüküm vermen için Allah’ın kitabına çağırılıyorlar da, sonra onlardan bir zümre arkasını çeviriyor. Onlar, temelli yüz çevirenlerdendir."},{"n":24,"t":"Bu, onların: Sayılı günlerden başka bize, asla ateş dokunmayacak, demeleri yüzündendir. Ve uydurageldikleri şeyler, dinlerinde kendilerini aldatmıştır."},{"n":25,"t":"Ya geleceğinden şüphe olmayan bri günde onları topladığımız ve kendilerine zulmedilmeden herkesin kazandığının tastamam ödendiği zaman halleri ne olacak?"},{"n":26,"t":"De ki: Ey mülkün sahibi olan Allah’ım; Sen mülkü dilediğine verirsin. Sen, mülkü dilediğinin elinden alırsın. Sen, dilediğini aziz edersin. Sen, dilediğini zelil edersin. Hayır, yalnız Senin elindedir. Sen hiç şüphe yok ki her şeye Kadirsin."},{"n":27,"t":"Geceyi gündüze geçirir, gündüz geceye geçirirsin. Ölüden diriyi çıkarır, diriden ölüyü çıkarırsın. Dilediğin kimseye hesabsız rızık verirsin."},{"n":28,"t":"Mü’minler, Mü’minleri bırakıp da kafirleri dost edinmesinler. Kim böyle yaparsa; Allah ile dostluğu kalmaz. Ancak onlardan sakınmanız müstesnadır. Allah, size kendisinden korkmanızı emrediyor. Dönüş Allah’adır."},{"n":29,"t":"De ki: İçinizde olanı gizleseniz de, açıklasanız da Allah bilir. Göklerde ve yerde ne varsa hepsini O, bilir. Allah, herşeye Kadir’dir."},{"n":30,"t":"O gün ki; herkes ne hayır işledi ise karşısında onu hazırlanmış bulacak. Kötülükten de ne yapmışsa; kendisiyle onun arasında uzun bir mesafe olmasını ister. Allah bizzat korkutuyor. Ve Allah kullarına Rauf’dur."},{"n":31,"t":"De ki: Allah’ı seviyorsanız bana uyun ki, Allah sizi sevsin ve günahlarınızı bağışlasın. Allah Gafur’dur, Rahim’dir."},{"n":32,"t":"Allah’a ve peygamberlere itaat edin, de. Şayet yüz çevirirlerse şüphesiz ki Allah, kafirleri sevmez."},{"n":33,"t":"Şüphe yok ki Allah, Ademi, Nuh’u, İbrahim soyunu ve İmran soyunu seçti. Alemlere üstün kıldı."},{"n":34,"t":"Onlar, birbirlerinden türemiş bir soydur. Allah, Semi’dir, Alim’dir."},{"n":35,"t":"Hani, İmran’ın karısı: Rabbım karnımdakini hür olarak Sana adadım, benden kabul buyur. Doğrusu Sensin Sen, Semi, Alim, demişti."},{"n":36,"t":"Fakat onu doğurunca-Allah onu ve doğurduğunu daha iyi bilici iken-Rabbım ben onu kız olarak doğurdum. Erkek, kız gibi değildir. Gerçekten ben adını Meryem koydum. Ben onu da soyunu da kovulmuş şeytandan sana sığındırırım, demişti."},{"n":37,"t":"Bunun üzerine Rabbı onu güzel bir kabul ile karşıladı. Onu güzel bir bitki gibi yetiştirdi. Zekeriyya’nın himayesine verdi. Zekeriyya mihraba her girişinde onun yanında bir yiyecek bulurdu. Ey Meryem, bu sana nereden? derdi. O da: Allah tarafından, derdi. Şüphe yok ki Allah, dilediğini hesapsız rızıklandırır."},{"n":38,"t":"Orada Zekeriyya Rabbına dua etti: Rabbım; bana katından temiz bir şey bahşet. Muhakkak Sen duayı işitensin."},{"n":39,"t":"O, mihrabda namaz kılarken melekler ona seslendiler: Allah sana, kendisinden bir kelimeyi tasdik edici bir efendi, nefsine hakim ve salihlerden bir peygamber olmak üzere Yahya’yı müjdeler."},{"n":40,"t":"Ve dedi ki: Rabbım; ben artık iyice kocamış, karım da kısırken nasıl oğlum olabilir? Öyle, Allah dilediğini yapar, dedi."},{"n":41,"t":"Rabbım, bana bir alamet ver, dedi. Alametin, işaretten başka şekillerle insanlarla konuşmamandır. Bununla beraber Rabbını çok an ve akşam sabah tesbih et."},{"n":42,"t":"Hani melekler: Ey Meryem, şüphesiz Allah seni seçip temizledi. Dünyaların kadınlarından seni üstün tuttu, demişlerdi."},{"n":43,"t":"Ey Meryem, huşu ile Rabbının divanına dur. Secdeye kapan. Rüku edenlerle birlikte rüku et."},{"n":44,"t":"Bunlar sana vahyetmekte olduğumuz gayb haberlerindendir. Meryem’e hangisi kefil olacak diye kalemlerini atarlarken sen yanlarında değildin. Çekişirlerken de orada bulunmadın."},{"n":45,"t":"Melekler demişlerdi ki: Ey Meryem; Allah kendinden bir kelimeyi sana müjdeliyor. Adı; Meryem oğlu İsa, Mesih’tir. Dünyada da, ahirette de, şanı yücedir. Allah’a yakın kılınanlardandır."},{"n":46,"t":"Beşiğinde de, yetişkinlik halinde de insanlarla konuşacaktır ve salihlerdendir."},{"n":47,"t":"Meryem dedi ki: Rabbım; bana bir beşer dokunmamışken, benim nasıl çocuğum olabilir? Melekler de: Allah, dilediğini öylece yaratır ve bir şeyin olmasını dilerse, ona; ol, der de oluverir, dediler."},{"n":48,"t":"O’na kitabı, hikmeti, Tevrat’ı ve İncil’i öğretecek."},{"n":49,"t":"O’nu İsrailoğullarına peygamber olarak gönderecek ve onlara şöyle diyecektir: Ben, size Rabbınızdan bir ayet getirdim. Ben, size çamurdan kuş gibi bir şey yapıp ona üfleyeceğim de Allah’ın izniyle, hemen kuş olacak. Anadan doğma körleri ve alacalıları iyi edeceğim. Allah’ın izniyle ölüleri dirilteceğim. Yediklerinizi ve evlerinizde sakladıklarınızı da size haber vereceğim. Eğer iman edenlerden iseniz; elbette bunda sizin için ayet vardır."},{"n":50,"t":"Benden önce gelen Tevrat’ı tasdik etmek ve size haram kılınanların bir kısmını helal kılmak üzere Rabbınızdan size bir ayet getirdim. Artık Allah’tan korkun ve bana itaat edin."},{"n":51,"t":"Şüphe yok ki Allah; benim de Rabbım, sizin de Rabbınızdır. Öyleyse O’na kulluk edin, dosdoğru yol işte budur."},{"n":52,"t":"İsa, onların inkarlarını sezince; Allah uğrunda yardımcılarım kimlerdir? dedi. Havariler: Biziz Allah’ın yardımcıları, Allah’a iman ettik. Sen de şahid ol ki biz, muhakkak müslümanlarız, dediler."},{"n":53,"t":"Ey Rabbımız; indirdiğine iman ettik. Ve peygamberlerin ardınca gittik. Bizi şahid olanlarla beraber yaz."},{"n":54,"t":"Hile yaptılar, Allah da onları cezalandırdı. Ve Allah, hile yapanların cezasını en iyi verendir."},{"n":55,"t":"Hani Allah demişti ki: Ey İsa; seni öldürecek olan Benim. Seni kendime yükseltip kaldıracak, sen, kafirlerin içinden tertemiz çıkaracak ve sana tabi olanları, kıyamet gününe kadar küfredenlerden üstün tutacak da Benim Sonra dönüşünüz yalnız Banadır. Ayrılığa düştüğünüz konularda aranızda Ben hükmedeceğim."},{"n":56,"t":"Küfredenleri de dünya ve ahirette şiddetli azaba uğratacağım. Onların hiçbir yardımcıları yoktur."},{"n":57,"t":"İman edip salih amel işleyenlere gelince; onların mükafaatları ödenecektir. Ve Allah, zalimleri sevmez."},{"n":58,"t":"İşte bunları; sana, ayetlerden bir hikmet dolu Kur’an’ dan okuyoruz."},{"n":59,"t":"Gerçekten Allah katında İsa’nın durumu, Adem’in durumu gibidir. Allah o’nu topraktan yarattı. Sonra o’na; ol dedi, o da oluverdi."},{"n":60,"t":"Hak, Rabbındandır. Öyleyse şüphecilerden olma."},{"n":61,"t":"Sana ilim geldikten sonra; kim seninle tartışırsa de ki: Gelin oğullarımızı ve oğullarınızı, kadınlarımızı ve kadınlarınızı, kendimizi ve kendinizi çağıralım. Sonra la’netleşelim. Allah’ın lanetinin yalancıların üstüne olmasını dileyelim."},{"n":62,"t":"Doğrusu işte budur, o kıssanın hak ifadesi: Allah’dan başka ilah yoktur. Şüphesiz ki Allah, Aziz’dir, Hakim’dir."},{"n":63,"t":"Şayet yüz çevirirlerse; şüphesiz ki Allah, bozguncuları bilir."},{"n":64,"t":"De ki: Ey Ehl-i Kitab; hepiniz, sizinle bizim aramızda eşit olan bir kelimeye gelin: Allah’dan başkasına kulluk etmeyelim. O’na hiçbir şeyi eş koşmayalım. Ve Allah’ı bırakıp da kimimiz, kimimizi Rab edinmesin. Eğer yüz çevirirlerse; o vakit şahid olun ki biz, müslümanız, deyin."},{"n":65,"t":"Ey Ehl-i Kitab; İbrahim hakkında niçin münakaşa ediyorsunuz? Tevrat da, İncil de şüphesiz ondan sonra indirilmiştir. Aklınız ermiyor mu?"},{"n":66,"t":"Siz, hadi bilginiz olan şey üzerine münakaşa eden kimselersiniz. Ya bilginiz olmayan şey üzerine niçin münakaşa ediyorsunuz? Halbuki Allah bilir, siz bilmezsiniz."},{"n":67,"t":"İbrahim; ne Yahudi, ne de Hristiyan idi. Fakat o, Allah’ı bir tanıyan, gerçek bir müslüman idi. Ve müşriklerden değildi."},{"n":68,"t":"Doğrusu İbrahim’e en yakın olanlar; o’na uyanlar, peygamber ve iman edenler. Ve o, müşriklerden de değildi. Ve Allah mü’minlerin velisidir."},{"n":69,"t":"Ehl-i Kitab’tan bir taife; sizi şaşırtmak istediler. Halbuki onlar; kendilerinden başkasını şaşırtmazlar da farkına varmazlar."},{"n":70,"t":"Ey Ehl-i Kitab; görüp dururken niçin Allah’ın ayetlerini inkar ediyorsunuz?"},{"n":71,"t":"Ey Ehl-i Kitab; Niçin hakkı batıla karıştırıyor ve bile bile hakkı gizliyorsunuz?"},{"n":72,"t":"Ehl-i Kitab’tan bir güruh şöyle dedi: Varın o mü’minlere indirilenlere güpegündüz iman edin. Sonunda da dönüp küfredin. Belki onlar da dönerler."},{"n":73,"t":"Kendi dininize uyanlardan başkasına inanmayın. De ki: Doğru yol, Allah’ın yoludur. Derler ki: Size verilen bir benzerinin de birine verildiğini veya Rabbınızın katında size delil gösterecekleri bir şeyi açıklamayın. De ki: Doğrusu lütuf Allah’ın elindedir, onu dilediğine verir. Allah Vasi’dir, Alim’dir."},{"n":74,"t":"Dilediğine rahmetini tahsis eder. Allah, en büyük lütuf sahibidir."},{"n":75,"t":"Ehl-i Kitab’dan öylesi vardır ki; kantarla emanet bıraksan; onu sana öder. Öylesi de vardır ki; bir tek altın emanet etsen; tepesine dikilmedikçe onu sana ödemez. Bu, onların: Ümmiler hakkında bize karşı sorumluluk yoktur, demelerindendir. Onlar, bile bile Allah’a karşı yalan söylemektedirler."},{"n":76,"t":"Hayır, kim ahdini yerine getirir ve sakınırsa; şüphe yok ki Allah, sakınanları sever."},{"n":77,"t":"Allah’ın ahdini ve kendi yeminlerini az bir paraya değişenlerin, ahirette hiç bir payı yoktur. Allah, kıyamet günü onlarla konuşmaz, onlara bakmaz, onları temize çıkarmaz. Ve onlar için elim bir azab vardır."},{"n":78,"t":"Onlardan bir güruh vardır ki; kitabda olmadığı halde kitabdan zannedesiniz diye, dillerini eğip, bükerler. Allah katında olmadığı halde; Allah katındandır, derler. Allah adına, bile bile yalan söylerler."},{"n":79,"t":"Hiç bir insana yakışmaz ki; Allah, kendisine kitabı, hükmü ve peygamberliği versinde sonra o, insanlara: Allah’ı bırakıp bana kullar olun, desin. Fakat: Kitabı okuyup öğrettiğinize göre Rabb’a kul olun, demek yaraşır."},{"n":80,"t":"Size melekleri ve peygamberleri Rabb olarak benimsemenizi de emretmez. Müslüman olduktan sonra size küfretmeyi mi emredecek?"},{"n":81,"t":"Hani Allah, Peygamberlerden söz almış: And olsun ki; size, kitabı, hikmeti verdim. Yanınızda olanı doğrulayıcı bir peygamber geldiğinde mutlaka o’na inanacak ve yardım edeceksiniz. İkrar edip de ahdi kabul ettiniz mi? demişti. Onlar da: İkrar ettik, demişlerdi. Allah: Şahid olsun, Ben de sizinle beraber şahidlerdenim, demişti."},{"n":82,"t":"Artık kim, bundan sonra dönerse işte onlar, fasıklardır."},{"n":83,"t":"Yoksa Allah’ın dininden başkasını mı arıyorlar? Oysa göklerde ve yerde kim varsa; ister istemez O’na teslim olmuştur. Ve O’na döndürüleceklerdir."},{"n":84,"t":"De ki: Allah’a iman ettik. Ve bize indirilene, İbrahim, İsmail, İshak, Ya’kub ve oğullarına indirilenlere, Musa’ya, İsa’ya ve peygamberlere; Rabbları tarafından verilenlere de iman ettik. Onların hiç birisi arasında fark gözetmeyiz. Ve biz, O’na teslim olanlarız."},{"n":85,"t":"Kim, İslam’dan başka bir din ararsa; ondan asla aknul olunmaz. Ve o, ahirette hüsrana uğrayanlardandır."},{"n":86,"t":"İman ettikten, peygamberlerin hak olduğunu gördükten ve kendilerine apaçık deliller geldikten sonra küfre sapan bir kavmi, Allah nasıl hidayete eriştirir? Ve Allah, zalimler güruhunu hidayete iletmez."},{"n":87,"t":"İşte bunların cezası: Allah’ın, meleklerin ve bütün insanların la’neti onların üzerinedir."},{"n":88,"t":"Ebediyyen onun içindedirler. Onlardan azab hafifletilmez ve onlara rahmet nazarıyla bakılmaz."},{"n":89,"t":"Ancak bunun ardından tevbe edip islah edenler müstesnadır. Doğrusu Allah, Gafur’dur, Rahim’dir."},{"n":90,"t":"İman ettikten sonra küfredip de, küfürleri artanların tevbeleri kabul edilmez. İşte onlar sapıkların kendileridir."},{"n":91,"t":"Doğrusu küfredip de, kafir olarak ölenler, yeryüzü dolusu altını fidye verecek olsalar yine de hiç birinden kabul edilmez. Onlar için elim bir azab vardır. Ve onların hiç yardımcıları da yoktur."},{"n":92,"t":"Sevdiğiniz şeylerden infak etmedikçe, asla bir’e erişemezsiniz. Ve her ne infak ederseniz; şüphesiz Allah, onu bilir."},{"n":93,"t":"Tevrat inmeden evvel İsrail’in, kendi nefsine haram kıldığından başka bütün yiyecekler İsrailoğullarına helal idi. Eğer sadıklardan iseniz; haydi Tevrat’ı getirip okuyun, de."},{"n":94,"t":"Bundan sonra artık kim Allah’a karşı yalan isnad ederse; işte onlar zalimlerin kendileridir."},{"n":95,"t":"De ki: Allah doğru buyurmuştur. O halde Hanif olarak İbrahim’in dinine uyun. O, müşriklerden değildi."},{"n":96,"t":"Muhakkak ki insanlar için konulmuş ilk ev; çok mübarek olarak kurulan ve alemler için hidayet olan Mekke’deki dir."},{"n":97,"t":"Orada apaçık alametlerle, İbrahim’in makamı vardır. Kim, oraya girerse emin olur. Ona yol bulabilen herkesin, Ka’be’yi haccetmesi insanlar üzerinde Allah’ın bir hakkıdır. Kim inkar ederse; bilsin ki doğrusu Allah, alemlerden müstağni’dir."},{"n":98,"t":"De ki: Ey Ehl-i Kitab; Allah yaptıklarınızı görüp dururken niçin Allah’ın ayetlerini inkar ediyorsunuz?"},{"n":99,"t":"De ki: Ey Ehl-i Kitab, siz gerçeği gördüğünüz halde Allah’ın yolunu eğri göstermeye yeltenerek, iman edenleri niçin ondan çeviriyorsunuz? Allah, yaptıklarınızdan gafil değildir."},{"n":100,"t":"Ey iman edenler; eğer kendilerine kitab verilenlerden herhangi bir zümreye uyarsanız, imanınızdan sonra sizi çevirirler de kafir yaparlar."},{"n":101,"t":"Allah’ın ayetleri size okunur, aranızda peygamberi bulunurken nasıl küfredersiniz? Kim, Allah’a sımsıkı sarılırsa; muhakkak doğru yola iletilmiştir."},{"n":102,"t":"Ey iman edenler; Allah’tan nasıl korkmak lazımsa öylece korkun. Ve her halde müslüman olarak can verin."},{"n":103,"t":"Topluca Allah’ın ipine sarılın, ayrılmayın. Ve Allah’ın üzerindeki nimetini hatırlayın. Hani, siz; düşman idiniz de O, kalblerinizin arasını uzlaştırdı da, O’nun nimeti sayesinde kardeş oldunuz. Siz; bir ateş uçurumunun tam kenarında iken, sizi oradan doğru yola eresiniz diye kurtardı. Alah ayetlerini size işte böylece açıklar."},{"n":104,"t":"İçinizden hayra çağıran, iyiliği emredip kötülükten alıkoyan bir topluluk bulunsun. İşte onlar, kurtuluşa erenlerdir."},{"n":105,"t":"Kendilerine apaçık deliller geldikten sonra, parçalanıp ihtilafa düşenler gibi olmayın. İşte onlara büyük bir azab vardır."},{"n":106,"t":"O gün; nice yüzler ağarır, nice yüzler kararır. O zaman yüzleri kara olanlara: İmanınızdan sonra küfür mü ettiniz? İşte o küfrünüzün cezası olarak tadın azabı, denir."},{"n":107,"t":"Ama yüzleri ağaranlar, Allah’ın rahmeti içindedirler. Onlar orada temelli kalacaklardır."},{"n":108,"t":"Bunlar; Allah’ın ayetleridir. Onları sana hak olarak okuyoruz. Allah, alemlere zulmetmek istemez."},{"n":109,"t":"Göklerde ve yerde ne varsa hepsi Allah’ındır. Bütün işler Allah’a döndürülür."},{"n":110,"t":"Siz; insanlar için çıkarılmış en hayırlı ümmetsiniz. İyiliği emreder, kötülükten alıkorsunuz. Ve Allah’a inanırsınız. Ehl-i Kitab’da inanmış olsaydı; kendileri için hayırlı olurdu. İçlerinde iman edenler olmakla beraber, çoğu fasıklardır."},{"n":111,"t":"İncitmekten başka size herhangi bir zarar veremezler. Sizinle savaşsalar bile geri dönüp kaçarlar. Sonra kendilerine yardım da edilmez."},{"n":112,"t":"Nerede bulunurlarsa bulunsunlar; üzerlerine zillet vurulmuştur. Allah’ın ve mü’minlerin ahdine sığınmış olanlar müstesna. Allah’ın hışmına uğradılar. Üzelerine de miskinlik vuruldu. Bu, Allah’ın ayetlerini inkar etmeleri ve haksız yere peygamberleri öldürmelerindendir. Bu, onların isyan etmeleri ve taşkınlık yapmalarındandır."},{"n":113,"t":"Hepsi bir değildir. Onlardan secdeye vararak geceleri Allah’ın ayetlerini okuyup duran bir topluluk vardır."},{"n":114,"t":"Onlar; Allah’a ve ahiret gününe inanırlar. İyiliği emreder, kötülükten alıkoyarlar. Hayırlara koşuşurlar, işte onlar salihlerdendir."},{"n":115,"t":"Ne hayır yaparlarsa; ondan mahrum bırakılacak değildirler. Ve Allah, takva sahiblerini bilir."},{"n":116,"t":"Küfredenlerin malları ve çocukları Allah’a karşı kendilerine hiçbir fayda sağlamayacaktır. Onlar cehennem yaranıdırlar, orada ebediyyen kalacaklardır."},{"n":117,"t":"Bu dünya hayatında onların sarfettikleri şeylerin durumu; kendilerine zulmeden bir kavmin ekinlerine isabet ederek mahveden kavurucu bir rüzgarın durumuna benzer. Allah onlara zulmetmedi, ama onlar; kendilerine zulmediyorlardı."},{"n":118,"t":"Ey iman edenler; sizden başkalarını dost edinmeyin. Onlar; sizi, şaşırtmaktan geri kalmazlar. Sıkıntıya düşmenizi isterler. Öfkeleri ağızlarından taşmaktadır. Sinelerinin gizlediği ise daha büyüktür. Düşünürseniz size ayetlerimizi açıkladık."},{"n":119,"t":"İşte siz; öyle kimselersiniz ki; onlar sizi sevmezken, siz onları seversiniz. Ve kitabın bütününe inanırsınız. Onlar ise ancak sizinle karşılaştıkları zaman; İman ettik, derler. Yalnız başlarına kaldıkları vakit de, size karşı öfkeden parmaklarını ısırırlar. De ki: Öfkenizden ölün. Gerçekten Allah, göğüslerin özünü bilir."},{"n":120,"t":"Sizlere bir iyilik dokunursa; bu onları, üzer. Ama başınıza bir felaket gelirse; buna sevinirler. Sabreder ve sakınırsanız, onların hilesi size hiçbir zarar veremez. Şüphesiz ki, Allah, onların yaptıklarını kuşatmıştır."},{"n":121,"t":"Hani sen; mü’minleri savaş için duracakları yere yerleştirmek üzere erkenden ayrılmıştın. Allah, Semi’dir, Alim’dir."},{"n":122,"t":"O zaman sizden iki takım bozulmaya yüz tutmuştu. Halbuki onların dostu Allah idi. Mü’minler yalnız Allah’a güvenip, dayansınlar."},{"n":123,"t":"Andolsun ki siz, düşkün bir durumda iken Bedir’de Allah size kat’i bir zafer vermişti. Allah’tan korkun ki şükretmiş olasınız."},{"n":124,"t":"Hani sen; mü’minlere: İndirilmiş üçbin melekle Rabbınızın size yardım etmesi yetmez mi? diyordun."},{"n":125,"t":"Evet. Sabreder, sakınırsanız ve onlar da üzerinize gelirlerse; Rabbınız, size nişanlı beşbin melekle yardım edecektir."},{"n":126,"t":"Bu yardımı Allah; size, sırf bir müjde olsun ve kalbleriniz bununla yatışsın diye yaptı. Yoksa zafer, ancak Aziz ve Hakim olan Allah’tandır."},{"n":127,"t":"Küfredenlerin bir kısmını kessin veya perişan etsin de ümitsiz olarak geri dönüp gitsinler diye."},{"n":128,"t":"Senin elinde emirden bir şey yok. Allah, ya onların tevbesini kabul eder, yahut da zalim oldukları için azablandırır."},{"n":129,"t":"Göklerde ve yerde ne varsa hepsi Allah’ındır. Dilediğini bağışlar, dilediğine azab eder. Ve Allah, Gafur’dur, Rahim’dir."},{"n":130,"t":"Ey iman edenler; kat kat faiz yemeyin. Allah’tan korkunki felah bulasınız."},{"n":131,"t":"Kafirler için hazırlanmış olan ateşten sakının."},{"n":132,"t":"Allah’a ve Peygamber’e itaat edin ki rahmete erdirilesiniz."},{"n":133,"t":"Rabbınızın mağfiretine ve genişliği göklerle yer arası kadar olan cennete koşun. O, takva sahibleri için hazırlanmıştır."},{"n":134,"t":"Onlar ki; bollukta ve darlıkta infak ederler, öfkelerini yenerler, insanların kusurlarını bağışlarlar. Allah, ihsan edenleri sever."},{"n":135,"t":"Onlar ki; fena bir şey yaptıklarında veya kendilerine zulmettiklerinde Allah’ı anarlar. Hemen günahlarının bağışlanmasını dilerler. Günahları, Allah’tan başka kim bağışlar? Hem onlar yaptıklarında bile bile ısrar da etmezler."},{"n":136,"t":"İşte onların mükafatı: Rabblarından bir mağfiret ve altından ırmaklar akan cennetlerdir. Orada temelli kalacaklardır. Ne de güzeldir mükafatı iş yapanların."},{"n":137,"t":"Sizden önce neler gelip geçti. Onun için gezin de yalanlayanların sonunun nasıl olduğunu görün."},{"n":138,"t":"Bu; insanlar için bir açıklama, müttakiler için de bir hidayet, bir öğüttür."},{"n":139,"t":"Gevşemeyin, üzülmeyin, gerçekten inanmışsanız, mutlaka siz üstünsünüz."},{"n":140,"t":"Eğer size bir yara dokunduysa; şüphesiz o kavme de o kadar yara dokunmuştur. Hem o günleri Biz, insanlar arasında döndürür dururuz. Bu; Allah’ın iman edenleri belirtmesi ve içinizden şahidler edinmesi içindir. Allah, zalimleri sevmez."},{"n":141,"t":"Bu; Allah’ın iman edenleri seçmesi, kafirleri mahvetmesi içindir."},{"n":142,"t":"Yoksa; Allah, içinizden cihad edenleri ve sabredenleri belirtmeden cennet’e girivereceğinizi mi sandınız?"},{"n":143,"t":"Gerçekten siz, ölümle karşılaşmadan önce onu arzulamıştınız. İşte onu gördüğünüz halde bakıp duruyorsunuz."},{"n":144,"t":"Muhammed; sadece bir elçidir. Ondan önce de nice elçiler gelip geçmiştir. Şimdi o, ölür veya öldürülürse; geriye mi döneceksiniz? Kim geriye dönerse; Allah’a hiç bir zarar vermez. Allah, şükredenlerin mükafatını verecektir."},{"n":145,"t":"Allah’ın izni olmadıkça hiç bir kimseye ölmek yoktur. O, vadesiyle yazılmış bir yazıdır. Kim dünya nimetini isterse kendisine ondan veririz, kim de ahiret nimetini dilerse buna da ondan veririz. Ve şükredenleri mükafatlandıracağız."},{"n":146,"t":"Nice peygamberler, beraberinde Rabba kul olanlardan bir çoğu bulunduğu halde savaştılar ve Allah yolunda başlarına gelenlerden dolayı yılmadılar, boyun eğmediler. Allah, sabredenleri sever."},{"n":147,"t":"Sadece: Ey Rabbımız, günahlarımızı ve işimizdeki israfımızı bize bağışla, sebatımızı artır; kafirler güruhuna karşı bize yardım et, diyorlardı."},{"n":148,"t":"Bu yüzden Allah, onlara dünya nimetini de, ahiret nimetini de fazlasıyla verdi. Ve Allah ihsan edenleri sever."},{"n":149,"t":"Ey iman edenler; küfredenlere uyarsanız ökçelerinizin üstünden sizi geri çevirirler de hüsrana uğrayanlardan olursunuz."},{"n":150,"t":"Halbuki Mevlanız Allah’tır. Ve O, yardımcıların en hayırlısıdır."},{"n":151,"t":"Hakkında hiçbir delil indirilmediği şeyi Allah’a eş tuttuklarından dolayı küfredenlerin kalblerine korku salacağız. Onların varacağı yer, ateştir. Ne kötüdür o zalimlerin varacağı yer."},{"n":152,"t":"Gerçekten Allah’ın size olan vaadi doğru çıktı; O’nun izni ile kafirleri kırıp biçiyordunuz ki içinizden, dünyayı isteyenler ve ahireti isteyenler bulunduğundan sevdiğiniz zaferi size gösterdikten sonra; baş kaldırdığınız, verilen emir hakkında çekiştiğiniz ve yıldığınız zaman, imtihan etmek için Allah sizi mağlubiyete uğrattı. Bununla beraber sizi bağışladı. Allah mü’minlere lütufkardır."},{"n":153,"t":"Hani siz; kimseye bakmadan kaçıyordunuz. Peygamber de arkanızdan çağırıp duruyordu. Kaybettiğinize ve başınıza gelene üzülmeyesiniz diye Allah, sizi kederden kedere uğrattı. Ve Allah, yaptıklarınızdan haberdardır."},{"n":154,"t":"Sonra o üzüntünün ardından, üzerinize öyle bir emniyet ve öyle bir uyku indirdi ki; içinizden bir kısmını bürüyordu, bir kısmı da canları sevdasına düşmüştü. Allah’a karşı cahiliyet zannı gibi haksız bir zan besliyorlar. Bu işten bize ne? diyorlardı. De ki: Bütün iş Allah’ındır. İçlerinde sana açmadıkları birşey gizliyorlar. Bu, bize ait birşey olsaydı burada öldürülmezdik, diyorlar. De ki: Evlerinizde olsaydınız üzerlerine ölüm yazılmış olanlar yine mutlaka devrilecekleri yerlere çıkıp gideceklerdi. Bu; göğüslerinizin içindekini yoklamak, kalblerinizdekini temizlemek içindir. Allah, göğüslerdekini bilendir."},{"n":155,"t":"İki topluluğun karşılaştığı gün; içinizden geri dönenleri, yaptıklarının bir kısmından ötürü şeytan yoldan çıkarmak istemiştir. Bununla beraber Allah onları bağışladı. Gerçekten Allah, Gafur’dur, Halim’dir."},{"n":156,"t":"Ey iman edenler; siz; küfredip de yeryüzünde dolaşan veya gazada bulunan kardeşleri hakkında: Onlar yanınızda olsalardı ölmezler veya öldürülmezlerdi, diyenler gibi olmayın. Allah; bunu, onların kalblerinde bir hasret olarak koydu. Halbuki öldüren de dirilten de Allah’tır. Ve Allah, yaptığınız şeyleri görendir."},{"n":157,"t":"Andolsun ki, Allah yolunda öldürülür veya ölürseniz; Allah’ın bağışlaması ve rahmeti onların toplayacağı şeylerden çok daha hayırlıdır."},{"n":158,"t":"Andolsun ki, ölseniz de, öldürülseniz de; Allah katında toplanacaksınız."},{"n":159,"t":"Allah’ın rahmeti sayesinde sen onlara karşı yumuşak davrandın. Eğer kaba ve katı kalbli olsaydın şüphesiz çevrenden dağılır giderlerdi. Öyleyse onları bağışla ve yargılanmalarını dile. İşler hakkında onlarla müşavere et. Bir kerre de azmettin mi artık Allah’a tevekkül et. Muhakkak Allah, tevekkül edenleri sever."},{"n":160,"t":"Allah size yardım ederse, artık sizi yenecek yoktur. Sizi yardımsız bırakırsa da ondan başka size yardım edecek kimdir. Mü’minler sadece Allah’a tevekkül etsinler."},{"n":161,"t":"Bir peygamber için emanete hıyanet, olur şey değildir. Kim böyle hainlik ederse; kıyamet günü hainlik ettiği şey ile gelir. Sonra herkese kazandığı ödenir. Ve onlara zulmedilmez."},{"n":162,"t":"Allah’ın rızasına uyan kimse; hiç Allah’ın hışmına uğrayan gibi olur mu? Onun varacağı yer, cehennemdir. O, ne kötü dönüş yeridir."},{"n":163,"t":"Onlar, Allah katında derece derecedir. Allah yaptıklarını görendir."},{"n":164,"t":"And olsun ki: Allah, mü’minlere büyük bir lutufda bulunmuştur. Zira onlara Allah’ın ayetlerini okuyan, teskiye eden, kitab ve hikmeti öğreten kendi içlerinden bir peygamber göndermiştir. Halbuki onlar, daha önce apaçık bir dalalet içindeydiler."},{"n":165,"t":"Onları iki misline uğrattığınız bir musibete kendiniz uğrayınca; bu nereden? dediniz. De ki: O, kendinizdendir. Doğrusu Allah herşeye kadirdir."},{"n":166,"t":"İki ordu karşılaştığı gün size gelen musibet, Allah’ın emriyleydi. Bu; mü’minleri belirtmek içindi."},{"n":167,"t":"Bir de münafıklık edenleri açığa vurmak içindi. Kendilerine: Gelin Allah yolunda savaşın veya savunun, dendiği zaman: şayet savaşmayı bilseydik peşinizden gelirdik, dediler. O gün onlar imandan çok küfre yakındılar. Kalblerinde olmayan şeyi ağızlarıyla söylüyorlardı. Onların gizlediği şeyi Allah çok iyi bilir."},{"n":168,"t":"Kendileri oturarak kardeşleri için: Bize uysalardı öldürülmezlerdi, diyenlere, de ki: Şayet sadıklardan iseniz, kendi nefislerinizden ölümü geri çevirin."},{"n":169,"t":"Allah yolunda öldürülenleri sakın ölü sanmayın, bilakis onlar diridirler, Rabbları katında rızıklandırılırlar."},{"n":170,"t":"Allah’ın keremiyle kendilerine verdiklerinden sevinerek arkalarından henüz kendilerine katılmayanlara; kendilerine korku olmadığını ve üzülmeyeceklerini, müjdelemek isterler."},{"n":171,"t":"Onlar Allah’tan gelen bir nimet ve kerem ile ve Allah’ın mü’minlerin mükafatını zayi etmeyeceği müjdesiyle sevinirler."},{"n":172,"t":"Kendileri yara aldıktan sonra yine Allah’ın ve peygamberin davetine koşanlar, ihsan edenler ve sakınanlar için pek büyük mükafat vardır."},{"n":173,"t":"Onlar ki: Bir takım kimseler kendilerine; düşmanlarınız sizin için kuvvetlerini topladılar onlardan korkun dedikleri zaman, bu haber onların imanını artırır da, Allah bize kafidir. O ne güzel vekildir, derler."},{"n":174,"t":"Sonra da kendilerine hiç bir kötülük dokunmadan Allah’tan bir nimet ve bollukla geri döndüler. Allah’ın rızasına uydular. Ve Allah, çok büyük lutuf sahibidir."},{"n":175,"t":"O şeytan, ancak kendi dostlarını korkutur. Mü’min iseniz onlardan korkmayın, Benden korkun."},{"n":176,"t":"Küfre koşanlar, seni üzmesin. Şüphesiz onlar, Allah’a zarar veremezler. Allah, onlara ahirette hiç bir nasib vermemek istiyor. Onlar için büyük bir azab vardır."},{"n":177,"t":"İman karşılığı küfrü satın alanlar; Allah’a hiç bir şey ile zarar veremezler. Onlar için elem verici bir azab vardır."},{"n":178,"t":"Küfredenler, kendilerine mühlet verişimizi; sakın kendileri için hayırlı sanmasınlar, Biz onlara sırf günahları çoğalsın diye mühlet veriyoruz. Onlar için alçaltıcı bir azab vardır."},{"n":179,"t":"Allah; mü’minleri oldukları halde bırakacak değildir. Nihayet murdarı temizden ayıracaktır. Allah, size gaybı da bildirecek değildir. Fakat Allah, peygamberlerinden dilediğini seçer. Bunun için siz, Allah’a ve peygamberlerine inanın. İnanır ve sakınırsanız; size çok büyük bir mükafat vardır."},{"n":180,"t":"Allah’ın fazl-ı kereminden verdiği şeylerde cimrilik edenler; bunun kendileri için hayırlı olduğunu sanmasınlar. Bilakis bu, onlar için şerlidir. Cimrilik ettikleri şey; kıyamet günü boyunlarına dolanacaktır. Göklerin ve yerin mirası Allah’ındır. Ve Allah, işlediğiniz şeylerden haberdardır."},{"n":181,"t":"Gerçekten, Allah, fakirdir, bizler zenginiz, diyenlerin lafını; Allah işitmiştir. Dediklerini ve haksız yere peygamberleri öldürdüklerini yazacağız. Ve: Tadın o yangın azabını, diyeceğiz."},{"n":182,"t":"Bu, yaptığınızın karşılığıdır. Allah kullarına asla zulmedici değildir."},{"n":183,"t":"Doğrusu, ateşin yiyeyceği bir kurban getirmedikçe; hiçbir peygambere inanmamamız için Allah, bize and verdi, diyenlere; benden önce nice peygamberler size apaçık delillerle ve dediğiniz şeylerle geldi. Doğru söylüyorsanız niçin onları öldürdünüz? de."},{"n":184,"t":"Seni yalanladılarsa senden önce açık mucizeler, sahifeler ve nurlu kitabı getirenler de yalanlanmıştı."},{"n":185,"t":"Her nefis, ölümü tadacaktır. Kıyamet günü ecirleriniz size eksiksiz verilecektir. O vakit, kim ateşten uzaklaştırılır, cennete sokulursa; artık o, kurtulmuştur. Zaten dünya hayatı, aldatıcı geçimlikten başka bir şey değildir."},{"n":186,"t":"And olsun ki; mallarınız ve nefisleriniz konusunda deneneceksiniz. Sizden önce kendilerine kitab verilenlerden ve Allah’a şirk koşanlardan birçok incitici şeyler işiteceksiniz. Eğer sabreder ve sakınırsanız işte bu, azme değer işlerdendir."},{"n":187,"t":"Hani Allah, kendilerine kitab verilenlerden; onu mutlaka insanlara açıklayacaksınız, gizlemeyeceksiniz, diye söz almıştı. Onlar ise bunu arkalarına attılar ve az bir değere değiştiler. Satın aldıkları şey ne kötüdür."},{"n":188,"t":"Ettikleri ile sevinen ve yapmadıkları şeylerle övülmeyi sevenlerin azabtan kurtarılacaklarını sanma. Onlar için pek acıklı bir azab vardır."},{"n":189,"t":"Göklerin ve yerin mülkü Allah’ındır. Allah, her şeye Kadir’dir."},{"n":190,"t":"Muhakkak ki göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelmesinde; akıl sahibleri için elbette ayetler vardır."},{"n":191,"t":"Onlar ki; ayakta, oturarak ve yanları üstü yatarken Allah’ı anarlar, göklerin ve yerin yaratılışını düşünürler. Rabbımız; Sen bunları boşuna yaratmadın. Sen pak ve münezzehsin. Bizi, o ateş azabından koru."},{"n":192,"t":"Rabbımız; Sen, kimi ateşe sokarsan; şüphesiz onu perişan edersin. Zalimlerin hiç yardımcıları yoktur."},{"n":193,"t":"Rabbımız; doğrusu biz: Rabbınıza inanın, diye imana çağıran bir davetçiyi işittik ve imana geldik. Ey Rabbımız; günahlarımızı bağışla, kusurlarımızı ört, canımızı da iyilerle birlikte al."},{"n":194,"t":"Rabbımız; bize peygamberlerinin va’d ettiklerini ver ve kıyamet günü rezil etme bizi. Sen, sözünden asla dönmezsin."},{"n":195,"t":"Nihayet Rabbları, onlara icabet etti: Birbirinizden meydana gelen sizlerden; gerek erkek olsun gerek dişi olsun, çalışanın işini boşa çıkarmam. Hicret edenlerin, yurtlarından çıkarılanların, benim yolumda işkenceye, hakarete, ziyana uğrayanların, muharebe edenlerin ve öldürülenlerin suçlarını elbette örteceğim, Allah katından mükafat olmak üzere; onları altlarından ırmaklar akan cennetlere koyacağım. Sevabın en güzeli, Allah katındadır."},{"n":196,"t":"Küfredenlerin diyar diyar dönüp dolaşmaları sakın seni aldatmasın."},{"n":197,"t":"Az bir geçim. Sonra varacakları yer cehennemdir. O ne kötü yataktır."},{"n":198,"t":"Fakat Rabblarından korkanlar için; altlarından ırmaklar akan cennetler var. Orada temelli kalacaklar. Allah tarafından ağırlanacaklar. Allah katında olanlar kendileri için daha hayırlıdır."},{"n":199,"t":"Ehl-i Kitab’tan öyleleri vardır ki; Allah’a, size indirlen ve kendilerine indirilmiş olana, Allah’a huşu’ duyarak inanırlar. Allah’ın ayetlerini az bir pahaya değişmezler. İşte onların ecirleri Rabbları katındadır. Allah, şüphesiz hesabı çabuk görendir."},{"n":200,"t":"Ey iman edenler; sabredin, sebat gösterin, düşmana karşı durun ve Allah’tan sakının ki, felah bulasınız."}],[{"n":1,"t":"Ey insanlar; sizi bir tek nefisten yaratan, ondan eşini var eden ve ikisinden bir çok erkek ve kadın üreten Rabbınızdan korkun. Kendisi adına birbirinizden dilekte bulunduğunuz Allah’dan korkun da, akrabalık bağını kesmekten sakının. Muhakkak ki Allah; sizin üzerinizde tam bir gözeticidir."},{"n":2,"t":"Yetimlere mallarını verin. Temizi murdara değişmeyin. Onların mallarını kendi mallarınıza katarak yemeyin. Çünkü bu, büyük bir günahtır."},{"n":3,"t":"Eğer yetim kızların haklarını gözetemeyeceğinizden korkarsanız; size helal olan diğer kadınlardan ikişer, üçer ve dörder olmak üzere nikahlayın. Şayet aralarında adalet yapamayacağınızdan endişe ederseniz; o zaman, bir tane. Veya sağ ellerinizin sahip oldukları. Bu adaletten sapmamanıza daha uygundur."},{"n":4,"t":"Kadınların mehirlerini seve seve verin. Şayet ondan bir kısmını gönül hoşluğu ile size bağışlar iseler, onu afiyetle yiyin."},{"n":5,"t":"Allah’ın sizi başına diktiği mallarınızı beyinsizlere vermeyin. Kendileribi bunların geliri ile rızıklandırıp giydirin ve onlara güzel söz söyleyin."},{"n":6,"t":"Öksüzleri evlenme çağına gelene kadar deneyin. O vakit kendilerinde bir olgunlaşma görürseniz; mallarını kendilerine teslim edin. Büyüyecekler de geri alacaklar diye onları israf edip de tez elden yemeyin. Zengin olan sakınsın. Fakir olan da uygun bir şekilde yesin. Mallarını kendilerine verdiğinizde yanlarında şahid bulundurun. Hesab sorucu olarak Allah kafidir."},{"n":7,"t":"Ana-babanın ve yakınların bıraktıklarında erkeklere bir pay vardır. Ana-babanın ve yakınların bıraktıklarında kadınlara da bir pay vardır. Bunlar; az veya çok farz kılındığı şekilde bir paydır."},{"n":8,"t":"Miras taksim olunurken; yakınlar, yetimler ve miskinler de hazır bulunursa, onları da rızıklandırın. Hem de güzel söz söyleyin."},{"n":9,"t":"Arkalarında küçük ve aciz çocuklar bıraktıkları takdirde, onlar için endişe edecek olanlar, haksızlıktan çekinsinler, Allah’tan sakınsınlar ve sözü de dosdoğru söylesinler."},{"n":10,"t":"Yetimlerin mallarını zulmen yiyenler; karınlarına sadece ateş doldurmuş olurlar. Zaten onlar çılgın bir ateşe gireceklerdir."},{"n":11,"t":"Çocuklarınızın mirastaki durumu hakkında Allah, size şöyle emir buyuruyor: Erkeğe iki dişinin hissesi kadardır. Eğer kadınlar ikinin üstünde ise; bırakılan malların üçte ikisi onlarındır. Şayet kız tek ise, yarısı onundur. Ölenin çocuğu varsa; ana ve babadan herbirine bırakılan malın altıda biri; çocuğu olmayıp da ona ana ve babası mirasçı olduysa; üçte biri, anasınındır. Kardeşleri varsa; o vakit, altıda bir anasınındır. Bu hükümler ölenin borcu ödenip yaptığı vassiyetler yerine getirildikten sonradır. Babalarınız ve oğullarınızdan hangisinin fayda bakımından size daha yakın olduğunu bilmezsiniz. Allah’tan bir fariza olarak. Doğrusu Allah; Alim, Hakim olandır."},{"n":12,"t":"Çocukları yoksa; eşlerinizin geriye bıraktıklarının yarısı, sizindir. Çocukları varsa; bıraktıklarının dörtte biri, sizindir. Bunlar; yaptıkları vasiyyet ve borç ödendikten sonradır. Çocuğunuz yoksa; sizin bıraktıklarınızın dörtte biri, eşlerinizindir. Şayet çocuğunuz varsa; bıraktıklarınızın sekizde biri, onlarındır. Ancak bu; yaptığınız vasiyyet ve borç ödendikten sonradır. Eğer miras bırakan erkek veya kadın çocuğu ve ana-babası olmayan bir kimse olur da bir erkek veya bir kız kardeşi bulunursa; bunlardan herbirine, altıda bir düşer. Eğer onlar bundan çoksalar; zarara uğratılmaksızın üçte birine ortak olurlar. Bunlar; yaptıkları vasiyyet ve borç ödendikten sonradır. Allah’tan bir vasiyyet olarak, Allah; Alim’dir, Halim’dir."},{"n":13,"t":"İşte bunlar; Allah’ın hudududur. Kim, Allah’a ve O’nun elçisine itaat ederse; Allah onu, altından ırmaklar akan cennetlere koyacaktır. İşte bu; en büyük kurtuluştur."},{"n":14,"t":"Kim de Allah’a ve O’nun elçisine isyan eder de hududu aşarsa, onu da içinde temelli kalmak üzere ateşe sokar. Hor ve hakir edici bir azab vardır onun için."},{"n":15,"t":"Kadınlarınızdan fuhuş yapanlara karşı, içinizden dört şahid getirin. Onlar şehadet ederlerse; ölünceye veya Allah onlara bir yol gösterinceye kadar evlerde tutun."},{"n":16,"t":"Sizden fuhuş yapanların her ikisine de eziyet edin. Tevbe edip ıslah olurlarsa; artık onlardan vazgeçin. Çünkü Allah, Tevvab, Rahim olandır."},{"n":17,"t":"Allah için tevbe ancak, bilmeyerek kötülük yapıp da hemen tevbe edenlerin tevbesidir. İşte Allah, onların tevbesini kabul eder. Ve Alim, Hakim olandır."},{"n":18,"t":"Kötülükleri işleyip dururken, ölüm gelip çatınca: Şimdi işte gerçekten tevbe ettim, diyenlerin ve kafir olarak ölenlerin tevbesi kabul değildir. İşte onlar için, elem verici bir azab hazırlamışızdır."},{"n":19,"t":"Ey iman edenler; kadınlara zorla varis olmaya kalkmanız size helal değildir. Apaçık hayasızlık etmedikçe onlara verdiğinizden mehrin bir kısmını alıp götürmeniz için onları sıkıştırmayın, onlarla iyi geçinin. Eğer onlardan boşanmıyorsanız; olabilir ki bir şey, sizin hoşunuza gitmez de Allah onu çok daha hayırlı kılar."},{"n":20,"t":"Bir eşin yerine başka bir eş almak istediğiniz takdirde; öncekine yüklerle mehir vermiş olsanız bile, bir şey almayın. İftira ederek ve günaha girerek ona verdiğiniz geri alır mısınız?"},{"n":21,"t":"Onu nasıl alırsınız ki; birbirinize karışıp katıldınız. Ve onlar, sizden kuvvetli te’minat aldılar."},{"n":22,"t":"Babalarınızın nikahladığı kadınları nikahlamayın. Geçmişte olanlar artık geçmiştir. Çünkü o, çok çirkin ve iğrenç bir şeydi. Ve o, fena adetti."},{"n":23,"t":"Analarınız, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, kardeşlerinizin kızları, kız kardeşlerinizin kızları, sizi emziren süt anneleriniz, süt kardeşleriniz, karılarınızın anaları, gerdeğe girdiğiniz karılarınızdan evlerinizde bulunan üvey kızlarınız, size haram kılındı. Eğer üvey kızlarınızın anaları ile gerdeğe girmemişseniz, onlarla evlenmenizde bir vebal yoktur. Öz oğullarınızın karıları ile evlenmeniz ve iki kızkardeşi birlikte nikahlamanız da haramdır. Geçmişte olanlar artık geçmiştir. Şüphesiz ki Allah, Gafur’dur, Rahim’dir."},{"n":24,"t":"Evli kadınlarla evlenmeniz de. Sağ ellerinizin sahib oldukları müstesna. Bunlar; Allah’ın size farz kıldığı hükümlerdir. Geriye kalanları ise; zinadan kaçınıp iffetli yaşamanız şartı ile mallarınızla istemeniz size helal kılındı. Onlardan yararlandığınızın karşılığı olarak kararlaştırılmış olan mehirlerini verin. Kararlaştırdıktan sonra, aranızda anlaştığınız hususta size bir sorumluluk yoktur. Şüphesiz ki Allah, Alim, Hakim olandır."},{"n":25,"t":"Sizden; hür, inanmış kadınlarla evlenmeye güç yetiremeyen kimse, inanmış genç kızlarınızdan sağ ellerinizin sahib olduklarından (alsın). Allah sizin imanınızı daha iyi bilir. Birbirinizdensiniz. Onlarla zinadan kaçınmaları, iffetli yaşamış ve gizli dost tutmamış olmaları halinde, velilerinin izniyle evlenin. Ve ma’ruf şekilde mehirlerini verin. Evlendiklerinde zina edecek olurlarsa; onlara hür kadınlara verilen cezanın yarısı verilir. Bu; içinizden, günaha girme korkusu olanlaradır. Sabretmeniz ise sizin için daha hayırlıdır. Allah, Gafur’dur, Rahim’dir."},{"n":26,"t":"Allah; size bilmediklerinizi açıkça bildirmek, sizden öncekilerin yollarını size göstermek ve tövbelerinizi kabul etmek ister. Allah Halim’dir, Hakim’dir."},{"n":27,"t":"Allah; sizin tövbelerinizi kabul etmek ister. Şehvetlerine uyanlarda sizin büyük bir sapıklığa düşmenizi isterler."},{"n":28,"t":"Allah (tekliflerini) sizden hafifletmek istiyor. Ve insan, zayıf yaratılmıştır."},{"n":29,"t":"Ey iman edenler; mallarınızı aranızda karşılıklı rıza ile gerçekleştirdiğiniz ticaret yolu hariç, batıl yollarla yemeyin. Ve kendinizi öldürmeyin. Şüphesiz ki Allah, sizin için Rahim olandır."},{"n":30,"t":"Kim, zulüm ve düşmanlıkla bunu yaparsa; yakında onu cehenneme sokacağız. Bu Allah’a kolaydır."},{"n":31,"t":"Size yasaklanan büyük günahlardan kaçınırsanız; küçük günahlarınızı örter ve sizi şerefli bir mevkiye koyarız."},{"n":32,"t":"Allah’ın sizi birbirinizden üstün kıldığı şeyleri özlemeyin. Erkeklere kazandıklarından bir pay vardır. Kadınlara da kazandıklarından bir pay vardır. Allah’ın lütfundan isteyin. Muhakkak ki Allah; herşeyi bilici olandır."},{"n":33,"t":"Ana-babanın ve akrabanın geriye bıraktıklarından her birine varisler kıldık. Yeminlerinizin bağladığı kimselere hisselerini verin. Muhakkak ki; Allah herşeye şahid olandır."},{"n":34,"t":"Allah’ın kimini kimine üstün kılmış olması ve onların mallarından infak etmeleri sebebiyle erkekler, kadınlar üzerine hakimdirler. İyi kadınlar; itaatli olan ve Allah’ın kendilerini korumasına karşılık, kendileri de gizliyi koruyanlardır. Serkeşlik etmelerinden endişelendiğiniz kadınlara öğüt verin, kendilerini yataklarında yalnız bırakın, (yine uslanmazlarsa) dövün, sizi itaat ederlerse aleyhlerinde bir yol aramayın. Muhakkak ki Allah; Aliyy ve Kebir olandır."},{"n":35,"t":"Eğer aralarının açılmasından endişeye düşerseniz; erkek tarafından bir hakem, kadın tarafından bir hakem gönderin. Bunlar barıştırılmak isterlerse; Allah, onların arasını bulur. Muhakkak ki Allah; Alim, Habir olandır."},{"n":36,"t":"Allah’a ibadet edin. O’na hiç bir şeyi ortak koşmayın. Ana-babaya da iyilik. Yakınlara, yetimlere, düşkünlere, yakın komşuya, uzak komşuya, yakın arkadaşa, yolcuya ve sağ elinizin sahib olduklarına da. Allah, kendini beğenip böbürlenenleri elbette sevmez."},{"n":37,"t":"Onlar ki; hem cimrilik ederler, hem de insanlara cimrilik tavsiye ederler ve Allah’ın kendilerine lütfundan verdiği şeyleri saklarlar. Biz, kafirler için hor ve rüsvay edici bir azab hazırladık."},{"n":38,"t":"Mallarını, insanlara gösteriş için sarfeden, Allah’a ve ahiret gününe inanmayanları da Allah sevmez. Şeytan kime arkadaş olursa; o, ne kötü bir arkadaştır."},{"n":39,"t":"Ne olurdu sanki onlar; Allah’a, ahiret gününe inanmış ve Allah’ın verdiği rızıklardan infak etmiş olsalardı. Allah onları çok iyi bilendir."},{"n":40,"t":"Allah; şüphesiz zerre kadar haksızlık yapmaz. Ama zerre kadar iyilik yapılsa onu kat kat artırır. Ve kendi katından büyük bir mükafaat verir."},{"n":41,"t":"Her ümmetten bir şahid kıldığımız ve onlara da seni şahid getirdiğimiz zaman nice olacak?"},{"n":42,"t":"İşte o gün, küfredip Rasul’e asi olanlar, isterlerdi ki; yerle bir olsalardı da Allah’dan o bir sözü gizlememiş bulunsalardı."},{"n":43,"t":"Ey iman edenler; sarhoşken, ne söylediğinizi bilinceye kadar, bir de cünübken -yolcu olmanız müstesnagusül yapmadıkça namaza yaklaşmayın. Eğer hasta veya yolculukta iseniz, yahut herhangi biriniz heladan gelirse veya kadınlara yaklaşıp da su bulamazsanız, temiz bir toprağa teyemmüm edin, yüzlerinize ve ellerinize sürün. Şüphesiz ki Allah; Afüvv ve Gafur olandır."},{"n":44,"t":"Bakmaz mısın şu kendilerine kitabdan bir pay verilmiş olanlara? Kendileri sapıklığı satın aldıkları gibi sizin de yoldan sapmanızı istiyorlar."},{"n":45,"t":"Allah, düşmanlarınızı daha iyi bilir. Allah, size dost olarak da yeter, yardımcı olarak da yeter."},{"n":46,"t":"Yahudilerden öyleleri var ki; kelimeleri yerlerinden değiştirir ve dillerini eğip bükerek ve dine tan ederek; işittik ve karşı geldik, duy, duymaz olası ve bizi güt (raina) derler. Eğer işittik ve itaat ettik, dinle ve bizi gözet demiş olsalardı, onlar için daha iyi olurdu. İşte Allah, inkarları yüzünden onlara la’net etmiştir. Onların ancak pek azı iman eder."},{"n":47,"t":"Ey kitab verilenler; Biz bir takım yüzleri silip de enselerine çevirmezden veya onları Ashab-ı Sebit’i la’netlediğimiz gib la’netlemezden önce, gelin de elinizdekini doğrulayıcı olarak indirdiğimize iman edin. Allahın emri daima yapılagelmiştir."},{"n":48,"t":"Allah; kendisine ortak koşmayı bağışlamaz. Bundan başkasını dilediğine bağışlar. Allah’a ortak koşan kimse, hiç şüphesiz pek büyük bir günahla iftira etmiş olur."},{"n":49,"t":"Bakmaz mısın şu kendilerini temize çıkaranlara? Halbuki dilediğini temize çıkaran yalnız Allah’tır. Ve kıl payı zulme uğratılmazlar."},{"n":50,"t":"Bir bak; Allah’a karşı nasıl yalan uyduruyorlar? Apaçık bir günah olarak bu, yeter."},{"n":51,"t":"Kendilerine kitab verilmiş olanların puta ve tağut’a inanıp, küfredenlere: Bunlar mü’minlerden daha doğru yoldadırlar, dediklerini görmedin mi?"},{"n":52,"t":"Allah’ın la’netlediği; işte onlardır. Allah’ın la’netlediği kişiye sen yardımcı bulamazsın."},{"n":53,"t":"Yoksa onların mülkten bir payı mı var? Öyle olsaydı; onlar insanlara bir çekirdek parçası bile vermezlerdi."},{"n":54,"t":"Yoksa Allah’ın bol nimetinden verdiği insanları mı çekemiyorlar? Doğrusu biz, İbrahim soyuna da kitab ve hikmet verdik. Ve onlara büyük bir nimet bahşettik."},{"n":55,"t":"Onlardan bir kısmı ona inandı, bir kısmı da ondan yüz çevirdi. Çılgın ateş olarak cehennem yeter."},{"n":56,"t":"Şüphesiz ki ayetlerimizi inkar edenleri yakında ateşe atacağız. Derileri piştikçe azabı duysunlar diye, derilerini değiştirip yenileyeceğiz. Allah; Aziz, Hakim olandır."},{"n":57,"t":"İman edip salih amel işleyenleri; içinde ebedi kalacakları, altından ırmaklar akan cennetlere koyacağız. Onlara orada tertemiz eşler vardır. Onları koyu bir gölgeye sokacağız."},{"n":58,"t":"Şüphesiz ki Allah; size, emanetleri ehline vermenizi ve insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emreder. Gerçekten Allah; bununla size ne güzel öğüt veriyor. Şüphesiz ki Allah; Semi’, Basir olandır."},{"n":59,"t":"Ey iman edenler; Allah’a itaat edin. Rasule ve sizden olan emir sahiblerine itaat edin. Eğer bir şeyde çekişirseniz; Allah’a ve ahiret gününe inanmışsanız onun hallini Allah’a ve Rasulüne bırakın. Bu; hem hayırlı hem de netice itibariyle daha güzeldir."},{"n":60,"t":"Sana indirilene ve senden önce inidirilenlere; inandıklarını iddia edenleri görmedin mi? Küfretmeleri emrolunmuş iken Tağut’un önünde muhakeme edilmelerini isterler. Halbuki şeytan, onları uzak bir sapıklıkla saptırmak istiyor."},{"n":61,"t":"Onlara; Allah’ın indirdiğine ve peygambere gelin, denilince; münafıkların senden büsbütün uzaklaştıklarını görürsün."},{"n":62,"t":"Kendi işledikleri yüzünden başlarına bir musibet geldiğinde, nasıl hemen sana geldiler de; gayemiz sadece bir iyilik etmek ve ara bulmaktan ibaret idi, diye yemin ediyorlar."},{"n":63,"t":"Onlar öyle kimsler ki; kalblerindekini Allah bilir. Sen onlara aldırma da öğüt ver. Haklarında te’sirli sözler söyle."},{"n":64,"t":"Biz, hiçbir peygamberi Allah’ın izniyle itaat edilmekten başka bir gaye ile göndermedik. Onlar kendilerine yazık ettikleri zaman, sana gelip Allah’tan mağfiret dileseler ve peygamberleri de onlara mağfiret dileseydi elbette Allah’ı Tevvab vd Rahim olarak bulacaklardı."},{"n":65,"t":"Hayır, Rabbına andolsun ki; aralarında çekiştikleri şeylerde seni hakem ta’yin edip sonra haklarında verdiği hükümden dolayı içlerinde bir sıkıntı duymadan kendilerini tamamen teslim etmedikçe iman etmiş olmazlar."},{"n":66,"t":"Şayet onlara; Kendinizi feda edin, yahut memleketinizden çıkın, diye emretmiş olsaydık, pek azı müstesna bunu yapmazlardı. Kendilerine öğüt verilen şeyleri yerine getirseydiler elbette bu; haklarında çok hayırlı ve payidar olma açısından daha sağlam olurdu."},{"n":67,"t":"O takdirde onlara katımızdan büyük bir mükafat verirdik."},{"n":68,"t":"Ve şüphesiz onları doğru yola eriştirirdik."},{"n":69,"t":"Kim, Allah’a ve peygambere itaat ederse; işte onlar, şehidler ve salihlerle birliktedirler. Ne iyi arkadaştır onlar."},{"n":70,"t":"Bu büyük lütuf, Allah’tandır. Allah; her şeyi bilici olarak kafidir."},{"n":71,"t":"Ey iman edenler; korunma tedbirinizi alın da silahlanarak, birlikler halinde veya toptan seferber olun."},{"n":72,"t":"Aranızda pek ağır davranacak olanlar da var. Size bir musibet geldiği takdirde: Allah bana gerçekten lütfetti de onlarla beraber bulunmadım der."},{"n":73,"t":"Şayet Allah’ın büyük bir nimetine mazhar olursanız; andolsun ki, sizinle bir dostluk ve tanışıklığı yokmuş gibi: Keşki onlarla beraber olsaydım da ben de büyük bir başarıya erişseydim, der."},{"n":74,"t":"O halde dünya hayatını ahirete satanlar, Allah yolunda savaşsınlar. Allah yolunda savaşan kimse; öldürülse de, galip gelse de Biz, ona büyük bir mükafat vereceğiz."},{"n":75,"t":"Siz ne oluyor da: Rabbımız, halkı zalim olan şu şehirden bizi kurtar, katından bize bir sahib gönder, bir yardımcı yolla, diyen; zavallı çocuklar, erkekler ve kadınlar uğrunda ve Allah yolunda savaşmıyorsunuz?"},{"n":76,"t":"İman edenler Allah yolunda savaşırlar. Küfür edenler ise, Tağut yolunda harbederler. O halde şeytanın dostlarıyla savaşın. Şüphesiz ki şeytanın hilesi zayıftır."},{"n":77,"t":"Kendilerine: Ellerinizi savaştan çekin, namazı kılın, zekatı verin, denilmiş olanlara bakmaz mısın? Şimdi onların üzerine savaş farz kılınınca; içlerinden bir grup Allah’tan korkar gibi, hatta daha şiddetli bir korku ile insanlardan korkuyorlar. Bunlar: Ey Rabbımız, üzerimize şu savaşı niye farz kıldın? Ne olurdu bizi yakın bir geleceğe kadar geri bırakaydın, dediler. Onlara de ki: Dünyanın geçimi azdır. Ahiret ise, müttakiler için elbet daha hayırlıdır. Ve kıl kadar haksızlığa uğratılmayacaksınız."},{"n":78,"t":"Nerede olursanız olun, sağlam kaleler içinde dahi olsanız ölüm sizi bulacaktır. İman etmeyenlere bir iyilik gelirse: Bu, Allah’tandır. Bir kötülük erişirse de: Bu senin yüzündendir, derler. De ki: Hepsi Allah tarafındandır. Bunlara ne oluyor ki hiçbir sözü anlamaya yanaşmıyorlar?"},{"n":79,"t":"Sana gelen her iyilik, Allah’tandır. Sana gelen her fenalık da kendindendir. Seni insanlara elçi olarak gönderdik. Buna şahid olarak Allah yeter."},{"n":80,"t":"Rasüle itaat eden; Allah’a itaat etmiş olur. Kim de yüz çevirirse; Biz, seni onlara koruyucu göndermedik."},{"n":81,"t":"Sana; peki, derler. Yanından ayrıldıktan sonra da içlerinden bir grup sana söylediklerini hilafına geceleyin plan kurarlar. Allah gece tasarladıklarını yazıyor. Onlara aldırış etme. Allah’a tevekkül et. Vekil olarak Allah yeter."},{"n":82,"t":"Onlar hala Ku’an’ı gereği gibi düşünmeyecekler mi? Eğer o, Allah’tan başkası tarafından gelseydi, muhakkak ki içinde birbirini tutmayan bir çok şeyler bulurlardı."},{"n":83,"t":"Kendilerine güven ve korkuya dair bir haber geldiğinde; onu yayarlar. Halbuki o haberi peygambere veya mü’min kumandanlara götürselerdi; onlar, ondan ne gibi netice çıkaracaklarını bilirlerdi. Eğer üzerinizde Allah’ın nimet ve rahmeti olmasaydı; pek azınız müstesna, şeytana uymuş gitmiştiniz."},{"n":84,"t":"Allah yolunda savaş. Sen, ancak kendinden sorumlusun. İman edenleri de savaşa teşvik et. Umulur ki Allah, küfredenlerin şiddet ve baskısını önler. Allah’ın kahrı da, ibret alınacak cezası da pek şiddetlidir."},{"n":85,"t":"Kim, iyi işte aracılık ederse; ondan kendisine bir pay ayrılır. Kim de kötü bir şeyde aracılık yaparsa; o kötülükten kendisine bir pay vardır. Allah, her şeye hakkıyla kadir ve nazır’dır."},{"n":86,"t":"Size bir selam verildiği zaman; ondan daha iyisiyle selam verin. Veya aynısıyla mukabele edin. Muhakkak ki Allah, her şeyin hesabını arayandır."},{"n":87,"t":"Allah O’ndan başka ilah yoktur. Geleceğinden şüphe olmayan kıyamet günü sizi mutlaka toplayacaktır. Allah’tan daha doğru sözlü kim olabilir?"},{"n":88,"t":"Size ne oluyor ki; münafıklar hakkında iki fırkaya ayrıldınız? Allah, onları yaptıklarından dolayı başaşağı etmiştir. Allah’ın saptırdığını doğru yola getirmek mi istiyorsunuz? Allah’ın saptırdığı kimse için, asla yol bulamazsın."},{"n":89,"t":"Kendileri küfrettikleri gibi, sizin de küfretmenizi isterler. O halde onlar, Allah yolunda hicret edinceye kadar içlerinden dost edinmeyin. Eğer yüz çevirirlerse; bulduğunuz yerde onları öldürün ve onlardan ne bir dost, ne de bir yardımcı edinin."},{"n":90,"t":"Ancak sizinle kendileri arasında bir anlaşma bulunan bir millete sığınanlar ve sizinle savaşmaktan veya kendi milletleriyle harbetmekten bunalarak size başvuranlar müstesnadır. Allah dileseydi; onları size musallat ederdi de sizinle savaşırlardı. Eğer sizden uzak durur, savaşmaz ve size barış teklif ederlerse; Allah, onlara dokunmanıza izin vermez."},{"n":91,"t":"Diğerlerinin de sizden ve kendi milletlerinden güvende olmayı istediklerini göreceksiniz. Fitneciliğe çağırıldıklarında ona can atarlar. Eğer sizden uzak durmazlar, barış teklif etmezler ve sizinle savaşmaktan geri durmazlarsa; onları tutun ve bulduğunuz yerde öldürün. İşte onların aleyhlerine, size apaçık ferman verdik."},{"n":92,"t":"Bir mü’min’in diğer mü’mini hata dışında öldürmesi olur şey değildir. Bir mü’min’i yanlışlıkla öldürenin bir mü’min köleyi azad etmesi ve öldürülenin ailesi bağışlamadıkça ona teslim edilmiş bir diyet ödemesi gerekir. Öldürülen mü’min, düşmanınız olan bir topluluktan ise; mü’min bir köle azad etmek gerekir. Şayet sizin ile kendileri arasında andlaşma bulunan bir topluluktan ise; ailesine verilecek bir diyet ve mü’min bir köle azad etmek gerekir. Bunları bulamayan kimsenin Allah tarafından tevbesinin kabulü için iki ay ardarda oruç tutması gerekir. Allah; Alim, Hakim olandır."},{"n":93,"t":"Kim de bir mü’min’i kasden öldürüse; onun cezası içinde ebediyyen kalacağı cehennemdir. Allah ona gazab etmiş, la’net etmiş ve büyük bir azab hazırlamıştır."},{"n":94,"t":"Ey iman edenler; Allah yoluna koyulduğunuz zaman, iyice araştırın. Size selam verene; dünya hayatının geçici menfaatine göz dikerek; sen mü’min değilsin, demeyin. Allah katında çok ganimetler vardır. Önce siz de öyleydiniz ama Allah size lütfetti. Onun için iyice araştırın. Muhakkak ki Allah; yaptıklarınızdan haberdardır."},{"n":95,"t":"Mü’minlerden; özürsüz olarak yerlerinde oturanlar ile Allah yolunda malları ve canları ile cihad edenler bir değildir. Allah; mallarıyla ve canlarıyla cihad edenleri derece bakımından oturanlara üstün kıldı. Bununla beraber Allah, her ikisine de güzelliği vaad etmiştir. Fakat Allah; cihad edenlere, oturanların üzerine büyük bir mükafat vermiştir."},{"n":96,"t":"Kendisinden dereceler, mağfiret ve rahmet. Ve Allah; Gafur’dur, Rahim’dir."},{"n":97,"t":"Melekler; nefislerine zulmedenlerin canlarını aldıkları zaman: Ne yapıyordunuz? deyince; biz yeryüzünde zayıf düşürülmek istenmiş kimselerdik, diyecekler. Melekler de: Allah’ın yeri geniş değil miydi? Hicret etseydiniz? diyecekler. Onların varacakları yer, cehennemdir. Dönülecek yer olarak ne kötüdür orası."},{"n":98,"t":"Ancak erkek, kadın ve çocuklardan çaresiz kalarak bir yol bulamayan zavallılar müstesnadır."},{"n":99,"t":"Umulur ki Allah, onları affetsin. Ve Allah; Afüvv, Gafur olandır."},{"n":100,"t":"Her kim, Allah yolunda hicret ederse; yeryüzünde bereketli yer ve genişlik bulur. Allah’a ve Rasulüne hicret ederek evinden çıkan kimseye ölüm gelirse; onun ecrini vermek Allah’a düşer. Ve Allah, Gafur’dur, Rahim’dir."},{"n":101,"t":"Yeryüzünde (sefere) koyulduğunuz zaman; kafirlerin size bir fenalık yapmasından korkarsanız; namazı kısaltmanızda size bir vebal yoktur. Şüphe yok ki kafirler, sizin apaçık düşmanınızdır."},{"n":102,"t":"Sen; içlerinde olup da namazlarını kıldırdığın zaman, bir kısmı seninle beraber namaza dursun ve silahlarını da alsınlar. Secdeye vardıklarında onlar arkanıza geçsinler, kılmayan öbür kısım gelsin, seninle beraber kılsınlar. Tedbirli olsunlar, silahlarını alsınlar. Kafirler size ansızın bir baskın vermek için silah ve eşyanızdan gafil bulunmanızı arzu ederler. Yağmurdan zarar görecekseniz veya hasta olursanız, silahlarınızı bırakmanıza bir beis yoktur. Fakat dikkatli olun. Allah; şüphesiz kafirlere horlayıcı bir azab hazırlamıştır."},{"n":103,"t":"Namazı kıldıktan sonra; ayakta iken, otururken, yanlarınız üstü yatarken de Allah’ı anın. Emniyete kavuştuğunuzda; namazı dosdoğru kılın. Namaz; şüphesiz mü’minler üzerine vakitleri belli bir farz olmuştur."},{"n":104,"t":"O kavmi aramakta gevşek davranmayın. Siz, acı çekiyorsanız onlar da sizin çektiğiniz gibi acı çekiyorlar. Halbuki siz; Allah’tan onların beklemedikleri şeyleri bekliyorsunuz. Ve Allah; Alim, Hakim olandır."},{"n":105,"t":"Dosdoğrusu Biz, sana kitabı hak olarak indirdik ki insanlar arasında Allah’ın sana gösterdiği gibi hüküm veresin. Hainlerin savunucusu olma."},{"n":106,"t":"Ve Allah’tan mağfiret dile. Şüphesiz ki Allah; Gafur’dur, Rahim’dir."},{"n":107,"t":"Nefislerine hainlik etmiş kimseleri savunma. Allah; hainlikte direnen günahkarları sevmez."},{"n":108,"t":"İnsanlardan gizlerler de Allah’tan gizlemezler. Halbuki Allah’ın razı olmayacağı sözü, geceleyin uydurup düzdükleri zaman da Allah onlarla beraberdir. Allah; yapacakları herşeyi kuşatıcıdır."},{"n":109,"t":"İşte siz öyle kimselersiniz ki; dünya hayatında onları savunuyorsunuz. Ama kıyamet günü Allah’a karşı onları kim savunacak? Yahut onlara kim vekil olacak?"},{"n":110,"t":"Kim, bir kötülük yapar veya nefsine zulmeder de sonra Allah’dan mağfiret dilerse; Allah’ın Gafur ve Rahim olduğunu görür."},{"n":111,"t":"Kim, bir günah kazanırsa; bunu ancak kendi aleyhine kazanmış olur. Ve Allah; Alim, Hakim olandır."},{"n":112,"t":"Kim, bir hata veya bir günah işler de sonra onu bir suçsuzun üstüne atarsa; şüphesiz iftira etmiş ve apaçık bir günah yüklenmiş olur."},{"n":113,"t":"Eğer Allah’ın lütfu ve rahmeti üzerinde olmasaydı; onlardan bir takımı seni saptırmaya çalışırdı. Halbuki onlar, kendilerinden başkalarını saptıramazlar. Sana da bir zarar veremezler. Allah, sana kitabı ve hikmeti indirmiş, bilmediğini öğretmiştir. Ve Allah’ın senin üzerindeki lütfu çok büyük olmuştur."},{"n":114,"t":"Onların fısıldaşmalarının bir çoğunda hayır yoktur. Ancak sadaka vermeyi, yahut ma’rufu emretmeyi ve insanların arasını düzeltmeyi emreden başka. Kim Allah’ın rızasını arayarak böyle yaparsa; Biz, ona çok büyük bir ecir vereceğiz."},{"n":115,"t":"Kim, kendisine doğru yol apaçık belli olduktan sonra, peygambere karşı gelir, mü’minlerin yolundan başakasına uyup giderse; onu döndüğü yolda bırakırız. Kendisini cehenneme koyarız. Ne kötü dönüş yeridir orası."},{"n":116,"t":"Elbette Allah; kendisine şirk koşulmasını bağışlamaz. Bundan başkasını dilediğine bağışlar. Kim, Allah’a şirk koşarsa; çok uzak bir dalalete düşmüş olur."},{"n":117,"t":"Onu bırakıp da yalnız dişi putlara tapıyorlar. Aslında onlar, inatçı şeytandan başkasına tapmıyorlar."},{"n":118,"t":"Allah; ona la’net etsin. O dedi ki: Celal’in hakkı için, kullarından muayyen bir pay alacağım."},{"n":119,"t":"Onları mutlaka saptıracağım, olmayacak kuruntulara boğacağım. Onlara emredeceğim; davarların kulaklarını yaracaklar, emredeceğim; Allah’ın yaratışını değiştirecekler. Allah’ı bırakıp şeytanı dost edinen kimse; şüphesiz açıktan açığa kayba uğramıştır."},{"n":120,"t":"Şeytan onlara vaad ediyor, kuruntulara düşürüyor. Şeytanın kendilerine vaad ettikleri, aldatmaktan başka birşey değildir."},{"n":121,"t":"Onların varacağı yer, cehennemdir. Oradan kaçacak yer de bulamayacaklardır."},{"n":122,"t":"İman edip salih ameller işleyenlere gelince; Biz, onları altlarından ırmaklar akan cennetlere koyacağız. İşte Allah’ın gerçek vaadi. Allah’dan daha doğru sözlü kim olabilir?"},{"n":123,"t":"Ne sizin kuruntunuzla, ne de kitab ehli olanların kuruntularıyladır. Kim, kötü iş yaparsa; cezasını görür. Ve kendisine Allah’tan başka ne bir dost bulabilir, ne de bir yardımcı."},{"n":124,"t":"Erkek veya kadın her kim ki; mü’min olarak salih amel işlerse cennete girer. Ve kendilerine zerre kadar zulmedilmez."},{"n":125,"t":"İhsan ederek kendini Allah’a teslim eden ve İbrahim’in dinine uymuş olandan daha güzel din sahibi kim olabilir? Allah İbrahim’i dost edinmiştir."},{"n":126,"t":"Göklerde olanlar da, yerde olanlar da Allah’ındır. Allah; her şeyi kuşatıcı olandır."},{"n":127,"t":"Kadınlar hakkında senden fetva istiyorlar. De ki: Onlara dair fetvayı size Allah veriyor. Kendilerine yazılmış olanı vermediğiniz ve nikahlamayı istemediğiniz yetim kızlar hakkında, mağdur çocuklar hakkında ve yetimlere insafla bakmanız hakkında kitabda sizlere okunan ayetler var. Hayır olarak ne yaparsanız, şüphesiz Allah, onu bilicidir."},{"n":128,"t":"Eğer kadın; kocasının serkeşliğinden veya yüz çevirmesinden endişe ederse; anlaşma yoluyla aralarını bulmalarında kendileri için bir günah yoktur. Anlaşmak daha hayırlıdır. Nefisler kıskançlığa meyyaldir. Eğer iyi davranır ve sakınırsanız; Allah işlediklerinizden haberdardır."},{"n":129,"t":"Ne kadar isteseniz; yine de kadınlar arasında adalet yapamazsınız. Bari bir tarafa tamamen meyletmeyin ki; öbürünü askıdaymış gibi bırakmayasınız. Eğer arayı düzeltir ve haksızlıktan sakınırsanız; şüphesiz ki Allah; Gafur, Rahim olandır."},{"n":130,"t":"Eğer ayrılırlarsa; Allah, her birinin nimetinin genişliği ile zengin kılar. Allah; Vasi’, Hakim olandır."},{"n":131,"t":"Göklerde olanlar da, yerde olanlar da Allah’ındır. Andolsun ki; senden önce kendilerine kitab verilenlere de size de hep; Allah’dan korkun, diye tavsiye ettik. Küfür ederseniz; muhakkak ki göklerde olanlar da yerde olanlar da Allah’ındır. Allah; Gani ve Hamid olandır."},{"n":132,"t":"Göklerde olanlar da, yerde olanlar da Allah’ındır. Vekil olarak Allah yeter."},{"n":133,"t":"Ey insanlar; o, dilerse; sizi götürür de yerinize başkalarını getirir. Allah, buna kadirdir."},{"n":134,"t":"Kim, dünya mükafatını isterse bilsin ki; dünyanın da, ahiretin de mükafatı Allah’ın katındadır. Allah; Semi’, Basir olandır."},{"n":135,"t":"Ey iman edenler; kendiniz, ana-babanız ve yakınlarınız aleyhinde de olsa Allah için şahid olarak adaleti gözetin. İster zengin, ister fakir olsun; onları Allah’ın koruması daha uygundur. Adaletinizde heveslere uymayın. Eğer dilinizi büker veya yüz çevirirseniz; Allah, yaptıklarınızdan haberdardır."},{"n":136,"t":"Ey iman edenler; Allah’a, peygamberine, peygamberine indirdiği kitaba ve daha önce indirdiği kitaba inanın. Kim, Allah’ı, meleklerini, kitablarını, peygamberlerini, ve ahiret gününü inkar ederse; şüphesiz derin bir sapıklığa düşmüştür."},{"n":137,"t":"Doğrusu inanıp sonra küfür edenleri, sonra inanıp tekrar küfür edenleri, sonra da küfürleri artmış olanları Allah bağışlamayacaktır. Onları doğru yola da eriştirmeyecektir."},{"n":138,"t":"Münafıklara; kendilerine elem verici bir azab olduğunu müjdele."},{"n":139,"t":"Onlar ki; mü’minleri bırakıp kafirleri dost ediniyorlar. Onların tarafından izzet mi arıyorlar? Doğrusu izzet, bütünüyle Allah’ındır."},{"n":140,"t":"O, size kitabda; Allah’ın ayetlerine küfür edildiğini ve alaya alındığını işittiğinizde, onlar başka bir mevzua intikal edinceye kadar yanlarında oturmayın, yoksa siz de onlar gibi olursunuz, diye bildirdi. Doğrusu Allah; münafıkların ve kafirlerin hepsini cehennemde toplayacaktır."},{"n":141,"t":"Onlar, hep sizi gözetleyip durular. Allah’tan size bir zafer gelince; sizinle beraber değil miydik? derler. Kafirlere zaferden bir pay düştüğü zaman da onlara; size üstünlük sağlayarak mü’minlerden korumadık mı? derler. Kıyamet günü aranızda hüküm vercek Allah’tır. Allah, mü’minlerin aleyhinde asla fırsat vermeyecektir."},{"n":142,"t":"Doğrusu münafıklar; Allah’a oyun etmek isterler. Oysa O, onların oyunlarını başlarına geçirir. Onlar namaza kalktıklarında tenbel tenbel kalkarlar. İnsanlara gösteriş yaparlar. Allah’ı pek az anarlar."},{"n":143,"t":"Ne onlarladırlar, ne de bunlarla. İkisi arasında bocalayıp dururlar. Allah’ ın saptırdığı kimseye yol bulamazsın."},{"n":144,"t":"Ey iman edenler; mü’minleri bırakıp da kafirleri dost edinmeyin. Allah’ın aleyhinize apaçık bir ferman vermesini mi istersiniz?"},{"n":145,"t":"Doğrusu münafıklar; cehennemin en alt tabakasındadırlar. Onlara yardımcı bulamazsın."},{"n":146,"t":"Ancak tevbe edenler, ıslah olanlar, Allah’a sarılanlar ve Allah için dinlerine bağlananlar müstenadır. Onlar, mü’minlerle beraberdirler. Allah, mü’minlere büyük bir mükafat vercektir."},{"n":147,"t":"Şükredip iman ederseniz; Allah, sizin niçin azab etsin? Allah Şakir ve Alim olandır."},{"n":148,"t":"Zulme uğrayanların ki başka; Allah çirkin sözün alenen söylenmesini sevmez. Allah Semi, Alim olandır."},{"n":149,"t":"Bir iyiliği açığa vurur veya gizler, yahut bir kötülüğü affederseniz; şüphesiz ki Allah; Afüvv ve Kadir olandır."},{"n":150,"t":"Doğrusu Allah’ı ve peygamberlerini inkar edenler, Allah ile peygamberlerinin arasını ayırmak isteyenler, bir kısmına inanır, bir kısmını da inkar ederiz, diyerek bu ikisinin arasında yol tutmak isteyenler;"},{"n":151,"t":"İşte onlar; gerçekten kafir olanlardır. Kafirlere alçaltıcı bir azab hazırlamışızdır."},{"n":152,"t":"Allah ve peygamberlerine iman edip onların birini diğerinden ayırmayanlara; işte onlara Allah mükafatlarını verecektir. Allah Gafur, Rahim olandır."},{"n":153,"t":"Kitab ehli senin kendilerine gökten bir kitab indirmeni isterler. Musa’ dan da bundan daha büyüğünü istemişlerdi. Ve; bize Allah’ı apaçık göster, demişlerdi. Zulümlerinden dolayı onları yıldırım çarpmıştı. Kendilerine bunca açık ayetler ve deliller geldikten sonra da buzağıya taptılar. Nihayet Biz, bunu affettik ve Musa’ya apaçık bir hüccet verdik."},{"n":154,"t":"Söz vermelerine karşılık Tur dağını üzerlerine kaldırdık. Ve onlara; Şehrin kapısından secde ederek girin, dedik. Cumartesileri aşırı gitmeyin, dedik. Onlardan ağır bir te’minat aldık."},{"n":155,"t":"Sözlerini bozmaları, Allah’ın ayetlerini inkar etmeleri, peygamberlerini haksız yere öldürmeleri, kalblerimiz perdelidir, demeleri yüzünden Allah, evet, inkarlarına karşılık onların kalblerini mühürledi, onun için bunların pek azı hariç inanmazlar."},{"n":156,"t":"Küfür etmeleri ve Meryem’e büyük iftirada bulunmalarından."},{"n":157,"t":"Ve Allah elçisi Meryem oğlu İsa Mesihi öldürdük, demelerinden. Oysa onu öldürmediler ve asmadılar. Ancak onlara (İsa’ya) benzer gösterildi. Onun hakkında ihtilafa düşerler. Ondan yana şüphe içindedirler. Bu husustaki bilgileri ancak zanna dayanmaktan ibarettir. Onu gerçekten öldürememişlerdir."},{"n":158,"t":"Bilakis Allah, onu kendi katına yükseltmiştir. Allah; Aziz’dir, Hakim’dir."},{"n":159,"t":"Kitab ehlinden hiç kimse yoktur ki; ölümünden önce ona inanacak olmasın. O da kıyamet günü aleyhlerinde şahid olacaktır."},{"n":160,"t":"Yahudi olanların zulümleri ve bir çok kimseleri Allah yolundan çevirmelerinden dolayı; kendilerine, helal kılınmış şeyleri yasakladık."},{"n":161,"t":"Kendilerine yasaklanan faizi almaları ve haksız yere insanların mallarını yemelerinden ötürü. Onların küfür içinde olanlarına elem verici bir azab hazırladık."},{"n":162,"t":"Fakat onlardan ilimde derinleşmiş olanlar ve mü’minler; sana indirilen kitaba ve senden önce indirilmiş olanlara inanırlar. Namaz kılanlara, zekat verenlere, Allah ve ahiret gününe inannalara elbette büyük bir mükafat vereceğiz."},{"n":163,"t":"Nuh’a, ondan sonra gelen peygamberlere, İbrahim’e, İsmail’e, İshak’a, Ya’kub’a ve torunlarına, İsa’ya, Eyyüb’a, Yunus’a, Harun’a ve Süleyman’a vahyettiğimiz gibi, şüphesiz sana da vahyettik. Davud’a da Zebur’u verdik."},{"n":164,"t":"Kıssalarını daha önce sana anlattığımız peygamberlerle, kıssasını sana anlatmadığımız peygamberlere de. Ve Allah Musa ile konuşmuştur."},{"n":165,"t":"Müjdeleyici ve uyarıcı peygamberler olarak. Ta ki peygamberler geldikten sonra insanların Allah’a karşı hüccetleri kalmasın. Allah; Aziz, Hakim olandır."},{"n":166,"t":"Lakin Allah, sana indirdiğine şahidlik eder. Onu bilerek indirmiştir. Melekler de şahidlik ederler. Esasen şahid olarak Allah yeter."},{"n":167,"t":"Muhakkak ki küfredip insanları Allah yolundan alıkoyanlar, derin bir sapıklığa düşmüşlerdir."},{"n":168,"t":"Muhakkak ki küfreden ve zulmedenleri Allah, bağışlayacak ve onları doğru yola iletecek değildir."},{"n":169,"t":"Ancak cehennem yoluna. Onlar orada temelli kalıcıdırlar. Bu ise Allah’a pek kolaydır."},{"n":170,"t":"Ey insanlar; Peygamber, size Rabbınızdan gerçekle geldi. Kendi yararınıza olarak hemen iman edin. Eğer küfür ederseniz; muhakkak ki göklerde ve yerde olanlar Allah’ındır. Allah; Alim, Hakim olandır."},{"n":171,"t":"Ey Ehl-i Kitab; dininizde taşkınlık etmeyin. Allah hakkında ancak gerçeği söyleyin. Meryem oğlu İsa Mesih; Allah’ın peygamberi, O’nun Meryem’e ulaştırdığı kelimesi ve kendinden bir ruhtur. Allah’a ve peygamberlerine iman edin. Allah üçtür, demeyin. Kendi yararınıza olarak bundan vazgeçin. Allah sadece bir tek ilahtır. Çocuğu olmaktan münezzehtir. Göklerde olanlar da, yerde olanlar da O’nundur. Vekil olarak Allah yeter."},{"n":172,"t":"Mesih, Allah’a kul olmaktan asla çekinmez. Gözde melekler de. Kim, O’na kulluktan çekinir ve büyüklük taslarsa; bilsin ki, O hepsini huzuruna toplayacaktır."},{"n":173,"t":"İman edip salih ameller işleyenlere gelince; onlara mükafatlarını ödeyecek ve daha fazlasını da ihsan edecektir. Kulluk etmekten çekinenleri ve büyüklük taslayanları elem verici bir azaba uğratacaktır. Onlar, kendilerine Allah’tan başka bir dost ve yardımcı bulamazlar."},{"n":174,"t":"Ey insanlar; Rabbınızdan size açık bir delil geldi ve size apaçık bir nur indirdik."},{"n":175,"t":"Allah’a iman edenleri ve O’na sarılanları; Allah rahmetine ve bol nimetine kavuşturacaktır. Onları, kendisine götüren doğru yola eriştirecektir."},{"n":176,"t":"Senden fetva isterler. De ki: Size babası ve çocuğu olmayanın mirası hakkında fetvayı Allah veriyor. Çocuğu olmayıp bir kız kardeşi bulunan erkek ölürse; bıraktığının yarısı kız kardeşine kalır. Fakat kız kardeşinin çocuğu yoksa; kendisi ona tamamen varis olur. Eğer iki kız kardeş kalmışsa; bıraktığının üçte ikisi onlaradır. Eğer erkekli kadınlı bir çok kardeşi varsa; erkeğe iki kadının hissesi kadar pay vardır. Şaşırasınız diye Allah, size açıklıyor. Allah; her şeyi hakkıyla bilendir."}],[{"n":1,"t":"Ey iman edenler; akidleri yerine getirin. Siz, ihramlı iken avlanmayı helal görmeksizin; size bildirilecekler müstesna, hayvanlar size helal kılınmıştır. Muhakkak ki Allah, dilediğini hükmeder."},{"n":2,"t":"Ey iman edenler; Allah’ın nişanelerine, haram olan aya, hediye olan kurbanlığa, gerdanlıklı hayvanlara ve Rabblarından nimet, rıza taleb ederek Beyt’ül Haram’a gelenlere hürmetsizlik etmeyin. İhramdan çıkınca avlanın. Sizi Mescid-i Haram’dan alıkoydukları için bir kavme olan kininiz, siz haddi aşmaya sürüklemesin. İyilik ve takva üzerinde yardımlaşın. Günah işlemek ve aşırı gitmek üzerinde yardımlaşmayın. Allah’tan sakının, muhakkak ki Allah’ın cezası şiddetlidir."},{"n":3,"t":"Ölü, kan, domuz eti, Allah’tan başkası adına boğazlananlar, boğularak, vurularak, yuvarlanarak veya sürüklenerek ölen, yırtıcı hayvan tarafından parçalananlar, canları çıkmadan evvel kestiğiniz müstesna, dikili taşlar üzerine kesilenler ve fal oklarıyla kısmet aramanız size haram kılınmıştır. Bunlar fasıklıktır. Bugün, küfredenler sizin dininizden ümitlerini kesmişlerdir. Öyleyse onlardan korkmayın da Ben’den korkun. Bugün, dininizi kemale erdirdim, üzerinize olan nimetimi tamamladım ve size din olarak İslamiyeti beğendim. Her kim ki açlıktan darda kalırsa günaha kaymaksızın (bunlardan yemeğe mecbur olursa) muhakkak ki, Allah Gafur’dur, Rahim’dir."},{"n":4,"t":"Sana, kendilerine neyin helal kılındığını soruyorlar. De ki: Size bütün iyi ve temizler helal kılındı. Allah’ın size öğrettiği ile alıştırıp öğrettiğiniz avcı hayvanların sizin için tuttuklarını yeyin ve üzerine Allah’ın adını anın. Ve Allah’tan sakının, muhakkak ki Allah; hesabı çabuk görendir."},{"n":5,"t":"Bugün, size, iyi ve temiz olanlar helal kılındı. Kitab verilmiş olanların yemeği size helaldir, sizin yemeğiniz de onlara helaldir. Mü’min kadınlardan iffetli olanlar ve sizden önce kitab verilenlerdenb iffetli kadınlar, zina etmeksizin, gizli dost tutmaksızın ve mehirlerini verdiğinizde size helaldir. Kim de imanı inkar ederse; yaptıkları boşa gitmiştir ve o, ahirette hüsrana uğrayanlardandır."},{"n":6,"t":"Ey iman edenler; namaza kalktığınız zaman; yüzlerinizi, dirseklerinize kadar ellerinizi yıkayın, başınıza meshedin ve topuklarınıza kadar ayaklarınızı da (yıkayın). Eğer cünüb iseniz; hemen temizlenin. Eğer hasta olmuşsanız veya seferde iseniz; yahut heladan gelmişseniz veya kadınlara yaklaşmış da su bulamamışsanız; temiz bir toprakla teyemmüm edin. Yüzlerinizi ve ellerinizi onunla meshedin. Allah, size zorluk vermek istemez. Lakin sizi temizlemek, üzerinizde olan nimetini tamamlamak ister ki şükredesiniz."},{"n":7,"t":"Ve Allah’ın üzerinizdeki nimetini; işittik, itaat ettik, dediğinizde sizi onunla bağlamış olduğu misakını anın. Allah’tan sakının. Muhakkak ki Allah; kalblerdekini bilir."},{"n":8,"t":"Ey iman edenler; adaleti gözeten şahidler olun. Ve bir topluluğa karşı olan kininiz sizi adaletsizliğe sürüklemesin. Adalet edin. Bu, takvaya daha yakındır. Ve Allah’tan korkun. Muhakkak ki Allah; işlediklerinizden haberdardır."},{"n":9,"t":"Allah; iman edenlere ve salih amel işleyenlere, mağfiret ve büyük bir ecir vaadetmiştir."},{"n":10,"t":"Küfür edenler ve ayetlerimizi tekzib edenler, işte onlar, cehennem yaranıdırlar."},{"n":11,"t":"Ey iman edenler; Allah’ın üzerinize olan nimetini hatırlayın. Hani bir kavim, size el uzatmağa kalkmıştı da, onların ellerini üzerinizden geri çekmişti. Allah’tan sakının. Ve mü’minler, Allah’a tevekkül etsinler."},{"n":12,"t":"And olsun ki, Allah İsrailoğullarından söz almıştı. Biz, onlardan oniki temsilci seçtik. Allah demişti ki: Muhakkak ki Ben, sizinleyim; namaz kılar, zekat verir, peygamberlerime inanır, onlara yardım ederseniz, Allah’a güzel bir borç verirseniz; andolsun ki sizin kötülüklerinizi örterim. Ve andolsun ki sizi, altlarından ırmaklar akan cennetlere koyarım. Bundan sonra sizden her kim de küfrederse; şüphesiz doğru yoldan sapmış olur."},{"n":13,"t":"Ahidlerini bozmalarından ötürü onlara la’net ettik, kalblerini de katılaştırdık. Onlar, kelimeleri yerlerinden değiştiriyorlar. Kendilerine öğretilenlerin bir kısmını unuttular. İçlerinden pek azı müstesna daima hainliklerini görürsün. Sen; onları affet ve geç. Muhakkak Allah; ihsan edenleri sever."},{"n":14,"t":"Biz, hristiyanız diyenlerden de söz aldık. Onlar da kendilerine öğretilenlerin bir kısmını unuttular. Bu yüzden kıyamete kadar aralarına kin ve düşmanlık saldık. Allah; yapmakta olduklarını kendilerine haber verecektir."},{"n":15,"t":"Ey Ehl-i Kitab; size peygamberimiz gelmiştir, kitabtan gizleyip durduğunuzun çoğunu size açıkça anlatır ve çoğundan da geçiverir. Gerçekten size Allah’tan bir nur ve apaçık bir kitab gelmiştir."},{"n":16,"t":"Allah onunla, rızasını gözetenleri selamet yollarına iletir. İzniyle onları karanlıklardan aydınlığa çıkarır ve doğru yola iletir."},{"n":17,"t":"Andolsun ki, Allah; ancak Meryem oğlu Mesih’tir, diyenler kafir olmuşlardır. De ki: Eğer, Meryem oğlu Mesih’i anasını ve yeryüzünde olanların hepsini helak etmek isterse; kim, Allah’a karşı koyabilir? Göklerin, yerin ve arasındakilerin mülkü Allah’ındır. Dilediğini yaratır. Ve Allah, her şeye Kadir’dir."},{"n":18,"t":"Yahudiler ve hristiyanlar dediler ki: Biz; Allah’ın oğulları ve sevgilileriyiz. De ki: Öyleyse günahınızdan dolayı size neden azab ediyor? Hayır, siz O’nun yarattığı insanlarsınız. Dilediğini bağışlar, dilediğine azab eder. Göklerin, yerin ve ikisi arasındakilerin mülkü Allah’ındır. Dönüş de O’nadır."},{"n":19,"t":"Ey Ehl-i Kitab, Peygamberlerin arası kesildiği bir dönemde, gerçekten size peygamberimiz gelmiştir. Gerçekleri açıklıyor ki; bize müjdeci ve uyarıcı gelmedi, demeyesiniz ve o, size gerçekten müjdeci ve uyarıcı olarak gelmiştir. Ve Allah; her şeye Kadir’dir."},{"n":20,"t":"Hani, Musa kavmine demişti ki: Ey kavmim; Allah’ın size olan nimetini hatırlayın. Hani sizden peygamberler yetiştirmiş ve size saltanatlar ihsan etmişti. Dünyalarda kimseye vermediğini size vermişti."},{"n":21,"t":"Ey kavmim; Allah’ın size yazdığı mukaddes yere girin ve ardınıza dönmeyin, yoksa hüsrana uğrayanlardan olursunuz."},{"n":22,"t":"Demişlerdi ki: Ey Musa; orada gerçekten zorba bir kavim var. Onlar oradan çıkmadıkça biz katiyyen oraya girmeyiz. Eğer oradan çıkarlarsa biz de gireriz."},{"n":23,"t":"Korkanlar arasında bulunan, Allah’ın nimetine erdirdiği iki adam demişlerdi ki: Onların üstlerine kapıdan yürüyün, oraya girerseniz; muhakkak siz, galiblersiniz. Şayet mü’minlerseniz; Allah’a tevekkül edin."},{"n":24,"t":"Demişlerdi ki: Ey Musa; onalr orada oldukça, ebediyyen oraya girmeyiz. Git, sen ve Rabbın savaşın. Biz, burada oturanlardanız."},{"n":25,"t":"Demişti ki: Rabbım; ben, ancak kendime ve kardeşime sahibim. Artık bizimle fasıklar güruhunun arasını ayır."},{"n":26,"t":"Buyurmuştur ki: Orası onlara kırk yıl haram edildi. Yeryüzünde şaşkın şaşkın dolaşacaklar. Artık sen fasıklar güruhu için tasalanma."},{"n":27,"t":"Onlara Adem’in iki oğlunun kıssasını doğru olarak anlat. Hani ikisi birer kurban sunmuşlardı da; birininki kabul edilmiş, diğerininki kabul edilmemişti. O: Andolsun seni öldüreceğim, deyince, (kardeşi): Allah, ancak müttakilerden kabul eder, demişti."},{"n":28,"t":"Beni öldürmek için elini bana uzatırsan; ben, seni öldürmek için elimi sana uzatmam. Muhakkak ki ben; alemlerin Rabbı olan Allah’tan korkarım."},{"n":29,"t":"Dilerim ki sen; benim günahımı da, kendi günahını da yüklenip cehennemliklerden olasın. Zalimlerin cezası da budur."},{"n":30,"t":"Bunun üzerine kardeşini öldürmekte nefsine uydu ve onu öldürdü de hüsrana uğrayanlardan oldu."},{"n":31,"t":"Sonra Allah; kardeşinin ölüsünü nasıl gömeceğini göstermek için, ona yeri eşeleyen bir karga gösterdi. Yazıklar olsun bana, bu karga gibi bile olmaktna aciz kaldım da kardeşimin ölüsünü örtemedim, dedi. Pişmanlık duyanlardan oldu."},{"n":32,"t":"Bundan dolayı İsrailoğullarının üzerine yazdık ki: Her kim, bir nefsi bir nefse veya yeryüzünde bozgunculuğa karşılık olmadan öldürürse, bütün insanları öldürmüş gibi olur. Kim de, onu diri bırakırsa sanki bütün insanları diriltmiş gibidir. Andolsun ki; onlara, peygamberlerimiz apaçık delillerle geldiler. Bundan sonra da onlardan bir çoğu gerçekten taşkınlık edenlerdir."},{"n":33,"t":"Allah ve Rasulü ile savaşanların ve yeryüzünde fesada koşanların cezası; ancak öldürülmek, asılmak, çaprazvari el ve ayakları kesilmek veya yerlerinden sürülmektir. Bu, onlara dünyada rüzvaylıktır. Onlara ahirette de büyük bir azab vardır."},{"n":34,"t":"Yalnız kendilerine gücünüz yetmeden önce tevbe edenler müstesnadır. Biliniz ki, Allah; Gafur’dur, Rahim’dir."},{"n":35,"t":"Ey iman edenler; Allah’tan korkun ve O’na yaklaşmak için vesile arayın. O’nun yolunda cihad edin ki, felaha eresiniz."},{"n":36,"t":"Muhakkak ki yeryüzündeki bütün şeyler ve onların bir katı daha kafirlerin olsa da kıyamet gününün azabından kurtulmak için onu fidye olarak verseler; onlardan kabul olunmaz ve onlara elim bir azab vardır."},{"n":37,"t":"Ateşten çıkmak isterler, ama oradan çıkacak değillerdir. Ve onlar için sürekli bir azab vardır."},{"n":38,"t":"Hırsız erkek ve hırsız kadının yaptıklarına karşılık Allah tarafından bir ceza olarak; ellerini kesin. Ve Allah; Aziz’dir, Hakim’dir."},{"n":39,"t":"Kim de zulmettikten sonra tevbe eder, düzelirse; muhakkak ki Allah, onun tevbesini kabul eder. Gerçekten Allah; Gafur’dur, Rahim’dir."},{"n":40,"t":"Bilmez misin ki, göklerin ve yeryüzünün mülkü Allah’ındır. Dilediğine azab eder, dilediğini bağışlar. Ve Allah; her şeye Kadir’dir."},{"n":41,"t":"Ey peygamber; ağızlarıyla inandık dedikleri halde kalbleriyle inanmayanlardan, yahudi olanlardan, yalan kulak verenler ve sana gelmeyen başka bir kavmin sözünü dnleyenlerden küfre koşanlar, sen, üzmesin. Sözlerin yerlerini değiştirirler de; size bu verilirse alın, verilmezse kaçının, derler. Allah, kimin de fitneye düşmesini isterse; onun için senin Allah’a karşı hiçbir şeye gücün yetmez. İşte onlar; Allah’ın kalblerini temizlemek istemediği kimselerdir. Dünyada rüsvaylık, onlaradır. Ve onlar için ahirette, büyük bir azab vardır."},{"n":42,"t":"Yalan kulak verici, haramı yiyicidirler. Sana gelirlerse; ister aralarında hükmet, ister onlardan yüz çevir. Eğer onlardan yüz çevirirsen; sana hiçbir zarar veremezler. Şayet hükmedersen de; aralarında adaletle hükmet. Çünkü Allah; adil olanları sever."},{"n":43,"t":"Nasıl seni hakem tayin ediyorlar? Halbuki Tevrat yanlarındadır. Onda Allah’ın hükmü vardır. Hem bundan sonra yüz çevirirler. Onlar inanıcı değillerdir."},{"n":44,"t":"Doğrusu Tevrat’ı Biz indirdik. Onda hidayet ve nur vardır. Kendilerini Allah’a teslim etmiş peygamberler, yahudi olanlara onunla, Rabb’a kul olanlarla bilginler de Allah’ın kitabından elde mahfuz kalanla hükmederlerdi. Ve ona şahid idiler. İnsanlardan korkmayın da Ben’den korkun. Ve ayetlerimi az bir değerle değiştirmeyin. Kim de Allah’In indirdiğiyle hükmetmezse, işte onlar, kafirlerin kendileridir."},{"n":45,"t":"Orada onlara yazdık ki: Muhakkak cana can, göze göz, buruna burun, kulağa kulak, dişe diştir. Yaralamalara kısas vardır. Kim de hakkından vazgeçerse; o, kendisi için keffarettir. Kim Allah’ın indirdiği ile hükmetmezse; işte onlar, zalimlerin kendileridir."},{"n":46,"t":"Ve onların izinden Meryem oğlu İsa’yı, önündeki Tevrat’ı doğrulayıcı olarak gönderdik. Ve ona İncil’i verdik. Onda hidayet ve nur vardır. Kendinden önceki Tevrat’ı doğrulayıcı, hidayet ve müttakiler için bir öğüt olarak."},{"n":47,"t":"İncil ehli, Allah’ın onda indirdikleri ile hükmetsinler. Kim de Allah’ın indirdiği ile hükmetmezse; işte onlar, fasıkların kendileridir."},{"n":48,"t":"Sana da; kendinden önceki kitabları doğrulayıcı ve üzerlerine şahid olarak bu kitabı hak ile indirdik. Aralarında Allah’ın indirdiği ile hükmet. Sana hak gelmişken onların heveslerine uyma. Sizden her biriniz için bir yol, bir şeriat kıldık. Şayet Allah dileseydi; sizi tek bir ümmet yapardı. Lakin sizi verdiği ile denemek istedi. Öyleyse hayırda yarışın. Hepinizin dönüşü Allah’a dır. Size ayrılığa düştüğünüz şeyleri bildirecektir."},{"n":49,"t":"Ve aralarında Allah’ın indirdiği ile hükmet. Onların heveslerine uyma. Seni Allah’ın sana indirdiğinden vazgeçirmelerinden sakın. Eğer yüz çevirirlerse; bil ki, bir kısım günahları yüzünden Allah onları cezalandırmak istiyor. Gerçekten insanların bir çoğu fasıklardır."},{"n":50,"t":"Cahiliyet hükmünü mü istiyorlar? Ama yakın getiren bir kavim için Allah’tan daha iyi hüküm veren kimdir?"},{"n":51,"t":"Ey iman edenler, yahudi ve hristiyanları dost edinmeyin. Onlar birbirlerinin dostudurlar. Sizden her kim ki, onları dost edinirse; o da, onlardandır. Şüphesiz ki Allah, zalimler güruhunu hidayete erdirmez."},{"n":52,"t":"Kalblerinde hastalık olanların; bize bir felaket gelmesinden korkuyoruz, diyerek onlara koşuştuklarını görürsün. Olur ki, Allah, fetih verir veya katından bir emir getirir de onlar, içlerinde gizlediklerinden dolayı pişman olurlar."},{"n":53,"t":"Aman edenler derler ki: Sizinle beraber olduklarına bütün güçleriyle Allah’a yemin edenler bunlar mıdır? Amelleri boşa gitmiş ve hüsrana uğrayanlardan olmuşlardır."},{"n":54,"t":"Ey iman edenler; içinizden her kim, dininden dönerse; Allah’ın sevdiği ve onların da O’nu sevdikleri, mü’minlere karşı alçak gönüllü, kafirlere karşı zorlu bir kavim getirir. Allah yolunda cihad ederler, hiç bir yerenin yermesinden korkmazlar. Bu, Allah’ın bir lütfudur. O’nu dilediğine verir. Allah; Vasi’dir, Alim’dir."},{"n":55,"t":"Sizin dostunuz yalnız Allah, O’nun Rasulü ve namaz kılan, zekat veren, rüku edenlerdir."},{"n":56,"t":"Her kim ki Allah’ı, peygamberini ve mü’minleri dost edinirse; muhakkak ki galig gelecek olanlar Allah’ın taraftarlarıdır."},{"n":57,"t":"Ey iman edenler; sizden önce kendilerine kitab verilenlerden dininizi alay ve eğlenceye alanları ve kafirleri dost edinmeyin. Eğer mü’min iseniz; Allah’tan korkun."},{"n":58,"t":"Birbirinizi namaza çağırdığınızda; onu alay ve eğlenceye alırlar. Bu, onların gerçekten kabul edemez bir topluluk olmalarındandır."},{"n":59,"t":"De ki: Ey Ehl-i Kitab; bizden hoşlanmayışınız, ancak Allah’a, bize indirilene ve daha önce indirilenlere inanmamızdan ve sizin bir çoğunuzun da fasık kimseler olmanızdandır."},{"n":60,"t":"De ki: Allah katında bundan daha kötü bir cezanın bulunduğunu size haber vereyim mi? O kimse ki; Allah ona la’net etmiş, aleyhine gazab etmiş ve onlardan maymunlar, domuzlar ve Tağut’a kullar kılmıştır. İşte onlar; yer bakımından en kötü ve doğru yoldan en çok sapmış olanlardır."},{"n":61,"t":"Size geldiklerinde; iman ettik, derler. Halbuki onlar, küfür ile girmişler ve onlar yine onunla çıkmışlardır. Ve Allah; gizlemekte olduklarını çok daha iyi bilir."},{"n":62,"t":"Onlardan bir çoğunu görürsün ki; günaha, haksızlığa ve haram yemeye koşuşurlar. İşledikleri şey; gerçekten ne kötüdür."},{"n":63,"t":"Rabb’a kul olanlar ve bilginler; onları günah söylemelerinden ve haram yemelerinden vazgeçirmeye çalışmalı değiller miydi? Yapmakta oldukları şey gerçekten ne kötü."},{"n":64,"t":"Yahudiler dediler ki: Allah’ın eli bağlıdır. Böyle dediklerinden ötürü kendi elleri bağlansın, la’net olsun. Hayır, O’nun iki eli de açıktır, nasıl dilerse öyle infak eder. Rabbından sana indirilen; andolsun ki, onlardan çoğunun azgınlığını ve küfürünü artıracaktır. Onların aralarına kıyamet gününe kadar sürecek kin ve nefret saldık. Savaş için ateşi ne zaman körükleseler; Allah, onu söndürür. Ve yeryüzünde fesada koşarlar. Allah, ise fesadçıları sevmez."},{"n":65,"t":"Eğer Ehl-i Kitab, iman edip de sakınsalardı; kötülüklerini örterdik ve onları Naim cennetlerine koyardık."},{"n":66,"t":"Eğer onlar; Tevrat’ı, İncil’i ve kendilerine Rabblarından indirilmiş olanı dosdoğru tutsalardı; muhakkak ki hem üstlerinden, hem de ayaklarının altlarından yiyeceklerdi. İçlerinden orta yolu tutan bir ümmet vardır. Onlardan bir çoğunun yapmakta oldukları şey ise ne kötüdür."},{"n":67,"t":"Ey Peygamber; Rabbından sana indirileni tebliğ et. Eğer yapmazsan; O’nun elçiliğini yapmamış olursun. Allah; seni insanlardan korur. Muhakkak ki Allah; kafirler güruhunu hidayete erdirmez."},{"n":68,"t":"De ki: Ey Ehl-i Kitab; Tevrat’ı, İncil’i ve Rabbınızdan size indirileni dosdoğru tatbik etmedikçe; hiç bir şey üzerinde değilsiniz. Andolsun ki; Rabbından sana indirilen; onlardan çoğunun azgınlık ve küfrünü artıracaktır. Öyleyse o kafirler güruhu için tasalanma."},{"n":69,"t":"Doğrusu; iman edenler, yahudi olanlar, sabiiler ve hristiyanlardan Allah’a ve ahiret gününe inananlara, salih amel işleyenlere; hiç korku yoktur. Ve onlar, üzülecek de değildir."},{"n":70,"t":"Andolsun ki; İsrailoğullarından ahd almış ve onlara peygamberler göndermişizdir. Ne zaman bir peygamber, onlara nefislerinin hoşlanmadığı bir şeyle gelmişse; bir kısmını yalanlamışlar, bir kısmını da öldürmüşlerdi."},{"n":71,"t":"Bir fitne olmayacağını sandılar da körleştiler, sağırlaştılar. Sonra Allah kendilerine tevbe nasib etti. Sonra yine içlerinden bir çoğu, körleştiler ve sağırlaştılar. Allah, işlediklerini hakkıyla görücüdür."},{"n":72,"t":"Meryem oğlu Mesih; gerçekten Allah’ın kendisidir, diyenler andolsun ki; kafir olmuşlardır. Halbuki Mesih demiştir ki: Ey İsrailoğulları; benim de Rabbım, sizin de Rabbınız olan Allah’a kulluk edin. Zira her kim ki, Allah’a şirk koşarsa; muhakkak Allah, ona cenneti haram eder ve onun varacağı yer, ateştir. Zalimlerin hiç yardımcıları yoktur."},{"n":73,"t":"Allah, gerçekten üçün üçüncüsüdür, diyenler andolsun ki; kafir olmuşlardır. Halbuki hiç bri tanrı yoktur, ancak bir tek tanrı vardır. Söylediklerinden vazgeçmezlerse; onlardan kafir olanlara acıklı bir azab dokunacaktır."},{"n":74,"t":"Hala Allah’a tevbe edip O’ndan mağfiret dilemezler mi? Halbuki Allah; Gafur’dur, Rahim’dir."},{"n":75,"t":"Meryem oğlu Mesih, Peygamberden başka bir şey değildir. Ondan önce de peygamberler geçmiştir. Annesi de dosdoğru bir kadındı. İkisi de yemek yerlerdi. Onlara ayetleri nasıl açıkladığımıza bak. Sonra da bak ki; nasıl yüz çeviriyorlar."},{"n":76,"t":"De ki: Allah’ı bırakıp da size ne bir zarar, ne de bir fayda veremeyecek birine mi ibadet ediyorsunuz? Halbuki Allah, Semi’, Ali olanın kendisidir."},{"n":77,"t":"De ki: Ey Ehl-i Kitab; dininizde haksız yere haddi aşmayın, daha önce hem kendi sapmış hem de birçoğunu saptırmış ve doğru yoldan ayrılmış bir kavmin heveslerine uymayın."},{"n":78,"t":"İsrailoğullarından küfredenler; Davud’un ve Meryem oğlu İsa’nın diliyle la’netlenmişlerdi. Bu; isyan etmeleri ve aşırı gitmelerindendi."},{"n":79,"t":"Birbirlerinin yaptıkları fenalıklara engel olmuyorlardı. Yapmakta oldukları ne kötü idi."},{"n":80,"t":"Görürsün ki; onlardan çoğu, küfredenleri dost edinmektedirler. Nefislerinin kendileri için öne sürdüğü, ne kötüdür. Allah onlara gazab etmiştir ve azabta ebedi kalıcıdırlar."},{"n":81,"t":"Şayet Allah’a, Peygambere ve ona indirilene iman etmiş olsalardı; onları dost edinmezlerdi. Ne var ki, onların çoğu fasıklardır."},{"n":82,"t":"Andolsun ki, insanlardan, iman edenlere en şiddetli düşman olarak, yahudileri ve Allah’a şirk koşanları bulacaksın. Andolsun ki, onlardan iman edenlere sevgide en yakını da; Biz hristiyanlarız, diyenleri bulacaksın. Bunun sebebi: Onların içinde keşişler ve rahibler bulunmasından ve onların gerçekten büyüklük taslamamalarındandır."},{"n":83,"t":"Peygambere indirileni işittiklerinde; hakkı tanıdıklarından dolayı gözleri yaşla dolup taşar da derler ki: Rabbımız; biz, iman ettik, bizi de şahidlerle beraber yaz."},{"n":84,"t":"Hem, Rabbımızın bizi salihler topluluğuyla beraber bulundurmasını umarken niçin Allah’a ve bize gelen hakikate iman etmeyelim."},{"n":85,"t":"Allah da onları dediklerinden dolayı; altlarından ırmaklar akan cennetlerle mükafatlandırdı. Orada temelli kalacaklardır. İşte ihsan edenlerin mükafatı budur."},{"n":86,"t":"Küfredip de ayetlerimizi yalanlayanlar, işte onlar, cehennem ashabıdırlar."},{"n":87,"t":"Ey iman edenler; Allah’ın size helal kıldığı iyi ve temiz şeyleri kendinize haram kılmayın ve haddi aşmayın. Doğrusu Allah, haddi aşanları sevmez."},{"n":88,"t":"Allah’ın size verdiği rızıktan helal ve temiz olarak yeyin. Sizin kendisine iman etmiş olduğunuz Allah’tan da korkun."},{"n":89,"t":"Allah size rasgele yeminlerinizden dolayı değil, bile bile ettiğiniz yeminlerden ötürü sorumlu tutar. Onun keffareti; ailenize yedirmekte olduğunuzun ortalamasından, on düşkünü yedirmek, yahut giydirmek veya bir köle azad etmektir. Kim de bunları bulamazsa; üç gün oruçtur. İşte bu, yemin ettiğiniz vakit yeminlerinizin keffaretidir. Yeminlerinizi tutun. Şükredersiniz diye Allah ayetlerini size işte böyle açıklar."},{"n":90,"t":"Ey iman edenler; içki, kumar, dikili taşlar ve fal okları; ancak şeytan işi pisliklerdir. Bunlardan kaçının ki, felaha eresiniz."},{"n":91,"t":"Şeytan; ancak içki ve kumar yüzünden aranıza düşmanlık ve kin sokmak ve sizi Allah’ı anmaktan ve namazdan alıkoymak ister. Artık vazgeçersiniz değil mi?"},{"n":92,"t":"Allah’a itaat edin, Rasule itaat edin ve sakının. Yüz çevirecek olursanız, bilinki; peygamberimize düşen, yalnız açıkça tebliğ etmektir."},{"n":93,"t":"İman edip salih amel işleyenler, sakınırlar, inanırlar ve salih amel işlerlerse; sonra sakınır ve ihsan ederlerse; daha önce tatmış olduklarından dolayı bir sorumluluk yoktur. Allah, ihsan edenleri sever."},{"n":94,"t":"Ey iman edenler; Allah, görmeksizin kendisinden korkanları ayırdetmek için; elinizin ve mızraklarınızın ulaştığı avdan bir şeyle sizi, mutlaka dener. Bundan sonra da her kim, haddi aşarsa; ona elem verici bir azab vardır."},{"n":95,"t":"Ey iman edenler; siz ihramlı iken avı öldürmeyin. Sizden her kim; bile bile onu öldürürse; öldürdüğü o hayvanın benzeri bir ceza vardır ki, Ka’be’ye ulaşmış bir kurbanlık olmak üzere, buna içinizden adil iki kişi hükmedecektir. Yahut düşkünlere yemek yedirmek şeklinde keffaret veya onun dengi oruç tutmaktır. Ta ki yaptığının vebalini tatmış olsun. Allah; geçmiştekileri affetmiştir. Kim de sonradan böyle yaparsa; Allah, ondan intikamını alır. Allah, Aziz’dir, İntikam sahibidir."},{"n":96,"t":"Deniz avı ve onu yemek; size de, yolculara da geçimlik olmak üzere helal kılınmıştır. İhramlı bulunduğunuz sürece, kara avı haram kılınmıştır. Hem, huzuruna varıp toplanacağınız Allah’tan korkun."},{"n":97,"t":"Allah Ka’be’yi, o haram evi insanlar için hayat ve güven kaynağı kıldı. Keza o haram olan ayı da, kurbanı da, boynu bağlı olan kurbanlıkları da. Bu, Allah’ın göklerde ve yerde olanları bildiğini ve Allah’ın gerçeten her şeyi bilici olduğunu bilmeniz içindir."},{"n":98,"t":"Bilin ki; Allah, gerçekten azabı pek çetin olandır. Ve Allah; gerçekten Gafur’dur, Rahim’dir."},{"n":99,"t":"Peygamberin vazifesi sadece tebliğdir. Allah; sizin açıkladıklarınızı da, gizlediklerinizi de bilir."},{"n":100,"t":"De ki: Murdarı çokluğu hoşunuza gitse de; murdarla temiz bir olmaz. Öyleyse ey akıl sahibleri; Allah’tan korkun ki kurtıuluşa eresiniz."},{"n":101,"t":"Ey iman edenler; size açıklanınca hoşunuza gitmeyecek olan şeyleri sormayın. Ku’ran indirilirken onları soracak olursanız, size açıklanır. Allah, bunları affetmiştir. Allah; Gafur’dur, Halim’dir."},{"n":102,"t":"Sizden önce bir kavim onları sormuştu da, sonra o sebeple kafirler olmuştu."},{"n":103,"t":"Allah; ne Bahire’den, ne Saibe’den, ne Vasile’den, ne de Ham’dan hiç birini meşru kılmamıştır. Fakat küfredenler; Allah’a karşı yalan uydurdular. Onların çoğunun ise akılları ermez."},{"n":104,"t":"Onlara; Allah’ın indirdiğine ve peygambere gelin, denildiği zaman; atalarımızı üstünde bulunduğumuz şey bize yeter, dediler. Ya ataları, bir şey bilmiyor ve doğru yola gitmiyorlar idiyse?"},{"n":105,"t":"Ey iman edenler; siz kendinize bakın. Siz doğru yolda bulunursanız; sapıtmış olanalr size zarar veremez. Hepinizin dönüşü Allah’a dır. Yapmış olduklarınızı O, size haber verecektir."},{"n":106,"t":"Ey iman edenler; herhangi birinize ölüm gelip çattığı zaman, vasiyet anında aranızda ya adalet sahibi iki kişiyi veya yolculuk ta başınıza ölüm musibeti gelmişse, sizden olmayan iki kişiyi şahid tutun. Onlardan şüpheleniyorsanız; namazdan sonra alıkoyarsınız da Allah’a şöyle yemin ederler; Akraba bile olsa yeminle hiç bir değeri değiştirmeyeceğiz, Allah’ın şahidliğini gizlemeyeceğiz, yoksa elbette günahkarlardan oluruz."},{"n":107,"t":"Şayet onların aleyhinde gerçekten bir vebale hak kazanmış oldukları ortaya çıkarsa; onların aleyhlerine hak iddia ettikleri iki kişi, bunların yerine geçer. Ve; bizim şehadetimiz onların şehadetinden daha doğrudur, biz haddi aşmadık, o takdirde biz, doğrusu zalimlerden oluruz, diye Allah’a yemin ederler."},{"n":108,"t":"Bu, şehadeti gereği gibi yapmalarına veya yeminden sonra yeminlerinin reddedileceğinden korkmalarına daha yakındır. Allah’tan korkun ve dinleyin. Allah fasıklar güruhunu hidayete erdirmez."},{"n":109,"t":"Allah, Rasulleri topladığı gün şöyle buyurur; Size ne cevab verildi? Onlar da: Bizim bir bildiğimiz yoktur, doğrusu gaybları bilen Sensin Sen, derler."},{"n":110,"t":"Hani Allah; Ey Meryem oğlu İsa; senin ve ananın üzerindeki nimetimi hatırla, demişti. Hani seni, Ruh’ül-Kudüs ile desteklemiştim. Beşikte iken de, yetişkin iken de insanlar la konuşuyordun. Hani sana; kitabı, hikmeti Tevrat’ı ve İncil’i öğretmiştim. Hani sen; Benim iznimle çamurdan kuş gibi bir şey yapıyordun da içine üflüyordun ve Benim iznimle kuş oluyordu. Hani sen; anadan doğma körü ve abraşı Benim iznimle iyi ediyordun. Hani; ölüleri Benim iznimle diriltiyordun. Ve hani, İsrailoğullarını senden çekmiştim, kendilerine apaçık ayetler getirdiğin zaman içlerinden küfredenler; bu apaçık bir büyüdür, demişti."},{"n":111,"t":"Hani Ben Havarilere: Bana ve peygamberime iman edin, diye vahyetmiştim de; inandık, şahid ol ki biz, müslümanlarız, demişlerdi."},{"n":112,"t":"Hani Havariler: Ey Meryem oğlu İsa; Rabbın bize gökten bir sofra indiribilir mi? demişlerdi de, O; eğer inanmışlarsanız Allah’tan korkun, demişti."},{"n":113,"t":"Demişlerdi ki: İstiyorsanız ki; ondan yiyelim, kalblerimiz yatışsın ve senin bize hakikaten doğru söylediğini bilelim de biz ona şahidlerden olalım."},{"n":114,"t":"Meryem oğlu İsa’da: Allahım; Rabbımız, üstümüze gökten bir sofra indir ki, bizim hem öncekilerimiz, hem sonrakilerimiz için bir bayram ve Senden bir ayet olsun. Bizi rızıklandır. Sen, rızık vernlerin en hayırlısısın, diye dua etmişti."},{"n":115,"t":"Allah buyudu ki: Ben, onu şühesiz indireceğim. Bundan sonra da artık içinizden her kim küfrederse; onu dünyalarda hiç kimseyi azablandırmayacağım azabla azablandırırım."},{"n":116,"t":"Allah buyurmuştu ki: Ey meryem oğlu İsa; sen mi insanlara: Beni ve annemi Allah’tan başka iki ilah edinin, dedin? Demişti ki: Tenzih ederim Seni, hak olmayan bir sözü söylemek bana yakışmaz. Eğer ben, onu söylemişsem; Sen, onu elbette bilirsin. Sen, benim içimde olanı bilirsin, ama ben Senin zatında olanı bilmem. Doğrusu görülmeyeni en iyi bilen Sensin, Sen."},{"n":117,"t":"Ben; onlara Senin bana buyuduğundan başkasını söylemedim. Rabbım ve Rabbınız olan Allah’a kulluk edin, dedim. Ben, aralarında bulunduğum sürece üzerlerine şahid idim. Beni öldürdüğünde onların murakıbı Sensin. Sen herşeye şahidsin."},{"n":118,"t":"Eğer onlara azab edersen; şüphesiz onlar Senin kullarındır. Şayet bağışlarsan; muhakkak ki Sensin Sen; Aziz, Hakim."},{"n":119,"t":"Allah buyurdu ki: Bu, doğru söyleyenlerin doğruluklarının fayda verdiği gündür. Onlara; altından ırmaklar akan, içinde temelli kalacakları cennetler vardır. Allah; onlardan hoşnud olmuştur, onlar da Allah’dan hoşnud olmuşlardır. Büyük kurtuluş işte budur."},{"n":120,"t":"Göklerin, yerin ve onlardaki her şeyin mülkü Allah’ındır. Ve O, her şeye Kadir’dir."}],[{"n":1,"t":"Hamd; gökleri ve yeri yaratan, karanlıkları ve aydınlığı vareden Allah’a mahsustur. Sonra da kafirler bunları rabblarına denk tutuyorlar."},{"n":2,"t":"O’dur; sizi, bir çamurdan yaratan. Sonra da size bir ecel tayin eden. Bir de O’nun katında belli bir ecel vardır. Siz hala şüphe edip durursunuz."},{"n":3,"t":"O; göklerde de, yerde de Allah’tır. Gizlinizi de aşikarınızı da bilir. Ne kazanacağınızı da bilir."},{"n":4,"t":"Rabblarının ayetlerinden bir ayet onlara gelmez ki; ondan yüzçevirmiş olmasınlar."},{"n":5,"t":"Onlar; kendilerine gelince, hakkı yalanladılar. Ama alaya aldıkları şeyin haberi onlara gelecektir."},{"n":6,"t":"Görmediler mi ki; Biz, onlardan önce nice nesilleri yok ettik. Biz, onları sizi yerleştirmediğimiz şekilde yer yüzüne yerleştirmiş, gökten bol yağmur yağdırmış ve altlarından ırmaklar akıtmıştık. Sonra onları günahlarından dolayı yok ettik. Ve aralarından başka bir nesil yetiştirdik."},{"n":7,"t":"Eğer sana kağıt içinde bir kitab indirmiş olsaydık da elleriyle ona dokunsalardı; yine de küfretmiş olanlar derlerdi ki: Bu, apaçık büyüden başkası değildir."},{"n":8,"t":"Ona bir melek indirmeli değil miydi? dediler. Eğer Biz, bir melek indirseydik; elbette iş bitirilmiş olurdu da sonra kendilerine göz bile açtırılmazdı."},{"n":9,"t":"Eğer Biz, onu bir melek kılsaydık; onu bir erkek yapardık da düştükleri şüpheye onları yine düşürürdük."},{"n":10,"t":"Andolsun ki; senden önce de peygamberlerle alay edilmişti. Onlarla eğlenenleri, alaya aldıkları şey çepeçevre kuşatıverdi."},{"n":11,"t":"De ki: Yeryüzünde gezip dolaşın da sonra bir görün, yalanlayanların sonu nice olmuştur?"},{"n":12,"t":"De ki: Göklerde ve yerde olanlar kimindir? Allah’ındır, de. O, rahmeti kendi üzerine yazmıştır. Andolsun ki; hepinizi, hakkında hiçbir şüphe olmayan kıyamet gününde toplayacaktır. Nefislerini ziyana uğratanlar, işte onlar inanmazlar."},{"n":13,"t":"Gecenin ve gündüzün içinde barınan her şey O’nundur. Ve O, Semi’dir, Alim’dir."},{"n":14,"t":"De ki: Ben Allah’tan başka bir dost mu edinirim? Gökleri ve yeri yoktan var eden O’dur. Ve O yedirir, ama yedirilmez. De ki: Doğrusu ben, müslüman olanların ilki olmakla emrolundum. Sakın müşriklerden olma."},{"n":15,"t":"De ki: Ben, Rabbıma karşı gelirsem, büyük günün azabından korkarım."},{"n":16,"t":"O gün, kim ondan döndürülürse; şüphesiz o, rahmete ermiştir. İşte apaçık kurtuluş budur."},{"n":17,"t":"Eğer Allah, sana bir sıkıntı dokundurursa; onu kendisinden başka giderecek hiçbir kimse yoktur. Şayet sana bir de hayır dokundurursa; işte O; her şeye Kadir’dir."},{"n":18,"t":"O; kullarının üstünde yegane mutasarrıftır. Ve O; Hakim’dir, Habir’dir."},{"n":19,"t":"De ki: Şahid olarak hangi şey daha büyüktür? De ki: Benimle sizin aranızda Allah şahiddir. Bu Kur’an; bana sizi de, ulaştığı kimseleri de, uyarmam için vahyolundu. Allah ile beraber başka tanrılar olduğuna siz mi şahidlik ediyorsunuz? De ki: Ben şehadet etmem. De ki: O, ancak bir tanrıdır. Ve ben, gerçekten sizin şirk koştuklarınızdan uzağım."},{"n":20,"t":"Kendilerine kitab verdiklerimiz; onu, öz oğullarını tanıdıkları gibi tanırlar. Nefislerini ziyana uğratanlar, işte onlar inanmazlar."},{"n":21,"t":"Allah’a karşı yalan uyduran ve ayetlerini yalan sayandan daha zalim kimdir? Muhakkak ki zalimler, felaha ermezler."},{"n":22,"t":"Ve onların hepsini toplayıp sonra da şirk koşanlara: Nerede iddia ettiğiniz ortaklarınız? diyeceğimiz gün."},{"n":23,"t":"Sonra onların sadece: Andolsun Allah’a ki, ey Rabbımız; bizler müşriklerden değildik, demelerinden başka çareleri kalmaz."},{"n":24,"t":"Bak, kendilerine nasıl yalan söylediler? Yalan yere uydurdukları kendilerinden nasıl kayboluverdi?"},{"n":25,"t":"İçlerinden seni dinleyenler vardır. Halbuki Biz, onu anlarlar diye, kalblerine örtüler, kulaklarına da ağrılık koyduk. Onlar her ayeti görseler de yine inanmazlar. Hatta sana geldiklerinde, seninle çekişirler. O küfredenler derler ki; Bu, eskilerin masallarından başka birşey değildir."},{"n":26,"t":"Onlar, hem bundan vazgeçirmeye çalışırlar, hem de kendileri ondan uzaklaşırlar. Onlar sadece kendilerini helake sürüklerler de farkına varmazlar."},{"n":27,"t":"Bir görsen; ateşin başında durdukları: Keşke geri döndürülseydik ve Rabbımızın ayetlerini yalan saymasaydık da mü’minlerden olsaydık, dedikleri zaman."},{"n":28,"t":"Hayır, öteden beri gizleyegeldikleri şeylerle karşılarına çıktık. Eğer geri döndürülselerdi yine kendilerine yasaklanan şeylere döneceklerdi. Doğrusu onlar, yalancılardır."},{"n":29,"t":"Ve dediler ki: Hayat ancak bu dünyadaki hayatımızdır. Ve biz dirilecek değiliz."},{"n":30,"t":"Bir görseydin eğer; Rabblarının huzurunda durdukları zaman, O: Bu, hak değil miymiş? deyince; onlar da: Rabbımız hakkı için evet, derler. Allah da buyurur ki: Öyleyse küfür edegeldiğinizden dolayı tadın azabı."},{"n":31,"t":"Allah’a kavuşmayı yalan sayanlar; gerçekten kaybetmişlerdir. Nihayet kıyamet ansızın gelip çattığı zaman; yüklerini sırtlarına yüklenerek: Orada yaptığımız eksiklerden dolayı yazıklar olsun bize, derler. Dikkat edin, ne kötüdür yüklendikleri şeyler."},{"n":32,"t":"Dünya hayatı; ancak oyun ve eğlenceden ibarettir. Ahiret yurdu ise; müttakiler için daha hayırlıdır. Hala aklınızı başınıza almayacak mısınız?"},{"n":33,"t":"Gerçekyen biliyoruz ki; söyledikleri söz, seni üzüyor. Onlar, hakikatte seni yalanlamıyorlar. Lakin o zalimler, Allah’ın ayetlerini inkar ediyorlar."},{"n":34,"t":"Andolsun ki; senden önce de nice peygamberler yalanlandı da yalanlanmalarına ve eziyyet edilmelerine sabrettiler. Nihayet onlara yardımımız gelip yetişti. Allah’ın kelimelerini değiştirebilecek yoktur. Andolsun ki; peygamberlerin haberinden bir kısmı sana gelmiştir."},{"n":35,"t":"Eğer onların yüz çevirmeleri sana ağır geliyorsa; yeri delmeğe ve göğe merdiven dayamaya gücün yetmiş olsaydı; onlara bir ayet gösterirdin. Şayet Allah dileseydi; onları hidayet üzerinde birleştirirdi. Sakın bilgisizlerden olma."},{"n":36,"t":"Ancak dnleyenler icabet ederler. Ölülere gelince; onları Allah diriltir. Sonra O’na döndürülürler."},{"n":37,"t":"Ve dediler ki: Ona Rabbından bir ayet indirilmeli değil miydi? De ki: Şüphesiz Allah, ayet indirmeye kadirdir. Ne var ki, onların çoğu bilmezler."},{"n":38,"t":"Yerde yürüyen hiçbir hayvan ve iki kanadıyla uçan hiçbir kuş yoktur ki; onlar da sizin gibi bir ümmet olmasınlar. Biz, kitabta hiçbir şeyi eksik bırakmadık. Sonra onlar Rabblarına toplanırlar."},{"n":39,"t":"Ayetlerimizi yalanlayanlar ise; karanlıklarda kalmış sağırlar, dilsizlerdir. Allah; kimi dilerse, onu şaşırtır. Kimi de dilerse; onu dosdoğru yol üstünde tutar."},{"n":40,"t":"De ki: Bana haber verir misiniz, eğer üzerinize Allah’ın azabı gelse veya size kıyamet gelirse; Allah’tan başkasını mı çağırırsınız? Eğer sadıklardan iseniz."},{"n":41,"t":"Hayır, ancak O’nu çağırırsınız da; isterse çağırdığınız şeyi giderir ve siz de şirk koştuğunuz eşleri unutursunuz."},{"n":42,"t":"Andolsun ki; Biz, senden önceki ümmetlere de peygamberler gönderdik. Yalvarsınlar diye, onları darlık ve sıkıntıya soktuk."},{"n":43,"t":"Onlar, hiç değilse kendilerine bir azabımız geldiği zaman; yalvarmalı değiller miydi? Fakat kalbleri katılaşmış, şeytan da onlara yaptıklarını süsleyip püslemişti."},{"n":44,"t":"Onlar, kendilerine hatırlatılan şeyleri unutunca; Biz de kendilerine her şeyin kapılarını açtık. Nihayet kendilerine verilen o şeyler yüzünden sevinince; onları, ansızın yakaladık ve bütün ümitlerinden mahrum kaldılar."},{"n":45,"t":"Ve böylece zulmedenler güruhunun kökü kesilmişti. Hamd, alemlerin Rabbı olan Allah’a mahsustur."},{"n":46,"t":"De ki: Bana haber verir misiniz; eğer Allah, kulağınızı, gözlerinizi alır ve kalblerinizin üstüne mühür vurursa; Allah’tan başka onları size getirecek ilah kimdir? Bak, ayetlerimizi nasıl açıklıyoruz da sonra onlar yüz çeviriyorlar."},{"n":47,"t":"De ki: Bana haber verir misiniz; Allah’ın azabı siz ansızın ve açıkça gelirse; zalimler güruhundan başka kimse helake uğratılmış olur mu?"},{"n":48,"t":"Biz, peygamberleri ancak müjdeci ve uyarıcı olarak göndeririz. Öyleyse her kim ki inanır ve ıslah ederse; artık onlar için korku yoktur. Ve onlar üzülecek de değillerdir."},{"n":49,"t":"Ayetlerimizi yalanlayanlara ise fasıklık eder olmalarından dolayı azab dokunacaktır."},{"n":50,"t":"De ki: Size, Allah’ın hazineleri benim yanımdadır, demiyorum. Ben, gaybı da bilmem. Ve size bir melek olduğumu da söylemiyorum. Ben; bana vahyolunandan başkasına uymam. De ki: Hiç görenle görmeyen bir olur mu? Hiç düşünmüyor musunuz?"},{"n":51,"t":"Rabblarına toplanacaklarından korkanları, sen onunla uyar. O’ndan başka bir dost ve şefaatçıları yoktur. Umulur ki sakınalar."},{"n":52,"t":"Sabah, akşam Rabblarına, rızasını dileyerek dua edenleri kovma. Onların hesabından sana bir şey yoktur, senin hesabından onlara bir şey yoktur ki onları kovasın da zalimlerden olasın."},{"n":53,"t":"Biz, böylece onların bir kısmını bir kısmıyla denedik ki: Aramızadan Allah bunlara mı lütfetti? desinler. Allah; şükredenleri daha iyi bilen değil midir?"},{"n":54,"t":"Ayetlerimize iman edenler, sana geldiklerinde de ki: Selam size. Rabbınız rahmeti kendi üzerine yazdı. İçinizden her kim ki bilmeyerek bir fenalık yapar da arkasından tevbe eder ve ıslah ederse; şüphesiz O; Gafur’dur, Rahim’dir."},{"n":55,"t":"Böylece ayetlerimizi açıklarız ki; suçluların yolu sana besbelli olsun."},{"n":56,"t":"De ki: Allah’ı bırakıp da taptığınız başka şeylere tapmaktan men’olundum. De ki: Sizin heveslerinize asla uymam. O takdirde sapmış olurum da hidayete erenlerden olmam."},{"n":57,"t":"De ki: Ben, şüphesiz Rabbımdan bir hüccet üzereyim. Siz ise onu yalanladınız. Sizin acale istediğiniz şey yanımda değildir. Hüküm; ancak Allah’ındır. Doğrusu O, hakkı verir ve O, ayırdedenlerin en hayırlısıdır."},{"n":58,"t":"De ki: Acele istediğiniz şey, benim yanımda olsaydı; benimle aranızdaki iş bitmiş olurdu. Allah; zalimleri çok iyi bilendir."},{"n":59,"t":"Gaybın anahtarları O’nun katındadır. O’ndan başka kimse bilmez. Karada ve denizde olanı da O bilir. Bir yaprak düşmez ki; onu bilmesin. Yerin karanlıkları içindeki tek bir tane, yaş ve kuru müstesna olmamak üzere her şey apaçık bir kitabtadır."},{"n":60,"t":"O’dur, geceleyin sizi kendinizden geçiren. Gündüzün de ne yaptığınızı bilir. Sonra sizi oraya geri dönderir ki, belirli bir ecelin hükmü yerine gelsin. Sonra sizin dönüşünüz O’nadır. Sonra da ne yaptığınızı size haber verecektir."},{"n":61,"t":"O, kulları üzerinde yegane hakimdir. Ve size, koruyucular yollar. Nihayet herhangi birinize ölüm gelince; elçilerimiz bir eksiklik yapmaksızın onun canını alırlar."},{"n":62,"t":"Sonra onlar, gerçek mevlalarına döndürülürler. Dikkat edin; hüküm O’nundur. Ve; O hesab görenlerin en sü’ratlisidir."},{"n":63,"t":"De ki: Karanın ve denizlerin karanlıklarından sizi, kim kurtarır? Siz, gizlice O’na yalvarır yakarırsınız. Bizi bundan kurtarırsa; andolsun şükredenlerden olacağız."},{"n":64,"t":"De ki: Allah kurtarır sizi ondan da, her sıkıntıdan da. Sonra da siz şirk koşarsınız."},{"n":65,"t":"De ki: Üstünüzden ve altınızdan size azab göndermeye, sizi fırka fırka yapıp kiminizin hıncını kimine tattırmaya Kadir olan O’dur. Bak; onlar iyice anlasınlar diye ayetlerimizi nasıl açıklıyoruz."},{"n":66,"t":"Kavmin onu yalanladı. Halbuki o, haktır. De ki: Ben, sizin üzerinize vekil değilim."},{"n":67,"t":"Her haberin kararlaşmış bir zamanı vardır. Siz de yakında bileceksiniz."},{"n":68,"t":"Ayetlerimizi çekişmeye dalanları gördüğün vakit; onlar başka bir söze geçinceye kadar, kendilerinden yüzçevir. Eğer şeytan sana unutturursa; hatırladıktan sonra, artık zalimler güruhu ile oturma."},{"n":69,"t":"Allah’tan sakınanlara; onların hesabından bir şey yoktur, fakat bir öğüttür. Olur ki, sakınırlar."},{"n":70,"t":"Bırak o dinlerini oyun ve eğlence edinenleri; dünya hayatının aldattığı kimseleri. Sen, onunla öğüy ver ki Allah’tan başka dostu ve şefaatçısı olmayan bir kimse; kazandığından ötürü yok olmasın. O, bütün varını fidye olarak verse de kabul olunmaz. İşte onlar, kazandıklarından ötürü yok olanlardır. Küfür edegeldiklerinden dolayı onlara, kaynar sudan içecek ve elim bir azab vardır."},{"n":71,"t":"De ki: Allah’ı bırakıp da bize fayda ve zarar veremeyen şeylere mi yalvaralım? Allah bizi hidayete erdirdikten sonra arkadaşları; bize gel, diye doğru yola çağırırken; şeytanların saptırıp şaşkın bir halde çöle düşürmek istedikleri kimse gibi ökçelerimizin üstünden gerisin geri mi dönelim? De ki: Allah’ın hidayeti, asıl hidayetin kendisidir. Ve biz; alemlerin Rabbına teslim olmakla emrolunduk."},{"n":72,"t":"Ve bir de namaz kılın ve O’ndan korkun diye. O’dur kendisine varıp toplanacağınız."},{"n":73,"t":"O’dur, gökleri ve yeri hak ile yaratan. O’nun; ol, dediği gün; hemen olur. O’nun sözü haktır. Sur’a üfleneceği gün de mülk O’nundur. Görülmeyeni de, görüleni de bilir. Ve O; Hakim’dir, Habir’dir."},{"n":74,"t":"Hani İbrahim, babası Azer’e demişti ki: Sen, putları tanrı mı ediniyorsun? Doğrusu ben, seni ve kavmini apaçık bir sapıklık içinde görüyorum."},{"n":75,"t":"İşte böylece yakınen bilenlerden olması için Biz, İbrahim’e göklerin ve yerin melekutunu gösteriyorduk."},{"n":76,"t":"Gece bastırınca; bir yıldız görmüş: Bu mu benim Rabbım? demiş. O, batınca da: Ben, batanları sevmem, demişti."},{"n":77,"t":"Sonra ayı doğarken görünce: Bu mu benim Rabbım? demiş. O da batınca: Eğer Rabbım beni hidayete erdirmeseydi; muhakkak sapanlar güruhundan olurdum, demişti."},{"n":78,"t":"Sonra güneşi doğarken görünce: Bu mu benim Rabbım? Bu daha büyük demiş. Ama batınca: Ey kavmim, ben sizin şirk koştuğunuz şeylerden uzağım, demişti."},{"n":79,"t":"Doğrusu ben, gerçekten yüzümü bir muvahhid olarak gökleri ve yeri yaratana çevirdim ve ben, müşriklerden değilim."},{"n":80,"t":"Kavmi, onunla tartoşmaya girişti. Demişti ki: Beni doğru yola iletmişken; Allah hakkında mı benimle tartışıyorsunuz? O’na şirk koştuklarınızdan korkmam. Meğer ki, Rabbım bir şey dilemiş olsun. Rabbım, ilimce herşeyi kuşatmıştır. Hala düşünüp öğüt almayacak mısınız?"},{"n":81,"t":"Hem siz; Allah’ın size hiçbir delil ve bürhan indirmediği şeyleri O’na şirk koşmaktan korkmazken; kendisine şirk koştuğunuz şeylerden ben nasıl korkarım? Şimdi, bu iki zümreden hangisi emin olmaya daha layıktır? Eğer biliyorsanız."},{"n":82,"t":"İman edenler, imanlarını zulüm ile bulaştırmayanlar, işte onlaradır emniyet. Ve işte onlar, hidayete ermiş olanlardır."},{"n":83,"t":"İşte bu, bizim hüccetimizdir. Onu kavmine karşı İbrahim’e verdik. Dilediğimizi derecelerle yükseltiriz. Ve muhakkak ki Rabbın; Hakim, Alim’dir."},{"n":84,"t":"Ve Biz, ona İshak’ı ve Ya’kub’u ihsan ettik. Her birini hidayete erdirdik. Daha önce de Nuh’u ve onun soyundan Davud’u, Süleyman’ı, Eyyub’u, Yusuf’u, Musa’yı ve Harun’u hidayete erdirdik. İşte böyle mükafaatlandırırız ihsan edenleri."},{"n":85,"t":"Zekeriyya’yı, Yahya’yı, İsa’yı ve İlyas’ı da. Hepsi salihlerdendir."},{"n":86,"t":"İsmail’i, el-Yesa’ı, Yunus’u ve Lüt’u da. Her birini alimlerden üstün kıldık."},{"n":87,"t":"Onların babalarından, zürriyetlerinden, kardeşlerinden kimini de. Onları seçtik ve onları dosdoğru yola ilettik."},{"n":88,"t":"İşte bu; Allah’ın, hidayetidir ki kullarından dilediğini onunla hidayete erdirir. Eğer onlar da şirk koşsalardı yapageldikleri şeyler boşa çıkardı."},{"n":89,"t":"Onlar; kendilerine kitab, hikmet ve peygamberlik verdiklerimizdir. Şimdi bunlar, onları tanımayıp da küfrederlerse; Biz, onu inkar etmeyen bir kavmi buna vekil kılmışızdır."},{"n":90,"t":"İşte bunlar; Allah’ın hidayet ettikleridir. Öyleyse sen de onların hidayetine uy. De ki: Ben bunlara karşı sizden hiçbir ücret istemem. Bu, ancak alemler için bir öğüttür."},{"n":91,"t":"Allah; hiçbir insana bir şey indirmedi, demekle; Allah’ı, şanına yaraşır şekilde tanıyamadılar. De ki: Musa’nın insanlara bir nur ve hidayet olmak üzere getirdiği ve sizin de parça parça kağıtlar haline koyup açıkladınız, çoğunu da gizlediğiniz o kitabı kim indirdi? Sizin de, atalarınızın da bilmediğiniz şeyler size öğretilmiştir. «Allah» de, sonra onları bırak da, daldıkları sapıklıkta oynayadursunlar."},{"n":92,"t":"Şehirlerin anası ile çevresindekileri uyarasın diye sana indirdiğimiz işte bu kitab, mübarektir. Ve kendisinden öncekileri doğrulayıcıdır. Ahirete inananlar buna da inanırlar. Ve onlar namazlarına da devam ederler."},{"n":93,"t":"Allah’a karşı yalan uydurandan, yahut kendisine hiçbir şey vahyedilmemişken; bana da vahyolundu, diyenden ve; Allah’ın indirdiği gibi ben de indireceğim, diyenden daha zalim kimdir? Bir görseydin; o zalimler can çekişirlerken melekler de ellerini uzatmış: Can verip bugün Allah’a karşı haksız yere söylediklerinizden ve O’nun ayetlerine büyüklük taslamanızdan ötürü horluk azabı ile cezalandırılacaksınız, derken."},{"n":94,"t":"Andolsun ki siz; ilk defa yarattığımız gibi, yapayalnız ve teker teker huzurumuza geldiniz. Ve size verdiğimiz şeyleri ardınızda bıraktınız. Hani, ortaklarınız olduğunu sandığınız şefaatçılarınızı da beraberinizde görmüyoruz. Andolsun ki; aranızdaki bağlar artık kopmuştur. Ortak sandıklarınız da sizden kaybolup gitmiştir."},{"n":95,"t":"Muhakkak ki Allah; taneyi ve çekirdeği yarandır. Ölüden diriyi çıkarır, diriden de ölüyü çıkarandır. İşte Allah budur. Nasıl olup da yüz çeviriyorsunuz?"},{"n":96,"t":"Sabahı yarıp çıkarandır. Geceyi bir sükun, güneşi ve ayı da vakit ölçüsü kılmıştır. İşte bu; Aziz, Alim olanın takdiridir."},{"n":97,"t":"O’dur, yıldızları yaratmış olan, karanın ve denizin karanlıklarında onlarla yol bulasınız diye. Ayetlerimizi bilen bir kavim için uzun uzadıya açıkladık."},{"n":98,"t":"Ve O’dur; sizi bir tek nefisten yaratmış olan. Sonra bir karar yeri, bir de emanet yeri vardır. Ayetlerimizi, anlayan bir kavim için uzun uzadıya açıkladık."},{"n":99,"t":"O’dur; gökten su indirmiş olan. Onunla her bitkiyi çıkardık. Ondan yeşillikler çıkardık. Ondan yığın yığın taneler, hurmaların tomurcuklarından sarkan salkımlar, birbirine hem benzeyen, hem benzemeyen üzümlerden, zeytinden ve nardan bahçeler yapıp çıkarıyoruz. Meyvesine; bir meyve verdikleri zaman, bir de olgunlaştıkları zaman bakın. Şüphesiz ki bunlarda; iman eden bir kavim için ayetler vardır."},{"n":100,"t":"Cinnleri, Allah’a ortak koştılar. Halbuki onları, O yaratmıştır. Bilmeden O’na oğullar ve kızlar uydurdular. Haşa O, onların vasıflandırdıklarından yüce ve münezzehtir."},{"n":101,"t":"Gökleri ve yeri yoktan varedendir. O’nun nasıl çocuğu olabilir? O’nun bir eşi de yoktur. Ve herşeyi O yaratmıştır. O, her şeyi en iyi bilendir."},{"n":102,"t":"İşte Rabbınız olan Allah, O’ndan başka hiçbir tanrı yoktur. Her şeyin yaratanıdır. Ve O, her şeye de Vekil’dir."},{"n":103,"t":"Gözler; O’na erişemez. O ise, bütün gözlere erişir. Ve O; Latif, Habir’dir."},{"n":104,"t":"Doğrusu size, Rabbınızdan basiretler gelmiştir. Kim, onları görürse; kendi lehine, kim de körlük ederse; kendi aleyhinedir. Ve ben, sizin üzerinize bir bekçi değilim."},{"n":105,"t":"İşte Biz, ayetleri sana böylece türlü türlü açıklarız. Ta ki onlar; sen okumuşsun, desinler ve Biz onu bilen bir kavme besbelli edelim."},{"n":106,"t":"Rabbından sana vahyolunana uy. O’ndan başka tanrı yoktur. Müşriklerden yüz çevir."},{"n":107,"t":"Eğer Allah dileseydi; onlar şirk koşmazlardı. Hem Biz, seni onların başına bir bekçi yapmadık. Sen, onların üzerine bir vekil de değilsin."},{"n":108,"t":"Allah’tan başka yalvardıklarına sövmeyin ki; onlar da bilmeyerek, haddi aşıp Allah’a sövmesinler. İşte böylece bir ümmete yaptıklarını hoş gösterdik. Sonra dönüşleri Rabblarınadır. Artık O, kendilerine ne yapmakta olduklarını haber verir."},{"n":109,"t":"Onlar, bütün güçleriyle Allah’a yemin ettiler ki; eğer kendilerine bir ayet gelirse mutlaka ona inanacaklar. De ki: Ayetler; ancak Allah’ın nezdindedir. O, geldiği zaman da onların yine inanmayacaklarının farkında değil misiniz?"},{"n":110,"t":"Biz, onların kalblerini ve gözlerini çeviririz de ona ilk defa iman etmedikleri gibi azgınlıkları içinde kör ve şaşkın bırakırız."},{"n":111,"t":"Eğer biz, onlara gerçekten melekleri indirseydik, ölüler kendileriyle konuşsaydı ve herşeyi karşılarına toplasaydık, Allah dilemedikçe, onlar yine de inanacak değillerdi. Fakat onların çoğu bilmezler."},{"n":112,"t":"İşte böylece Biz, her peygambere insan ve cinn şeytanlarını düşman yaptık. Onlardan kimi, kimini aldatmak için cazip sözler fısıldarlar. Eğer Rabbın dileseydi; bunu yapamazlardı. Öyleyse onları iftiraları ile başbaşa bırak."},{"n":113,"t":"Bir de ahirete inanmayanların kalbleri ona meyletsin, ondan hoşlansınlar ve işlesinler diye."},{"n":114,"t":"Allah’tan başka bir hakem mi arayacak mışım? Halbuki O’dur; size, kitabı açık açık indirmiş olan. Kendilerine kitab verdiklerimiz bilirler ki; o Rabbın katından hak olarak indirilmiştir. Öyleyse sakın şüpheye düşenlerden olma."},{"n":115,"t":"Rabbının sözü; doğruluk ve adalet yönünden tam kemalindedir. O’nun sözlerini değiştirebilecek yoktur. O; Semi’dir, Alim’dir."},{"n":116,"t":"Eğer sen, yeryüzünde bulunanların çoğunluğuna uyarsan; seni Allah’ın yolundan saptırırlar. Onlar, ancak zanna uyarlar ve yalnız yalan söyleyip dururlar."},{"n":117,"t":"Muhakkak ki Rabbın; yolundan sapanları en iyi bilendir. Ve O; hidayete ermiş olanları da en iyi bilendir."},{"n":118,"t":"Üzerine Allah’ın adı anılmış olanlardan yeyin, şayet O’nun ayetlerine inananlardan iseniz."},{"n":119,"t":"Size ne oluyor ki; üzerine Allah’ın adı anılan şeyden yemiyorsunuz? Halbuki darda kalmanızın dışında size haram olanları O, uzun uzadıya açıklamıştır. Doğrusu birçokları heva ve heveslerine uyarak bilmeden sapıtıyorlar. Şüphesiz ki haddi aşanları, en çok bilen Rabbındır."},{"n":120,"t":"Günahın açığını da, gizlisini de bırakın. Çünkü günah kazananlar; kazanmakta oldukları yüzünden cezalandırılacaklardır."},{"n":121,"t":"Üzerine Allah’ın adı anılmayanlardan yemeyin. Çünkü bu; bir fısktır. Doğrusu, şeytanlar sizinle mücadele etmeleri için kendi dostlarına telkinde bulunurlar. Şayet onlara itaat ederseniz; şüphesiz ki siz de müşrikler olursunuz."},{"n":122,"t":"Ölü iken dirilttiğimiz ve insanlar arasında yürüyebileceği bir nur verdiğimiz kimse; karanlıklarda kalıp ondan çıkamayan kimse gibi midir hiç? İşte böyle, kafirlere işledikleri süslü gösterilmiştir."},{"n":123,"t":"Ve böylece her kasabada hile yapsınlar diye oranın ileri gelenlerini suçlular kıldık. Halbuki yalnız kendilerine hile yaparlar da farkına varmazlar."},{"n":124,"t":"Onlara bir ayet geldiği zaman; derler ki: Allah’ın peygamberlerine verilen bize de verilmedikçe asla iman etmeyiz. Allah, risaletini nereye vereceğini en iyi bilendir. Suç işleyenlere; yapageldikleri hilekarlık yüzünden Allah katında bir horluk ve şiddetli bir azab erişecektir."},{"n":125,"t":"Allah, kimi hidayete erdirmek isterse; onun kalbini İslam’a açar. Kimi de saptırmak isterse; onu da göğe doğru yükseliyormuş gibi kalbini daraltır, sıkar. Allah; iman etmeyenlerin üstüne, işte böylece murdarlık çökertir."},{"n":126,"t":"Ve işte budur, Rabbının dosdoğru yolu. Gerçekten Biz, ayetleri; aklını başına alıp düşünen bir kavim için uzun uzadıya açıkladık."},{"n":127,"t":"Rabbları katında selamet yurdu onlara aittir. İşlediklerinden ötürü Allah, onların dostudur."},{"n":128,"t":"O gün, onların hepsini toplar. Ey cinn topluluğu; insanlardan bir çoğunu yoldan çıkardınız ha? Onların dostları olan insanlar da diyecek ki: Rabbımız, kimimiz kimimizden faydalandık. Ve bizim için takdir ettiğin ecelimize ulaştık. Buyurur ki: Allah’ın diledikleri müstesna, devamlı kalmak üzere duracağınız yer, ateştir. Muhakkak ki Rabbın; Hakim’dir, Alim’dir."},{"n":129,"t":"İşte böylece zalimlerden kimini kimine kazandıklarından ötürü musallat ederiz."},{"n":130,"t":"Ey cinn ve insan topluluğu; içinizden size ayetlerimi anlatan, bu gününüzün gelip çatmasından sizi uyaran peygamberler gelmedi mi? Derler ki; Ey Rabbımız, kendi hakkımızda şahidiz. Dünya hayatı onları aldattı da gerçek küfredenler olduklarına kendi aleyhlerinde şahidlik ettiler."},{"n":131,"t":"Bu; Rabbının, haberleri yokken, kasabalar halkını haksız yere helak edici olmadığından dolayıdır."},{"n":132,"t":"Her birinin işlediklerine karşılık dereceleri vardı. Ve Rabbın onların işlediklerinden gafil değildir."},{"n":133,"t":"Rabbın müstağni ve rahmet sahibidir. İsterse, sizi giderir ve arkanızdan yerinize dilediğini getirir. Nitekim sizi de başka bir kavmin soyundan getirmiştir."},{"n":134,"t":"Muhakkak size vaad olunan; yerine gelecektir. Siz, O’nu aciz kılacaklar değilsiniz."},{"n":135,"t":"De ki: Ey kavmim; elinizden geleni yapın, doğrusu ben de yapacağım. Dünya evinin sonunun kimin olacağını bileceksiniz. Şurası muhakkak ki zalimler; felah bulmazlar."},{"n":136,"t":"Onlar; Allah için, O’nun yarattığı ekin ve davarlardan bir pay ayırdılar ve kendi zanlarına göre; bu, Allah’ındır, bu da koştuğumuz ortaklarımızındır, dediler. Ortaklarına ait olanlar Allah’a ulaşamaz dı da, Allah’a ait olanlar ortaklarına giderdi. Ne kötüdür hükmedegeldikleri şeyler."},{"n":137,"t":"Ve böylece onların ortakları; ortak koşanlardan bir çoğunu helake sürüklemek, dinlerini karmakarışık etmek için; çocuklarını öldürmelerini hoş göstermiştir. Şayet Allah, dilemiş olsaydı; bunu yapamazlardı. Artık sen, onları uydurdukları o yalanları ile başbaşa bırak."},{"n":138,"t":"Onlar kendi zanlarınca; bu davarlar, bu ekinler haramdır, onları diledimizden başkası yiyemez. Bir takım hayvanların sırtları haramdır, dediler. Bir kısım hayvanların üzerine de O’na karşı iftira ederek; Allah’ın adını anmazlar. Allah; yapmakta oldukları iftiraları yüzünden onları cezalandıracaktır."},{"n":139,"t":"Bir de dediler ki: Şu davarların karınlarında bulunanlar, yalnız erkeklerimiz içindir, kadınlarımıza haram kılınmıştır. Ölü doğacak olursa; hepsi ona ortaktırlar. Allah, onların bu vasıflandırmalarının cezasını verecektir. Muhakkak ki O; Hakim’dir, Alim’dir."},{"n":140,"t":"Bilgisizlikleri yüzünden; çocuklarını beyinsizce öldürenler ve Allah’ın kendilerine verdiği rızkı Allah’a iftira ederek haram sayanlar; gerçekten hüsrana uğramuşlardır. Onlar; şüphesiz sapıtmışlardır. Zaten hidayete erenlerden olmamışlardı."},{"n":141,"t":"Çardaklı ve çardaksız bağları, tatları değişik ekin ve hrumaları, zeytin ve narı, birbirine benzer ve benzemez şekilde yaratıp yetiştirmiş olan O’dur. Her biri mahsul verdiği zaman, mahsulünden yeyin, hasad edildiği gün de, hakkını verin ve israf etmeyin. Çünkü O; israf edenleri sevmez."},{"n":142,"t":"Hayvanları da yük taşıyacak ve kesim hayvanı olarak yaratan O’dur. Allah’ın size verdiği rızıktan yeyin. Şeytanın izlerinden gitmeyin. Çünkü o, sizin apaçık bir düşmanınızdır."},{"n":143,"t":"Sekiz çift; koyundan iki, keçiden iki. De ki: İki erkeği mi, iki dişiyi mi veya iki dişinin rahimlerinde bulunanları mı haram kıldı? Eğer sadıklardan iseniz; bana bilgiye dayanarak haber verin."},{"n":144,"t":"Deveden de iki, sığırdan da iki. De ki: İki erkeği mi, iki dişiyi mi veya iki dişinin rahimlerinde bulunanı mı haram kıldı? Yoksa Allah; size bunları buyururken, siz orada mı idiniz? İnsanları bilgisizce saptırmak için Allah’a karşı yalan uyduranlardan daha zalim kimdir? Muhakkak ki Allah; zalimler güruhunu hidayete erdirmez."},{"n":145,"t":"De ki: Bana vahyolunanlar arasında; haram dediklerinizi yiyecek kişiye murdar oldukları için; ölüden, dökülen kandan, domuz etinden -ki pistirve Allah’tan başkasının adına kesildişğinden dolayı fısk olandan başka haram olan bir şey bulamıyorum. İstememek ve haddi aşmamak üzere, kim de bunlardan yemeye mecbur kalırsa; muhakkak ki Rabbın, Gafur’dur, Rahim’dir."},{"n":146,"t":"Yahudi olanlara da bütün tırnaklıları haram kıldık. Sığır ve koyunun iç yağlarını da üzerlerine haram kıldık. Bunlardan sırtlarına ve bağırsaklarına yapışan ve kemiğe karışan müstesnadır. Biz, onları zulümlerinden dolayı cezaya çarptırdık. Biz, elbette sadıklarızdır."},{"n":147,"t":"Seni yalanlarlarsa; de ki: Rabbımız geniş rahmet sahibidir. O’nun gücü günahkarlar güruhundan döndürülemez."},{"n":148,"t":"Şirk koşanlar diyecekler ki: Eğer Allah dileseydi; biz de, atalarımız da şirk koşmazdık. Hiçbir şeyi haram da kılmazdık. Onlardan öncekiler de, Bizim gücümüzü tadana kadar böyle dediler. De ki: Bize karşı yanınızda ortaya koyabileceğiniz bir bilgi var mı? Siz, ancak zanna uyuyorsunuz ve siz, sadece yalanlar atıyorsunuz."},{"n":149,"t":"De ki: Üstün ve mükemmel hüccet Allah’ındır. Eğer O, dileseydi hepinizi birden hidayete kavuştururdu."},{"n":150,"t":"De ki: Muhakkak Allah, şunu haram kıldı diye, bildiğini söyleyecek şahidlerinizi getirin. Eğer onlar şahidlik ederlerse; sende onlarla beraber olup tasdik etme. Onlar Rabblarına başkalarını denk tutuyorlar."},{"n":151,"t":"De ki: Gelin, Rabbınızın size neleri haram kıldığını ben söyleyeyim; O’na hiçbir şeyi ortak koşmayın, anaya-babaya iyilik edin. Fakirlik korkusuyla çocuklarınızı öldürmeyin. Sizin de onların da rızkını veren Biziz. Kötülüğün gizlisine de, açığına da yaklaşmayın. Hak ile olmadıkça, Allah’ın haram kıldığı bir cana kıymayın. İşte aklınızı başınıza alasınız diye size, bunları emretti."},{"n":152,"t":"Yetimin malına; erginlik çağına gelinceye kadar o en güzel olanından başka bir şekilde yaklaşmayın. Ölçüyü, tartıyı da tam ve doğru yapın. Biz kimseye, gücünün yettiğinden başkasını yüklemeyiz. Söylediğiniz zaman da -akraba dahi olsa-adil olun. Allah’ın ahdini de yerine getirin. İşte iyice düşünesiniz diye size bunları emretti."},{"n":153,"t":"Ve şüphesiz ki bu; Benim dosdoğru yolumdur. Ona hemen uyun. Başka yollara uymayın ki; sonra sizi O’nun yolundan ayırır. İşte, sakınasınız diye size bunları emretti."},{"n":154,"t":"Sonra Biz, Musa’ya bir bütün halinde, her şeyi apaçık göstermek, hidayet ve rahmet olmak üzere o kitabı verdik. Belki Rabblarına kavuşacaklarına artık inanırlar."},{"n":155,"t":"İşte şu da indirdiğimiz kitabdır, mübarektir. Öyleyse ona uyun ve sakının ki merhamet olunasınız."},{"n":156,"t":"Demeyesiniz ki: Bizden önce kitab, yalnız iki topluluğa indi. Bizim ise onlarınkinden hiç haberimiz yok."},{"n":157,"t":"Veya demeyesiniz ki: Bize de o kitab indirilseydi; muhakkak ki onlardan daha fazla hidayete ererdik. İşte size, Rabbınızdan apaçık hüccet, hidayet ve rahmet gelmiştir. Artık Allah’ın ayetlerini yalanlayandan ve onlardan yüzçevirenden daha zalim kimdir? Biz, ayetlerimizden yüzçevirenleri bu yüzden azabın kötüsüyle cezalandıracağız."},{"n":158,"t":"Onlar; hala kendilerine meleklerin gelmesini, yahut Rabbının gelmesini veya Rabbının ayetlerinden birinin gelmesini mi bekliyorlar? Rabbının ayetleri geldiği gün; kişi daha önceden inanmamış veya imanından bir hayır kazanmamışsa; imanı, ona hiç fayda vermez. De ki: Bekleyin, doğrusu biz de bekleyenlerdeniz."},{"n":159,"t":"Dinlerini parça parça edenler, bölük bölük olanlar yok mu? Senin onlarla hiçbir alakan yoktur. Onların işi Allah’a kalmıştır. Sonra O, ne yapmakta idiklerini kendilerine haber verecektir."},{"n":160,"t":"Kim, bir iyilikle gelirse; ona, onun on katı vardır. Kim de bir kötülükle gelirse; o, ancak misliyle cezalandırılır. Ve onlara haksızlık edilmez."},{"n":161,"t":"De ki: Şüphesiz Rabbım, beni dosdoğru yola iletti. Hanif olan İbrahim’in dinine. Ve o, müşriklerden olmadı."},{"n":162,"t":"De ki: Muhakkak benim namazım, ibadetlerim, hayatım ve ölümüm alemlerin Rabbı olan Allah içindir."},{"n":163,"t":"O’nun hiçbir ortağı yoktur. Ben, böylece emrolundum. Ve ben, müslümanların ilki."},{"n":164,"t":"De ki: Ben, Allah’tan başka bir Rabb mı arayacağım? Halbuki O; herşeyin Rabbıdır. Herkes ne kazanırsa kendine aittir. Yük yüklenen kimse, başkasının yükünü taşımaz. Sonunda dönüşünüz Rabbınızadır. Artık O; size ayrılığa düştüğünüz şeyleri haber verecektir."},{"n":165,"t":"Sizi, verdikleriyle denemek için yeryüzünün halifeleri yapan ve kiminizi kiminize derecelerle üstün kılan O’dur. Şüphe yok ki O; Gafur, Rahim’dir."}],[{"n":1,"t":"Elif, Lam, Mim, Sad."},{"n":2,"t":"Bir kitab indirilmiştir sana. Ondan dolayı göğsünde bir sıkıntı olmasın. Onunla uyarman için. Ve iman edenlere bir öğüt."},{"n":3,"t":"Rabbınızdan size indirilene uyun. O’ndan başka dostlara uymayın. Ne de az öğüt dinliyorsunuz."},{"n":4,"t":"Nice kasabalar vardır ki; Biz, onları helak etmişizdir. Geceleyin uyurken, öğleyin dinlenirken, baskınımız gelip çattı onlara."},{"n":5,"t":"Baskınımız geldiği zaman, çağırışları: Biz gerçekten zalimlerdendik, demekten başka birşey olmadı."},{"n":6,"t":"Andolsun ki; kendilerine peygamber gönderilmiş olanlara da soracağız, peygamber olarak gönderilenlere de."},{"n":7,"t":"Andolsun ki; onlara bilerek anlatacağız, zaten gaibler de değildik."},{"n":8,"t":"Tartı, o gün haktır. Kimin terazisi ağır basarsa; işte onlar, felaha erenlerin kendileridir."},{"n":9,"t":"Kimin de tartısı hafif gelirse; işte onlar da ayetlerimize zulmeder oldukları için kendilerini ziyana uğratmış olanlardır."},{"n":10,"t":"Andolsun ki; sizi, yeryüzüne yerleştirdik. Ve size orada geçimlikler yarattık. Ne de az şükrediyorsunuz."},{"n":11,"t":"Andolsun ki; sizi yarattık, sonra size şekil verdik, sonra da meleklere dedik ki: Adem’e secde edin. Hemen secde ettiler. Ancak İblis müstesna. O, secde edenlerden olmadı."},{"n":12,"t":"Buyurdu ki: Sana emretmişken secdeden seni alıkoyan nedir? Dedi ki: Ben ondan daha hayırlıyım; beni ateşten yarattın, onu ise çamurdan yarattın."},{"n":13,"t":"Buyurdu ki: Öyle ise: İn oradan, artık büyüklenmek sana düşmez. Hemen çık sen alçaklardansın."},{"n":14,"t":"Dedi ki: Bana, onların tekrar dirilecekleri güne kadar mühlet ver."},{"n":15,"t":"Buyudu ki: Sen mühlet verilmişlerdensin."},{"n":16,"t":"Dedi ki: Öyleyse beni azgınlığa mahkum ettiğin için ben de andolsun ki; Senin dosdoğru yolun üzerinde onlara karşı duracağım."},{"n":17,"t":"Sonra andolsun ki; onların önlerinden, arkalarından, sağlarından ve sollarından geleceğim. Ve Sen, onların çoğunu şükreder bulmayacaksın."},{"n":18,"t":"Buyudu ki: Çık oradan, alçak ve kovulmuş olarak. Andolsun ki; onlardan kim, sana tabi olursa; cehennemi bütün sizden dolduracağım."},{"n":19,"t":"Ey Adem; sen ve eşin cennette oturun. İkiniz de dilediğiniz yerden yeyin. Şu ağaca yaklaşmayın, sonra zalimlerden olursunuz."},{"n":20,"t":"Derken şeytan ayıp yerlerini kendilerine göstermek için ikinize de vesvese verdi ve dedi ki: Rabbınız, sizi başka bir şey için değil, ancak iki melek veya ebedi kalanlardan olmanızı önlemek için yasaklamıştır."},{"n":21,"t":"Ve; doğrusu ben size öğüt verenlerdenim, diye ikisine yemin etti."},{"n":22,"t":"Böylece onların ikisini de baştan çıkarıp aldattı. Ağaçtan tadınca ayıp yerleri kendilerine göründü. İkisi de kendilerini cennetin yaprağıyla örtmeye başladılar. Rabbları da onlara: Ben sizi o ağaçtan men’etmedim mi? Ve şeytan size apaçık bir düşmandır, demedim mi? diye nida etti."},{"n":23,"t":"İkisi dediler ki: Rabbımız; kendimize zulmettik. Eğer bizi bağışlamazsan ve bize merhamet etmezsen; muhakkak ki biz, hüsrana uğrayanlardan oluruz."},{"n":24,"t":"Buyurdu ki: Kimimiz kiminize düşman olarak inin. Sizin için yeryüzünde bir müddet yerleşip kalmak ve geçinmek vardır."},{"n":25,"t":"Buyurdu ki: Orada yaşar, orada ölür ve oradan çıkarılırsınız."},{"n":26,"t":"Ey ademoğulları; size çirkin yerlerinizi örtecek bir giyimlikle, bir de sizi süsleyecek elbise gönderdik. Takva örtüsü ise daha hayırlıdır. Bunlar; Allah’ın ayetlerindendir. Belki onlar öğüt alırlar."},{"n":27,"t":"Ey ademoğulları, şeytan, ana ve babanızı ayıp yerlerini kendilerine göstermek için elbiselerini soyarak nasıl cennetten çıkardıysa; sakın size de bir fitne yapmasın. O da, taraftarları da sizin onları görmediğiniz yerden sizi görürler. Biz, şeytanı; iman etmeyenlerin velileri yaptık."},{"n":28,"t":"Onlar; bir hayasızlık yaptıkları zaman: Biz atalarımızı da onun üzerinde bulduk. Allah da bize onu emretti, dediler. De ki: Allah; hiçbir zaman hayasızlığı emretmez. Siz, bilmediğiniz şeyi Allah’a karşı mı söylüyorsunuz?"},{"n":29,"t":"De ki: Rabbım, adaleti emretti. Her secde yerinde yüzlerinizi ona doğrultun. Ve dinde ancak kendisine muhlisler olarak yalvarın. İlk önce sizi yarattığı gibi, yine O’na döndürüleceksiniz."},{"n":30,"t":"Bir kısmını hidayete erdirdi, bir kısmına da sapıklık hak oldu. Çünkü onlar; Allah’ı bırakıp şeytanları kendilerine dostlar edindiler. Ve onlar; kendilerinin doğru yolda olduklarını sanıyorlardı."},{"n":31,"t":"Ey ademoğulları; her mescide güzel elbiselerinizi giyinerek gidin; yeyin için ama israf etmeyin. Çünkü O; israf edenleri sevmez."},{"n":32,"t":"De ki: Allah’ın kulları için çıkardığı zineti ve temiz rızıkları kim haram kılmış? De ki: Bunlar, dünya hayatında iman edenler içindir. Kıyamet günü ise yalnız onlara tahsis edilmiştir. Biz, ayetlerimizi bilen bir kavim için böylece uzun uzun açıklarız."},{"n":33,"t":"De ki: Rabbım, açığıyla, gizlisiyle tüm hayasızlıkları, günahı, Allah’a şirk koşmanızı ve Allah’a karşı bilmediğiniz şeyleri söylemenizi haram kılmıştır."},{"n":34,"t":"Her ümmetin bir eceli vardır. Ecelleri gelince; ne bir an geri kalır, ne de bir an ileri gidebilirler."},{"n":35,"t":"Ey ademoğulları; içinizden size ayetlerimizi anlatan peygamberler gelince, her kim ki sakınıp düzelirse; artık onlar için bir korku yoktur ve onlar üzülecek de değillerdir."},{"n":36,"t":"Ayetlerimizi yalanlayıp onlara karşı büyüklük taslayanlar; işte onlar ateşliklerdir. Onlar orada temelli kalıcıdırlar."},{"n":37,"t":"Allah’a karşı yalan uyduran veya O’nun ayetlerini yalan sayanlardan daha zalim kim vardır? İşte onlara; kitabdaki payları erişecektir. Nihayet, elçilerimiz canlarını almak üzere onlara geldiklerinde; diyeceklerdir ki: Allah’tan başka tapar olduklarınız nerede? Onlar da derler ki: Onlar, bizi bırakıp kaçtılar. Ve onlar, kendi aleyhlerine gerçekten kafir olduklarına şehadet ederler."},{"n":38,"t":"Buyurdu ki: Sizden önce geçmiş cinn ve insan topluluklarıyla girin ateşe. Her ümmet girdikçe; yoldaşına la’net eder. Nihayet hepsi birbiri ardından orada toplanınca; sonrakiler öncekiler için derler ki: Rabbımız; işte bizi bunlar saptırdı. Onun için bunlara katmerli azab ver. Buyurur ki: Hepiniz Evet, dediler. Bunun üzerine aralarında bir münadi: Allah’ın la’neti; zalimlerin üzerinedir, diye seslendi."},{"n":39,"t":"Öncekiler de sonrakilere: Sizin bizden bir üstünlüğünüz yoktur. Öyleyse ne kazandıysanız karşılığı olan azabı tadın, derler."},{"n":40,"t":"Muhakkak ki ayetlerimizi yalan sayıp onlara karşı büyüklük taslayanlara; işte onlara, göğün kapıları açılmaz ve onlar; deve iğne deliğinden geçinceye kadar cennete de giremezler. Biz, suçluları işte böyle cezalandırırız."},{"n":41,"t":"Onlar için cehennemde bir döşek ve üstlerine de örtüler vardır. Biz, zalimleri işte böyle cezalandırırız."},{"n":42,"t":"İman edip te salih ameller işleyenlere gelince; Biz, hiç kimseye gücünün yeteceğinden baikasını yüklemeyiz. İşte onlar, cennetliklerdir. Onlar orada temelli kalıcıdırlar."},{"n":43,"t":"Göğüslerinde kinden ne varsa söküp atmışızdır. Altlarından ırmaklar akar ve derler ki: Hamdolsun Allah’a ki; bizi buna hidayet etti. Eğer Allah bizi hidayete erdirmemiş olsaydı, biz hidayete erecek değildik. Andolsun ki; Rabbımızın peygamberleri hakkı getirmişlerdir. Onlara: Yapmakta olduklarınızdan dolayı mirasçısı kılındığınız cennet işte budur, diye seslenilir."},{"n":44,"t":"Cennet ashabı, cehennem ashabına: Rabbımızın bize vaadettiğini hak bulduk. Siz de rabbınızın size vaadettiğini hak buldunuz mu? diye seslendiler."},{"n":45,"t":"Onlar ki; Allah’ın yolundan alıkoyarlar ve onu eğriltmek isterler. Ve onlar; ahireti de inkar edenlerdir."},{"n":46,"t":"İki taraf arasında bir perde vardır. A’raf üzerinde de her birini simalarıyla tanıyan adamlar vardır. Cennetliklere: Size selam olsun, diye seslenirler. Bunlar, henüz girmeyen, ama uman kimselerdir."},{"n":47,"t":"Gözleri cehennem ashabından tarafa çevrilince de; Rabbımız, bizi zalimler güruhu ile beraber bulundurma, derler."},{"n":48,"t":"A’raf ashabı; simalarıyla tanıdıkları adamlara seslenirler: Topluluğunuz, topladığınız mal ve büyüklük taslamalarınız size fayda vermedi, derler."},{"n":49,"t":"Bunlar mıydı ki; kendilerini Allah’ın rahmetine erdirmeyeceğine yemin etmiştiniz. Girin cennete; size hiç bir korku yoktur ve sizler üzülecek de değilsiniz."},{"n":50,"t":"Cehenenm ashabı; cennet ashabına: Sudan veya Allah’ın size verdiği rızıktan biraz da bize akıtın, diye seslenirler. Onlar da derler ki: Doğrusu Allah; onları kafirlere haram kıldı."},{"n":51,"t":"Onlar ki; dinlerini alayla eğlenceye aldılar. Dünya hayatı da kendilerini aldattı. İşte onlar; bu günlerine kavuşmayı nasıl unutmuşlar idiyse, ayet için katmerlidir. Ne var ki bilmezsiniz. lerimizi nasıl bilerek inkar etmişler idiyse; Biz de bugün onları öylece unuturuz."},{"n":52,"t":"Andolsun ki; Biz, onlara kitab indirdik. Onu bilgiye dayanarak uzun uzun açıkladık. İnanan bir kavim için hidayet ve rahmet olarak."},{"n":53,"t":"Onlar, onun te’vilinden başkasını mı bekliyorlar? Onun te’vilinin geldiği gün; daha önce onu unutmuş olanlar derler ki: Gerçekten Rabbımızın elçileri, bize hakkı getirmiştir. Şimdi bize şefaat edecek var mı ki; şefaat etsin. Yahut geriye çevrilir miyiz ki, yapmış olduğumuzdan başkasını yapalım? Onlar gerçekten kendilerini hüsrana uğratmışlardır. Ve uydurageldikleri şeyler, kendilerinden uzaklaşıp kaybolmuştur."},{"n":54,"t":"Muhakkak ki sizin Rabbınız; gökleri ve yeri altı günde yaratan, sonra Arş’a hükmeden Allah’tır. Gündüzü; durmadan kovalayan gece ile bürür. Güneş, ay ve yıldızlar O’nun emri ile müsahhar kılmışlardır. Bilin ki; yaratma da, emir de O’nundur. Alemlerin Rabbı olan Allah’ın şanı ne yücedir."},{"n":55,"t":"Rabbınıza yalvara yakara gizlice dua edin. Muhakkak ki O; haddi aşanları sevmez."},{"n":56,"t":"Islah olmuşken yeryüzünde fesad çıkarmayın ve O’na korka korka ve ümitle yalvarın. Muhakkak ki Allah’ın rahmeti; ihsan edenlere çok yakındır."},{"n":57,"t":"O’dur ki rahmetinin önünde rüzgarı müjdeci olarak gönderir. Nihayet bunlar, ağır yüklü bulutları yüklendiğinde; Biz, onu ölü bir memlekete gönderir, su indirir ve onunla her tür mahsulleri yetiştiririz. İşte ölüleri de böylece çıkarırız. Ta ki iyice düşünüp ibret alasınız."},{"n":58,"t":"İyi ve temiz memleketin bitkisi; Rabbının izniyle çıkar. Kötü olandan ise; faydası çok az olandan başkası çıkmaz. Şükreden bir kavim için ayetleri işte böyle yerli yerince açıklarız."},{"n":59,"t":"Andolsun ki; Nuh’u kavmine gönderdik de; Ey kavmim, Allah’a kulluk edin, sizin için O’ndan başka hiçbir ilah yoktur. Doğrusu ben, sizin için büyük bir günün azabından korkarım, dedi."},{"n":60,"t":"Kavminden ileri gelenler de dedi ki: Biz seni apaçık bir sapıklık içinde görüyoruz."},{"n":61,"t":"Dedi ki: Ey kavmim; bende bir sapıklık yoktur. Ben, ancak alemlerin Rabbından bir peygamberim."},{"n":62,"t":"Rabbımın vahyettiklerini size bildiriyorum. Ve size öğüt veriyorum. Ben sizin bilmediğinizi de Allah katından biliyorum."},{"n":63,"t":"Sizi uyarması, sizin sakınmanızı ve böylece rahmete kavuşturulmanız için; aranızdan bir adama, Rabbınız tarafından bir haber geldi diye mi hayret ediyorsunuz?"},{"n":64,"t":"Bunun üzerine onu yalanladılar. Biz de onu ve gemide beraberinde olanları kurtardık. Ayetlerimizi yalan sayanları da suda boğduk. Çünkü onlar, gerçekten kör bir kavim idiler."},{"n":65,"t":"Ad’a da kardeşleri Hüd’u gönderdik. De ki: Ey kavmim Allah’a ibadet edin. Sizin için O’ndan başka ilah yoktur. Hala sakınmaz mısınız?"},{"n":66,"t":"Kavminin ileri gelenlerinden küfretmiş olanlar: Gerçekten biz, seni beyinsizlik içinde görüyoruz ve doğrusu biz, seni yalancılardan sanıyoruz, dediler."},{"n":67,"t":"Dedi ki: Ey kavmim; bende hiç bir beyinsizlik yoktur. Yalnız ben, alemlerin Rabbından gelmiş bir peygamberim."},{"n":68,"t":"Size Rabbımın vahyettiklerini bildiriyorum. Ve ben, sizin için emin bir öğütçüyüm."},{"n":69,"t":"Sizi uyarması için aranızdan bir adama Rabbınız tarafından bir haber geldi diye mi hayret ediyorsunuz? Düşünün ki; O, sizi Nuh kavminden sonra halifeler yaptı. Yaratılış itibariyle onlardan fazla boy bos verdi. Hem Allah’ın nimetlerini hatırlayın ki; felaha eresiniz."},{"n":70,"t":"Dediler ki: Sen, bize; yalnız Allah’a kulluk etmemiz ve atalarımızın tapmakta olduklarını bırakmamız için mi geldin? Şayet sadıklardan isen; tehdit ettiklerini getir bize."},{"n":71,"t":"Dedi ki: Gerçekten üzerinize Rabbınızdan bir azab, bir gazab hak oldu. Allah onlara, kendinizin ve atalarınızın taptığı bir takım adlar hakkında hiç bir hüccet indirmemişken benimle mücadele mi ediyorsunuz? Bekleyin öyleyse, şüphesiz ben de sizinle beraber bekleyenlerdenim."},{"n":72,"t":"Biz, bunun üzerine, rahmetimizle onu ve beraberinde bulunanları kurtardık. Ayetlerimizi yalan sayıp iman etmemiş olanların kökünü kestik. Onlar, zaten mü’minler değillerdi."},{"n":73,"t":"Semud’a da kardeşleri Salih’i. Dedi ki: Ey kavmim; Allah’a ibadet edin, sizin için O’ndan başka hiç bir ilah yoktur. Size Rabbınızdan açık bir burhan gelmiştir. İşte size bir ayet olarak Allah’ın dişi devesi. Onu bırakın da Allah’ın toprağında otlasın. Ona bir kötülükle dokunmayın. Yoksa sizi elim bir azab yakalar."},{"n":74,"t":"Düşününüz ki; O, sizi Ad kavminden sonra halifeler yaptı, yeryüzüne sizi yerleştirdi. Ovalarından köşkler yapıyor, dağlarından evler yontuyorsunuz. Artık Allah’ın nimetlerini anın. Yeryüzünde fesadçılar olarak taşkınlık yapmayın."},{"n":75,"t":"Onun kavminden büyüklük taslayan ileri gelenleri; kendilerine hor görünenlere içlerinden iman edenlere: Siz; Salih’in gerçekten Rabbı tarafından gönderilmiş olduğuna inanıyor musunuz? dediler. Onlar da dediler ki: Doğrusu biz, onunla gönderilene inanıyoruz."},{"n":76,"t":"Büyüklük taslayanlar dediler ki: Biz, doğrusu sizin iman ettiğinizi inkar edenleriz."},{"n":77,"t":"Ve dişi deveyi kesip devirdiler de Rabblarının emrine baş kaldırdılar ve dediler ki: Ey Salih; eğer sen peygamberlerden isen tehdid edip durduğun azabı getir bize."},{"n":78,"t":"Bu yüzden onları şiddetli bir sarsıntı tutuverdi de yurtlarında dizüstü çöken kimseler oldular."},{"n":79,"t":"O da onlardan yüz çevirdi ve dedi ki: Ey kavmim; andolsun ki ben, size Rabbımın vahyettiğini bildirdim ve size öğüt verdim. Ne var ki siz, öğüt verenleri sevmiyorsunuz."},{"n":80,"t":"Lüt’u da. Hani o, kavmine demişti ki: Sizden önce dünyalarda hiç kimsenin yapmadığı hayasızlığı mı yapıyorsunuz?"},{"n":81,"t":"Siz; kadınları bırakıp şehvetle erkeklere yaklaşıyorsunuz. Doğrusu siz, çok aşırı giden bir kavimsiniz."},{"n":82,"t":"Kavminin cevabı sadece; çıkarın onları memleketinizden. Çünkü onlar, fazla temizlik yapan insanlarmış, demek oldu."},{"n":83,"t":"Bunun üzerine Biz de, hem onu, hem de ehlini kurtardık. Ancak karısı, geride kalanlardan oldu."},{"n":84,"t":"Onların üzerine öyle bir yağmur yağdırdık ki; bir bak, işte suçluların sonu nasıl olmuştur."},{"n":85,"t":"Medyen’e de kardeşleri Şuayb’ı. Dedi ki: Ey kavmim; Allah’a kulluk edin. Sizin O’ndan başka hiç bir ilahınız yoktur. Rabbınızdan size apaçık bir burhan gelmiştir. O halde ölçüyü ve tartıyı doğru tutun. İnsanların eşyasını eksik vermeyin. Ve o, ıslah olduktan sonra yeryüzünde fesad çıkarmayın. Bunlar, sizin için hayırlıdır, eğer mü’minlerden iseniz."},{"n":86,"t":"Ve siz, Allah’a iman edenleri tehdit ederek, Allah’ın yolundan alıkoyarak ve onun eğriliğini isteyerek, her yolun başını tutup oturmayın. Hem hatırlayın ki; siz, vaktiyle pek az idiniz de sizi O, çoğalttı. Ve bakın fesad çıkaranların sonu ne olmuştur."},{"n":87,"t":"Eğer içinizden bir kısmı benimle gönderilene inanmış, bir kısmı da inanmamışsa; Allah, aranızdaki hükmü verinceye kadar sabredin. O; hüküm verenlerin en hayırlısıdır."},{"n":88,"t":"Kavminden büyüklük taslayan ileri gelenler dediler ki: Ey Şuayb; seni ve beraberindeki inanmış olanları, ya memleketimizden çıkarırız veya mutlaka bizim dinimize dönersiniz. Dedi ki: İstemezsek de mi?"},{"n":89,"t":"Allah, bizi ondan kurtardıktan sonra yine sizin dininize dönecek olursak; doğrusu Allah’a karşı yalan uydurmuş oluruz. Rabbımız olan Allah’ın dilemesi bir yana, O’na dönmemiz bizim için olacak şey değildir. Rabbımızın ilmi her şeyi kuşatmıştır. Ancak Allah’a dayanıp güvendik biz. Rabbımız, kavmimizle bizim aramızda Sen, hak ile hüküm ver. Sen, hüküm verenlerin en hayırlısısın."},{"n":90,"t":"Kavminden küfretmiş olan ileri gelenler dediler ki: Şuayb’a uyarsanız; andolsun ki siz, o zaman hüsrana uğrayanlardansınız."},{"n":91,"t":"Bunun üzerine onları sarsıntı yakalayıverdi. Ve yurtlarında dizüstü çökenler oldular."},{"n":92,"t":"Şuayb’ı yalanlayanlar, zaten yurtlarında hiç oturmamış gibi oldular. Şuayb’ı yalanlamış olanlar; hüsrana uğrayanlar, işte onlar oldular."},{"n":93,"t":"Bunun üzerine onlardan yüz çevirdi ve dedi ki: Ey kavmim; andolsun ki ben, Rabbımın bana vahyettiklerini size bildirdim. Ve öğüt verdim. Öyleyse ben, küfredenler kavmine nasıl tasalanırım?"},{"n":94,"t":"Biz, hangi kasabaya bir peygamber gönderdiysek; yalvarıp yakarsınlar diye, ora halkını mutlaka darlık ve sıkıntıya uğratmışızdır."},{"n":95,"t":"Sonra kötülüğün yerine iyilik koyduk. Nihayet çoğaldılar ve; atalarımıza da fakirlik, şiddet, hastalık, iyilik ve genişlik dokunmuştu, dediler. Bunun üzerine Biz de onları kendilerine farkına varmadan ansızın yakalayıverdik."},{"n":96,"t":"Şayet kasabaların halkı, inanmış ve sakınmış olsalardı; elbette üzerlerine gökten ve yerden bereketler açardık. Fakat onlar yalanladılar. Biz de bunun üzerine onları, yaptıklarından dolayı yakalayıverdik."},{"n":97,"t":"Kasabaların halkı; kendileri geceleyin uyurlarken, azabımızın onlara gelip çatmasından emin mi oldular?"},{"n":98,"t":"Yoksa kasabaların halkı; kendileri, güpegündüz oynarlarken azabımızın onlara gelip çatmasından emin mi oldular?"},{"n":99,"t":"Artık onlar; Allah’ın düzeninden emin mi oldular? Hüsrana uğrayanlar topluluğundan başkası Allah’ın düzeninden emin olmaz."},{"n":100,"t":"Sahiplerinden sonra, yeryüzüne varis olanlara besbelli değil midir ki; eğer Biz, dileseydik onları da günahlarından dolayı cezalandırırdık. Ve onların kalbleri üzerine mühür basarız da bir şey duymazlar."},{"n":101,"t":"İşte o kasabaların haberlerinin bir kısmını sana anlatıyoruz. Andolsun ki; peygamberleri; onlara apaçık burhanlar getirdi de, önceleri yalanladıklarından inanmadılar. İşte böyle mühür basar Allah kafirlerin kalblerine."},{"n":102,"t":"Onların çoğunda Biz, ahde vefa görmedik. Onların çoğunu fasıklar olarak bulduk."},{"n":103,"t":"Sonra onların ardından Musa’yı ayetlerimizle Firavun’a ve erkanına gönderdik. Onlar buna karşı haksızlık ettiler. Bir bak ki; fesadçıların sonu nice oldu?"},{"n":104,"t":"Musa dedi ki: Ey Firavun; ben, alemlerin Rabbından gönderilmiş bir peygamberim."},{"n":105,"t":"Bana yaraşan; Allah hakkında haktan başkasını söylememektir. Size, Rabbınızdan apaçık bir burhan getirdim. Artık İsrailoğullarını benimle beraber gönder."},{"n":106,"t":"Dedi ki: Şayet sen, bir ayet getirdinse; göster onu, eğer sadıklardan isen."},{"n":107,"t":"Bunun üzerine asasını bıraktı. Bir de ne görsünler; o, apaçık bir ejderhadır."},{"n":108,"t":"Elini çıkardı, ne görsün; o da bakanlara bembeyaz."},{"n":109,"t":"Firavun’un kavminden ileri gelenler: Doğrusu bu, bilgin bir sihirbazdır, dediler."},{"n":110,"t":"Sizi yurdunuzdan çıkarmak istiyor. Firavun: O halde ne buyurursunuz?"},{"n":111,"t":"Dediler ki: Onu ve kardeşini alıkoy, şehirlere toplayıcılar yolla."},{"n":112,"t":"Bütün bilgin sihirbazları sana getirsinler."},{"n":113,"t":"Sihirbazlar Firavun’a geldi ve dediler ki: Eğer galibler biz olursak; şüphesiz bize bir mükafat var, değil mi?"},{"n":114,"t":"Evet, hem siz muhakkak gözdeler olacaksınız, dedi."},{"n":115,"t":"Dediler ki: Ey Musa, sen mi atacaksın, yoksa atanlar biz mi olalım?"},{"n":116,"t":"Siz atın, dedi. Atınca; halkın gözlerini büyülediler, onlara korku saldılar ve büyük bir sihir getirmiş oldular."},{"n":117,"t":"Biz de Musa’ya: Asanı bırak, diye vahyettik. Bir de ne görsünler; onların uydurduklarını yalayıp yutuyor."},{"n":118,"t":"Böylece hak yerini buldu ve onların yapmakta oldukları şeyler de boşa gitti."},{"n":119,"t":"İşte orada yenildiler, hor ve hakir geri döndüler."},{"n":120,"t":"Sihirbazlar da hep birden secdeye kapandılar."},{"n":121,"t":"Dediler ki: Alemlerin Rabbına iman ettik."},{"n":122,"t":"Musa ve Harun’un Rabbına."},{"n":123,"t":"Firavun dedi ki: Ben size izin vermeden mi ona inandınız? Doğrusu bu; halkı şehirden çıkarmanız için düşündüğünüz bir hiledir. Fakat yakında bilirsiniz siz."},{"n":124,"t":"Elbette ve elbette ellerinizi ve ayaklarınızı çaprazlama keseceğim. Sonra da hepinizi asacağım."},{"n":125,"t":"Dediler ki: Biz, şüphesiz Rabbımıza dönenleriz."},{"n":126,"t":"Sen; bizden, sırf Rabbımızın ayetleri gelince ona inandık diye intikam alıyorsun. Rabbımız; üzerimize sabır yağdır ve bizi müslümanlar olarak öldür."},{"n":127,"t":"Firavun’un kavminin ileri gelenleri: Musa’yı ve kavmini yeryüzünde fesadçılık etsinler, seni de, tanrılarını da terketsinler diye mi bırakıyorsun? dediler. Dedi ki: Oğullarını öldürtürüz, kadınlarını sağ bırakırız. Elbette biz, onları ezicileriz."},{"n":128,"t":"Musa kavmine dedi ki: Allah’tan yardım isteyin ve sabredin. Yeryüzü muhakkak ki Allah’ındır. Kullarından dilediğini ona mirasçı kılar ve akıbet müttakilerindir."},{"n":129,"t":"Dediler ki: Sen, bize gelmezden önce de, geldikten sonra da eziyyet edildik. Dedi ki: Rabbınızın, düşmanınızı yok etmesi ve yeryüzünde sizi onların yerine getirmesi umulur. Ve o zaman nasıl davranacağınıza bakacaktır."},{"n":130,"t":"Andolsun ki; Biz, Firavun hanedanını düşünüp ibret alırlar diye yıllarca kuraklık ve mahsullerinin kıtlığıyla tutup sıktık."},{"n":131,"t":"Onlara bir iyilik geldiğinde: Bu, bizim içindir, dediler. Şayet kendilerine bir kötülük gelirse; Musa ile beraberindekilere uğursuzluk yüklerdi. Dikkat edin, onların uğursuzluğu ancak Allah katındadır, fakat çoğu bilmezler."},{"n":132,"t":"Dediler ki: Bizi büyülemek için ne kadar mucize gösterirsen göster; biz, sana inananlardan olmayacağız."},{"n":133,"t":"Bunun üzerine, biz de birbirinden ayrı mucizeler olarak başlarına tufan, çekirge, haşerat, kurbağalar ve kan gönderdik. Yine de büyüklük taslayıp suçlular güruhu oldular."},{"n":134,"t":"Üzerlerine azab çökünce, dediler ki: Ey Musa, sana olan ahdine göre Rabbına dua et. Eğer bu azabı bizden kaldırırsan; andolsun ki, sana inanacağız ve İsrailoğullarını seninle birlikte göndereceğiz."},{"n":135,"t":"Onların erişecekleri bir süreye kadar azabı üzerlerinden kaldırınca; bir de bakarsın, onlar sözlerinden cayıyorlardı."},{"n":136,"t":"Bu yüzden; Biz de onlardan intikam aldık. Ve ayetlerimizi yalanlayıp umursamadıkları için hepsini denizde boğduk."},{"n":137,"t":"Hor görülmüş olan kavmi de, bereketlendirdiğimiz yerin doğularına ve batılarına mirasçı kıldık. Rabbının İsrailoğullarına vukü bulan güzel sözü de onların sabretmelerinden dolayı yerini buldu. Firavun’un da, kavminin de yapmakta ve yükselmekte oldukları şeyleri harab ettik."},{"n":138,"t":"İsrailoğullarını denizden geçirdik. Onlar, gönülden putlara tapagelen bir topluluğa rastladılar ve dediler ki: Ey Musa; onların tanrıları olduğu gibi bize de bir tanrı yap. O da dedi ki: Siz gerçekten cahil topluluksunuz."},{"n":139,"t":"Şüphesiz ki bunların içinde bulundukları; yok olmaya mahkumdur ve yapmakta oldukları şey de batıldır."},{"n":140,"t":"Dedi ki: Ben, sizin için bir tanrı olarak Allah’tan başkasını mı arayacak mışım? Halbuki O, sizi alemlere üstün kılmıştır."},{"n":141,"t":"Hani sizi, işkencenin en kötüsüne uğratan, kadınlarınızı sağ bırakıp, oğullarınızı öldüren Firavun hanedanından kurtarmıştık. Bunda size Rabbınızdan büyük bir imtihan vardır."},{"n":142,"t":"Musa’ya otuz gece vade verdik. Sonra bunu on ile tamamladık. Böylece Rabbının ta’yin ettiği vakit, kırk gece olarak tamamlandı. Musa kardeşi Harun’a dedi ki: Kavmim içinde, benim yerime geç. Islah et ve fesadçıların yoluna uyma."},{"n":143,"t":"Musa ta’yin ettiğimiz vakitte gelince ve Rabbı onunla konuşunca; dedi ki: Rabbım; bana, kendini göster. Sana bakayım. Buyurdu ki: Beni kat’iyyen göremezsin. Ama dağa bak; eğer o yerinde kalırsa, sen de Beni görürsün. Rabbı dağa tecelli edince; onu paramparça etti ve Musa da baygın düştü. Ayılınca dedi ki: Tenzih ederim Seni, Sana tevbe ettim ve ben, mü’minlerin ilkiyim."},{"n":144,"t":"Buyudu ki: Ey Musa; risaletim ve kelamımla seni insanlar arasından seçtim. Sana verdiğimi al ve şükredenlerden ol."},{"n":145,"t":"Biz, ona levhalarda herşeyden bir öğüt yazdık ve herşeyi uzun uzadıya açıkladık. Öyleyse sen, bunları kuvvetle al, kavmine de emret. Onları en güzel şekilde tutsunlar. İlerde size fasıklar yurdunu göstereceğim."},{"n":146,"t":"Yeryüzünde haksız yere büyüklük taslayanları ayetlerimden çevireceğim. Onlar, her ayeti görseler yine de inanmazlar. Doğru yolu görseler, onu yol edinmezler. Azgınlık yolunu görseler, hemen» onu yol edinirler. Bu, ayetlerimizi yalanlamış olmalarından ve ondan gafil bulunmalarındandır."},{"n":147,"t":"Ayetlerimizi ve ahirete kavuşmayı yalanlayanların işledikleri boşa gitmiştir. Onlar; işlediklerinden başka bir şeyle mi cezalandırılacaklardı?"},{"n":148,"t":"Musa’nın kavmi; onun ardından, zinet takımlarından canlıymış gibi böğüren bir buzağı heykeli edindiler. Onun kendileriyle konuşmadığını ve bir yol da göstermediğini görmediler mi ki, tanrı edindiler de zalimlerden oldular?"},{"n":149,"t":"Elleri böğründe, çaresiz kalıp kendilerinin de sapıtmış olduklarını görünce; dediler ki: Rabbımız bize merhamet etmezse ve bizi bağışlamazsa muhakkak ki hüsrana uğrayanlardan olacağız."},{"n":150,"t":"Musa; kavmine kızgın ve üzgün dönünce; benden sonra arkamdan ne kötü işler yapmışsınız? Rabbınızın emrinin çabucak gelmesini mi istediniz? dedi ve levhaları attı. Kardeşinin başından tutup kendisine doğru çekiyordu: Ey anamın oğlu, bu kavim beni gerçekten zayıf gördüler. Az kalsın öldürüyorlardı. Sen de bana düşmanları sevindirecek harekette bulunma ve beni zalimler güruhu ile bir tutma, dedi."},{"n":151,"t":"Dedi ki: Rabbım, beni ve kardeşimi bağışla. Bizi rahmetinin içine al. Sen merhametlilerin en merhametlisisin."},{"n":152,"t":"Muhakkak ki buzağıyı tanrı edinenlere; Rabblarından bir gazab ve dünya hayatında bir horluk erişecektir. Biz, işte böylece cezalandırırız iftira edenleri."},{"n":153,"t":"Kötülükleri işleyip sonra ardından tevbe ve iman edenlere gelince şüphesiz ki Rabbın; bundan sonra elbette Gafur’dur, Rahim’dir."},{"n":154,"t":"Öfkesi dinip, sükun hasıl olunca; Musa levhaları aldı. Onlardaki nüshasında Rabblarından korkanlara hidayet ve rahmet vardı."},{"n":155,"t":"Musa, ta’yin ettiğimiz vakit için kavminden yetmiş kişi seçti. Onları titreme tutunca dedi ki: Rabbım; dileseydin önce onalrı da helak ederdin, beni de. İçimizdeki beyinsizlerin işledikleri yüzünden bizi helak eder misin? Bu, Senin imtihanından başka birşey değildir. Onunla dilediğini dalalete düşürür, dilediğini de hidayete götürürsün. Sen, bizim dostumuzsun. O halde bizi bağışla, merhamet et bize. Sen bağışlayanların en hayırlısısın."},{"n":156,"t":"Ve bize; hem bu dünyada bir iyilik yaz, hem de ahirette. Biz sana döndük."},{"n":157,"t":"Onlar ki; yanlarındaki Tevrat’ta ve İncil’de yazılı bulacakları; okuma, yazma bilmeyen ve nebi olan Rasule tabi olurlar. O, kendilerine ma’rufu emreder, münkerden nehyeder. Temiz şeyleri helal kılar, murdar şeyleri de haram eder. Onların ağır yüklerini ve üzerlerindeki bağları, zincirleri indirir. İşte ona iman edenler, onu ta’zim edenler, ona yardım edenler ve onunla birlikte indirilen nura tabi olanlar, işte onlar; felaha erenlerin kendileridir."},{"n":158,"t":"De ki: Ey insanlar; ben gerçekten göklerin ve yerin mülkü kendisinin olan, O’ndan başka hiçbir tanrı bulunmayan, hem dirilten, hem öldüren Allah’ın hepiniz için gönderdiği peygamberiyim. Şu halde Allah’a ve O’nun ümmi peygamberi olan elçisine inanın: Ki o da Allah’a ve O’nun sözlerine inanmaktadır. Ve ona uyun ki hidayete eresiniz."},{"n":159,"t":"Musa’nın kavminden bir topluluk vardır ki; irşad ederler ve onunla hükmederler."},{"n":160,"t":"Biz, onları on iki oymağa, ümmetlere ayırdık. Kavmi ondan su istediği zaman Musa’ya vahyettik ki: Asanı taşa vur. Ondan on iki pınar fışkırdı. Herkes içeceği yeri belledi. Ve onların üzerine bulutla gölge yaptık. Onlara kudret helvası ve bıldırcın indirdik. Size rızık olarak verdiklerimizin temiz ve güzel olanlarından yeyin. Onlar bize zulmetmediler, ancak kendilerine zulmediyorlardı."},{"n":161,"t":"Hani onlara denilmişti ki: Şu şehirde oturun, dilediğiniz gibi yeyin, için. «Affet» deyin ve kapısından secde ederek girin ki; yanılmalarınızı bağışlayalım. İhsan edenlere daha da arttıracağız."},{"n":162,"t":"İçlerinden zulmedenler, kend, lerine söylenen sözü başkasıyla değiştirdiler. Biz de onlara, zulmeder olduklarından dolayı gökten azab indirdik."},{"n":163,"t":"Onlara; denizin kıyısındaki o kasabanın durumunu sor. Hani onlar, cumartesi gününü ihlal ederek haddi aşmışlardı. Zira cumartesi günleri balıkları sürüyle geliyor, cumartesi tatili yapmayacakları gün ise gelmiyordu. İşte biz, fasıklık eder oldukları için onları böylece imtihan ediyorduk."},{"n":164,"t":"Hani, içlerinden bir topluluk demişti ki: Allah’ın kendilerini helak edeceği veya çetin bir azab ile cezalandıracağı bir kavme ne diye öğüt veriyorsunuz? Onlar da: Rabbınıza karşı mazeret olsun ve belki sakınırlar diye, demişlerdi."},{"n":165,"t":"Onlar, kendilerine verilen öğüdü unutunca; Biz, kötülükden men’edenleri kurtardık, zulmedenleri ise fasıklık eder oldukları için şiddetli bir azab ile yakaladık."},{"n":166,"t":"Böylece onlar, serkeşlik ederek yasak edileni yapmakta ısrar edince; aşağılık maymunlar olun, dedik."},{"n":167,"t":"Hani Rabbın; onları kıyamet gününe kadar azabın en kötüsüne uğratacak olanları, muhakkak göndereceğini ilan etmişti. Şüphesiz ki Rabbın; cezayı çabuk verendir. Ve muhakkak ki O; Gafur’dur, Rahim’dir."},{"n":168,"t":"Biz; onları, yeryüzünde cemaatlere ayırdık. İçlerinden kimisi salihlerdi, kimisi de onlardan aşağıdırlar. Belki dönerler diye onları güzellikler ve kötülüklerle denedik."},{"n":169,"t":"Onlardan kötü kimseler gelip onların yerine geçmiş, kitaba varis olmuşlardı. Dünyanın geçici meta’ını alıyorlar ve: İleride affedileceğiz diyorlardı. Onlara buna benzer bir meta’ gelse onu da alıyorlar. Onlardan; Allah’a karşı ancak hakkı söyleyeceklerine dair kitab üzerine ahd alınmamış mıydı? Ahiret yurdu, Allah’tan korkanlar için daha hayırlıdır. Hala aklınızı başınıza almayacak mısınız?"},{"n":170,"t":"Onlar ki; kitaba sımsıkı sarılırlar ve namazı dosdoğru kılarlar. Elbette Biz, ıslah edenlerin mükafatını zayi’ etmeyiz."},{"n":171,"t":"Hani, Biz dağı üzerlerine gölgelik gibi kaldırmıştık da, onlar tepelerine düşecek sanmışlardı. Size verdiğimizi kuvvetle tutun. Ve onda olanı düşünün ki; sakınasınız."},{"n":172,"t":"Hani Rabbın; ademoğullarının sülbünden soyunu çıkarmış ve kendilerini nefislerine şahid tutmuş. Ben, sizin Rabbınız değil miyim? demişti. Onlar da demişlerdiki: Evet, biz buna şahidiz. Kıyamet günü: Bizim bundan haberimiz yoktu, demeyesiniz."},{"n":173,"t":"Veya daha önce sadece atalarımız şirk koşmuştu, biz ise onların ardından gelen bir nesiliz, bizi batıl işleyenlerin yaptıkları yüzünden helak eder misin? demeyesiniz."},{"n":174,"t":"İşte Biz ayetleri böyle uzun uzadıya açıklarız. Belki dönerler diye."},{"n":175,"t":"Kendisine ayetlerimizi verdiğimiz halde, onlardan sıyrılan ve şeytanın arkasına taktığı sonunda da azgınlardan olan o kimsenin haberini anlat."},{"n":176,"t":"Dileseydik onu, bununla yükseltirdik. Fakat o; yere saplandı ve hevesine uydu. Artık onun hali; o köpeğin hali gibidir ki, üstüne varsan da dilini sarkıtıp solur, kendi haline bıraksan da dilini sarkıtıp solur. İşte ayetlerimizi yalanlayan kavmin hali böyledir. Sen, kıssayı anlat. Belki düşünürler."},{"n":177,"t":"Ayetlerimizi yalanlayarak kendilerine zulmeden kavmin misali ne kötüdür."},{"n":178,"t":"Allah; kimi hidayete erdirirse; odur hidayete eren. Kimi de saptırırsa; işte onlardır hüsrana uğrayanların kendileri."},{"n":179,"t":"Andolsun ki; Biz cinn ve insanlardan bir çoğunu cehennem için yarattık. Onların kalbleri vardır; anlamazlar, gözleri vardır; görmezler, kulakları vardır; duymazlar. Onlar; hayvanlar gibidirler, hatta daha da sapıktırlar. İşte onlar; gafillerin kendilerdir."},{"n":180,"t":"En güzel isimler Allah’ındır. Öyleyse O’na bunlarla dua edin. O’nun isimleri konusunda eğriliğe sapanları bırakın. Onlar, yaptıklarının cezalarını göreceklerdir."},{"n":181,"t":"Yarattıklarımızdan öyle bir ümmet vardır ki; onlar hakkı gösterirler ve onunla adaleti uygularlar."},{"n":182,"t":"Ayetlerimizi yalanlayanlara gelince; Biz, onları bilmeyecekleri noktadan derece derece helake yaklaştırırız."},{"n":183,"t":"Ben, onlara mühlet veririm. Muhakkak ki Benim düzenim çetindir."},{"n":184,"t":"Düşünmüyorlar mı ki; arkadaşlarında hiçbir delilik yoktur. O, ancak apaçık bir uyarıcıdır."},{"n":185,"t":"Onlar; göklerin melekutuna, Allah’ın yarattığı herhangi bir şeye ve ecellerinin yaklaşmış olması ihtimaline hiç bakmazlar mı? Bundan sonra artık hangi söze inanacaklar?"},{"n":186,"t":"Kimi, Allah saptırırsa; onu doğru yola götürecek yoktur. O, bunları taşkınlıkları içinde serseri bir halde bırakır."},{"n":187,"t":"Sana kıyametin ne zaman gelip çatacağını soruyorlar. De ki: Onun bilgisi, ancak Rabbımın katındadır. Onun vaktini kendisinden başkası açıklayamaz. Onun ağırlığını gökler de, yer de kaldıramaz. O, size ansızın gelir. Sen, onu biliyormuşsun gibi sana soruyorlar. De ki: Onun bilgisi ancak Allah katındadır. Fakat insanların çoğu bilmezler."},{"n":188,"t":"De ki: Ben, kendime Allah’ın dilediğinden başka ne fayda verebilirim, ne de zarar. Eğer ben, gaybı bileydim; daha çok hayır yapmak isterdim. Ve bana, hiç bir fenalık da dokunmazdı. Ben, sadece iman eden bir kavme uyarıcı ve müjdeciyim."},{"n":189,"t":"O’dur, sizi tek bir nefisten yaratan ve ondan da gönlünün ısınacağı eşini vareden. Eşini örtüp bürüyünce; o, hafif bir yük yüklendi ve onunla bir müddet gider gelirdi. Nihayet ağırlaşınca; karı koca Rabbları olan Allah’a: Eğer bize salih bir çocuk verirsen andolsun ki şükredenlerden oluruz, diye dua ettiler."},{"n":190,"t":"Allah onlara salih bir çocuk verince; kendilerine verdiği şey hakkında Allah’a ortaklar koştular. Allah, onların ortak koştukları şeyden münezzeh tir."},{"n":191,"t":"Kendileri-yaratılmışken-Bir şey yaratamayan şeyleri mi ortak koşuyorlar?"},{"n":192,"t":"Halbuki bunlar; ne onlara yardım edebilir, ne de kendilerine bir yardımları olabilir."},{"n":193,"t":"Onları doğru yola çağırsanız da, size uymazlar. Çağırmanız da, susmanız da onlar için birdir."},{"n":194,"t":"Allah’tan başka taptıklarınız da sizin gibi kullardır. Eğer sadıklardan iseniz; haydi onları çağırın da size karşılık versinler."},{"n":195,"t":"Onların ayakları var mıdır ki onunla yürüsünler? Elleri var mıdır ki onunla tutsunlar? Gözleri var mıdır ki onunla görsünler? Kulakları var mıdır ki onunla işitsinler? De ki: Çağırın ortaklarınızı da, elinizden gelirse, bana tuzak kurun ve göz açtırmayın."},{"n":196,"t":"Muhakkak ki benim dostum, kitabı indirmiş olan Allah’tır. Ve O, salihleri dost edinir."},{"n":197,"t":"O’nu bırakıp taptıklarınız ise; size yardım edemedikleri gibi; kendilerine de yardım edemezler."},{"n":198,"t":"Onları hidayete çağırsanız; duymazlar bile. Onları sana bakar görürsün; ama görmezler ki."},{"n":199,"t":"Sen; affı tut, ma’rufu emret ve cahillerden yüz çevir."},{"n":200,"t":"Şeytan seni dürtecek olursa; hemen Allah’a sığın. Çünkü O; gerçekten Semi’ dir, Alim’dir."},{"n":201,"t":"Muhakkak ki takvaya erenler; onlar şeytan tarafından bir vesveseye uğrayınca iyice düşünürler. Bir de bakarsın ki gördürücüdürler."},{"n":202,"t":"Kardeşleri ise onları azgınlığa sürüklerler. Sonra da bırakmazlar."},{"n":203,"t":"Onlara bir ayet getimediğin zaman, derler ki: Sen, bir tane yapsaydın ya? De ki: Ben, ancak Rabbımdan bana vahyolunana uyarım. Bu, Rabbımızdan gözleri açacak delillerdir. İman eden bir kavim için hidayet ve rahmettir."},{"n":204,"t":"Kur’an okunduğu zaman; ona derhal kulak verin ve susun ki, merhamet olunasınız."},{"n":205,"t":"Rabbına; içinden yalvararak ve korkarak, yüksek olmayan bir sesle sabah akşam zikret. Ve gafillerden olma."},{"n":206,"t":"Muhakkak ki Rabbının katındakiler, O’na kulluk etmekten asla büyüklenmezler. O’na tesbih ederler ve O’na secde ederler."}],[{"n":1,"t":"Sana ganimetlerden sorarlar. De ki: Ganimetler; Allah’ın ve Rasulünündür. Şu halde eğer mü’minler iseniz Allah’tan korkun, aranızı düzeltin, Allah’a ve peygamberlerine itaat edin."},{"n":2,"t":"Mü’minler, ancak onlardır ki; Allah anıldığı zaman kalbleri ürperir, Allah’ ın ayetleri kendilerine okunduğu zaman imanları artar ve Rabblarına tevekkül ederler."},{"n":3,"t":"Onlar ki; namazı dosdoğru kılarlar ve kendilerine rızık olarak verdiğimizden de infak ederler."},{"n":4,"t":"İşte onlar; inanmışların kendileridir. Onlara Rabb’larının katından dereceler, mağfiret ve cömertçe verilmiş rızıklar vardır."},{"n":5,"t":"Nitekim Rabbın; seni evinden hak uğruna çıkarmıştı. Halbuki mü’minlerden bir zümre bundan hoşlanmamışlardı."},{"n":6,"t":"Hak, apaçık meydana çıktıktan sonra bile, sanki göz göre göre ölüme sürükleniyorlarmış gibi seninle mücadele ediyorlardı."},{"n":7,"t":"Hani Allah; iki taifeden birini size vaadediyordu. Siz ise, kuvvetli bulunmayanın sizin olmasını arzu ediyordunuz. Allah ta istiyordu ki; sözleriyle hakkı gerçekleştirsin ve kafirlerin kökünü kessin."},{"n":8,"t":"Ta ki suçlular istemese de, hakkı gerçekleştirsin ve batılı iptal etsin."},{"n":9,"t":"Hani siz, Rabbınızdan imdad istiyordunuz da: Birbiri ardında bin melekle size imdad ederim, diyerek duanıza icabet etmişti."},{"n":10,"t":"Allah; bunu size sırf bir müjde olsun ve kalblerinizi yatışsın diye yapmıştır. Yardım; ancak Allah katındandır. Muhakkak ki Allah; Aziz’dir, Hakim’ dir."},{"n":11,"t":"Hani O, size kendi katından bir emniyet olmak üzere sizi hafif bir uykuya daldırıyordu. Sizi tertemiz yapmak, sizden şeytanın pisliğini gidermek, kalblerinizi pekiştirmek ve ayaklarınıza sebat vermek için gökten üstünüze bir su indiriyordu."},{"n":12,"t":"Hani Rabbın, meleklere: Ben sizinleyim, haydi iman edenlere sebat verin, diye vahyetmişti. Ben, küfretmiş olanların kalblerine korku salacağım. Artık siz de vurun boyunlarının üstüne, vurun tüm parmaklarına."},{"n":13,"t":"Bunun sebebi: Allah’a ve peygamberlerine karşı koymalarıdır. Her kim ki, Allah’a ve peygamberlerine karşı koyarsa; muhakkak Allah cezası çetin olandır."},{"n":14,"t":"İşte bunu tadın. Muhakkak ki kafirlere bir de ateş azabı vardır."},{"n":15,"t":"Ey iman edenler; toplu halde kafirlerle karşılaştığınız zaman, onlara arkalarınızı dönmeyin."},{"n":16,"t":"Tekrar savaşmak için bir tarafa çekilme veya bir başka topluluğa katılma dışından her kim, o gün arkasını dönerse; muhakkak ki o, Allah katından bir gazaba uğramıştır. Onun yurdu cehennenmdir ve o, ne kötü bir sonuçtur."},{"n":17,"t":"Siz öldürmediniz onları, fakat Allah öldürdü. Attığın zaman da; sen atmadın ancak Allah attı. Allah bunu, inananları güzel bir imtihana tabi tutmak için yapmıştı. Muhakkak ki Allah; Semi’dir, Alim’dir."},{"n":18,"t":"İşte bu, böyledir. Muhakkak ki Allah kafirlerin düzenini zayıflatıcıdır."},{"n":19,"t":"Eğer, fetih istiyor idiyseniz; işte size fetih gelmiştir. Eğer vazgeçerseniz; bu, sizin için daha hayırlıdır. Yok tekrar dönerseniz; biz de döneriz. Topluluğunuz çok da olsa hiç bir şeye yaramaz. Çünkü Allah muhakkak Mü’minlerle beraberdir."},{"n":20,"t":"Ey iman edenler; Allah’a ve Rasulüne itaat edin. Dinleyip dururken ondan yüzçevirmeyin."},{"n":21,"t":"Hem dinlemedikleri halde; dinledik; diyenler gibi olmayın."},{"n":22,"t":"Allah katında canlıların en kötüsü; akletmeyen sağır ve dilsizlerdir."},{"n":23,"t":"Şayet Allah onlarda bir hayır görseydi; onlara işittirirdi. Eğer işittirmiş olsaydı; yine de yüz çevirenler olarak arkalarını dönerlerdi."},{"n":24,"t":"Ey iman edenler; sizi hayat verecek şeylere çağırdığı zaman; Allah’a ve Rasulüne icabet edin. Hem bilin ki; Allah şüphesiz kişi ile kalbi arasına girer. Ve muhakkak O’na dönüp toplanacaksınız."},{"n":25,"t":"Bir de fitneden sakının ki; içinizden yalnız zulmedenlere erişmekle kalmaz. Hem bilin ki; muhakkak Allah azabı şiddetli olandır."},{"n":26,"t":"Hatırlayın ki; bir zamanlar yeryüzünde azlıktınız, zayıf sayılırdınız. İnsanların sizi tutup kapmasından korkuyordunuz. Size ev bark verdi, yardımıyla destekledi ve temiz şeylerden rızıklandırdı. Umulur ki şükredersiniz."},{"n":27,"t":"Ey iman edenler; Allah’a ve peygamberlerine ihanet etmeyin. Bile bile kendi emanetlerinize hıyanet etmiş olursunuz."},{"n":28,"t":"Hem bilin ki; mallarınız da, çocuklarınız da ancak birer fitnedir. Ve Allah katında büyük mükafat vardır."},{"n":29,"t":"Ey iman edenler; Allah’tan korkarsanız O, size bir furkan verir. Suçlarınızı örter ve sizi bağışlar. Allah, büyük lütuf sahibidir."},{"n":30,"t":"Hani küfredenler; seni tutup bağlamak, yahut öldürmek veya çıkarmak için düzen kuruyorlardı. Onlar düzen kurarlarken Allah da düzenlerine müdahale ediyordu. Allah, düzen yapanların en hayırlısıdır."},{"n":31,"t":"Ayetlerimiz onlara okunduğu zaman; işittik, istersek biz de bunun benzerini söyleriz. Bu, eskilerin masallarından başka bir şey değildir, demişlerdi."},{"n":32,"t":"Hani demişlerdi ki: Ey Allah’ımız; eğer bu, gerçekten Senin katından ise; bize gökten taş yağdır, yahut acıklı bir azab getir."},{"n":33,"t":"Halbuki sen içlerinde iken; Allah onlara azab etmez. Onlar istiğfar ederken de Allah, yine onları azablandıracak değildir."},{"n":34,"t":"Allah onlara, niçin azab etmesin ki; onlar, kendileri ona ehil olmadıkları halde (insanları) Mescid-i Haram’dan men’edip duranlardır. Hem O’nun dostu değillerdir. O’nun dostları ancak müttakilerdir, ama onların çoğu bilmezler."},{"n":35,"t":"Onların Beyt’in yanındaki duaları; sadece ıslık çalmak veya el çırpmaktan başka bir şey değildir. Öyleyse devamedegelmekte olduğunuz küfürden dolayı tadın azabı."},{"n":36,"t":"Muhakkak ki küfredenler; mallarını, Allah yolundan alıkoymak için harcarlar. Daha harcayacaklar, sonra içleri yanacak, sonra da mağlup olacaklardır. Küfredenler, cehenneme toplanacaklardır."},{"n":37,"t":"Allah; murdarı temizden ayırdetsin ve murdarı birbiri üstüne koyup topunu birden yığsın da, cehenneme atsın diye. İşte onlar; hüsrana uğrayanların kendileridir."},{"n":38,"t":"Küfredenlere söyle: Vazgeçerlerse; geçmiş kendilerine bağışlanacaktır. Tekrar başlarlarsa evvelkilerin hükmü muhakkak devam etmiş olacaktır."},{"n":39,"t":"Fitne kalmayıp din de yalnız Allah için oluncaya kadar onlarla savaşın. Eğer vazgeçerlerse; muhakkak ki Allah, yaptıklarını görendir."},{"n":40,"t":"Eğer yüz çevirirlerse; o takdirde bilin ki Allah, sizin Mevlanızdır. Ne güzel Mevla, ne güzel yardımcıdır O."},{"n":41,"t":"Eğer Allah’a ve hakkı batıldan ayıran günde, iki topluluğun karşılaştığı o günde kulumuza indirdiğimize inanıyorsanız; bilin ki: Ele geçirdiğiniz ganimetin beşte biri Allah’ın, peygamberin ve yakınlarının, yetimlerin, düşkünlerin ve yolcularındır. Allah, her şeye gücü yetendir."},{"n":42,"t":"Hani siz, o vakit vadinin yakın kenarında idiniz, onlar da öte yamacında idiler. Kervan ise sizden daha aşağıda idi. Eğer bir yerde buluşmak üzere sözleşseydiniz; muhakkak ki vaktini ta’yinde ihtilafa düşerdiniz. Fakat Allah, işlenmesi gerekli olan emri yerine getirmek için yaptı. Ta ki helak olan; apaçık bir delilden dolayı helak olsun, yaşayan da apaçık bir delilden dolayı yaşasın. Ve muhakkak ki Allah; Semi’dir, Alim’dir."},{"n":43,"t":"Hani Allah; uykunda, onları sana az gösteriyordu. Eğer sana onları çok göstermiş olsaydı; elbette çekinecek ve iş hakkında çekişecektiniz. Fakat Allah, sizi kurtardı. Muhakkak ki O; göğüslerde olanı bilendir."},{"n":44,"t":"Hani, karşılaştığınız zaman; Allah, yapılmış bir emri yerine getireceğinden onları gözlerinizde az gösteriyor, sizi de onların gözünde azaltıyordu. Ve işler Allah’a döndürülür."},{"n":45,"t":"Ey iman edenler; bir toplulukla karşılaşırsanız sebat edin ve Allah’ı çok zikredin ki felaha eresiniz."},{"n":46,"t":"Allah’a ve Rasulüne itaat edin. Birbirinizle çekişmeyin. Sonra korkuya kapılırsınız da zaafa düşerseniz ve rüzgarınız gider. Sabredin, muhakkak ki Allah; sabredenlerle beraberdir."},{"n":47,"t":"Hem yurtlarından böbürlenerek ve insanlara gösteriş yaparak çıkan ve Allah yolundan alıkoyanlar gibi olmayın. Allah, onların yaptıklarını çepeçevre kuşatandır."},{"n":48,"t":"Hani şeytan onlara yaptıklarını süslemiş ve demişti ki: Bugün insanlardan sizi yenecek yoktur. Ben de size muhakkak yardımcıyım. İki ordu karşılaşınca da, iki topuğu üstüne kaçarak: Benim sizinle alakam yok, doğrusu sizin görmediklerinizi görüyorum, ben Allah’tan korkuyorum. Çünkü Allah azabı şiddetli olandır, demişti."},{"n":49,"t":"Hani münafıklar, kalblerinde hastalık bulunanlar: Bunları, dinleri aldattı, diyorlardı. Halbuki kim Allah’a tevekkül ederse; muhakkak ki Allah, Aziz’ dir, Hakim’dir."},{"n":50,"t":"Bir görseydin sen; hani melekler, küfredenlerin canlarını alırken yüzlerine ve arkalarına vuruyorlar ve: Tadın yakıcı azabı, diyorlardı."},{"n":51,"t":"İşte bu; ellerinizin yaptığının karşılığıdır. Muhakkak ki Allah; kullarına asla zulmedici değildir."},{"n":52,"t":"Firavun hanedanıyla onlardan öncekilerin gidişi gibi. Allah’ın ayetlerini yalanlamışlardı da, Allah onları günahlarından dolayı yakalamıştı. Muhakkak ki Allah; kuvvetlidir, azabı şiddetli olandır."},{"n":53,"t":"Bunun sebebi; bir topluluk kendi nefislerindekini değiştirmedikçe, Allah’ ın onlara verdiği nimetini değiştirmeyeceğidir. Ve muhakkak ki Allah; Semi’dir, Alim’dir."},{"n":54,"t":"Firavun hanedanıyla, onlardan öncekilerin gidişi gibi. Rabblarının ayetlerini yalanlamışlardı da, Biz de günahlarından dolayı onları helak etmiş ve Firavun hanedanını suda boğmuştuk. Hepsi de zalimlerdi."},{"n":55,"t":"Allah katından yeryüzünde yürüyen canlıların en kötüsü; şüphesiz ki küfredenlerdir. Artık onlar, inanmazlar."},{"n":56,"t":"Onlar, kendileriyle anlaşma yaptığın kimselerdir. Sonra her defasında ahidlerini bozdular. Onlar sakınmazlar da."},{"n":57,"t":"Bunun için eğer savaşta ele geçirirsen; onları dağıt ki arkalarında olanlar ibret alsınlar."},{"n":58,"t":"Eğer bir kavmin hiyanet etmesinden korkarsan; sen de onlara karşı aynı şekilde davran. Muhakkak ki Allah; hainleri sevmez."},{"n":59,"t":"Küfredenler; asla öne geçtiklerini ve bizi aciz bırakacaklarını sanmasınlar."},{"n":60,"t":"Siz de onlara karşı gücünüzün yettiği kadar kuvvet ve bağlanıp beslenen atlar hazırlayın ki bununla Allah’ın düşmanı, sizin düşmanınız ve bunlardan başka sizin bilmeyip te Allah’ın bildiği diğerlerini korkutasınız. Allah yolunda ne harcarsanız, size ödenir ve siz asla zulmolunmazsınız."},{"n":61,"t":"Eğer barışa yanaşırlarsa; sen de yanaş ve Allah’a tevekkül et. Muhakkak ki Semi, Alim, O’dur."},{"n":62,"t":"Eğer seni aldatmak isterlerse; muhakkak ki Allah, sana yeter. Seni ve mü’minleri yardımıyla destekleyen O’dur."},{"n":63,"t":"Ve onların kalblerini birleştirmiştir. Eğer yeryüzünde bulunan her şeyi sarfetsen yine de onların kalblerini birleştiremezdin. Fakat Allah birleştirdi onların arasını. Muhakkak ki Allah; Aziz’dir, Hakim’dir."},{"n":64,"t":"Ey Peygamber; Allah, sana ve sana tabi olan mü’minlere yeter."},{"n":65,"t":"Ey Peygamber; mü’minleri savaşa teşvik et. Eğer sizden sabreden yirmi kişi bulunursa; ikiyüz kişiyi mağlup ederler. Eğer sizden yüz kişi bulunursa; küfretmiş olanlardan binini mağlup ederler. Çünkü onlar, anlamazlar güruhu dur."},{"n":66,"t":"Şimdi Allah yükünüzü hafifletti ve bildi ki; sizde bir zaaf vardır. O halde şayet sizden sabırlı yüz kişi olursa; ikiyüz kişiyi mağlup ederler. Şayet sizden bin kişi olursa; Allah’ın izniyle ikibin kişiyi mağlup ederler. Ve Allah; sabredenlerle beraberdir."},{"n":67,"t":"Hiç bir peygambere yeryüzünde savaşırken zaferler kazanıncaya kadar esirler alması yaraşmaz. Geçici dünya malını istiyorsunuz. Allah ise ahireti istiyor. Ve Allah; Aziz’dir, Hakim’dir."},{"n":68,"t":"Eğer daha önceden Allah’ın geçmiş bir hükmü olmasaydı; aldıklarınızdan dolayı size büyük bir azab dokunurdu."},{"n":69,"t":"Artık elde ettiğiniz ganimetten helal ve temiz olarak yeyin. Allah’tan da sakının. Çünkü Allah; Gafur’dur, Rahim’dir."},{"n":70,"t":"Ey peygamber; elinizdeki esirlere de ki: Eğer Allah kalbinizde hayır olduğunu bilirse; sizden alınandan daha hayırlısını size verir ve sizi bağışlar. Ve Allah, Gafur’dur, Rahim’dir."},{"n":71,"t":"Eğer sana hainlik yapmak isterlerse; daha önce Allah’a da hainlik etmişlerdi de Allah, onlara karşı sana imkan ve kudret vermişti. Ve Allah; Alim’dir, Hakim’dir."},{"n":72,"t":"Muhakkak ki iman edip hicret eden, mallarıyla ve canlarıyla Allah yolunda cihad edenler; barındırıp yardım edenler, işte onlar; birbirinin dostudurlar. İman edip de hicret etmeyenlere gelince; hicret edene kadar sizin onlarla bir dostluğunuz yoktur. Şayet onlar da din hususunda sizden yardım isterlerse; sizinle aralarında muahede bulunan bir kavim aleyhinde olmamak üzere onlara yardım etmek boynunuza borçtur. Allah yaptıklarınızı görendir."},{"n":73,"t":"Küfredenler ise birbirlerinin dostudurlar. Eğer siz bunu yapmazsanız; yeryüzünde bir fitne ve büyük bir fesad olur."},{"n":74,"t":"İman edip hicret edenler, Allah yolunda cihad edenler, barındıranlar ve yardım edenler; işte onlar, gerçek mü’minlerdir. Onlar için mağfiret ve cömertçe verilmiş rızıklar vardır."},{"n":75,"t":"Sonra iman edip de hicret edenler ve sizinle birlikte savaşanlar; işte onlar sizdendir. Hısımlar, Allah’ın kitabına göre birbirine daha yakındırlar. Muhakkak ki Allah, her şeyi bilendir."}],[{"n":1,"t":"Müşriklerden muahede yaptıklarınıza; Allah ve Rasulünden bir ihtardır:"},{"n":2,"t":"Yeryüzünde dört ay daha dolaşın. Ve bilin ki; siz, Allah’ı aciz bırakamazsınız. Hem Allah, gerçekten kafirleri rüsvay edendir."},{"n":3,"t":"Büyük hacc günü, insanlara Allah ve Rasulünden bir ilandır. Muhakkak ki Allah ve Rasulü, artık müşriklerden uzaktır. Eğer tevbe ederseniz; bu, sizin için daha hayırlıdır. Yok eğer yüz çevirirseniz; bilin ki; siz, Allah’ı aciz bırakacak değilsiniz. Küfredenlere elem verici bir azabı müjdele."},{"n":4,"t":"Yalnız muahede yaptığınız müşriklerden, muahede hükümlerinde size karşı bir eksiklik yapmayan ve aleyhinizde kimseye yardım etmeyenler, müstesnadır. O halde anlaşmayı, sonuna kadar tamamlayın. Muhakkak ki Allah, müttakileri sever."},{"n":5,"t":"Haram aylar çıkınca; artık müşrikleri bulduğunuz yerde öldürün. Onları yakalayın ve hapsedin. Her gözetleme yerinde onları bekleyin. Eğer tevbe ederler; namaz kılar, zekat verirlerse; yollarını serbest bırakın. Muhakkak ki Allah; Gafur’dur, Rahim’dir."},{"n":6,"t":"Eğer müşriklerden birisi senden aman dilerse; ona aman ver. Ta ki Allah’ın kelamını dinlesin. Sonra onu emin olacağı yere kadar ulaştır. Bu; onların bilmez bir kavim olmaları sebebiyledir."},{"n":7,"t":"Mescid-i Haram’ın yanında muahede yaptıklarınız müstesna, müşriklerin Allah yanında ve Rasulünün yanında nasıl bir ahdi olabilir ki? Onlar, size doğru davrandıkça siz de onlara karşı doğru davranın. Muhakkak ki Allah; müttakileri sever."},{"n":8,"t":"Nasıl olabilir ki, şayet size üstün gelselerdi; hakkınızda ne yemin, ne de bir vecibe gözetirlerdi. Sizi ağızlarıyla hoşnud etmeye çalışırlar, ama kalbleri dayatır. Ve onların çoğu fasıklardır."},{"n":9,"t":"Onlar, Allah’ın ayetlerini az bir değere değişip O’nun yolundan alıkoydular. Gerçekten onların yapageldikleri şey ne kötüdür."},{"n":10,"t":"Onlar, hiç bir mü’min hakkında bir vecibe veya yemin gözetmezler. İşte onlar, haddi aşanların kendileridir."},{"n":11,"t":"Eğer tevbe ederler, namaz kılarlar ve zekat verirlerse; onlar, artık dinde kardeşlerinizdir. Biz, ayetleri bilir bir kavim için açıklıyoruz."},{"n":12,"t":"Eğer andlaşmalarından sonra yine yeminlerini bozar ve dininize saldırırlarsa; o küfür önderlerini hemen öldürün. Çünkü onların yeminleri yoktur. Belki son verirler."},{"n":13,"t":"Yeminlerini bozan, peygamberi yurdundan çıkarmaya teşebbüs eden bir kavim ile döğüşmez misiniz? Ki, önceleri kendileri başlamışlardır. Onlardan korkar mısınız? Şayet mü’minler iseniz asıl korkmanız gereken; Allah’tır."},{"n":14,"t":"Onlarla savaşın ki Allah, sizin ellerinizle onları azablandırsın, rüsvay etsin ve sizi onlara karşı üstün kılsın ve mü’minler topluluğunun göğüslerini ferahlandırsın."},{"n":15,"t":"Ve kalblerindeki öfkeyi gidersin. Allah; dilediğine tevbe nasib eder. Ve Allah; Alim’dir, Hakim’dir."},{"n":16,"t":"Yoksa siz, içinizden cihad edip Allah’tan, peygamberinden ve mü’minlerden başkasını sırdaş edinmeyenleri ortaya çıkarmadan sizi kendi halinize bırakacak mı sandınız? Allah, işlediklerinizden haberdardır."},{"n":17,"t":"Müşriklerin, kendi küfürlerine kendileri şahid iken; Allah’ın mescidlerini tamir etme hakları yoktur. İşte onların bütün yaptıkları boşa gitmiştir. Ve onlar, ateşte ebedi kalıcıdırlar."},{"n":18,"t":"Allah’ın mescidlerini; ancak Allah’a ve ahiret gününe iman eden, namaz kılan, zekat veren ve Allah’tan başka kimseden korkmayanlar tamir ederler. İşte bunlar, hidayete erenlerden olabilirler."},{"n":19,"t":"Siz; hacılara su vermeyi, Mescid-i Haram’ı tamir etmeyi; Allah’a ve ahiret gününe inanan ve Allah yolunda cihad edenle bir mi tuttunuz? Bunlar, Allah katında bir olamazlar. Ve Allah; zalimler güruhunu hidayete erdirmez."},{"n":20,"t":"Onlar ki iman etmişler, hicret etmişler ve Allah yolunda mallarıyla, canlarıyla cihad etmişlerdir. Derece bakımından Allah katında çok büyüktürler. Ve işte onlar, kurtuluşa erenlerin kendileridir."},{"n":21,"t":"Rabbları onlara; kendinden bir rahmet, hoşnudluk ve içlerinde tükenmez ve ebedi nimetler bulunan cennetleri müjdeler."},{"n":22,"t":"Orada temelli kalıcıdırlar. Muhakkak ki Allah katında büyük mükafat vardır."},{"n":23,"t":"Ey iman edenler; eğer küfrü imana tercih ediyorlarsa, babalarınızı, kardeşlerinizi dostlar edinmeyin. Sizden her kim onları dost edinirse; işte onlar, zalimlerin kendileridir."},{"n":24,"t":"De ki: Eğer babalarınız, oğullarınız, kardeşleriniz, eşleriniz, kabileniz, elinize geçirdiğiniz mallar, durgunluğa uğramasından korktuğunuz ticaret, hoşunuza giden evler, size Allah’tan vve peygamberden ve Allah yolunda cihaddan daha sevimli ise; o zaman Allah’ın emri gelinceye kadar bekleyedurun. Ve Allah; fasıklar güruhunu hidayete erdirmez."},{"n":25,"t":"Andolsun ki; Allah, size birçok yerlerde ve Huneyn gününde yardım etmiştir. Hani, çokluğunuz sizi böbürlendirmişti de size bir faydası olmamıştı. Yeryüzü genişliğine rağmen size dar gelmişti. Sonra gerisin geri dönüp gitmiştiniz."},{"n":26,"t":"Bilahare Allah; Rasulü ile mü’minlerin üzerine sekinetini indirmişti, görmediğiniz orduları da indirmişti. Ve kafirleri azaba uğratmıştı. Kafirlerin cezası buydu."},{"n":27,"t":"Sonra Allah, bunun ardından dilediğinin tevbesini kabul eder. Allah; Gafur’dur, Rahim’dir."},{"n":28,"t":"Ey iman edenler; doğrusu müşrikler ancak necistir. Onun için bu yıllarından sonra Mescid-i Haram’a yaklaşmasınlar. Eğer fakirlikten korkarsanız, Allah dilerse sizi yakında kendi lütfu ile zenginleştirir. Muhakkak ki Allah; Alim’dir, Hakim’dir."},{"n":29,"t":"Kitab verilmiş olanlardan; Allah’a da, ahiret gününe de inanmayan, Allah ve peygamberinin haram kıldığını haram saymayan ve hak din edinmeyenlerle -boyun eğip kendi elleriyle cizye verinceye kadar savaşın."},{"n":30,"t":"Yahudiler dediler ki: Uzeyr Allah’ın oğludur. Hristiyanlar da dediler ki: Mesih Allah’ın oğludur. Bu, onların ağızlarında dolaşan sözlerdir ki, daha önce küfretmiş olanların sözüne benzetiyorlar. Allah onları yok etsin, nasıl da uyduruyorlar."},{"n":31,"t":"Onlar Allah’tan ayrı hahamlarını, rahiblerini rabblar edindiler. Meryem Oğlu Mesih’i de. Halbuki tek tanrıdan başkasına ibadet etmemekle emrolunmuşlardır. O’ndan başka ilah yoktur. O; bunların şirk koştukları şeylerden münezzehtir."},{"n":32,"t":"Allah’ın nurunu ağızlarıyla söndürmek isterler. Halbuki Allah nurunu mutlaka tamamlayacaktır. İsterse kafirler hoşlanmasınlar."},{"n":33,"t":"Dinini bütün dinlere üstün kılmak için; Rasulünü hidayet ve hak din ile gönderen O’dur. İsterse müşrikler hoşlanmasınlar."},{"n":34,"t":"Ey iman edenler; doğrusu hahamlar ve rahiblerin çoğu insanların malını haksızlıkla yerler. Ve Allah yolundan alıkoyarlar. Altını ve gümüşü biriktirip de onları Allah yolunda harcamayanlara; işte onlara pek acıklı bir azabı müjdele."},{"n":35,"t":"O gün cehennem ateşinde bunların üzeri kızdırılır ve bunlarla onların alınları, böğürleri ve sırtları dağlanır. İşte bu, kendiniz için biriktirdiğiniz, tadın biriktirmiş olduğunuzu, denir."},{"n":36,"t":"Doğrusu ayların sayısı; gökleri ve yeri yarattığı günden beri Allah’ın kitabında oniki aydır. Bunlardan dördü haram olanlardır. İşte doğru din budur. O halde bunlardan nefislerinize zulmetmeyin. Müşrikler sizinle nasıl toplu olarak savaşıyorlarsa, siz de onlarla tolu olarak savaşın. Ve bilin ki; muhakkak Allah, müttakilerle beraberdir."},{"n":37,"t":"Nesi; ancak küfürde bir artıştır. Onunla kafirler şaşırtılırlar. Bunu bir yıl helal, bir yıl haram sayarlar ki, Allah’ın haram kıldığına sayıca uysunlar da Allah’ın haram ettiğini helal kılmış olsunlar. Böylece onların amellerinin kötülüğü kendilerine süslenip güzel gösterildi. Allah; kafirler güruhunu hidayete erdirmez."},{"n":38,"t":"Ey iman edenler; size ne oldu ki: Allah yolunda elbirliği ile savaşa çıkın, denildiği zaman, yere çakılıp kaldınız. Yoksa ahireti bırakıp da dünya hayatına mı razı oldunuz? Halbuki dünya hayatının geçimi ahiretin yanında pek azdır."},{"n":39,"t":"Eğer elbirliği ile çıkmazsanız; sizi elim bir azabla azablandırır ve yerinize sizden başka bir kavim getirir. Siz ona hiç bir şeyle zarar veremezsiniz. Allah, her şeye Kadir’dir."},{"n":40,"t":"Eğer siz ona yardım etmezseniz; doğrusu Allah, ona yardım etmişti. Hani kafirler onu çıkarmışlardı da, o ikinin ikinicisydi. Hani onlar mağarada idiler ve hani o, arkadaşına; üzülme, Allah bizimledir, diyordu. Bunun üzerine Allah, ona sekinetini indirmişti, onu sizin görmediğiniz ordularla desteklemişti. Ve küfretmiş olanların sözünü alçaltmıştı. Allah’ın kelimesi ise en yüce olandır. Allah; Aziz’dir, Hakim’dir."},{"n":41,"t":"Gerek hafif, gerekse ağırlıklı olarak elbirliğiyle çıkın, mallarınız ve nefisleriniz ile cihad edin. Eğer bilirseniz bu; sizin için daha hayırlıdır."},{"n":42,"t":"Eğer kolay bir kazanç ve orta bir sefer olsaydı; elbette senin arkana düşerlerdi. Fakat zorluk onlara uzak geldi. Gücümüz yetseydi; herhalde biz de sizinle beraber çıkardık, diye yemin edeceklerdir. Kendilerini helak ederler. Allah biliyor ki; onlar muhakkak yalancılardır."},{"n":43,"t":"Allah seni affetsin. Doğrular sana besbelli olup yalancıları bilmeden önce neden onlara izin verdin?"},{"n":44,"t":"Allah’a ve ahiret gününe iman edenler, geri kalmak için senden izin istemezler ki mallarıyla ve canlarıyla cihad etsinler. Allah, müttakileri bilir."},{"n":45,"t":"Senden; ancak, Allah’a ve ahiret gününe inanmayanlar ve kalbleri şüpheye düşüp, şüphelerinde bocalayanlar izin isterler."},{"n":46,"t":"Eğer onlar çıkmak isteselerdi; elbette bunun için hazırlık yaparlardı. Fakat Allah, onların davranışlarını çirkin gördü de kendilerini alıkoydu. Ve: Oturun oturanlarla beraber, denildi."},{"n":47,"t":"Eğer onlar da aranızda çıksalardı size şer ve fesadı arttırmaktan başka bir şey yapmazlar ve aranıza muhakkak bir fitne sokmak isteyerek koşarlardı. İçinizde onlara iyice kulak verenler de var. Allah; zalimleri çok iyi bilendir."},{"n":48,"t":"Andolsun ki, onlar daha önce de fitne aramışlar ve sana karşı bir takım işler çevirmişlerdi. Nihayet Hak geldi ve onlar istemedikleri halde Allah’ın emri zahir oldu."},{"n":49,"t":"Onlardan kimi de: Bana izin ver, beni fitneye düşürme, der. İyi bilin ki; onlar fitne içine düşmüşlerdir. Ve muhakkak ki cehennem, kafirleri çepeçevre kuşatıcıdır."},{"n":50,"t":"Eğer sana bir iyilik erişirse; bu onları fenalaştırır. Bir kötülük erişirse de derler ki: Biz, daha önceden tedbirimizi almışızdır. Ve sevinerek dönüp giderler."},{"n":51,"t":"De ki: Allah’ın bizim için yazdığından başkası bize erişmez. O, bizim Mevlamızdır. Onun için mü’minler Allah’a tevekkül etsinler."},{"n":52,"t":"De ki: Bize iki güzelliğin birinden başka bir şeyin gelmesini mi bekliyorsunuz? Halbuki biz, Allah’ın kendi katından veya bizim elimizle size bir azab getireceğini bekliyoruz. Öyleyse bekleyin, doğrusu biz de sizinle beraber bekleyenlerdeniz."},{"n":53,"t":"De ki: Gerek istekli, gerek isteksiz olarak infak edin, nasıl olsa kabul edilmeyecektir. Çünkü siz, gerçekten fasıklık eden bir kavim oldunuz."},{"n":54,"t":"Verdiklerinin onlardan kabul edilmesini engelleyen şudur: Onlar, Allah’a ve Rasulüne küfretmişlerdir. Namaza tembel tembel gelirler ve mallarını da istemeye istemeye infak ederler."},{"n":55,"t":"Artık onların malları da çocukları da seni imrendirmesin. Doğrusu Allah, ancak bununla onlara dünya hayatında azab etmeyi ve kafirler olarak canlarının çıkmasını ister."},{"n":56,"t":"Ve Allah’a yemin ederler ki; gerçekten sizinledirler. Halbuki onlar, sizinle değildirler. Ancak korkak bir kavimdirler."},{"n":57,"t":"Eğer sığınılacak bir yer, yahut mağaralar veya bir delik bulsalardı; çabucak oraya yönelirlerdi."},{"n":58,"t":"İçlerinden kimi de sadakalar hakkında sana dil uzatırlar. Eğer kendilerine verilirse hoşlanırlar, verilmezse hemen kızarlar."},{"n":59,"t":"Şayet onlar, Allah’ın ve peygamberinin kendilerine verdiklerinden hoşnud olsalardı da: Bize Allah yeter, yakında bize bol nimetinden verir, Rasulü’ de. Biz, ancak Allah’a rağbet edenleriz, demiş olsalardı."},{"n":60,"t":"Sadakalar, Allah’tan bir farz olarak; ancak fakirler, miskinler, sadaka üzerinde memur olanlar, kalbleri ısındırılanlar, köleler, borçlular, Allah yolunda olanların ve yolda kalanların uğruna sarfedilir. Ve Allah; Alim’ dir, Hakim’dir."},{"n":61,"t":"Onlardan kimileri de; o, her şeye kulak kesiliyor, diyerek peygambere eziyyet ederler. De ki: O, sizin için bir hayır kulağıdır. Allah’a inanır, mü’minlere inanır. Ve aranızda iman etmiş olanlara rahmettir. Allah’ın Rasulüne eziyyet verenler için elem verici bir azab vardır."},{"n":62,"t":"Sizi hoşnud etmek için Allah’a yemin ederler. Halbuki Allah ve Rasulü hoşnud etmeye daha layıktır. Eğer mü’min idiyseler."},{"n":63,"t":"Bilmezler mi ki: Kim, Allah’a ve Rasulüne karşı koymaya kalkışırsa; muhakkak ona, içinde ebedi kalacağı cehennem ateşi vardır. İşte bu, en büyük rüsvaylıktır."},{"n":64,"t":"Münafıklar; üzerlerine kalblerinde olanı haber verecek bir surenin indirilmesinden çekiniyorlar. De ki: Siz alay edin bakalım, Allah çekindiğinizi ortaya çıkarandır."},{"n":65,"t":"Şayet onlara soracak olursan, diyeceklerdir ki: Andolsun ki biz, dalmış oyalanıyorduk. De ki: Allah ile, O’nun ayetleri ve peygamberleri ile mi alay ediyorsunuz?"},{"n":66,"t":"Mazeret beyan etmeyin, gerçekten siz, inanmanızdan sonra küfrettiniz. İçinizden bir topluluğu affetsek bile, mücrimler oldukları için bir topluluğa azab ederiz."},{"n":67,"t":"Münafık erkeklerle, münafık kadınlar birbirlerindendirler. Münkeri emreder ve ma’rufu nehyederler. Ellerini sımsıkı tutarlar. Onlar Allah’ı unuttular; O da onları unuttu. Muhakkak ki münafıklar; fasıkların kendileridir."},{"n":68,"t":"Allah; münafık erkeklerle, münafık kadınlara ve kafirlere cehennem ateşini vaadetmiştir. Orada temelli kalıcıdırlar. Bu, onlara yeter. Ve Allah; onlara la’net etmiştir. Onlara, sürekli bir azab vardır."},{"n":69,"t":"Sizden öncekiler gibi. Onlar kuvvet bakımından sizden daha yaman, mallar ve çocuklar bakımından çoktular. Onlar hisselerince bundan faydalandılar. Sizden öncekiler hisselerince faydalandıkları gibi, siz de hissenizce ondan faydalandınız ve onların daldığı gibi siz de daldınız. İşte onların yaptıkları dünyada da, ahirette de boşa gitmiştir. Ve onlar, hüsrana uğrayanların kendileridir."},{"n":70,"t":"Onlara kendilerinden öncekilerin, Nuh, Ad ve Semud kavminin, İbrahim kavminin, Medyen ve altüst olmuş şehirler halkının haberleri gelmedi mi? Peygamberi onlara apaçık delillerle gelmişlerdi. Allah, onlara zulmediyor değildi. Ama onlar, kendilerine zulmediyorlardı."},{"n":71,"t":"Mü’min erkekler ve mü’min kadınlar; birbirlerinin velileridirler. Ma’rufu emreder, münkerden nehyederler. Namaz kılarlar, zekat verirler, Allah’a ve Rasulüne itaat ederler. İşte Allah, bunlara rahmet edecektir. Muhakkak ki Allah; Aziz’dir, Hakim’dir."},{"n":72,"t":"Allah mü’min erkeklere ve mü’min kadınlara, içinde temelli kalacakları ve altından ırmaklar akan cennetleri vaadetti. Ve Adn cennetlerinde çok güzel meskenler de. Allah tarafından bir hoşnudluk ise daha büyüktür. En büyük kurtuluş işte budur."},{"n":73,"t":"Ey peygamber; kafirler ve münafıklar ile cihad et ve onlara karşı çetin ol. Onların varacakları yer, cehennemdir ve o, ne kötü dönüş yeridir."},{"n":74,"t":"And olsun ki, müslüman olduktan sonra inkar edip küfür sözünü söylemişler iken, söylemedik diye Allah’a yemin ettiler, başaramayacakları bir şeye giriştiler; Allah ve peygamberi bol nimetinden onları zenginleştirdi ve öç almaya kalktılar. Eğer tevbe ederlerse iyiliklerine olur; şayet yüz çevirirlerse, Allah onları dünya ve ahirette can yakıcı azaba uğratır. Ve onlar için yeryüzünde bir dost ve yardımcı yoktur."},{"n":75,"t":"İçlerinden kimi de: Eğer bize lütuf ve kereminden ihsan ederse; andolsun ki, muhakkak tasadduk edeceğiz ve muhakkak salihlerden olacağız, diye Allah’a ahdetmişlerdi."},{"n":76,"t":"Ama Allah onlara lütuf ve kereminden ihsan edince; cimrilik ettiler ve yüz çevirdiler. Onlar zaten dönektirler."},{"n":77,"t":"Allah’a verdikleri vaadi tutmadıkları ve yalanı adet edindikleri için, kendisinin huzuruna çıkacakları güne kadar Allah kalblerine nifak soktu."},{"n":78,"t":"Bilmezler mi ki; Allah, onların içlerinden gizlediklerini de, fısıltılarını da bilir. Ve Allah, gaybları çok iyi bilendir."},{"n":79,"t":"Sadaka vermekte gönülden davranan mü’minlere dil uzatan ve güçlerinin yetebildiğinden başkasını bulamayanlarla eğlenenleri Allah maskaraya çevirir. Ve onlar için elim bir azab vardır."},{"n":80,"t":"Onlar için ister mağfiret dile, ister mağfiret dileme. Onlar için yetmiş defa mağfiret dilesen de Allah onları bağişlamayacaktır. Bu, Allah’ı ve Peygamberini inkar etmelerindendir. Allah; fasıklar güruhunu hidayete erdirmez."},{"n":81,"t":"Allah’ın peygamberine muhalefet için geri kalanlar, oturup kalmalarına sevindiler. Allah yolunda mallarıyla, canlarıyla cihad etmek hoşlarına gitmedi. Bu sıcakta savaşa çıkmayın, dediler. De ki: Cehennem ateşi daha sıvaktır. Keşke bilselerdi."},{"n":82,"t":"Artık yaptıklarının cezası olarak az gülsünler, çok ağlasınlar."},{"n":83,"t":"Allah, seni onlardan bir topluluğa geri döndürür de; senden savaşa çıkmak için izin isterlerse; de ki: Benimle hiç bir zaman çıkmayacaksınız. Benim yanımda hiç bir düşmanla savaşmayacaksınız. Çünkü siz, baştan oturup kalmaya razı oldunuz. Artık siz, geri kalanlarla birlikte oturun."},{"n":84,"t":"Onlardan ölen hiç birinin namazını asla kılma, kabrinin başında durma. Çünkü onlar, Allah’a ve Rasulüne küfrettiler ve fasıklar olarak öldüler."},{"n":85,"t":"Onların malları ve çocukları seni imrendirmesin. Allah; bunlarla, ancak onlara dünyada azab etmeyi ve kafir oldukları halde canlarının zorla çıkmasını diler."},{"n":86,"t":"Allah’a iman edin, Rasulü ile birlikte cihad edin, diye bir sure indirildiğinde; içlerinden gücü yetenler senden izin isteyip: Bizi bırak da oturanlarla birlikte kalalım, derler."},{"n":87,"t":"Geri kalanlarla birlikte oturmaya razı oldular. Kalblerine mühür vurulmuştur onların. Bu yüzden onlar iyice anlamazlar."},{"n":88,"t":"Fakat peygamber ve onunla iman etmiş olanlar; mallarıyla, canlarıyla cihad ettiler. Bütün hayırlar, işte onlarındır. Ve işte onlar, felaha erenlerin kendileridir."},{"n":89,"t":"Onlar için Allah; içinde ebedi kalacakları ve altından ırmaklar akan cennetler hazırladı. İşte bu, en büyük kurtuluştur."},{"n":90,"t":"Bedevilerden özür beyan edenler, kendilerine izin verilsin diye geldiler. Allah’a ve Rasulüne yalan söyleyenler ise oturup kaldı. İçlerinden küfretmiş olanlara elim bir azab isabet edecektir."},{"n":91,"t":"Zayıflara, hastalara ve harcayacak şeyleri bulunmayanlara, Allah’a ve Rasulüne sadık kaldıkça bir sorumluluk yoktur. İhsan edenleri hesaba çekmeye de bir yol yoktur. Allah; Gafur’dur, Rahim’dir."},{"n":92,"t":"Kendilerine binek vermen için sana geldiklerinde: Size bir binek bulamıyorum, dediğin zaman, infak edecek bir şey bulamadıkları için üzüntüden gözleri yaşararak geri dönenlere de bir sorumluluk yoktur."},{"n":93,"t":"Sorumluluk ancak, zengin oldukları halde senden izin isteyen, geride kalan kadınlarla bulunmaya razı olanlara ve Allah kalblerini mühürlemiş olduğu için bilmeyenleredir."},{"n":94,"t":"Kendilerine döndüğünüz vakit de size özür beyan ederler. De ki: Özür dilemeyin. Size katiyyen inanmıyorum. Doğrusu Allah, bize haberlerinizi bildirmiştir. Allah da, Rasulü de amellerimizi görecektir. Sonra hepiniz, görüleni de görülmeyeni de bilene döndürüleceksiniz. O, size neler yaptığınızı haber verecektir."},{"n":95,"t":"Kendilerine döndüğünüz zaman; onlardan vazgeçmeniz için Allah’a yemin edeceklerdir. Öyleyse onlardan yüz çevirin. Çünkü murdardırlar. Yaptıklarının karşılığı olarak varacakları yer, cehennemdir."},{"n":96,"t":"Size yemin ederler ki; kendilerinden hoşnud olasınız. Siz, onlardan hoşnud olsanız da şüphesiz ki Allah, fasıklar güruhundan hoşnud olmaz."},{"n":97,"t":"Bedeviler; küfür ve nifak bakımından daha yaman ve Allah’ın peygamberine indirdiğinin hududunu bilmemeye daha müsaittirler. Ve Allah; Alim’dir, Hakim’dir."},{"n":98,"t":"Bedevilerden öyleleri de vardır ki; infak edeceğini angarya sayar ve sizin başınıza belalar gelmesini bekler. Belalar kendi başlarına olsun. Va Allah; Semi’dir, Alim’dir."},{"n":99,"t":"Bedevilerden öyleleri de vardır ki; Allah’a ve ahiret gününe inanır, infak ettiğini Allah katında yakınlığa ve peygamberin duasına nail olmaya vesile sayar. Bilin ki; bunlar kendileri için gerçek bir yakınlıktır. Allah, onları rahmetine girdirecektir. Muhakkak ki Allah; Gafur’dur, Rahim’ dir."},{"n":100,"t":"Muhacirlerden, ensardan en ileri ve önde gelenlerle, ihsan ile onlara uyanlardan Allah razı olmuştur. Onlar da Allah’tan hoşnuddurlar. Hem onlara altından ırmaklar akan cennetler hazırlamıştır. Orada temelli kalıcıdırlar. İşte budur en büyük kurtuluş."},{"n":101,"t":"Çevrenizdeki Bedevilerden münafıklar vardır. Medine halkından da. Ki onlar nifak üzerinde diretirler. Siz bilmezsiniz onları, Biz biliriz. Onlara iki kere azab edeceğiz. Sonra da onlar; daha büyük bir azaba döndürüleceklerdir."},{"n":102,"t":"Diğer bir kısımı da günahlarını itiraf ettiler. Onlar iyi ameli kötü ile karıştırdılar. Onlar ki, Allah onların tevbelerini kabul eder. Muhakkak ki Allah; Gafur’dur, Rahim’dir."},{"n":103,"t":"Onların mallarından sadaka al ki, bununla onları temizleyip arıtmış olasın. Ve onlara dua et. Şüphesiz ki senin duan onlar için bir sükunettir. Allah; Semi’dir, Alim’dir."},{"n":104,"t":"Bilmezler mi ki; Allah, muhakkak kullarından tevbeyi kabul edecek ve sadakaları alacak olanın kendisidir. Ve muhakkak ki Allah, Tevvab ve Rahim’dir."},{"n":105,"t":"De ki: İşleyiniz, Allah Rasulü ve mü’minler işlediklerinizi görecektir. Ve görüleni de, görülmeyeni de bilene döndürüleceksiniz. O, size neyi işlediğinizi bildirecektir."},{"n":106,"t":"Diğer bir kısmı da Allah’ın emrine bırakılmışlardır; ya onlara azab eder veya tevbelerini kabul eder. Allah; Alim’dir, Hakim’dir."},{"n":107,"t":"Zarar vermek, küfretmek, mü’minlerin arasını açmak ve daha evvel Allah’a, peygamberine karşı savaşan kişiyi beklemek ve gözetlemek üzere bir mescid edinenler: Biz iyilikten başka bir şey istemedik, diye yemin ederler. Allah şehadet eder ki; onlar hiç şüphesiz yalancılardır."},{"n":108,"t":"Orada asla durma. İlk gününden takva üzerine kurulmuş olan mescid, içinde durmana daha uygundur. Orada temizlenmek isteyen adamlar vardır. Allah, temizlenmek isteyenleri sever."},{"n":109,"t":"Binasını Allah korkusu ve rızası üzerine kuran kimse mi daha hayırlıdır, yoksa binasını bir yar kenarına kurup da onunla birlikte kendisini de cehennem ateşine yuvarlanan kimse mi? Allah, zalimler güruhunu hidayete erdirmez."},{"n":110,"t":"Kalbleri paralayıncaya kadar kurdukları bina kalblerinde kuşku kaynağı olmaya devam edecektir. Allah; Alim’dir, Hakim’dir."},{"n":111,"t":"Muhakkak ki Allah, mü’minlerin mallarını ve canlarını, karşılığı cennet olmak üzere satın almıştır. Onlar, Allah yolunda savaşırlar; öldürürler ve öldürülürler. Tevrat’da, İncil’de ve Kur’an’da kendi üzerine hak bir vaaddir. Kim Allah’tan daha çok ahdini yerine getirebilir? Öyleyse yaptığınız alış-verişe sevinin. En büyük kurtuluş işte budur."},{"n":112,"t":"Tevbe edenler, ibadet edenler, hamd edenler, seyahat edenler, rüku’ edenler, secde edenler, ma’rufu emredenler, münkeri nehyedenler, Allah’ın hududunu koruyanlardır. Mü’minleri müjdele."},{"n":113,"t":"Cehennem ashabı oldukları muhakkak meydana çıktıktan sonra, akraba bile olsalar, müşrikler için mağfiret dilemek peygambere ve mü’minlere yaraşmaz."},{"n":114,"t":"İbrahim’in babası için mağfiret dilemesi; sadece ona verdiği bir vaadden dolayı idi. Ama onun Allah’ın düşmanı olduğu kendisine belli olunca; ondan uzaklaştı. Muhakkak ki İbrahim, çok içli ve halim idi."},{"n":115,"t":"Allah bir kavmi hidayete erdirdikten sonra; sakınacakları şeyleri onlara açıklamadıkça dalalete düşürmez. Muhakkak ki Allah; her şeyi bilendir."},{"n":116,"t":"Göklerin ve yerin mülkü Allah’ındır. Öldürür ve diriltir. Sizin için Allah’tan başka bir dost ve yardımcı da yoktur."},{"n":117,"t":"Andolsun ki Allah, Peygamberin ve güçlük anında ona uyan muhacir ve ensarın tevbelerini kabul etti. İçlerinden bır kısmının kalbleri kaymak üzere iken yine de onların tevbesini kabul buyurdu. Çünkü O, kendilerine Rauf ve Rahim’dir."},{"n":118,"t":"Geri bırakılan üç kişiye de yeryüzü bütün genişliğine rağmen dar gelmiş ve nefisleri kendilerini sıkıştırmıştı da, Allah’tan başka sığınacak hiç bir şey olmadığını anlamışlardı. Sonra onları da eski hallerine dönsünler diye tevbeye muvaffak kıldı. Muhakkak ki Allah; Tevvab, Rahim olandır."},{"n":119,"t":"Ey iman edenler; Allah’tan korkun ve sadıklarla beraber olun."},{"n":120,"t":"Gerek Medine’liler için, gerekse onların çevresinde bulunan Bedeviler için; Allah’ın peygamberinden geri kalmak, kendilerini ona tercih etmek yaraşmaz. Çünkü Allah yolunda susuzluk, yorgunluk, açlık, kafirleri kızdıracak bir yere ayak basmak ve düşmana karşı başarı kazanmak karşılığında; onlara mutlaka bir salih amel yazılır. Muhakkak ki Allah, ihsan edenlerin mükafatını zayi etmez."},{"n":121,"t":"Onlar, küçük veya büyük nafaka olarak ne infak ederlerse, ne kadar yol giderler ve bir vadi geçerlerse; mutlaka onların lehine yazılır ki Allah yaptıklarının en güzeli ile mükafatlandırsın."},{"n":122,"t":"Mü’minlerin hepsi de seferber olacak değildirler. Her topluluktan bir taifenin dinini iyi öğrenmek ve kendisine döndüklerinde kavmini uyarmak üzere geri kalmaları gerekmez mi? Olur ki kaçınırlar. 9"},{"n":123,"t":"Ey iman edenler; kafirlerden size yakın olanlarla savaşın. Ve onlar sizde sertlik görsünler. Ve bilin ki; Allah, muhakkak müttakilerle beraberdir."},{"n":124,"t":"Bir sure indirilince; onlardan kimi: Bu, hanginizin imanını artırdı? der. İman etmiş olanlara gelince; onların imanını artırmıştır. Ve onlar, birbirleri ile müjdeleşirler."},{"n":125,"t":"Kalblerinde hastalık bulunanların ise, murdarlıklarına murdarlık katmıştır. Ve kafir olarak ölmüşlerdir."},{"n":126,"t":"Onlar görmezler mi ki; her yıl bir veya iki kere belalara çarpılıyorlar da yine tevbe etmiyorlar. Ve ibret almıyorlar."},{"n":127,"t":"Bir sure indiği zaman; birbirlerine bakarlar ve: Sizi bir kimse görüyor mu? der, sonra dönüp giderler. Allah, onların kalblerini döndürmüştür. Çünkü onlar, anlamazlar güruhudur."},{"n":128,"t":"Andolsun ki; size kendinizden bir peygamber gelmiştir. Sıkıntıya uğramanız kendisine ağır gelir. Sizin üzerinize düşkündür, mü’minlere rauf ve rahim’ dir."},{"n":129,"t":"Eğer yüz çevirirlerse; de ki: Allah, bana yeter. O’ndan başka hiç bir ilah yoktur. Ben O’na tevekkül ettim ve O, büyük Arş’ın Rabbıdır."}],[{"n":1,"t":"Elif, Lam, Ra. Bunlar hikmetli kitabın ayetleridir."},{"n":2,"t":"İçlerinden bir adama: İnsanları uyar ve iman edenlere Rabbları katında yüksek bir makam olduğunu müjdele, diye vahyettiğimiz insanların tuhafına mı gitti ki kafirler: Bu, apaçık bir büyüdür, dediler."},{"n":3,"t":"Doğrusu sizin Rabbınız, gökleri ve yeri altı günde yaratıp sonra Arş’a hükmeden Allah’tır. İşi düzenler. İzni olmadıktan sonra kimse şefaat edemez. İşte Rabbınız Allah budur. O’na kulluk edin. Öğüt dinlemez misiniz?"},{"n":4,"t":"Hepinizin dönüşü O’nadır. Allah’ın vaadi haktır. Doğrusu O, yaratmaya başlar, sonra iman edip iyi amel işleyenlere adaletle karşılık vermek için onu tekrar eder. Küfredenlere de; küfreder olmalarından dolayı kaynar sudan bir içki ve elem verici bir azab vardır."},{"n":5,"t":"Güneşi ziya ayı nur yapan, yılların sayısını ve hesabı bilmeniz için aya konak yerleri düzenleyen O’dur. Allah, bunları ancak hak ile yaratmıştır. Bilen insanlar için ayetlerini uzun uzadıya açıklar."},{"n":6,"t":"Gece ile gündüzün değişmesinde; Allah’ın göklerde ve yerde yarattıklarında, sakınan bir kavim için ayetler vardır."},{"n":7,"t":"Muhakkak ki Bize kavuşmayı ummayanlar, dünya hayatından hoşnud olup ona bağlananlar ve ayetlerimizden habersiz bulunanlar;"},{"n":8,"t":"İşte kazanır olduklarından dolayı onların varacakları yer, cehennemdir."},{"n":9,"t":"Muhakkak ki iman edip salih amellerde bulunanları; Rabbları imanlarına karşılık doğru yola eriştirir. Na’im cennetlerinde altlarından ırmaklar akar."},{"n":10,"t":"Oradaki duaları: Münezzehsin Allah’ım; dirlik temennileri: Selam sizedir; dualarının sonu ise: Hamd alemlerin Rabbı olan Allah’a mahsusdur."},{"n":11,"t":"Eğer Allah insanlara hayrı çarçabuk istedikleri gibi, şerri de süratle verseydi, süreleri hemen bitmiş olurdu. İşte Biz, Bize kavuşmayı ummayanları böyle azgınlıkları içinde bocalamaya terkederiz."},{"n":12,"t":"İnsan bir sıkıntıya düşünce; yan gelip yattığı veya ayakta bulunduğu anlarda Bize yalvarıp yakarır. Biz, sıkıntısını giderince de; karşılaştığı sıkıntıdan ötürü Bize hiç yalvarmamışa döner. Böylece aşırı gidenlere işledikleri hoş görünür."},{"n":13,"t":"Andolsun ki; sizden önce nice nesilleri zulmettikleri zaman helak ettik. Peygamberleri onlara apaçık delillerle geldikleri halde, onlar inanmamışlardı. İşte Biz, suçlu kavmi böyle cezalandırırız."},{"n":14,"t":"Sonra onların ardından sizi, nasıl davranacağınıza bakmak için yeryüzünde onların yerine getirdik."},{"n":15,"t":"Ayetlerimiz onlara açık açık okununca; Bizimle karşılaşmayı ummayanlar: Bundan başka bir Kur’an getir veya bunu değiştir, dediler. De ki: Onu kendiliğimden değiştirmem olmaz. Ben, ancak bana vahyolunana uyarım. Ben, Rabbıma karşı gelirsem; büyük bir günün azabından korkarım."},{"n":16,"t":"De ki: Allah dileseydi; ben, onu size okumazdım. Ve size hiç bildirmezdim. Daha önce yıllarca aranızda bulundum. Hiç düşünmüyor musunuz?"},{"n":17,"t":"Allah’a karşı yalan uyduran veya ayetlerini yalanlayanlardan daha zalim kim olabilir? Suçlular muhakkak ki felaha ermezler."},{"n":18,"t":"Onlar Allah’ı bırakarak; kendilerine fayda da, zarar da vermeyen şeylere taparlar. Bunlar, Allah katında bizim şefaatçılarımızdır, derler. De ki: Siz, Allah’a göklerde ve yerde bilmediği bir şey mi bildiriyorsunuz? Allah, onların ortak koşmalarından münezzeh ve yücedir."},{"n":19,"t":"İnsanlar tek bir ümmetten başka bir şey değildir. Sonradan ayrılığa düştüler. Eğer Rabbından daha önce bir söz geçmemiş olsaydı; ayrılığa düştükleri şeyler hakkında hüküm çoktan verilmiş olurdu."},{"n":20,"t":"Ona Rabbından bir ayet indirlmeli değil miydi? derler. De ki: Gayb; ancak Allah’a aittir. Bekleyin, doğrusu ben de sizinle birlikte bekleyenlerdenim."},{"n":21,"t":"Kendilerine dokunan sıkıntılardan sonra insanlara bir rahmet tattırdığımızda; hemen ayetlerimize düzen kurmaya çalışırlar. De ki: Düzen kurmada Allah en hızlıdır. Elçilerimiz de kurduğunuz düzenleri hiç şüphesiz yazmaktadırlar."},{"n":22,"t":"Sizi karada ve denizde yürüten O’dur. Gemide bulunduğunuzda geminin onları hoş bir rüzgarla götürdüğünde ve onunla sevindiklerinde; birden şiddetli bir kasırga gelip onları her taraftan dalgaların sardığı ve çepeçevre kuşatıldıklarını sandıkları anda, Allah’ın dinine sarılarak: Bizi bu tehlikeden kurtarırsan; andolsun ki, şükredenlerden oluruz, diye O’na yalvarırlar."},{"n":23,"t":"Allah onları kurtarınca; hemen yeryüzünde haksız yere taşkınlıklara başlarlar. Ey insanlar; yaptığınız taşkınlık aleyhinize, dünya hayatının eğlencesidir. Sonra dönüşünüz, Bizedir. Biz de yapmış olduğunuzu size bildiririz."},{"n":24,"t":"Dünya hayatının misali; sadece gökten indirdiğimiz su gibidir. Onunla, insan ve hayvanların yiyerek beslendikleri bitkiler bol bol yetişir; yeryüzü renk renk, çeşit çeşit masullerle süslenir. Ve yerin sahibleri bütün bunlara kadir olduklarını sandıkları sırada; geceleyin veya gündüzün emrimiz geliverirde orayı hiç birşey bitirmemişe çeviririz. Daha dün birşey yokmuş gibi olur. İşte Biz, ayetlerimizi düşünen insanlar için böylece açıklarız."},{"n":25,"t":"Ve Allah selam yurduna çağırır ve dilediğini dosdoğru yola iletir."},{"n":26,"t":"Güzel davrananlara daha güzeli ve fazlası var. Onların yüzleri ne kararır ne de zilletten kızarır. Onlar cennetin yaranıdırlar. Orada temelli kalacaklardır."},{"n":27,"t":"Kötülükleri kazananlara; kötülükleri kadar ceza verilir. Onların yüzlerini zillet bürür. Allah’a karşı onları savunacak kimse yoktur. Yüzleri, geceden de kara bir parçayla örtülmüş gibidir. İşte bunlar da ateşin yaranıdırlar. Orada temelli kalacaklardır."},{"n":28,"t":"O gün hepsini toplarız. Şirk koşanlara; Siz ve koştuğunuz ortaklar yerlerinize, deriz. Artık onların arasını açmışızdır. Ortakları derler ki: Bize tapmıyordunuz."},{"n":29,"t":"Allah, sizinle bizim aramızda şahid olarak yeter. Sizin tapınmanızdan haberimiz yoktur."},{"n":30,"t":"İşte orada herkes önceden yapmış olduğunu bilir. Gerçek mevlaları olan Allah’a döndürülürler. Uydurdukları şeyler ise kendilerinden kaybolup gider."},{"n":31,"t":"De ki: Gökten ve yerden size rızık veren kimdir? Kulak ve gözlere kim hükmeder? Diriyi ölüden çıkaran, ölüyü de diriden çıkaran kimdir? Her işi düzenleyen kimdir? Onlar: Allah’tır, diyecekler. O halde O’na karşı gelmekten sakınmaz mısınız? de."},{"n":32,"t":"İşte gerçek Rabbınız olan Allah budur. Haktan sonra dalaletten başka ne vardır? O halde nasıl çevriliyorsunuz?"},{"n":33,"t":"Böylece, fasık olanların iman etmeyeceklerine dair Rabbının sözü gerçekleşti."},{"n":34,"t":"De ki: Ortaklarınız içinde önce yaratan, sonra bunu tekrar eden var mıdır? De ki: Allah önce yaratır, sonra bunu tekrar eder. Nasıl da döndürülüyorsunuz?"},{"n":35,"t":"De ki: Sizin ortaklarınız içinde; hakka ileten var mıdır? De ki: Allah hakka eriştirir. Hakka eriştiren mi, yoksa götürülmeden gidemeyen mi uyulmaya daha layıktır. Ne oluyor size, nasıl hükmediyorsunuz?"},{"n":36,"t":"Onların çoğu, sadece zanna tabi olurlar. Şüphe yok ki zann, hakikat karşısında bir şey ifade etmez. Doğrusu Allah, onların bütün işlediklerini bilendir."},{"n":37,"t":"Bu Kur’an, Allah’tan başkası tarafından uydurulmuş değildir. Ancak kendinden evvel geleni tasdik eder ve kitabı uzun uzun açıklar. Onda hiç şüphe yoktur. Alemlerin Rabbındandır."},{"n":38,"t":"Yoksa: Onu uydurdu mu? diyorlar. De ki: Sadıklardan iseniz, onun benzeri bir sure getirin. Ve Allah’tan başka çağırabileceklerinizi de çağırın."},{"n":39,"t":"Hayır, onlar bilgisini kavrayamadıkları, yorumu kendilerine gelmemiş bir şeyi yalanladılar. Onlardan öncekiler de böyle yalanlamışlardı. Zalimlerin sonunun nasıl olduğuna bir bak."},{"n":40,"t":"İçlerinden kimisi buna iman eder, kimisi de iman etmez. Rabbın fesad çıkaranları daha iyi bilir."},{"n":41,"t":"Şayet seni yalanlarlarsa; benim yaptığım bana, sizin yaptığınız sizedir. Siz benim yaptığımdan uzaksınız, ben de sizin yaptığınızdan uzağım, de."},{"n":42,"t":"İçlerinde sana kulak verenler vardır. Fakat sen sağırlara işittirebilir misin? Üstelik akılları da hiç ermiyorsa."},{"n":43,"t":"İçlerinde sana bakanlar da vardır. Körlere sen mi yol göstereceksin? Üstelik hiç görmüyorlarsa."},{"n":44,"t":"Doğrusu Allah insanlara hiç zulmetmez, ama insanlar kendilerine zulmederler."},{"n":45,"t":"O gün, onları sanki dünyada gündüzün sadece bir saat kalmışlar gibi toplayınca; birbirlerini tanırlar. Allah’a kavuşmayı yalan sayanlar ziyana uğramışlardır. Zaten onlar, hidayete ermişler de değillerdi."},{"n":46,"t":"Onlara vaadettiğimizin bir kısmını sana gösteririz veya seni alırız. Onların dönüşü bizedir. Allah onların yaptıklarına şahiddir."},{"n":47,"t":"Her ümmetin bir rasulü vardır. Onların rasulleri gelince aralarında adaletle hükmedilir. Ve asla zulme uğratılmazlar."},{"n":48,"t":"Derler ki: Doğru sözlülerden iseniz bu vaad ne zamanmış?"},{"n":49,"t":"De ki: Allah’ın dilemesi dışında, ben; kendime bir fayda ve zarar verecek durumda değilim. Her ümmet için bir sure vardır. Sureleri gelince; ne bir an geciktirilir, ne de öne alınırlar."},{"n":50,"t":"De ki: Görmüyor musunuz, ya Allah’ın azabı size gece veya gündüz gelirse? Suçlular neden bunu acele istiyorlar?"},{"n":51,"t":"Gerçekleştikten sonra mı ona inanacaksınız? Hemen şimdi mi. Hani siz onu acele istiyordunuz."},{"n":52,"t":"Sonra zulmetmiş olanlara denilir ki: Sürekli azabı tadın. Yalnız kazanır olduğunuz şeylerle cezalandırılmıyor musunuz?"},{"n":53,"t":"O gerçek mi? diye senden haber sorarlar. De ki: Rabbıma andolsun ki o, muhakkak gerçektir. Elbette siz, O’nu aciz bırakacaklar değilsiniz."},{"n":54,"t":"Yeryüzünde bulunan her şey, nefsine zulmeden kimsenin olsaydı, onu fidye verirdi. Azabı gördükleri zaman içlerinde pişmanlık duyarlar. Halbuki onlar haksızlığa uğratılmadan aralarında adaletle hükmolunmuştur."},{"n":55,"t":"Dikkat edin, göklerde ve yerde ne varsa hepsi Allah’ındır. Dikkat edin, Allah’ın vaadi şüphesiz bir gerçektir. Fakat onların çoğu bunu bilmezler."},{"n":56,"t":"Dirilten ve öldüren O’dur. O’na döneceksiniz."},{"n":57,"t":"Ey insanlar; size Rabbınızdan bir öğüt, gçğüslerde olana bir şifa, mü’minler için bir hidayet ve rahmet gelmiştir."},{"n":58,"t":"De ki: Bunlar Allah’ın lütfu ve rahmeti iledir. Sadece bunlarla sevinsinler. O, bütün toplayıp yığdıklarından daha hayırlıdır."},{"n":59,"t":"De ki: Allah’ın size gönderdiği, sizin de bazılarını haram, bazılarını da helal kıldığınız rızıklar hakkında ne dersiniz? De ki: Allah mı size izin verdi, yoksa Allah’a iftira mı ediyorsunuz?"},{"n":60,"t":"Allah’a karşı yalan uyduranlar, kıyamet gününü ne sanıyorlar? Doğrusu Allah, insanlar hakkında lütuf sahibidir. Fakat onların çoğu şükretmezler."},{"n":61,"t":"Ne işte bulunsan, Kur’an’dan ne okusan ve siz ne iş yaparsanız; yaptıklarınıza daldığınızda mutlaka Biz üzerinizde şahidiz. Yerde ve gökte hiç bir zerre Rabbından gizli değildir. Bundan daha küçüğü de, daha büyüğü de şüphesiz apaçık kitabdadır."},{"n":62,"t":"Dikkat edin, Allah dostlarında hiç bir korku yoktur. Onlar, mahzun da olacak değillerdir."},{"n":63,"t":"Onlar ki iman edip takvaya ermişlerdir."},{"n":64,"t":"Onlar için dünya hayatında da, ahirette de müjde vardır. Allah’ın sözleri değişmez. Bu, büyük kurtuluşun kendisidir."},{"n":65,"t":"Onların sözleri seni üzmesin. Muhakkak ki izzet, bütünüyle Allah’ındır. O, Semi’dir, Alim’dir."},{"n":66,"t":"Dikkat edin; göklerde kim varsa ve yerde kim varsa, hepsi Allah’ındır. Allah’tan başkasına tapanlar, gerçekte Allah’a koştukları ortaklara tabi olmuyorlar, onlar bir takım zannlara uyuyor ve ancak yalan söylüyorlar."},{"n":67,"t":"O’dur size geceyi dinlenesiniz diye karanlık ve gündüzü çalışasınız diye aydınlık kılan. Kulak veren bir kavim için bunlarda ayetler vardır."},{"n":68,"t":"Allah, çocuk edindi, dediler. Haşa, Allah bundan münezzehtir. O, müstağnidir. Göklerde ve yerde ne varsa hepsi O’nundur. Bu hususta hiç bir deliliniz yok. Allah hakkında bilmediğiniz şeyi mi söylüyorsunuz?"},{"n":69,"t":"De ki: Allah hakkında yalan uyduranlar hiç şüphesiz felah bulmayacaklardır."},{"n":70,"t":"Dünyada biraz faydalanma vardır. Sonra dönüşleri Bizedir. Sonra Biz de küfreder olmalarından dolayı onlara şiddetli azabı tattıracağız."},{"n":71,"t":"Onlara Nuh’un haberini oku. Hani Nuh, kavmine demişti ki: Ey kavmim; aranızda kalmam, Allah’ın ayetlerini hatırlatmam, onlarla öğüt vermem size ağır geliyorsa; ben, Allah’a tevekkül ettim. Siz ve ortaklarınız toplanıp ne yapacağınızı kararlaştırın, içinizde ne tasarlıyorsanız açığa çıkarın, sonra bana mühlet de vermeyerek yapacağınızı yapın."},{"n":72,"t":"Yüz çevirirseniz; zaten ben sizden öğütlerimin karşılığı olarak bir ücret istemedim. Benim ücretim ancak Allah’a aittir. Ben, müslümanlardan olmakla emrolundum."},{"n":73,"t":"Onu yalanladılar; ama Biz, onu ve gemide beraberinde bulunanları kurtardık. Bunları yeryüzünün halifeleri yaptık. Ayetlerimizi yalanlayanları ise suda boğduk. Bir bak uyarılanların sonu nice oldu."},{"n":74,"t":"Sonra onun arkasından peygamberleri kavimlerine gönderdik. Onlara apaçık ayetylerle geldiler. Fakat önceden yalanladıkları için inanmadılar. Aşırı gidenlerin kalblerini işte böylece mühürleriz."},{"n":75,"t":"Bunlardan sonra Musa ile Harun’u ayetlerimizle Firavun’a ve erkanına gönderdik. İnanmayı kibirlerine yediremediler. Zaten günahkar bir topluluktular."},{"n":76,"t":"Tarafımızdan kendilerine hak geldiği vakit; doğrusu bu, apaçık bir büyüdür, dediler."},{"n":77,"t":"Musa dedi ki: Hak size geldiğinde mi böyle söylersiniz? Bu mudur büyü? Halbuki büyücüler felah bulmazlar."},{"n":78,"t":"Dediler ki: Siz ikiniz; bizi, babalarımızı üzerinde bulduğumuz yoldan çevirmek ve yeryüzünün büyükleri olmak için mi geldiniz? Biz, size inanmıyoruz."},{"n":79,"t":"Firavun: Bütün bilgin büyücüleri bana getirin, dedi."},{"n":80,"t":"Sihirbazlar gelince, Musa onlara: Atacağınızı atın, dedi."},{"n":81,"t":"Onlar atacaklarını atınca; Musa dedi ki: Bu sizin yaptığınız sihirdir, Allah onu boşa çıkaracaktır. Allah, elbette fesadçıların işini düzeltmez."},{"n":82,"t":"Ve suçlular istemese de Allah, hakkı sözleriyle gerçekleştirir."},{"n":83,"t":"Firavun ve erkanının kendilerine fenalık yapmasından korktuklarından, kavminin bir kısım gençleri dışında kimse Musa’ya iman etmedi. Çünkü Firavun, yeryüzünde çok ululanan ve gerçekten aşırı gidenlerdendi."},{"n":84,"t":"Musa dedi ki: Ey kavmim, eğer siz, gerçekten Allah’a iman etmişseniz ve müslüman olmuşsanız; artık O’na tevekkül edin."},{"n":85,"t":"Onlar da dediler ki: Biz, Allah’a tevekkül ettik. Ey Rabbımız, bizi, o zalimler güruhu ile sınama."},{"n":86,"t":"Merhametinle o kafirler güruhundan bizi kurtar."},{"n":87,"t":"Musa ve kardeşine de vahyettik ki: Mısır’da kavminiz için evler hazırlayın; evlerinizi namazgah edinin namaz kılın. Ve mü’minlere müjdele."},{"n":88,"t":"Musa dedi ki: Rabbımız, doğrusu sen Firavun’a ve erkanına bu dünyada hayatında süsler ve mallar verdin. Rabbımız; Senin yolundan insanları saptırsınlar diye mi? Rabbımız; mallarını yok et, onların kalblerini sık. Çünkü onlar, elim azabı görmedikçe iman etmezler."},{"n":89,"t":"Allah: ikinizin de duası kabul olundu. İkiniz de doğru yolda devam edin ve sakın bilmezlerin yolunu tutmayın, buyurdu."},{"n":90,"t":"İsrailoğullarına da denizi geçirdik. Firavun ve askerleri haksızlık ve düşmanlıkla ardlarına düştüler. Firavun boğulacağı anda: İsrailoğullarının iman ettiğinden başka tanrı olmadığına inandım. Artık ben de müslümanlardanım, dedi."},{"n":91,"t":"Şimdi mi inandın? Daha önce baş kaldırmış ve bozgunculardan olmuştun."},{"n":92,"t":"Senden sonrakilere ayet olman için bu gün senin cesedini kurtaracağız, dedik. Doğrusu insanların çoğu ayetlerimizden gafildirler."},{"n":93,"t":"Biz, İsrailoğullarını güzel bir yere yerleştirmiştik. Onlara tertemiz şeylerden rızıklar verdik. Kendilerine ilim gelinceye kadar hiç ihtilafa düşmediler. Şüphesiz Rabbın, kıyamet günü aralarındaki ihtilaflar hakkında hükmünü verecektir."},{"n":94,"t":"Sana indirdiklerimizden şüphe ediyorsan; senden önce indirdiğimiz kitabları okuyanlara sor. Andolsun ki; sana Rabbından hak gelmiştir. Sakın şüpheye düşenlerden olma."},{"n":95,"t":"Sakın Allah’ın ayetlerini yalan sayanlardan olma, yoksa hüsrana uğrayanlardan olursun."},{"n":96,"t":"Doğrusu, üzerlerine Rabbının sözü hak olanlar inanmazlar."},{"n":97,"t":"Onlara her türlü ayet gelse bile elem verici azabı görünceye kadar."},{"n":98,"t":"İman edip imanı kendisine fayda sağlayan bir kasaba olsaydı ya? Yunus’un kavmi müstesna. Onlar, iman ettikleri zaman üzerlerinden bu dünya hayatında rüsvaylık azabını kaldırdık, bir zamana kadar da kendilerini faydalandırdık."},{"n":99,"t":"Eğer Rabbın dileseydi; yeryüzündeki insanların hepsi iman ederdi. Öyleyse sen mi insanları mü’min olmaları için zorlayacaksın."},{"n":100,"t":"Allah’ın izni olmadan hiç kimse iman edemez. Ve o, pisliği akledemeyenlerin üzerine kılar."},{"n":101,"t":"De ki: Göklerde ve yerde neler var, bir bakın. Fakat bunca ayetler ve uyarılar inanmayanlar güruhuna fayda vermez."},{"n":102,"t":"Kendilerinden önce geçenlerin başlarına gelen günler gibisinden başkasını mı bekliyorlar? De ki: Bekleyin, ben de sizinle beraber beklemekteyim."},{"n":103,"t":"Sonra Biz, peygamberlerimizi ve iman edenleri kurtarırız. Böylece üstümüze bir hak olarak mü’minleri kurtaracağız."},{"n":104,"t":"De ki: Ey insanlar; benim dinimden şüphede iseniz, ben Allah’tan başka taptıklarınıza tapmam. Ancak, sizi öldürecek olan Allah’a kulluk ederim. Ben, mü’minlerden olmakla emrolundum."},{"n":105,"t":"Ve yüzünü tevhid dinine döndür, sakın müşriklerden olma diye."},{"n":106,"t":"Allah’ı bırakıp da sana ne fayda, ne de zarar getirmeyecek olan şeylere tapma. Eğer böyle yapacak olursan; şüphesiz zalimlerden olursun."},{"n":107,"t":"Allah sana bir sıkıntı verirse; onu yine ancak Allah giderir. Sana biri iyilik dilediği takdirde; onun lütfunu geri çevirecek de yoktur. O, bunu kullarından dilediğine verir. O, Gafur’dur, Rahim’dir."},{"n":108,"t":"De ki: Ey insanlar; size Rabbınızdan hak gelmiştir. Artık kim hidayeti kabul ederse; o, ancak kendi faydası için hidayete ermiş, kim de saparsa; kendi zararına sapmış olur. Ben, sizin başınıza bir bekçi değilim."},{"n":109,"t":"Sana vahyedilene uy. Allah hükmünü verinceye kadar sabret. O, hüküm verenlerin en hayırlısıdır."}],[{"n":1,"t":"Elif, Lam, Ra. Bu kitab, ayetleri kesinleştirilmiş, sonra da Hakim ve Habir olan Allah tarafından uzun uzadıya açıklanmıştır."},{"n":2,"t":"Allah’tan başkasına kulluk etmeyesiniz diye. Muhakkak ki ben, size O’nun katından gönderilmiş bir uyarıcı ve müjdeciyim."},{"n":3,"t":"Rabbınızdan mağfiret dileyin, sonra O’na tevbe edin ki, belli bir süreye kadar sizi güzelce geçindirsin. Her lütuf sahibine lütfunu versin. Eğer yüzçevirirseniz; o zaman ben, başınıza gelecek büyük bir günün azabından korkarım."},{"n":4,"t":"Dönüşünüz ancak Allah’a dır. Ve O, her şeye Kadir’dir."},{"n":5,"t":"Dikkat edin, onlar peygambere düşmanlıklarını gizlemek için iki büklüm olurlar. Elbiselerine büründükleri zaman da dikkat edin. Allah, onların gizlediklerini ve açığa vurduklarını bilir. Çünkü O, göğüslerde olanı bilendir."},{"n":6,"t":"Yeryüzünde yürüyen hiç bir canlı yoktur ki, rızkı Allah’a ait olmasın. Onların durup dinlenecek ve saklanacak yerlerini de O bilir. Hepsi apaçık kitabdadır."},{"n":7,"t":"Hanginizin daha güzel ameli olduğunu denemek için; gökleri ve yeri altı günde yaratan O’dur. Zaten Arş’ı su üstünde idi. Andolsun ki; ölümden sonra muhakkak siz yine dirileceksiniz, desen; küfredenler mutlaka: Bu, apaçık bir büyüden başka bir şey değildir, diyeceklerdir."},{"n":8,"t":"Sayılı bir müddete kadar üzerlerinden azabı erteleyecek olsak mutlaka: Bunu alıkoyan da ne? derler. Dikkat edin, o geldiği gün, onlardan asla dönmeyecek, alaya aldıkları şey onları mahvedecektir."},{"n":9,"t":"Biz, insana tarafımızdan bir rahmet tattırır, sonra onu geri alırsak; andolsun ki o, pek ümitsiz, pek nankör olur."},{"n":10,"t":"Şayet başına gelen bir sıkıntıdan sonra ona bir nimet tattırırsak; kötülükler başımdan gitti der, şımarır ve öğünür."},{"n":11,"t":"Sadece sabredip de güzel ameller işleyenlere; işte onlara mağfiret ve büyük ecir vardır."},{"n":12,"t":"Belki de sen; ona bir hazine indirilmeli veya yakında bir melek gelmeli değil miydi? demelerinden ötürü sana vahyolunanların bir kısmını terkedecek olursun. Sen, ancak bir uyarıcısın. Ve Allah; her şeye Vekil’dir."},{"n":13,"t":"Yoksa: Onu kendisi uydurdu mu? diyorlar. De ki: Eğer doğru söylüyorsanız; haydi onun surelerine benzer uydurma on sure meydana getirin. Allah’tan başka çağırabileceklerinizi de çağırın."},{"n":14,"t":"Size cevab veremezlerse bilin ki; o, ancak Allah’ın ilmiyle indirilmiştir. Ve O’ndan başka ilah yoktur. Hala müslüman olmuyor musunuz?"},{"n":15,"t":"Kim, dünya hayatını ve onun süsünü isterse; onlara amellerinin karşılığını burada tamamen öderiz. Onlar bu hususta hiç bir zarara da uğratılmazlar."},{"n":16,"t":"Onlar, öyle kimselerdir ki; ahirette kendilerine ateşten başka bir şey yoktur. İşledikleri ameller boşa gitmiştir. Yapageldikleri zaten batıldır."},{"n":17,"t":"Rabbından açık bir delil üzerinde bulunan, ardınca da Rabbı tarafından bir şahid gelen, ondan önce de Musa’nın imam ve rahmet olan kitabını tasdik eden kimse, başkaları gibi midir? İşte onlar; Kur’an’a inanırlar. Herhhangi bir güruh onu inkar ederse; onun varacağı yer ateştir. Bundan şüphen olmasın. Doğrusu o, Rabbın tarafından gelen bir gerçektir, ama insanların çoğu inanmazlar."},{"n":18,"t":"Allah’a karşı yalan uyduranlardan daha zalim kim vardır? Bunlar Rabblarının huzuruna götürülürler ve şahidler: Rabblarına yalan uyduranlar bunlardır, derler. Bilin ki; Allah’ın laneti zalimlerin üzerinedir."},{"n":19,"t":"Onlar ki Allah yolundan alıkorlar. Ve o yolu eğriltmeye çalışırlar. Ve ahireti inkar edenler de onlardır."},{"n":20,"t":"Bunlar, yeryüzünde aciz bırakacak olanlar değillerdir. Allah’a karşı duracak yardımcıları da yoktur. Onların azabı kat kat olacaktır. Onlar, işitmeye tahammül edemez ve göremezlerdi de."},{"n":21,"t":"Kendilerini kayba uğratanlar, işte bunlardır. Uydurdukları şeyler de kendilerinden kaybolup gitmiştir."},{"n":22,"t":"Şüphesiz ahirette büsbütün kayba uğrayanlar da bunlardır."},{"n":23,"t":"Doğrusu inanan, salih ameller işleyen ve Rabblarına boyun eğenler; işte onlardır cennetlik olanlar. Orada ebediyyen kalacaklardır."},{"n":24,"t":"Bu iki zümrenin durumu kör ve sağır kimse ile gören ve işiten kimsenin durumuna benzer. İkisi bir olur mu hiç? Hala ibret almıyor musunuz?"},{"n":25,"t":"Gerçekten Nuh’u da kavmine göndermiştik. Ben, sizin için apaçık bir uyarıcıyım."},{"n":26,"t":"Allah’tan başkasına ibadet etmeyin. Doğrusu ben, hakkınızda acıklı bir günün azabından korkuyorum."},{"n":27,"t":"Bunun üzerine kavminden küfredenlerin elebaşları dediler ki: Biz, senin ancak kendimiz gibi bir insan olduğunu görüyoruz. İçimizde sadece ayak takımının, başlangıçta düşünmeden sana uydukları gözümüzün önündedir. Sizin bize üstün bir meziyyetinizi görmüyoruz. Aksine biz, sizi yalancılar sanıyoruz."},{"n":28,"t":"Nuh dedi ki: Ey kavmim; eğer Rabbım tarafından bir delilim bulunur ve O, katından bana ihsan eder de bunlar sizden gizli kalırsa; onu istemediğiniz halde size zorla mı kabul ettireceğiz?"},{"n":29,"t":"Ey kavmim: buna karşılık olarak sizden hiç bir mal istemiyorum. Benim ücretim yalnız Allah’a aittir. İnananları da kovacak değilim. Çünkü onlar, Rabblarına kavuşacaklardır. Ne var ki ben; sizi, cahil bir kavim olarak görüyorum."},{"n":30,"t":"Ey kavmim; ben, onları kovarsam; beni, Allah’a karşı kim savunur? Hala düşünemiyor musunuz?"},{"n":31,"t":"Ben, size: Allah’ın hazineleri yanımdadır, demiyorum. Gaybı da bilmem. Meleğim de demiyorum. Hor gördüklerinize Allah iyilik vermeyecektir de demiyorum. İçlerinde olanı en iyi bilen Allah’tır. Yoksa ben de zalimlerden olurum."},{"n":32,"t":"Onlar dediler ki: Ey Nuh; bizimle tartıştın, çok uğraştın, doğru sözlü isen haydi tehdid ettiğin şeyi getir."},{"n":33,"t":"Dedi ki: Onu size dilediği takdirde ancak Allah getirir. Ve siz, O’nu asla aciz bırakamazsınız."},{"n":34,"t":"Allah, sizi azdırmak isterse; ben size öğüt vermek istesem de faydası olmaz, Rabbınız O’dur. O’na döndürüleceksiniz."},{"n":35,"t":"Yoksa: «onu kendiliğinden uydurdu» mu derler? De ki: Ben bunu uydurduysam vebali banadır. Oysa ben, sizin işlediğiniz günahlardan tamamen uzağım."},{"n":36,"t":"Nuh’a vahyolundu ki: Senin kavminden iman edenlerden başkası asla inanmayacaktır. Bunun için onların işlediklerine üzülme."},{"n":37,"t":"Gözetimimiz altında ve vahyimizle gemiyi yap. Zulmedenler için Bana bir şey söyleme. Çünkü onlar, suda boğulacaklardır."},{"n":38,"t":"Gemiyi yapmaya başladı. Kavminin ileri gelenleri yanına uğradıkça onunla eğlenirlerdi. O da dedi ki: Bizimle alay ediyorsunuz ama, sizin alay ettiğiniz gibi biz de sizinle alay edeceğiz."},{"n":39,"t":"Rüsvay edici azabın kime geleceğini sürekli azabın kime ineceğini göreceksiniz."},{"n":40,"t":"Nihayet buyruğumuz gelip sular kaynamaya başlayınca: Her cinsten birer çifti ve hakkında hüküm verilmiş olanın dışında kalan çoluk çocuğunu ve inananları gemiye al, dedik. Zaten onunla beraber pek az kimse inanmıştı."},{"n":41,"t":"Nuh dedi ki: Ona binin, onun akıp gitmesi de durması da Allah’ın adıyladır. Rabbım muhakkak Gafur ve Rahim’dir."},{"n":42,"t":"Dağlar gibi dalgaların içinde onları götürürken Nuh bir kenarda ayrı kalmış oğluna: Bizimle beraber gel, küfredenlerle birlikte olma, diye seslendi."},{"n":43,"t":"O: Dağa sığınırım, beni sudan kurtarır, deyince; Nuh: Bu gün Allah’ın rahmetine erişenden başkası için Allah’ın buyruğundan kurtuluş yoktur, dedi. Ve aralarına dalga girdi, o da boğulanlardan oldu."},{"n":44,"t":"Denildi ki: Ey yer suyunu çek, Ey gök, sen de tut, su çekildi, iş de bitti. Gemi Cudi’ye oturdu. Zalimler güruhu Allah’ın rahmetinden uzak olsun, denildi."},{"n":45,"t":"Nuh Rabbına yakardı ve: Ey Rabbım; oğlum benim ailemdendi, ama Senin vaadin haktır. Ve sen; hakimlerin en iyi hükmedenisin, dedi."},{"n":46,"t":"Buyurdu ki: Ey Nuh; o senin ailenden değildir. Çünkü kötü bir iş işlemiştir. Öyleyse bilmediğin şeyi Benden isteme. Cahillerden olmaman için sana öğüt veriyorum."},{"n":47,"t":"Rabbım; bilmediğim şeyi Senden istemekten Sana sığınırım. Beni bağışlamaz ve yarlıgamazsan; hüsrana uğrayanlardan olurum, dedi."},{"n":48,"t":"Ey Nuh; bizim katımızdan selametle in. Sana ve seninle beraber olan ümmetlere hayır ve bereketler olsun. Ama öyle ümmetler var ki; onları bir süre geçindireceğiz. Sonra onlara can yakıcı bir azab vereceğiz, denildi."},{"n":49,"t":"İşte bunlar, gayb haberlerindendir ki sana vahyediyoruz. Ne sen, ne de kavmin daha önce bunları bilemezdiniz. Öyleyse sabret, çünkü akıbet müttakilerindir."},{"n":50,"t":"Ad’a kardeşleri Hud’u gönderdik. O dedi ki: Ey kavmim; Allah’a ibadet edin, O’ndan başka ilahınız yoktur, yoksa sadece yalan uyduran kimseler olursunuz."},{"n":51,"t":"Ey kavmim; ben sizden bunun için bir ücret istemiyorum. Benim ücretim, yalnız beni yaratana aittir. Aklınız ermiyor mu?"},{"n":52,"t":"Ey kavmim; Rabbınızdan mağfiret dileyin, sonra O’na tevbe edin ki size gökten bol bol yağmur göndersin, kuvvetinize kuvvet, katsın. Ve suçlular olarak dönmeyin."},{"n":53,"t":"Dediler ki: Ey Hud; sen bize apaçık bir burhanla gelmedin, senin sözünden dolayı ilahlarımızı terkedemeyiz ve sana inanmayız."},{"n":54,"t":"İlahlarımızdan biri seni fena çarpmış, demekten başka bir şey de söylemeyiz. Dedi ki: Doğrusu ben, Allah’ı şahid tutuyorum. Siz de şahid olun ki; sizin Allah’tan başka şirk koştuğunuz şeylerden, ben uzağım."},{"n":55,"t":"Hepiniz birlikte tuzak kurun bana. Sonra da hiç müsade etmeyin."},{"n":56,"t":"Ben, sadece benim de, sizin de Rabbınız olan Allah’a tevekkül ettim. Yürüyen hiç bir canlı yoktur ki; O, alnından tutmasın. Elbette dosdoğru yol üzeredir benim Rabbım."},{"n":57,"t":"Yüz çevirirseniz; bilin ki: Ben, size neyi bildirmek için gönderildimse onları bildirdim. Rabbım, yerinize sizden başka bir kavim de getirebilir. Ve siz, O’na bir şey yapamazsınız. Doğrusu Rabbım, her şeye Hafiz’dir."},{"n":58,"t":"Emrimiz gelince; Hud’u ve beraberindeki mü’minleri tarafımızdan bir rahmetle kurtardık. Onları katı bir azabtan kurtardık."},{"n":59,"t":"Ad da, Rabblarının ayetlerini bile bile inkar ettiler. Peygamberlerine isyan ettiler. Ve her inadçı zorbanın emrine uydular."},{"n":60,"t":"Bu dünyada da, kıyamet gününde de la’nete uğradılar. Bilin ki: Ad, Rabblarını inkar ettiler. Ve yine bilin ki; Hud’un kavmi Ad, Allah’ın rahmetinden uzaklaştı."},{"n":61,"t":"Semud’a da kardeşleri Salih’i, Ey kavmim; Allah’a kulluk edin, sizin O’ndan başka tanrınız yoktur. O’dur sizi yeryüzünden yaratıp orayı i’mar etmenizi isteyen. Mağfiret dileyin O’ndan, sonra da tevbe edin. Şüphesiz Rabbım, size yakındır, kabul edendir, dedi."},{"n":62,"t":"Dediler ki: Ey Salih, aramızda bundan önce kendisinden iyilik beklenmiş kimseydin sen. Şimdi kalkıp da babalarımızın taptıklarına tapmaktan bizi vazgeçirmek mi istiyorsun? Doğrusu, bizi çağırdığın şeyden şüphe ve endişe içindeyiz."},{"n":63,"t":"Dedi ki: Ey kavmim; Rabbımdan açık bir delilim olur, bana rahmet eder ve ben de O’na baş kaldırırsam; söyleyin bakalım, beni Allah’a karşı kim savunur? Bana hüsrandan başka bir şey kazandırmazsınız."},{"n":64,"t":"Ey kavmim; bu, size bir ayet olarak Allah’ın yarattığı dişi devedir, bırakın onu da Allah’ın toprağında otlasın. Ona kötü maksadla dokunmayın. Yoksa siz, pek yakın bir azaba uğrarsınız."},{"n":65,"t":"Buna rağmen onu kesip devirdiler. O zaman: Yurdunuzda üç gün daha kalın. Bu; yalanlanmayacak bir sözdür, dedi."},{"n":66,"t":"Emrimiz gelince; Salih’i ve beraberindeki mü’minleri, tarafımızdan bir rahmet ile azabdan ve o günün rüsvaylığından kurtardık. Doğrusu Rabbın; Kavi’dir, Aziz’dir."},{"n":67,"t":"Zulmedenleri bir çığlık tuttu. Oldukları yerde diz üstü çöküverdiler."},{"n":68,"t":"Sanki orada hiç yaşamamışlardı. Bilin ki; Semud, Rabblarını inkar etmişlerdi. Ve yine bilin ki; Semud, Allah’ın rahmetinden uzaklaştı."},{"n":69,"t":"Elçilerimiz İbrahim’e müjdelerle gelmiş: Selam, demişlerdi de o; Selam, demiş ve beklemeden onlara kızartılmış bir buzağı ikram etmişti."},{"n":70,"t":"Ellerinin ona uzanmadığını görünce, durumlarını beğenmedi ve içine korku düştü. Korkma, biz Lut kavmine gönderildik, dediler."},{"n":71,"t":"Hanımı ayakta idi. Bunun üzerine güldü. Biz de ona İshak’ı, İshak’ın ardından Ya’kub’u müjdeledik."},{"n":72,"t":"Vay başıma gelenler, ben mi doğuracağım? Ben kocamış biri, şu erim de bir ihtiyar iken. Doğrusu bu, şaşılacak bir şey, dedi."},{"n":73,"t":"Dediler ki: Allah’ın işine mi şaşarsın ey evin hanımı? Allah’ın rahmeti ve bereketleri sizin üzerinizedir. Muhakkak ki O, Hamid’dir, Mecid’dir."},{"n":74,"t":"İbrahim’in korkusu geçipte müjde kendisine ulaşınca; Lut kavmi hakkında bizimle tartışmaya girişti."},{"n":75,"t":"Doğrusu İbrahim; yumuşak huylu, çok içli ve kendisini Allah’a vermiş bir kimseydi."},{"n":76,"t":"Ey İbrahim; bundan vazgeç, zira Rabbının fermanı gelmiştir. Onlara muhakkak geri çevirilmeyecek bir azab gelmektedir."},{"n":77,"t":"Elçilerimiz Lut’a gelince; onların gelmelerinden endişeye düştü, çok sıkıldı ve: İşte bu çok çetin bir gündür, dedi."},{"n":78,"t":"Kavmi ona koşa koşa geldi. Daha önce de kötü işler işlerlerdi. Ey kavmim; işte kızlarım, bunlar sizin için daha temizdir. Allah’tan korkun da misafirlerin önünde beni rezil etmeyin. İçinizde aklı erer bir kimse yok mudur? dedi."},{"n":79,"t":"Dediler ki: Senin kızlarınla bizim bir ilgimizin olmadığını biliyorsun. Sen ne istediğimizi bilirsin."},{"n":80,"t":"Keşke size yetecek bir kuvvetim olsaydı. Veya sağlam bir yere sığınsaydım dedi."},{"n":81,"t":"Dediler ki: Ey Lut; biz Rabbının elçileriyiz. Onlar sana ilişemeyecekler. Bir ara geceleyin ailenle birlikte yola çık. Karının dışında kimse geri kalmasın. Doğrusu onların başına gelecek olan, onun da başına gelecektir. Onların başına gelecek sabahleyindir. Daha sabah yakın değil mi?"},{"n":82,"t":"Emrimiz gelince; oranın üstünü altına getirdik ve üzerine yığın yığın sert taşlar yağdırdık."},{"n":83,"t":"Ki bu taşlar, Rabbının katında işaretlenmiştir. Bunlar zalimlerden hiç bir zaman uzak olmayacaktır."},{"n":84,"t":"Medyen’e de kardeşleri Şuayb’ı. Dedi ki: Ey kavmim; Allah’a kulluk edin, O’ndan başka ilahınız yoktur. Ölçüyü tartıyı eksik tutmayın. Ben sizi, iyi bir halde, refah içinde görüyorum. Ve sizi azabla kuşatacak bir günden korkuyorum."},{"n":85,"t":"Ey kavmim; ölçüyü ve tartıyı yerine getirin. İnsanlara eşyalarını eksik vermeyin, yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın."},{"n":86,"t":"İman ediyorsanız; Allah’ın geri bıraktığı sizin için daha hayırlıdır. Sonra ben, sizin üzerinizde bir koruyucu da değilim."},{"n":87,"t":"Dediler ki: Ey Şuayb; senin namazın mı bize babalarımızın taptıklarını ve mallarımızı dilediğimiz gibi kullanmamızı men’ediyor? Sen, doğrusu aklı başında, yumuşak huylu birisin."},{"n":88,"t":"Dedi ki: Ey kavmim; ben Rabbımdan apaçık bir delil üzere iken O, bana kendisinden güzel bir rızık ihsan etmişse; ne dersiniz? Size yasakladığım şeylere aykırı hareket etmek istemem. Gücümün yettiği kadar islah etmekten başka bir isteğim yoktur. Başarım; ancak Allah’tadır. O’na tevekkül ettim ve O’na yöneliyorum."},{"n":89,"t":"Ey kavmim; bana karşı gelmeniz; Nuh kavminin, Hud kavminin, Salih kavminin başına gelen felaketin benzerini, sakın başınıza getirmesin. Lut kavmi de sizden pek uzak değildir."},{"n":90,"t":"Rabbınızdan mağfiret dileyin, sonra da tevbe edin O’na. Doğrusu benim Rabbım, Rahim’dir, Vedud’dur."},{"n":91,"t":"Dediler ki: Ey Şuayb; söylediklerinin çoğunu anlamıyor ve seni aramızda cidden zayıf görüyoruz. Taraftarların olmasaydı, seni taşlardık. Esasen sen, bizim yanımızda şerefli kimse de değilsin."},{"n":92,"t":"Dedi ki: Ey kavmim; benim taraftarlarım size göre Allah’tan daha mı üstün ki O’na sırt çevirdiniz? Doğrusu Rabbım, sizin yaptıklarınızı kuşatmıştır."},{"n":93,"t":"Ey kavmim; elinizden geleni yapın. Doğrusu ben de yapacağım. Kime rüsvay edecek bir azabın geleceğini ve kimin yalancı olduğunu bileceksiniz. Gözetletin, doğrusu ben de sizinle beraber gözetleyenlerdenim."},{"n":94,"t":"Emrimiz gelince; Şuayb’ı ve beraberindeki inananları, katımızdan bir rahmet ile kurtardık. Zulmedenleri de korkunç bir ses yakaladı ve oldukları yerde diz üstü çöküverdiler."},{"n":95,"t":"Sanki orada hiç yaşamamışlardı. Bilin ki; Semud da Medyen de Allah’ın rahmetinden uzaklaştı."},{"n":96,"t":"Andolsun ki Musa’yı, ayetlerimizle ve apaçık bir delille Firavun’a ve erkanına gönderdik."},{"n":97,"t":"Yine de onlar Firavun’un emrine uydular. Oysa Firavun’un emri hiç de doğru değildi."},{"n":98,"t":"O, kıyamet gününde kavmine öncülük eder ve onları ateşe götürür. Ne kötü yerdir onların gittikleri yer."},{"n":99,"t":"Hem burada, hem de kıyamet gününde la’nete uğratıldılar. Kendilerine verilen bu bağış ne kötü bir bağıştır."},{"n":100,"t":"Bunlar; o kasabanın haberleridir ki, sana anlatıyoruz. Onların bir kısmı hala duruyor, bir kısmı ise silinip gitmiştir."},{"n":101,"t":"Onlara, Biz zulmetmedik, fakat onlar kendilerine zulmettiler. Rabbının emri gelince de Allah’ı bırakıp taptıkları ilahları kendilerine bir fayda vermedi. Kayıplarını artırmaktan başka bir şeye yaramadı."},{"n":102,"t":"İşte böyledir Rabbının yakalayışı; kasabaların zalim halkını yakaladığı zaman. Çünkü O’nun yakalaması hem şiddetli, hem de acıklıdır."},{"n":103,"t":"Muhakkak ki ahiret azabından korkanlar için, bunda ayet vardır. O gün; bütün insanların toplanacağı gündür ve o, görülecek gündür."},{"n":104,"t":"Biz, o günü, ancak sayılı bir süreye kadar erteleriz."},{"n":105,"t":"O gün gelince; Allah’ın izni olmadan kimse konuşamaz. Onlardan kimisi bedbaht, kimisi de bahtiyardır."},{"n":106,"t":"Bedbahtlara gelince; onlar, cehennenmdedirler. Orada yüksek sesle solurlar."},{"n":107,"t":"Gökler ve yer durdukça orada temelli kalacaklardır. Rabbının dilediği müddet başka. Muhakkak ki Rabbın, dilediğini elbette yapandır."},{"n":108,"t":"Bahtiyar olanlar ise cennettedirler. Gökler ve yer durdukça temelli kalacaklardır orada. Rabbının dilediği başka. Bu, ardı arkası kesilmeyen bir vergidir."},{"n":109,"t":"Öyleyse bunların taptıkları şeyler konusunda sakın şüphede olma. Daha önce babalarının taptıkları gibi onlar da taparlar. Onların paylarını eksiksiz ödeyeceğiz."},{"n":110,"t":"Andolsun ki; Musa’ya kitabı verdik de hakkında ihtilafa düştüler. Eğer Rabbından bir söz geçmiş olmasaydı; aralarında hüküm verilmiş bitmişti bile. Doğrusu onlar, bundan yana şiddetli bir tereddüd ve şüphe içindedirler."},{"n":111,"t":"Hiç şüphe yok ki Rabbın; herkese amellerinin karşılığını tamamen ödeyecektir. Muhakkak ki O; yaptıklarınızdan haberdardır."},{"n":112,"t":"Öyleyse sen, emrolunduğun gibi dosdoğru hareket et. Beraberindeki tevbe edenler de. Aşırı gitmeyin. Çünkü O, yaptıklarınızı görür."},{"n":113,"t":"Zulmedenlere meyletmeyin, yoksa size de ateş dokunur. Sizin Allah’tan başka yardımcılarınız yoktur. Sonra yardım da göremezsiniz."},{"n":114,"t":"Gündüzün iki tarafında ve gecenin de yakın saatlerinde namaz kıl. Çünkü iyilikler kötülükleri giderir. Bu; öğüt kabul edenlere bir öğüttür."},{"n":115,"t":"Sabret, çünkü Allah ihsan edenlerin ücretini zayi etmez."},{"n":116,"t":"Sizden önceki nesillerin ileri gelenleri yeryüzünde bozgunculuğa engel olmalı değil miydiler? Onlardan kurtardıklarımız pek azdır. Zalim olanlar ise yalnız kendilerine verilen refahın ardına düştüler. Suçlu kimselerdi onlar."},{"n":117,"t":"Kasabaların halkı ıslah edilip dururken Rabbın haksız yere onları helak etmez."},{"n":118,"t":"Rabbın dileseydi; bütün insanları tek bir ümmet yapardı. Onlar ise hala ayrılıktadırlar."},{"n":119,"t":"Esasen onları bunun için yaratmıştır. Rabbının rahmet ettikleri müstesnadır. Bununla beraber, Rabbının şu sözü de tamamen yerine gelmiştir: Şüphesiz ki Ben, cehennemi hep insan ve cinn ile dolduracağım."},{"n":120,"t":"Peygamberlerin haberlerinden hepsini senin kalbini bunlarla pekiştirmek için sana anlatıyoruz. Bununla sana hak, mü’minlere de öğüt ve nasihat geldi."},{"n":121,"t":"İnanmayanlara de ki: Elinizden geleni yapın, biz de yapacağız."},{"n":122,"t":"Bekleyin, biz de bekleyeceğiz."},{"n":123,"t":"Göklerin ve yerin gaybı Allah’ındır. Bütün işler O’na döndürülür. Öyleyse O’na ibadet et ve O’na tevekkül et. Rabbın; yaptıklarınızdan gafil değildir."}],[{"n":1,"t":"Elif, Lam, Ra. Bunlar apaçık kitabın ayetleridir."},{"n":2,"t":"Doğrusu biz; onu akıl erdiresiniz diye arapça bir Kur’an olarak indirdik."},{"n":3,"t":"Biz; sana, bu Kur’an’ı vahyetmekle; kıssaların en güzelini anlatıyoruz. Halbuki sen, daha önce bundan habersizdin."},{"n":4,"t":"Hani Yusuf babasına demişti ki: Babacığım, rüyamda on bir yıldızla, güneşi ve ayı gördüm. Gördüm ki onlar bana secde etmektedirler."},{"n":5,"t":"Dedi ki: Oğulcuğum, rüyanı kardeşlerine anlatma, sonra sana tuzak kurarlar. Çünkü şeytan insan için apaçık bir düşmandır."},{"n":6,"t":"Rabbın seni böylece beğenip seçecek, sana rüyaların yorumlanmasına dair bilgi verecek ve daha önce ataların İbrahim’e ve İshak’a nimetlerini tamamladığı gibi, sana ve Ya’kup hanedanına da tamamlayacaktır. Muhakkak ki Rabbın, Alim’dir, Hakim’dir."},{"n":7,"t":"Andolsun ki; Yusuf’da ve kardeşlerinde, soranlar için nice ayetler vardır."},{"n":8,"t":"Hani demişlerdi ki: Biz, güçlü bir topluluk olduğumuz halde Yusuf ve kardeşi, babamızın yanında daha sevgilidirler. Doğrusu babamız apaçık bir sapıklık içindedir."},{"n":9,"t":"Yusuf’u öldürün veya bir yere atın ki, babanızın teveccühü yalnız size kalsın, ondan sonra da tevbe eder, salihler topluluğu olursunuz."},{"n":10,"t":"İçlerinden bir sözcü dedi ki: Yusuf’u öldürmeyin, onu bir kuyunun derinliklerine bırakın da yolculardan bir onu bulup alsın, eğer yapacaksanız."},{"n":11,"t":"Dediler ki: Ey babamız; sen bize Yusuf’u neden güvenmiyorsun? Halbuki biz, onun iyiliğini istemekteyiz."},{"n":12,"t":"Yarın onu bizimle beraber gönder de gezsin, oynasın. Şüphesiz biz, onu koruruz."},{"n":13,"t":"Dedi ki: Onu götürmeniz doğrusu beni tasaya düşürüyor. Siz, ondan habersizken onu kurdun yemesinden korkuyorum."},{"n":14,"t":"Dediler ki: Biz bir toplulukken onu kurt yerse; bu takdirde biz, muhakkak hüsrana uğrayanlardan oluruz."},{"n":15,"t":"Onu götürdükleri vakit, kuyunun derinliklerine bırakmayı birlikte kararlaştırdılar. Biz de kendisine vahyettik ki: Sen; onlara, kendileri hiç farkına varmadan yaptıklarını bir bir haber vereceksin."},{"n":16,"t":"Akşam üstü ağlaya ağlaya babalarına geldiler."},{"n":17,"t":"Dediler ki: Ey babamız; gerçekten biz gitmiştik ki yarış yapalım. Yusuf’u da eşyaların yanında bırakmıştık. Onu kurt yemiş. Her ne kadar doğru söylüyorsak da sen, bize inanacak değilsin."},{"n":18,"t":"Onlar sahte bir kan ile gömleğini getirdiler. Dedi ki: Hayır, nefisleriniz sizi aldatıp bir işe sürüklemiş. Artık bana güzelce bir sabır gerekir. Sizin şu anlattıklarınıza karşı yardımına sığınılacak, Allah’tır."},{"n":19,"t":"Bir kervan gelip sucularını gönderdiler. O da kovasını salıp dedi ki: Müjde; işte bir oğlan. Onu bir mal olarak sakladılar. Allah, yaptıklarını bilendir."},{"n":20,"t":"Onu, ucuz bir fiyata, birkaç dirheme sattılar. Onu yanlarında alıkoymak istemediler."},{"n":21,"t":"Onu satın alan Mısırlı, karısına dedi ki: Ona güzel bak, olur ki bize faydası dokunur veya onu evlad ediniriz. İşte böylece Yusuf’u Biz oraya yerleştirdik. Ve ona rüyaların yorumunu öğrettik. Ve Allah; emrinde galibdir. Fakat insanların çoğu bilmezler."},{"n":22,"t":"Ergenlik çağına gelince; ona hüküm ve ilim verdik. İşte böyle mükafaatlandırırız Biz, ihsan edenleri."},{"n":23,"t":"Evinde bulunduğu kadın onu kendine ram etmek istedi. Kapıları sımsıkı kapadı. Ve: Sana söylüyorum gelsene, dedi. O da: Allah’a sığınırım, doğrusu o, benim efendimdir, bana iyi bakmıştır. Muhakkak ki zalimler asla felah bulmaz, dedi."},{"n":24,"t":"Andolsun ki o, istekli idi. Eğer Rabbının burhanını görmemiş olsaydı; o da onu arzu etmiş gitmişti. İşte Biz, böylece ondan fenalığı ve fuhşu bertaraf ettik. Çünkü o, ihlasa erdirilmiş kullarımızdandı."},{"n":25,"t":"İkisi de kapıya koştular. Kadın, onun gömleğini arkasından boylu boyunca yırttı. Kapının yanında efendisine rast geldi. Kadın dedi ki: Ailene kötülük etmek isteyenin cezası; zindana atılmaktan veya acıklı bir azabdan başka ne olabilir?"},{"n":26,"t":"Dedi ki: O, beni kendisine ram etmek istedi. Kadının ailesinden biri de şehadet etti: Eğer gömleği önden yırtılmışsa; o (kadın) doğru söylemiştir. Bu (Yusuf) ise yalancılardandır."},{"n":27,"t":"Eğer gömleği arkadan yırtılmışsa, o (kadın) yalan söylemiştir, bu (Yusuf) ise doğru söyleyendir."},{"n":28,"t":"Gömleğinin arkadan yırtılmış olduğunu görünce; (kadının kocası) dedi ki: Doğrusu bu, sizin tuzağınızdandır, siz kadınların tuzağı büyüktür."},{"n":29,"t":"Yusuf; sen bundan vazgeç. Ey kadın; sen de günahının bağışlanmasını dile. Çünkü sen, gerçekten suçlulardan oldun."},{"n":30,"t":"Şehirde bir takım kadınlar dediler ki: Aziz’in karısı delikanlısını kendine ram etmek istiyormuş, sevgisi bağrını yakmış. Görüyoruz ki; o, apaçık bir sapıklıktadır."},{"n":31,"t":"Onların dedikodularını işitince; onlara haber yolladı. Onlar için yaslanacak yerler hazırladı ve onlardan her birine birer bıçak verdi. (Yusuf’a): Çık karşılarına, dedi. Hepsi onu görünce kendisini çok büyüttüler. Ve ellerini kestiler. Dediler ki: Allah’ı tenzih ederiz. Haşa bu, bir beşer değildir, ancak çok şerefli bir melektir."},{"n":32,"t":"Kadın dedi ki: İşte beni, onun için ayıpladığınız budur. Onu kendime ram etmek istedim, ama o iffetinden çekindi. Eğer istediğimi yapmazsa; andolsun ki, zindana atılacak ve zillete uğrayanlardan olacaktır."},{"n":33,"t":"Dedi ki: Rabbım, zindan bana bunların beni davet ettiklerinden daha iyidir. Eğer Sen, bunların tuzaklarını benden uzaklaştırmazsan; onlara meyleder, cahillerden olurum."},{"n":34,"t":"Rabbı onun duasını kabul etti de onların tuzaklarını kendisinden savdı. Muhakkak ki O’dur, Semi, Alim."},{"n":35,"t":"Sonra bütün delilleri onun lehine gördükleri halde yine de bir süre için onu zindana atmayı uygun buldular."},{"n":36,"t":"Onunla beraber iki kişi daha zindana girdi. Bunlardan biri dedi ki: Ben rüyamda kendimi şarap sıkıyor gördüm. Öbürü de: Ben de başımın üzerinde kuşların yediği bir ekmek taşıdığımı gördüm, dedi. Bize onun yorumunu bildir, çünkü senin gerçekten iyilik edenlerden olduğunu görüyoruz."},{"n":37,"t":"Dedi ki: Size rızık olmak üzere verilen yemeklerin gelmesinden önce onun yorumunu bildiririm. Bu; Rabbımın bana öğrettiklerindendir. Doğrusu ben, Allah’a inanmaz bir kavmin dinini terkettim. Hem onlar, ahirete küfrederdi."},{"n":38,"t":"Atalarım İbrahim, İshak ve Ya’kub’un dinine uydum. Herhangi bir şeyi Allah’a şirk koşmamız bize yaraşmaz. Bu, Allah’ın bize ve insanlara olan lütfundandır. Fakat insanların çoğu şükretmezler."},{"n":39,"t":"Ey zindan arkadaşlarım; darmadağınık ve değişik Rabblar mı hayırlıdır, yoksa Vahid ve Kahhar olan Allah mı?"},{"n":40,"t":"Sizin O’nu bırakıp taptıklarınız; kendinizibn ve atalarınızın takmış oldukları adlardan başka bir şey değildir. Allah, onlara hiç bir hüküm indirmemiştir. Hüküm; ancak Allah’ındır. Kendisinden başkasına ibadet etmemenizi emretmiştir. İşte dosdoğru din. Ama insanların çoğu bilmezler."},{"n":41,"t":"Ey zindan arkadaşlarım; biriniz efendisine şarab içirecek, diğeri de asılacak, kuşlar onun başından yiyecektir. İşte sorduğunuz iş, böylece olup bitmiştir."},{"n":42,"t":"O ikisinden kurtulacağını sandığı kimseye dedi ki: Efendinin yanında beni an. Fakat şeytan onu efendisine anmayı unutturdu. Bu yüzden daha nice yıl zindanda kaldı."},{"n":43,"t":"Hükümdar dedi ki: Ben gördüm ki; yedi semiz ineği yedi zayıf inek yemektedir. Yedi yeşil başak ve bir o kadar da kurumuş başak. Ey ileri gelenler; eğer rüya yorumlayabiliyorsanız şu benim rüyamın anlamını söyleyin."},{"n":44,"t":"Dediler ki: Karmakarışık rüyalar bunlar. Biz böyle rüyaların yorumunu bilenler değiliz."},{"n":45,"t":"O ikiden kurtulmuş olanı nice zaman sonra hatırladı da dedi ki: Ben, size onun yorumunu bildireyim. Hemen gönderin beni."},{"n":46,"t":"Yusuf, ey doğru sözlü; bildir bakalım bize: Yedi semiz ineği, yedi zayıf ineğin yemesini ve yedi yeşil başakla bir o kadar da kuru başağı. Geri dönüp insanlara haber vereyim de onlar bilsinler."},{"n":47,"t":"Dedi ki: Yedi sene alıştığınız biçimde ekin. Yediğiniz bir mikdar dışında biçtiklerinizi başağında bırakın."},{"n":48,"t":"Sonra bunun ardından yedi kurak yıl gelir. Saklayacağınız az bir mikdar dışında biriktirdiklerinizi yer, götürür."},{"n":49,"t":"Sonra bunun ardından öyle bir yıl gelir ki insanlar, onda yağmura kavuşturulur ve onda sıkıp sağarlar."},{"n":50,"t":"Hükümdar dedi ki: Onu bana getirin. Bunun üzerine ona elçi gelince: Efendine dön ve ellerini kesen o kadınların zoru neydi kendisine sor. Şüphesiz ki benim Rabbım, onların düzenini bilir, dedi."},{"n":51,"t":"Dedi ki: Yusuf’tan kam almak istediğiniz zaman ne halde idiniz? Onlar dediler ki: Haşa, Allah için biz onun bir kötülüğünü görmedik. Aziz’in karısı da şöyle dedi: Şimdi hak ortaya çıktı. Onu kendime ben ram etmek istedim. Ve o, gerçekten sadıklardandır."},{"n":52,"t":"Bu; gıyabında kendisine gerçekten hıyanet etmediğimi, hainlerin hilesini Allah’ın başarıya erdirmeyeceğini, onun da bilmesi içindi."},{"n":53,"t":"Ve ben, nefsimi temize çıkarmam. Çünkü nefs var şiddetiyle kötülüğü emredendir. Meğer ki Rabbımın esirgediği bir nefs ola. Rabbım Gafur’dur, Rahim’dir."},{"n":54,"t":"Hükümdar dedi ki: Onu bana getirin de yanıma alayım. Onunla konuşunca da dedi ki: Sen, bugün bizim yanımızda önemli bir mevki sahibisin, eminsin."},{"n":55,"t":"Dedi ki: Beni memleketin hazineleri üzerine tayin et. Çünkü ben, onları iyi korurum, bilirim."},{"n":56,"t":"İşte böylece Yusuf’u yeryüzünde yerleştirdik. Nereyi isterse orada konaklardı. Rahmetimizi, istediğimize veririz. Ve ihsan edenlerin ecrini zayi etmeyiz."},{"n":57,"t":"Ama ahiret mükafaatı, iman edip de takvada daim olanlar için daha hayırlıdır."},{"n":58,"t":"Yusuf’un kardeşleri gelip yanına girdiler. Onları tanıdı, ama onlar kendisini tanımıyorlardı."},{"n":59,"t":"Onların yüklerini hazırlatınca dedi ki: Bana baba bir kardeşinizi getirin. Görmüyor musunuz ki ben, ölçüyü tam ölçüyorum ve ben, konukseverlerin en iyisiyim."},{"n":60,"t":"Eğer onu bana getirmezseniz; benden bir ölçek dahi alamazsınız ve bir daha bana yaklaşmayın."},{"n":61,"t":"Dediler ki: Onu babasından istemeye çalışırız ve herhalde bunu yaparız."},{"n":62,"t":"Yusuf uşaklarına dedi ki: Karşılık olarak getirdiklerini de yüklerinin içine koyun. Olur ki ailelerine dönünce bunu anlarlar da geri dönerler."},{"n":63,"t":"Babalarına döndüklerinde dediler ki: Ey babamız; artık bize zahire verilmeyecek. Kardeşimizi bizimle beraber gönder de zahiremizi alalım. Biz herhalde onu koruruz."},{"n":64,"t":"Dedi ki: Daha önce kardeşinizi size ne kadar inandıysam, bunu da ancak o kadar inanırım. Ama Allah, koruyucuların en hayırlısıdır ve o, merhametlilerin en merhametlisidir."},{"n":65,"t":"Yüklerini açyıkları vakit; karşılık olarak götürdüklerinin kendilerine iade edilmiş olduğunu gördüler. Dediler ki: Ey babamız, daha ne isteriz, işte mallarımız da bize geri verilmiş, onunla ailemize yine zahire getiririz. Kardeşimizi koruruz ve bir deve yükü zahire artırırız. Esasen bu, az bir ölçektir."},{"n":66,"t":"Dedi ki: Etrafınız kuşatılmadıkça muhakkak bana getireceğinize dair Allah’a karşı sağlam bir söz vermezseniz, onu sizinle asla göndermem. Artık onlar söz verince: Allah söylediklerinize Vekil’dir, dedi."},{"n":67,"t":"Ve dedi ki: Oğullarım, hepiniz bir kapıdan girmeyin, ayrı ayrı kapılardan girin. Bununla beraber, Allah katında size bir faydam olmaz. Hüküm ancak Allah’ındır. Ben, O’na tevekkül ettim. Tevekkül edenler de yalnız O’na tevekkül etsinler."},{"n":68,"t":"Babalarının kendilerine emrettiği yerden girdiler. Bu, Allah katında onlara bir fayda sağlamazdı. Ancak Ya’kub içindeki dileği meydana çıkarmış oldu. O, şüphe yok ki kendisine öğrettiğimiz için ilim sahibi idi, ama insanların çoğu bilmezler."},{"n":69,"t":"Yusuf’un yanına girince; o, kardeşini yanına aldı ve: Ben senin kardeşinim, onların yapmış olduklarına artık üzülme, dedi."},{"n":70,"t":"Onların yüklerini yüklettiğinde su kabını öz kardeşinin yüküne koydurdu. Sonra bir münadi: Ey kafile; siz gerçekten hırsızlarsınız, diye bağırdı."},{"n":71,"t":"Onlara döndüler ve: Ne kaybettiniz? dediler."},{"n":72,"t":"Dediler ki: Hükümdarın su kabını kaybettik, onu getirene de bir deve yükü var. Ben de buna kefilim."},{"n":73,"t":"Dediler ki: Allah’a yemin ederiz, siz de öğrendiniz ki biz, yeryüzünde fesad çıkarmak için gelmedik. Ve biz hırsızlar da olmadık."},{"n":74,"t":"Eğer yalancılar iseniz; bunun cezası nedir? dediler."},{"n":75,"t":"Dediler ki: Bunun cezası, yükünde bulunan kimsenin kendisidir. İşte o kimse bunun cezasıdır. Biz zalimleri böyle cezalandırırız."},{"n":76,"t":"Bunun üzerine kardeşinin kablarından evvel onlarınkini aramaya başladı. Sonra onu kardeşinin kabından çıkardı. İşte Biz, Yusuf için böyle bir tedbir kullandık. Yoksa o hükümdarın dinine göre; kardeşini tutabilecek değildi. Meğer ki Allah dileye. Dilediğimizi derecelerle yükseltiriz. Ve her bilgi sahibinin üstünde bir bilen vardır."},{"n":77,"t":"Dediler ki: O çalmışsa, daha evvel onun bir kardeşi de çalmıştı. Yusuf bunu içinde gizledi, onlara açılmadı. Sizin durumunuz daha kötüdür. Allah sizin anlatmakta olduğunuzu en iyi bilendir, dedi."},{"n":78,"t":"Dediler ki: Ey Aziz, gerçekten bunun ihtiyar bir babası var, onun yerine bizden birini al. Doğrusu biz seni ihsan edenlerden görüyoruz."},{"n":79,"t":"Dedi ki: Eşyamızı yanında bulduğumuz kimseden başkasını yakalamaktan Allah’a sığınırız. Çünkü biz, o zaman zalimlerden oluruz."},{"n":80,"t":"Ondan ümitlerini kesince; fısıldaşarak bir yana çekildiler. Büyükleri dedi ki: Bilmiyor musunuz ki, babanız sizden Allah adına bir söz almıştı, daha önce de Yusuf hakkında bir kusur işlemiştiniz. Babam bana izin verinceye veya Allah hakkımda hükmedinceye kadar, ben buradan asla ayrılmam. O, hükmedenlerin en hayırlısıdır."},{"n":81,"t":"Siz, babanıza dönün de deyin ki: Ey babamız; doğrusu oğlun hırsızlık etti. Ve biz bildiğimizden başka bir şey görmedik. Hem biz gaybın bekçileri de değildik."},{"n":82,"t":"Bulunduğumuz kasabanın halkına, aralarında geldiğimiz kervana da sor. Biz gerçekten sadıklarız."},{"n":83,"t":"Ya’kub dedi ki: Hayır, nefisleriniz sizi aldatıp bir işe sürüklemiş. Artık bana sabır gerekir. Umulur ki Allah, onların hepsini birden bana getirecektir. Muhakkak ki Alim, Hakim O’dur O."},{"n":84,"t":"Ve onlardan yüz çevirdi de: Vah, yazık oldu Yusuf’a, dedi ve üzüntüsünden gözleri ağardı. Artık üzüntüsünü içinde saklıyordu."},{"n":85,"t":"Dediler ki: Vallahi sen, hala Yusuf’u anıp duruyorsun, sonunda ya kederinden bitkin düşeceksin veya helake uğrayanlardan olacaksın."},{"n":86,"t":"Dedi ki: Ben, üzüntümü ve kederimi yalnız Allah’a açarım. Ve ben, Allah katından sizin bilmediğinizi biliyorum."},{"n":87,"t":"Ey oğullarım; haydi gidin, Yusuf’u ve kardeşini araştırın. Allah’ın rahmetinden ümidinizi kesmeyin. Zira kafirler güruhundan başkası Allah’ın rahmetinden ümidini kesmez."},{"n":88,"t":"Onlar yanına vardıklarında dediler ki: Ey Aziz; bizi de ailemizi de darlık bastı, pek değersiz bir malla geldik. Bize yine tam ölçek ver de tasadduk et. Muhakkak ki Allah, tasadduk edenleri mükafaatlandırır."},{"n":89,"t":"Siz, cahiller iken Yusuf’a ve kardeşine neler yaptığınızı biliyor musunuz? dedi."},{"n":90,"t":"Dediler ki: Yoksa sen gerçekten Yusuf musun? O da dedi ki: Ben, Yusuf’um, bu da kardeşim. Doğrusu Allah, size lutfetti. Çünkü kim sakınır ve sabrederse; muhakkak ki Allah, ihsan edenlerin ecrini zayi etmez."},{"n":91,"t":"Dediler ki: Allah’a yemin ederiz, Allah gerçekten seni bizden üstün kılmıştır. Doğrusu biz, suçlu idik."},{"n":92,"t":"Dedi ki: Bugün size başa kakmak ve kınamak yok. Allah sizi bağışlasın. O, merhametlilerin merhametlisidir."},{"n":93,"t":"Şimdi siz, şu gömleğimi götürün de babamın yüzüne sürün, görmeye başlar. Bütün ailenizi de bana getirin."},{"n":94,"t":"Kafile ayrılınca babaları dedi ki: Bana bunak demezseniz; inan olsun ki, Yusuf’un kokusunu duyuyorum."},{"n":95,"t":"Dediler ki: Allah’a yemin ederiz, sen hala eski şaşkınlığındasın."},{"n":96,"t":"Fakat müjdeci gelip de onu yüzüne sürünce; derhal gördü ve dedi ki: Ben, size Allah katından sizin bilmeyeceğinizi biliyorum, dememiş miydim?"},{"n":97,"t":"Dediler ki: Ey babamız; bizim için mağfiret dile, biz gerçekten suçlular idik."},{"n":98,"t":"Dedi ki: Sizin için ilerde Rabbımdan mağfiret dileyeceğim. Muhakkak ki O’dur O, Gafur, Rahim."},{"n":99,"t":"Onlar Yusuf’un yanına girdiklerinde; o anasını, babasını bağrına bastı ve: Allah’ın isteği ile Mısır’a emin olarak girin, dedi."},{"n":100,"t":"Ana-babasını tahtın üzerine çıkarıp oturttu. Hepsi onun için secdeye kapandılar. Dedi ki: Babacığım; işte bu; vaktiyle gördüğüm rüyanın gerçekleşmesidir. Doğrusu Rabbım, onu gerçekleştirdi ve bana ihsan etti de; şeytan benimle kardeşlerimin arasını bozduktan sonra, beni zindandan çıkardı ve sizi çölden getirdi. Muhakkak ki Rabbım, dilediğine lütufkardır. Muhakkak ki O’dur O, Hakim, Alim."},{"n":101,"t":"Rabbım; bana Sen mülk verdin ve sözlerin te’vilini öğrettin. Ey göklerin ve yerin yaratanı; Sen, dünyada da, ahirette de benim velimsin. Müslüman olarak canımı al. Ve beni salihlere kat."},{"n":102,"t":"Bunlar gayb haberlerindendir ki, sana vahyediyoruz. Onlar, elbirliği edip düzen kurdukları zaman; sen, orada değildin."},{"n":103,"t":"Sen, ne kadar hırs göstersen de; yine insanların çoğu, inanmazlar."},{"n":104,"t":"Halbuki sen, buna karşı onlardan hiç bir ücret de istemiyorsun. O, alemler içn bir öğütten başka bir şey değildir."},{"n":105,"t":"Göklerde ve yerde nice ayetler vardır ki; yüzlerini çevirerek onları görüp geçerler."},{"n":106,"t":"Onların çoğu; Allah’a iman etmezler, ille de şirk koşanlardır onlar."},{"n":107,"t":"Allah tarafından onları kuşatacak bir azabın kendilerine gelip çatmasından veya farkında olmadan kıyamet saatinin ansızın gelmesinden emin midirler?"},{"n":108,"t":"De ki: Benim yolum işte budur. Allah’a basiretle davet ediyorum, ben de bana uyanlar da, Allah’ı tenzih ederiz. Ben, asla müşriklerden değilim."},{"n":109,"t":"Senden önce gönderdiğimiz elçiler de ancak kasabalar halkından, kendilerine vahyettiğimiz birtakım erkeklerdi. Yeryüzünde dolaşmıyorlar mı ki; görsünler kendilerinden önce geçenlerin akıbetlerinin nasıl olduğunu. İttika edenler için ahiret yurdu elbette daha hayırlıdır. Hala akıllanmayacak mısınız?"},{"n":110,"t":"Nihayet o Peygamber ümitsizliğe düşüp kesinlikle yalanladıklarını sandıkları sırada, onlara yardımımız gelmiştir. Böylece dilediğimiz kurtarılmıştır. Suçlular güruhundan ise baskınımız asla geri çevrilmeyecektir."},{"n":111,"t":"Andolsun ki; onların kıssalarında aklı olanlar için ibretler vardır. Bu, uydurulabilecek bir söz değildir. O; sadece kendinden önceki kitabların tasdiki, her şeyin tafsilidir. İnananlar topluluğu için de hidayet ve rahmettir."}],[{"n":1,"t":"Elif, Lam, Mim, Ra. Bunlar Kitab’ın ayetleridir. Sana Rabbinden indirilen Kitab haktır. Ama insanların çoğu inanmazlar."},{"n":2,"t":"Allah O’dur ki; gökleri gördüğünüz gibi yükseltmiş, sonra Arş’a hükmetmiştir. Güneşi ve ayı buyruğu altına almıştır. Bunların her biri belli bir süreye kadar hareket edecektir. İşleri yürütür. Rabbınızla karşılaşacağınıza kesin olarak inanmanız için ayetleri uzun uzun açıklar."},{"n":3,"t":"O’dur yeri düzleyen ve orada dağlar, nehirler var eden, her türlü mahsulden çift çift yetiştiren ve gündüzü geceyle bürüyen. Muhakkak ki bunlarda; düşünen bir kavim için ayetler vardır."},{"n":4,"t":"Yeryüzünde birbirine komşu toprak parçaları, üzüm bağları, ekinler ve çatallı çatalsız hurma ağaçları vardır. Hepsi de aynı su ile sulanır. Ama lezzetçe onları birbirinden ayrı kılmışızdır. Şüphesiz ki bunlarda; akleden bir kavim için ayetler vardır."},{"n":5,"t":"Şaşacaksan, onların: Biz, toprak olunca yeniden mi yaratılacağız? demelerine şaşmak gerekir. İşte onlar; Rabblarını inkar edenlerdir. İşte onlar; boyunlarına demir halkalar vurulanlardır. Ve işte onlar; cehennemliklerdir, orada temelli kalacaklardır."},{"n":6,"t":"İyilikten önce, kötülük isterler çabucak senden. Oysa onlardan önce nice örnekler geçmiştir. Doğrusu insanların zulmetmelerine rağmen, Rabbın mağfiret sahibidir. Şüphesiz ki Rabbının cezalandırması; şiddetlidir."},{"n":7,"t":"Küfredenler, derler ki: Ona Rabbından bir ayet indirilmeli değil miydi? Sen; ancak bir uyarıcısın ve her kavmin bir yol göstericisi vardır."},{"n":8,"t":"Allah; her dişinin neyi yüklendiğini ve rahimlerin neyi eksiltip artırdığını bilir. O’nun katında her şey bir ölçüye göredir."},{"n":9,"t":"Görüleni de, görülmeyeni de bilir. Yücelerin yücesidir."},{"n":10,"t":"Aranızdan birisi; ister sözü gizlesin, ister açığa vursun, ister geceye bürünerek gizlensin, ister gündüzün ortaya çıksın; hiç fark yoktur."},{"n":11,"t":"Ardından ve önünden takib edenler vardır. Allah’ın emriyle onu gözetirler. Şüphesiz ki bir kavim, kendini değiştirmedikçe; Allah da onları değiştirmez. Ve Allah, bir kavimin fenalığını dileyince; artık onun önüne geçilemez. Allah’tan başka onları koruyacak birisi de bulunmaz."},{"n":12,"t":"O’dur, korku ve ümide düşürmek için size, şimşeği gösteren ve yağmur yüklü bulutları meydana getiren."},{"n":13,"t":"Gökgürültüsü; hamd ile, melekler de korku ile O’nu tesbih eder. O, yıldırımları gönderir de onlarla dilediğini çarpar. Halbuki onlar; Allah hakkında tartışıyorlardı. O, kudretinde pek çetin olandır."},{"n":14,"t":"Gerçek dua ancak O’nadır. O’ndan başka taptıkları kendilerine hiçbir şeyle cevap veremezler. Durumları; suyun ağzına gelmesi için avuçlarını ona açmış kimsenin durumu gibidir. Oysa o, hiç bir zaman suya kavuşamaz. İşte kafirlerin yalvarışı da böyle boşunadır."},{"n":15,"t":"Göklerde ve yerdekiler de, gölgeleri de sabah akşam, ister istemez Allah’a secde ederler."},{"n":16,"t":"De ki: Göklerin ve yerin Rabbı kimdir? Allah’tır de. Yoksa O’nu bırakıp kendilerine bir fayda ve zararı olmayan veliler mi edindiniz? de. De ki: Hiç körle gören bir olur mu? Yahut karanlık ile aydınlık bir midir? Yoksa, Allah gibi yaratması olan ortaklar buldular da yaratmaları birbirine mi benzettiler? De ki: Her şeyi yaratan, Allah’tır. Ve O; Vahid ve Kahhar’dır."},{"n":17,"t":"Gökten su indirir de dereler onunla dolar taşar. Üste çıkan köpüğü sel alır götürür. Süslenmek veya yararlanmak için ateşle erittiklerinizin üzerinde de buna benzer bir köpük vardır. Böyle misal verir Allah hak ile batıl için. Köpük; uçar gider, insanlara fayda veren ise yerde kalır. İşte böyle; Allah daha nice misaller verir."},{"n":18,"t":"Rabblarına icabet edenlere; en güzel karşılık vardır. O’na icabet etmeyenler ise; şayet yeryüzünde bulunan her şey ve bir katı daha onların olsa, kurtulmak için onu fidye verirlerdi. Hesabın kötüsü, onlar içindir. Varacakları yer, cehennemdir ve o, ne kötü konaktır."},{"n":19,"t":"Şimdi, Rabbından sana indirilenin gerçek olduğunu bilen; hiç kör gibi midir? Ancak akıl sahibleri ibret alırlar."},{"n":20,"t":"Onlar ki; Allah’ın ahdini yerine getirirler ve anlaşmayı bozmazlar."},{"n":21,"t":"Ve onlar ki; Allah’ın bitiştirilmesini emrettiği şeyi bitiştirirler. Rabblarından korkarlar ve kötü hesabdan ürkerler."},{"n":22,"t":"Ve onlar ki; Rabblarının rızasını dileyerek sabrederler, namazı kılarlar, kendilerine verdiğimiz rızıktan, gizlice ve açıkça infak ederler. Kötülüğü iyilik yaparak ortadan kaldırırlar. İşte onlara bu dünyanın karşılığı;"},{"n":23,"t":"Adn cennetleridir; oraya girerler. Babalarının, eşlerinin, çocuklarının iyi olanları da oraya girerler. Melekler her kapıdan yanlarına gelir."},{"n":24,"t":"Sabrettiğiniz için selam size. Burası dünyanın en güzel karşılığıdır, derler."},{"n":25,"t":"Pekiştirdikten sonra Allah’ın ahdini bozanlar, Allah’ın bitiştirilmesini emrettiğini ayıranlar ve yeryüzünde bozgunculuk yapanlar; işte la’net onlaradır. Yurtların en kötüsü de onlarındır."},{"n":26,"t":"Alah; dilediği kimseye rızkı genişletir, daraltır. Onlar ise dünya hayatı ile sevindiler. Halbuki dünya hayatı ahiretin yanında sadece bir geçimlikten ibarettir."},{"n":27,"t":"Küfredenler dediler ki: Rabbından kendisine bir ayet inidirilmeli değil miydi? De ki: Allah dilediğini saptırır, kendisine yöneleni de doğru yola eriştirir."},{"n":28,"t":"Onlar ki; inanmışlardır ve kalbleri Allah’ı anmakla huzura kavuşmuştur. Dikkat edin; gerçekten kalbler, ancak Allah’ı anmakla huzura kavuşur."},{"n":29,"t":"İnanmış olup salih ameller işleyenler için, hoş bir hayat ve güzel bir gelecek vardır."},{"n":30,"t":"İşte böyle; sana vahyettiğimizi okuman için, seni de onlardan önce nice ümmetlerin gelip geçtiği bir ümmete gönderdik. Onlar; Rahman’ı inkar ederler. De ki: O benim Rabbımdır. O’ndan başka ilah yoktur. Yalnız O’na tevekkül ederim. Dönüşüm de O’nadır."},{"n":31,"t":"Şayet Kur’an ile; dağlar yürütülmüş veya yeryüzü parçalanmış, yahut ölüler konuşturulmuş olsaydı; kafirler yine de inanmazlardı. Halbuki bütün işler Allah’a aittir. İnananlar hala anlamadılar mı ki; Allah dileseydi bütün insanları doğru yola eriştirirdi. Ve yaptıklarından dolayı Allah’ın vaadi yerine gelene kadar küfredenlerin ya başına veya evlerinin yakınına bir bela gelirdi. Şüphesiz Allah, verdiği sözden caymaz."},{"n":32,"t":"Andolsun ki; senden önce de nice peygamberlerle alay edilmişti. Küfredenleri önce tehir ettim, sonra cezalarını verdim. Cezalandırmam nasıldı?"},{"n":33,"t":"Herkesin yaptığını gözeten Allah; böyle olmayanla bir olur mu hiç? Oysa onlar Allah’a ortak koştular. De ki: Onlara bir ad bulun bakalım. Yeryüzünde bilmediği bir şeyi mi Allah’a haber veriyorsunuz? Yoksa kuru sözlere mi aldanıyorsunuz? Küfredenlere kurdukları düzenler güzel gösterildi. Ve doğru yoldan alıkonuldular. Allah kimi saptırırsa, ona doğru yolu gösteren bulunmaz."},{"n":34,"t":"Onlara; dünya hayatında azab vardır. Ahiret azabı ise daha zorludur. Allah’a karşı onları koruyacak kimse de yoktur."},{"n":35,"t":"Müttakilere vaad olunan cennetin içinden ırmaklar akar. Oranın yiyecekleri de, gölgeleri de ebedidir. Bu, takva sahiplerinin akıbetidir. Kafirlerin akıbeti ise ateştir."},{"n":36,"t":"Kendilerine kitab verdiklerimiz, sana indirilenden memnun olurlar. Karşı gruplar içinde de onun bir kısmını inkar edenler vardır. De ki: Ben, ancak Allah’a ibadet etmek ve O’na şirk koşmamakla emrolundum. Ben, hepinizi O’na çağırıyorum ve dönüşüm de O’nadır."},{"n":37,"t":"İşte böylece Biz, onu arapça bir hüküm olarak indirdik. Sana gelen bilgiden sonra, onların heveslerine uyarsan; andolsun ki Allah katından sana bir dost ve koruyucu çıkmaz."},{"n":38,"t":"Andolsun ki; senden önce nice peygamberler gönderdik. Onlara eşler ve çocuklar verdik. Allah’ın izni olmadan hiç bir peygamber bir ayet getiremez. Herkesin süresi yazılıdır."},{"n":39,"t":"Allah dilediğini siler ve dilediğini bırakır. Ve ana kitab O’nun katındadır."},{"n":40,"t":"Onlara vaad ettiğimizin bir kısmını sana göstersek de, senin canını alsak da; senin vazifen, sadece tebliğ etmektir. Hesab görmekse Bize düşer."},{"n":41,"t":"Görmüyorlar mı ki; Biz, yeryüzünün etrafından gitgide eksiltmekteyiz. Allah hükmünü verir. O’nun hükmünü bozacak yoktur. Ve O, hesabı çabuk görendir."},{"n":42,"t":"Onlardan öncekiler de düzen kurdular. Halbuki bütün düzenler Allah’ındır. Herkesin ne kazandığını bilir. Küfredenler yurdun sonunun kimin olacağını bilecektir."},{"n":43,"t":"Küfredenler: Sen peygamber değilsin, derler. De ki: Benimle sizin aranızda şahid olarak Allah ve kitabın bilgisi kendi yanında olanlar yeter."}],[{"n":1,"t":"Elif, Lam, Ra. Bu, insanları Rabblarının izniyle karanlıklardan aydınlığa çıkarman için onu sana indirdiğimiz bir kitaptır. Aziz ve Hamid’in dosdoğru yoluna."},{"n":2,"t":"O Allah ki; göklerde ve yerde olanlar O’nundur. Şiddetli azaptan dolayı vay kafirlere."},{"n":3,"t":"Onlar ki; dünya hayatını ahiret tercih ederler. Allah yolundan alıkoyarlar ve onda eğrilik ararlar. İşte onlar, derin bir sapıklık içindedirler."},{"n":4,"t":"Biz, her peygamberi kendi milletinin diliyle gönderdik ki; onlara, apaçık anlatsın. Bundan sonra Allah; dilediğini saptırır, dilediğini de doğru yola iletir. Ve O; Aziz’dir, Hakim’dir."},{"n":5,"t":"Andolsun ki; Biz, Musa’yı; kavmini karanlıklardan aydınlıklara çıkar ve onlara, Allah’ın günlerini hatırlat, diye gönderdik. Şüphesiz bunda, sabreden ve şükreden herkes için ayetler vardır."},{"n":6,"t":"Hani Musa kavmine demişti ki: Allah’ın üzerinizdeki nimetini hatırlayın. Çünkü o, sizi azabın kötüsüne uğratan, kadınlarınızı sağ bırakıp oğullarınızı boğazlayan Firavun hanedanından kurtarmıştı. Bunda Rabbınızdan büyük bir imtihan vardır."},{"n":7,"t":"Hani Rabbınız: Şükrederseniz; andolsun ki, size artırırım, nankörlük ederseniz; bilin ki azabım çok şiddetlidir, diye bildirmişti."},{"n":8,"t":"Musa: Siz ve yeryüzünde bulunanların hepsi nankörlük etseniz; muhakkak ki Allah, müstağni ve hamde layık olandır, demişti."},{"n":9,"t":"Sizden önce geçenlerin Nuh, Ad, Semud kavimlerinin ve onlardan sonra Allah’tan başka kimsenin bilmediği kavimlerin haberi size gelmedi mi? Peygamberleri onlara ayetlerle geldiler de onlar, ellerini ağızlarına koyup: Biz, sizin gönderilmiş olduğunuz şeyi inkar ettik, bizi çağırdığınız şeyden şüphe ve endişe içindeyiz, dediler."},{"n":10,"t":"Peygamberleri onlara: Gökleri ve yeri yaratan, günahlarınızı bağışlamak için çağıran ve sizi belirli bir süreye kadar tehir eden Allah’tan mı şüphe ediyorsunuz? demişlerdi. Onlar da: Siz de bizim gibi sadece birer insansınız. Siz; bizi, atalarımızın tapındığı şeylerden döndürmek istiyorsunuz. Öyleyse, bize açık bir delil getirin, demişlerdi."},{"n":11,"t":"Peygamberleri onlara: Biz de sizin gibi birer insanız, ama Allah kullarından dilediğine ihsanda bulunur. Allah’ın izni olmadıkça biz; size delil getiremeyiz. Mü’minler; Allah’a tevekkül etsinler, demişlerdi."},{"n":12,"t":"Hem biz, ne diye Allah’a tevekkül etmeyelim ki; bize dosdoğru yolları O, göstermiştir. Bize yaptığınız eziyetlere elbette dayanacağız. Tevekkül edenler de yalnız Allah’a tevekkül etsinler."},{"n":13,"t":"Küfredenler peygamberlerine dediler ki: Ya bizim dinimize dönersiniz, ya da sizi memleketimizden çıkarırız. Rabbları da onlara vahyetti ki: Biz,"},{"n":14,"t":"Onlardan sonra da yeryüzüne sizi yerleştireceğiz. Bu, makamımdan ve tehdidimden korkanlara vaadimdir."},{"n":15,"t":"Yardım istediler ve bütün inatçı zorbalar da hüsrana uğradılar."},{"n":16,"t":"Ardından da cehennem. Orada irinli sudan içirilecektir."},{"n":17,"t":"Onu yudum yudum alacak ama yutamayacaktır. Her taraftan ona ölüm geldiği halde ölemeyecektir. Ve arkasından şiddetli bir azab gelip çatacaktır."},{"n":18,"t":"Rabblarına küfredenlerin hali; fırtınalı bir günde rüzgarın şiddetle savurduğu küle benzer. Yaptıklarından dolayı hiçbir şey elde edemezler. İşte bu, uzak bir sapıklıktır."},{"n":19,"t":"Görmez misin ki, Allah; gökleri ve yeri hak ile yaratmıştır. Dilerse sizi yok edip yeni bir halk getirir."},{"n":20,"t":"Ve bu, Allah için hiç de güç değildir."},{"n":21,"t":"Onların hepsi; Allah’ın huzuruna toplanıp çıkarlar. Zayıflar büyüklük taslayanlara: Doğrusu biz; size uymuştuk. Allah’ın azabından bizi koruyabilecek misiniz? derler. Onlar da: Allah, bizi doğru yola eriştirseydi; biz de sizi eriştirirdik. Şu halde artık sızlansak da katlansak da birdir. Bizim için kaçıp sığınacak bir yer yoktur, derler."},{"n":22,"t":"İş olup bitince; şeytan dedi ki: Gerçekten Allah, size sözün doğrusunu söylemişti. Ben de size söz verdim, ama caydım. Sizi zorlayacak hiç bir gücüm de yoktu. Yalnız ben sizi çağırdım, siz de geldiniz. O halde beni kınamayın, kendinizi kınayın. Artık ben sizi kurtaramam, siz de beni kurtaramazsınız. Esasen daha önce, beni Allah’a ortak koşmanızı kabul etmemiştim. Doğrusu zalimlere elim bir azab vardır."},{"n":23,"t":"İman edenler, salih amel işleyenler; altlarından ırmaklar akan cennetlere konulurlar. Rabblarının izni ile orada ebediyyen kalırlar. Onların birbirine sağlık temennileri de; selam’dır."},{"n":24,"t":"Görmez misin; Allah, nasıl bir misal verdi. Hoş bir söz; kökü sağlam, dalları göğe doğru olan hoş bir ağaca benzer."},{"n":25,"t":"Ki, Rabbının izniyle her zaman yemişini verir. İnsanlar ibret alsınlar diye Allah, onlara misal veriyor."},{"n":26,"t":"Çirkin bir söz; yerden koparılmış, kökü olmayan kötü bir ağaca benzer."},{"n":27,"t":"Allah; inananları, dünya hayatında ve ahirette sağlam bir söz üzerinde tutar. Zalimleri de saptırır. Allah, dilediğini yapar."},{"n":28,"t":"Allah’ın verdiği nimeti küfre çevirip değiştirenleri ve milletlerini helak olacakları yere götürenleri görmüyor musun?"},{"n":29,"t":"Yaslanacakları cehenneme ki; o, ne kötü bir karargahtır."},{"n":30,"t":"Onlar; Allah’ın yolundan saptırmak için O’na eşler koşmuşlardı. Yaşayın bakalım, varacağınız yer şüphesiz ateş olacaktır, de."},{"n":31,"t":"İman eden kullarıma söyle: Namazı kılsınlar, alışveriş ve dostluğun olmayacağı gün gelmezden önce; kendilerine verdiğimiz rızıktan gizli, açık infak etsinler."},{"n":32,"t":"Allah O’dur ki; gökleri ve yeri yaratmış, indirdiği su ile size rızık olarak ürünler çıkarmıştır. Emri gereğince denizde yüzmek üzere gemileri ve nehirleri buyruğunuza verdi."},{"n":33,"t":"Devamlı olarak yörüngelerinde yürüyen güneşi ve ayı size müsahhar kıldı. Geceyi ve gündüzü de size teshir etti."},{"n":34,"t":"O, size istediğiniz şeylerin hepsinden verdi. Allah’ın nimetini sayacak olsanız; bitiremezsiniz. Doğrusu insan, pek zalim ve nankördür."},{"n":35,"t":"Hani İbrahim demişti ki: Rabbım; bu şehri emniyetli kıl. Beni de, oğullarımı da puta tapmaktan uzak tut."},{"n":36,"t":"Rabbım; çünkü onlar insanlardan bir çoğunu baştan çıkardılar. Bundan sonra bana uyan bendendir. Bana karşı gelen kimseyi de Sana havale ederim. Muhakkak ki Sen; Gafur, Rahim’sin."},{"n":37,"t":"Rabbımız; ben, çocuklarımdan kimini; namaz kılabilmeleri için, Senin mukaddes evinin yanında çorak bir vadiye yerleştirdim. Rabbımız; insanların gönüllerini onlara meylettir. Şükretmeleri için onları meyvelerle rızıklandır."},{"n":38,"t":"Rabbımız; doğrusu Sen, gizlediğimizi de açığa vurduğumuzu da bilirsin. Zaten yerde ve gökte hiçbir şey Allah’tan gizli kalmaz."},{"n":39,"t":"İhtiyarlığıma rağmen bana İsmail’i ve İshak’ı bahşeden Allah’a hamdolsun Doğrusu Rabbım; duaları işitendir."},{"n":40,"t":"Rabbım; beni namaz kılan eyle. Soyumdan gelenleri de. Duamı kabul buyur Rabbımız."},{"n":41,"t":"Rabbımız; hesabın görüldüğü günde beni, anamı, babamı ve mü’minleri bağışla."},{"n":42,"t":"Zalimlerin yaptıklarından Allah’ı gafil sanma. Onları sadece gözlerin dehşetle belireceği bir güne kadar tehir etmektedir."},{"n":43,"t":"O gün; başları kalkmış, gözleri kendilerine dönmeyecek şekilde sabit kalmış, gönülleri bomboş olarak koşup duracaklardır."},{"n":44,"t":"İnsanları, kendilerine azabın geleceği gün ile uyar. Zulmedenler derler ki: Rabbımız; bizi, yakın bir müddete kadar tehir et, davetine uyalım ve peygamberlere tabi olalım. Siz daha önce de sonunuzun gelmeyeceğine yemin etmemiş miydiniz?"},{"n":45,"t":"Üstelik kendilerine zulmedenlerin yerlerinde oturdunuz, onlara yaptıklarımız ise sizlere açıklanmıştı. Size misaller vermiştik."},{"n":46,"t":"Gerçekten onlar, düzenlerini kurmuşlardı. Halbuki dağları oynatacak güçte olsa bile, onların bu düzenleri hep Allah’ın elindeydi."},{"n":47,"t":"Sakın, Allah’ın peygamberlerine vaadinden cayacağını sanma. Muhakkak Allah; Aziz’dir, intikam sahibidir."},{"n":48,"t":"O gün; yer başka bir yerle değiştirilir. Gökler de başka göklerle. Ve onlar; Vahid ve Kahhar olan Allah’ın huzuruna çıkarlar."},{"n":49,"t":"O gün; mücrimleri zincirlere vurulmuş olarak görürsün."},{"n":50,"t":"Gömlekleri katrandandır, yüzlerini ateş bürüyecektir."},{"n":51,"t":"Bu; Allah’ın herkese yaptığının karşılığını vermesi içindir. Muhakkak ki Allah; hesabı çabuk görendir."},{"n":52,"t":"Bu; uyarılsınlar ve yalnızca bir tek ilah bulunduğunu bilsinler, akıl sahipleri de öğüt alsınlar diye insanlara bir tebliğdir."}],[{"n":1,"t":"Elif, Lam, Ra. Bunlar kitabın ve Kur’an’ı Mübin’in ayetleridir."},{"n":2,"t":"Kafirler bir zaman gelir ki müslüman olmayı isteyeceklerdir."},{"n":3,"t":"Bırak onları; yesinler, eğlensinler ve kendilerini emel, oyalayadursun. Sonra öğreneceklerdir."},{"n":4,"t":"Biz, hiç bir kasabayı bilinen bir yazısı olmaksızın helak etmedik."},{"n":5,"t":"Hiç bir ümmetin süresi öne geçmez, geciktiremezler de."},{"n":6,"t":"Dediler ki: Ey kendisine kitab indirilen kişi; sen, mutlaka delisin."},{"n":7,"t":"Doğru söyleyenlerden isen; bize, melekleri getirmeli değil misin?"},{"n":8,"t":"Biz, melekleri ancak hak ile indiririz. O zaman da kendilerine mühlet verilmez."},{"n":9,"t":"Muhakkak ki Kur’an’ı Biz indirdik Biz. Onun koruyucusu da elbet Biziz."},{"n":10,"t":"Andolsun ki; senden önce çeşitli milletler içinde de peygamberler göndermiştik."},{"n":11,"t":"Onlara gelen her peygamberle alay ediyorlardı."},{"n":12,"t":"Biz, böylece onu suçluların kalbine sokarız."},{"n":13,"t":"Kendilerinden öncekilerin uğradıkları ortada iken yine de ona inanmazlar"},{"n":14,"t":"Onlara gökten bir kapı açsak da çıkmaya koyulsalardı;"},{"n":15,"t":"Gözlerimiz döndü, biz herhalde büyülendik, derlerdi."},{"n":16,"t":"Andolsun ki; Biz, gökte burçlar yaptık ve onları bakanlar için donattık."},{"n":17,"t":"Ve onları kovulmuş her şeytandan koruduk."},{"n":18,"t":"Ancak kulak hırsızlığı yapan olursa; apaçık görülen bir ateş onu kovalar."},{"n":19,"t":"Yeri de döşeyip yaydık. Oraya sabit dağlar yerleştirdik. Ve orada her şeyden ölçülü olarak yetiştirdik."},{"n":20,"t":"Orada hem sizin için, hem de rızıklarını temin edemeyecekleriniz için geçimlikler meydana getirdik."},{"n":21,"t":"Hiç bir şey yoktur ki; hazinesi Bizim katımızda olmasın. Ve Biz, onu ancak belli bir ölçüye göre indiririz."},{"n":22,"t":"Rüzgarları da aşılayıcı olarak gönderdik, gökten su indirip onunla sizi suladık. Yoksa siz onu biriktiremezdiniz."},{"n":23,"t":"Doğrusu Biz, hem diriltiriz, hem de öldürürüz. Hepsine varis de Biziz."},{"n":24,"t":"Andolsun ki; sizden öne geçenleri de Biz biliriz, geride kalanları da Biz biliriz."},{"n":25,"t":"Şüphe yok ki Rabbın, onları toplayacaktır. Gerçekten O, Hakim’dir, Alim’dir."},{"n":26,"t":"Andolsun ki Biz; insanı, kuru bir çamurdan, şekillenmiş bir balçıktan yarattık."},{"n":27,"t":"Daha önce de cinnleri alevli ateşten yarattık."},{"n":28,"t":"Hani Rabbın meleklere demişti ki: Kuru bir çamurdan, şekillenmiş bir balçıktan bir insan yaratacağım."},{"n":29,"t":"Onu yapıp ruhumdan üflediğimde; siz derhal onun için secdeye kapanın."},{"n":30,"t":"Bunun üzerine meleklerin hepsi bütünüyle secde etti."},{"n":31,"t":"Ancak İblis secde edenlerle beraber olmaktan çekinerek dayattı."},{"n":32,"t":"Buyurdu ki: Ey İblis, sen neden secde edenlerle beraber değildin?"},{"n":33,"t":"Ben, dedi: Kuru bir çamurdan, şekillenmiş bir balçıktan yarattığın insana secde etmem."},{"n":34,"t":"Buyurdu ki: Öyleyse çık oradan. Sen, artık kovulmuş birisin."},{"n":35,"t":"Muhakkak ki ceza gününe kadar la’net sanadır."},{"n":36,"t":"Dedi ki: Rabbım; beni hiç olmazsa tekrar dirilecekleri güne kadar ertele,"},{"n":37,"t":"Buyurdu ki: Şüphesiz sen ertelenenlerdensin."},{"n":38,"t":"Bilinen gün gelene kadar."},{"n":39,"t":"Dedi ki: Rabbım; beni azdırdığın için, andolsun ki; ben de onlara yeryüzündeki fenalıkları güzel göstereceğim ve onların hepsini azdıracağım."},{"n":40,"t":"Ancak içlerinden ihlas verilen kulların müstesna."},{"n":41,"t":"Buyurdu ki: İşte, Benim taahhüd ettiğim dosdoğru yol budur."},{"n":42,"t":"Muhakkak ki kullarımın üzerinde senin bir nüfuzun olmaz. Ancak sana uyan sapıklar müstesna."},{"n":43,"t":"Şüphesiz onların hepsine vaadolunan yer, cehennemdir."},{"n":44,"t":"Onun yedi kapısı vardır. Ve her kapıdan onların girecekleri bir kısım vardır."},{"n":45,"t":"Müttakiler ise; muhakkak ki cennetler ve pınarlar içindedirler."},{"n":46,"t":"Selametle ve güven içinde girin oraya."},{"n":47,"t":"Biz, onların gönüllerindeki kini söküp attık. Artık onlar kardeş olarak sedirler üzerinde karşılıklı otururlar."},{"n":48,"t":"Onlara orada hiç bir yorgunluk ve zahmet değmez. Oradan çıkarılacak da değillerdir."},{"n":49,"t":"Kullarıma bildir ki: Muhakkak Benim Ben, Gafur, Rahim olan."},{"n":50,"t":"Ve muhakkak ki azabım da elem verici bir azabtır."},{"n":51,"t":"Hem onlara İbrahim’in konuklarından haber ver."},{"n":52,"t":"Onun yanına girip: Selam demişlerdi. O da: Doğrusu biz, sizden endişe ediyoruz, demişti."},{"n":53,"t":"Demişlerdi ki: Korkma, biz sana bilgin bir oğlun olacağını müjdelemeye geldik."},{"n":54,"t":"Ben, kocamışken mi bana müjde veriyorsunuz? O halde neye dayanarak müjdeliyorsunuz? dedi."},{"n":55,"t":"Dediler ki: Seni gerçekten müjdeliyoruz, öyleyse ümidini kesenlerden olma."},{"n":56,"t":"Dedi ki: Sapıklardan başka Rabbının rahmetinden kim ümidini keser?"},{"n":57,"t":"Ey elçiler; gerçek işiniz nedir? dedi."},{"n":58,"t":"Dediler ki: Biz, günahkar bir kavme gönderildik."},{"n":59,"t":"Şu kadar var ki Lut ailesi bunların dışındadır. Biz, onların hepsini behemehal kurtaracağız."},{"n":60,"t":"Karısı müstesna. Karısının geride kalanlar arasında bulunmasını takdir ettik."},{"n":61,"t":"Elçiler Lut ailesine varınca;"},{"n":62,"t":"Lut: Doğrusu siz, tanınmamış kimselersiniz, dedi."},{"n":63,"t":"Onlar da: Biz, sana sadece onların şüphe edip durdukları azabı getirdik."},{"n":64,"t":"Gerçekle geldik sana. Biz, şüphesiz doğru söyleyenleriz, dediler."},{"n":65,"t":"O halde geceleyin bir ara aileni yola çıkar, sen de arkalarından git. Hiç biriniz arkaya bakmasın ve emrolunduğunuz yere doğru yürüyün, demişlerdi."},{"n":66,"t":"Böylece ona bunların sonlarının kesilmiş olarak sabahlayacaklarını bildirdik."},{"n":67,"t":"Şehir halkı sevinerek geldiler."},{"n":68,"t":"Dedi ki: Bunlar benim konuklarımdır, onlara karşı beni mahcub etmeyin."},{"n":69,"t":"Allah’tan korkun da beni rezil etmeyin."},{"n":70,"t":"Dediler ki: Biz seni alemlerden men’etmemiş miydik?"},{"n":71,"t":"Dedi ki: Yapacaksanız işte bunlar, benim kızlarım."},{"n":72,"t":"Senin ömrüne andolsun ki, onlar sarhoşlukları içinde muhakkak serseri bir halde idiler."},{"n":73,"t":"Tan yeri ağarırken çığlık onları yakalayıverdi."},{"n":74,"t":"Ülkelerinin üstünü altına getirdi. Üzerlerine sert taş yağdırdık."},{"n":75,"t":"Bunda görebilenler için ayetler vardır."},{"n":76,"t":"O yerler, işlek yollar üzerinde hala durmaktadır."},{"n":77,"t":"Muhakkak ki bunda, inananlar için ayetler vardır."},{"n":78,"t":"Ormanlık yerde oturanlar da gerçekten zalim kimselerdi."},{"n":79,"t":"Bunun için onlardan öc aldık. Her ikisi de hala işlek bir yol üzerindedir"},{"n":80,"t":"Andolsun ki Hicr ahalisi de peygamberlerini yalanlamışlardı."},{"n":81,"t":"Onlara ayetlerimizi verdiğimiz halde yüz çevirmişlerdi."},{"n":82,"t":"Onlar, dağlardan emin evler yontup oyarlardı."},{"n":83,"t":"Sabaha karşı çığlık onları da yakalayıverdi."},{"n":84,"t":"Binaenaleyh yaptıkları da kendilerine bir fayda sağlamadı."},{"n":85,"t":"Gökleri, yeri ve aralarındakini ancak hak ile yarattık. Kıyamet günü, muhakkak gelecektir. O halde sen yumuşak ve iyi davran."},{"n":86,"t":"Muhakkak ki senin Rabbın, yaratan ve bilendir."},{"n":87,"t":"Doğrusu sana; Biz, tekrarlanan yediyi ve şu Kur’an’ı verdik."},{"n":88,"t":"Sakın onlardan bazı sınıflara verdiğimiz geçimliğe gözlerini dikme ve onlara üzülme. İnananlara kanat ger."},{"n":89,"t":"De ki: Ben apaçık bir uyarıcıyım."},{"n":90,"t":"Tıpkı o bölüşenlere indirdiğimiz gibi."},{"n":91,"t":"Onlar ki; Kur’an’ı parçalara ayırmışlardı."},{"n":92,"t":"Rabbına andolsun ki; onların hepsine birden mutlaka soracağız;"},{"n":93,"t":"Yapmakta oldukları şeyleri."},{"n":94,"t":"Sen; emrolunduğun şeyi açıkça söyle ve müşriklere aldırış etme."},{"n":95,"t":"O alaycılara karşı muhakkak ki Biz, sana yeteriz."},{"n":96,"t":"Onlar ki; Allah’la beraber başka bir tanrı edinirler. Onlar yakında bileceklerdir."},{"n":97,"t":"Andolsun; onların söylediğinden dolayı kalbinin sıkıldığını biliyoruz."},{"n":98,"t":"Sen, hemen Rabbını hamd ile tesbih et ve secde edenlerden ol."},{"n":99,"t":"Ve sana yakin gelinceye kadar Rabbına ibadet et."}],[{"n":1,"t":"Allah’ın emri geldi. Artık onu acele istemeyin. O; ortak koşmakta oldukları şeylerden münezzehtir, yücedir."},{"n":2,"t":"O, kullarından dilediğine kendi emrinden melekleri ruh ile indirir ki; Ben’den başka tanrı yoktur, Ben’den sakının, diye uyarsınlar."},{"n":3,"t":"Gökleri ve yeri hak ile yaratmıştır. Onların ortak koştukları şeyden münezzehtir."},{"n":4,"t":"İnsanı, bir damla sudan yarattı. Öyleyken o, nasıl da apaçık bir hasım kesilmiştir."},{"n":5,"t":"Hayvanları da yaratmıştır. Onlarda sizi ısıtacak şeyler ve birçok faydalar vardır. Ve onlardan yersiniz."},{"n":6,"t":"Akşamleyin getirir, sabah salarken onlarda sizin için bir güzellik vardır"},{"n":7,"t":"Kendi kendinize zor varacağınız memleketlere yüklerinizi taşırlar. Muhakkak ki Rabbınız; Rauf’tur, Rahim’dir."},{"n":8,"t":"Atları, katırları ve merkebleri de sizin için binek ve süs hayvanı olarak yaratmıştır. Bilmediğiniz daha nice şeyleri de yaratır."},{"n":9,"t":"Yolun doğrusunu göstermek Alla’a aittir. Ondan sapan da vardır. O, dileseydi; hepinizi birlikte doğru yola iletirdi."},{"n":10,"t":"O’dur size semadan su indiren, ondan içersiniz. Ve hayvanları otlattığınız bitki de onunla biter."},{"n":11,"t":"Onunla size ekinler, zeytin ve hurma ağaçları, üzümler ve türlü türlü ürünler bitirir. Düşünen bir kavim için bunda ayetler vardır."},{"n":12,"t":"Geceyi, gündüzü, güneşi ve ayı sizin buyruğunuza verdi. Yıldızlar da O’nun buyruğu ile müsahhar kılınmıştır. Muhakkak ki bunda, akleden bir kavim için ayetler vardır."},{"n":13,"t":"Yeryüzünde rengarenk şeyleri de sizin için O, yaratmıştır. Muhakkak ki öğüt alan bir kavim için bunda ayetler vardır."},{"n":14,"t":"Taze et yemeniz, giyineceğiniz süs eşyanızı çıkarmanız ve Allah’ın bol nimetinden istifade etmeniz için; denizi müsahhar kılan O’dur. Gemilerin onu yara yara gittiğini görürsün, O’nun lutfunu aramanız ve şükretmeniz içindir, belki şükredersiniz artık."},{"n":15,"t":"Yeryüzünde sarsılmayasınız diye sabit dağlar, nehirler ve yollar koymuştur ki onunla, doğru yolu bulasınız."},{"n":16,"t":"İşaretler de. Yıldızlarla da, onlar yollarını bulurlar."},{"n":17,"t":"Yaratan; yaratmayan gibi midir hiç? Artık öğüt almaz mısınız?"},{"n":18,"t":"Allah’ın nimetini sayacak olursanız; bitiremezsiniz. Muhakkak ki Allah; Gafur’dur, Rahim’dir."},{"n":19,"t":"Allah; gizlediklerinizi de, açığa vurduklarınızı da bilir."},{"n":20,"t":"Allah’tan başka taptıkları; hiç bir şey yaratamazlar. Çünkü onların kendileri yaratılmıştır."},{"n":21,"t":"Onlar; diri değil, ölüdürler. Ne zaman dirileceklerini de fark edemezler."},{"n":22,"t":"İlahınız; tek bir ilahtır. Ahirete inanmayanların kalbleri inkar edicidir ve onlar büyüklük taslayanlardır."},{"n":23,"t":"Şüphesiz Allah; onların gizlediklerini de, açığa vurduklarını da bilir. Ve O; büyüklük taslayanları sevmez."},{"n":24,"t":"Onlara: Size Rabbınız ne indirdi? denildiği zaman; geçmişlerin masallarını, derler."},{"n":25,"t":"Bununla onlar; kıyamet günü kendilerinin bütün yüklerini taşıdıktan başka, bilgisizlikle baştan çıkardıklarının yüklerinden bir kısmını da sırtlarlar. Dikkat edin; yüklendikleri yük, ne kötüdür."},{"n":26,"t":"Kendilerinden öncekiler de düzen kurmuşlardı. Bunun üzerine Allah; binalarını temellerinden çökertti de üstlerindeki tavanları başlarına yıkıldı. Hem bu azab; onlara hissedemeyecekleri taraftan gelmişti."},{"n":27,"t":"Sonra da kıyamet gününde onları rezil eder ve der ki: Haklarında tartıştığınız Benim ortaklarım nerede? Kendilerine bilgi verilmiş olanlar derler ki: Doğrusu bugün, rezillik ve zillet kafirleredir."},{"n":28,"t":"Melekler; kendilerine zulmetmiş olanların canını alırken: Biz, hiç bir kötülük yapmıyorduk, diyerek teslim olurlar. Hayır, Allah sizin neler yaptığınızı bilir."},{"n":29,"t":"Haydi cehennemin kapılarından girin. Orada temelli kalacaksınız. Büyüklenenlerin durağı ne kötüdür."},{"n":30,"t":"Müttakilere: Rabbınız ne indirdi? denildiği vakit: Hayır indirdi, derler. Bu dünyada ihsan edenlere iyilik vardır, ahiret yurdu ise daha hayırlıdır. Müttakilerin yurdu ne de güzeldir."},{"n":31,"t":"Adn cennetlerine girerler. Onların altlarından ırmaklar akar. Orada diledikleri kendilerinindir. Ve işte Allah; müttakileri böyle mükafatlandırır."},{"n":32,"t":"Onlar; meleklerin, güzel güzel canlarını alacakları kimselerdir. Selam size, yaptıklarınıza karşılık haydi girin cennete, derler."},{"n":33,"t":"Onlar, kendilerine meleklerin veya Rabbının emrinin gelmesini mi bekliyorlar? Onlardan öncekiler de böyle yapmışlardı. Allah onlara zulmetmedi, fakat onlar kendilerine zulmediyorlardı."},{"n":34,"t":"Bunun için işledikleri kötülüklere uğradılar ve alay ettikleri şey onları kuşattı."},{"n":35,"t":"Şirk koşanlar dediler ki: Allah dileseydi; ne biz ne de babalarımız O’ ndan başka bir şeye tapınırdık. O’nun emri dışında hiç bir şeyi haram kılmazdık. Onlardan öncekiler de şöyle yapmışlardı. Peygambere apaçık tebliğden başka ne düşer?"},{"n":36,"t":"Andolsun ki; her ümmete: Allah’a ibadet edin ve putlardan kaçının, diye peygamberler göndermişizdir. Allah, içlerinden kimini hidayete erdirdi. Kimi de sapıklığı hak etti. Şimdi yeryüzünde gezin de; peygamberleri yalanlayanların sonunun nasıl olduğunu görün."},{"n":37,"t":"Onların hidayeti bulmalarına ne kadar hırs göstersen; muhakkak ki Allah dalalete sapanı hidayete erdirmez. Ve onların yardımcıları da yoktur."},{"n":38,"t":"Onlar: Ölen kimseyi Allah diriltmez, diye olanca güçleriyle yemin ettiler. Hayır öyle değil. Bu, O’nun dosdoğru bir vaadidir. Ancak insanların çoğu bilmezler."},{"n":39,"t":"Üzerinde ihtilafa düştükleri şeyi onlara açıklasın ve küfredenler gerçekten yalancı olduklarını bilsinler diye, diriltecektir."},{"n":40,"t":"Bir şeyin olmasını istediğimiz zaman ona, sözümüz sadece; ol, demektir ve o, hemen oluverir."},{"n":41,"t":"Zulmedildikten sonra, Allah yolunda hicret eden kimseleri, andolsun ki; dünyada güzel bir yere yerleştiririz. Ahiret mükafatı ise daha büyüktür. Şayet bilselerdi."},{"n":42,"t":"Onlar sabreden ve yalnız Rabblarına tevekkül edenlerdir."},{"n":43,"t":"Senden önce de ancak kendilerine vahyeder olduğumuz adamlar gönderdik. Öyleyse bilmiyorsanız zikir ehline sorun."},{"n":44,"t":"Kitablar ve apaçık delillerle. Sana da insanlara indirileni açıklayasın diye bu zikri indirdik. Belki düşünürler."},{"n":45,"t":"Kötü işler düzenleyenler; Allah’ın kendilerini yere batırmasından, yahut haberleri yokken üzerlerine ansızın azab gelmesinden emin mi bulunuyorlar?"},{"n":46,"t":"Yahut onlar dönüp dolaşırken kendilerini yakalamasından mı? Allah’ı aciz bırakacak değillerdir."},{"n":47,"t":"Yahut yok olmak endişesindeyken yakalamasından mı? Muhakkak ki Rabbın, Rauf’tur, Ramim’dir."},{"n":48,"t":"Allah’ın yarattığı şeylerin gölgelerinin sağa sola vurarak boyun eğip Allah’a secde ettiklerini görmüyorlar mı?"},{"n":49,"t":"Göklerde ve yerde bulunan canlılar ve melekler, büyüklük taslamaksızın Allah’a secde ederler."},{"n":50,"t":"Üstlerinden, Rabblarından korkarlar ve emrolundukları şeyleri yaparlar."},{"n":51,"t":"Allah buyurdu ki: İki ilah edinmeyin. O, ancak bir tek ilahtır. Yalnız Ben’den korkun."},{"n":52,"t":"Göklerde ve yerde ne varsa hepsi O’nundur. Din de sürekli olarak O’nundur. Yoksa Allah’tan başkasından mı sakınıyorsunuz?"},{"n":53,"t":"Sizdeki her nimet, Allah’tandır. Sonra bir sıkıntıya uğradığınızda yalnız O’na sığınırsınız."},{"n":54,"t":"Sonra sıkıntınızı giderince de içinizden bir grup; Rabblarına şirk koşarlar."},{"n":55,"t":"Kendilerine verdiğimize nankörlük etmeleri için. Geçinin bakalım, yakında bileceksiniz."},{"n":56,"t":"Kendilerine verdiğimiz rızıktan, bilmediklerine pay ayırırlar. Allah’a andolsun ki; uydurup durduğunuz şeylerden muhakkak sorguya çekileceksiniz."},{"n":57,"t":"Onlar; Allah’a kızlar isnad ederler. O’nun sanı yücedir. Hoşlandıkları da kendilerinindir."},{"n":58,"t":"Onlardan birine bir kızı olduğu müjdelenirse; içi öfkeyle dolarak yüzü simsiyah kesilir."},{"n":59,"t":"Kendisine verilen kötü müjde yüzünden halktan gizlenmeye çalışır. Utana utana onu tutsun mu, yoksa toprağa mı gömsün? Bakın ne kötü hükmediyorlar."},{"n":60,"t":"Ahirete inanmayanlar kötülük örneğidirler. En yüce örnek ise Allah’ındır. O; Aziz’dir, Hakim’dir."},{"n":61,"t":"Şayet Allah, zulümlerinden dolayı insanları yakalayacak olsaydı; yeryüzünde bir tek canlı bırakmazdı. Fakat onları belli bir müddete kadar tehir eder. Müddetleri dolunca onu ne bir an geciktirebilirler, ne de bir an öne alabilirler."},{"n":62,"t":"Hoşlanmadıklarını Allah’a mal ederler. Dilleri de güzel şeylerin kendilerinde olduğunu yalan yere söyler durur. Şüphesiz cehennem onlarındır. Ve onlar, gerçekten aşırı gidenlerdir."},{"n":63,"t":"Allah’a andolsun ki; senden önceki ümmetlere de elçiler gönderdik. Şeytan onlara yaptıklarını güzel gösterdi. Bugün de onların dostu odur. Ve onlar için elim bir azab vardır."},{"n":64,"t":"Sana kitabı; sırf ihtilafa düştükleri şeyleri onlara açıklaman için ve inananlar topluluğuna hidayet ve rahmet olmak üzere indirdik."},{"n":65,"t":"Allah; gökten su indirir de onunla yeryüzünü öldükten sonra tekrar diriltir. Muhakkak ki bunda, dinleyen topluluklar için ayet vardır."},{"n":66,"t":"Sizin için hayvanlarda da ibret vardır. Onların karınlarındaki fışkı ile kan arasından; size, içenlerin boğazından kolaylıkla geçen dupduru bir süt içiririz."},{"n":67,"t":"Hurma ağaçlarının meyvelerinden ve üzümlerden; şerbet, şıra ve güzel rızık elde edersiniz. Akleden bir kavim için bunda bir ayet vardır."},{"n":68,"t":"Ve Rabbın bal arısına vahyetti ki: Dağlarda, ağaçlarda ve hazırlanmış kovanlarda yuva edin."},{"n":69,"t":"Sonra her tür üründen ye. Sonra da Rabbının işlemen için gösterdiği yoldan yürü. Karınlarından insanlara şifa olan, renkleri çeşit çeşit bir içecek çıkar. Bunda düşünen bir kavim için şüphesiz bir ayet vardır."},{"n":70,"t":"Allah sizi yaratmıştır, sonra da öldürecektir. İçinizden bir kısmı ömrünün en fena zamanına ulaştırılır ki bilirken bilmez olur. Muhakkak Allah Alim’dir, Kadir’dir."},{"n":71,"t":"Allah; rızık hususunda kiminizi kiminizden üstün kıldı. Üstün kılınanlar buyrukları altında bulunanların rızıklarını vermezler. Halbuki bunda hepsi eşittir. Yoksa Allah’ın nimetini bile bile inkar mı ediyorlar?"},{"n":72,"t":"Allah sizin için kendinizden eşler yarattı. Eşlerinizden de sizin için oğullar, torunlar varetti. Temiz şeylerden size rızık verdi. Böyleyken batıla inanıyorlar da Allah’ın nimetine nankörlük mü ediyorlar?"},{"n":73,"t":"Onlar; Allah’ı bırakarak, göklerden ve yerden kendilerine verecek rızıkları olmayan, olsa bile veremeyen şeylere mi tapınıyorlar?"},{"n":74,"t":"Allah’a benzerler koşmaya kalkmayın. Şüphesiz Allah bilir, siz bilmezsiniz."},{"n":75,"t":"Allah, size bir misal verir: Başkasının malı olan ve hiç bir şeye gücü yetmeyen bir köle ile tarafımızdan güzel bir rızka nail olup gizli veya açık infak eden; hiç bir olur mu? Hamd, Allah’a mahsustur. Fakat onların çoğu bilmezler."},{"n":76,"t":"Allah; iki kişiyi de misal veriyor: Biri hiç bir şeye gücü yetmez bir dilsizdir ki, efendisine yüktür. Nereye gönderse bir hayır getirmez. Bununla; doğru yolda olup adaletle emreden bir olur mu hiç?"},{"n":77,"t":"Göklerin ve yerin gaybı Allah’ındır. Saat hadisesi ise ancak bir göz kırpma gibi veya daha yakındır. Şüphesiz ki Allah; her şeye Kadir’dir"},{"n":78,"t":"Sizi, annelerinizin karnından Allah çıkardı. Hiç bir şey bilmezdiniz. Ve size kulaklar, gözler ve gönüller verdi ki şükredesiniz."},{"n":79,"t":"Göğün boşluğunda; Allah’ın buyruğuna boyun eğerek uçan kuşlara bakmıyorlar mı? Onları Allah’tan başka kimse tutmaz. İnanan bir kavim için muhakkak ki bunda ayetler vardır."},{"n":80,"t":"Allah evlerinizi sizin için bir huzur ve sükun yeri yaptı ve size hayvan derilerinden; gerek göç gününde gerek konduğunuz günde hafifçe taşıyacağınız evler; yünlerinden, yapağılarından, kıllarından bir zamana kadar giyimlik, döşemelik ve ticaret kumaşı verdi."},{"n":81,"t":"Allah; yaratıklarından sizin için gölgeler yapmış, dağlarda sığınacağınız barınaklar var etmiş, sizi sıcaktan koruyacak elbiseler, harbde muhafaza edecek zırhlar vermiştir. Müslüman olasınız diye, size olan nimetini işte böylece tamamlamıştır."},{"n":82,"t":"Eğer yüz çevirirlerse; sana düşen, ancak açıkça tebliğdir."},{"n":83,"t":"Allah’ın nimetini hem bilirler, hem de inkar ederler. Zaten onların çoğu kafirdirler."},{"n":84,"t":"Her ümmetten birer şahit göndereceğimiz gün; inkar edenlere itiraz için izin verilmez, özürleri de dinlenmez."},{"n":85,"t":"O zalimler azabı görünce; onlardan ne hafifletilir, ne de mühlet verilir."},{"n":86,"t":"Allah’a şirk koşanlar; şirk koştuklarını gördüklerinde derler ki: Rabbımız; işte şunlar, seni bırakıp da kendilerine yalvardığımız şeriklerimizdir. Bunlar da onlara: Doğrusu siz yalancılarsınız, diyerek söz atarlar."},{"n":87,"t":"O gün Allah’a arz-ı teslimiyet ederler. Uydurdukları şeyler onlardan uzaklaşıp gitmiştir."},{"n":88,"t":"Küfredip de Allah yolundan alıkoyanlara; bozgunculuk yaptıklarından dolayı azab üstüne azabı artırdık."},{"n":89,"t":"Her ümmette bir kişiyi aleyhlerine şahid gönderdiğimiz gün; seni de onların üzerine tastamam şahid olarak getirdik. Sana; her şeyi açıklayan, hidayet ve rahmet, müslümanlara da bir müjde olan kitabı indirdik."},{"n":90,"t":"Muhakkak ki Allah; adaleti, ihsanı, yakınlara vermeyi emreder. Hayasızlığı, fenalığı ve taşkınlığı ise yasaklar. Tezekkür edesiniz diye size öğüt verir."},{"n":91,"t":"Ahidleştiğiniz zaman; Allah’ın ahdini yerine getirin. Pekiştirdiğiniz yeminleri bozmayın. Çünkü Allah’ı üzerinize kefil yapmışsınızdır. Muhakkak ki Allah; yaptıklarınızı bilir."},{"n":92,"t":"İpliğini iyice eğirip katladıktan sonra, söküp bozan kadın gibi olmayın. Bir ümmetin diğerinden daha çok olmasından ötürü yeminlerinizi aranızda aldatma vasıtası yapıyorsunuz. Allah, onunla sizi imtihan eder. Kıyamet günü ihtilaf ettiğiniz şeyleri elbette size beyan edecektir."},{"n":93,"t":"Allah dileseydi; sizi bir tek ümmet yapardı. Ama O; istediğini saptırır, istediğini doğru yola iletir. İşlediklerinizden muhakkak sorumlu tutulacaksınız."},{"n":94,"t":"Yeminlerinizi aranızda hile ve bozgun vesilesi yapmayın. Çünkü bu yüzden sağlamca yere basmakta olan ayak, kayabilir. Allah yolundan alıkoyduğunuz için kötü bir azab tadarsınız. Ve sizin için büyük bir azab vardır."},{"n":95,"t":"Allah’ın ahdini az bir pahaya değişmeyin. Eğer bilirseniz; Allah katında olan, sizin için daha hayırlıdır."},{"n":96,"t":"Sizin yanınızdaki tükenir. Allah’ın katında olanlar ise sonsuzdur. Sabredenlere mükafatlarını, yaptıklarının daha güzeli ile ödeyeceğiz."},{"n":97,"t":"Kadın olsun, erkek olsun; her kim, inanmış olarak iyi amel işlerse; ona hoş bir hayat yaşatacağız. Mükafatlarını yaptıklarından daha güzeli ile ödeyeceğiz."},{"n":98,"t":"Kur’an okuyacağın zaman; kovulmuş şeytandan Allah’a sığın."},{"n":99,"t":"Doğrusu inananlar ve yalnız Rabblarına güvenenler üzerinde, onun bir nüfuzu yoktur."},{"n":100,"t":"Onun nüfuzu; sadece onu dost edinenler ve Allah’a şirk koşanlar üzerindedir."},{"n":101,"t":"Biz, bir ayetin yerine başka bir ayet getirdiğimiz zaman; Allah ne indirdiğini gayet iyi bilirken, onlar: Sen sadece uyduruyorsun, derler. Hayır onların çoğu bunu bilmezler."},{"n":102,"t":"De ki: Onu Ruh-el Kudüs, mü’minlerin imanını pekiştirmek, müslümanlara hidayet ve müjde olmak üzere Rabbın katından hak ile indirmiştir."},{"n":103,"t":"Andolsun ki; ona mutlaka bir insan öğretiyor, dediklerini biliyoruz. Kasdettikleri kişinin dili yabancıdır. Kur’an ise apaçık arapçadır."},{"n":104,"t":"Muhakkak ki Allah’ın ayetlerine inanmayanları; Allah, doğru yola eriştirmez. Onlara elim bir azab vardır."},{"n":105,"t":"Allah’ın ayetlerine inanmayanlar; sadece yalan uydururlar. Ve işte onlar yalancıların kendileridir."},{"n":106,"t":"Kalbi imanla dolu olduğu halde zorlananların dışında, her kim; imanından sonra Allah’ı tanımayıp küfre göğüs açarsa; işte Allah’ın gazabı onların üzerinedir. Ve onlar için büyük bir azab vardır."},{"n":107,"t":"Bu, dünya hayatını ahirete tercih etmeleri ve Allah’ın da kafirler topluluğunu hidayete eriştirmemesinden ötürü, böyledir."},{"n":108,"t":"Onlar; Allah’ın kalblerini, kulaklarını ve gözlerini mühürlediği kimselerdir. Ve gafiller de işte bunlardır."},{"n":109,"t":"Şüphesiz ki ahiret gününde de hüsrana uğrayacaklar işte bunlardır."},{"n":110,"t":"Hem Rabbın; işkenceye uğratıldıktan sonra hicret eden, sonra Allah yolunda savaşan ve sabredenlerle birliktedir. Muhakkak ki Rabbın; bundan sonra da Gafur’dur, Rahim’dir."},{"n":111,"t":"O gün herkes öz nefsi için uğraşacaktır. Herkes ne yaptıysa kendisine eksiksiz olarak verilecek, onlar; asla haksızlığa uğratılmayacaklardır."},{"n":112,"t":"Allah; size, huzur ve güven içinde bir kasabayı misal olarak verir. Her yandan oraya bol bol rızık geliyordu. Ama Allah’ın nimetine nankörlük ettiler de yaptıklarından dolayı Allah onlara açlık ve korku belasını tattırdı."},{"n":113,"t":"Andolsun ki; onlara, kendilerinden bir peygamber gelmişti de onu yalanlamışlardı. Zulüm ederken kendilerini azab yakalayıvermişti."},{"n":114,"t":"Artık Allah’ın size rızık olarak verdiği şeylerden helal ve temiz olarak yeyin. Eğer O’na kulluk edecekseniz; Allah’ın nimetine şükredin."},{"n":115,"t":"O; size ancak ölüyü, kanı, domuz etini, bir de Allah’tan başkası için kesilmiş olanı haram kıldı. Mecbur olan; saldırmamak ve haddi aşmamak şartıyla bunun dışındadır. Şüphesiz Allah; Gafur’dur, Rahim’dir."},{"n":116,"t":"Diliniz yalan yere vasıflandırageldiği için her şeye: Şu helal; bu haramdır demeyin. Çünkü Allah’a karşı yalan uydurmuş olursunuz. Şüphesiz ki Allah’a karşı yalan uyduranlar, asla felah bulmazlar."},{"n":117,"t":"Az bir geçim ve ardından onlara elim bir azab vardır."},{"n":118,"t":"Sana anlattıklarımızı daha evvel Yahudi olanlara da haram kılmıştık. Biz onlara zulmetmemiştik, fakat onlar kendilerine zulmetmişlerdi."},{"n":119,"t":"Hem Rabbın; bilmeyerek kötülük işleyip de tevbe eden ve ıslah olanlardan yanadır. Bundan sonra da Rabbın; muhakkak Gafur’dur, Rahim’dir."},{"n":120,"t":"Muhakkak ki İbrahim; başlı başına bir ümmetti. Allah’a itaat ederdi ve bir Hanif idi. Hiç bir zaman müşriklerden olmamıştır."},{"n":121,"t":"Rabbının nimetlerine şükrederdi. Onu beğenip seçmiş, kendisini doğru bir yola iletmişti."},{"n":122,"t":"Dünyada ona iyilik verdik. Doğrusu o, ahirette de iyilerdendir."},{"n":123,"t":"Sonra sana: Hanif olarak İbrahim’in dinine uy; o, hiç bir zaman müşriklerden olmadı, diye vahyettik."},{"n":124,"t":"Cumartesi; ancak o gün üzerinde ihtilafa düşenlere farz kılındı. Şüphesiz Rabbın; onların ihtilaf edegeldikleri şeyler hakkında kıyamet günü aralarında hükmünü verecektir."},{"n":125,"t":"Rabbının yoluna hikmetle ve güzel öğütle davet et. Onlarla en güzel şekilde tartış. Muhakkak ki Rabbın; yolundan sapanları en iyi bilir. O, doğru yolda olanları da en iyi bilendir."},{"n":126,"t":"Eğer ceza verecek olursanız; ancak sizin cezalandırıldığınızın misliyle ceza verin. Sabrederseniz; elbette bu, sabredenler için daha iyidir."},{"n":127,"t":"Sabret; senin sabrın ancak Allah içindir. Üzülme onlara. Kurdukları düzenlerden dolayı da endişe etme."},{"n":128,"t":"Şüphesiz ki Allah; müttakiler ve ihsan edenlerle beraberdir."}],[{"n":1,"t":"Şanı yücedir o Allah’ın ki; kulunu geceleyin Mescid-i Haram’dan çevresini mübarek kıldığımız Mescid-i Aksa’ya götürmüştür. Bir kısım ayetlerimizi gösterelim diye. Muhakkak ki O’dur O, Semi’, Basir."},{"n":2,"t":"Musa’ya da kitabı verdik. Ve onu, İsrailoğulları için bir hidayet kıldık. Beni bırakıp başkasını vekil edinmeyesiniz diye."},{"n":3,"t":"Nuh ile beraber taşıdığımız kimselerin soyunu da. Gerçekten o, çok şükreden bir kul idi."},{"n":4,"t":"İsrailoğullarına kitabda hükmettik ki: Doğrusu yeryüzünde iki defa bozgunculuk yapacak ve kibirlendikçe kibirleneceksiniz."},{"n":5,"t":"O ikiden birincisinin vakti gelince, üzerinize çok güçlü olan kullarımızı saldık. Onlar, memleketin her köşesini kontrollarına aldılar. Bu, yerine gelmiş bir vaad idi."},{"n":6,"t":"Bundan sonra sizi, onlara tekrar galip getirdik. Mallar ve oğullarla size yardım ederek sayınızı artırdık."},{"n":7,"t":"Eğer ihsan ederseniz; kendiniz için ihsan etmiş olursunuz. Kötülük ederseniz; o da kendinizedir. Diğerinin vakti gelince; yüzünüzü karartsınlar, mescide ilk defa girdikleri gibi girsinler ve ele geçirdikleri yeri harab etsinler diye onları tekrar göndeririz."},{"n":8,"t":"Belki Rabbınız size merhamet eder. Eğer dönerseniz; Biz de döneriz ve Biz, cehennemi kafirler için bir zindan kılmışızdır."},{"n":9,"t":"Muhakkak ki bu Kur’an; en doğru olana götürür. Ve salih amel işleyen mü’ minlere kendileri için büyük bir mükafat olduğunu müjdeler."},{"n":10,"t":"Ahirete inanmayanlar; onlar için elem verici bir azab hazırladık."},{"n":11,"t":"İnsan; hayır istiyormuşçasına şer ister. Ve insan, esasen çok acelecidir."},{"n":12,"t":"Biz, geceyi ve gündüzü iki ayet kıldık. Rabbınızdan lutuf dileyesiniz ve yılların hesabını, sayısını bilesiniz diye gece ayetini silip gündüz ayetini aydınlık kıldık. Ve her şeyi uzun uzadıya açıkladık."},{"n":13,"t":"Her insanın işlediklerini boynuna dolarız. Ve onun için kıyamet gününde açılmış bulacağı bir kitab çıkarırız."},{"n":14,"t":"Oku kitabını. Bugün kendi hesabın için kendi nefsin sana yeter."},{"n":15,"t":"Kim, hidayete ererse; kendi nefsi için hidayete ermiş olur. Kim de dalalete düşerse; kendi nefsi aleyhine dalalete düşmüş olur. Hiç kimse başkasının yükünü yüklenmez. Biz, bir peygamber göndermedikçe azab ediciler değiliz."},{"n":16,"t":"Bir kasabayı da helak etmek istediğimiz zaman; varlıklılarına emir veririz de, orada fasıklık yaparlar. Bunun üzerine artık oraya söz hak olur. Ve Biz de onları yerle bir ederiz."},{"n":17,"t":"Nuh’tan sonra, nice nesilleri yok etmişizdir. Kullarının günahlarına Habir ve Basir olarak Rabbın yeter."},{"n":18,"t":"Kim geçici dünyayı isterse; onun için orada dilediğimiz kadar, dilediğimiz kimseye hemen veririz. Sonra onun için cehennemi hazırlarız. Kötülenmiş ve koğulmuş olarak oraya girer."},{"n":19,"t":"Kim de ahireti isterse ve onun için inanmış olarak gerekli çabayı gösterirse; işte onların say’i şükre değerdir."},{"n":20,"t":"Her birine, bunlara da, onlara da Rabbının nimetinden ulaştırırız. Rabbının nimeti engellenmiş değildir."},{"n":21,"t":"Bak, nasıl onların bir kısmını bir kısmına üstün kıldık. Elbetteki ahiret; dereceler bakımından da büyüktür, üstünlük bakımından da."},{"n":22,"t":"Allah ile beraber başka ilah edinme. Yoksa yerilmiş ve terkedilmiş olarak kalırsın."},{"n":23,"t":"Rabbın buyurmuştur ki: Kendisinden başkasına ibadet etmeyesiniz, ana ve babaya iyi davranasınız. Eğer onlardan biri veya her ikisi senin yanında iken yaşlılığa erecek olurlarsa; onlara karşı, of dahi deme. Onları azarlama. Ve her ikisine de efendice sözler söyle."},{"n":24,"t":"Merhametten onlara alçak gönüllülük kanatlarını ger. Ve de ki: Rabbım; o ikisi, beni küçükken yetiştirdikleri gibi sen de onlara merhamet et."},{"n":25,"t":"Rabbınız; nefislerinizde olanı en iyi bilendir. Eğer salihlerden olursanız muhakkak ki O; kendisine dönenler için Gafur’dur."},{"n":26,"t":"Yakınlara hakkını ver. Miskine, yolcuya da. Ama saçıp savurma."},{"n":27,"t":"Muhakkak ki saçıp savuranlar, şeytanlarla kardeş olmuşlardır. Şeytan ise Rabbına pek nankördür."},{"n":28,"t":"Rabbından beklediğin bir rahmeti elde etmek için onlardan yüz çevirmek zorunda kalırsan; o zaman onlara tatlı bir söz söyle."},{"n":29,"t":"Ve elini boynuna bağlı kılma, onu büsbütün de açıp durma. Yoksa kaybedenlerden ve kınananlardan olursun."},{"n":30,"t":"Muhakkak ki Rabbın; dilediğine rızkı genişletir ve daraltır. Muhakkak ki O; kulları için Habir’dir, Basir’dir."},{"n":31,"t":"Çocuklarınızı açlık korkusuyla öldürmeyin. Onlara da size de Biz; rızık veririz. Muhakkak ki onları öldürmek, büyük bir günahtır."},{"n":32,"t":"Zinaya yaklaşmayın. Muhakkak ki o, azgınlıktır. Ve yol olarak da kötüdür."},{"n":33,"t":"Allah’ın haram kıldığı canı öldürmeyin. Ancak hak ile olursa müstesna. Kim, zulmedilerek öldürülürse; gerçekten Biz, onun velisine bir yetki kılmışızdır. Artık o da öldürmekte aşırı gitmesin. Muhakkak ki o, yardım görenlerden olmuştur."},{"n":34,"t":"Erginlik çağına ulaşıncaya kadar, en güzel şeklin dışında yetimin malına yaklaşmayın. Ahdi yerine getirin. Muhakkak ki ahid, mes’uliyettir."},{"n":35,"t":"Ölçtüğünüz zaman da; ölçüyü tam tutun. Ve dosdoğru ölçekle tartın. Bu, daha hayırlı ve netice itibariyle daha güzeldir."},{"n":36,"t":"Hakkında bilgin olmadığı şey üzerinde durma. Çünkü kulak da, göz de, kalb de bütün bunlar ondan sorumludurlar."},{"n":37,"t":"Yeryüzünde kibirlenerek yürüme. Şüphesiz ki sen, ne yeri yarabilirsin, ne de boyca dağlara ulaşabilirsin."},{"n":38,"t":"Bütün bunlar, Rabbın katında beğenilmeyen kötü şeylerdir."},{"n":39,"t":"Bunlar, Rabbının sana vahyettiği hikmettendir. Allah ile beraber bir başka ilah edinme. Yoksa kınanmış ve kovulmuş olarak cehenneme atılırsın."},{"n":40,"t":"Yoksa Rabbınız size oğulları seçti de kendisi meleklerden kızlar mı edindi? Muhakkak ki siz, büyük bir söz söylüyorsunuz."},{"n":41,"t":"Andolsun ki; Biz, öğüt alsınlar diye bu Kur’an’da çeşitli açıklamalar yaptık. Fakat bu, onların nefretinden başka bir şeyi artırmıyor."},{"n":42,"t":"De ki: Onların dedikleri gibi Allah ile beraber tanrılar bulunsaydı; o zaman, hepsi Arş’ın sahibi olmaya bir yol ararlardı."},{"n":43,"t":"Onların söylediklerinden O, münezzehtir, yücedir ve uludur."},{"n":44,"t":"Yedi gök, yeryüzü ve içinde bulunanlar; O’nu tesbih ederler. O’nu hamd ile tesbih etmeyen hiç bir şey yoktur. Ama siz, onların tesbihlerini anlamazsınız. Muhakkak ki O; Halim, Gafur olandır."},{"n":45,"t":"Kur’an okuduğun zaman; seninle ahirete inanmayanların arasına örtülmüş bir perde koyarız."},{"n":46,"t":"Onu anlarlar diye kalblerine örtüler koyduk. Kulaklarına da ağırlık. Kur’an’da Rabbını tek olarak zikrettiğin zaman da onlar nefret ederek arkalarına döner giderler."},{"n":47,"t":"Biz, onların seni dinledikleri zaman; neye kulak verdiklerini çok iyi biliriz. Gizli toplandıkları zaman da hani zalimler diyorlardı ki: Siz, sadece büyülenmiş bir adama tabi oluyorsunuz."},{"n":48,"t":"Bak, sana nasıl misaller veriyorlar. Bunun için dalalete düşmüşlerdir. Ve bir daha yol bulamamaktadırlar."},{"n":49,"t":"Ve dediler ki: Biz, kemik ve ufalanmış toprak olduğumuzda mı, cidden biz yeni bir yaratılışla diriltilecek miyiz?"},{"n":50,"t":"De ki: İster taş ister demir olun,"},{"n":51,"t":"Veya gözünüzde büyüttüğünüz bir yaratık olun. Diyecekler ki: Bizi tekrar kim diriltir? De ki: Sizi ilk defa yaratmış olan. Sana başlarını sallayacaklar ve ne zaman o? diyecekler. De ki: Yakın olması umulur."},{"n":52,"t":"O, sizi çağırdığı gün; hamdederek davetine uyarsınız. Ve çok az kalmış olduğunuzu zannedersiniz."},{"n":53,"t":"Kullarıma de: En güzel olanı söylesinler. Doğrusu şeytan aralarını açmak ister. Zira şeytan, insan için apaçık bir düşman olmuştur."},{"n":54,"t":"Rabbınız sizi daha iyi bilir. İsterse size merhamet eder, isterse sizi azablandırır. Biz; seni, onların üzerine vekil olarak göndermedik."},{"n":55,"t":"Rabbın göklerde ve yerde olanları daha iyi bilendir. Andolsun ki; Biz, peygamberlerden bir kısmını bir kısmına üstün kıldık, Davud’a da Zebur’u verdik."},{"n":56,"t":"De ki: O’ndan başka taptıklarınızı çağırın. Sizin bir sıkıntınızı gidermeye de, değiştirmeye de güçleri yetmez."},{"n":57,"t":"Onlar, Rabblarına vesile arayarak daha yakın olmak için bunlara taparlar. O’nun rahmetini umarlar, azabından korkarlar. Zira Rabbının azabı, sakınılmaya değerdir."},{"n":58,"t":"Hiç bir kasaba yoktur ki; kıyamet gününden önce Biz, onu helak edecek veya şiddetli bir azabla azablandıracak olmayalım. Bu, Kitab’da yazılmıştır."},{"n":59,"t":"Bizi ayetlerle göndermekten alıkoyan şey; ancak öncekilerin onları yalanlamış olmalarıdır. Semud’a da gözleri göre göre bir dişi deve vermiştik de, ona zulmetmişlerdi. Halbuki Biz; ayetleri ancak korkutmak için göndeririz."},{"n":60,"t":"Hani sana demiştik ki: Rabbın gerçekten insanları kuşatmıştır. Sonra göstermiş olduğumuz rüyayı sadece insanlar için bir imtihan kıldık. Kur’an’da lanetlenmiş olan ağacı da. Biz onları korkutuyoruz ama bu, onlara büyük bir azgınlık vermekten başka bir şeyi artırmıyor."},{"n":61,"t":"Hani meleklere demiştik ki: Adem’e secde edin. Onlar secde etmilerdi. Sadece İblis müstesna. Ve demişti ki: Çamurdan yaratmış olduğuna mı secde edeceğim?"},{"n":62,"t":"Benden üstün kıldığını görüyor musun? Eğer beni kıyamet gününe kadar tehir edersen; pek azı müstesna, onun soyunu emrim altına alırım, demişti."},{"n":63,"t":"Buyurmuştu ki: Haydi git, onlardan her kim sana uyarsa; muhakkak cehennem sizin cezanızdır. Hem de tam bir ceza."},{"n":64,"t":"Sesinle onlardan gücünün yettiğini yerinden oynat. Atlılarınla ve yayalarınla onlara karşı haykırarak yürü. Mallarda ve çocuklarda onlara ortak ol. Ve vaadde bulun kendilerine. Şeytan ancak aldatmak için vaad eder onlara."},{"n":65,"t":"Muhakkak ki Benim kullarım üzerine senin bir hakimiyetin yoktur. Vekil olarak Rabbın yeter."},{"n":66,"t":"Rabbınız O’dur ki; lutfundan elde edesiniz diye gemileri sizin için denizde yüzdürür. Muhakkak ki O; sizin için Rahim olandır."},{"n":67,"t":"Denizde size bir sıkıntı dokununca; yalvardıklarınızın hepsi kaybolur. Ancak O, kalır. Ama O, sizi kurtarıp karaya çıkarınca, yüz çevirirsiniz. Ve insan, zaten pek nankör olandır."},{"n":68,"t":"Kara tarafında sizi yere batırmasından veya başınıza taş yağdırmasından emin mi oldunuz? Sonra kendiniz için bir vekil de bulamazsınız."},{"n":69,"t":"Yoksa sizi tekrar bir kere daha oraya döndürüp üzerinize ortalığı yıkan bir fırtına göndererek, küfretmiş olmanızdan dolayı sizi suda boğmasından mı emin oldunuz? Sonra, Bize karşı sizi takib edecek birini de bulamazsınız."},{"n":70,"t":"Andolsun ki Biz, ademoğlunu mükerrem kıldık. Karada ve denizde taşıdık. Ve onları temiz nimetlerden rızıklandırdık. Yaratmış olduklarımızdan çoğuna onları üstün kıldık."},{"n":71,"t":"O bütün insanları imamları ile çağırdığımız gün; kime kitabı sağından verilmişse; işte onlar, kitablarını okuyacaklar, kıl kadar zulüm olunmayacaklardır."},{"n":72,"t":"Kim de, burada kör ise ahirette de kördür. Yol bakımından da daha sapıktır."},{"n":73,"t":"Onlar; sana vahyettiğimizden ayırıp başka bir şeyi Bize karşı uydurman için, seni fitneye düşürmeye çalışırlar. O zaman, seni dost edineceklerdi."},{"n":74,"t":"Şayet sana sebat vermemiş olsaydık; andolsun ki, az da olsa onlara meyl edecektin."},{"n":75,"t":"Ve o zaman Biz; sana, hayatın da kat katını, ölümün de kat katını tattırdık. Sonra Bize karşı, sana bir yardımcı da bulamazdın."},{"n":76,"t":"Neredeyse seni memleketten çıkarmak için zorlayacaklardı. O zaman, senin ardından onlar da ancak çok az kalabilirler."},{"n":77,"t":"Senden önce gönderdiğimiz peygamberlerimizin kanunu. Sen, Bizim kanunumuzda değişiklik bulamazsın."},{"n":78,"t":"Güneşin batıya yönelmesinden gecenin kararmasına kadar namaz kıl. Sabah vakti de. Zira sabah vakti görülmesi gerekli bir ibadettir."},{"n":79,"t":"Geceleyin yalnız sana mahsus olmak üzere teheccüd namazı kıl. Umulur ki, Rabbın seni öğülmüş bir makama gönderiverir."},{"n":80,"t":"Ve de ki: Rabbım; beni doğruluk yerine koy. Ve doğruluk yerinden çıkar. Ve katından bana destekleyecek bir kuvvet ver."},{"n":81,"t":"De ki: Hak geldi, batıl yıkıldı. Muhakkak batıl zaten yıkılacaktı."},{"n":82,"t":"Kur’an’dan; müminler için rahmet ve şifa olanı indiririz. Zalimler için ise ancak hüsranı artırır."},{"n":83,"t":"İnsana nimet verdiğimiz vakit; yüz çevirir ve yan çizer. Başına bir kötülük gelince de ümitsiz olur."},{"n":84,"t":"De ki: Herkes, yaratılışına göre hareket eder. Ve Rabbınız kimin yol bakımından daha doğru olduğunu en iyi bilendir."},{"n":85,"t":"Sana ruhdan sorarlar. De ki: Ruh, Rabbımın emrindedir. Ve size bilgiden ancak, çok azı verilmiştir."},{"n":86,"t":"Eğer Biz istemiş olsaydık; sana, vahyetmiş olduğumuzu götürürdük. Sonra onun için Bize karşı duracak bir vekil de bulamazdın."},{"n":87,"t":"Ancak Rabbından bir rahmet iledir. Muhakkak ki O’nun sana olan lutfu, pek büyüktür."},{"n":88,"t":"De ki: İnsanlar ve cinnler bu Kur’an’ın bir benzerini getirmek için toplansalardı; birbirlerine yardımcı da olsalar onun bir benzerini getiremezlerdi."},{"n":89,"t":"Andolsun ki; Biz, bu Kur’an’da insanlar için her türlü örneği çeşitli şekillerde açıkladık. Yine de insanların çoğu pek nankör oldu."},{"n":90,"t":"Dediler ki: Sen, bize yerden bir kaynak fışkırtıncaya kadar sana asla inanmayacağız."},{"n":91,"t":"Veya hurmalıklardan ve üzümden bahçelerin olsun ve aralarında ırmaklar akıtmalısın."},{"n":92,"t":"Yahut iddia ettiğin gibi göğü üzerimize parça parça düşüresin veya Allah ı ve melekleri karşımıza getiresin."},{"n":93,"t":"Yahut da altundan bir evin olsun veya göğe yükselesin. Oradan bize okuyacağımız bir kitab indirilinceye kadar, senin yükselmene de inanmayacağız. De ki: Tenzih ederim Rabbımı. Ben, peygamber olarak gönderilmiş bir beşerden başkası değilim."},{"n":94,"t":"Onlara hidayet geldiği zaman; insanları inanmaktan alıkoyan, sadece: Allah peygamber olarak bir beşeri mi göndermiştir? demeleridir."},{"n":95,"t":"De ki: Eğer yeryüzünde yerleşmiş dolaşan melekler olsaydı; Biz, ancak onlara peygamber olarak gökten bir melek indirirdik."},{"n":96,"t":"De ki: Şahid olarak, benim ve sizin aranızda Allah yeter. Muhakkak ki O; kulları için Habir’dir, Basir’dir."},{"n":97,"t":"Allah kimi hidayete erdirirse; o, hidayete ermiştir. Kimi da dalalete düşürürse; O’ndan başka onlar için dostlar bulamazsın. Biz, onları kıyamet günü körler, dilsizler ve sağırlar olarak yüzüstü haşredeceğiz. Yurtları cehennemdir. O ne zaman sönmeye yüz tutsa; hemen alevini artırırız."},{"n":98,"t":"Bu, onların cezasıdır. Çünkü onlar; ayetlerimize küfrettiler ve: Kemik, ufalanmış toprak olduğumuzdan sonra mı, biz mi, yeniden bir yaratılışla diriltileceğiz? dediler."},{"n":99,"t":"Görmezler mi ki; gökleri ve yeri yaratmış olan Allah; onların benzerlerini de yaratmaya Kadir’dir. Onlar için şüphe olmayan bir ecel kılmıştır Buna rağmen zalimler küfürden başka bir şeyde diretmediler."},{"n":100,"t":"De ki: Eğer siz, Rabbımın rahmet hazinelerine sahip olsaydınız; o zaman tükenir korkusuyla onları saklardınız. Zaten insan pek cimridir."},{"n":101,"t":"Andolsun ki; Biz, Musa’ya dokuz tane apaçık ayet verdik. Sor, İsrailoğullarına, hani onlara gelmişti de Firavun ona şöyle demişti: Ey Musa, doğrusu ben, seni büyülenmiş zannediyorum."},{"n":102,"t":"O da demişti ki: Andolsun ki sen; bunları göklerin ve yerin Rabbının, açık deliller olarak indirmiş olduğunu biliyorsun. Ben, doğrusu ey Firavun, senin mahvolacağını sanıyorum."},{"n":103,"t":"Bunun üzerine onları memleketten sürmek istedi. Biz de onu ve beraberindekileri bütünüyle suda boğduk."},{"n":104,"t":"Onun ardından İsrailoğullarına dedik ki: Haydin, o memlekette siz oturun. Ahiret vaadi geldiği zaman; onları da sizi de bir araya getiririz."},{"n":105,"t":"Biz onu hak ile indirdik. O da hak olarak indi. Seni de ancak müjdeci ve uyarıcı olarak gönderdik."},{"n":106,"t":"Bir de Kur’an’ı insanlara ağır ağır okuman için, bölüm bölüm ve gerektikçe indirdik."},{"n":107,"t":"De ki: Ona ister inanın, ister inanmayın, muhakkak ki ondan önce kendilerine bilgi verilenlere, o okunduğu zaman, yüzleri üstü secdeye kapanırlar."},{"n":108,"t":"Ve derler ki: Tenzih ederiz Rabbımızı. Rabbımızın vaadi şüphesiz yerine gelmiş olacaktır."},{"n":109,"t":"Yüzleri üstü kapanarak ağlarlar. Ve bu, onların huşu’unu artırır."},{"n":110,"t":"De ki: İster Allah deyin, ister Rahman deyin. Hangisini derseniz deyin; en güzel isimler O’nun içindir. Namazında sesini yükseltme de, gizleme de. İkisi arasında bir yol bul."},{"n":111,"t":"Ve de ki: Hamd, O Allah’a mahsustur ki; bir çocuk edinmemiş ve O’nun mülkünde bir ortak bulunmamıştır. Düşkünlükten dolayı O’nun bir yardımcısı olmamıştır. Ve O’nu tekbir et."}],[{"n":1,"t":"Hamd, O Allah’a ki; kuluna dosdoğru kitabı indirdi ve onda hiç bir eğrilik koymadı."},{"n":2,"t":"Kendi katından şiddetli bir baskını haber vermek ve salih amel işleyen mü’minlere güzel bir mükafat olduğunu müjdelemek için."},{"n":3,"t":"Orada temelli kalacaklardır."},{"n":4,"t":"Ve: Allah çocuk edindi, diyenleri uyarman için."},{"n":5,"t":"Ne onların, ne de babalarının buna dair bilgileri vardır. O, ağızlarından çıkan ne büyük bir sözdür. Onlar yalnız ve yalnız yalan söylerler."},{"n":6,"t":"Demek ki bu söze inanmayanların ardından üzülerek neredeyse kendini mahvedeceksin."},{"n":7,"t":"İnsanlardan hangisinin daha güzel amel işlediğini deneyelim diye, yeryüzünde olan şeylere bir süs verdik."},{"n":8,"t":"Şüphesiz ki Biz, yeryüzünde olanları kupkuru bir toprak haline getirebiliriz."},{"n":9,"t":"Yoksa; sen, mağara ve kitabe ehlini şaşılacak ayetlerimizden mi sandın?"},{"n":10,"t":"Hani o yiğitler; mağaraya sığınmışlardı da: Rabbımız; bize katından rahmet ver, işlerimizde başarılı kıl, demişlerdi."},{"n":11,"t":"Bunun üzerine yıllarca mağarada onların kulaklarına perde vurduk."},{"n":12,"t":"Sonra iki taraftan hangisinin bekledikleri sonucu daha iyi hesaplamış olduğunu belirtmek için onları uyandırdık."},{"n":13,"t":"Sana; onların kıssalarını gerçek olarak anlatalım: Doğrusu onlar; Rabblarına inanmış, genç yiğitlerdi. Biz de onların hidayetini artırmıştık."},{"n":14,"t":"Kalkıp da; Bizim Rabbımız göklerin ve yerin Rabbıdır; biz O’ndan başkasına tanrı demeyiz, yoksa andolsun ki; batıl söz söylemiş oluruz, dedikleri zaman kalblerini pekiştirmiştik."},{"n":15,"t":"Şu bizim kavmimiz, Allah’ı bırakıp O’ndan başka tanrılar edindiler. Onların gerçek olduğuna apaçık delil getirmeleri gerekmez mi? Allah’a karşı yalan uyduranlardan daha zalim kimdir?"},{"n":16,"t":"Onlara: Madem siz, onlardan ve Allah’tan başka tapmakta olduklarınızdan ayrıldınız; o halde mağaraya çekilin ki Rabbınız; size, rahmetinden genişlik versin, işinizde kolaylık göstersin, denildi."},{"n":17,"t":"Güneşin doğduğu zaman; mağaralarının sağ tarafına yöneldiğini, battığı zaman da; sol tarafa gittiğini görürsün. Kendileri de mağaranın iç tarafında idiler. Bu, Allah’ın ayetlerindendir. Allah, kimi hidayete erdirirse; o, doğru yola ermiştir, kimi de şaşıracak olursa; artık onun için yol gösterici bir dost bulamazsın."},{"n":18,"t":"Onlar uykuda iken; sen, onları uyanık sanırdın. Biz, onları sağa ve sola döndürüyorduk. Köpekleri de dirseklerini eşiğe uzatmıştı. Onları görsen; için korkuyla dolar, geri dönüp kaçardın."},{"n":19,"t":"Böylece, birbirine sorsunlar diye onları uyandırdık. İçlerinden biri; ne kadar kaldınız? dedi. Bir gün veya daha az bir müddet kaldık, dediler. Ne kadar kaldığınızı Rabbınız daha iyi bilendir. Şimdi siz, birinizi paranızla şehre gönderin de yiyeceklere baksın, hangisi daha temiz ise ondan size getirsin. Orada nazik davransın da sakın sizi kimseye duyurmasın, dediler."},{"n":20,"t":"Çünkü sizden haberleri olacak olursa; sizi, ya taşla öldürürler veya dinlerine döndürürler. Bu takdirde ise asla kurtulamazsınız."},{"n":21,"t":"Böylece, insanların onları bulmalarını sağladık ki Allah’ın sözünün gerçek olduğunu ve kıyametin kopmasından şüphe edilmeyeceğini bilsinler. Nitekim bunlar hakkında çekişip duruyorlar: Onların mağaralarının önüne bir bina kurun, diyorlardı. Halbuki Rabbları onları çok daha iyi bilendir. Onların yerlerine galib gelenler ise: Onların mağaralarının önüne mutlaka bir mescid yapacağız, dediler."},{"n":22,"t":"Karanlığa taş atar gibi; üçtür, dördüncüsü köpekleridir, diyeceklerdir. Veya beştir, altıncıları köpekleridir, derler. Yahut: Yedidir, sekizincileri köpekleridir, derler. Onların sayısını en iyi bilen Rabbımdır, de. Onları pek az kimseden başkası bilmez. Bu yüzden onlar hakkında bu kısa anlatılanların dışında kimseyle tartışma ve onlar hakkında kimseden bir şey sorma."},{"n":23,"t":"Bir şey hakkında; ben bunu yarın mutlaka yapacağım, deme."},{"n":24,"t":"Meğer ki Allah dilemiş ola. Unuttuğun zaman da Rabbını an ve şöyle de: Umulur ki Rabbım; beni doğruya daha yakın olana eriştirir."},{"n":25,"t":"Onlar mağaralarında üçyüz sene eğleştiler. Buna dokuz daha kattılar."},{"n":26,"t":"Onların ne kadar kaldıklarını en iyi Allah bilir, de. Göklerin ve yerin bilinmezlikleri O’na aittir. O ne güzel görendir. O ne güzel işitendir. Bunların O’ndan başka yardımcısı yoktur. O, hiç kimseyi hükmüne ortak yapmaz."},{"n":27,"t":"Rabbının kitabından sana vahyolunanı oku. O’nun sözlerini değiştirebilecek yoktur. O’ndan başka bir sığınak da bulamazsın."},{"n":28,"t":"Sabah akşam Rabblarının rızasını dileyerek O’na yalvaranlarla beraber, sen de sabret. Dünya hayatının güzelliklerini isteyerek gözlerini onlardan ayırma. Bizi anmasını unutturduğumuz, heva ve hevesine uymuş, haddi aşmış kimselere itaat etme."},{"n":29,"t":"De ki: Gerçek, Rabbınızdandır. İsteyen inansın, isteyen inkar etsin. Şüphesiz ki zalimler için, duvarları kendilerini çepeçevre kuşatmış bir ateş hazırlamışızdır. Onlar feryad edip yardım dilediklerinde, erimiş maden gibi yüzleri kavuran bir su kendilerine sunulur. O, ne kötü içecek ve ne kötü duraktır."},{"n":30,"t":"Muhakkak ki iman edip, salih amel işleyenlere gelince; muhakkak ki Biz; iyi hareket edenlerin ecrini zayi etmeyiz."},{"n":31,"t":"İşte onlara; altlarından ırmaklar akan Adn cennetleri vardır. Orada altın bilezikler takınırlar, ince ve kalın ipekliden yeşil elbiseler giyerek tahtları üzerine otururlar. O ne güzel mükafat ve ne güzel duraktır."},{"n":32,"t":"Onlara iki adamı örnek ver ki; birisine iki üzüm bağı verip çevresini hurmalıklarla çevirmiş ve aralarında ekinler bitirmiştik."},{"n":33,"t":"Her iki bahçe de ürünlerini vermişler ve hiç bir şeyi eksik bırakmamışlardı. İkisinin arasından bir de ırmak akıtmıştık."},{"n":34,"t":"Başkaca onun meyvesi de vardı. Bu yüzden arkadaşıyla konuşurken: Ben, malca senden daha zengin, nüfuzca da senden üstünüm, derdi."},{"n":35,"t":"O, nefsine böylece zulmederek bahçesine girerken dedi ki: Bu bahçenin batacağını hiç sanmam."},{"n":36,"t":"Kıyametin kopacağını da tahmin etmiyorum. Eğer Rabbıma döndürülürsem, andolsun ki; bundan daha iyisini bulurum."},{"n":37,"t":"Arkadaşı ona cevap vererek dedi ki: Seni topraktan, sonra bir damla sudan yaratıp sonunda da seni insan kılığına koyanı mı inkar ediyorsun?"},{"n":38,"t":"İşte O; benim Rabbım olan Allah’tır ve ben, kimseyi Rabbıma ortak koşmam."},{"n":39,"t":"Bahçene girdiğin zaman her ne kadar mal ve nüfuz bakımından beni kendinden daha az buluyorsan da; maşaallah, Allah’tan başka kuvvet yoktur, demen lazım değil miydi?"},{"n":40,"t":"Rabbım bana senin bahçenden daha iyisini verebilir ve seninkinin üzerine gökten bir felaket gönderir de kaypak bir toprak haline getirebilir."},{"n":41,"t":"Yahut suyu çekilir de bir daha bulamazsın."},{"n":42,"t":"Nitekim ürünleri yok edildi. Sarfettiği emeğe içi yanarak avuçlarını oğuşturuyordu. Çardakları hep yere düşmüştü. Ve diyordu ki: Ne olaydım, Rabbıma hiç kimseyi ortak koşmasaydım."},{"n":43,"t":"Allah’tan başka ona yardım edecek adamları da yoktu. Yardım edilen de olmadı."},{"n":44,"t":"İşte burada velayet, yalnız hak olan Allah’ındır. Mükafatlandırma bakımından da hayırlı olan, neticelendirme bakımından da hayırlı olan O’dur."},{"n":45,"t":"Dünya hayatının misalini de anlat onlara. Gökten indirdiğimiz su gibidir. Ki bununla yeryüzünde yetişen bitkiler birbirine karışır. Ama sonunda da rüzgarın savuracağı çörçöpe döner. Allah; her şeyin üstünde bir kudret sahibidir."},{"n":46,"t":"Mal ve oğullar dünya hayatının zinetidir. Ama baki kalacak salih ameller, sevab olarak da, amel olarak da Rabbının katında daha hayırlıdır."},{"n":47,"t":"Bir gün dağları yürütürüz de; sen, yeri dümdüz görürsün. Hiç birini bırakmaksızın toplarız onları."},{"n":48,"t":"Saflar halinde Rabbına sunulduklarında onlara: Andolsun ki; sizi ilk kez yarattığımız gibi Bize geldiniz. Sizi toplamak için bir söz vermediğimizi iddia etmiştiniz değil mi?"},{"n":49,"t":"Kitab konulduğunda suçluların onda yazılı olandan korktuklarını görürsün Vah bize, eyvah bize, bu kitab nasıl olmuş da küçük büyük bir şey bırakmaksızın hepsini saymış, derler. Çünkü bütün işlediklerini hazır bulurlar. Ve Rabbın, kimseye asla zulmetmez."},{"n":50,"t":"Hani meleklere; Adem’e secde edin, demiştik de İblis’ten başka hepsi secde etmişti. O ise, cinnlerden olduğu için Rabbının emrinden dışarı çıkmıştı. Şimdi siz, beni bırakıp da size düşman olan, onu ve soyunu mu dost ediniyorsunuz? Zalimler için ne kötü bedeldir bu."},{"n":51,"t":"Oysa Ben onları; ne göklerin ve yerin yaratılmasında, ne de kendilerinin yaratılmasında şahid tuttum. Sapıkları da hiç bir zaman yardımcı edinmiş değilim."},{"n":52,"t":"Bana ortak kabul ettiklerinize seslenin, dediği gün; onları çağırırlar ama hiç birisi cevab vermez. Aralarına bir uçurum koyarız."},{"n":53,"t":"Suçlular ateşi görünce; ona düşeceklerini anlarlar, ama ondan kaçacak yer bulamazlar."},{"n":54,"t":"Andolsun ki; Biz, bu Kur’an’da insanlara türlü türlü misal gösterip açıkladık. İnsanın en çok yaptığı iş ise, tartışmadır."},{"n":55,"t":"İnsanlara hidayet geldiğinde; onları inanmaktan ve Rabblarından mağfiret dilemekten alıkoyan; öncekilerin başına gelenlerin kendilerine de gelmesini veya göz göre göre azaba uğramayı beklemeleridir."},{"n":56,"t":"Biz, peygamberleri; sadece müjdeci ve uyarıcılar olarak göndeririz. Küfredenler ise hakkı batılla ortadan kaldırmak için mücadele ederler. Ayetlerimizi ve kendilerine yapılan uyarıları alaya alırlar."},{"n":57,"t":"Kendisine Rabbının ayetleri anlatılıp da, onlardan yüz çeviren ve önceden yaptıklarını unutan kimseden daha zalim kim vardır? Biz, onların kalblerinin üstüne; onu iyice anlamalarına engel olan örtüler, kulaklarına da ağırlık koyduk. Sen, onları hidayete çağırsan da; onlar asla hidayete gelmezler."},{"n":58,"t":"Bununla beraber Rabbın Gafur’dur, merhamet sahibidir. Eğer onları, yaptıklarından dolayı hemen yakalasaydı; elbette çabucak azaba uğratırdı. Fakat onların bir vadesi vardır ve ondan kaçıp sığınacak yer bulamazlar."},{"n":59,"t":"İşte zulmettiklerinden dolayı helak ettiğimiz kasabalar. Onları yok etmek için, bir süre tayin etmiştik."},{"n":60,"t":"Hani Musa delikanlısına demişti ki: Ben iki denizin birleştiği yere ulaşmaya, yahut yıllarca yürümeye kararlıyım."},{"n":61,"t":"İkisi, iki denizin birleştiği yere gelince; balıklarını unuttular. O, bir delikten kayıp denizi boyladı."},{"n":62,"t":"Oradan uzaklaştıkları vakit Musa delikanlısına; azığımızı çıkar, bu yolculuğumuzdan andolsun ki yorgun düştük, dedi."},{"n":63,"t":"Bak sen, kayalığa vardığımızda balığı unutmuşum. Şeytandan başkası unutturmadı onu bana. Şaşılacak şekilde o, denizi boylayıvermiş, dedi."},{"n":64,"t":"Musa; zaten istediğimiz buydu, dedi. Hemen izlerinin üstünden gerisin geri döndüler."},{"n":65,"t":"Derken kullarımızdan bir kul buldular ki Biz, ona; katımızdan bir rahmet vermiş ve kendisine nezdimizden bir ilim öğretmiştik."},{"n":66,"t":"Musa ona: Sana öğretilen ilimden bana öğretmen için, peşinden geleyim mi? dedi."},{"n":67,"t":"O da dedi ki: Doğrusu sen, benim yaptıklarıma asla dayanamazsın."},{"n":68,"t":"Kavrayamayacağın bir bilgiye nasıl dayanırsın?"},{"n":69,"t":"O da: İnşallah sabrettiğimi göreceksin, sana hiç bir işte karşı gelmeyeceğim, dedi."},{"n":70,"t":"O halde bana uyacaksan; ben sana anlatmadıkça herhangi bir şey hakkında soru sormayacaksın, dedi."},{"n":71,"t":"Bunun üzerine kalkıp gittiler. Nihayet bir gemiye bindiklerinde; o, bu gemiyi deliverdi. Musa: Gemiyi içindekileri boğmak için mi deldin? Doğrusu şaşılacak bir şey yaptın, dedi."},{"n":72,"t":"Ben, sana; yaptığım şeylere dayanamazsın, demedim mi? dedi."},{"n":73,"t":"Unuttuğum şeyden dolayı bana çıkışma, gücümün yetmediği şeyden beni sorumlu tutma, dedi."},{"n":74,"t":"Yine gittiler, nihayet bir erkek çocuğa rastladılar. O, hemen bunu öldürdü. Cana karşılık olmaksızın masum bir kimseye mi kıydın? Doğrusu, çok kötü bir şey yaptın, dedi."},{"n":75,"t":"O: Ben, sana; yaptığım işlere dayanamazsın, demedim mi? dedi."},{"n":76,"t":"Eğer bundan sonra sana bir şey sorarsam; benimle arkadaşlık etme. O zaman benim tarafımdan mazur sayılırsın, dedi."},{"n":77,"t":"Yine gittiler ve nihayet vardıkları kasaba halkından yiyecek istediler. Kasaba halkı bu ikisini misafir etmek istemedi. İkisi şehrin içinde yıkılmaya yüz tutan bir duvar gördüler. O, bunu doğrultuverdi. Musa: Dileseydin; buna karşı bir ücret alabilirdin, dedi."},{"n":78,"t":"O dedi ki: İşte bu; seninle benim ayrılışımızdır. Dayanamadığın işlerin içyüzünü sana anlatacağım."},{"n":79,"t":"Gemi; denizde çalışan yoksullara aitti. Onu kusurlu kılmak istedim. Zira arkalarında, her sağlam gemiye zorla el koyan bir hükümdar vardı."},{"n":80,"t":"Oğlana gelince; onun anası babası inanmış kimselerdi. Çocuğun onları azdırıp küfre sürüklemesinden korkmuştuk."},{"n":81,"t":"Rabblarının o çocuktan daha temiz ve daha çok merhametli birini vermesini istedik."},{"n":82,"t":"Duvar ise; o şehirdeki iki yetim erkek çocuğa aitti. Altında da onlara ait bir define vardı. Babaları iyi bir kimseydi. Rabbın; onların erginlik çağına ulaşmasını ve Rabbından bir rahmet olarak deefinelerini çıkar malarını istedi. Ben, bunları kendiliğimden yapmadım. İşte dayanamadığın şeylerin tevili budur."},{"n":83,"t":"Sana Zülkarneyn’i sorarlar. Onu, size anlatacağım, de."},{"n":84,"t":"Doğrusu Biz; onu, yeryüzünde büyük bir kudret sahibi kılmıştık ve ona her şeyin yolunu öğretmiştik."},{"n":85,"t":"O da bir yol tuttu."},{"n":86,"t":"En sonunda güneşin battığı yere vardığı zaman; onu kara bir suda batıyor buldu. Orada bir kavme rastladı. Zülkarneyn, onlara azab da edebilirsin, iyi muamelede de bulunabilirsin, dedik."},{"n":87,"t":"Dedi ki: Kim zulmederse; ona, azab edeceğiz. Sonra Rabbına döndürülür ve Rabbı; onu, görülmemiş bir azaba uğratır."},{"n":88,"t":"Fakat kim de, iman eder ve salih ameller işlerse; ona, mükafat olarak güzel şeyler vardır. Ona emrimizden kolayını da söyleyeceğiz."},{"n":89,"t":"Sonra o, bir yol tuttu."},{"n":90,"t":"Nihayet güneşin doğduğu yere ulaştığında; onun, güneşe karşı hiç bir siper yapmadığımız bir kavmin üzerine doğduğunu gördü."},{"n":91,"t":"İşte bunun gibi, onun yaptıklarının hepsini baştan başa biliyorduk Biz."},{"n":92,"t":"Sonra da bir yol tuttu."},{"n":93,"t":"En sonunda iki dağın arasına varınca; orada hemen hemen hiç bir söz anlamayan bir kavme rastladı."},{"n":94,"t":"Dediler ki: Ey Zülkarneyn; Ye’cuc ve Me’cuc bu ülkede doğrusu bozgunculuk yapıyorlar. Bizim ve onların arasına bir sed yapman için sana vergi verelim mi?"},{"n":95,"t":"Dedi ki: Rabbımın bana verdikleri sizinkinden daha hayırlıdır. Bana gücünüzle yardım edin de, sizin ve onların arasına sağlam bir duvar yapayım."},{"n":96,"t":"Bana demir kütleleri getirin. Bunlar iki dağın arasını doldurunca; körükleyin, dedi. Nihayet o, bir ateş haline gelince; bana erimiş bakır getirin de üzerine dökeyim, dedi."},{"n":97,"t":"Onlar; artık onu, ne aşabildiler, ne de delip geçebildiler."},{"n":98,"t":"Dedi ki: Bu, Rabbımın bir rahmetidir. Rabbımın vaadi gelince onu yerle bir eder. Rabbımın verdiği söz, gerçektir."},{"n":99,"t":"O gün; Biz, onları bırakırız, dalgalar halinde birbirlerine girerler. Sur’a üflenince hepsini bir araya toplarız."},{"n":100,"t":"O gün; kafirlere cehennemi öyle bir gösteririz ki;"},{"n":101,"t":"Onların gözleri Bizim öğüdümüze karşı kapalıdır ve öfkelerinden onu dinlemeye tahammül edemezler."},{"n":102,"t":"Kafirler, Beni bırakıp da kullarımı dost edinmelerini kafi mi sandılar? Doğrusu Biz, cehennemi kafirlere konak olarak hazırladık."},{"n":103,"t":"De ki: Size amel bakımından en çok kayıpta bulunanları haber vereyim mi?"},{"n":104,"t":"Onlar ki; güzel iş yaptıklarını sandıkları halde dünya hayatındaki çalışmaları boşa gitmiştir."},{"n":105,"t":"İşte onlar, Rabblarının ayetlerini ve O’na kavuşmayı inkar edenlerdir. Bunun için yaptıkları boşa gitmiştir. Kıyamet günü Biz, onlara değer vermeyeceğiz."},{"n":106,"t":"İşte onların cezası; inkar edip peygamberlerimi ve ayetlerimi alaya almalarına karşılık, cehennemdir."},{"n":107,"t":"Muhakkak ki iman edip salih amel işleyenlerin konakları, Firdevs cennetleridir."},{"n":108,"t":"Orada temmelli kalırlar ve hiç ayrılmak istemezler."},{"n":109,"t":"De ki: Rabbımın sözlerini yazmak için denizler mürekkep olsa ve bir o kadarını da katsak; daha Rabbımın sözleri tükenmeden denizler tükenirdi."},{"n":110,"t":"De ki: Ben de ancak sizin gibi bir beşerim. Yalnız bana tanrınızın tek bir tanrı olduğu vahyediliyor. Artık kim, Rabbına kavuşmayı arzu ediyorsa salih bir amel işlesin. Ve Rabbına ibadette hiç kimseyi ortak koşmasın."}],[{"n":1,"t":"Kaf, Ha, Ya, Ayn, Sad."},{"n":2,"t":"Rabbının, kulu Zekeriyya’ya rahmetinin zikri."},{"n":3,"t":"Hani o; Rabbına içinden yalvarmıştı."},{"n":4,"t":"Ve demişti ki: Rabbım; gerçekten kemiklerim yıprandı, baş yaşlılık alevi ile tutuştu. Rabbım; şimdiye kadar sana yalvarmakla bir şeyden mahrum olmadım."},{"n":5,"t":"Doğrusu ben; kendimden sonra yerime geçecek yakınlarımın iyi hareket etmeyeceklerinden korkuyorum. Karım da kısırdır. Bana katından bir oğul bağışla."},{"n":6,"t":"Ki bana ve Yakuboğullarına mirasçı olsun. Rabbım; onu razı olunan kıl."},{"n":7,"t":"Ey Zekeriyya; sana Yahya adında bir oğlan müjdeliyoruz. Daha önce bu adı hiç kimseye vermedik."},{"n":8,"t":"Rabbım; karım kısır ve ben de son derece kocamışken nasıl oğlum olur ki? dedi."},{"n":9,"t":"Öyledir. Rabbım buyurdu ki: Bu, bana çok kolaydır. Daha önce sen yokken seni de yaratmıştım."},{"n":10,"t":"Öyleyse Rabbım bana bir nişan ver, dedi. Senin nişanın; birbiri ardı sıra üç gece insanlarla konuşmamandır, buyurdu."},{"n":11,"t":"Bunun üzerine ma’bedden çıkıp kavmine: Sabah akşam Allah’ı tesbih edin, diye işaret etti."},{"n":12,"t":"Ey Yahya, Kitab’a kuvvetle sarıl. Daha çocuk iken ona hikmet verdik."},{"n":13,"t":"Katımızdan bir kalb yumuşaklığı ile safiyet verdik. O, takva sahibi biri idi."},{"n":14,"t":"Anasına ve babasına karşı iyi davranırdı. Baş kaldıran bir zorba değildi."},{"n":15,"t":"Selam olsun ona, doğduğu günde, öleceği günde ve dirileceği günde."},{"n":16,"t":"Kitab’da Meryem’i de an. Hani o, ailesinden ayrılarak Doğu tarafında bir yere çekilmişti."},{"n":17,"t":"Onlardan gizlenmek için de bir perde germişti. Derken, Biz de ona ruhumuzu göndermiştik de tam bir insan olarak görünmüştü ona."},{"n":18,"t":"Rahman’a sığınırım senden, dedi. Eğer takva sahibi isen."},{"n":19,"t":"O da: Ben, Rabbının sana tertemiz bir oğul vermek için gönderdiği bir elçiden başka bir şey değilim, dedi."},{"n":20,"t":"Meryem: Benim nasıl bir oğlum olabilir ki; bana hiç bir beşer dokunmamıştır. Ve ben, kötü kadın da değilim, dedi."},{"n":21,"t":"Bu böyledir, zira Rabbın; bu, Bana kolaydır, onu insanlar için bir ayet ve katımızdan bir rahmet kılacağız, buyuruyor, dedi. Ve iş, olup bitti."},{"n":22,"t":"Nihayet ona gebe kaldı ve bu sebeple uzak bir yere çekildi."},{"n":23,"t":"Doğum sancısı onu bir hurma dalına sürükledi. Keşki, dedi; bundan evvel öleydim de unutulup gideydim."},{"n":24,"t":"Altından ona şu nida geldi: Üzülme sakın, Rabbın senin ayağının altında bir ırmak akıttı."},{"n":25,"t":"Hurma dalını kendine doğru silkele; üstüne taze hurma dökülsün."},{"n":26,"t":"Ye, iç, gözün aydın olsun. İnsanlardan birini görecek olursan; ben Rahman’ a oruç adadım. Onun için bugün hiç bir kimseyle konuşmayacağım, de."},{"n":27,"t":"Derken çocuğu alıp kavmine getirdi. Ey Meryem; andolsun ki utanılacak bir şey yaptın, dediler."},{"n":28,"t":"Ey Harun’un kızkardeşi; baban kötü birisi değildi, annen de iffetsiz değildi, dediler."},{"n":29,"t":"Bunun üzerine o, çocuğu gösterdi: Biz beşikteki çocukla nasıl konuşabiliriz? dediler."},{"n":30,"t":"Çocuk dedi ki: Şüphesiz ben Allah’ın kuluyum. Bana kitabı verdi ve beni peygamber yaptı."},{"n":31,"t":"Nerede olursam olayım, beni mübarek kıldı ve yaşadığım müddetçe namaz kılmamı ve zekat vermemi emretti."},{"n":32,"t":"Bir de anneme iyi davranmamı. Ve beni bedbaht bir zorba kılmadı."},{"n":33,"t":"Selam olsun bana; doğduğum günde, öleceğim günde ve diri olarak kaldırılacağım günde, dedi."},{"n":34,"t":"İşte hakkında şüpheye düştükleri Meryem oğlu İsa, hak söze göre budur."},{"n":35,"t":"Oğul edinmek Allah’a asla yakışmaz. O münezzehtir. Bir işin olmasını istedi mi, ona sadece; ol, der, o da oluverir."},{"n":36,"t":"Şüphesiz ki Allah; benim de Rabbım, sizin de Rabbınızdır. O’na ibadet edin. İşte dosdoğru yol budur."},{"n":37,"t":"Fırkalar kendi aralarında ihtilafa düştüler. Vay o büyük günü görecek kafirlerin haline."},{"n":38,"t":"Bize geldikleri gün; neler görüp işitecekler. Ne var ki zalimler bugün apaçık bir sapıklık içindedirler."},{"n":39,"t":"Sen, onları hasret günü ile korkut. O gün, onlar gaflet içinde inanmamakta iken, iş bitirilmiş olur."},{"n":40,"t":"Şüphe yok ki bütün yeryüzüne ve üzerinde bulunanlara Biz, varis olacağız Ve onlar, Bize döndürüleceklerdir."},{"n":41,"t":"Kitab’da İbrahim’i de an. Muhakkak ki o, dosdoğru bir peygamberdi."},{"n":42,"t":"Hani babasına demişti ki: Babacığım; işitmeyen, görmeyen ve sana hiç bir faydası olmayan şeylere niçin tapıyorsun?"},{"n":43,"t":"Babacığım, doğrusu sana gelmeyen bir ilim bana gelmiştir. Öyleyse bana uy da, seni dosdoğru bir yola ileteyim."},{"n":44,"t":"Babacığım, şeytana tapma. Çünkü şeytan, Rahman’a başkaldırmıştır."},{"n":45,"t":"Babacığım, sana Rahman’ın katından bir azabın gelmesinden korkuyorum. Böylece şeytanın dostu olarak kalırsın."},{"n":46,"t":"Dedi ki: Sen, benim tanrılarımdan yüz mü çeviriyorsun? Ey İbrahim, eğer bundan vazgeçmezsen; andolsun ki seni taşlarım, uzun bir müddet benden ayrıl, git."},{"n":47,"t":"İbrahim dedi ki: Selam olsun sana, senin için Rabbımdan mağfiret dileyeceğim. Zira O, bana karşı çok lütufkardır."},{"n":48,"t":"Sizi ve Allah’tan başka taptıklarınızı bırakıp çekilirim, Rabbıma yalvarırım. Rabbıma yalvarışımdan ötürü mahrum kalmayacağımı umarım."},{"n":49,"t":"Onları ve Allah’tan başka taptıklarını bırakıp çekilince; ona İshak’ı ve Yakub’u bahşettik. Ve her birini peygamber yaptık."},{"n":50,"t":"Bunlara rahmetimizden lutfettik. Onlar için yüce bir doğruluk dili verdik"},{"n":51,"t":"Kitab’da Musa’yı da an. Muhakkak ki o, ihlasa erdirilmiş ve gönderilmiş bir peygamberdi."},{"n":52,"t":"Ona Tur’un sağ yanından seslendik. Ve onu gizlice söyleşmek için yaklaştırdık."},{"n":53,"t":"Ve rahmetimizden ötürü ona; kardeşi Harun’u da bir peygamber olarak bağışladık."},{"n":54,"t":"Kitab’da İsmail’i de an. Muhakkak ki o, vaadine sadık idi ve katımızdan gönderilmiş bir peygamberdi."},{"n":55,"t":"Kavmine namaz kılmalarını, zekat vermelerini emrederdi. Rabbının katında hoşnudluğu ermişti."},{"n":56,"t":"Kitab’da İdris’i de an. Muhakkak ki o, dosdoğru bir peygamberdi."},{"n":57,"t":"Onu yüce bir yere yükselttik."},{"n":58,"t":"İşte bunlar; Allah’ın kendilerine nimetler verdiği peygamberlerden, Adem in soyundan, Nuh ile beraber taşıdıklarımızdan ve İbrahim ile İsrail’in neslinden, hidayete erdirdiğimiz ve seçtiğimiz kimselerdendir. Rahman’ın ayetleri onlara okunduğu zaman; ağlayarak secdeye kapanırlardı."},{"n":59,"t":"Ama onların ardından namazı bırakan, şehvetlerine uyan bir nesil geldi. Onlar bu azgınlıklarının karşılığını göreceklerdir."},{"n":60,"t":"Ancak tevbe edip iman ederek salih amel işleyenler müstesnadır. Onlar, hiç bir haksızlığa uğratılmadan cennete girerler."},{"n":61,"t":"Rahman’ın kullarına gıyaben vaad ettiği Adn cennetlerine. Şüphesiz O’nun sözü yerini bulacaktır."},{"n":62,"t":"Orada boş sözler değil, sadece selam sözü işitirler ve sabah-akşam rızıklarını hazır bulurlar."},{"n":63,"t":"İşte bu cennetlere; kullarımızdan takva sahiplerini mirasçı kılacağız."},{"n":64,"t":"Biz, ancak Rabbının emri ile ineriz. Önümüzde, arkamızda ve bu ikisi arasındaki her şey, O’nundur. Ve Rabbın unutkan değildir."},{"n":65,"t":"Göklerin, yerin ve ikisi arasında bulunanların Rabbıdır. O halde O’na ibadet et ve bu ibadetinde devamlı ol. Sen, hiç O’nun için bir adaş bilir misin?"},{"n":66,"t":"İnsan der ki: Ben, öldüğümde mi diriltileceğim?"},{"n":67,"t":"İnsan hiç düşünmez mi ki; kendisi önceden bir şey değilken, Biz yarattık onu."},{"n":68,"t":"Rabbına andolsun ki; Biz, onları da, şeytanları da beraber mutlaka haşr edeceğiz. Sonra cehennemin yanında diz çöktürerek hazır bulunduracağız."},{"n":69,"t":"Sonra her toplumdan Rahman’a karşı en çok başkaldıranları ortaya koyacağpız."},{"n":70,"t":"Cehenneme en çok layık olanları elbette Biz, biliriz."},{"n":71,"t":"Sizden oraya gitmeyecek hiç kimse yoktur. Bu, Rabbının yapmayı üzerine aldığı kesin bir hükümdür."},{"n":72,"t":"Sonra Biz, takvaya erenleri kurtaracağız. Zalimleri de orada diz üstü çökmüş olarak bırakacağız."},{"n":73,"t":"Ayetlerimiz kendilerine açıkça okunduğu zaman; küfreden o adamlar mü’minlere: Bu iki takım insanın hangisinin makamı daha iyi ve yeri daha güzeldir? derler."},{"n":74,"t":"Onlardan önce nice nesilleri yok ettik ki, varlıkça ve gösterişçe bunlardan çok daha üstündüler."},{"n":75,"t":"De ki: Rahman; sapıklıkta olanın günlerinin uzunluğunu uzattıkça uzatır. Nihayet tehdit edildikleri azabı veya kıyamet gününü gördükleri zaman; kimin yerinin daha kötü ve taraftarlarının daha güçsüz olduğunu bileceklerdir."},{"n":76,"t":"Allah, hidayete erenlerin hidayetini artırır. Baki kalacak salih ameller Rabbının katında hem sevab olarak daha hayırlı, hem de netice olarak daha hayırlıdır."},{"n":77,"t":"Ayetlerimizi inkar eden; bana elbette mal ve çocuk verilecektir, diyeni gördün mü?"},{"n":78,"t":"O, görülmeyeni mi biliyor yoksa Rahman katından bir söz mü almış?"},{"n":79,"t":"Hayır, onun söylediğini yazacağız ve azabını uzattıkça uzatacağız."},{"n":80,"t":"Onun söylemekte olduğuna Biz, mirasçı olacağız. Kendisi Bize tek olarak gelecektir."},{"n":81,"t":"Onlar; kendilerine güç kazandırsın diye, Allah’ı bırakarak ilahlar edindiler."},{"n":82,"t":"Hayır, onlar kendilerinin ibadetlerini inkar edecekler ve aleyhlerine döneceklerdir."},{"n":83,"t":"Bilmiyor musun ki; kafirlerin üzerine, onları kışkırtan şeytanlar gönderdik."},{"n":84,"t":"Şu halde sen, onlara karşı acele etme. Biz, onların günlerini saydıkça sayıyoruz."},{"n":85,"t":"O gün muttakileri Rahman’ın huzurunda, O’na gelmiş konuklar olarak toplarız."},{"n":86,"t":"Mücrimleri de suya götürür gibi cehenneme süreriz."},{"n":87,"t":"Rahman’ın katında, ahid almış olanlardan başkası asla şefaatta bulunamayacaktır."},{"n":88,"t":"Bir kısım kimseler: Rahman çocuk edindi, dediler."},{"n":89,"t":"Andolsun ki; ortaya çok kötü bir şey attınız."},{"n":90,"t":"Neredeyse gökler parçalanacak, yer yarılacak ve dağlar göçecekti;"},{"n":91,"t":"Rahman’a çocuk isnad etmelerinden ötürü."},{"n":92,"t":"Oysa Rahman’a çocuk edinmek yaraşmaz."},{"n":93,"t":"Çünkü göklerde ve yerlerde olan her şey, Rahman’a kul olarak gelecektir."},{"n":94,"t":"Andolsun ki; ilmi onları kuşatmış ve teker teker saymıştır."},{"n":95,"t":"Hepsi kıyamet günü O’na tek olarak gelecektir."},{"n":96,"t":"Muhakkak ki iman edip salih amel işleyenleri, Rahman sevgili kılacaktır."},{"n":97,"t":"İşte Biz; bunu muttakilere müjdeleyesin ve inatçı bir kavmi uyarasın diye senin dilinde indirerek kolaylaştırdık."},{"n":98,"t":"Onlardan önce nice nesilleri yok ettik. Şimdi onlardan hiç bir varlık emaresi hissediyor veya bir ses işitiyor musun?"}],[{"n":1,"t":"Ta-Ha."},{"n":2,"t":"Biz; Kur’an’ı, sana güçlük çekesin diye indirmedik."},{"n":3,"t":"Ancak Allah’tan korkanlara bir bir öğüt olarak."},{"n":4,"t":"Yeri ve yüce gökleri yaratanın katından indirmedir."},{"n":5,"t":"Rahman, Arş’a hükmetmiştir."},{"n":6,"t":"Göklerde, yerde, ikisinin arasında ve toprağın altında bulunanlar O’nun."},{"n":7,"t":"İstersen sen sözü açığa vur, şüphesiz ki O; gizliyi de, gizlinin gizlisini de bilir."},{"n":8,"t":"Allah’tan başka hiç bir ilah yoktur. En güzel isimler O’nundur."},{"n":9,"t":"Ve sana Musa’nın haberi geldi mi?"},{"n":10,"t":"Hani o; bir ateş görmüştü de ailesine: Durun, ben bir ateş gördüm. Size ya ondan bir kor getiririm veya ateşin yanında bir yol gösteren bulurum, demişti."},{"n":11,"t":"Ateşin yanına gelince; kendisine: Ey Musa, diye seslenildi."},{"n":12,"t":"Şüphesiz ki senin Rabbın Benim, Ben. Pabuçlarını çıkar. Zira sen mukaddes vadide, Tuva’dasın."},{"n":13,"t":"Ve ben; seni seçtim. Öyleyse vahyolunanı dinle."},{"n":14,"t":"Şüphesiz ki Ben; Allah’ım. Benden başka hiç bir ilah yoktur. Öyleyse Bana ibadet et ve Beni anmak için namaz kıl."},{"n":15,"t":"Çünkü kıyamet muhakkak gelecektir. Her nefis işlediğinin karşılığını görsün diye onu neredeyse gizliyorum."},{"n":16,"t":"Ona inanmayan ve hevesine uyan kimse, seni bundan alıkoymasın, yoksa helak olursun."},{"n":17,"t":"O sağ elindeki de nedir ey Musa?"},{"n":18,"t":"Dedi ki: O benim değneğimdir. Ona dayanırım, onunla davarıma yaprak silkerim ve daha bir çok işlerde ondan faydalanırım."},{"n":19,"t":"Buyurdu: Ey Musa bırak onu."},{"n":20,"t":"O da bıraktı. Bir de ne görsün; o, hemen koşan bir yılan oluvermiş."},{"n":21,"t":"Buyurdu: Tut onu korkma. Biz onu yine eski durumuna çevireceğiz."},{"n":22,"t":"Elini de koltuğunun altına koy ki; diğer bir mucize olarak kusursuz, bembeyaz çıksın."},{"n":23,"t":"Bununla sana daha büyük mucizelerimizi gösterelim."},{"n":24,"t":"Firavun’a git, doğrusu o, azmıştır."},{"n":25,"t":"Dedi ki: Rabbım, göğsümü aç."},{"n":26,"t":"İşimi kolaylaştır."},{"n":27,"t":"Dilimden de düğümü çöz ki;"},{"n":28,"t":"Sözümü iyi anlasınlar."},{"n":29,"t":"Kendi ailemden bir vezir ver bana;"},{"n":30,"t":"Kardeşim Harun’u."},{"n":31,"t":"Onunla destekle beni."},{"n":32,"t":"Onu işimizde ortak yap,"},{"n":33,"t":"Ki seni daha çok tesbih edelim."},{"n":34,"t":"Ve seni daha çok analım."},{"n":35,"t":"Şüphesiz ki Sen, bizi görmektesin."},{"n":36,"t":"Buyurdu: Ey Musa; istediğin sana verilmiştir."},{"n":37,"t":"Zaten sana, başka bir defa daha lutufta bulunmuştuk."},{"n":38,"t":"Hani annene vahyedilmesi gerekeni vahyetmiştik."},{"n":39,"t":"Onu bir sandığa koy da suya bırak. Su onu kıyıya atar. Bana da, ona da düşman olan birisi onu alır. Gözümün önünde yetişesin diye, senin üzerine katımdan bir sevgi koydum."},{"n":40,"t":"Hani kızkardeşin gidip diyordu ki: Ona bakacak birini size göstereyim mi? İşte böylece, annen üzülmesin de gözü aydın olsun diye seni ona geri vermiştik. Ve sen, bir cana kıymıştın da; seni üzüntüden kurtarmıştık. Hem seni bir çok musibetlerle denemiştik. Böylece Medyen halkı arasında yıllarca kalmıştın. Sonra da bir kader üzerine geldin ey Musa."},{"n":41,"t":"Ve seni kendim için yetiştirdim."},{"n":42,"t":"Sen ve kardeşin ayetlerimle git. İkiniz de Beni zikretmede gevşek davranmayın."},{"n":43,"t":"Firavun’a gidin, doğrusu o, azmıştır."},{"n":44,"t":"Ve ona yumuşak söz söyleyin, belki nasihat dinler veya korkar."},{"n":45,"t":"Dediler ki: Rabbımız; onun bize taşkınlık yapmasından veya azgın davranmasından endişe ederiz."},{"n":46,"t":"Buyurdu: Korkmayın, Ben sizinle beraberim, hem görür, hem de işitirim."},{"n":47,"t":"Haydi ona gidin ve deyin ki: Doğrusu biz, senin Rabbının elçileriyiz. Artık İsrailoğullarını bizimle gönder ve onlara azab etme. Hem biz, Rabbından sana bir ayetle geldik. Hidayete tabi olanların üzerine selam olsun"},{"n":48,"t":"Doğrusu bize vahyolundu ki; yalanlayıp sırt çevirene azab vardır."},{"n":49,"t":"Ey Musa, Rabbınız kimdir sizin ikinizin? dedi."},{"n":50,"t":"Dedi ki: Rabbımız her şeye yaratılışını veren, sonra da doğru yola eriştirendir."},{"n":51,"t":"Öyle ise önceki nesillerin durumu nedir? dedi."},{"n":52,"t":"Dedi ki: Onların bilgisi Rabbımın katında bir kitabdadır. Benim Rabbım şaşırmaz, unutmaz."},{"n":53,"t":"O ki; sizin için, yeryüzünü döşemiş, orada sizin için yollar açmış, gökten su indirmiştir. Biz o su ile çeşitli bitkilerden çifter çifter çıkardık."},{"n":54,"t":"Hem siz yeyin, hem hayvanlarınızı otlatın. Şüphesiz ki bunlarda sağduyu sahipleri için ayetler vardır."},{"n":55,"t":"Ondan yarattık sizi, oraya da döndüreceğiz. Ve sizi, bir kere daha oradan çıkaracağız."},{"n":56,"t":"Andolsun ki ona bütün ayetlerimizi gösterdik ama yalanlayıp kaçtı."},{"n":57,"t":"Ve dedi ki: Sihirbazlığınla bizi yurdumuzdan çıkarmaya mı geldin ey Musa?"},{"n":58,"t":"Şimdi biz de seninkine benzer bir sihir göstereceğiz sana. Bizimle senin aranda bir buluşma zamanı ve yeri tayin et ki; sen de, biz de düz bir yerde bulunalım, caymayalım."},{"n":59,"t":"Buluşma zamanımız; sizin bayram gününüzde, insanların toplandığı kuşluk vaktidir, dedi."},{"n":60,"t":"Bunun üzerine Firavun dönüp gitti ve sonra bütün hilesini toplayıp geldi"},{"n":61,"t":"Musa onlara dedi ki: Yazıklar olsun size, Allah’a karşı yalan uydurmayın Sonra azabla sizi yok eder. Doğrusu Allah’a iftira eden, hüsrana uğramıştır."},{"n":62,"t":"Derken onlar işi aralarında tartıştılar ve gizlice müşavere ettiler."},{"n":63,"t":"Dediler ki: Muhakkak bu iki sihirbaz sihirleriyle sizi yurdunuzdan çıkar mak ve örnek olan yolunuzu yok etmek istiyorlar."},{"n":64,"t":"Onun için tuzaklarınızı bir araya getirin, sonra da sırayla gelin. Bugün üstün gelen felah bulmuştur."},{"n":65,"t":"Dediler ki: Ey Musa; ya sen at, ya da ilk atanlar biz olalım."},{"n":66,"t":"O da: Hayır siz atın, dedi. Bir de ne görsün; onların ipleri ve değnekleri, büyüleri yüzünden kendisine gerçekten yürüyorlarmış gibi geldi."},{"n":67,"t":"Bu sebeple Musa, içinde bir korku hissetti."},{"n":68,"t":"Korkma; muhakkak sen daha üstünsün, dedik."},{"n":69,"t":"Sağ elindekini at da onların yaptıklarını yutsun. Zira onların yaptıkları, sadece sihirbaz düzenidir. Nerede olursa olsun sihirbaz asla felah bulamaz."},{"n":70,"t":"Sonunda sihirbazlar secdeye kapanarak dediler ki: Biz, Musa ve Harun’un Rabbına inandık."},{"n":71,"t":"Dedi ki: Ben size izin vermeden mi O’na inandınız? Doğrusu o size büyü öğreten büyüğünüzdür. Öyleyse ben de ellerinizi ve ayaklarınızı çaprazlama olarak keseceğim ve sizi hurma kütüklerine asacağım. O zaman hangimizin azabının daha çetin ve devamlı olduğunu bileceksiniz."},{"n":72,"t":"Dediler ki: Seni, bize gelen apaçık mucizelere ve bizi yaratana üstün tutmayacağız. Ne hüküm vereceksen ver. Sen ancak bu dünya hayatına hükmedebilirsin."},{"n":73,"t":"Doğrusu biz, hatalarımızı ve bize zorla yaptırdığın büyüyü bağışlaması için Rabbımıza iman ettik. Allah’ın vereceği mükafat daha hayırlı ve daha devamlıdır."},{"n":74,"t":"Kim Rabbına suçlu olarak gelirse; şüphesiz ki cehennem onun içindir. Orada ne ölür, ne de yaşar."},{"n":75,"t":"Kim de O’na iman etmiş ve salih ameller işlemiş olarak gelirse; işte onlara en üstün dereceler vardır."},{"n":76,"t":"Altlarından ırmaklar akan ve içinde temelli kalacakları Adn cennetleri vardır ve bu, arınanların mükafatıdır."},{"n":77,"t":"Andolsun ki; Musa’ya şöyle vahyettik: Kullarımı geceleyin yürüt. Denizde onlara kuru bir yol aç. Batmaktan ve düşmanların yetişmesinden korkma, endişe etme."},{"n":78,"t":"Firavun da ordusuyla onu takip etti. Deniz de onları nasıl kapladıysa öylece kaplayıverdi."},{"n":79,"t":"Firavun kavmini saptırdı ve onlara doğru yolu göstermedi."},{"n":80,"t":"Ey İsrailoğulları; sizleri düşmanınızdan kurtardık ve size Tur’un sağ yanını vaad eetik. Ve üzerinize kudret helvasıyla bıldırcın indirdik."},{"n":81,"t":"Size rızık olarak verdiklerimizin temizlerinden yeyin, bunda aşırı gitmeyin ki gazabımı hak etmeyesiniz. Gazabımı hak eden, muhakkak mahvolmuştur."},{"n":82,"t":"Muhakkak ki ben; tevbe edeni, inanarak salih amel işleyeni sonra da doğru yola gireni elbette bağışlayanım."},{"n":83,"t":"Ey Musa; seni, kavminden daha çabuk gelmeye sevk eden nedir?"},{"n":84,"t":"Dedi ki: Onlar izim üzerindedirler. Rabbım, hoşnud olman için sana çabucak geldim."},{"n":85,"t":"Buyurdu: Doğrusu biz, senden sonra kavmini sınadık ve Samiri de onları saptırdı."},{"n":86,"t":"Musa kavmine kızgın ve üzgün olarak döndü ve: Ey kavmim; Rabbınız size güzel bir vaadde bulunmadı mı? Uzun bir zaman mı geçti aradan, yoksa Rabbınızın gazabına uğramak istediniz de mi bana verdiğiniz sözden caydınız? dedi."},{"n":87,"t":"Onlar: Sana verdiğimiz sözden kendi başımıza caymadık. O kavmin ziynet eşyasından bize yükler dolusu taşıtıldı ve biz onları attık. Samiri de aynı şekilde attı, dediler."},{"n":88,"t":"Derken o, kendilerine böğüren bir buzağı heykeli çıkarmıştı. Dediler ki: İşte bu, sizin de, Musa’nın da tanrısıdır. Fakat o, unuttu."},{"n":89,"t":"Görmüyorlar mıydı ki; o kendilerine ne bir söz söyleyebilirdi, ne bir zarar, ne de bir fayda verebilirdi."},{"n":90,"t":"Andolsun ki; daha önce Harun da onlara: Ey kavmim; siz, bununla sınanıyorsunuz. Sizin gerçek Rabbınız Rahman’dır. Bana uyun ve emrime itaat edin, demişti."},{"n":91,"t":"Onlar da: Musa bize dönene kadar, buna sarılmaktan asla vazgeçmeyeceğiz, demişlerdi."},{"n":92,"t":"Dedi ki: Ey Harun; bunların saptıklarını görünce ne alıkoydu seni,"},{"n":93,"t":"Benim ardımdan gelmekten? Yoksa benim emrime karşı mı geldin?"},{"n":94,"t":"O da: Ey anamın oğlu; saçımdan sakalımdan tutma. Doğrusu; İsrailoğulları arasına ayrılık soktun, sözüme bakmadın, demenden korktum, dedi."},{"n":95,"t":"Ya senin zorun neydi ey Samiri? dedi."},{"n":96,"t":"O da: Onların görmedikleri bir şey gördüm ve o elçinin bastığı yerden bir avuç avuçladım. Ve bunu ziynet eşyasının eritildiği potaya attım. Nefsim bana bunu hoş gösterdi, dedi."},{"n":97,"t":"Dedi ki: Haydi git, doğrusu hayatta artık; bana dokunmayın, demenden başka yapacağın bir şey yoktur. Bir de senin için hiç kaçamayacağın bir ceza günü var. Sarılıp durduğun üstüne düşüp tapındığın ilahına bak; yemin olsun ki; biz onu yakacağız, sonra da parça parça edip denize atacağız."},{"n":98,"t":"Sizin ilahınız; ancak O’ndan başka hiç bir ilah olmayan Allah’tır. O, ilmiyle her şeyi kuşatmıştır."},{"n":99,"t":"Sana geçmişlerin haberlerinden bir kısmını işte böylece anlatıyoruz. Şüphe yok ki sana, katımızdan bir de zikir verdik."},{"n":100,"t":"Kim, ondan yüz çevirirse; şüphesiz ki kıyamet günü ağır bir günah yüklenecektir."},{"n":101,"t":"Onda temelli kalacaklardır. Bu, kıyamet gününde onlar için ne kötü bir yüktür."},{"n":102,"t":"Sur’a üflendiği gün, işte o gün; suçluları, gözleri korkudan gövermiş olarak toplarız."},{"n":103,"t":"Aralarında gizli gizli konuşarak: Siz, sadece o gün eğleştiniz, derler,"},{"n":104,"t":"Onların söylediklerini Biz daha iyi biliriz. En akıllıları da: Sadece bir gün eğleştiniz, der."},{"n":105,"t":"Ve sana dağlardan sorarlar. De ki: Rabbım, onları ufalayıp savuracak."},{"n":106,"t":"Yerlerini düz, kuru bir toprak haline getirecek."},{"n":107,"t":"Orada ne bir çukur, ne de bir tümsek göreceksin."},{"n":108,"t":"O gün; hiç bir tarafa sapmadan o davetçiye uyacaklardır. Sesler, Rahman’ ın heybetinden kısılmıştır ve sen; fısıltıdan başka bir şey işitmezsin."},{"n":109,"t":"O gün; Rahman’ın izin verdiği ve sözünden hoşnud olduğu kimseden başkasının şefaati fayda vermez."},{"n":110,"t":"O, onların önlerindekini de, arkalarındakini de bilir. Onların hiç birinin ilmi asla bunu kavrayamaz."},{"n":111,"t":"Ve bütün yüzler Hayy ve Kayyum olan Allah’a baş eğmiştir. Bir zulüm yükü taşıyanlar ise gerçekten hüsrana uğramıştır."},{"n":112,"t":"Kim de inanmış olarak salih ameller işlerse; o, zulümden ve hakkının yenmesinden korkmaz."},{"n":113,"t":"Biz onu böylece Arapça bir Kur’an olarak indirdik. Belki sakınırlar veya onlara ibret verir diye tehditleri açıkladık."},{"n":114,"t":"Gerçek hükümdar olan Allah; yücedir. Kur’an sana vahyedilirken; vahiy bitmezden önce unutmamak için acele tekrar edip durma ve: Rabbım, ilmimi artır, de."},{"n":115,"t":"Andolsun ki; Biz, daha önce Adem’e de ahid vermiştik. Fakat o unuttu ve Biz onda bir azim bulmadık."},{"n":116,"t":"Hani meleklere demiştik ki: Adem’e secde edin. İblis’ten başka hepsi secde etmiş, o ise dayatmıştı."},{"n":117,"t":"Biz de demiştik ki: Ey Adem, doğrusu bu, hem senin hem de eşinin düşmanıdır. Sakın sizi cennetten çıkarmasın. Yoksa bedbaht olursun."},{"n":118,"t":"Zira cennette ne acıkırsın, ne de çıplak kalırsın."},{"n":119,"t":"Orada ne susarsın, ne de güneşte yanarsın."},{"n":120,"t":"Ama şeytan ona vesvese verdi ve: Ey Adem, sana ebedilik ağacını ve yok olmayacak bir mülkü göstereyim mi? dedi."},{"n":121,"t":"Bunun üzerine ikisi de ondan yediler. Hemen ayıp yerleri açıldı. Üzerlerine cennet yapraklarından yamamaya başladılar. Adem, Rabbına karşı geldi de şaşkın düştü."},{"n":122,"t":"Sonra Rabbı onu seçti de tevbesini kabul etti ve ona doğru yolu gösterdi"},{"n":123,"t":"Buyurdu ki: Birbirinize düşman olarak hepiniz oradan inin. Benden size bir yol gösteren gelir de kim, benim yoluma uyarsa; ne sapar, ne de bedbaht olur."},{"n":124,"t":"Kim de benim zikrimden yüz çevirirse bilsin ki; onun dar bir geçimi olur ve kıyamet gününde Biz onu kör olarak haşrederiz."},{"n":125,"t":"Der ki: Rabbım, beni niçin kör olarak haşrettin? Halbuki ben gören biriydim"},{"n":126,"t":"Allah buyurur ki: Öyledir işte. Sana ayetlerimiz gelmişti de sen onları unutmuştun. Bugün de sen öylece unutulursun."},{"n":127,"t":"İşte israf edenleri, Rabbının ayetlerine inanmayanları böylece cezalandıracağız. Hem ahiretin azabı daha çetin ve daha süreklidir."},{"n":128,"t":"Kendilerinden önce nice nesilleri yok edişimiz hala onları uyarmadı mı? Halbuki onların yurdlarında gezinip duruyorlar. Doğrusu bunda sağduyu sahipleri için ayetler vardır."},{"n":129,"t":"Şayet Rabbının verilmiş bir sözü ve tayin ettiği bir vakit olmasaydı; hemen azaba uğrarlardı."},{"n":130,"t":"Onların söylediklerine sabret ve güneşin doğmasından önce de, batmasından önce de Rabbını hamd ile tesbih et. Gece saatlarında ve gündüzleri de tesbih et ki, Rabbının rızasına eresin."},{"n":131,"t":"Onlardan bazılarına; denemek için verdiğimiz dünya hayatının süsüne gözlerini dikme. Rabbının rızkı daha hayırlı ve daha devamlıdır."},{"n":132,"t":"Ehline namazı emret. Kendin de onda devamlı ol. Biz senden rızık istemiyoruz. Sana Biz rızık veririz. Akibet takvadadır."},{"n":133,"t":"Rabbından bize bir ayet getirseydi ya derler. Onlara önceki kitablarda apaçık deliller gelmedi mi?"},{"n":134,"t":"Eğer onları daha evvel azaba uğratarak yok etseydik: Rabbımız, bize bir peygamber gönderseydin de hor ve rüsvay olmadan önce ayetlerine uysaydık olmaz mıydı? diyeceklerdi."},{"n":135,"t":"De ki: Herkes gözlemektedir, siz de gözleye durun. Şüphesiz kimlerin dosdoğru yolun sahipleri olduğunu ve kimlerin hidayete ermiş bulunduğunu yakında bileceksiniz."}],[{"n":1,"t":"İnsanların hesab zamanı yaklaştı. Fakat onlar hala gaflet içinde yüz çeviriyorlar."},{"n":2,"t":"Rabblarından kendilerine yeni bir uyarı gelmeye dursun; onlar, bunu mutlaka eğlenerek dinlemişlerdir."},{"n":3,"t":"Kalbleri gaflet içerisinde. Zulmedenler gizlice fısıldaştılar: Bu sizin gibi bir insandan başka bir şey midir? Siz, göre göre büyüye mi aldanacaksınız?"},{"n":4,"t":"Dedi ki: Benim Rabbım; gökte ve yerde söyleneni bilir. O; Semi’dir. Alim’dir"},{"n":5,"t":"Onlar: Hayır, bunlar saçma sapan rüyalardır. Hayır onu uydurmuştur, hayır o, şairdir. Haydi önceki peygamberler gibi o da bize bir mucize getirsin dediler."},{"n":6,"t":"Onlardan önce helak etmiş olduğumuz kasaba halkı iman etmemişti. Şimdi bunlar mı iman edecekler?"},{"n":7,"t":"Senden önce de, kendilerine vahyettiğimiz erkeklerden başkasını göndermedik. Eğer bilmiyorsanız; zikir ehline sorun."},{"n":8,"t":"Biz onları; yemek yemez bir ceset kılmadık ve onlar, ebedi de değillerdi"},{"n":9,"t":"Nihayet onlara verdiğimiz sözün doğruluğunu gösterdik. Kendilerini ve dilediklerimizi kurtardık, aşırı gidenleri de yok ettik."},{"n":10,"t":"Andolsun ki; size, içinde zikrinizin bulunduğu bir Kitab indirdik. Hala akletmiyor musunuz?"},{"n":11,"t":"Biz, zulmeden nice kasabayı kırıp geçirdik. Ve onlardan sonra başka bir kavmi var ettik."},{"n":12,"t":"Bizim baskınımızı hissettikleri zaman; onlar, oradan kaçmaya yelteniyordu"},{"n":13,"t":"Koşup kaçmayın, size nimet verilen yere, yurtlarınıza dönün. Elbette sorguya çekileceksiniz."},{"n":14,"t":"Dediler ki: Vay başımıza gelenlere; doğrusu biz, zalimler idik."},{"n":15,"t":"Bu haykırmaları devam edip dururken Biz; onları, biçilmiş bir ot, sönmüş bir ocak haline getirdik."},{"n":16,"t":"Biz; göğü, yeri ve ikisinin arasındakileri oyun olsun diye yaratmadık."},{"n":17,"t":"Eğer bir eğlence edinmek isteseydik, elbette onu kendi katımızdan edinirdik. Fakat asla edinmedik."},{"n":18,"t":"Hayır Biz; gerçeği batılın tepesine indiririz de onun beynini parçalar. Bir de bakarsın ki; o, yok olup gitmiştir. Allah’a yakıştırdıklarınızdan dolayı yazıklar olsun size."},{"n":19,"t":"Göklerde ve yerde ne varsa O’nundur. Katında olanlar O’na kulluk etmekten büyüklenmezler ve usanmazlar."},{"n":20,"t":"Gece gündüz hiç durmaksızın O’nu tesbih ederler."},{"n":21,"t":"Yoksa onlar; yerden bir takım tanrılar edindiler de onlar mı ölüleri diriltecekler?"},{"n":22,"t":"Eğer göklerde ve yerde Allah’tan başka tanrılar olsaydı; bunların ikisi de muhakkak bozulup gitmişti. Arş’ın Rabbı olan Allah; onların nitelendirdiklerinden münezzehtir."},{"n":23,"t":"O; yaptığından sorumlu değildir, fakat onlar sorumludurlar."},{"n":24,"t":"Yoksa O’ndan başka tanrılar mı edindiler? De ki: Kesin delilinizi getirin işte benimle birlikte olanların zikri ve benden öncekilerin zikri. Hayır onların çoğu hakkı bilmezler de onun için yüz çevirirler."},{"n":25,"t":"Senden önce gönderdiğimiz her peygambere mutlaka: Ben’den başka tanrı yoktur. Bana kulluk edin, diye vahyetmişizdir."},{"n":26,"t":"Dediler ki: Rahman çocuk edindi. O’nun şanı yücedir. Hayır, onlar ikram edilmiş kullardır."},{"n":27,"t":"Onlar, sözle asla O’nun önüne geçemezler. Ancak O’nun emriyle hareket ederler."},{"n":28,"t":"O, onların önlerindekilerini de bilir, arkalarındakini de bilir. Onlar, Allah’ın hoşnud olduğu kimseden başkasına şefaat edemezler ve O’nun korkusundan titrerler."},{"n":29,"t":"Bunlardan kim: Tanrı O değil de benim derse; onu derhal cehennemle cezalandırırız. Biz, zalimlerin cezasını böyle veririz."},{"n":30,"t":"O küfredenler görmezler mi ki; gökler ve yer bitişikken Biz ayırdık onları. Ve her şeyi sudan canlı kıldık. Hala inanmıyorlar mı?"},{"n":31,"t":"Onlar sarsılmasın diye yeryüzünde sabit dağlar yerleştirdik. Doğru yoldan gitsinler diye orada geniş yollar açtık."},{"n":32,"t":"Gökyüzünü de korunmuş bir tavan kıldık. Fakat onlar, bundaki ayetlerden yüz çeviriyorlar."},{"n":33,"t":"Geceyi ve gündüzü, güneşi ve ayı yaratan O’dur. Her biri bir yörüngede yüzer."},{"n":34,"t":"Senden önce hiç bir insanı ebedi kılmadık. Sen ölürsen; onlar baki mi kalırlar?"},{"n":35,"t":"Her nefis ölümü tadıcıdır. Bir imtihan olarak sizi iyilik ve kötülükle deneriz. Sonunda, Bize döndürüleceksiniz."},{"n":36,"t":"Küfredenler seni gördükleri zaman, alaya almaktan başka bir şey yapmazlar. Ve: Tanrılarınızı diline dolayan bu mudur? derler. İşte Rahman’ın kitabını inkar edenler onlardır."},{"n":37,"t":"İnsan aceleden yaratılmıştır. Size ayetlerimi göstereceğim. Ama o kadar çabuk istemeyin."},{"n":38,"t":"Doğru sözlüler iseniz bu vaad ne zaman? derler."},{"n":39,"t":"O küfredenler; yüzlerinden ve sırtlarından ateşi engellemeyecekleri ve yardım göremeyecekleri zamanı keşki bilseler."},{"n":40,"t":"Doğrusu o aniden gelecek ve onları şaşırtacaktır. Artık onu geri çevirmeye güçleri yetmeyecektir. Ve onlara mühlet de verilmeyecektir."},{"n":41,"t":"Andolsun ki; senden önce de bir çok peygamberle alay edilmişti. Ama alaya alanları, eğlendikleri şey mahvetmişti."},{"n":42,"t":"De ki: Geceleyin ve gündüzün sizi Rahman’dan kim koruyabilir? Ne var ki onlar, Rabblarının zikrinden yüz çevirmektedirler."},{"n":43,"t":"Yoksa kendilerini Bize karşı savunacak tanrıları mı var? Oysa bunlar kendilerine bile yardım edemezler. Bizden yakınlık da görmezler."},{"n":44,"t":"Evet Biz; onlara da, atalarına da geçimlikleri verdik. Öyle ki ömürleri kendilerine uzun geldi. Fakat şimdi görmüyorlar mı ki; Biz; o yeryüzüne gelip çevresinden eksiltip durmaktayız. Onlar mıdır galip gelenler şu halde?"},{"n":45,"t":"De ki: Ben ancak sizi vahiy ile uyarıyorum. Sağırlar uyarıldıkları zaman çağrıyı işitmezler."},{"n":46,"t":"Andolsun ki Rabbının azabından onlara bir esinti dokunsa; eyvahlar bize, doğrusu biz gerçekten zalimlermişiz, diyeceklerdir."},{"n":47,"t":"Biz; kıyamet günü adalet terazilerini kurarız. Hiç kimse hiç bir şeyle haksızlığa uğratılmaz. Hardal tanesi kadar bile olsa yapılanı ortaya koyarız. Hesab görenler olarak da Biz, yeteriz."},{"n":48,"t":"Andolsun ki; Biz Musa ile Harun’a Furkan ışık, takva sahibleri için de bir zikir verdik."},{"n":49,"t":"Onlar ki görmedikleri halde, Rabblarından korkarlar ve kıyamet saatından titrerler."},{"n":50,"t":"İşte bu da Bizim indirdiğimiz mübarek bir zikirdir. Yoksa siz onu inkar mı ediyorsunuz?"},{"n":51,"t":"Andolsun ki; Biz, daha önce İbrahim’e de rüşdünü vermiştik. Ve Biz onu bilenlerdik."},{"n":52,"t":"Hani o, babasına ve kavmine demişti ki: Şu tapınıp durduğunuz heykeller de nedir?"},{"n":53,"t":"Onlar da: Babalarımızı bunlara tapar bulduk, demişlerdi."},{"n":54,"t":"O: Andolsun ki sizler de, babalarınız da apaçık bir sapıklık içerisindesiniz, demişti."},{"n":55,"t":"Onlar: Sen, bize gerçeği mi getirdin, yoksa bizimle eğleniyor musun? dediler"},{"n":56,"t":"O da dedi ki: Hayır, Rabbınız göklerin ve yerin Rabbıdır ki onları, O yaratmıştır. Ve ben bunlara şahidlik edenlerdenim."},{"n":57,"t":"Allah’a yemin ederim ki; siz, arkanızı dönüp gittikten sonra putlarınıza bir tuzak kuracağım."},{"n":58,"t":"Derken hepsini paramparça edip içlerinden büyüğünü, ona başvursunlar diye sağlam bıraktı."},{"n":59,"t":"Bunu tanrılarımıza kim yaptı? Doğrusu o zalimlerden biridir, dediler."},{"n":60,"t":"Dediler ki: Kendisine İbrahim denilen bir gencin bunları diline doladığını duymuştuk."},{"n":61,"t":"Dediler ki: O halde bunların şahidlik edebilmeleri için onu insanların gözleri önüne getirin."},{"n":62,"t":"Ey İbrahim; tanrılarımıza bu işi sen mi yaptın? dediler."},{"n":63,"t":"Dedi ki: Belki onu şu büyükleri yapmıştır. Konuşabiliyorsa onlara sorun."},{"n":64,"t":"Bunun üzerine kendilerine dönüp dediler ki: Hiç şüphesiz zalimler sizsiniz siz."},{"n":65,"t":"Sonra eski kafalarına döndürüldüler: Bunların konuşamayacağını, andolsun ki; sen de bilirsin, dediler."},{"n":66,"t":"Dedi ki: O halde Allah’ı bırakıp da size hiç bir fayda veya zarar veremeyecek şeylere ne diye taparsınız?"},{"n":67,"t":"Yuh olsun size ve Allah’tan başka taptıklarınıza. Daha akıllanmayacak mısınız?"},{"n":68,"t":"Onlar: Bir şey yapacaksanız şunu yakın da tanrılarınıza yardım edin, dedi"},{"n":69,"t":"Biz de: Ey ateş; İbrahim’e serin ve selamet ol, dedik."},{"n":70,"t":"Ona düzen kurmak istediler. Ama Biz, onları daha çok hüsrana uğrayanlar kıldık."},{"n":71,"t":"Onu da, Lut’u da alemler için mübarek kıldığımız yere ulaştırıp kurtardık"},{"n":72,"t":"Ona İshak’ı, üstelik bir de Yakub’u ihsan ettik. Ve her birini salih kimseler kıldık."},{"n":73,"t":"Onları emrimizle insanlara doğru yolu gösteren imamlar kıldık. Ve onlara hayırlar yapmayı, namaz kılmayı, zekat vermeyi vahyettik. Ve onlar, Bize kulluk eden kimselerdi."},{"n":74,"t":"Lut’a da. Ona hüküm ve ilim verdik, onu çirkin işler yapan o memleketten kurtardık. Doğrusu onlar, yoldan çıkmış kötü bir kavim idiler."},{"n":75,"t":"Ve onu rahmetimize kattık. Doğrusu o, salih kimselerdendi."},{"n":76,"t":"Nuh’u da. Hani daha önceleri Bize niyaz etmişti. Onun duasını kabul edip kendisini ve ailesini büyük sıkıntıdan kurtardık."},{"n":77,"t":"Ayetlerimizi yalanlayan kavme karşı ona yardım ettik. Doğrusu onlar; kötü bir kavim idiler. Biz de hepsini birden suda boğduk."},{"n":78,"t":"Davud ve Süleyman’a da. Hani kavmin koyunlarının yayıldığı bir ekin hakkında hüküm veriyorlarken; Biz, onların hükmüne şahidlerdik."},{"n":79,"t":"Biz bu hükmü hemen Süleyman’a belletmiştik. Her birine hüküm ve ilim verdik. Davud ile birlikte tesbih etsinler diye dağları ve kuşları buyruk altına aldık. Bunları yapanlar Bizdik."},{"n":80,"t":"Biz, ona; sizi savaşta korumak için zırh yapma sanatını öğrettik. Artık şükreder misiniz?"},{"n":81,"t":"Süleyman’a da şiddetli esen rüzgarı müsahhar kıldık. Rüzgar, onun emri ile mübarek kıldığımız yere doğru eserdi. Ve Biz, her şeyi bilenleriz."},{"n":82,"t":"Denize dalacak ve bundan başka işler görecek şeytanları da onun emrine verdik. Onları gözetenler de Bizdik."},{"n":83,"t":"Eyyub’a da. Hani Rabbına niyaz etmiş: Bu dert beni sarıverdi. Sen, merhametlilerin merhametlisisin, demişti."},{"n":84,"t":"Biz de onun duasını kabul etmiş ve uğradığı sıkıntıyı kaldırmıştık. Katımızdan bir rahmet ve kulluk edenlere bir hatıra olmak üzere, ona hem ailesini, hem de bir katını vermiştik."},{"n":85,"t":"İsmail’e, İdris’e ve Zülkifl’e de. Onların her biri sabredenlerdendi."},{"n":86,"t":"Ve onları rahmetimize kattık. Doğrusu onlar; salih kimselerdendi."},{"n":87,"t":"Zünnun’a da. Hani o, öfkelenerek giderken kendisine güç yetiremeyeceğimizi sanmıştı. Ama sonunda karanlıklar içinde: Sen’den başka hiç bir ilah yoktur. Tenzih ederim seni, doğrusu ben, haksızlık edenlerden oldum, diye niyaz etmişti."},{"n":88,"t":"Biz de onun duasını kabul edip üzüntüden kurtarmıştık. İşte inananları böyle kurtarırız."},{"n":89,"t":"Zekeriyya’ya da. Hani o, Rabbına niyaz etmiş ve Rabbım; beni tek başıma bırakma. Sen, varislerin en hayırlısısın, demişti."},{"n":90,"t":"Biz de ona icabet ederek Yahya’yı ihsan etmiş, eşini doğum yapabilecek bir hale getirmiştik. Doğrusu onlar; hayırlı şeylerde yarışıyorlar, korkarak ve umarak bize yalvarıyorlardı. Bize karşı derin saygı duyuyorlardı"},{"n":91,"t":"Mahrem yerini koruyana da ruhumuzdan üflemiş; onu da, oğlunu da alemler için bir ayet kılmıştık."},{"n":92,"t":"Gerçekten şu sizin ümmetiniz, bir tek ümmettir. Ve Ben de Rabbınızım, artık yalnız Bana ibadet edin."},{"n":93,"t":"Onlar aralarında kendi işlerinde bölük bölük oldular. Ama hepsi Bize döneceklerdir."},{"n":94,"t":"Artık inanmış olarak salih amel işleyenlerin ameli inkar edilmez. Ve Biz onu yazanlarız."},{"n":95,"t":"Helak ettiğimiz kasaba halkına da haramdır. Onlar geri dönmezler."},{"n":96,"t":"Ye’cuc ve Me’cuc açılıp da her tepeden ve dereden akın ettikleri vakit."},{"n":97,"t":"Ve gerçek vaad yaklaştığı zaman; o küfredenlerin gözleri belerip kalır: Vah bize, bundan önce gaflet içindeydik, biz gerçekten zalimler idik."},{"n":98,"t":"Siz ve Allah’tan başka taptıklarınız, şüphesiz ki cehennem odunusunuz. Oraya gireceksiniz."},{"n":99,"t":"Şayet bunlar tanrı olsaydı; oraya girmezlerdi. Ve hepsi orada temelli kalacaklardır."},{"n":100,"t":"Orada inim inim inleyecekler ve bir şey de işitmeyeceklerdir."},{"n":101,"t":"Şüphesiz ki daha önce, kendilerine Bizden güzellik vaadi geçmiş olanlar; bunlar, oradan uzaklaştırılmışlardır."},{"n":102,"t":"Onun uğultusunu duymazlar. Canlarının istediği şeyler içinde temelli kalırlar."},{"n":103,"t":"O en büyük korku bile onları tasalandırmaz. Melekler onları: Size söz verilen gün, işte bu gündür, diye karşılarlar."},{"n":104,"t":"Göğü kitab dürer gibi düreceğimiz gün; yaratmaya ilk başladığımız gibi katımızdan verilmiş bir vaad olarak onu yeniden var edeceğiz. Doğrusu Biz, yapanlar olduk."},{"n":105,"t":"Andolsun ki; Zikir’den sonra Zebur’da da yazdık ki: Yeryüzüne ancak salih kullarım varis olur."},{"n":106,"t":"Doğrusu bunda ibadet edenler için, tebliğ vardır."},{"n":107,"t":"Biz, seni ancak alemlere rahmet olarak gönderdik."},{"n":108,"t":"De ki: Gerçekten bana, sizin tanrınızın yalnızca bir tek tanrı olduğu vahyolunuyor. Artık Müslüman olacak mısınız?"},{"n":109,"t":"Şayet yüz çevirirlerse; de ki: Ben, size eşitlik üzere bildirdim. Artık tehdid edildiğiniz şeyin yakın mı, uzak mı olduğunu bilmem."},{"n":110,"t":"Doğrusu O, sözün açığa vurulanını da bilir, gizlediklerinizi de bilir."},{"n":111,"t":"Bilmem. Belki bu, sizin için bir deneme ve bir süreye kadar yararlanmadır."},{"n":112,"t":"Dedi ki: Rabbım; hak ile hükmet. Rahman olan Rabbımız; sizin nitelendirmelerinize karşı yardımına sığınılacak odur."}],[{"n":1,"t":"Ey insanlar; Rabbınızdan sakının. Doğrusu kıyamet saatının sarsıntısı büyük bir şeydir."},{"n":2,"t":"Onu göreceğiniz gün; her emzikli emzirdiğini unutur, her yüklü yükünü düşürür. İnsanları sarhoş gibi görürsün. Oysa sarhoş değildirler, ama Allah’ın azabı pek çetindir."},{"n":3,"t":"İnsanlardan kimi; Allah hakkında bilmeden tartışır ve azgın şeytanın ardına düşer."},{"n":4,"t":"Onun aleyhinde şu hüküm yazılmıştır: O, kendisini dost edinen kimseyi saptırır ve alevli ateşin azabına götürür."},{"n":5,"t":"Ey insanlar; eğer dirilişten yana bir şüphede iseniz; gerçek şu ki: Size açıkça gösterelim diye Biz sizi; topraktan, sonra nutfeden, sonra pıhtılaşmış bir kandan, sonra da yaratılışı belli belirsiz bir çiğnem etten yarat tık. İstediğimizi belli bir süreye kadar rahimlerde tutarız. Sonra sizi bir çocuk olarak çıkarırız. Böylece yetişip erginlik çağına gelirsiniz. Kiminiz öldürülür, kiminiz de bilirken hiç bir şey bilmez olsun diye ömrünün en fena zamanına geri itilir. Yeryüzünü kupkuru olarak görürsün. Ama Biz, ona su indirdiğimiz zaman harekete geçer, kabarır ve her çeşit güzel bitkiden çift çift yetiştirir."},{"n":6,"t":"İşte böyle. Muhakkak ki Allah hakkın kendisidir. Doğrusu ölüleri O, diriltir. Ve O; her şeye Kadir’dir."},{"n":7,"t":"Kıyamet saatı mutlaka gelecektir, onda hiç şüphe yoktur. Ve Allah; kabirlerde olanları diriltecektir."},{"n":8,"t":"İnsanlardan öyleleri vardır ki; bilmeden, doğruya götüren bir rehberi olmadan, aydınlatıcı bir kitabı bulunmadan Allah hakkında tartışmaya girer."},{"n":9,"t":"Allah yolundan saptırmak için, kibirlenerek, yanını eğip büker. Dünyada rüsvaylık onadır. Ve kıyamet günü ona yakıcı azabı tattırırız."},{"n":10,"t":"Ona: Bunlar senin yaptıklarından ötürüdür, denir. Yoksa Allah kullarına asla zulmedici değildir."},{"n":11,"t":"İnsanlardan öyleleri de vardır ki; Allah’a bir yar kenarındaymış gibi kulluk eder. Ona bir iyilik gelirse yatışır. Başına bir bela gelirse; yüz üstü döner. Dünyayı da ahireti de kaybetmiştir. İşte apaçık kayıp budur."},{"n":12,"t":"O, Allah’ı bırakıp da kendisine fayda ve zarar veremeyecek şeylere tapınır. İşte en derin sapıklık budur."},{"n":13,"t":"Kendisine zararı faydasından daha yakın olana tapınır. Tapındığı şey ne kötü yardımcıdır, ne kötü yoldaştır."},{"n":14,"t":"Muhakkak ki Allah; iman edenleri ve salih ameller işleyenleri altından ırmaklar akan cennetlere koyar. Doğrusu Allah; istediğini yapar."},{"n":15,"t":"Kim, dünyada ve ahirette Allah’ın ona yardım etmeyeceğini sanıyorsa; bir sebeple göğe tırmansın sonra kessin de bir düşünsün bakalım; bu hilesi kendisini öfkelendiren şeye engel olabilir mi?"},{"n":16,"t":"İşte böylece ona apaçık ayetler olarak indirdik. Muhakkak ki Allah; dilediğini hidayete eriştirendir."},{"n":17,"t":"Muhakkak ki Allah; iman edenler, yahudiler, sabiiler, hıristiyanlar, mecusiler ve puta tapanlar arasında kıyamet günü kesin hükmünü verecektir. Doğrusu Allah; her şeye şahiddir."},{"n":18,"t":"Göklerde ve yerde olanların; güneş, ay, yıldızlar, dağlar, ağaçlar, hayvanlar ile insanların bir çoğunun Allah’a secde ettiklerini görmüyor musun? İnsanların bir çoğu da azabı hak etmiştir. Ve Allah kimi alçaltırsa; ona ikram edecek kimse yoktur. Şüphesiz ki Allah; dilediğini yapar."},{"n":19,"t":"Bunlar iki düşmandır ki, Rabbları hakkında çekişmişlerdir. Küfredenler için, ateşten elbiseler kesilmiştir. Başları üstünden de kaynar su dökülecektir."},{"n":20,"t":"Bununla karınlarındakiler ve derileri eritilir."},{"n":21,"t":"Demir kamçılar da onlar içindir."},{"n":22,"t":"Ne zaman oradan ve oradaki ıztırabdan çıkıp kurtulmak isteseler; her defasında oraya geri çevrilirler. Yakıcı azabı tadın, denir."},{"n":23,"t":"Muhakkak ki Allah; iman edip salih ameller işleyenleri altından ırmaklar akan cennetlere koyar. Orada altun bilezikler ve inciler takınırlar. Ve oradaki elbiseleri ipektendir."},{"n":24,"t":"Onlar sözün en güzeline alıştırılmışlar ve övülmeye layık olan Allah’ın doğru yoluna iletilmişlerdir."},{"n":25,"t":"Muhakkak ki o küfredenlere, Allah’ın yolundan ve (yerli, yolcu bütün insanları eşit kıldığımız) Mescid-i Haram’dan alıkoyanlara ve orada zulm ile ilhada yeltenenlere; elim bir azabtan tattırırız."},{"n":26,"t":"Hani İbrahim’e: Bana hiç bir şeyi ortak koşma, tavaf edenler, kıyama duranlar, rüku edenler ve secdeye varanlar için evimi temiz tut, diye Kabe’ nin yerini hazırlamıştık."},{"n":27,"t":"İnsanlar için haccı ilan et. Gerek yaya, gerek arık binekler üzerinde uzak vadiden ve yollardan sana gelsinler."},{"n":28,"t":"Ta ki kendileri için faydalara şahid olsunlar ve Allah’ın onlara rızık olarak verdiği hayvanları belli günlerde kurban ederken O’nun adını ansınlar. Siz de bunlardan yeyin. Çaresiz kalmış yoksulu da doyurun."},{"n":29,"t":"Bilahare kirlerini gidersinler, adaklarını yerine getirsinler ve Beyt el Atik’i tavaf etsinler."},{"n":30,"t":"İşte böyle. Kim Allah’ın haram kıldıklarına saygı gösterirse; Rabbı katında bu, onun hayrınadır. Size okunanlardan başka büyük hayvanlar helal kılınmıştır. O halde murdardan, putlardan kaçının ve yalan sözlerden çekinin."},{"n":31,"t":"Allah’a şirk koşmaksızın, hanifler olarak. Kim Allah’a şirk koşarsa; gökten düşüp de kuşların kaptığı veya rüzgarın uçuruma attığı bir şeye benzer."},{"n":32,"t":"Bu böyledir. Kim, Allah’ın nişanelerine saygı gösterirse; şüphesiz ki bu kalblerin takvasındandır."},{"n":33,"t":"Onlarda belli bir süreye kadar sizin için faydalar vardır. Sonra varacakları yer, Beyt el Atik ile son bulur."},{"n":34,"t":"Biz; her ümmet için kurban kesmeyi meşru kıldık ki Allah’ın kendilerine rızık olarak verdiği hayvanların üzerine O’nun adını ansınlar. Sizin tanrınız, bir tek tanrıdır. O’na teslim olun. Sen mütevazı olanları müjdele."},{"n":35,"t":"Onlar ki; Allah anıldığı zaman kalbleri titrer. Başlarına gelenlere sabr eder, namaz kılar ve kendilerine verdiğimiz rızıktan infak ederler."},{"n":36,"t":"Biz, kurbanlık develeri de sizin için Allah’ın nişanelerinden kıldık. Onlarda sizin için hayır vardır. Ön ayakları bağlı halde keserken üzerlerine Allah’ın adını anın. Kesilince onlardan yeyin. İsteyene de, istemeyene de verin. Şükredersiniz diye, onları böylece sizin emrinize müsahhar kıldık."},{"n":37,"t":"Onların ne etleri, ne de kanları Allah’a ulaşır. Sizden O’na sadece takva ulaşır. Sizi hidayete erdirdiği için Allah’ı tekbir edesiniz diye O, bunları size müsahhar kılmıştır."},{"n":38,"t":"Muhakkak ki Allah; iman edenleri savunur. Muhakkak ki Allah; hainleri ve nankörleri sevmez."},{"n":39,"t":"Zulmedildikleri için savaşanlara izin verildi. Allah, onlara yardım etmeye elbette Kadir’dir."},{"n":40,"t":"Onlar ki; haksız yere ve sadece: Rabbımız Allah’tır dedikleri için yurtlarından çıkarılmışlardır. Şüphesiz ki Allah; insanların bir kısmını diğerleriyle bertaraf etmeseydi; manastırlar, kiliseler, havralar ve içinde Allah’ın adı çok anılan mescidler yıkılır giderdi. Allah; kendisine yardım edenlere elbette yardım eder. Şüphesiz ki Allah; Kavi’dir, Aziz’dir."},{"n":41,"t":"Onlar ki; eğer kendilerini yeryüzüne yerleştirirsek; namaz kılarlar, zekat verirler, ma’rufu emreder, münkerden nehyederler. Bütün işlerin akıbeti Allah’adır."},{"n":42,"t":"Eğer seni yalanlıyorlarsa; doğrusu onlardan önce Nuh kavmi, Ad ve Semud da yalanlamıştır."},{"n":43,"t":"İbrahim’in kavmi, Lut’un kavmi de."},{"n":44,"t":"Medyen halkı da. Musa da yalanlanmıştır. Ama Ben; kafirlere mühlet verdim, sonra da onları yakaladım. Benim inkarım nasılmış?"},{"n":45,"t":"Nice kasabaları zulüm ederken helak ettik. Şimdi onların altları üstlerine gelmiş ıpıssız durmaktadır, kuyuları körelmiş, sarayları yıkılmıştır."},{"n":46,"t":"Yeryüzünde dolaşmıyorlar mı ki; orada olanları akledecek kalbleri, işitecek kulakları olsun. Ne var ki yalnız gözler kör olmaz, göğüslerde olan kalbler de körelir."},{"n":47,"t":"Senden çabucak azabı getirmeni istiyorlar. Allah, asla vaadinden caymaz. Doğrusu Rabbının katında bir gün; saydıklarınızdan bin yıl gibidir."},{"n":48,"t":"Nice kasabalar var ki; zalim oldukları halde onlara mühlet vermiştim. Sonunda onları yakalayıverdim. Dönüş yalnız Banadır."},{"n":49,"t":"De ki: Ey insanlar; ben sizin için ancak apaçık bir uyarıcıyım."},{"n":50,"t":"İman edip salih amel işleyenler için mağfiret ve cömertçe verilmiş rızık vardır."},{"n":51,"t":"Ayetlerimizi tartışarak bozmaya uğraşanlar ise; işte onlar, cehennem ashabıdır."},{"n":52,"t":"Senden önce gönderdiğimiz hiç bir Rasul ve hiç bir Nebi yoktur ki; bir şeyi arzuladığı zaman şeytan onun arzusuna vesvese karıştırmamış olsun. Allah; şeytanın karıştırdığını giderir. Sonra Allah; kendi ayetlerini yerleştirir. Ve Allah; Alim’dir, Hakim’dir."},{"n":53,"t":"Şeytanın karıştırdığı, kalblerinde hastalık bulunan ve kalbleri kaskatı olan kimseleri sınamay vesile kılmak içindir. Zalimler, şüpjesiz derin bir ayrılık içindedirler."},{"n":54,"t":"Bir de bu, kendilerine ilim verilenlerin onun, Rabbından gelme bir gerçek olduğunu bilip inanmaları ve gönüllerini ona bağlamaları içindir. Muhakkak ki Allah; iman edenleri dosdoğru yola iletir."},{"n":55,"t":"Küfredenler; kendilerine o saat ansızın gelinceye veya gecesi olmayan günün azabı çatana kadar ondan yana devamlı bir şüphe içinde kalırlar."},{"n":56,"t":"O gün; mülk Allah’ındır. Onların arasında hükmeder. İman edip salih ameller işleyenler; Naim cennetlerindedirler."},{"n":57,"t":"Küfredip ayetlerimizi yalan sayanlar ise; işte onlar için horlayıcı bir azab vardır."},{"n":58,"t":"Onlar ki; Allah yolunda hicret edip de sonra ölür veya öldürülürler; Allah onlara elbette güzel bir rızık verecektir. Şüphesiz ki Allah; rızık verenlerin en hayırlısıdır."},{"n":59,"t":"Andolsun ki; onları hoşnud olacakları bir yere koyacaktır. Muhakkak ki Allah; Alim’dir, Halim’dir."},{"n":60,"t":"İşte böyle. Kim, kendisine yapılan haksızlığa benzeriyle mukabele eder de sonra yine kendisine saldırılırsa; andolsun ki Allah; ona yardım edecektir. Şüphesiz ki Allah; Afüvv’dür, Gafur’dur."},{"n":61,"t":"İşte böyle. Allah; geceyi gündüze katar, gündüzü de geceye katar. Muhakkak ki Allah; Semi’dir, Basir’dir."},{"n":62,"t":"İşte böyle. Çünkü Allah; hakkın ta kendisidir. O’nu bırakıp da taptıkları şeyler de doğrudan doğruya batıldır. Muhakkak ki Allah; Aliyy’dir, Kebir’dir."},{"n":63,"t":"Görmedin mi; Allah, gökten su indirdi de böylece yeryüzü yemyeşil olmaktadır. Ve gerçekten Allah; Latif’dir, Hamid’dir."},{"n":64,"t":"Göklerde ve yerde olanlar O’nundur. Muhakkak ki O; Gani’dir, Hamid’dir."},{"n":65,"t":"Görmedin mi; Allah, yerde olanları ve emriyle denizde akıp giden gemileri buyruğunuz altına vermiştir. İzni olmadıkça, göğü yerin üstüne düşmemesi için O tutar. Doğrusu Allah; insanlara karşı Rauf’dur, Rahim’dir."},{"n":66,"t":"O’dur; sizi dirilten, sonra öldürecek, sonra yine diriltecek olan. Gerçekten insan; çok nankördür."},{"n":67,"t":"Her ümmete; yerine getirmeleri gerekli ibadetler koyduk. Öyle ise işte seninle çekişmesinler, Rabbına davet et. Şüphesiz ki sen; dosdoğru bir hidayet üzeresin."},{"n":68,"t":"Seninle tartışırlarsa de ki: Allah, yapmakta olduğunuzu en iyi bilendir."},{"n":69,"t":"İhtilafa düştüğünüz şeylerde Allah; kıyamet günü aranızda hükmedecektir."},{"n":70,"t":"Bilmez misin ki Allah; gökte ve yerde olanı bilir. Hiç şüphesiz bunlar, bir Kitab’dadır. Doğrusu bunlar, Allah için pek kolaydır."},{"n":71,"t":"Onlar; Allah’ı bırakır da Allah’ın haklarında hiç bir delil indirmediği ve kendilerinde de bilgi bulunmayan şeylere taparlar. Zalimlerin hiç bir yardımcısı yoktur."},{"n":72,"t":"Onlara, apaçık ayetlerimiz okunduğu zaman; o küfredenlerin yüzlerinden inkarı anlarsın. Neredeyse, kendilerine ayetlerimizi okuyanlara saldıracaklar. De ki: Size bundan daha kötüsünü haber vereyim mi? Ateş. Allah, onu küfredenlere vaad etmiştir. Ne kötü dönüş."},{"n":73,"t":"Ey insanlar, bir misal verildi, şimdi onu dinleyin: Şüphesiz ki Allah’ı bırakıp da taptıklarınız bir araya gelseler; bir sinek bile yaratamazlar Ama sinek, onlardan bir şey kapsa bunu da ondan kurtaramazlar. İsteyen de, istenen de aciz."},{"n":74,"t":"Onlar Allah’ı gereği gibi takdir edemediler. Muhakkak ki Allah; Kavi’dir, Aziz’dir."},{"n":75,"t":"Allah; meleklerden elçiler seçer. İnsanlardan da. Doğrusu Allah; Semi’ dir, Basir’dir."},{"n":76,"t":"Onların önlerinde ve arkalarında olanı bilir. Bütün işler Allah’a döndürülür."},{"n":77,"t":"Ey iman edenler; rüku edin, secdeye varın, Rabbınıza kulluk edin ve iyilik yapın ki kurtuluşa eresiniz."},{"n":78,"t":"Ve Allah için hakkıyla cihad edin. O, sizi seçmiş ve babanız İbrahim’in yolu olan dinde sizin için bir zorluk kılmamaıştır. Daha önce peygamberlerin size şahid olması, sizin de insanlara şahidler olmanız için size müslüman adını veren O’dur. Şu halde namaz kılın, zekat verin ve Allah’a sarılın. O’dur sizin Mevlanız. Ne güzel Mevla, ne güzel yardımcı."}],[{"n":1,"t":"Mü’minler; gerçekten felah bulmuşlardır."},{"n":2,"t":"Ki onlar; namazlarında huşu’ içindedirler."},{"n":3,"t":"Ki onlar; boş sözlerden yüz çevirirler."},{"n":4,"t":"Ki onlar; zekatlarını verirler."},{"n":5,"t":"Ki onlar; ırzlarını korurlar."},{"n":6,"t":"Sadece eşleri ve sağ ellerinin malik oldukları müstesnadır. Doğrusu onlar; bunun için de kınanacak değildirler."},{"n":7,"t":"Kim de bundan başkasını ararsa; işte onlar, haddi aşanlardır."},{"n":8,"t":"Ki onlar; emanetlerine ve ahidlerine riayet ederler."},{"n":9,"t":"Ki onlar; namazlarını korurlar."},{"n":10,"t":"İşte onlar; varis olanlardır."},{"n":11,"t":"Onlar ki; Firdevs’e varis olacaklardır ve orada ebedi kalıcıdırlar."},{"n":12,"t":"Andolsun ki; Biz, insanı; çamurdan, süzme bir özden yarattık."},{"n":13,"t":"Sonra da onu nutfe halinde sağlam bir yere yerleştirdik."},{"n":14,"t":"Sonra nutfeyi bir kan pıhtısı haline getirdik. Derken o kan pıhtısını bir çiğnemlik et yaptık. Bir çiğnemlik et parçasını kemik olarak yarattık. Kemiklere de et giydirdik. Ve sonra onu apayrı bir yaratık yaptık. Yaratanların en güzeli olan Allah’ın şanı ne yücedir."},{"n":15,"t":"Sonra siz, bunun arkasından hiç şüphesiz ki öleceksiniz."},{"n":16,"t":"Sonra siz, kıyamet gününde muhakkak diriltileceksiniz."},{"n":17,"t":"Andolsun ki; biz, sizin üstünüzde yedi yol yarattık. Biz yaratmadan gafiller değiliz."},{"n":18,"t":"Gökten belli bir miktarda su indirdik ve onu yerde durdurduk. Şüphesiz Biz; onu gidermeye de kadiriz."},{"n":19,"t":"Onunla sizin için hurmalıklardan, üzümlüklerden nice bağlar ve bahçeler yaptık ki içlerinde sizin için bir çok yemişler vardır. Onlardan yersiniz"},{"n":20,"t":"Tur-u Sina’da yetişen, yiyenlere yağ ve katık veren bir ağaç da var ettik"},{"n":21,"t":"Davarlarda da sizin için elbette bir ibret vardır. Onların karınlarındakinden size içiririz. Sizin için onlarda daha bir çok faydalar vardır. Ve onlardan yersiniz de."},{"n":22,"t":"Hem onların üzerinde, hem de gemilerin üstünde taşınırsınız."},{"n":23,"t":"Andolsun ki; Nuh’u kavmine gönderdik. Dedi ki: Ey kavmim, Allah’a kulluk edin. O’ndan başka tanrınız yoktur, sakınmaz mısınız?"},{"n":24,"t":"Bunun üzerine kavminin önde gelen kafirlerinden bir grup dediler ki: Bu, sizin gibi bir insandan başka bir şey değildir. Sizden üstün olmak istiyor. Şayet Allah dilemiş olsaydı; melekler indirirdi. İlk atalarımızdan da böyle bir şey işitmedik."},{"n":25,"t":"O, kendisinde delilik bulunan bir adamdan başkası değildir. Bir süreye kadar onu gözetleyin."},{"n":26,"t":"O da: Rabbım, beni yalanlamalarına karşılık bana yardım et, dedi."},{"n":27,"t":"Ona vahyettik ki: Gözetimimiz altında sana bildirdiğimiz gibi gemiyi yap. Buyruğumuz gelip de sular kaynayınca her cinsten ikişer çiftive aleyhine hüküm verilmiş olanın dışında kalan çoluk çocuğunu alıp gemiye bindir. Zalimler için bana başvurma. Çünkü onlar boğulacaklardır."},{"n":28,"t":"Sen ve beraberindekiler, gemiye yerleşince: Bizi zalimler topluluğundan kurtaran Allah’a hamdolsun, de."},{"n":29,"t":"Ve de ki: Rabbım; beni mübarek bir yere indir. Ve Sen indirenlerin en hayırlısısın."},{"n":30,"t":"Şüphesiz ki bunda ayetler vardır. Biz, elbette deneyenleriz."},{"n":31,"t":"Bunların ardından başka bir nesil yarattık."},{"n":32,"t":"Onlara da kendilerinden: Allah’a ibadet edin, O’ndan başka tanrınız yoktur. Hala sakınmayacak mısınız? diyen bir peygamber gönderdik."},{"n":33,"t":"Onun kavminden; kendilerine dünya hayatında rızık verdiğimiz halde küfr ederek ahirete kavuşmayı yalanlayan ileri gelenler dediler ki: Bu, sizin gibi bir beşerden başka bir şey değildir. Sizin yediklerinizden yiyor, içtiklerinizden içiyor."},{"n":34,"t":"Eğer kendiniz gibi bir insana boyun eğecek olursanız; hüsrana uğrayacağınızda hiç şüphe yoktur."},{"n":35,"t":"Öldüğünüz ve bir toprak, bir kemik olduğunuz zaman tekrar dirilmenizi mi vaad ediyor?"},{"n":36,"t":"Vaad edildiğiniz şey ne kadar uzak, hem de ne kadar uzak."},{"n":37,"t":"Hayat ancak bu dünyadakidir. Ölürüz, yaşarız. Ama tekrar diriltilecek değiliz."},{"n":38,"t":"O, sadece Allah’a karşı yalan uyduran biridir. Biz ona inanacak değiliz."},{"n":39,"t":"O peygamber: Rabbım, beni yalanlamalarına karşılık bana yardım et, dedi."},{"n":40,"t":"Allah da buyurdu ki: Az sonra pişman olacaklar."},{"n":41,"t":"Gerçekten onları müthiş bir çığlık yakaladı. Ve onları bir süprüntü yığını haline getirdik. Zulmeden kavim uzak olsun."},{"n":42,"t":"Sonra bunların ardından başka bir nesil yarattık."},{"n":43,"t":"Hiç bir ümmet, kendi süresini öne de alamaz, geriye de bırakamaz."},{"n":44,"t":"Sonra birbiri ardı sıra peygamberlerimizi gönderdik. Her ümmete peygamber geldikçe onu yalanladılar. Biz de onları birbiri ardı sıra yok edip hepsini birer söylenti yaptık. İnanmayan bir kavim uzak olsun."},{"n":45,"t":"Sonra Musa’yı ve kardeşi Harun’u ayetlerimizle ve apaçık delillerle gönderdik."},{"n":46,"t":"Firavun’a ve erkanına. Bunun üzerine büyüklük tasladılar. Zaten mağrur bir topluluktular."},{"n":47,"t":"Bu yüzden dediler ki: Kavimleri bize kulluk edip dururken, bizim gibi şu iki insana mı inanacağız?"},{"n":48,"t":"Onları yalanladılar ve bu yüzden helake uğratılanlardan oldular."},{"n":49,"t":"Andolsun ki; doğru yola gelsinler diye Musa’ya Kitab’ı verdik."},{"n":50,"t":"Biz; Meryem’in oğlunu da, annesini de bir ayet kıldık. Her ikisini de sulak, oturmaya elverişli yüksek bir yere yerleştirdik."},{"n":51,"t":"Ey peygamberler; temiz şeylerden yeyin ve salih amel işleyin. Doğrusu Ben; yaptığınızı bilirim."},{"n":52,"t":"Şüphesiz bu; bir tek ümmet olarak sizin ümmetinizdir. Ben de sizin Rabb’ ınızım. Ben’den korkun."},{"n":53,"t":"Ama onlar işlerini kendi aralarında bölük bölük ayırdılar. Her bölük kendi tuttuğu yoldan memnundur."},{"n":54,"t":"Bir süreye kadar onları kendi sapıklıklarıyla başbaşa bırak."},{"n":55,"t":"Zannederler mi ki; kendilerine mal ve oğullar vermekle,"},{"n":56,"t":"İyiliklerde onlar için acele davranmaktayız. Hayır farkında değiller."},{"n":57,"t":"Muhakkak ki Rabblarından korktukları için titreyenler,"},{"n":58,"t":"Ve Rabblarının ayetlerine inananlar,"},{"n":59,"t":"Ve Rabblarına şirk koşmayanlar,"},{"n":60,"t":"Ve Rabblarına döneceklerinden kalbleri ürpererek vermeleri gerekenleri verenler,"},{"n":61,"t":"İşte onlar; hayırlara koşuşurlar ve o uğurda öne geçerler."},{"n":62,"t":"Biz, hiç kimseye gücünün yeteceğinden fazlasını yüklemeyiz. Katımızda gerçeği konuşan bir kitab vardır. Ve onlar asla haksızlığa uğratılmazlar"},{"n":63,"t":"Hayır, onların kalbleri bundan habersizdir. Onların bundan başka da yapageldikleri işler vardır."},{"n":64,"t":"En sonunda onların refahla şımaranlarını azabla yakaladığımız zaman hemen feryad ederler."},{"n":65,"t":"Feryad etmeyin bugün. Doğrusu siz, katımızdan bir yardım görmezsiniz."},{"n":66,"t":"Ayetlerimiz size okunuyordu da siz, ona arkanızı dönüyordunuz."},{"n":67,"t":"Büyüklük taslıyor, gece ağzınıza geleni söylüyordunuz."},{"n":68,"t":"Söyleneni düşünmediler mi hiç? Yoksa onlara, daha önce geçen atalarına gelmeyen bir şey mi geldi?"},{"n":69,"t":"Yoksa peygamberlerini tanımadılar da onun için mi inkar ediyorlar?"},{"n":70,"t":"Yahut; onda bir delilik var mı diyorlar? Hayır, o kendilerine hak ile gelmiştir. Ama onların çoğu haktan hoşlanmamaktadırlar."},{"n":71,"t":"Şayet hak, onların heveslerine uysaydı; gökler, yer ve onlarda bulunanlar muhakkak bozulup giderdi. Hayır, Biz onlara kendi zikirlerini getirdik. Ama onlar zikirlerinden yüz çeviriyorlar."},{"n":72,"t":"Yoksa sen, onlardan bir ücret mi istiyorsun? Rabbının ecri daha hayırlıdır. Ve O, rızık verenlerin en hayırlısıdır."},{"n":73,"t":"Aslında sen, onları dosdoğru bir yola çağırıyorsun."},{"n":74,"t":"Ama ahirete inanmayanlar, mutlaka bu yoldan sapmaktadırlar."},{"n":75,"t":"Şayet Biz, onlara acısak ve başlarındaki sıkıntıyı gidersek yine de azgınlıkları içinde bocalayıp kalırlar."},{"n":76,"t":"Andolsun ki Biz, onları azabla yakaladık. Ama yine de Rabblarına boyun eğmediler. Onlar yalvarıp yakarmazlar."},{"n":77,"t":"Sonunda onlara şiddetli bir azab kapısı açtığımızda şaşkına dönüp ümitsiz kalıverdiler"},{"n":78,"t":"Sizin için kulaklar, gözler ve kalbler var eden O’dur. Ne de az şükrediyorsunuz."},{"n":79,"t":"Sizi yeryüzünde yaratıp türeten O’dur. Ve O’nun huzurunda toplanacaksınız"},{"n":80,"t":"Dirilten de, öldüren de O’dur. Geceyle gündüzün birbiri ardı sıra gelmesi de O’nun emrine bağlıdır. Hala düşünmez misiniz?"},{"n":81,"t":"Hayır, onlar yine de öncekilerin dediklerini derler."},{"n":82,"t":"Onlar demişlerdi ki: Ölüp de toprak ve kemik yığını olduğumuzda mı, gerçekten biz mi diriltileceğiz?"},{"n":83,"t":"Andolsun ki biz, ve daha önce de atalarımız bununla tehdit edilmişti. Bu eskilerin masallarından başka bir şey değildir."},{"n":84,"t":"De ki: Yer ve onda bulunanlar kimindir? Biliyorsanız söyleyin."},{"n":85,"t":"Allah’ındır, diyecekler. Öyleyse ibret almaz mısınız? de."},{"n":86,"t":"De ki: Yedi göğün Rabbı ve yüce Arş’ın Rabbı kimdir?"},{"n":87,"t":"Allah’tır, diyecekler. Öyleyse sakınmaz mısınız? de."},{"n":88,"t":"De ki: Her şeyin hükümranlığı elinde olan, barındıran, ama barındırılmaya asla muhtaç olmayan kimdir?"},{"n":89,"t":"Allah’tır, diyecekler. Öyleyse nasıl aldanıyorsunuz? de."},{"n":90,"t":"Hayır, Biz, onlara gerçeği getirdik. Ama onlar muhakkak yalancılardır."},{"n":91,"t":"Allah, hiç bir çocuk edinmemiştir ve O’nunla birlikte hiç bir ilah da yoktur. Olsaydı; o zaman, her ilah, kendi yarattığını alıp götürür ve birbirinden üstün çıkmaya çalışırlardı. Allah, onların nitelendirdiklerinden mğünezzehtir."},{"n":92,"t":"O, görüleni de, görülmeyeni de bilir. Onların koştukları ortaklardan çok yücedir."},{"n":93,"t":"De ki: Rabbım, onların tehdit olundukları şeyi bana mutlaka göstereceksen,"},{"n":94,"t":"Rabbım, o zaman beni zalimler güruhunun içinde bulundurma."},{"n":95,"t":"Biz, onlara vaad ettiğimizi sana göstermeye elbette kadiriz."},{"n":96,"t":"Sen, kötülüğü en güzel ile sav. Onların nitelendirmekte olduklarını Biz, çok daha iyi biliriz."},{"n":97,"t":"Ve de ki: Rabbım, şeytanların kışkırtmalarından Sana sığınırım."},{"n":98,"t":"Rabbım, onların huzurumda bulunmalarından Sana sığınırım."},{"n":99,"t":"Onlardan birine ölüm geldiği vakit der ki: Rabbım, beni geri döndür."},{"n":100,"t":"Belki yapmadan bıraktığımı tamamlar ve salih amel işlerim. Hayır, bu söylediği, sadece kendi lafıdır. Tekrar diriltilecekleri güne kadar arkalarında onları geriye dönmekten alıkoyan bir berzah vardır."},{"n":101,"t":"Sur’a üflendiği zaman; o gün, artık aralarındaki soy yakınlığı fayda vermez. Birbirlerine bir şey de soramazlar."},{"n":102,"t":"Tartıları ağır gelenler; işte onlar, felaha ermiş olanların kendileridir."},{"n":103,"t":"Kimin de tartıları hafif gelirse; işte onlar, kendilerine yazık edenlerdir, cehennemde ebedi kalırlar."},{"n":104,"t":"Ateş onların yüzlerini yalar, dişleri sırıtıp kalır."},{"n":105,"t":"Ayetlerim size okunurken, onları yalanlayanlar siz değil miydiniz?"},{"n":106,"t":"Derler ki: Rabbımız, bedbahtlığımız bizi yenmişti. Sapıklar topluluğu olmuştuk."},{"n":107,"t":"Rabbımız, bizi buradan çıkar, tekrar dönersek doğrusu zulmetmiş oluruz."},{"n":108,"t":"Buyurdu ki: Yıkılıp gidin içerisine. Benimle konuşmayın."},{"n":109,"t":"Çünkü kullarımdan bir zümre vardı ki, onlar: Rabbımız, inandık, artık bağışla bizi, merhamet et bize. Sen merhamet edenlerin en hayırlısısın, diyordu."},{"n":110,"t":"Siz ise, onları alaya alıyordunuz. Öyle ki size Benim zikrimi unutturdular. Ve siz, onlara hep gülüyordunuz."},{"n":111,"t":"Sabrettiklerinden dolayı bugün onları mükafatlandırdım. Doğrusu onlar, kurtuluşa erenlerin kendileridir."},{"n":112,"t":"Buyurdu ki: Yıl sayısı olarak yeryüzünde ne kadar kaldınız?"},{"n":113,"t":"Bir gün veya daha az bir süre kaldık, sayanlara sor, dediler."},{"n":114,"t":"Buyurdu ki: Çok az bir süre kaldınız. Keşki bilseydiniz."},{"n":115,"t":"Sizi boşuna yarattığımızı ve Bize hiç döndürülmeyeceğinizi mi sandınız?"},{"n":116,"t":"Gerçek hükümdar olan Allah yücedir. O’ndan başka hiç bir tanrı yoktur ve O, yüce Arş’ın Rabbıdır."},{"n":117,"t":"Kim, başka bir tanrıya taparsa; onun hiç bir delili yoktur ve onun hesabı Rabbının katındadır. Gerçek şu ki, kafirler felah bulamazlar."},{"n":118,"t":"De ki: Rabbım, mağfiret et, merhamet et. Sen, merhamet edenlerin en hayırlısısın."}],[{"n":1,"t":"Bir sure. Onu indirdik ve farz kıldık. Onda apaçık ayetler indirdik ki düşünüp öğüt alasınız."},{"n":2,"t":"Zina eden kadın ve zina eden erkeğin her birine yüzer değnek vurun. Allah a ve ahiret gününe inanıyorsanız, Allah’ın dini hususunda bir acıma tutmasın. Mü’minlerden bir grup da bunların azabına şahid olsun."},{"n":3,"t":"Zina eden erkek; zina eden veya müşrik olan bir kadından başkasını nikah layamaz. Zina eden kadınla da zina eden veya müşrik olan bir erkekten başkası nikahlanamaz. Bu, mü’minlere haram kılınmıştır."},{"n":4,"t":"İffetli, hür kadınlara iftira atan, sonra da dört şahid getiremeyenlere seksen değnek vurun. Ebediyyen onların şahidliğini kabul etmeyin. İşte onlar, fasıkların kendileridir."},{"n":5,"t":"Meğer ki bundan sonra tevbe edip islah olalar. Şüphesiz ki Allah; Gafur’ dur, Rahim’dir."},{"n":6,"t":"Eşlerine zina isnad edip de kendilerinden başka şahidleri olmayanların şahidliği; kendisinin doğru sözlülerden olduğuna dair Allah’ı dört defa şahid tutmasıdır."},{"n":7,"t":"Beşincisi de; eğer yalancılardan ise Allah’ın lanetinin kendi üzerine olmasıdır."},{"n":8,"t":"Kocasının yalancılardan olduğuna dair dört defa Allah’ı şahid tutması kadından cezayı savar."},{"n":9,"t":"Beşincisi de; kocası doğrulardan ise kendisinin Allah’ın gazabına uğramasıdır."},{"n":10,"t":"Ya üzerlerinizde Allah’ın fazl-u rahmeti olmasaydı? Ve gerçekten Allah; Tevvab, Hakim olmasaydı?"},{"n":11,"t":"Doğrusu uydurulmuş bir yalanla gelenler, içinizden bir zümredir. Bunu kendiniz için kötü sanmayın. O, sizin için hayırlı olmuştur. O kimselerden her birine kazandığı günaha karşılık ceza vardır. En büyük azab da içlerinden elebaşılık yapanındır."},{"n":12,"t":"Onu işittiğiniz vakit mü’min erkeklerle, mü’min kadınların kendiliklerinden hüsn-ü zanda bulunup: Bu, apaçık bir iftiradır, demeleri gerekmez miydi?"},{"n":13,"t":"Buna karşı dört şahidle gelmeleri gerekmez miydi? Madem ki onlar şahidleri getiremediler, öyleyse onlar Allah katında yalancıların kendileridirler."},{"n":14,"t":"Dünya ve ahirette Allah’ın lutfu ve rahmeti üzerinizde olmasaydı, içine daldığınız yaygaradan dolayı her halde size büyük bir azab dokunurdu."},{"n":15,"t":"Onu dilinize dolamıştınız. Ve bilmediğiniz şeyleri ağzınıza alıyordunuz. Önemsiz bir şey sanıyorsunuz ama Allah katında önemi çok büyüktür."},{"n":16,"t":"Onu duyduğunuz zaman: Bunu söylememiz bize yakışmaz. Haşa bu, büyük bir iftiradır, demeniz gerekmez miydi?"},{"n":17,"t":"Eğer mü’min kişilerdenseniz; buna benzer bir şeye bir daha dönmemeniz için Allah, size öğüt veriyor."},{"n":18,"t":"Ve Allah, size ayetlerini açıkça bildiriyor. Allah; Alim’dir, Hakim’dir."},{"n":19,"t":"Mü’minler arasında kötülüğün ve hayasızlığın yayılmasını arzu edenlere, işte onlara, dünya ve ahirette elim bir azab vardır ve Allah bilir, siz bilmezsiniz."},{"n":20,"t":"Ya Allah’ın üzerinizde lutuf ve rahmeti bulunmasaydı? Ya Allah, gerçekten Rauf ve Rahim olmasaydı?"},{"n":21,"t":"Ey iman edenler; şeytanın adımlarına uymayın. Kim, şeytanın adımlarına uyarsa; bilsin ki o, hayasızlığı ve kötülüğü emreder. Şayet Allah’ın sizin üzerinizde lutuf ve rahmeti bulunmasaydı; hiç biriniz ebediyyen temize çıkamazdı. Ancak Allah, dilediğini temize çıkarır ve Allah Semi’ dir, Alim’dir."},{"n":22,"t":"Sizden faziletli ve varlıklı olanlar; yakınlarına, yoksullara ve Allah yolunda hicret edenlere vermekte kusur etmesinler, affetsinler, aldırış etmesinler. Allah’ın sizi bağışlamasını sevmez misiniz? Ve Allah; Gafur’ dur, Rahim’dir."},{"n":23,"t":"İffetli ve mü’min kadınlara iftira atanlar; dünyada da ahirette de lanetlenmişlerdir. Ve onlar için büyük bir azab vardır."},{"n":24,"t":"O gün; kendi dilleri, elleri ve ayakları yapmış oldukları şeylere şahidlik edecektir."},{"n":25,"t":"O gün; Allah onlara hak olan cezalarını verecektir. Şüphesiz onlar da Allah’ın apaçık hakkın ta kendisi olduğunu bileceklerdir."},{"n":26,"t":"Kötü kadınlar, kötü erkekler için; kötü erkekler de, kötü kadınlar içindir. İyi kadınlar, iyi erkekler için; iyi erkekler de, iyi kadınlar içindir. Bunlar; onların söylediklerinden uzaktırlar. Ve onlar için; mağfiret, cömertçe verilmiş bir rızık vardır."},{"n":27,"t":"Ey iman edenler; evlerinizden başka evlere, sahibleriyle alışkanlık kurup selam vermeden girmeyin. Bu, sizin için daha hayırlıdır. Olur ki iyice düşünürsünüz."},{"n":28,"t":"Eğer orada kimseyi bulamazsanız; size izin verilinceye kadar içeri girmeyin. Şayet size; dönün, denilirse, dönün. Bu, sizin için daha temizdir. Ve Allah; yaptıklarınızı bilir."},{"n":29,"t":"İçinde menfaatınız bulunan ve oturulmayan boş evlere girmenizde birvebal yoktur. Ve Allah; açığa vurduğunuzu da, gizlediğinizi de bilir."},{"n":30,"t":"Mü’min erkeklere söyle: Gözlerini sakınsınlar ve ırzlarını korusunlar. Bu, kendileri için daha temizdir. Allah yaptıklarından şüphesiz haberdardır."},{"n":31,"t":"Mü’min kadınlara da söyle: Gözlerini sakınsınlar ve ırzlarını korusunlar. Görünen kısmı müstesna, zinetlerini göstermesinler. Başörtülerini yakalarının üstüne salsınlar. Zinetlerini; kocaları veye babaları veya kocalarının babaları veya oğulları veya kocalarının oğulları veya kardeşleri veya erkek kardeşlerinin oğulları veya kızkardeşlerinin oğulları veya kadınları veya cariyeleri veya erkekliği kalmamış hizmetçileri, yahut kadınların mahrem yerlerini henüz anlamayan çocuklardan başkasına göster mesinler. Gizledikleri zinetlerinin bilinmesi için de ayaklarını vurmasınlar. Ey mü’minler; hepiniz Allah’a tevbe edin ki felaha eresiniz."},{"n":32,"t":"İçinizden bekarları ve kölelerinizden, cariyelerinizden salih olanları evlendirin. Şayet yoksul iseler; Allah onları lutfuyla zenginleştirir. Ve Allah; Vasi’dir, Alim’dir."},{"n":33,"t":"Evlenemeyenler de; kendilerini Allah, lutfuyla zenginleştirinceye kadar iffetli davransınlar. Kölelerinizden hür olmak için bedel vermek isteyenlerin bedel vermelerini kabul edin. Şayet onlarda bir hayır görüyorsanız Ve Allah’ın size verdiği maldan onlara verin. Dünya hayatının geçici menfaatını elde etmek için iffetli olmak isteyen cariyelerinizi fuhşa zorlamayın. Kim onları zorlarsa şüphesiz ki Allah, onların zorlamalarından sonra da Gafur’dur, Rahim’dir."},{"n":34,"t":"Andolsun ki Biz; apaçık ayetler, sizden önce geçenlerden misaller ve takvaya erenler için de öğütler indirdik."},{"n":35,"t":"Allah; göklerin ve yerin nurudur. O’nun nurunun misali; içinde çerağ bulunan bir kandil yuvası gibidir. O çerağ bir sırça içindedir. Sırça sanki inci gibi parlayan bir yıldızdır. Güneşin doğduğu yere de, battığı yere de nisbeti olmayan mübarek bir ağaçtan, zeytinden tutuşturulup yakılır. Ateş değmese dahi, neredeyse yağın kendisi aydınlatacak. Nur üstüne nurdur. Allah; dilediğini nuruna kavuşturur. Allah; insana misaller verir. Ve Allah; her şeyi bilendir."},{"n":36,"t":"O evlerde ki; Allah, onların yüceltilmesine ve içlerinde kendisinin adının anılmasına izin vermiştir. Onlar da sabah akşam O’nu tesbih ederler."},{"n":37,"t":"Öyle erler ki; ne ticaret, ne alış-veriş onları Allah’ı zikretmekten, namaz kılmaktan ve zekat vermekten alıkoymaz. Onlar gönüllerin ve gözlerin döneceği günden korkarlar."},{"n":38,"t":"Allah; onları işledikleri amellerin en güzeliyle mükafatlandıracak, onlara lutfunu fazlasıyla verecektir. Ve Allah; dilediğini hesapsız şekilde rızıklandırır."},{"n":39,"t":"Küfredenlere gelince; onların amelleri, engin çöllerde serap gibidir. Susayan kimse onu, su sanır. Fakat yanına vardığı zaman hiç bir şey bulamaz. Kendi yanında Allah’ı bulur ve O da hesabını tastamam görür. Allah hesabı çabucak görendir."},{"n":40,"t":"Veya engin bir denizdeki karanlıklara benzer. Onun üstünü bir dalga kaplar, onun üstünde bir dalga, onun da üstünde bir bulut vardır. Karanlıklar üstünde karanlıklar. Elini uzattığı zaman; neredeyse onu bile göremez. Allah’ın nur vermediği kimsenin, asla nuru olmaz."},{"n":41,"t":"Görmedin mi ki; göklerde ve yerde bulunanlar, saf saf uçan kuşlar Allah’ ı tesbih etmektedir. Her biri kendi duasını ve tesbihini bilir. Allah; onların yaptıklarını bilendir."},{"n":42,"t":"Göklerin ve yerin mülkü Allah’ındır. Dönüş de yalnız Allah’adır."},{"n":43,"t":"Görmedin mi ki; Allah, bulutları sürer, sonra onları bir araya getirip üst üste yığar. Ve sen, onların arasından yağmurun yağdığını görürsün. Gökten içinde dolu bulunan dağlar gibi bulutlar indirir de dilediğini ona uğratır ve dilediğinden onu uzak tutar. Onun şimşeğinin pırıltısı, neredeyse gözleri alıverecek."},{"n":44,"t":"Allah; gece ile gündüzü evirip çevirir. Doğrusu, görebilenler için bunda ibret vardır."},{"n":45,"t":"Allah; hareket eden her canlıyı sudan yaratmıştır. Kimi karnı üzerinde sürünür, kimi iki ayakla yürür, kimi de dört ayakla yürür. Allah; dilediğini yaratır. Şüphesiz ki Allah; her şeye kadirdir."},{"n":46,"t":"Andolsun ki Biz; açıklayıcı ayetler indirdik, Ve Allah; dilediğini doğru yola iletir."},{"n":47,"t":"Allah’a da Peygambere de inandık ve itaat ettik, derler. Sonra da bunun ardından bir takımı yüz çevirir. Bunlar inanmış kimseler değillerdir."},{"n":48,"t":"Aralarında hükmetmesi için Allah’a ve Rasulüne çağrıldıkları zaman; bir takımı hemen yüz çevirir."},{"n":49,"t":"Eğer hak, kendilerinden tarafa ise; boyunlarını bükerek gelirler."},{"n":50,"t":"Kalblerinde bir hastalık mı var bunların? Yoksa şüphe mi ettiler? Veya Allah’ın ve Rasulünün kendilerine haksızlık edeceğinden mi korkuyorlar? Hayır, onlar; zalimlerin kendileridir."},{"n":51,"t":"Aralarında hükmetmesi için Allah’a ve Rasulüne çağrıldıkları zaman; mü’minlerin sözü, sadece: İşittik ve itaat ettik, demekten ibarettir. Ve işte onlar, felaha erenlerin kendileridir."},{"n":52,"t":"Kim, Allah’a ve Rasulüne itaat eder, Allah’tan korkar ve sakınırsa; işte onlar, kurtuluşa erenlerin kendileridir."},{"n":53,"t":"Var güçleriyle Allah’a yemin ettiler ki; eğer kendilerine emredersen çıkacaklardır. De ki: Yemin etmeyin. Makul bir itaat. Muhakkak ki Allah, yaptıklarınızdan haberdardır."},{"n":54,"t":"De ki: Allah’a itaat edin, Peygambere itaat edin. Şayet yüz çevirirseniz bilin ki; o, kendisine yükletilenden, siz de kendinize yükletilenden sorumlusunuz. Eğer ona itaat ederseniz; doğru yolu bulursunuz. Peygambere düşen, apaçık tebliğden başkası değildir."},{"n":55,"t":"Allah; içinizden iman edip salih amel işleyenlere vaad etti ki: Onlardan öncekileri nasıl halef kıldı ise onları da yeryüzüne halef kılacak ve on lar için beğendiği dini temelli yerleştirecek, korkularını emniyete çevirecektir. Çünkü onlar, Bana kulluk eder ve hiç bir şeyi Bana şirk koşmazlar. Kim de bundan sonra inkar ederse; işte onlar fasıkların kendileridir."},{"n":56,"t":"Namaz kılın, zekat verin ve peygambere itaat edin ki rahmete kavuşturulasınız."},{"n":57,"t":"Sakın küfredenlerin, Bizi yeryüzünde aciz bırakacaklarını sanma. Onların barınakları ateştir. Ne kötü dönüştür."},{"n":58,"t":"Ey iman edenler; ellerinizin altında olan köle ve cariyeler ve sizden henüz erginlik çağına gelmemiş olanlar; sabah namazından önce, öğle sıcağında soyunduğunuz zaman ve yatsı namazından sonra, yanınıza girecekleri vakit üç defa izin istesinler. Bunlar sizin üç mahrem vaktinizdir. Bu vakitlerin dışında birbirinizin yanına girip çıkmakta size de, onlara da bir sorumluluk yoktur. Allah; size ayetlerini böylece açıklar. Ve Allah; Alim’dir, Hakim’dir."},{"n":59,"t":"Çocuklarınız erginlik çağına vardığında, kendilerinden öncekilerin izin istediği gibi onlar da izin istesinler. Allah; size ayetlerini böyle açıklar. Ve Allah; Alim’dir, Hakim’dir."},{"n":60,"t":"Evlenme ümidi kalmayan yaşlanıp oturmuş kadınlara, zinetlerini açığa vurmamak şartıyla dış elbiselerini çıkarmaktan dolayı bir vebal yoktur. Ama iffetli davranmaları onlar için daha hayırlıdır. Ve Allah; Semi’dir, Alim’dir."},{"n":61,"t":"Köre bir sorumluluk yoktur. Topala da bir sorumluluk yoktur. Hastaya da bir sorumluluk yoktur. Kendi evlerinizde veya babalarınızın evlerinde veya annelerinizin evlerinde veya erkek kardeşlerinizin evlerinde veya kızkardeşlerinizin evlerinde veya amcalarınızın evlerinde veya halalarınızın evlerinde veya dayılarınızın evlerinde veya teyzelerinizin evlerinde veya anahtarlarına malik olduğunuz yerlerde veya dostlarınızın evlerinde izinsiz yemek yemenizde bir sorumluluk yoktur. Bir arada veya ayrı ayrı yemenizde bir sorumluluk yoktur. Evlere girdiğiniz zaman, Allah katından bereket, sağlık ve güzellik dileyerek kendinize selam verin. Allah"},{"n":62,"t":"Mü’minler; ancak Allah’a ve Rasulüne iman edenler ve peygamberle birlikte bir işe karar vermek için toplandıklarında, ondan izin isteyip alıncaya kadar ayrılıp gitmeyenlerdir. Gerçekten senden izin isteyenler; işte onlar, Allah’a ve Rasulüne iman edenlerdir. Bir takım işleri için senden izin isterlerse içlerinden dilediğine izin ver ve Allah’tan onların bağışlanmalarını dile. Şüphesiz ki Allah; Gafur’dur, Rahim’dir."},{"n":63,"t":"Peygamberin çağırmasını; kendi aranızda birbirinizi çağırmanız gibi saymayın. Allah; içinizden bir diğerini siper ederek sıvışıp gidenleri muhakkak bilir. Onun buyruğuna aykırı hareket edenler, başlarına bir bela gelmesinden veya elim bir azaba uğramaktan sakınsınlar."},{"n":64,"t":"Dikkat edin, göklerde ve yerde ne varsa hepsi Allah’ındır. O, içinde bulunduğunuz durumu da, kendisine döndürüleceğiniz günü de muhakkak bilir. Onlara işlediklerini haber verecektir. Allah, her şeyi hakkıyla bilendir."}],[{"n":1,"t":"Alemleri uyarmak üzere kuluna Furkan’ı indiren ne yücedir."},{"n":2,"t":"O ki; göklerin ve yerin mülkü O’nundur. Çocuk edinmemiştir, mülkte ortağı yoktur. Her şeyi yaratmış, ona bir düzen vermiş ve bir ölçüyle takdir etmiştir."},{"n":3,"t":"O’nu bırakıp da, bir şey yaratmayan; üstelik kendileri yaratılmış olan ve kendilerine ne bir zarar ne de bir fayda vermeyen, öldürmeye, diriltmeye ve ölümden sonra tekrar canlandırmaya gücü yetmeyen bir takım ilahlar edindiler."},{"n":4,"t":"Küfredenler dediler ki: Bu ancak onun uydurduğu bir yalandır ve ona bu hususta bir başka topluluk yardım etmiştir. Hiç şüphesiz onlar, zulüm ve iftira ile geldiler."},{"n":5,"t":"Ve dediler ki: Öncekilerin masallarıdır. Başkalarına yazdırıp sabah akşam kendisine okunmaktadır."},{"n":6,"t":"De ki: Onu göklerde ve yerdeki sırrı bilen indirmiştir. Şüphesiz ki O; Gafur ve Rahim olandır."},{"n":7,"t":"Ve dediler ki: Bu peygambere ne oluyor ki; yemek yiyor, sokaklarda geziyor? Onun beraberinde bulunup uyaran bir melek indirilmeli değil miydi?"},{"n":8,"t":"Yahut kendisine bir hazine verilmeli veya besleneceği bir bahçe olmalı değil miydi? O zalimler dediler ki: Siz, büyülenmiş bir adamdan başkasına tabi olmuyorsunuz."},{"n":9,"t":"Bir bak; sana nasıl misaller getirip saptılar. Bir daha yol bulamazlar."},{"n":10,"t":"Dilerse sana bunlardan daha hayırlı olarak altından ırmaklar akan cennet ler verebilen ve köşkler kurabilen Allah ne yücedir."},{"n":11,"t":"Fakat onlar, kıyamet saatını da yalanladılar. Biz, o saatın geleceğini yalanlayanlara öyle çılgın bir ateş hazırladık ki."},{"n":12,"t":"Bu, kendilerine uzak bir yerden gözükünce onun kaynayışını ve uğultusunu duyacaklardır."},{"n":13,"t":"Elleri boyunlarına bağlı olarak onun en dar bir yerine atıldıkları zaman orada yok olup gitmeyi isterler."},{"n":14,"t":"Bugün bir kere yok olmayı değil, bir çok kereler yok olmayı isteyin."},{"n":15,"t":"De ki: Bu mu daha hayırlıdır, yoksa müttakilere vaad olunan ebedi cennet mi? Ki bu, onlar için bir mükafat ve son duraktır."},{"n":16,"t":"Onlar için orada diledikleri her şey var. Ve temelli kalırlar. Bu, Rabbının yerine getirilmesi istenen bir vaadidir."},{"n":17,"t":"O gün Rabbın onları ve Allah’tan başka taptıklarını bir araya toplar ve: Bu kullarımı siz mi saptırdınız, yoksa kendileri mi yoldan saptılar? der."},{"n":18,"t":"Onlar da derler ki: Tenzih ederiz, Seni bırakır da başka dostlar edinmek bize yaraşmaz. Ama Sen, onlara ve babalarına nimetler verdin de, Seni anmayı unuttular ve helaki hak eden bir kavim oldular."},{"n":19,"t":"İşte sizi söylediklerinizde yalancı çıkardılar. Artık üzerinizden azabı çeviremez ve yardım göremezsiniz. Sizden zulmedenlere büyük bir azab tattıracağız, denir."},{"n":20,"t":"Senden önce gönderdiğimiz bütün peygamberler de şüphesiz yemek yerler, sokaklarda gezinirlerdi. Sabreder misiniz diye sizi birbirinizle deneriz. Ve Rabbın Basir olandır."},{"n":21,"t":"Bize kavuşmayı ummayanlar: Bize melekler indirilmeli değil miydi veya Rabbımızı görmeli değil miydik? derler. Andolsun ki; kendi kendilerine büyüklenmişler ve büyük bir azgınlıkla haddi aşmışlardır."},{"n":22,"t":"Melekleri görecekleri gün; işte o gün, günahkarlara iyi haberler yoktur. Melekler: Size iyi haber yasaktır, yasak, derler."},{"n":23,"t":"Yaptıkları her işi ele alır ve onu toz-duman ederiz."},{"n":24,"t":"O gün cennet yaranının kalacağı yer; çok daha iyi, dinlenecekleri yer; çok daha güzeldir."},{"n":25,"t":"Ve o gün; gök beyaz bulutlar halinde parçalanacak, melekler bölük bölük indirileceklerdir."},{"n":26,"t":"O günde gerçek mülk, Rahman’ındır. Kafirler için de pek yaman bir gündür."},{"n":27,"t":"O gün; zalim kimse iki elini ısırarak: Ne olurdu ben de peygamberle beraber bir yol tutsaydım, diyecektir."},{"n":28,"t":"Vay başıma gelene: Keşki falancayı dost edinmeseydim."},{"n":29,"t":"Andolsun ki; bana gelen zikirden beni, o saptırdı. Şeytan; insanı yapayalnız ve yardımsız bırakandır."},{"n":30,"t":"Ve Peygamber dedi ki: Ey RAbbım; doğrusu kavmim bu Kur’an’ı terkedilmiş olarak bıraktı."},{"n":31,"t":"İşte böylece Biz; her peygambere suçlulardan bir düşman kıldık. Hidayete götüren ve yardımcı olarak Rabbın yeter."},{"n":32,"t":"O küfredenler dediler ki: Kur’an ona bir kerede topluca indirilmeli değil miydi? Halbuki Biz; onu senin kalbine iyice yerleştirmek için böyle azar azar indirir ve ağır ağır okuruz."},{"n":33,"t":"Onlar sana bir misal getirmeye görsünler, Biz; onun gerçeğini ve en iyi anlaşılanını sana getirmişizdir."},{"n":34,"t":"Cehennemde yüzleri üstü toplanacak olanların; işte onların yeri çok kötü ve yolu çok sapıktır."},{"n":35,"t":"Andolsun ki; Biz, Musa’ya kitabı verdik. Kardeşi Harun’u da kendisine vezir yaptık."},{"n":36,"t":"Ayetlerimizi yalanlayan kavme gidin, dedik. Neticede o kavmi yerle bir ettik."},{"n":37,"t":"Nuh kavmini de peygamberlerini yalanladıkları vakit, suda boğduk ve kendilerini insanlar için bir ayet yaptık. Zalimlere elim bir azab hazırlamışızdır."},{"n":38,"t":"Ad ve Semud’u da, Ress ashabını ve bunların arasında bir çok nesilleri de"},{"n":39,"t":"Her birine misaller vermiştik. Ama hepsini kırdık geçirdik."},{"n":40,"t":"Andolsun ki; onlar, bela yağmuruna tutulmuş olan kasabaya uğramışlardır. Onu görmediler mi? Hayır, onlar tekrar dirileceklerini ummazlar."},{"n":41,"t":"Seni gördükleri vakit: Bu mu Allah’ın gönderdiği elçi? diye alaya almaktan başka bir şey yapmazlar."},{"n":42,"t":"Gerçekten tanrılarımız üzerinde direnmeseydik bizi az kalsın onlardan saptıracaktı, derler. Azabı gördükleri vakit, kimin yolunun sapık olduğunu bileceklerdir."},{"n":43,"t":"Heva ve hevesini tanrı edinen kimseyi gördün mü? Şimdi onun üzerine vekil sen mi olacaksın?"},{"n":44,"t":"Yoksa sen, onların çoğunun dilediklerini veya aklettiklerini mi sanıyorsun? Başka değil, onlar dört ayaklı hayvanlar gibidirler. Hatta daha da sapıktırlar."},{"n":45,"t":"Görmedin mi; Rabbın, gölgeyi nasıl uzatmıştır. İsteseydi onu durdururdu. Sonra Biz, güneşi ona delil kıldık."},{"n":46,"t":"Sonra onu yavaş yavaş kendimize çekmişizdir."},{"n":47,"t":"O’dur; size geceyi örtü, uykuyu rahatlık kılan ve gündüzü çalışma zamanı yapan."},{"n":48,"t":"Ve O’dur; rüzgarları rahmetinin önünde müjdeci gönderen. Ve Biz; gökten tertemiz bir su indirdik."},{"n":49,"t":"Ki onunla ölü bir şehri canlandıralım ve yarattığımız nice hayvan ve insanları sulayalım."},{"n":50,"t":"Andolsun ki; düşünüp ibret alsınlar diye onu aralarında evirip çevirmekteyiz. Buna rağmen insanların çoğu nankörlükte direnmişlerdir."},{"n":51,"t":"Dileseydik; her kasabaya bir uyarıcı gönderirdik."},{"n":52,"t":"Öyleyse sen, kafirlere uyma ve onlara karşı olanca gücünle cihad et."},{"n":53,"t":"Ve O’dur; iki denizi salıp katan. Şu tatlı ve susuzluğu giderici, bu ise tuzlu ve acıdır. İkisinin arasına bir engel ve aşılamayan bir sınır koymuştur."},{"n":54,"t":"O’dur; insanı sudan yaratarak ona soy-sop veren. Ve Rabbın her şeye kadirdir."},{"n":55,"t":"Allah’ı bırakıp kendilerine fayda veya zarar veremeyen şeylere ibadet ederler. Kafir; Rabbına karşı duranın yardımcısıdır."},{"n":56,"t":"Biz; seni, sadece bir müjdeci ve uyarıcı olarak gönderdik."},{"n":57,"t":"De ki: Buna karşılık ben, sizden bir ücret değil, sadece Rabbıma doğru bir yol tutmak isteyen kimseler olmanızı istiyorum."},{"n":58,"t":"Sen; asla ölmeyen ve daima diri olana tevekkül et ve O’nu hamd ile tesbih et. Kullarının günahlarından haberdar olarak kendisi yeter."},{"n":59,"t":"Gökleri, yeri ve ikisinin arasındakileri altı günde yaratan, sonra da Arş’a hükmeden Rahman’dır. Bunu haberdar olana sor."},{"n":60,"t":"Onlara: Rahman’a secde edin, denildiği zaman: Rahman da nedir? Senin bize emredegeldiğine mi secde edeceğiz? derler. Ve bu, onların nefretini arttırır."},{"n":61,"t":"Gökte burçlar var eden, orada bir çerağ ve aydınlatan ayı var eden ne yücedir."},{"n":62,"t":"İbret almak veya şükretmek isteyen kimseler için, gece ile gündüzü bir biri ardınca getiren O’dur."},{"n":63,"t":"Rahman’ın kulları, onlardır ki; yeryüzünde mütevazi olarak yürürler. Bilgisizler kendilerine takıldıkları zaman, selam, derler."},{"n":64,"t":"Onlar ki; Rabbları için secdeye vararak ve kıyama durarak gecelerler."},{"n":65,"t":"Ve onlar ki: Rabbımız, bizden cehennem azabını uzaklaştır. Doğrusu cehennem in azabı sürekli ve acıdır, derler."},{"n":66,"t":"Muhakkak ki o, ne kötü bir karargah ve konaklama yeridir."},{"n":67,"t":"Onlar ki; infak ettikleri zaman, ne israf ederler, ne de cimrilik. İkisi arasında orta bir yol tutarlar."},{"n":68,"t":"Onlar ki; Allah ile beraber başka bir tanrıya tapmazlar. Allah’ın haram kıldığı cana haksız yere kıymazlar. Zina etmezler. Kim de bunları yaparsa, cezaya çarpar."},{"n":69,"t":"Kıyamet günü azabı kat kat olur ve orada alçaltılarak temelli bırakılır."},{"n":70,"t":"Ancak tevbe eden, inanıp salih amel işleyenlerin; Allah, işte onların kötülüklerini iyiliklere çevirir. Ve Allah; Gafur ve Rahim olandır."},{"n":71,"t":"Kim de tevbe edip salih amel işlerse; şüphesiz ki o, Allah’a tevbesi kabul edilmiş olarak döner."},{"n":72,"t":"Onlar ki; yalan yere şehadet etmezler. Boş ve kötü lakırdıya rastladıkları zaman, yüz çevirip vakarla geçerler."},{"n":73,"t":"Onlar ki; kendilerine Rabblarının ayetleri hatırlatıldığı vakit, onlara karşı kör ve sağır davranmazlar."},{"n":74,"t":"Onlar ki; Rabbımız, eşlerimiz ve çocuklarımız hususunda gözümüzü aydın kıl, bizi müttakilere imam yap, derler."},{"n":75,"t":"İşte onlar, sabrettiklerinden dolayı cennetin en yüksek dereceleri ile mükafatlandırılırlar ve orada sağlık ve selamla karşılanırlar."},{"n":76,"t":"Orada temelli kalırlar. Orası ne güzel bir yer ve ne güzel bir duraktır."},{"n":77,"t":"De ki: Duanız olmasaydı, Rabbım size değer verir miydi? Gerçekten yalanladınız. O halde azab yakanızı bırakmayacaktır."}],[{"n":1,"t":"Ta, Sin, Mim."},{"n":2,"t":"Bunlar apaçık kitabın ayetleridir."},{"n":3,"t":"Mü’min olmuyorlar diye nerede ise kendini mahvedeceksin."},{"n":4,"t":"Dilersek, onlara gökten bir ayet indiririz de ona boyunları eğik kalır."},{"n":5,"t":"Onlara Rahman’dan bir öğüt geldiğinde, mutlaka ondan yüz çevirirler."},{"n":6,"t":"Onlar, gerçekten yalanladılar. Ama alay edip durdukları şeylerin haberleri kendilerine yakında gelecektir."},{"n":7,"t":"Yeryüzüne bakmazlar mı ki; Biz, orada bitkilerden nice güzel çiftler bitirmişizdir."},{"n":8,"t":"Muhakkak ki bunda, bir ayet vardır. Ama onların çoğu mü’min olmadılar."},{"n":9,"t":"Ve muhakkak ki senin Rabbın, elbette O; Aziz’dir, Rahim’dir."},{"n":10,"t":"Hani Rabbın Musa’ya seslenmişti ki: Zalimler güruhuna git;"},{"n":11,"t":"Firavun kavmine. Sakınmazlar mı hala?"},{"n":12,"t":"Dedi ki: Rabbım, onların beni yalanlamalarından korkarım."},{"n":13,"t":"Göğsüm daralıyor, dilim açılmıyor. Bunun için Harun’a da elçilik ver."},{"n":14,"t":"Hem onların bana isnad ettikleri bir suç var. Korkarım ki beni öldürürler"},{"n":15,"t":"Buyurdu ki: Hayır, ikiniz ayetlerimizle gidin. Muhakkak Biz, sizinle beraber dinleyicilerdeniz."},{"n":16,"t":"Firavun’a varın, deyin ki: Biz, alemlerin Rabbının peygamberleriyiz."},{"n":17,"t":"İsrailoğullarını bizimle beraber gönder."},{"n":18,"t":"Dedi ki: Çocukken biz, seni yanımıza alıp büyütmedik mi? Ve sen, hayatının bir çok yılllarını aramızda geçirdin."},{"n":19,"t":"Ve yapacağın işi de yaptın. Sen nankörlerdensin."},{"n":20,"t":"Dedi ki: Ben, onu yaptım, ama o zaman şaşkınlardandım."},{"n":21,"t":"Bu yüzden sizden korktuğum için kaçtım. Sonra Rabbım bana hüküm ihsan etti ve beni peygamberlerden kıldı."},{"n":22,"t":"İşte, başıma kaktığın o nimet, İsrailoğullarını köle ettiğin içindir."},{"n":23,"t":"Firavun: Alemlerin Rabbı da nedir? dedi."},{"n":24,"t":"Dedi ki: Göklerin, yerin ve ikisinin arasında bulunanların Rabbıdır. Eğer siz yakin getirenlerden iseniz."},{"n":25,"t":"Yanında bulunanlara: İşitmiyor musunuz? dedi."},{"n":26,"t":"O da: Sizin de Rabbınız ve önce geçmiş atalarınızın da Rabbıdır, dedi."},{"n":27,"t":"Firavun dedi ki: Size gönderilen peygamberiniz şüphesiz delidir."},{"n":28,"t":"O da: Eğer aklınızı başınıza alırsanız; doğunun, batının ve ikisinin arasında bulunanların Rabbıdır, dedi."},{"n":29,"t":"Firavun dedi ki: Benden başka bir tanrı edinirsen; şüphesiz seni hapse atılanlardan kılarım."},{"n":30,"t":"Sana apaçık bir şeyle gelmişsem de mi? dedi."},{"n":31,"t":"Firavun: Eğer doğru söylüyorsan, haydi getir onu, dedi."},{"n":32,"t":"Bunun üzerine o asasını attı, bir de ne görsün; apaçık bir ejderhadır."},{"n":33,"t":"Elini çıkardı, bir de ne görsün; bakanlara bembeyazdır."},{"n":34,"t":"Çevresinde bulunan ileri gelenlere dedi ki: Şüphesiz bu, belletilmiş bir büyücüdür."},{"n":35,"t":"Sizi büyüsüyle memleketinizden çıkarmak istiyor. Ne dersiniz?"},{"n":36,"t":"Dediler ki: Onu ve kardeşini alıkoy. Şehirlere toplayıcılar gönder."},{"n":37,"t":"Belletilmiş tüm büyücüleri sana getirsinler."},{"n":38,"t":"Büyücüler belli bir günün tayin edilen vaktinde toplandılar."},{"n":39,"t":"İnsanlara: Siz de toplanır mısınız? denildi."},{"n":40,"t":"Eğer onlar galip gelirlerse; büyücülere belki biz de tabi oluruz."},{"n":41,"t":"Büyücüler geldikleri vakit, Firavun’a dediler ki: Galip gelenler biz olursak; muhakkak bize bir ücret vardır değil mi?"},{"n":42,"t":"Evet, dedi. O takdirde siz, muhakkak gözdelerdensiniz."},{"n":43,"t":"Musa onlara dedi ki: Atacak olduğunuz şeyleri atın."},{"n":44,"t":"Onlar da bunun üzerine iplerini ve değneklerini attılar ve dediler ki: Firavun hakkı için elbette elbette biz galib gelenleriz."},{"n":45,"t":"Ardından Musa asasını attı. Bir de ne görsünler; onların uydurduklarını yutuveriyor."},{"n":46,"t":"Bunun üzerine büyücüler secdeye kapandılar."},{"n":47,"t":"Dediler ki: Biz, alemlerin Rabbına inandık."},{"n":48,"t":"Musa ve Harun’un Rabbına."},{"n":49,"t":"Ben size izin vermezden önce mi ona inandınız? Şüphesiz size büyü öğreten büyüğünüzdür. Şimdi bileceksiniz; elbette ben, ellerinizi ve ayaklarınızı andolsun ki çaprazlama kestireceğim ve hepinizi astıracağım, dedi."},{"n":50,"t":"Onlar da dediler ki: Zararı yok. Biz muhakkak Rabbımıza dönenleriz."},{"n":51,"t":"Mü’minlerin ilki olmamızdan dolayı biz, gerçekten Rabbımızın hatalarımızı bağışlayacağını umarız."},{"n":52,"t":"Musa’ya da vahyetti ki: Kullarımı geceleyin yola çıkar. Şüphesiz siz, izleneceksiniz."},{"n":53,"t":"Bunun üzerine Firavun şehirlere toplayıcılar gönderdi."},{"n":54,"t":"Şüphesiz ki bunlar; döküntü azınlıklarıdır."},{"n":55,"t":"Ve gerçekten bize de büyük bir öfke beslemektedirler."},{"n":56,"t":"Doğrusu biz, topluca tedbirli olmalıyız."},{"n":57,"t":"Fakat Biz, onları bahçelerden ve pınar başlarından çıkardık."},{"n":58,"t":"Hazinelerden ve şerefli makamlardan."},{"n":59,"t":"Böylece onlara İsrailoğullarını mirasçı kıldık."},{"n":60,"t":"Güneş üzerlerine doğarken onları izlediler."},{"n":61,"t":"İki topluluk karşı karşıya geldiğinde, Musa’nın arkadaşları dediler ki: Gerçekten biz, yakalandık."},{"n":62,"t":"Hayır, dedi. Muhakkak ki Rabbım benimledir. Bana doğru yolu gösterecektir."},{"n":63,"t":"Bunun üzerine Musa’ya vahyettik ki: Asanı denize vur. O, hemen yarıldı ve her parçası yüce bir dağ gibi oldu."},{"n":64,"t":"Sonra diğerlerini oraya yaklaştırdık."},{"n":65,"t":"Musa’yı ve beraberindekileri yopluca kurtardık."},{"n":66,"t":"Sonra diğerlerini suda boğduk."},{"n":67,"t":"Şüphesiz ki bunda, bir ayet vardır. Ama onların çoğu inananlar değildi."},{"n":68,"t":"Muhakkak ki Rabbın, elbette o; Aziz’dir, Rahim’dir."},{"n":69,"t":"Onlara İbrahim’in haberini oku."},{"n":70,"t":"Hani babasına ve kavmine: Nelere tapıyorsunuz? demişti."},{"n":71,"t":"Onlar da: Putlara tapıyoruz ve onlara bağlanıp duruyoruz, demişlerdi."},{"n":72,"t":"O da demişti ki: Çağırdığınızda sizi duyuyorlar mı?"},{"n":73,"t":"Yahut size fayda veya zarar veriyorlar mı?"},{"n":74,"t":"Demişlerdi ki: Hayır. Atalarımızı böyle yapar gördük."},{"n":75,"t":"O da demişti ki: Neye tapmış olduğunuzu görüyor musunuz?"},{"n":76,"t":"Siz ve geçmiş atalarınız?"},{"n":77,"t":"Doğrusu onlar, benim düşmanımdır. Ancak alemlerin Rabbı müstesna."},{"n":78,"t":"Ki O, yaratmıştır beni. Ve O doğru yola eriştirir beni."},{"n":79,"t":"Ki O, yedirir, içirir beni."},{"n":80,"t":"Hastalandığımda O, şifa verir bana."},{"n":81,"t":"Ki O, öldürür beni, sonra da O, diriltir."},{"n":82,"t":"Ve din günü günahlarımı bağışlamasını umduğum O’dur."},{"n":83,"t":"Rabbım, bana hüküm ver. Ve beni salihlere kat."},{"n":84,"t":"Ve sonrakiler içinde bana doğru söyler bir dil ihsan et."},{"n":85,"t":"Beni Naim cennetinin varislerinden kıl."},{"n":86,"t":"Babamı da bağışla. Şüphesiz o, sapıklardan olmuştur."},{"n":87,"t":"Diriltilecekleri günde beni rezil etme."},{"n":88,"t":"O gün ki mal da fayda vermez, çocuklar da."},{"n":89,"t":"Ancak Allah’a kalb-i selimle gelmiş olan başka."},{"n":90,"t":"Cennet, muttakiler için hazırlanmıştır."},{"n":91,"t":"Cehennem de azgınlara gösterilir."},{"n":92,"t":"Ve onlara denilir ki: Nerededir taptıklarınız?"},{"n":93,"t":"Allah’tan başka? Size yardım ediyorlar mı veya kendilerine yardımları dokunuyor mu?"},{"n":94,"t":"Oraya; onlar ve azgınlar atılırlar."},{"n":95,"t":"İblis’in askerleri de topluca."},{"n":96,"t":"Orada birbirleriyle çekişerek derler ki:"},{"n":97,"t":"Andolsun Allah’a ki; biz, apaçık sapıklıkta idik."},{"n":98,"t":"Hani biz, sizi alemlerin Rabbı ile bir tutmuştuk."},{"n":99,"t":"Ve bizi suçlulardan başka da saptıran olmamıştı."},{"n":100,"t":"Şimdi bize şefaat eden kimse yoktur."},{"n":101,"t":"Ve sıcak bir dostumuz da yoktur."},{"n":102,"t":"Keşki bizim için geri dönüş olsa da, mü’minlerden olsak."},{"n":103,"t":"Muhakkak ki bunda bir ayet vardır. Ama onların çoğu mü’minler olmadı."},{"n":104,"t":"Muhakkak ki Rabbın, elbette o; Aziz’dir, Rahim’dir."},{"n":105,"t":"Nuh’un kavmi de peygamberleri yalanladı."},{"n":106,"t":"Hani onlara kardeşleri Nuh demişti ki: Siz sakınmaz mısınız?"},{"n":107,"t":"Muhakkak ki ben, size emin bir peygamberim."},{"n":108,"t":"Artık Allah’tan korkun da bana itaat edin."},{"n":109,"t":"Buna karşı sizden bir ücret istemiyorum. Benim ücretim ancak alemlerin Rabbına aittir."},{"n":110,"t":"O halde Allah’tan korkun da bana itaat edin."},{"n":111,"t":"Sana mı inanacağız? Halbuki sana uyanlar en rezil kimselerdir, dediler."},{"n":112,"t":"Dedi ki: Onların yapmakta oldukları şeyler hakkında bir bilgim yoktur."},{"n":113,"t":"Onların hesabı ancak Rabbıma aittir. Keşki düşünseniz."},{"n":114,"t":"Ve ben, inananları kovacak değilim."},{"n":115,"t":"Ben, ancak apaçık bir uyarıcıyım."},{"n":116,"t":"Ey Nuh, eğer son vermezsen, sen muhakkak taşlananlardan olursun, dediler"},{"n":117,"t":"O da dedi ki: Rabbım, doğrusu kavmim beni yalanladı."},{"n":118,"t":"Artık benimle onların arasında Sen, bir hüküm ver. Beni ve beraberimdeki mü’minleri kurtar."},{"n":119,"t":"Bunun üzerine Biz de, onu ve beraberindekileri, dolu bir gemi içinde kurtardık."},{"n":120,"t":"Sonra geride kalanları suda boğduk."},{"n":121,"t":"Muhakkak ki bunda, bir ayet vardır. Ama onların çoğu mü’minler olmadı."},{"n":122,"t":"Ve muhakkak ki Rabbın, elbette o; Aziz’dir, Rahim’dir."},{"n":123,"t":"Ad da peygamberleri yalanladı."},{"n":124,"t":"Hani onlara kardeşleri Hud demişti ki: Siz, sakınmaz mısınız?"},{"n":125,"t":"Muhakkak ki ben, size emin bir peygamberim."},{"n":126,"t":"Artık Allah’tan korkun da bana itaat edin."},{"n":127,"t":"Buna karşı sizden bir ücret istemiyorum. Benim ücretim ancak alemlerin Rabbına aittir."},{"n":128,"t":"Siz, her yüksek yere koca bir bina kurup boş şeylerle mi uğraşırsınız?"},{"n":129,"t":"Temelli kalacağınızı umarak sağlam yapılar mı edinirsiniz?"},{"n":130,"t":"Ve yakaladığınız zaman da zorbaca mı yakalarsınız?"},{"n":131,"t":"O halde Allah’tan korkun da bana itaat edin."},{"n":132,"t":"Bildiğiniz şeylerle sizi destekleyenden sakının."},{"n":133,"t":"O, desteklemiştir sizi, hayvanlar ve oğullarla;"},{"n":134,"t":"Bahçeler ve çeşmelerle."},{"n":135,"t":"Doğrusu hakkınızda büyük bir günün azabından korkuyorum."},{"n":136,"t":"Dediler ki: Öğüt versen de, yahut öğüt verenlerden olmasan da bizim için eşittir."},{"n":137,"t":"Bu, öncekilerin adetinden başka bir şey değildir."},{"n":138,"t":"Hem biz, azaba uğratılacak da değiliz."},{"n":139,"t":"Böylece onu yalanladılar. Ve Biz, onları yok ettik. Muhakkak ki bunda bir ayet vardır. Ama onların çoğu mü’minler olmadı."},{"n":140,"t":"Ve muhakkak ki Rabbın, elbette o; Aziz’dir, Rahim’dir."},{"n":141,"t":"Semud da peygamberleri yalanladı."},{"n":142,"t":"Hani onlara kardeşleri Salih demişti ki: Siz, sakınmaz mısınız?"},{"n":143,"t":"Muhakkak ki ben, size emin bir peygamberim."},{"n":144,"t":"Artık Allah’tan korkun da bana itaat edin."},{"n":145,"t":"Buna karşı sizden bir ücret istemiyorum. Benim ücretim, ancak alemlerin Rabbına aittir."},{"n":146,"t":"Burada emniyet içinde bırakılır mısınız?"},{"n":147,"t":"Bahçelerde, çeşmelerde."},{"n":148,"t":"Ekinler, salkımları sarkmış hurmalıklar arasında."},{"n":149,"t":"Dağlarda ustalıkla evler oyar mısınız?"},{"n":150,"t":"O halde Allah’tan korkun da bana itaat edin."},{"n":151,"t":"Müsriflerin emrine itaat etmeyin."},{"n":152,"t":"Onlar ki yeryüzünde bozgunculuk yaparlar da ıslah etmezler."},{"n":153,"t":"Dediler ki: Şüphesiz sen, ancak büyülenmişlerdensin."},{"n":154,"t":"Hem sen, bizim gibi insandan başka bir şey değilsin. Şayet sadıklardan isen o zaman bir ayet getir."},{"n":155,"t":"Dedi ki: İşte şu devedir. Su içme hakkı; belirli bir gün onun ve belirli bir gün sizindir."},{"n":156,"t":"Sakın ona bir kötülük yapmayın. Yoksa sizi büyük bir günün azabı yakalayıverir."},{"n":157,"t":"Onlar ise onu kestiler de pişman oldular."},{"n":158,"t":"Bunun üzerine azab onları yakaladı. Muhakkak ki bunda bir ayet vardır. Ama onların çoğu mü’minler olmadı."},{"n":159,"t":"Muhakkak ki Rabbın, elbette O; Aziz’dir, Rahim’dir."},{"n":160,"t":"Lut kavmi de peygamberleri yalanladı."},{"n":161,"t":"Hani onlara kardeşleri Lut demişti ki: Siz, sakınmaz mısınız?"},{"n":162,"t":"Muhakkak ki ben, size emin bir peygamberim."},{"n":163,"t":"Artık Allah’tan korkun da bana itaat edin."},{"n":164,"t":"Buna karşı sizden bir ücret istemiyorum. Benim ücretim, ancak alemlerin Rabbına aittir."},{"n":165,"t":"İnsanlar arasında erkeklere mi yaklaşıyorsunuz?"},{"n":166,"t":"Ve Rabbınızın sizin için yarattığı eşleri bırakıyor musunuz? Hayır, siz azmış bir kavimsiniz."},{"n":167,"t":"Dediler ki: Ey Lut, buna son vermezsen sen, elbette çıkarılanlardan olursun."},{"n":168,"t":"Dedi ki: Doğrusu ben, sizin işlediğinize kızanlardanım."},{"n":169,"t":"Rabbım, beni ve ailemi bunların yaptıklarından kurtar."},{"n":170,"t":"Bunun üzerine onu ve ailesini topluca kurtardık."},{"n":171,"t":"Sadece yaşlı bir kadın geride kalanlardan oldu."},{"n":172,"t":"Sonra diğerlerini yerle bir ettik."},{"n":173,"t":"Üzerlerine de bir yağmur yağdırdık. Uyarılanların yağmuru ne kötüdür."},{"n":174,"t":"Muhakkak ki bunda bir ayet vardır. Ama onların çoğu mü’minler olmadı."},{"n":175,"t":"Muhakkak ki Rabbın, elbette O; Aziz’dir, Rahim’dir."},{"n":176,"t":"Eyke halkı da peygamberleri yalanladı."},{"n":177,"t":"Hani onlara Şuayb demişti ki: Siz, sakınmaz mısınız?"},{"n":178,"t":"Muhakkak ki ben, size emin bir peygamberim."},{"n":179,"t":"Artık Allah’tan korkun da bana itaat edin."},{"n":180,"t":"Buna karşı sizden bir ücret istemiyorum. Benim ücretim, ancak alemlerin Rabbına aittir."},{"n":181,"t":"Ölçüyü tam yapın da eksiltenlerden olmayın."},{"n":182,"t":"Doğru ölçekle tartın."},{"n":183,"t":"İnsanların eşyasını azaltmayın ve yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın."},{"n":184,"t":"Sizi ve daha önceki nesilleri yaratmış olandan korkun."},{"n":185,"t":"Dediler ki: Sen, ancak büyülenmişlerdensin."},{"n":186,"t":"Bizim gibi bir insandan başka bir şey değilsin. Doğrusu biz, seni yalancılardan sanıyoruz."},{"n":187,"t":"Eğer sadıklardan isen bize, gökten bir parça indir."},{"n":188,"t":"Dedi ki: Rabbım; yaptıklarınızı en iyi bilendir."},{"n":189,"t":"Onu da yalanladılar ve onları bulutlu bir günün azabı yakaladı. Doğrusu o, büyük bir günün azabı idi."},{"n":190,"t":"Muhakkak ki bunda bir ayet vardır. Ama onların çoğu mü’minler olmadı."},{"n":191,"t":"Muhakkak ki Rabbın, elbette O; Aziz’dir, Rahim’dir."},{"n":192,"t":"Muhakkak ki o, elbette alemlerin Rabbının indirmesidir."},{"n":193,"t":"Onu Ruh el-Emin indirmiştir."},{"n":194,"t":"Senin kalbine ki uyarıcılardan olasın."},{"n":195,"t":"Apaçık arab diliyle."},{"n":196,"t":"O, daha öncekilerin kitablarında vardır."},{"n":197,"t":"İsrailoğullarının bilginlerinin bunu bilmesi de onlar için bir ayet değil midir?"},{"n":198,"t":"Biz, onu arapça bilmeyen kimselerden birine indirseydik."},{"n":199,"t":"Ve o, bunu onlara okusaydı, yine de ona inananlardan olmazlardı."},{"n":200,"t":"İşte böylece onu suçluların kalbine sokarız."},{"n":201,"t":"Elim azabı görünceye kadar ona inanmazlar."},{"n":202,"t":"O da kendilerine apansız, haberleri olmadan geliverir."},{"n":203,"t":"O zaman derler ki: Acaba bekletilemez miyiz?"},{"n":204,"t":"Bizim azabımızı mı çabucak istiyorlardı."},{"n":205,"t":"Gördün mü, şayet Biz onları yıllarca yararlandırsak;"},{"n":206,"t":"Sonra kendilerine vaadolunan şey başlarına gelse,"},{"n":207,"t":"Eğlendirilmiş olmaları onlara bir fayda sağlamaz."},{"n":208,"t":"Uyarıcılar olmaksızın Biz, hiç bir kasabayı helak etmedik."},{"n":209,"t":"Öğüt olarak. Ve Biz, zalimler olmadık"},{"n":210,"t":"Onu şeytanlar indirmemiştir."},{"n":211,"t":"Bu, onlara düşmez de, buna güçleri de yetmez."},{"n":212,"t":"Onlar, gerçekten işitmekten uzak tutuldular."},{"n":213,"t":"O halde Allah ile beraber başka bir tanrıya yalvarma. Yoksa azablandırılanlardan olursun."},{"n":214,"t":"Ve yakın akrabalarını uyar."},{"n":215,"t":"Mü’minlerden sana uyanlara kanatlarını ger."},{"n":216,"t":"Şayet sana isyan ederlerse, de ki: Ben sizin yaptıklarınızdan uzağım."},{"n":217,"t":"Aziz, Rahim’e tevekkül et."},{"n":218,"t":"Görür O seni, kalktığında."},{"n":219,"t":"Secde edenler arasında bulunduğunda."},{"n":220,"t":"Muhakkak ki O’dur O; Semi, Alim."},{"n":221,"t":"Şeytanların kime indiğini size bildireyim mi?"},{"n":222,"t":"Onlar her günahkar, her müfteriye inerler."},{"n":223,"t":"Bunlar ona kulak verirler ve çoğu yalancılardır."},{"n":224,"t":"Şairlere gelince; onlara da azgınlar uyar."},{"n":225,"t":"Görmedin mi; onlar, her vadide şaşkın şaşkın dolaşırlar."},{"n":226,"t":"Ve onlar, gerçekten yapmadıklarını söylerler."},{"n":227,"t":"Ancak iman etmiş, salih amel işlemiş, Allah’ı çokça zikretmiş ve zulme uğratıldıktan sonra zafer kazananlar müstesnadır. Zulmedenler göreceklerdir nasıl bir yıkılışla yıkılacaklarını."}],[{"n":1,"t":"Ta, Sin. Bunlar; Kur’an’ın ve apaçık kitabın ayetleridir"},{"n":2,"t":"Mü’minlere doğruluk rehberi ve müjdedir."},{"n":3,"t":"Onlar ki; namazı kılarlar, zekatı verirler ve ahirete de yakınen inanırlar."},{"n":4,"t":"Ahirete inanmayanlara gelince; muhakkak ki onlara, yaptıklarını güzel göstermişizdir. Bu yüzden şaşırıp kalmaktadırlar."},{"n":5,"t":"Bunlar öyle kimselerdir ki; kötü azap onlarındır. Ve onlar; ahirette de en çok hüsrana uğrayanların kendileridir."},{"n":6,"t":"Muhakkak ki sen; Kur’an’ı Alim ve Hakim katından almaktasın."},{"n":7,"t":"Hani Musa, ailesine demişti ki: Ben bir ateş gördüm. Size oradan; ya bir haber getireceğim, yahut da ısınasınız diye yanan bir ateş koru getireceğim."},{"n":8,"t":"Oraya geldiği vakit, kendisine şöyle seslenildi: Ateşin yanında olan ve çevresinde bulunanlar mübarek kılınmıştır. Alemlerin Rabbı olan Allah, münezzehtir."},{"n":9,"t":"Ey Musa; gerçek şu ki, Ben Hakim ve Aziz olan Allah’ım."},{"n":10,"t":"Değneğini at. Onun yılan gibi hareketler yaptığını görünce, arkasına bakmadan dönüp kaçtı ve geri dönmedi. Ey Musa; korkma. Benim katımda muhakkak ki peygamberler korkmazlar."},{"n":11,"t":"Yalnız zulmeden bunun dışındadır. Sonra kötülüğün ardından iyiliğe çevirirse artık Ben, şüphesiz Gafur ve Rahim’im."},{"n":12,"t":"Ve elini koynuna sok. Firavun ve kavmine gönderilen dokuz mucizeden biri olarak kusursuz, bembeyaz çıksın. Şüphesiz ki onlar; fasık bir kavim idiler."},{"n":13,"t":"Ayetlerimiz böyle vazıh olarak onlara gelince; bu, apaçık bir büyüdür, dediler."},{"n":14,"t":"Gönülleri kesin olarak kabul ettiği halde, zulüm ve kibirle bunları bile bile inkar ettiler. Bozguncuların sonunun nasıl olduğuna bir bak."},{"n":15,"t":"Andolsun ki; Biz, Davud’a ve Süleyman’a iıim verdik. İkisi de: Bizi mü’min kullarının çoğundan üstün kılan Allah’a hamdolsun, dediler."},{"n":16,"t":"Süleyman da Davud’a varis oldu ve dedi ki: Ey insanlar; bize, kuş dili öğretildi. Ve bize, her şeyden bolca verildi. Doğrusu bu; apaçık bir lutuftur."},{"n":17,"t":"Süleyman’ın cinnlerden, insanlardan, kuşlardan orduları toplandı. Hepsi topluca gidiyorlardı."},{"n":18,"t":"Nihayet karıncaların bulunduğu vadiye geldiklerinde bir karınca dedi ki: Ey karıncalar, yuvalarınıza girin. Süleyman ve orduları farkına varmadan sakın sizi ezmesin."},{"n":19,"t":"Onun bu sözü üzerine gülerek tebessüm etti ve dedi ki: Rabbım; bana ve ana babama verdiğin nimete şükürde ve hoşnud olacağın şeyi yapmakta beni muvaffak kıl ve rahmetinle beni salih kullarının arasına kat."},{"n":20,"t":"Kuşları araştırarak dedi ki: Hüdhüd’ü niçin göremiyorum? Yoksa kayıplardan mı oldu?"},{"n":21,"t":"Ya bana apaçık bir burhan getirecektir, ya da onu şiddetli bir azaba uğratırım veya keserim."},{"n":22,"t":"Çok geçmeden o geldi ve dedi ki: Senin bilmediğin bir şeyi öğrendim ve sana Sebe’den gerçek bir haber getirdim."},{"n":23,"t":"Ora halkına hükmeden, her şeyden kendisine bolca verilmiş olan ve büyük bir tahta sahip bir kadın buldum."},{"n":24,"t":"Onun ve kavminin, Allah’ı bırakıp güneşe secde eder olduklarını gördüm. Şeytan onların yaptıklarını güzel göstermiş ve onları doğru yoldan alıkoymuştur. Bu yüzden onlar doğru yolu bulamazlar."},{"n":25,"t":"Göklerde ve yerde gizli olanları ortaya koyan, gizlediğinizi ve açıkladığınızı bilen Allah’a secde etmesinler diye."},{"n":26,"t":"Allah O’dur ki; O’ndan başka ilah yoktur. Yüce Arş’ın sahibi ancak ve ancak O’dur."},{"n":27,"t":"Dedi ki: Bakalım, doğru mu söyledin, yoksa yalancılardan mı oldun?"},{"n":28,"t":"Şu yazımı götür, kendilerine bırak. Sonra bir yana çekil, bak; neye dönecekler."},{"n":29,"t":"Dedi ki: Ey ileri gelenler; gerçekten bana çok şerefli bir mektup bırakıldı."},{"n":30,"t":"Gerçekten o; Süleyman’dandır ve gerçekten o; Rahman, Rahim olan Allah’ın adıyladır."},{"n":31,"t":"Bana karşı başkaldırmayasınız ve müslüman olarak gelesiniz diye."},{"n":32,"t":"Dedi ki: Ey ileri gelenler, vereceğim emir hakkında bana görüşünüzü söyleyin. Siz, benim yanımda bulunmadıkça bir iş hakkında kesin bir hüküm veremem."},{"n":33,"t":"Dediler ki: Biz, güçlü kimseler ve zorlu savaş adamlarıyız. Emirse senindir, sen emretmene bak."},{"n":34,"t":"Dedi ki: Doğrusu hükümdarlar, bir şehre girdikleri zaman, orasını perişan ederler. Halkından şerefli olanlarını aşağılık yaparlar ve işte böyle davranırlar."},{"n":35,"t":"Ben, onlara bir hediyye göndereyim de elçilerin ne ile döneceklerine bakayım."},{"n":36,"t":"Süleyman’a geldiklerinde dedi ki: Bana mal ile mi yardım etmek istiyorsunuz? Halbuki Allah’ın bana verdiği, size verdiğinden daha hayırlıdır. Belki siz, hediyyenizle sevinirsiniz."},{"n":37,"t":"Geri rötür onlara. Andolsun ki; güç yetiremeyecekleri bir ordu ile gelir onları oradan alçalmış ve küçük düşmüş olarak çıkartırım."},{"n":38,"t":"Dedi ki: Ey ileri gelenler; kendileri bana müslüman olarak gelmeden önce hanginiz onun tahtını bana getirebilir?"},{"n":39,"t":"Cinnlerden bir ifrit dedi ki: Sen; yerinden kalkmadan, onu sana getiririm, eminim ki buna gücüm yeter."},{"n":40,"t":"Nezdinde kitabdan bir bilgi bulunan da dedi ki: Gözünü açıp kapamadan ben, onu sana getiririm. Süleyman tahtı yanına yerleşivermiş görünce dedi ki: Bu, Rabbımın lutfundandır. Şükür mü yoksa küfür mü edeceğim diye beni sınamak içindir. Kim şükrederse; ancak kendisi için şükretmiş olur. Kim de küfrederse; muhakkak ki Rabbım; Gani’dir, Kerim’dir."},{"n":41,"t":"Dedi ki: Onun tahtını değişikliğe uğratın, bir bakalım hidayeti bulabilecek mi, yoksa bulamayanlardan mı olacak?"},{"n":42,"t":"Böylece geldiğinde: Senin tahtın böyle miydi? denildi. O da: Sanki bu, odur. Ondan önce de bize bilgi verilmişti ve biz müslüman olmuştuk, dedi"},{"n":43,"t":"Onun Allah’ı bırakıp da tapmaya devam ettiği şey, kendisine mani olmuştu. Ve gerçekten o, küfreden bir kavimdendi."},{"n":44,"t":"Ona: Köşke gir, dendi. Onu görünce; derin bir su sandı ve iki ayağını açtı. Doğrusu bu, camdan yapılmış düzeltilmiş mücella bir açıklıktır, dedi. O: Rabbım; şüphesiz ben, kendime zulmetmişim. Süleyman’la beraber alemlerin Rabbı olan Allah’a teslim oldum, dedi."},{"n":45,"t":"Andolsun ki; Semud’a da kardeşleri Salih’i; Allah’a ibadet edin, diye gönderdik. Hemen birbirleriyle çekişen iki grup oluverdiler."},{"n":46,"t":"Salih dedi ki: Ey kavmim; niçin iyilikten önce çarçabuk kötülük istiyorsunuz? Merhamet olunmanız için Allah’tan mağfiret dileseniz olmaz mı?"},{"n":47,"t":"Dediler ki: Senin ve beraberindekilerin yüzünden uğursuzluğa uğradık: O da: Uğursuzluğunuz Allah katındandır. Belki siz, imtihana çekilen bir kavimsiniz, dedi."},{"n":48,"t":"Şehirde dokuz kişi vardı ki; yeryüzünde bozgunculuk yapıyor ve ıslah etmiyorlardı."},{"n":49,"t":"Aralarında Allah’a yemin ederek: Gece, biz ona ve ailesine baskın verelim. Sonra da onun dostuna; ailesinin yok edilişinde bulunmadığımızı şüphesiz doğru söylediğimizi bildirelim, dediler."},{"n":50,"t":"Onlar bir düzen kurdular. Onlar farketmezlerken Biz de bir düzen kurduk."},{"n":51,"t":"Düzenlerinin sonunun nice olduğuna bir bak. Biz; onları ve kavimlerini toptan yerle bir ettik."},{"n":52,"t":"İşte zulmetmelerinden dolayı çökmüş, ıpıssız kalmış evleri. Muhakkak ki bunda; bilen bir kavim için ayet vardır."},{"n":53,"t":"İman edip takva sahibi olanları da kurtardık."},{"n":54,"t":"Lut’u da. Hani kavmine demişti ki: Göz göre göre bir hayasızlık mı yapıyorsunuz?"},{"n":55,"t":"Kadınları bırakıp şehvetle erkeklere mi yaklaşıyorsunuz? Hayır siz, cahil bir kavimsiniz."},{"n":56,"t":"Kavminin cevabı: Lut’un ailesini kasabanızdan çıkarın. Çünkü onlar, temiz kalmaya çalışan insanlardır, demekten başka bir şey olmadı."},{"n":57,"t":"Bunun üzerine onu ve ailesini kurtardık. Yalnız karısının geride kalanlardan olmasını takdir ettik."},{"n":58,"t":"Onların üzerine bir yağmur yağdırdık. Ne kötü idi uyarılanların yağmuru."},{"n":59,"t":"De ki: Hamdolsun Allah’a, selam olsun O’nun beğenip seçtiği kullarına. Allah mı daha iyidir, yoksa O’na koştukları ortaklar mı?"},{"n":60,"t":"Yoksa gökleri ve yeri yaratan, gökten size su indirip onunla bir ağacını dahi bitiremeyeceğiniz nice güzel bahçeler meydana getiren mi? Allah yanında başka bir ilah mı? Hayır, onlar sapıklıkta ısrar eden bir güruhtur."},{"n":61,"t":"Yoksa, yeri yaratıklarının oturmasına elverişli kılan ve aralarında ırmaklar akıtan, yeryüzüne sabit dağlar yerleştiren ve iki denizin arasına engel koyan mı? Allah’ın yanında başka bir ilah mı? Hayır, onların çoğu bilmezler."},{"n":62,"t":"Yoksa, kendisine yakardığı zaman bunalmışa karşılık veren ve başındaki sıkıntıyı gideren; sizi yeryüzünün halifeleri kılan mı? Allah’ın yanında başka bir ilah mı? Ne de kıt düşünüyorsunuz."},{"n":63,"t":"Yoksa, karanın ve denizin karanlıklarında size yol bolduran ve rahmetinin önünde rüzgarları müjdeci olarak gönderen mi? Allah’ın yanında başka bir ilah mı? Allah; onların koştukları ortaklardan münezzehtir."},{"n":64,"t":"Yoksa, önce yaratan, sonra da onu iade edecek olan ve sizi gökten ve yerden rızıklandıran mı? Allah’ın yanında başka bir ilah mı? De ki: Şayet doğru sözlü iseniz, delilinizi getirin."},{"n":65,"t":"De ki: Göklerde ve yerde gaybı Allah’tan başka kimse bilmez. Ne zaman diriltileceklerini de farketmezler."},{"n":66,"t":"Hayır, ahiret ile ilgili bilgileri de yetersizdir. Hayır, ondan şüphe etmektedirler. Hayır, ona karşı kördürler."},{"n":67,"t":"Küfredenler dediler ki: Biz ve babalarımız birer toprak olduktan sonra mı, doğrusu biz tekrar mı çıkarılacağız?"},{"n":68,"t":"Andolsun ki; bununla biz ve daha önce babalarımız tehdid edilmişlerdi. Bu, öncekilerin masallarından başka bir şey değildir."},{"n":69,"t":"De ki: Yeryüzünde gezinin de suçluların sonunun nasıl olduğunu görün."},{"n":70,"t":"Üzülme onlara. Düzenlerinden dolayı da sıkılma."},{"n":71,"t":"Onlar: Doğru söylüyorsanız; bu sözünüzün ne zaman yerine geleceğini bildirin, derler."},{"n":72,"t":"De ki: Çabucak istemekte olduğunuzun bir kısmı ensenize inmek üzeredir."},{"n":73,"t":"Muhakkak ki Rabbın; insanlara karşı lutuf sahibidir. Ama onların çoğu şükretmezler."},{"n":74,"t":"Şüphesiz ki Rabbın; onların göğüslerinin gizlediklerini de, açığa vurduklarını da bilir."},{"n":75,"t":"Gökte ve yerde gizli hiçbir şey yoktur ki apaçık bir kitabta olmasın."},{"n":76,"t":"Gerçekten bu Kur’an; İsrailoğullarına ayrılığa düştükleri şeyin çoğunu açıklamaktadır."},{"n":77,"t":"Gerçekten o; mutlak bir hidayettir ve mü’minler için de bir rahmettir."},{"n":78,"t":"Muhakkak ki RAbbın; onların arasında hükmünü verecektir. Ve O; Aziz’dir, Alim’dir."},{"n":79,"t":"Öyleyse sen; Allah’a tevekkül et. Şüphesiz ki sen; apaçık bir hak üzerindesin."},{"n":80,"t":"Elbette sen; ölülere işittiremezsin, dönüp giden sağırlara da çağrıyı duyuramazsın."},{"n":81,"t":"Körleri sapıklıklarından vazgeçirip hidayete erdirecek değilsin Sen; ancak ayetlerimize inananlara duyurabilirsin. Ve onlar müslümanlardır."},{"n":82,"t":"Kendilerine söylenmiş olan, başlarına geldiği zaman; yerden bir canlı çıkarılır ki insanların ayetlerimize kesin olarak inanmadıklarını söyleyerek konuşur."},{"n":83,"t":"Her ümmetten, ayetlerimizi yalanlayanları toplayacağımız gün; onlar, bir arada tutulurlar."},{"n":84,"t":"Nihayet geldikleri zaman; buyurur ki: Siz, Benim ayetlerimi anlamadığınız halde mi yalanladınız? Yoksa yaptığınız ne idi."},{"n":85,"t":"Zulümleri yüzünden, söylenilen söz başlarına geldi. Artık konuşamaz olurlar."},{"n":86,"t":"Görmediler mi ki; Biz, dinlenesiniz diye size geceyi karanlık, çalışasınız diye de gündüzü aydınlık olarak yarattık. Doğrusu bunda inanan bir kavim için ayetler vardır."},{"n":87,"t":"Sur’a üfürüleceği gün; Allah’ın dilediklerinden başka göklerde olanlar da, yerde olanlar da korku içinde kalırlar. Ve hepsi boyunları bükülmüş olarak O’na gelirler."},{"n":88,"t":"Sen; dağları görür ve yerinde durur sanırsın. Oysa onlar, bulut geçer gibi geçip giderler. Bu; her şeyi sapasağlam yapan Allah’ın san’atıdır. Muhakkak ki O; yaptıklarınızdan haberdardır."},{"n":89,"t":"Kim, bir iyilikle gelirse; ona daha iyisi vardır. Onlar, o günün korkusundan emindirler."},{"n":90,"t":"Kim de bir kötülükle gelirse; yüzleri ateşte sürtülür. Ya siz, yaptıklarınızdan başka bir şeyle mi cezalandırılacaksınız?"},{"n":91,"t":"Ben; ancak bu şehrin Rabbına kulluk etmekle emrolundum. O, burayı harem kılmıştır ve her şey O’nundur. Ben, müslümanlardan olmakla emrolundum."},{"n":92,"t":"Ve Kur’an okumakla da. Kim hidayete ererse; yalnız kendisi için ermiş olur. Kim de sapıtırsa; de ki: Ben, sadece uyaranlardanım."},{"n":93,"t":"De ki: Hamdolsun Allah’a. O, size ayetlerini gösterecektir. Siz de onları tanıyacaksınız. Ve Rabbın; yaptıklarınızdan habersiz değildir."}],[{"n":1,"t":"Ta, Sin, Mim."},{"n":2,"t":"Bunlar, apaçık Kitab’ın ayetleridir."},{"n":3,"t":"Sana, Musa ile Firavun’un haberinden inanacak bir kavim için doğru olarak anlatacağız."},{"n":4,"t":"Gerçekten, Firavun, yeryüzünde zorbalığa yöneldi ve halkını sınıflara ayırdı. İçlerinden bir zümreyi güçsüz bularak oğullarını boğazlıyor, kızlarını diri bırakıyordu. Çünkü o, bozgunculardandı."},{"n":5,"t":"Biz ise istiyorduk ki; güçsüz sayılanlara iyilikte bulunalım, onları önderler kılalım ve onları varisler yapalım."},{"n":6,"t":"Ve onları memleketlerine yerleştirelim, Firavun’ a Haman’a ve ikisinin askerlerine çekinmekte oldukları şeyleri gösterelim."},{"n":7,"t":"Musa’nın annesine: Onu emzir. Başına bir şey gelmesinden korktuğun zaman onu suya bırak. Korkma, üzülme, şüphesiz onu, Biz; sana döndürecek ve peygamber yapacağız, diye vahyettik."},{"n":8,"t":"Firavun’un adamları bunun üzerine onu aldılar. Çünkü o, sonunda kendileri için bir düşman ve bir tasa olacaktı. Zira Firavun, Haman ve askerleri gerçekten suçlu idiler."},{"n":9,"t":"Firavun’un karısı dedi ki: Benim de, senin de gözün aydın olsun. Onu öldürmeyin. Belki bize faydası dokunur veya onu oğul ediniriz. Ve onlar, farkında değillerdi."},{"n":10,"t":"Musa’nın annesi, yüreği bomboş sabah etti. Şayet inananlardan olması için kalbini pekiştirmemiş olsaydık; neredeyse onu açığa vuracaktı."},{"n":11,"t":"Onun kızkardeşine dedi ki: Onu izle, o da kimse farkına varmadan onu uzaktan gözetledi."},{"n":12,"t":"Önceden Biz, onun süt annelerin memesini kabul etmemesini sağladık. Bunun üzerine hemşiresi: Size, sizin adınıza ona bakacak ve iyi davranacak bir ev halkını tavsiye edeyim mi? dedi."},{"n":13,"t":"Böylece onun gözü aydın olsun, tasalanmasın ve Allah’ın vaadinin mutlak gerçek olduğunu bilsin diye, annesine geri verdik. Ama onların çoğu bilmezler."},{"n":14,"t":"Erginlik çağına erişip olgunlaşınca, Biz ona ilim ve hikmet verdik. İyi davrananları işte böylece mükafatlandırırız."},{"n":15,"t":"O, halkının haberi olmadığı bir sırada şehre girdi ve birbiriyle dövüşen iki adam gördü. Şu, kendi adamlarından, bu da düşmanlarındandı. Kendi tarafından olan, düşmanına karşı ondan yardım istedi. Bunun üzerine Musa düşmanına bir yumruk indirdi ve ölümüne sebep oldu. Bu, şeytanın işidir. Zira o, apaçık saptıran bir düşmandır, dedi."},{"n":16,"t":"Dedi ki: Rabbım; doğrusu kendime zulmettim. Bağışla beni. Bunun üzerine onu bağışladık. Muhakkak ki O’dur O; Gafur, Rahim."},{"n":17,"t":"Dedi ki: Rabbım, bana verdiğin nimet hakkı için, artık suçlulara asla yardımcı olmayacağım."},{"n":18,"t":"Şehirde korku içinde etrafı gözetleyerek sabahladı. Bir de baktı ki dün, kendisinden yardım isteyen kimse bağırarak ondan yine yardım istiyordu. Musa ona dedi ki: Doğrusu sen, besbelli bir azgınsın."},{"n":19,"t":"Derken ikisinin de düşmanı olanı yakalamak isteyince: Ey Musa, dün bir cana kıydığın gibi bana da mı kıymak istiyorsun? Sen ıslah edenlerden olmayı değil, yeryüzünde bir zorba olmayı istiyorsun, dedi."},{"n":20,"t":"Şehrin öte başından koşarak bir adam geldi ve dedi ki: Ey Musa; ileri gelenler, seni öldürmek için aralarında görüşüyorlar. Hemen çık git, doğrusu ben, sana öğüt verenlerdenim."},{"n":21,"t":"Bunun üzerine korku içinde gözetleyerek oradan çıktı ve: Rabbım; beni, o zalimler güruhundan kurtar, dedi."},{"n":22,"t":"Medyen tarafına yöneldiğinde dedi ki: Umarım ki Rabbım, beni yolun doğrusuna hidayet eder."},{"n":23,"t":"Medyen suyuna varınca; davarlarını sulayan bir insan topluluğu gördü. Ve onlardan başka sürülerini gözetleyen iki kadın buldu. Onlara: İşiniz nedir? dedi. Onlar da: Çobanlar ayrılana kadar biz sulamayız. Babamız çok yaşlıdır da ondan, dediler."},{"n":24,"t":"Bunun üzerine onlarınkini suladı. Sonra gölgeye çekildi ve dedi ki: Rabbım; doğrusu bana indireceğin hayra muhtacım."},{"n":25,"t":"Derken, o kadınlardan biri, utana utana yürüyüp ona geldi: Babam, dedi, sana sulama ücretini ödemek için seni çağırıyor. Ona gelince, başından geçeni anlattı. O da: Korkma; artık zalimler güruhundan kurtuldun, dedi."},{"n":26,"t":"O ikiden biri dedi ki: Babacığım, onu ücretle tut. Çünkü ücretle tuttuklarının en iyisi bu güçlü ve emin kişidir."},{"n":27,"t":"O da dedi ki: Bana sekiz yıl çalışmana karşılık, bu iki kızımdan birini sana nıkahlamak istiyorum. Şayet on yıla tamamlarsan o, senden bir lutuf olur. Ama sana zorluk çektirmek istemem. İnşaallah beni salihlerden bulacaksın."},{"n":28,"t":"Dedi ki: Bu, seninle benim aramdadır. Bu süreden hangisini doldurursam doldurayım, bir kötülüğe uğramam. Söylediklerimize Allah Vekil’dir."},{"n":29,"t":"Musa süreyi doldurunca; ailesi ile birlikte yola çıktı. Tur yanında bir ateş gördü. Ailesine dedi ki: Durun, ben bir ateş gördüm. Olur ki size ondan bir haber, yahut ısınmanız için ateşten bir kor getiririm."},{"n":30,"t":"Oraya geldiğinde, feyizli yerdeki vadinin sağ yanındaki ağaçtan: Ey Musa; şüphesiz Ben, alemlerin Rabbı olan Allah’ım."},{"n":31,"t":"Asanı bırak, diye seslenildi. Onun bir yılan gibi deprendiğini görünce, dönüp arkasına bakmadan kaçtı. Ey Musa, beri gel, korkma. Çünkü sen emniyyette olanlardansın, denildi."},{"n":32,"t":"Elini koynuna sok, lekesiz bembeyaz çıksın. Ellerini kendine çek, korkun kalmasın. Bu ikisi, Firavun ve erkanına karşı Rabbından iki burhandır. Doğrusu onlar, fasıklar güruhudur, denildi."},{"n":33,"t":"Dedi ki: Rabbım; doğrusu ben, onlardan bir cana kıydım, beni öldürmelerinden korkarım."},{"n":34,"t":"Kardeşim Harun’un dili benimkinden daha düzgündür. Onu benimle beraber yardımcı olarak gönder ki beni tasdik etsin. Çünkü ben, tekzib etmelerinden endişe duyuyorum."},{"n":35,"t":"Buyurdu ki: Senin gücünü kardeşinle artıracağız. İkinize de öyle bir güç vereceğiz ki onlar, size erişemeyecekler. Ayetlerimizle ikiniz de, ikinize uyanlar da üstün geleceklerdir."},{"n":36,"t":"Musa onlara apaçık ayetlerimizle gelince: bu, uydurulmuş bir sihirden başka bir şey değildir. Biz, önceki atalarımızdan böylesini işitmemiştik, dediler."},{"n":37,"t":"Musa dedi ki: Rabbım, kimin hidayetle katından geldiğini ve bu yurdun sonunun kimin olacağını daha iyi bilir. Doğrusu zalimler, asla felah bulmazlar."},{"n":38,"t":"Firavun da dedi ki: Ey ileri gelenler; sizin, benden başka bir tanrınız olduğunu bilmiyorum. Ey Haman; haydi, benim için çamurun üzerinde ateş yak da, bana büyük bir kule yap. Çıkar da belki Musa’nın tanrısını görürüm. Doğrusu onu yalancılardan sanıyorum."},{"n":39,"t":"O da, askerleri de memlekette haksız yere büyüklük tasladılar ve gerçekten Bize döndürülmeyeceklerini sandılar."},{"n":40,"t":"Biz de onu ve askerlerini yakalayıp suya attık. Zalimlerin sonunun nasıl olduğuna bir bak."},{"n":41,"t":"Onları, ateşe çağıran önderler kıldık. Kıyamet günü de yardım görmezler."},{"n":42,"t":"Bu dünyada arkalarına la’neti taktık. Kıyamet günü de onlar çirkinleştirilmiş olanlardır."},{"n":43,"t":"Andolsun ki; Biz, önceki nesilleri yok ettikten sonra Musa’ya insanlar için basiretler, hidayet ve rahmet olmak üzere kitabı verdik. Olur ki düşünürler diye."},{"n":44,"t":"Musa’ya buyruğumuzu bildirdiğimiz vakit, batı yönünde değildin sen. Görenlerden de olmamıştın."},{"n":45,"t":"Ama Biz; daha nice nesiller yarattık. Ömürleri uzadıkça uzadı onların. Sen, Medyen halkı arasında bulunup da onlara ayetlerimizi okumuyordun. O haberleri sana gönderen Biziz."},{"n":46,"t":"Biz seslendiğimiz vakit; sen Tur’un yanında da değildin. Fakat sen, kendinden önce onlara uyarıcı gelmeyen bir kavmi uyarman için, Rabbından bir rahmet olarak gönderildin. Olur ki onlar, düşünürler diye."},{"n":47,"t":"Yaptıklarından ötürü başlarına bir musibet geldiği zaman: Rabbımız, bize bir peygamber gönderseydin de ayetlerine uysak ve mü’minlerden olsak olmaz mıydı? derler."},{"n":48,"t":"Ama onlara katımızdan gerçek gelince: Musa’ya verilenler gibi ona da verilmeli değil miydi? derler. Daha önce Musa’ya verileni de inkar etmemişler miydi? Birbirine destek olan iki büyücü, demişlerdi ve biz, hepsini inkar edenleriz, demişlerdi."},{"n":49,"t":"De ki: Şayet doğru sözlüyseniz; Allah katından bu ikisinden daha doğru bir kitab getirin de ona uyalım."},{"n":50,"t":"Şayet sana cevab vermezlerse, bil ki; onlar, sırf kendi heveslerine uymaktadırlar. Halbuki Allah’tan bir hidayet olmaksızın kendi hevesine uyandan daha sapık kim vardır. Muhakkak ki Allah; zalimler güruhunu hidayete erdirmez."},{"n":51,"t":"Andolsun ki; Biz, onlar için sözü birbirine bitiştirdik. Belki düşünürler diye."},{"n":52,"t":"Kendilerine daha çnceden kitab verdiklerimiz de buna inanırlar."},{"n":53,"t":"Onlara Kur’an okunduğu zaman; derler ki: Ona inandık, doğrusu o, Rabbımızdan gelen gerçektir. Şüphesiz biz, ondan önce de müslümanlar olmuştuk."},{"n":54,"t":"İşte onlara sabrettiklerinden ötürü ecirleri iki defa verilir. Kötülüğü iyilikle savar onlar. Ve kendilerine verdiğimiz rızıktan da infak ederler."},{"n":55,"t":"Ve boş söz işittikleri zaman ondan yüz çevirirdiler. Bizim işlediklerimiz bize, sizin işledikleriniz sizedir. Selam olsun size, biz cahilleri aramayız derler."},{"n":56,"t":"Muhakkak ki sen; her sevdiğini hidayete erdiremezsin. Ama Allah; dilediğini hidayete erdirir. Ve hidayete erecekleri en iyi O, bilir."},{"n":57,"t":"Dediler ki: Seninle beraber hidayete uyacak olursak, yerimizden oluruz. Halbuki onları katımızdan bir rızık olarak her şeyin mahsulünün toplandığı emin bir haremde yerleştirmedik mi? Ama onların çoğu bilmezler."},{"n":58,"t":"Biz; nimet ve refahıyla şımarmış nice kasabaları yok etmişizdir. İşte kendilerinden sonra çok az kimselerin oturabileceği yerleri. Ve oralara varis olanlar Biz’dik, Biz."},{"n":59,"t":"Anasına, ayetlerimizi okuyacak bir peygamber göndermedikçe Rabbın kasabaları helak etmiş değildir. Ve Biz; halkı zalim olan kasabalardan başkasını helak edici değiliz."},{"n":60,"t":"Size verilen herhangi bir şey; dünya hayatının bir geçimliği ve süsüdür. Allah katında olan ise daha hayırlı ve devamlıdır. Hala akletmez misiniz"},{"n":61,"t":"Şimdi kendisine güzel bir vaadde bulunduğumuz ve ona kavuşan kimse; dünya hayatında kendisine bir geçimlik verdiğimiz, sonra kıyamet gününde huzurumuza getirilmişlerden olan kimse gibi midir?"},{"n":62,"t":"O gün Allah; onlara seslenip: Benim ortağım olduklarını ileri sürdükleriniz nerededirler? der."},{"n":63,"t":"Aleyhlerine hüküm gerçekleşen kimseler: Rabbımız; işte bunlar azdırdığımız kimselerdir. Kendimiz nasıl azmışsak onları da öylece biz azdırdık. Onlardan uzaklaşıp sana geldik, zaten onlar bize tapmıyorlardı, derler."},{"n":64,"t":"Denir ki: Koştuğunuz ortaklarınızı çağırın. Onlar çağırırlar, ama kendilerine cevap veremezler. Cehennem azabını görünce de doğru yolda olmadıklarına yanarlar."},{"n":65,"t":"O gün, Allah; onlara seslenip: Peygamberlere ne cevab verdiniz? der."},{"n":66,"t":"Ama o gün, onlara karşı bütün haberler kör olmuştur. Birbirlerine de soramazlar."},{"n":67,"t":"Ama tevbe edip inanan ve salih amel işleyen kimsenin, kurtuluşa erenlerden olması ümid edilir."},{"n":68,"t":"Rabbın; dilediğini yaratır ve seçer. Onlar için seçim hakkı yoktur. Onların koştukları ortaklardan Allah münezzehtir ve yücedir."},{"n":69,"t":"Rabbın; göğüslerinin gizlediklerini de, açığa vurduklarını da bilir."},{"n":70,"t":"O, öyle bir Allah’tır ki; kendinden başka ilah yoktur. Önünde de, sonunda da hamd O’nadır. Hüküm O’nundur ve O’na döndürüleceksiniz."},{"n":71,"t":"De ki: Şayet Allah; geceyi kıyamete kadar üzerinizde sürekli kılsaydı; Allah’tan başka size ışık getirecek tanrı kimdir? Hala dinlemeyecek misiniz?"},{"n":72,"t":"De ki: Şayet Allah gündüzü kıyamet gününe kadar üzerinizde sürekli kılsaydı; size içinde dinleneceğiniz bir geceyi getirecek Allah’tan başka tanrı kimdir? Hala görmeyecek misiniz?"},{"n":73,"t":"O’nun rahmetindendir ki; dinlenmeniz için geceyi, lutfedip verdiği rızkı aramanız için gündüzü yaratmıştır. Ta ki şükredesiniz."},{"n":74,"t":"O gün onlara seslenip: Nerededir Bana ortak olduklarını iddia ettikleriniz? der."},{"n":75,"t":"Her ümmetten bir şahid çekip çıkarmışızdır. Ve kesin delilinizi getirin, demişizdir. O zaman gerçeğin Allah’tan olduğunu ve uydurduklarının kendilerini bırakıp kaçtığını anlarlar."},{"n":76,"t":"Gerçekten Karun; Musa’nın kavminden biriydi. Ama onlara karşı azgınlık etti. Biz, ona; anahtarlarını güçlü bir topluluğun zor taşıdığı hazineler vermiştik. Kavmi ona şöyle demişti: Şımarma, çünkü Allah; şımarıkları sevmez."},{"n":77,"t":"Allah’ın sana verdiği şeylerde ahiret yurdunu gözet. Dünyadaki nasibini de unutma. Allah’ın sana ihsan ettiği gibi sen de ihsan da bulun. Yeryüzünde bozgunculuk arama. Doğrusu Allah; bozguncuları sevmez."},{"n":78,"t":"Dedi ki: Bu, bana; ancak bende olan bilgiden ötürü verilmiştir. Bilmez mi ki; Allah, önceleri ondan daha güçlü ve topladığı daha fazla olan nice nesilleri yok etmiştir. Suçlulardan günahları sorulmaz."},{"n":79,"t":"Debdebe içinde kavminin karşısına çıktı. Dünya hayatını isteyenler: keşki Karun’a verildiği gibi bizim de olsaydı. Doğrusu o, büyük bir varlık sahibidir, demişlerdi."},{"n":80,"t":"Kendilerine bilgi verilmiş olanlar da şöyle demişti: Yazıklar olsun size Allah’ın mükafatı, iman edip salih amel işleyenler için daha hayırlıdır. Ona da ancak sabredenler kavuşabilir."},{"n":81,"t":"Sonunda onu da, sarayını da yerin dibine geçirdik. Allah’a karşı kendisine yardım edebilecek kimsesi de yoktu. Bizzat kendisini koruyabileceklerden de değildi."},{"n":82,"t":"Daha dün onun yerinde olmayı isteyenler: Vay demek ki Allah; kullarından dilediğinin rızkını genişletip daraltmaktadır. Eğer Allah, bize lutfetmemiş olsaydı; bizi de yerin dibine geçirirdi. Vay, demek ki kafirler, asla felah bulmazlar, demeye başladılar."},{"n":83,"t":"İşte ahiret yurdu. Biz; onu, yeryüzünde böbürlenmeyen ve bozgunculuğu istemeyen kimselere veririz. Akıbet muttekilerindir."},{"n":84,"t":"Kim, bir iyilikle gelirse; ona, daha hayırlısı verilir. Kim de bir kötülükle gelirse; o kötülükleri işleyenler, ancak yaptıkları kadar ceza görürler."},{"n":85,"t":"Kur’an’ı senin üzerine farz kılan Allah; elbette seni döneceğin yere döndürecektir. De ki: Kimin doğrulukla geldiğini, kimin apaçık sapıklıkta bulunduğunu en iyi bilen Rabbımdır."},{"n":86,"t":"Sen; sana bu Kitab’ın verileceğini ummazdın. Bu; ancak Rabbının bir rahmetidir. Öyle ise, sakın kafirlere yardımcı olma."},{"n":87,"t":"Allah’ın ayetleri sana indirildikten sonra, sakın seni onlardan alıkoymasınlar. Rabbına davet et ve sakın müşriklerden olma."},{"n":88,"t":"Allah ile birlikte bir başka tanrıya yalvarma. O’ndan başka hiçbir ilah yoktur. O’nun zatından başka her şey helak olacaktır. Hüküm O’nundur ve sadece O’na döndürüleceksiniz."}],[{"n":1,"t":"Elif, Lam, Mim."},{"n":2,"t":"Yoksa, insanlar; inandık demeleriyle bırakılıvereceklerini ve kendilerinin denenmeyeceklerini mi sandılar."},{"n":3,"t":"Andolsun ki; Biz, onlardan öncekileri de denedik. Allah; elbette doğruları bilir ve elbette yalancıları da bilir."},{"n":4,"t":"Yoksa, kötülük yapanlar Biz’den kaçabileceklerini mi sanırlar? Ne kötü hüküm veriyorlar."},{"n":5,"t":"Kim Allah’a kavuşmayı umarsa; muhakkak ki Allah’ın belirttiği vakit mutlaka gelecektir. O; Semi’dir. Alim’dir."},{"n":6,"t":"Kim cihad ederse; ancak kendisi için cihad etmiş olur. Zira Allah; alemlerden müstağnidir."},{"n":7,"t":"İman edip de salih amel işleyenlerin, kötülüklerini andolsun ki örteriz. Onları yaptıklarından daha güzeli ile mükafatlandırırız."},{"n":8,"t":"Biz, insana; anne ve babasına iyi davranmasını tavsiye ettik. Eğer onlar, hakkında bilgin olmayan şeyi Bana ortak koşman için seni zorlarlarsa, kendilerine itaat etme. Dönüşünüz Bana’dır. Yaptıklarınızı size bildiririm."},{"n":9,"t":"İman edip salih amel işleyenleri de andolsun ki; salihlerin arasına katacağız."},{"n":10,"t":"İnsanlardan öyleleri de vardır ki; Allah’a inandık, der de; Allah uğrunda bir eziyete uğratılınca; insanların o eziyetini, Allah’ın azabı gibi tutar. Rabbından bir yardım gelecek olursa; andolsun ki: Doğrusu biz, sizinle beraberdik, derler. Allah, herkesin kalbinde olanları en iyi bilen değil midir?"},{"n":11,"t":"Elbette Allah; inananları bilir. Ve elbette münafıkları da bilir."},{"n":12,"t":"Küfredenler, inananlara derler ki: Bizim yolumuza uyun da sizin günahlarınızı biz taşıyalım. Halbuki onların günahlarından hiç birini yüklenecek değillerdir. Doğrusu onlar yalancıdırlar."},{"n":13,"t":"Gerçekten onlar; hem kendi yüklerini, hem de kendi yükleriyle beraber daha nice yükleri yüklenecekler ve uydurup durdukları şeylerden dolayı kıyamet günü elbette sorguya çekileceklerdir."},{"n":14,"t":"Andolsun ki; Biz, Nuh’u, kavmine gönderdik. Aralarında elli yılı müstesna olmak üzere bin yıl kaldı. Sonunda onlar, zulme devam edip dururken kendilerini tufan yakalayıverdi."},{"n":15,"t":"Ama Biz; onu da, gemi arkadaşlarını da kurtardık ve bunu alemlere bir ayet yaptık."},{"n":16,"t":"İbrahim’i de. Hani kavmine demişti ki: Allah’a ibadet edin ve O’ndan sakının. Bilirseniz bu; sizin için daha hayırlıdır."},{"n":17,"t":"Siz; sadece Allah’ı bırakıp putlara tapıyor, aslı astarı olmayan sözler uyduruyorsunuz. Doğrusu Allah’tan başka taptıklarınızın size rızık vermeye güçleri yetmez. Öyleyse, rızkı Allah katında arayın, sadece O’na kulluk edin, O’na şükredin. Siz; ancak O’na döndürüleceksiniz."},{"n":18,"t":"Eğer siz, yalanlıyorsanız, bilin ki; sizden önceki ümmetler de yalanlamışlardı. Peygambere düşen, sadece apaçık tebliğden ibarettir."},{"n":19,"t":"Görmediler mi ki; Allah yaratmayı nasıl başlatıyor sonra da onu iade ediyor? Şüphesiz bu, Allah’a pek kolaydır."},{"n":20,"t":"De ki: Yeryüzünde gezip dolaşın da Allah’ın yaratmaya nasıl başladığını bir görün. İşte Allah; yeni bir ahiret hayatını da tekrar yaratacaktır. Muhakkak ki Allah; her şeye kadirdir."},{"n":21,"t":"Dilediğine azab eder, dilediğine merhamet eder. Ve ona çevrileceksiniz."},{"n":22,"t":"Siz ne yerde, ne gökte O’nu aciz bırakabilirsiniz. Allah’tan başka sizin hiç bir dostunuz ve yardımcınız da yoktur."},{"n":23,"t":"Allah’ın ayetlerini ve O’na kavuşmayı inkar edenler; işte onlar, Benim rahmetimden ümitlerini kesmiş olanlardır. Ve işte elem verici azab onlaradır."},{"n":24,"t":"Bunun üzerine kavminin ona cevabı sadece: Onu öldürün veya yakın, demek oldu. Ama Allah onu ateşten korudu. Doğrusu bunda, inananlar için ayetler vardır."},{"n":25,"t":"Ve o: Dünya hayatında Allah’ı bırakıp aranızda putları dostluk vesilesi kıldınız. Sonra da kıyamet gününde birbirinize küfreder ve karşılıklı la’net okursunuz. Varacağınız yer, ateştir. Sizin yardımcılarınız da yoktur, dedi."},{"n":26,"t":"Bunun üzerine Lut ona inandı ve: Doğrusu ben, Rabbıma hicret edeceğim. Muhakkak ki O; Aziz ve Hakim olanın kendisidir, dedi."},{"n":27,"t":"Ve ona İshak ve Ya’kub’u ihsan ettik. Soyundan gelenlere kitab ve peygamberlik verdik. Ona dünyada mükafatını verdik. Doğrusu ahirette de o, salihlerdendir."},{"n":28,"t":"Lut’u da. Hani o, kavmine demişti ki: Gerçekten siz; dünyalarda hiç kimsenin sizden önce yapmadığı bir hayasızlığı yapıyorsunuz."},{"n":29,"t":"Siz; erkeklere yaklaşıyor, yol kesiyor ve toplantılarınızda fena şeyler yapmıyor musunuz? Kavminin ona cevabı: Doğru sözlü isen, bize Allah’ın azabını getir, demek oldu."},{"n":30,"t":"Dedi ki: Rabbım; bozgunculara karşı bana yardım et."},{"n":31,"t":"Elçilerimiz İbrahim’e müjde ile gelince dediler ki: Biz; bu kasaba halkını yok edeceğiz. Çünkü oranın ahalisi zalim kimselerdir."},{"n":32,"t":"Ama Lut oradadır, dedi. Elçiler de: Biz, orada olanları daha iyi biliyoruz. Onu ve geride kalanlardan karısı dışında ailesini kurtaracağız, dediler."},{"n":33,"t":"Elçilerimiz Lut’a geldiklerinde, bu yüzden o tasalandı ve çok sıkıldı. Ona dediler ki: Korkma ve tasalanma. Doğrusu biz, seni ve geride kalacaklardan olan karının dışındaki aileni kurtaracağız."},{"n":34,"t":"Bu kasaba halkına da fasıklık yapar olduklarından dolayı gökten azab indireceğiz."},{"n":35,"t":"Andolsun ki; akleden bir kavim için Biz, orada apaçık bir ayet bırakmışızdır."},{"n":36,"t":"Medyen halkına da kardeşleri Şuayb’ı: Ey kavmim; Allah’a ibadet edin, ahiret gününe ümid bağlayın ve yeryüzünde bozgunculuk yaparak karışıklık çıkarmayım, dedi."},{"n":37,"t":"Ama onu yalanladılar. Bunun üzerine kendilerini şiddetli bir sarsıntı yakalayıverdi de oldukları yerde diz üstü çökekaldılar."},{"n":38,"t":"Ad ve Semud kavmini de. Bunu, oturdukları yerlerden anlamaktasınız. Şeytan kendilerine yaptıkları şeyleri güzel göstermişti de onları doğru yoldan alıkoymuştu. Halbuki kendileri bunu anlayacak durumda idiler."},{"n":39,"t":"Karun’u, Firavun’u ve Haman’ı da. Andolsun ki Musa, kendilerine apaçık burhanlar getirmiş de onlar yeryüzünde büyüklük taslamışlardı. Halbuki azabımızın önüne geçebilecek değillerdi."},{"n":40,"t":"Her birini suçüstü yakaladık. Kimine taşlar savuran kasırga gönderdik, kimini bir çığlık tuttu, kimini yerin dibine geçirdik, kimini de suda boğduk. Allah; onlara zulmetmiyordu, ama onlar, kendi kendilerine zulmediyorlardı."},{"n":41,"t":"Allah’tan başka dostlar edinenlerin misali; kendine yuva yapan örümceğin misali gibidir. Evlerin en çürüğü muhakkak ki örümceğin yuvasıdır. Keşki bilselerdi."},{"n":42,"t":"Muhakkak ki Allah; kendini bırakıp da tapındıkları şeyi bilir. Ve O, Aziz’dir. Hakim’dir."},{"n":43,"t":"İşte misaller. Biz, onları insanlara anlatıyoruz. Bilenlerden başkası bunları anlamaz."},{"n":44,"t":"Allah; gökleri ve yeri hak ile yarattı. Muhakkak ki bunda, mü’minler için bir ayet vardır."},{"n":45,"t":"Sana kitabtan vahyolunanı oku, namaz kıl. Muhakkak ki namaz, hayasızlıktan ve kötülükten alıkoyar. Allah’ı zikretmek ise muhakkak ki en büyüktür. Ve Allah; yaptıklarınızı bilir."},{"n":46,"t":"İçlerinden zulmedenler bir yana; Ehl-i Kitab ile en güzel olanın dışında mücadele etmeyin ve deyin ki Bize indirilene de, size indirilene de inandık. Bizim tanrımız da, sizin tanrınız da birdir. Biz, O’na teslim olanlarız."},{"n":47,"t":"İşte böylece sana Kitab’ı indirdik. Kendilerine kitab verdiklerimiz de ona inanırlar. Bunlardan da ona inanan bulunur. Ayetlerimizi kafirlerden başkası inkar etmez."},{"n":48,"t":"Daha önce sen hiç bir kitab okur değildin. Sağ elinle de onu yazmıyordun. Öyle olsaydı; batılda olanlar şüpheye düşerlerdi."},{"n":49,"t":"Bilakis o, kendilerine ilim verilenlerin gönüllerinde apaçık olan ayetlerdir. Zalimlerden başkası ayetlerimizi inkar etmez."},{"n":50,"t":"Rabbından ona ayetler indirilmeli değil miydi? dediler. De ki: O ayetler, ancak Allah’ın nezdindedir. Ben, sadece apaçık bir uyarıcıyım."},{"n":51,"t":"Kendilerine okunan bu kitabı sana indirmiş olmamız onlara yetmiyor mu? Bunda inanan bir kavim için rahmet ve öğüt vardır."},{"n":52,"t":"De ki: Şahid olarak benimle sizin aranızda Allah yeter. O; göklerde ve yerde olanı bilir. Batıla inanıp Allah’a küfredenler, işte onlar hüsrana uğrayanların kendileridir."},{"n":53,"t":"Senden azabı çarçabuk isterler. Eğer belirtilmiş bir süre olmasaydı, azab onlara hemen gelirdi. Ama farkına varmadan o, kendilerine ansızın gelecektir."},{"n":54,"t":"Senden azabı çarçabuk istiyorlar. Doğrusu cehennem kafirleri kuşatıp durmaktadır."},{"n":55,"t":"O günde hem tepelerinden, hem de ayaklarının altından azab kendilerini kaplayacaktır. Ve: Yaptıklarınızın karşılığını tadın, diyecektir."},{"n":56,"t":"Ey iman etmiş olan kullarım; şüphesiz ki Benim yerim geniştir. O halde yalnız Bana ibadet edin."},{"n":57,"t":"Her nefis ölümü tadacaktır. Sonunda Bize döndürüleceksiniz."},{"n":58,"t":"İman edip de salih amel işleyenleri altından ırmaklar akan, içinde temelli kalacakları cennetteki köşklere yerleştiririz. Çalışanların mükafatları ne güzeldir."},{"n":59,"t":"Onlar ki; sabrederler ve Rabblarına tevekkül ederler."},{"n":60,"t":"Nice canlı vardır ki; rızkını kendi taşımaz. Sizin de, onların da rızkını Allah verir. Ve O; Semi’dir, Alim’dir."},{"n":61,"t":"Andolsun ki; onlara: Gökleri ve yeri yaratan, güneşi ve ayı müsahhar kılan kimdir? diye sorsan, elbette; Allah’tır, diyecekler. O halde neye, çevrilip döndürülüyorlar?"},{"n":62,"t":"Allah, kullarından dilediğine rızkı yayıp genişletir, onu (dilediğine de) kısar. Şüphesiz Allah, her şeyi bilendir."},{"n":63,"t":"Andolsun ki; onlara: ‘Gökten su indirip onunla ölümünden sonra yeri dirilten kimdir?’ diye sorarsan, elbette; ‘Allah’tır’ diyecekler. De ki: ‘Hamd Allah’adır’. Ama onların çoğu akletmezler."},{"n":64,"t":"Bu dünya hayatı; yalnızca bir oyun ve oyalanmadır. Asıl hayat, ahiret yurdundaki hayattır. Keşki bilseler."},{"n":65,"t":"Gemiye bindiklerinde; dini yalnız Allah’a tahsis ederek O’na yalvarırlar. Ama onları karaya çıkararak kurtarınca, hemen Allah’a şirk koşarlar."},{"n":66,"t":"Kendilerine verdiğimize küfretsinler, eğlensinler bakalım. Yakında bileceklerdir."},{"n":67,"t":"Çevrelerinde insanların zorla kapılıp götürülmesine rağmen orayı emin bir harem yaptığımızı onlar görmediler mi? Yoksa batıla inanıp da Allah’ın nimetine küfür mü ediyorlar?"},{"n":68,"t":"Allah’a karşı yalan düzenden veya hak kendisine gelmişken onu yalanlayandan daha zalim kim vardır? Kafirlere cehennemde barınacak yer mi yok?"},{"n":69,"t":"Bizim uğrumuzda mücahede edenleri elbette yollarımıza eriştiririz. Şüphesiz ki Allah, ihsan edenlerle beraberdir."}],[{"n":1,"t":"Elif, Lam, Mim."},{"n":2,"t":"Rumlar yenildiler."},{"n":3,"t":"Yakın bir yerde. Ama onlar, bu yenilgilerinden sonra galib geleceklerdir."},{"n":4,"t":"Birkaç yıl içinde. Eninde sonunda emir Allah’ındır. O gün mü’minler de sevinecekler."},{"n":5,"t":"Allah’ın yardımı ile. O dilediğine yardım eder ve O; Aziz’dir, Rahim’dir."},{"n":6,"t":"Allah’ın vaadi. Allah vaadinden asla caymaz, ama insanların çoğu bilmezler."},{"n":7,"t":"Onlar dünya hayatının yalnız dış yüzünü bilirler. Ve onlar ahiretten ise gafillerdir."},{"n":8,"t":"Kendi nefisleri hakkında düşünmezler mi? Ki Allah gökleri, yeri ve ikisinin arasında bulunanları ancak hak ile ve belirli bir süre için yaratmıştır. Doğrusu insanların çoğu Rabblarına kavuşmayı inkar ederler."},{"n":9,"t":"Onlar; yeryüzünde dolaşıp gezmezler mi ki, kendilerinden öncekilerin akıbetlerinin nasıl olduğunu görsünler. Onlat, kendilerinden daha kuvvetliydiler. Toprağı altüst etmişler ve onu kendilerinden daha çok imar etmişlerdi. Peygamberleri onlara nice açık deliller getirmişti. Demek Allah onlara zulmetmiyordu. Ama onlar kendilerine zulmediyorlardı."},{"n":10,"t":"Nihayet Allah’ın ayetlerini tekzib edip onları alaya alarak kötülük edenlerin akıbeti çok kötü oldu."},{"n":11,"t":"Allah; ilkin yaratır, sonra onu iade eder. En sonunda hepiniz O’na döndürüleceksiniz."},{"n":12,"t":"Kıyametin kopacağı gün, suçlular susacaklardır."},{"n":13,"t":"Ortaklarından da kendilerine hiçbir şefaatçı olmayacaktır. Onlar ortaklarını da inkar edeceklerdir."},{"n":14,"t":"Kıyametin kopacağı gün; işte o gün ayılırlar."},{"n":15,"t":"İman edip salih amellerde bulunanlar; bir bahçededirler, ağırlanırlar."},{"n":16,"t":"Küfredip de ayetlerimizi ve ahirete kavuşmayı yalanlayanlara gelince; işte onlar, azab için hazır bulundurulurlar."},{"n":17,"t":"Akşama girerken ve sabaha ererken hepiniz Allah’ı tesbih edin."},{"n":18,"t":"Ve hamd, O’nadır. Göklerde de, yerde de, günün sonunda da, öğleye erdiğiniz vakitte de."},{"n":19,"t":"Ölüden diriyi, diriden ölüyü çıkarır. Yeryüzünü ölümünden sonra canlandırır. İşte böyle çıkarılacaksınız."},{"n":20,"t":"Sizi topraktan yaratmış olması da O’nun ayetlerindendir. Sonra siz, yayılmakta olan bir beşer oldunuz."},{"n":21,"t":"Kendileriyle huzura kavuşmanız için size kendi nefislerinizden eşler yaratıp aranızda sevgi ve merhamet var etmesi de O’nun ayetlerindendir. Şüphesiz ki bunlarda düşünen bir kavim için ayetler vardır."},{"n":22,"t":"Gökleri ve yeri yaratması, dillerinizin ve renklerinizin birbirine uymaması da O’nun ayetlerindendir. Şüphesiz ki bunda, bilenler için ayetler vardır."},{"n":23,"t":"Geceleyin uyumanız, gündüz de lutfundan rızık aramanız O’nun ayetlerindendir. Şüphesiz ki, bunlarda kulak veren bir kavim için ayetler vardır."},{"n":24,"t":"Size korku ve ümit vermek için şimşeği göstermesi, gökten su indirip ölümden sonra yeri onunla diriltmesi de O’nun ayetlerindendir. Doğrusu bunlarda, akleden bir kavim için ayetler vardır."},{"n":25,"t":"Göğün ve yerin, O’nun emri ile ayakta durması da yine O’nun ayetlerindendir. Sonra sizi bir çağırmaya görsün, yerden hemen çıkıverirsiniz."},{"n":26,"t":"Göklerde ve yerde bulunanlar O’nundur. Hepsi O’na boyun eğer."},{"n":27,"t":"İlkin yaratıp sonra onu iade eden O’dur. Bu, O’nun için pek kolaydır. Göklerde ve yerde en yüce misal O’nundur. Ve O; Aziz’dir, Hakim’dir."},{"n":28,"t":"O, size kendi nefislerinizden bir misal verdi: Size verdiğimiz rızıklarda sağ ellerinizin malik olduklarından ortaklarınız olmasını ister de onlarla, eşit olur ve birbirinizi saydığınız gibi bunları da sayar mısınız? İşte Biz, akleden bir kavim için ayetleri böyle açıklarız."},{"n":29,"t":"Hayır, o zulmedenler; bilgisizce kendi heveslerine uymuşlardır. Allah’ın saptırdığı kimseyi kim doğru yola iletebilir? Onların yardımcıları da yoktur."},{"n":30,"t":"Öyleyse sen, yüzünü Hanif olarak dine, Allah’ın fıtratına çevir ki O, insanları bunun üzerine yaratmıştır. Allah’ın yaratışında değişme yoktur. İşte dosdoğru din budur. Ama insanların çoğu bilmezler."},{"n":31,"t":"Hepiniz O’na dönün, O’ndan korkun. Namaz kılın ve müşriklerden olmayın."},{"n":32,"t":"Onlar ki; dinlerinde ayrılığa düşüp fırka fırka olmuşlardır. Her zümre kendi yanında olanla sevinir durur."},{"n":33,"t":"İnsanlara bir zarar dokununca; Rabblarına dönerek O’na yalvarırlar. Sonra onlara katından bir rahmet tattırınca; bakarsınız ki, içlerinden bir grup Rabblarına şirk koşup durmaktadırlar."},{"n":34,"t":"Kendilerine verdiğimize nankörlük etmeleri için. Sefa sürün bakalım, yakında bileceksiniz."},{"n":35,"t":"Yoksa onlara ortak koşmalarını söyleyen bir delil mi indirdik?"},{"n":36,"t":"Ne zaman da insanlara bir rahmet tattırdık ise; onunla sevinirler. Ama yaptıklarından dolayı başlarına bir kötülük gelirse; hemen ümidlerini kesiverirler."},{"n":37,"t":"Görmezler mi ki Allah; rızkı dilediğine yayıp genişletir ve kısar da. Muhakkak ki bunda inanan bir kavim için ayetler vardır."},{"n":38,"t":"Akrabaya, yoksula ve yoloğluna hakkını ver. Bu; Allah’ın rızasını dileyenler için daha hayırlıdır ve işte onlar; kurtuluşa erenlerdir."},{"n":39,"t":"İnsanların malları içinde artsın diye verdiğiniz faiz Allah katında artmaz. Allah’ın rızasını dileyerek verdiğiniz zekat ise böyle değildir. İşte onlar; sevablarını kat kat artıranlardır."},{"n":40,"t":"Sizi yaratan, sonra rızıklandıran, sonra öldüren ve daha sonra dirilten de Allah’tır. O’na koştuğunuz ortaklarınızdan böyle bir şey yapan var mıdır? Allah, onların koştukları ortaklardan münezzehtir, yücedir."},{"n":41,"t":"İnsanların elleriyle işlediklerinden dolayı karada ve denizde Fesad belirdi. Ki yaptıklarının bir kısmını onlara tattırsın. Belki dönerler."},{"n":42,"t":"De ki: Yeryüzünde gezip dolaşın da daha önce geçenlerin akıbetinin nasıl olduğunu görün. Onların çoğu müşrik idiler."},{"n":43,"t":"Reddine asla imkan bulunmayan, Allah’ın o günü gelmezden önce, yüzünü dosdoğru dine çevir. Ki o gün insanlar bölük bölük ayrılacaklardır."},{"n":44,"t":"Kim, küfrederse; küfrü kendi aleyhinedir. Kim de salih amel işlerse; kendisi için rahat bir yer hazırlamış olur."},{"n":45,"t":"Ki, iman edip salih ameller işleyenleri Allah’ın fazlından mükafatlandırılması içindir bu. Muhakkak ki O; kafirleri sevmez."},{"n":46,"t":"Rüzgarları müjdeciler olarak göndermesi, rahmetinden size tattırması emri ile gemilerin yüzmesi ve lutfundan rızık istemeniz O’nun ayetlerindendir. Belki şükredersiniz."},{"n":47,"t":"Andolsun ki; senden önce Biz, nice peygamberleri kendi kavimlerine göndermişizdir de onlara açık deliller getirmişlerdir. Ama Biz, suç işleyenlerden öç aldık. Çünkü mü’minlere yardım etmek üstümüze bir haktır."},{"n":48,"t":"Allah, O’dur ki; rüzgarları gönderip bulutları yürütür ve onları dilediği gibi gökte yayar ve kısım kısım yığar. Nihayet sen de aralarından yağmurun çıktığını görürsün. Allah’ın kullarından dilediğine verdiği yağmurla onlar hemen seviniverirler."},{"n":49,"t":"Halbuki daha önceden kendilerine yağmur indirilmesinden kesin olarak ümitlerini kesmişlerdi."},{"n":50,"t":"Allah’ın rahmetinin belirtilerine bir baksana. Toprağı öldükten sonra nasıl diriltiyor? İşte O; bütün ölüleri de muhakkak diriltecek. O; her şeye kadirdir."},{"n":51,"t":"Andolsun ki; bir rüzgar gönderir de yeşillikleri sarartırsak; bunu görünce hemen nankörlüğe başlarlar."},{"n":52,"t":"Bunun için sen; ölüye katiyyen işittiremezsin. Dönüp giden sağırlara da daveti duyuramazsın."},{"n":53,"t":"Körleri sapıklıklarından vazgeçirip doğru yola döndüremezsin. Sen; ayetlerimizi ancak inananlara duyurabilirsin. İşte onlar, müslümanlardır."},{"n":54,"t":"Allah, O’dur ki; sizi güçsüz olarak yaratmıştır. Güçsüzlükten sonra kuvvetli kılmıl, sonra da kuvvetliliğn ardından güçsüz ve ihtiyar yapmıştır. O; dilediğini yaratır. O; Alim’dir, Kadir’dir."},{"n":55,"t":"Kıyametin kopacağı gün; suçlular bir saatten başka kalmadıklarına yemin ederler. İşte onlar, böylece aldatılıp döndürülürler."},{"n":56,"t":"Kendilerine bilgi ve iman verilenler: Andolsun ki; Allah’ın kitabında yazılan o yeniden diriliş gününe kadar kaldınız. İşte bu; yeniden diriliş günüdür. Ama siz, bilmiyordunuz, derler."},{"n":57,"t":"Zulmedenlerin o gün mazeret beyan etmeleri fayda vermez. Artık kendilerinden dönüşleri de istenmez."},{"n":58,"t":"Andolsun ki; bu Kur’an’da insanlar için her türlü misali irad etmişizdir. Bununla beraber sen, onlara herhangi bir ayet getirmiş olsan küfredenler: Siz ancak batıl şeyler ortaya atanlarsınız, derler."},{"n":59,"t":"İşte Allah; bilmeyenlerin kalblerine böyle damga basar."},{"n":60,"t":"Sabret, şüphesiz ki Allah’ın vaadi haktır. Yakınen inanmayanlar seni hafifliğe itmesinler."}],[{"n":1,"t":"Elif, Lam, Mim."},{"n":2,"t":"Bunlar Hakim kitabın ayetleridir."},{"n":3,"t":"Ki o; iyi davranan kimseler için hidayet ve rahmettir."},{"n":4,"t":"Onlar ki; namaz kılarlar, zekat verirler ve onlar ahirete de yakınen inanırlar."},{"n":5,"t":"İşte onlar; Rabblarından bir hidayet üzerindedirler. Ve işte onlar; felaha erenlerin kendileridir."},{"n":6,"t":"İnsanlar arasında bilgisizce Allah yolundan saptırmak için gerçeği boş sözlerle değişenler ve Allah yolunu alaya alanlar vardır. İşte horlayıcı azab onlar içindir."},{"n":7,"t":"Ayetlerimiz ona okunduğu zaman; kulaklarında ağırlık var da işitmiyormuş gibi büyüklük taslayarak sırt çevirir. İşte ona çok acıklı bir azabı müjdele."},{"n":8,"t":"İman edip salih amel işleyenlere; muhakkak ki Naim cennetleri vardır."},{"n":9,"t":"Orada devamlı kalırlar. Bu, Allah’ın hak vaadidir. Ve O; Aziz’dir, Hakim’dir."},{"n":10,"t":"Gökleri, gördüğünüz gibi direksiz olarak yaratmış, sizi sarsar diye yere ağır baskılar koymuş, orada her türlü canlıyı yaymıştır. Biz, gökten su indirip orada her sınıf bitkiler yetiştirmişizdir."},{"n":11,"t":"İşte bu, Allah’ın yaratışıdır. Gösterin bakalım bana O’ndan başkalarının ne yarattığını? Hayır, zalimler apaçık bir sapıklık içindedirler."},{"n":12,"t":"Andolsun ki; Biz, Allah’a şükret diye Lokman’a hikmeti verdik. Kim şükrederse; ancak kendisi için şükretmiş olur. Kim de küfrederse; muhakkak ki Allah; Gani’dir, Hamid’dir."},{"n":13,"t":"Hani Lokman; oğluna öğüt vererek demişti ki: Oğulcuğum; Allah’a şirk koşma, doğrusu şirk, büyük bir zulümdür."},{"n":14,"t":"Biz insana, ana ve babasına iyi davranmasını tavsiye ettik. Annesi onu zorluk üstüne zorlukla taşımıştı. Sütten ayrılması da iki yıl sürmüştür. Bana ve ana-babana şükret. Dönüş ancak Bana’dır."},{"n":15,"t":"Şayet onlar seni körü körüne Bana şirk koşman için zorlarsa; onlara itaat etme ve dünya işlerinde onlarla iyi geçin Bana dönenlerin yoluna uy. Sonra dönüşünüz yine Bana’dır. O zaman Ben, size yaptıklarınızı bildiririm."},{"n":16,"t":"Oğulcuğum; işlediğin şey bir hardal tanesi kadar da olsa, bir kayanın içinde veya göklerde, yahut yerin derinliklerinde de bulunsa, Allah onu getirir. Muhakkak ki Allah; Latif’tir, Habir’dir."},{"n":17,"t":"Oğulcuğum; namaz kıl, iyiliği emret, kötülüğü önle. Başına gelene sabret. Doğrusu bunlar azmedilmeye değer şeylerdir."},{"n":18,"t":"İnsanları küçümseyip yüz çevirme. Yeryüzünde böbürlenerek yürüme. Allah kendini beğenip böbürleneni şüphesiz ki hiç sevmez."},{"n":19,"t":"Yürüyüşünde tabii ol, sesini kıs. Şüphesiz ki seslerin en çirkini eşeklerin sesidir."},{"n":20,"t":"Görmez misiniz ki; Allah, göklerde olanları da, yerde olanları da size müsahhar kılmıştır. Gizli ve açık olarak nimetlerini size bolca vermiştir. İnsanlar arasında hiç bir bilgisi olmadan, hiç bir rehberi ve aydınlatıcı kitabı yokken Allah hakkında tartışanlar vardır."},{"n":21,"t":"Onlara: Allah’ın indirdiklerine uyun, denilince: Hayır, biz atalarımızı üzerinde bulduğumuz yola uyarız, derler. Ya şeytan, onları yalımlı azaba çağırıyor idiyse?"},{"n":22,"t":"Kim, ihsan ederek kendini Allah’a teslim ederse; muhakkak ki o, en sağlam kulpa sarılmıştır. Ve işlerin akıbeti Allah’a aittir."},{"n":23,"t":"Kim de küfrederse; onun küfrü, seni üzmesin. Onların dönüşü Bize’dir. O zaman yaptıklarını onlara bildiririz. Şüphesiz ki Allah; göğüslerin özünü gerçekten bilendir."},{"n":24,"t":"Onları az bir süre geçindirir, sonra da katı bir azaba sürükleriz."},{"n":25,"t":"Andolsun ki onlara: Gökleri ve yeri kim yarattı? diye sorsan; muhakkak: Allah, derler. De ki: Hamd Allah’a mahsustur. Hayır onların çoğu bilmezler."},{"n":26,"t":"Göklerde ve yerde olanlar Allah’ındır. Muhakkak ki Allah’tır O, Gani ve Hamid."},{"n":27,"t":"Eğer yeryüzündeki ağaçların hepsi kalem olsa, deniz de, arkasından yedi deniz daha kendisine yardım ederek mürekkep olsa, yine de Allah’ın kelimeleri tükenmez. Muhakkak ki Allah; Aziz’dir, Hakim’dir."},{"n":28,"t":"Sizin yaratılmanız da, yeniden diriltilmeniz de bir tek kişininki gibidir. Şüphesiz ki ALLAH; SEMİ’DİR, BASİR’DİR."},{"n":29,"t":"Görmez misin ki; Allah, geceyi gündüze, gündüzü de geceye katar. Güneşi ve ayı buyruk altında tutar. Her birisi belirli bir süreye kadar akıp gider. Muhakkak ki Allah, yaptıklarınızdan haberdardır."},{"n":30,"t":"Bu, Allah’ın; hakkın kendisi ve O’ndan başka taptıklarının da batıl olmasındandır. Doğrusu Allah; çok yücedir, çok büyüktür."},{"n":31,"t":"Görmez misin ki; gemiler denizde Allah’ın nimetiyle akıp gider. Böylece size ayetlerini gösterir. Bunlarda pek sabırlı ve çok şükreden kimseler için ayetler vardır."},{"n":32,"t":"Onları dağlar gibi dalgalar sardığı vakit; dini yalnız Allah’a tahsis ederek O’na yalvarırlar. Onları karaya çıkararak kurtardığı zaman da; içlerinden bir kısmı orta yolu tutar. Ayetlerimizi gaddar ve nankör olanın dışında başkası bilerek inkar etmez."},{"n":33,"t":"Ey insanlar; Rabbınızdan korkun. Babanın oğluna, oğulun babasına hiçbir şey ödemeyeceği günden çekinin. Allah’ın vaadi şüphesiz haktır. Öyleyse, sakın dünya hayatı sizi aldatmasın. Aldatıcı şeytan sizi Allah’ın bağışlamasına güvendirerek yoldan çıkarmasın."},{"n":34,"t":"Kıyamet saatının bilgisi şüphesiz ki Allah katındadır, yağmuru O indirir, rahimlerde bulunanı O bilir. Kimse yarın ne kazanacağını bilmez. Ve hiç bir nefis nerede öleceğini de bilmez. Muhakkak ki Allah; Alim’dir, Habir’dir."}],[{"n":1,"t":"Elif, Lam, Mim."},{"n":2,"t":"Şüphe götürmeyen kitabın indirilmesi alemlerin Rabbındandır."},{"n":3,"t":"Yoksa; O, bunu kendiliğinden uydurdu mu diyorlar; Hayır, o haktır, Rabbındandır. Ve senden evvel kendilerine uyarıcı gelmemiş olan bir kavme korkunç akıbetlerini haber vermen içindir. Belki hidayeti bulurlar."},{"n":4,"t":"Allah, O’dur ki; gökleri, yeri ve ikisinin arasında bulunanları altı günde yaratmış, sonra Arş’a hükmetmiştir. Sizin O’ndan başka bir dostunuz ve şefaatçınız yoktur. Hala düşünmüyor musunuz?"},{"n":5,"t":"Gökten yere kadar her işi O, düzenler. Sonra sizin hesabınıza göre bin yıl kadar tutan bir günde yine O’na yükselir."},{"n":6,"t":"Görülmeyeni de, görüleni de bilen, Aziz ve Rahim olan, O’dur."},{"n":7,"t":"Ki, yarattığı her şeyi güzel yaratan O’dur. İnsanı yaratmaya da çamurdan başlamıştır."},{"n":8,"t":"Sonra onun soyunu bayağı bir suyun özünden yapmıştır."},{"n":9,"t":"Sonra onu düzeltip tamamlamış ve ruhundan ona üflemiştir. Size de kulaklar, gözler ve kalbler vermiştir. Ne de az şükrediyorsunuz."},{"n":10,"t":"Dediler ki: Toprağa karışıp yok olduktan sonra mı, biz, yeniden yaratılacağız. Evet onlar; Rabblarına kavuşmayı inkar edenlerdir."},{"n":11,"t":"De ki: Size vekil kılınan ölüm meleği canınızı alacak, sonra Rabbınıza döndürüleceksiniz."},{"n":12,"t":"Suçluları Rabblarının huzurunda başları öne eğilmiş olarak: Rabbımız, gördük ve dinledik. Artık bizi dünyaya geri çevir de salih amel işleyelim. Gerçekten biz, kesin olarak inandık, derlerken bir görsen."},{"n":13,"t":"Eğer Biz isteseydik; herkesi elbette hidayete erdirirdik. Fakat: Cehennemi tamamen cinn ve insanlarla dolduracağım, diye Benden hak söz sadır olmuştur."},{"n":14,"t":"Öyleyse şu günümüze kavuşmayı unuttuğunuzdan ötürü tadın azabı. Doğrusu Biz de sizi unuttuk. Yaptıklarınıza karşılık sonsuz azabı tadın."},{"n":15,"t":"Ayetlerimize ancak, kendilerine hatırlatıldığı zaman secdeye kapananlar, büyüklük taslamayarak Rabblarını hamd ile tesbih edenler inanırlar."},{"n":16,"t":"Onların yanları yataklarından uzaklaşır. Korku ve ümid ile Rabblarına yalvarırlar. Verdiğimiz rızıklardan da infak ederler."},{"n":17,"t":"Yaptıklarına karşılık olarak onlara gözlerin aydın olacağı, nelerin gizlenmiş bulunduğunu kimse bilmez."},{"n":18,"t":"Mü’min olan kimse yoldan çıkmış kimse gibi midir? Bunlar hiç bir olmazlar."},{"n":19,"t":"İman edip salih amel işleyenlere gelince; onlar için yapmış oldukları amellere karşılık koymak üzere Me’va Cennetleri vardır."},{"n":20,"t":"Yoldan çıkanlara gelince; onların sığınağı da ateştir. Oradan çıkmak istedikleri her seferinde geri çevrilirler. Ve onlara: Yalanlayıp durduğunuz ateşin azabını tadın, denir."},{"n":21,"t":"Belki dönerler diye andolsun ki onlara büyük azabdan önce de mutlaka yakın azabdan tattıracağız."},{"n":22,"t":"Rabbının ayetleri kendisine hatırlatılıp da onlardan yüz çeviren kimseden daha zalim kim vardır? Muhakkak ki Biz, suçlulardan intikam alıcıyız."},{"n":23,"t":"Andolsun ki; Musa’ya da kitab verdik. Sakın, sen O’na kavuşacağından kuşku içinde olma. Ve onu İsrailoğullarına hidayet yaptık."},{"n":24,"t":"İçlerinden de sabrettikleri zaman emrimizle doğru yola götürecek kılavuzlar tayin ettik. Ve onlar ayetlerimizi çok iyi biliyorlardı."},{"n":25,"t":"Ayrılığa düştükleri şeylerde; Rabbın, muhakkak ki kıyamet günü aralarında hükmedecektir."},{"n":26,"t":"Şimdi yurtlarında gezip dolaştıkları, kendilerinden önceki nesillerden nicesini yok etmiş olmamız, onları doğru yola sevketmez mi? Şüphesiz bunlarda ayetler vardır. Hala dinlemezler mi?"},{"n":27,"t":"Görmezler mi ki; Biz, kuru yerlere suyu gönderiyor, onunla hayvanlarının ve kendilerinin yedikleri ekinleri çıkarıyoruz. Hala da görmeyecekler mi?"},{"n":28,"t":"Ve derler ki: Doğru söylüyorsanız bu fetih ne zamandır?"},{"n":29,"t":"De ki: Fetih günü o kafirlere imanları fayda vermeyecek ve onlara bakılmayacak."},{"n":30,"t":"Bırak onları ve bekle. Zaten onlar da beklemektedir."}],[{"n":1,"t":"Ey peygamber; Allah’tan kork ve kafirlere, münafıklara uyma. Muhakkak ki Allah; Alim, Hakim olandır."},{"n":2,"t":"Rabbından sana vahyolunana uy. Muhakkak ki Allah; yaptıklarınızdan haberdar olandır."},{"n":3,"t":"Ve Allah’a tevekkül et. Vekil olarak Allah yeter."},{"n":4,"t":"Allah, bir kişinin içinde iki kalb yaratmadı. Ve eşlerinizi, anneleriniz gibi kendinize haram saymanız için yaratmamıştır. Evladlıklarınızı da öz oğullarınız kılmamıştır. Bunlar, dillerinize doladığınız sözlerinizdir. Allah ise hakkı söyler. Ve O, yolu doğrultur."},{"n":5,"t":"Onları babalarına nisbet ederek çağırın. Allah katında en doğru olan budur. Eğer babalarını bilmezseniz; o takdirde, onlar sizin din kardeşleriniz ve dostlarınızdır. Kalbinizden kasdederek yaptıklarınız dışında hatalarınızda size bir vebal yoktur. Ve Allah; Gafur, Rahim olandır."},{"n":6,"t":"Peygamber; mü’minler için kendi öz nefislerinden daha evladır. Onun eşleri ise onların anneleridir. Akraba olanlar da Allah’ın kitabında birbirlerine diğer mü’minlerden ve muhacirlerden daha yakındırlar. Dostlarınıza yapacağınız uygun bir vasiyet başkadır. Bu, Kitab’da yazılmıştır."},{"n":7,"t":"Hani Biz; peygamberlerden söz almıştık. Senden de, Nuh’tan da, İbrahim’ den de, Musa’dan da, Meryem Oğlu İsa’dan da. Ve onlardan ağır bir misak almıştık."},{"n":8,"t":"Sadıklardan sadakatlarını sormak için. Ve O kafirlere elim bir azab hazırlamıştır."},{"n":9,"t":"Ey iman edenler; Allah’ın üzerinizdeki nimetini hatırlayın. Hani size ordular gelmişti de Biz, onların üzerine rüzgar ve sizin görmediğiniz ordular göndermiştik. Allah; yaptıklarınızı görendir."},{"n":10,"t":"Hani onlar size, hem üstünüzden hem de altınızdan gelmişlerdi. Ve hani gözler kaymış, yürekler ağızlara gelmişti ve siz Allah hakkında çeşitli zanlarda bulunuyordunuz."},{"n":11,"t":"İşte orada mü’minler imtihan edilmiş ve şiddetli bir sarsıntıyla sarsılmışlardı."},{"n":12,"t":"Ve hani münafıklar ve kalblerinde bir hastalık bulunanlar: Allah ve Rasulü bize sadece boş vaadlerde bulundular, diyorlardı."},{"n":13,"t":"Hani onlardan bir grup demişti ki: Ey Medine halkı; sizin için tutunacak bir yer yok. Artık geri dönün. İçlerinden bir grup da peygamberden izin isteyerek diyorlardı ki: Evlerimiz düşmana açıktır. Halbuki evleri açık değildi. Onlar, sadece kaçmak istiyorlardı."},{"n":14,"t":"Şayet onlara onun çevrelerinden varılmış olsaydı da fitne çıkarmaları istenseydi, hemen buna girişirler ve derhal yapmaktan geri durmazlardı."},{"n":15,"t":"Andolsun ki; onlar, daha önceden sırt çevirip kaçmayacaklarına dair Allah’a söz vermişlerdi. Ve Allah’a verilen ahid, sorumluluktu."},{"n":16,"t":"De ki: Eğer ölümden veya öldürülmekten kaçtıysanız; firar, size fayda vermeyecektir. Ve o zaman, çok az eğlendirileceksiniz."},{"n":17,"t":"De ki: Allah sizin için bir kötülük dilerse veya bir rahmet dilerse; sizi O’na karşı koruyabilecek kimdir? Onlar Allah’tan başka bir dost ve yardımcı da bulamazlar."},{"n":18,"t":"Doğrusu Allah; içinizden sizi alıkoyanları ve kardeşlerine; bize gelin, diyenleri bilir. Bunlar harbe pek az iştirak ediyorlardı."},{"n":19,"t":"Size karşı cimridirler. Korku geldiği zaman, görürsün ki onlar üstüne ölüm baygınlığı çökmüş gibi gözleri dönerek sana bakarlar. Korku gidince de iyiliğinizi çekemeyerek, sivri dilleriyle sizi incitirler. İşte onlar, inanmamışlardır. Bunun için de Allah yaptıklarını boşa çıkarmıştır. Bu, Allah için pek kolaydır."},{"n":20,"t":"Onlar, birliklerin gitmediğini sanıyorlardı. Birlikler gelmiş olsalardı, kendilerinin çöllerde bedevilerle bulunup sizin haberlerinizi oradan soruşturmayı isterlerdi. Aranızda bulunsalardı bu defa da çok az savaşırlardı."},{"n":21,"t":"Andolsun ki; sizin için Rasulullah’ta güzel bir örnek vardır. Allah’a ve ahiret gününe kavuşmayı umanlar ve Allah’ı çokça zikredenler için."},{"n":22,"t":"Mü’minler o birlikleri gördüklerinde dediler ki: İşte bize Allah’ın ve Rasulünün vaad ettiği bu. Allah ve Rasulü doğru söylemiştir. Ve bu, onların ancak imanını ve teslimiyetini artırdı."},{"n":23,"t":"Mü’minlerden öyle erler vardır ki; Allah’a verdikleri ahde sadakat göstermişlerdir. Kimi bu uğurda canını verdi, kimi de beklemektedir. Ve onlar, hiç bir değiştirme ile değiştirmediler."},{"n":24,"t":"Çünkü Allah, doğruları doğruluklarıyla mükafatlandıracak, münafıkları da dilerse azablandıracak veya tevbelerini kabul edecektir. Muhakkak ki Allah, Gafur, Rahim olandır."},{"n":25,"t":"Allah, küfredenleri kinleriyle geri çevirdi. Ve hiç bir hayra nail olmadılar. Allah, savaşta mü’minlere yetti. Ve Allah; Kavi, Aziz olandır."},{"n":26,"t":"Ehl-i kitabdan onlara destek olanları, kalelerinden indirdi. Ve kalblerine korku saldı. Onlardan kimini öldürüyor, kimini de esir alıyordunuz."},{"n":27,"t":"Ve sizi onların yerlerine, yurdlarına, mallarına henüz ayak basmadığınız yerlere de varis kıldı. Ve Allah, her şeye kadirdir."},{"n":28,"t":"Ey peygamber; eşlerine de: Eğer dünya hayatını ve süslerini istiyorsanız; gelin, size bağışta bulunayım ve güzellikle salıvereyim."},{"n":29,"t":"Yok eğer Allah’ı, Rasulünü ve ahiret yurdunu istiyorsanız; muhakkak ki Allah, içinizden iyi davranan hanımlara büyük mükafat hazırlamıştır."},{"n":30,"t":"Ey peygamber kadınları; sizlerden her kim, apaçık bir hayasızlıkla gelecek olursa, ona azab iki kat katlanır. Bu, Allah’a pek kolaydır."},{"n":31,"t":"Sizden her kim de Allah’a ve Rasulüne boyun eğip salih amel işlerse; onun mükafatını da iki kat veririz. Hem Biz, ona cömertçe bir rızık da hazırlamışızdır."},{"n":32,"t":"Ey peygamber kadınları; sizler, kadınlardan herhangi biri gibi değilsiniz. Eğer sakınıyorsanız; edalı olmayın yoksa kalbinde bir hastalık bulunanlar kötü şeyler umarlar. Ve hep ma’ruf söz söyleyin."},{"n":33,"t":"Evlerinizde oturun, ilk cahiliyye devrinde olduğu gibi açılıp saçılmayın. Namaz kılın, zekat verin, Allah’ a ve Rasulüne itaat edin. Ey Ehl-i Beyt; Allah, muhakkak ki sizden eksikliği gidermek ve sizi tertemiz temizlemek ister."},{"n":34,"t":"Evinizde okunan Allah’ın ayetlerini ve hikmeti hatırlayın. Muhakkak ki Allah, Latif, Habir olandır."},{"n":35,"t":"Doğrusu müslüman erkeklerle, müslüman kadınlar; mü’min erkeklerle, mü’ min kadınlar; taata devam eden erkeklerle, taata devam eden kadınlar; sadık erkeklerle, sadık kadınlar; sabreden erkeklerle, sabreden kadınlar; huşu’ eden erkeklerle, huşu’eden kadınlar; sadaka veren erkeklerle, sadaka veren kadınlar; oruç tutan erkeklerle, oruç tutan kadınlar; iffetlerini koruyan erkeklerle, iffetlerini koruyan kadınlar; Allah’ı çokça zikreden erkeklerle, çokça zikreden kadınlar; işte onlar için, Allah; mağfiret ve büyük bir mükafat hazırlamıştır."},{"n":36,"t":"Allah ve Rasulü bir şeye hükmettiği zaman; ne mü’min erkekler için ne de mü’min kadınlar için artık işlerinde bir seçme hakkı olamaz. Kim de Allah’a ve Rasulüne isyan ederse; şüphesiz ki apaçık bir sapıklıkla sapmış olur."},{"n":37,"t":"Hani sen; Allah’ın kendisine nimet verdiği ve senin de nimetlendirdiğin kimseye diyordun ki: Eşini bırakma ve Allah’tan kork. Allah’ın açığa vuracağı şeyi de içine saklıyor, insanlardan korkuyordun. Halbuki en çok Allah’tan korkman gerekirdi. Nihayet Zeyd onunla bağını kopardığında, onu seninle evlendirdik ki böylece evladlıkları eşleriyle bağlarını kopardıklarında onlarla evlenmek konusunda mü’minlere bir vebal olmadığı bilinsin. Allah’ın emri yerine getirilmiştir."},{"n":38,"t":"Allah’ın, kendisine farz kıldığı şeylerde peygamberine herhangi bir güçlük yoktur. Allah’ın önceden geçmişler hakkındaki sünnetidir. Ve Allah’ın emri, gereği gibi yerine gelmiştir."},{"n":39,"t":"Allah’ın risaletlerini tebliğ edenler ve O’ndan korkanlar; Allah’tan başka kimseden korkmazlar. Hesab görücü olarak Allah, yeter."},{"n":40,"t":"Muhammed; sizin adamlarınızdan herhangi birisinin babası değildir, sadece Allah’ın Rasulü ve peygamberlerin hatemidir. Allah, her şeyi bilendir."},{"n":41,"t":"Ey iman edenler; Allah’ı çokça zikredin."},{"n":42,"t":"Ve O’nu sabah akşam tesbih edin."},{"n":43,"t":"Sizi karanlıklardan aydınlığa çıkarmak için rahmet etmekte olan O’dur. Melekleri de size dua ederler. Ve O, mü’minlere Rahim olandır."},{"n":44,"t":"O’na kavuştukları gün, onların sağlık temennileri; selamdır. Onlara cömertçe bir mükafat hazırlamıştır."},{"n":45,"t":"Ey peygamber; Biz, seni muhakkak şahid, müjdeci ve uyarıcı olarak gönderdik."},{"n":46,"t":"İzniyle Allah’a çağıran ve aydınlatan bir ışık olarak."},{"n":47,"t":"Mü’minlere; kendileri için Allah tarafından büyük bir lütuf olduğunu müjdele."},{"n":48,"t":"Kafirlere ve münafıklara uyma, onların eziyetlerine aldırma. Allah’a tevekkül et. Vekil olarak Allah yeter."},{"n":49,"t":"Ey iman edenler; mü’min kadınları nikahlayıp sonra onlarla temasta bulunmadan önce boşadığınızda, artık onlar için iddet saymanıza lüzum yoktur. Kendilerini geçindirin ve güzellikle serbest bırakın."},{"n":50,"t":"Ey peygamber; Biz, mehirlerini verdiğin eşlerini, Allah’ın sana ganimet olarak verdiği cariyeleri, seninle beraber hicret eden amcanın kızlarını, halalarının kızlarını, dayının kızlarını, teyzelerinin kızlarını ve bir de eğer mü’min bir kadın kendisini peygambere hibe eder de peygamber de onunla evlenmeyi isterse onuki bu, mü’minlerden ayrı olarak sadece sana has olmak üzere senin için helal kıldık. Sana bir zorluk olmasın diye mü’minlerin eşleri ve sağ ellerinin malik oldukları hakkında ne hükmettiğimizi bildirdik. Ve Allah; Gafur, Rahim olandır."},{"n":51,"t":"Onlardan istediğini bırakabilir, istediğini alabilirsin. Bırakmış olduklarından da arzu ettiğini almanda sana bir vebal yoktur. Bu, onların gözlerinin aydın olması, üzülmemeleri ve kendilerine verdiğin şeylere razı olmaları için daha elverişlidir. Allah, kalblerimizde olanı bilir. Ve Allah; Alim, Halim olandır."},{"n":52,"t":"Bundan sonra artık sana kadınlarla evlenmek ve güzellikleri hoşuna gitse de sağ elinin malik olduklarının dışında hiç birini başka bir eşle değiş tirmek helal değildir. Allah; her şeyi murakabe edendir."},{"n":53,"t":"Ey iman edenler; Peygamber’in evlerine yemeğe çağrılmaksızın ve vakitli vakitsiz girmeyin. Ama davet olunursanız; girin ve yemeği yeyince de lafa dalmadan dağılın. Bu haliniz, Peygamber’i üzüyordu, o da size bir şey söylemeye çekiniyordu. Allah ise hakkı söylemekten çekinmez. Peygamber’in eşlerinden bir şey istediğinizde; onu perde arkasından isteyin. Bu; sizin kalbleriniz için de, onların kalbleri için de daha temizdir. Allah’ın Rasulünü üzmeniz ve ondan sonra eşlerini nikahlamak asla caiz değildir. Çünkü bu; Allah katında büyük bir günahtır."},{"n":54,"t":"Bir şeyi açıklasanız da, gizleseniz de muhakkak ki Allah; her şeyi bilendir."},{"n":55,"t":"Peygamber’in eşlerine; babaları, oğulları, kardeşleri, erkek kardeşlerinin oğulları, kız kardeşlerinin oğulları, hizmetçi kadınları ve sağ ellerinin malik oldukları hususunda vebal yoktur. Ve Allah’tan korkun. Muhakkak ki Allah; her şeye şahid olandır."},{"n":56,"t":"Muhakkak ki Allah ve melekleri, Peygamber’e salat ederler. Ey iman edenler; siz de O’nun üzerine salavat getiriniz ve onun için selamet dileyin."},{"n":57,"t":"Muhakkak ki Allah’ı ve Rasulünü incitenlere Allah; dünya ve ahirette la’net etmiştir. Ve onlar için, horlayıcı bir azab hazırlamıştır."},{"n":58,"t":"Mü’min erkekleri ve mü’min kadınları yapmadıkları bir şeyle incitenler; doğrusu bir iftirayı ve apaçık bir günahı yüklenmişlerdir."},{"n":59,"t":"Ey peygamber; eşlerine, kızlarına ve mü’minlerin kadınlarına söyle: Üstlerine örtü alsınlar. Bu, onların tanınıp da incitilmemeleri için daha elverişlidir. Ve Allah; Gafur, Rahim olandır."},{"n":60,"t":"Andolsun ki münafıklar, kalblerinde hastalık bulunanlar, şehirde bozguncu haberler yayanlar, buna son vermezlerse; muhakkak seni onlarla mücadeleye çağırırız da sonra çevrende az bir zamandan fazla kalamazlar."},{"n":61,"t":"La’netlenmişlerdir. Nerede bulunurlarsa yakalanırlar ve hemen öldürülürler."},{"n":62,"t":"Allah’ın daha önceden geçenler hakkındaki sünnetidir. Sen, Allah’ın sünnetinde bir değişiklik bulamazsın."},{"n":63,"t":"İnsanlar sana kıyametten sorarlar. De ki: Onun bilgisi ancak Allah katındadır. Ne bilirsin, belki de o saat yakında oluverir."},{"n":64,"t":"Muhakkak ki Allah; kafirleri la’netlemiştir. Ve onlara çılgın alevler hazırlamıştır."},{"n":65,"t":"Orada temelli kalırlar, ne bir dost ve ne de bir yardımcı bulamazlar."},{"n":66,"t":"O gün, yüzleri ateşte çevrilirken; ne olurdu keşki Allah’a itaat etseydik, peygambere de itaat etseydik, derler."},{"n":67,"t":"Ve dediler ki: Rabbımız; biz büyüklerimize ve yöneticilerimize itaat etmiştik. Onlar da bizi yoldan saptırdılar."},{"n":68,"t":"Rabbımız; onlara, azabdan iki kat ver. Ve onları büyük bir la’netle la’netle."},{"n":69,"t":"Ey iman edenler: Musa’ya eziyet vermiş olanlar gibi olmayın. Nitekim Allah, onu söyledikleri şeyden uzak tutmuştu. Ve o, Allah katında değerli idi."},{"n":70,"t":"Ey iman edenler; Allah’tan korkun ve doğru söz söyleyin."},{"n":71,"t":"Ki O da işlerinizi düzeltsin ve günahlarınızı bağışlasın. Kim Allah’a ve Rasulüne itaat ederse; gerçekten büyük bir kurtuluşla kurtulmuştur"},{"n":72,"t":"Gerçekten Biz, emaneti; göklere, yeryüzüne ve dağlara sunduk da onlar bunu yüklenmekten çekindiler. Ve korkup titrediler. Onu insan yüklendi. Doğrusu insan; pek zalim ve pek cahil oldu."},{"n":73,"t":"Ta ki Allah; münafık erkekleri ve münafık kadınları, müşrik erkekleri ve müşrik kadınları azaba uğratsın. Mü’min erkeklerle, mü’min kadınların da tevbelerini kabul buyursun. Ve Allah; Gafur, Rahim olandır."}],[{"n":1,"t":"Hamd, O Allah’a ki; göklerde ve yerde bulunanlar kendisine aittir. Ahirette de hamd O’nadır. O; Hakim’dir, Habir’dir."},{"n":2,"t":"Yere gireni, oradan çıkanı, gökten ineni ve oraya yükseleni bilir. O; Rahim’dir, Gafur’dur."},{"n":3,"t":"Küfredenler dediler ki: Kıyamet saatı bize gelmeyecektir. De ki: Hayır, gaybı Rabbıma andolsun ki; o saat muhakkak size gelecektir. Göklerde ve yerde zerre kadar olanlar bile O’nun ilminin dışında değildir. Ondan daha küçüğü de, büyüğü de istisnasız, mutlaka apaçık kitabtadır."},{"n":4,"t":"İman etmiş olup da salih amel işleyenleri mükafatlandırması için. İşte onlara mağfiret ve cömertçe verilmiş bir rızık vardır."},{"n":5,"t":"Ayetlerimiz hakkında Bizi aciz bırakmaya yeltenenlere de, işte onlara çetin ve elim azab vardır."},{"n":6,"t":"Kendilerine ilim verilmiş olanlar görürler ki; sana Rabbından indirilmiş olan, hakkın kendisidir. Ve Aziz, Hamid olanın dosdoğru yoluna iletmektedir."},{"n":7,"t":"Küfretmiş olanlar dediler ki: Siz, didik didik parçalanıp dağıldığınız zaman muhakkak sizin yeni bir yaratılışta bulunacağınızı haber veren bir adamı size gösterelim mi?"},{"n":8,"t":"Allah’a karşı yalan mı uyduruyor, yoksa kendisinde bir delilik mi vardır? Hayır, ahirete inanmayanlar azabtadırlar, uzak bir sapıklık içindedirler."},{"n":9,"t":"Gökten ve yerden önlerinde ve arkalarında olanı görmüyorlar mı? Biz, istersek; onları yerin dibine geçirir veya üzerlerine gökten parçalar indiririz. Muhakkak ki bunda, Allah’a yönelen her kul için bir ayet vardır."},{"n":10,"t":"Andolsun ki; Davud’a, katımızdan lutuf ihsan ettik. Ey dağlar; onunla birlikte siz de tesbih edin ve kuşlar da. Ona demiri yumuşak kıldık."},{"n":11,"t":"Geniş zırhlar yap ve dokumasını sağlam tut, diye. Ve salih ameller işleyin. Muhakkak ki Ben; yapmakta olduğunuz şeyi görenim."},{"n":12,"t":"Süleyman’a da rüzgarı, gündüz estiğinde gidişi bir aylık mesafedir. Akşamleyin de gelişi bir aylık mesafedir. Ve onun için su gibi erimiş bakır akıttık. Cinnlerden de Rabbının izniyle elinin altında iş göreni verdik. Onlardan her kim, Bizim emrimizden çıkarsa; ona alevli ateşin azabından tattırırız."},{"n":13,"t":"Onlar; kalelerden, heykellerden, büyük havuzlara benzer çanaklardan ve taşınması güç kazanlardan ne dilerse kendisine yaparlardı. Ey Davud hanedanı; şükrederek çalışın. Kullarımdan pek azı şükredicidir."},{"n":14,"t":"Onun ölümüne hükmettiğimiz zaman; ölümünü onlara ancak değneğini yiyen canlı farkettirdi. Yere düşünce ortaya çıktı ki; eğer onlar gaybı bilselerdi, horlayıcı azab içinde kalmazlardı."},{"n":15,"t":"Sebe’liler için yurdlarında bir ayet vardı: Sağlı sollu iki bahçe. Rabbınızın rızkından yeyin ve O’na şükredin. Güzel bir belde ve bağışlayan bir Rabb."},{"n":16,"t":"Ama onlar, yüz çevirdiler. Böylece Biz de üzerlerine Arim selini gönderdik. Ve onların iki bahçesini, buruk yemişli, ılgınlık ve biraz da sedir ağacı bulunan iki bahçeye çevirdik."},{"n":17,"t":"İşte böylece küfretmiş olmalarından ötürü onları cezalandırdık. Biz, küfredenlerden başkasını cezalandırır mıyız?"},{"n":18,"t":"Onlarla mübarek kıldığımız kasabalar arasında, görünebilen kasabalar var ettik. Ve orada gezilecek belirli yerler yaptık. Orada geceleri ve gündüzleri emniyet içerisinde gezin."},{"n":19,"t":"Fakat onlar dediler ki: Rabbım, yolculuklarımızın arasını uzaklaştır. Ve kendi öz nefislerine zulmettiler. Biz de onları efsaneler kılıverdik, darmadağınık ettik. Muhakkak ki bunda; çok sabreden ve çok şükreden herkes için ayetler vardır."},{"n":20,"t":"Andolsun ki; İblis, onlar hakkındaki zannını doğru çıkarmış ve mü’minlerden bir topluluk hariç ona tabi olmuşlardır."},{"n":21,"t":"Halbuki İblis’in onlar üzerinde hiç bir hakimiyeti yoktu. Ancak Biz, ahirete inananlarla, ondan şüphede olanları belirlemek için yaptık. Ve Rabbın, her şeye Hafiz’dir."},{"n":22,"t":"De ki: Allah’tan başka, taptıklarınızı çağıran. Onlar ne göklerde, ne de yerde zerre kadar bir şeye sahib değildirler. Ve onların bu ikisinde ortaklığı da yoktur. O’nun bunlardan hiçbir yardımcısı da yoktur."},{"n":23,"t":"O’nun katında, kendisine izin verdiğinden başkası şefaat edemez. Nihayet kalblerindeki korku giderilince: Rabbınız ne dedi? dediler. Hakkı, dediler. Ve O, Aliyy’dir, Kebir’dir."},{"n":24,"t":"De ki: Sizi gökten ve yerden rızıklandıran kimdir? De ki: Allah’tır. Ya biz, ya siz; elbette doğru yolda veya apaçık bir sapıklıktadır."},{"n":25,"t":"De ki: Bizim işlediğimiz suçlardan siz sorumlu olmazsınız, biz de sizin yaptıklarınızdan sorumlu olmayız."},{"n":26,"t":"De ki: Rabbımız aramızı birleştirir, sonra da aramızda hak ile hükmeder. Fettah, Alim O’dur."},{"n":27,"t":"De ki: O’na, haşa ortaklar olarak iliştirdiklerinizi gösterin bana. Hayır, O; Allah’tır, Aziz’dir, Hakim’dir."},{"n":28,"t":"Biz, seni; ancak bütün insanlara müjdeci ve uyarıcı olarak gönderdik. Ne var ki insanların çoğu bilmezler."},{"n":29,"t":"Derler ki: Doğru sözlüler iseniz, bu vaad ne zamandır."},{"n":30,"t":"De ki: Sizin için bir günün miadı vardır. Ondan bir an ne geri kalabilirsiniz, ne de öne geçebilirsiniz."},{"n":31,"t":"Küfretmiş olanlar dediler ki: Biz kesin olarak ne bu Kur’an’a ne de ondan öncekilere inanırız. Bir görseydin, hani zalimler Rabblarının huzurunda dikilmişler, bir kısmı bir kısmına söz atıyordu. Güçsüz sayılanlar büyüklük taslayanlara diyorlardı ki: Siz olmasaydınız biz, muhakkak inananlar olurduk."},{"n":32,"t":"Büyüklük taslayanlar da güçsüz sayılanlara dediler ki: Size hidayet geldikten sonra biz mi sizi ondan alıkoyduk? Bilakis siz, suçlular idiniz."},{"n":33,"t":"Güçsüz sayılanlar da, büyüklük taslayanlara dediler ki: Haydi, gece ve gündüzün (işiniz) hilekarlıktı. Hani siz, bizim Allah’a küfretmemizi ve O’na eşler koşmamızı emrediyordunuz. Azabı gördüklerinde ettiklerine içleri yandı. Ve küfretmiş olanların boyunlarına demir halkalar vurduk. Yapmakta olduklarından başkasıyla mı, cezalandırılacaklardı."},{"n":34,"t":"Uyarıcı gönderdiğimiz her kasabanın varlıklıları dediler ki: Biz, sizin gönderildiğiniz şeyi inkar edenleriz."},{"n":35,"t":"Ve dediler ki: Biz, malca ve evladca daha çoğuz. Hem biz, azab edilecekler değiliz."},{"n":36,"t":"De ki: Rabbım dilediğinin rızkını genişletir ve kısar, ama insanların çoğu bilmezler."},{"n":37,"t":"Ne mallarınız, ne de çocuklarınız sizi, Bizim katımıza yaklaştıracak olan. Ancak iman edip salih amel işleyen kimselerin, işte onların yaptıklarına karşılık kkat kat mükafat vardır. Ve onlar, yüksek dereceler içinde emindirler."},{"n":38,"t":"Ayetlerimizde bizi aciz bırakmaya çalışanlar, işte onlar azabla yüzyüze bırakılmışlardır."},{"n":39,"t":"De ki: Rabbım, rızkı kullarından dilediğine genişletir ve kısar. Hangi şeyden de infak ederseniz; O, yerine koyar. O, rızık verenlerin en hayırlısıdır."},{"n":40,"t":"O gün; onların hepsini topladıktan sonra meleklere: Bunlar mıydı, size tapmakta olanlar? der."},{"n":41,"t":"Melekler: Tenzih ederiz Seni, bizim dostumuz onlar değil Sensin. Hayır, onlar cinnlere tapıyorlardı ve çoğu da onlara iman etmişlerdi, derler."},{"n":42,"t":"İşte bugün; bir kısmınız, bir kısmınız için ne bir fayda, ne de bir zarar verebilir. Zulmetmiş olanlara da deriz ki: Yalanladığınız ateşin azabını tadın."},{"n":43,"t":"Onlara apaçık ayetlerimiz okunduğu zaman dediler ki: Bu, ancak sizi atalarınızın ibadet etmekte olduğundan alıkoymak isteyen bir adamdır. Ve dediler ki: Bu da düpedüz bir uydurmadan başka bir şey değildir. Hak kendilerine geldiğinde hakkı inkar etmiş olanlar dediler ki: Bu, sadece apaçık bir büyüdür."},{"n":44,"t":"Halbuki biz, onlara okuyacakları bir kitab vermemiş ve senden önce onlara bir uyarıcı da göndermemiştik."},{"n":45,"t":"Kendilerinden öncekiler de yalanlamışlardı. Halbuki bunlar, onlara verdiklerimizin onda birine bile ulaşamamışlardı. Peygamberlerimi yalanladılar. Beni inkar nasıl olurmuş?"},{"n":46,"t":"De ki: Ben, size ancak Allah için ikişer ikişer ve teker teker kalmanızı, sonra arkadaşınızda bir delilik olmadığını iyice düşünmenizi öğütlerim. O, ancak şiddetli bir azabın öncesinde sizin için bir uyarıcıdır."},{"n":47,"t":"De ki: Sizden bir ücret istersem eğer, o sizin olsun. Benim ücretim, ancak Allah’a aittir. Ve O, her şeye şahid’dir."},{"n":48,"t":"De ki: Hiç şüphesiz Rabbim, hakkı koyar. O, görünmezlikleri çok iyi bilendir."},{"n":49,"t":"De ki: Hak gelmiştir. Artık batıl, ne yeniden bir şey ortaya koyabilir, ne de geri getirebilir."},{"n":50,"t":"De ki: Eğer ben, sapacak olsam, ancak kendi aleyhime sapmış olurum. Şayet hidayete erersem, Rabbimin bana vahyetmesinden ötürü ererim. O, muhakkak ki Semi’dir. Karib’tir."},{"n":51,"t":"Bir görsen, hani onlar korkmuşlardı. Artık kaçacak yerleri de yoktur, yakın bir yerde yakalanmışlardır."},{"n":52,"t":"O’na inandık demişlerdir. Ama uzak bir yerden nasıl kolayca imana ulaşılır?"},{"n":53,"t":"Halbuki daha önce onu inkar etmişlerdi. Uzak bir yerden gayba atıp tutuyorlardı."},{"n":54,"t":"Onlarla arzuladıkları şeylerin arasına bir engel konulmuştur. Daha önce benzerlerine yapıldığı gibi. Şüphesiz onlar şiddetli bir tereddüt ve şüphe içindedirler."}],[{"n":1,"t":"Hamd; göklerin ve yerin yaratanı, melekleri ikişer, üçer, dörder kanatlı elçiler kılan Allah’a mahsustue. Yaratmada dilediği kadar fazlalaştırır. Muhakkak ki Allah; her şeye kadirdir."},{"n":2,"t":"Allah’ın insanlar için açtığı rahmeti, tutacak yoktur. Tuttuğunu da O’ndan sonra gönderecek yoktur. Aziz, Hakim O’dur."},{"n":3,"t":"Ey insanlar; Allah’ın üzerinizdeki nimetini düşünün. Allah’tan başka gökten ve yerden sizi rızıklandıran bir yaratıcı var mıdır? O’ndan başka ilah yoktur. O halde nasıl çevriliyorsunuz?"},{"n":4,"t":"Eğer seni yalanlıyorlarsa; doğrusu senden önce de nice peygamberler yalanlanmıştır. İşler, ancak Allah’a döndürülür."},{"n":5,"t":"Ey insanlar; Allah’ın vaadi muhakkak haktır, dünya hayatı sizi aldatmasın. Ve o mağrur da Allah ile sizi aldatmasın."},{"n":6,"t":"Muhakkak ki şeytan, sizin düşmanınızdır. Öyleyse siz de onu düşman edinin. O, taraftarlarını ancak çılgın alevli ateşin yaranı olmaya çağırır."},{"n":7,"t":"Küfredenler, işte onlara şiddetli azab vardır. İman etmiş olup da salih ameller işleyenlere de, işte onlara mağfiret ve büyük ecir vardır."},{"n":8,"t":"Kötü işi kendisine süslendirilip de onu güzel gören bir midir? Muhakkak ki Allah, dilediğini saptırır, dilediğini de hidayete erdirir. Öuleyse onlara yanarak kendini harab etme. Şüphesiz ki Allah, onların yaptıklarını bilendir."},{"n":9,"t":"Allah, O’dur ki; bulutları yürüten rüzgarlar göndermiştir. Biz, onu ölü bir memlekete sürüp onunla yeri ölümünden sonra diriltiriz. İşte diriliş de böyledir."},{"n":10,"t":"Kim, izzet istiyorsa; izzet bütünüyle Allah’ındır. Güzel sözler O’na yükselir. Onu da salih amel yükseltir. Kötülükleri tuzak yapanlar için şiddetli bir azab vardır. Onların hilesi, boşa çıkar."},{"n":11,"t":"Allah, sizi topraktan yaratmıştır, sonra bir damla sudan sonra da sizleri çiftler olarak var etmiştir. Hiç bir dişi O’nun bilgisi olmadan hamile kalmaz ve doğum yapmaz. Bir ömürlünün çok yaşaması ve ömrünün azalması ancak kitabdadır. Muhakkak ki bu; Allah’ a pek kolaydır."},{"n":12,"t":"İki deniz bir olmaz. Şu; çok tatlıdır, susuzluğu keser içilmesi kolaydır. Şu ise tuzludur, acıdır. Her birinden taze et yersiniz ve giyeceğiniz süs eşyası çıkarırsınız. O’nun lutfundan aramanız ve şükretmeniz için gemilerin yara yara gittiklerini görürsünüz."},{"n":13,"t":"Gündüzü geceye girdirir, geceyi de gündüze girdirir. Güneşi ve ayı buyruğu altına almıştır, her biri belli bir süre için hareket eder. İşte bu, Rabbınız olan Allah’tır. Mülk O’nundur. O’ndan başka taptıklarınız ise hurma çekirdeğinin zarına bile malik değildirler."},{"n":14,"t":"Onları çağırsanız; çağrınızı işitmezler. İşitseler dahi size cevap veremezler. Kıyamet günü de şirk koşmanızı inkar ederler. Haberdar olan gibi, kimse sana haber veremez."},{"n":15,"t":"Ey insanlar; sizler, Allah’a muhtaçsınız. Allah ise Gani’dir, Hamid’dir"},{"n":16,"t":"İsterse; sizi giderir ve yepyeni bir yaratık getirir."},{"n":17,"t":"Bu, Allah’a göre güç değildir."},{"n":18,"t":"Günah işleyen hiç bir nefis; başkasının günahını çekmez. Yükü ağır bir kişi onun yüklenilmesini istese-yakını bile olsa ondan bir şey yüklenmez. Sen, ancak görmedikleri halde Rabblarından korkanları ve namazı kılmış olanları uyarırsın. Kim de arınırsa; ancak kendisi için arınmış olur ve dönüş, Allah’adır."},{"n":19,"t":"Kör ile gören eşit olmaz."},{"n":20,"t":"Ve karanlıklarla aydınlık da."},{"n":21,"t":"Gölgelik ile sıcaklık da."},{"n":22,"t":"Diriler ile ölüler de bir değildir. Muhakkak ki Allah; dilediğine işittirir. Sen; kabirlerde olanlara işittirecek değilsin."},{"n":23,"t":"Sen; ancak bir uyarıcısın."},{"n":24,"t":"Muhakkak ki Biz; seni, müjdeleyici ve uyarıcı olarak hak ile gönderdik. Hiç bir ümmet yoktur ki ona, bir uyarıcı gelmiş olmasın."},{"n":25,"t":"Şayet seni yalanlıyorlarsa; onlardan öncekiler de yalanlamışlardı. Peygamberleri, onlara apaçık deliller, sahifeler ve aydınlatıcı kitablarla gelmişlerdi."},{"n":26,"t":"Sonra o küfretmiş olanları yakaladım. Beni inkar etmek nasılmış?"},{"n":27,"t":"Görmez misin ki; Allah, gökten su indirmiştir. Onunla Biz, türlü türlü renkte meyveler çıkarmışızdır. Dağlardan da beyaz, kırmızı, siyah ve türlü renkte yollar yaptık."},{"n":28,"t":"İnsanlardan da, yerde yürüyen canlılardan ve davarlardan da böyle renkleri değişik değişik olanlar vardır. Allah’tan ancak bilgin kulları korkar. Muhakkak ki Allah; Aziz’dir, Gafur’dur."},{"n":29,"t":"Şüphesiz ki Allah’ın kitabını okuyanlar, namaz kılanlar ve kendilerine rızık olarak verdiklerimizden gizli, açık infak etmekte bulunanlar; bitmez tükenmez bir ticaret umabilirler."},{"n":30,"t":"Mükafatlarını Allah’ın tam vermesi ve onlara lutfundan artırması içindir. Muhakkak ki O; Gafur’dur, Şekur’dur."},{"n":31,"t":"Kendisinden öncekileri tasdik eden kitabdan sana vahyettiğimiz, hakkın kendisidir. Şüphesiz ki Allah, kulları için Habir’dir, Basir’dir."},{"n":32,"t":"Sonra Biz; kitabı, kullarımızdan seçtiklerimize miras kıldık. Onlardan kimi nefsine zulmedicidir, kimi de muktesiddir. Kimi ise Allah’ın izni ile hayırlara koşandır. İşte bu; büyük lutfun kendisidir."},{"n":33,"t":"Adn cennetleri. Oraya girerler. Orada altun bilezikler ve incilerle süslenirler ve orada elbiseleri de ipektendir."},{"n":34,"t":"Derler ki: Hamdolsun bizden üzüntüyü gideren Allah’a. Muhakkak ki Rabbımız; elbette Gafur’dur, Şekur’dur."},{"n":35,"t":"Ki O; lutfuyla bizi kalınacak diyara yerleştirdi. Orada bize ne bir yorgunluk dokunacaktır, ne de bıkkınlık gelecektir."},{"n":36,"t":"Küfredenlere gelince; cehennem ateşi onlar içindir. Aleyhlerine hüküm verilmez ki ölsünler. Onlardan cehennemin azabı da hafifletilmez. İşte Biz; her küfredeni böyle cezalandırırız."},{"n":37,"t":"Onlar orada bağırışırlar; Rabbımız, bizi çıkar da yapageldiklerimizden farklı olarak salih amel işleyelim. Öğüt alacak kişinin öğüt alacağı kadar bir süre sizi yaşatmadık mı? Ve size uyarıcı da gelmişti. Öyleyse azabı tadın. Zalimler için hiç bir yardımcı yoktur."},{"n":38,"t":"Muhakkak ki Allah; göklerin ve yerin gaybını bilendir. Şüphesiz ki O; göğüslerde olanı da bilicidir."},{"n":39,"t":"O’dur; sizi, yeryüzünde halifeler kılmış olan. Kim, küfrederse; küfrü kendi aleyhinedir. Kafirlerin küfrü Rabbları katında ancak gazabı artırır. Kafirlerin küfrü onlara hüsrandan başka bir şeyi artırmaz."},{"n":40,"t":"De ki: Allah’tan başka taptığınız ortaklarınızı gördünüz mü? Yeryüzünde ne yaratmışlardır gösterin bana. Yoksa onların ortaklığı göklerde midir? Yoksa onlara bir kitab verdik de onlar bundan bir delile mi dayanıyorlar? Hayır, o zalimler; birbirine ancak aldatıcı şeyler vaad ederler."},{"n":41,"t":"Muhakkak ki zail olmasınlar diye gökleri ve yeri tutan Allah’tır. Eğer zail olurlarsa, andolsun ki; bundan sonra onları kimse tutamaz. Şüphesiz ki O; Halim, Gafur olandır."},{"n":42,"t":"Var güçleriyle Allah’a yemin ettiler ki; kendilerine bir uyarıcı gelecek olursa; muhakkak ki, ümmetlerin herhangi birinden daha doğru yolda olacaklardır. Fakat kendilerine bir uyarıcı gelince; onların sadece nefretlerini artırdı."},{"n":43,"t":"Yeryüzünde büyüklenerek ve kötü düzen kurarak. Halbuki kötü düzen ancak ehline zarar verir. Öncekilerin sünnetlerini görmezler mi? Sen, Allah’ın sünnetinde bir değişiklik bulamazsın. Sen, Allah’ın sünnetinde bir başkalaşma da bulamazsın."},{"n":44,"t":"Yeryüzünde gezip dolaşmazlar mı ki; kendilerinden öncekilerin akıbetlerinin nasıl olduğunu görsünler. Hem onlar, kendilerinden daha da kuvvetliydiler. Göklerde de yerde de Allah’ı aciz bırakacak hiç bir şey yoktur. Şüphesiz ki O; Alim, Kadir olandır."},{"n":45,"t":"Şayet Allah; insanları kazandıklarıyla muaheze etmiş olsaydı; onun üstünde hiç bir canlı bırakmazdı. Fakat onları belli bir süreye kadar te’hir eder. Süreleri geldiği zaman muhakkak ki Allah; kulları için Basir olandır."}],[{"n":1,"t":"Ya, Sin."},{"n":2,"t":"Kur’an-ı Hakim’e andolsun ki;"},{"n":3,"t":"Sen, elbette gönderilmiş peygamberlerdensin,"},{"n":4,"t":"Sırat-ı Müstakim üzere."},{"n":5,"t":"Bu; Aziz, Rahim’in indirmesidir."},{"n":6,"t":"Babaları uyarılmadığından gaflet içinde kalmış bir kavmi uyarman için."},{"n":7,"t":"Andolsun ki; onların, çoğunun üzerine, söz hak olmuştur. Onlar, artık iman etmezler."},{"n":8,"t":"Doğrusu Biz; onların boyunlarına, çenelerine kadar varan demir halkaları geçirdik. Bunun için artık başları yukarı kalkıktır."},{"n":9,"t":"Önlerinden bir sed ve arkalarından da bir sed çekmişizdir. Gözlerini perdelemişizdir. Bu yüzden artık göremezler."},{"n":10,"t":"Onları ister korkut, ister korkutma; onlar için birdir, iman etmezler."},{"n":11,"t":"Sen, ancak zikre ittiba eden ve görmeden Rahman’dan korkanı uyarırsın. Artık ona mağfiret ve yüce mükafatı müjdele."},{"n":12,"t":"Şüphesiz ki ölüleri, Biz diriltiriz Biz. İşlediklerini ve geride bıraktıklarını Biz yazarız. Biz, her şeyi apaçık bir kitabda saymışızdır."},{"n":13,"t":"Onlara misal olarak şu kasaba halkını anlat: Hani oraya elçiler gelmişlerdi."},{"n":14,"t":"Hani onlara iki elçi göndermiştik de bunları yalanlamışlardı. Bunun üzerine Biz de üçüncüsüyle desteklemiştik de: Biz, size gönderilmiş elçileriz, demişlerdi."},{"n":15,"t":"Onlar da; siz, ancak bizim gibi birer insansınız. Rahman, size hiç bir şey indirmemiştir. Siz, sadece yalan söylüyorsunuz, demişlerdi."},{"n":16,"t":"Dediler ki: Rabbımız bilir ki biz, muhakkak size gönderilmiş elçileriz."},{"n":17,"t":"Bize düşen, sadece apaçık tebliğdir."},{"n":18,"t":"Doğrusu, sizin yüzünüzden uğursuzluğa uğradık. Vazgeçmezseniz andolsun ki sizi taşlayacağız. Ve bizden size, elim bir azab dokunacaktır, dediler."},{"n":19,"t":"Dediler ki: Uğursuzluğunuz sizinledir. Size öğüt verildi diye mi? Hayır, siz; çok aşırı giden bir kavimsiniz."},{"n":20,"t":"Şehrin ötebaşından bir adam koşarak geldi ve şöyle dedi: Ey kavmim; gönderilmiş bulunan elçilere uyun."},{"n":21,"t":"Sizden hiç bir ücret istemeyenlere uyun. Onlar, hidayete erdirilmişlerdir."},{"n":22,"t":"Ben, beni yaratmış olana neden kulluk etmeyeyim? Siz de O’na döndürüleceksiniz."},{"n":23,"t":"Ben, O’ndan başka tanrılar mı edinirim? Eğer Rahman bana bir zarar vermek isterse; onların şefaatı bana hiç bir fayda sağlamaz ve beni kurtarmaz da."},{"n":24,"t":"O takdirde ben de gerçekten apaçık bir sapıklık içerisinde olurum."},{"n":25,"t":"Şüphesiz ki ben, Rabbınıza inandım. Artık beni dinleyin."},{"n":26,"t":"Cennete gir, denilince, dedi ki: Keşki kavmim bilir olsaydı;"},{"n":27,"t":"Rabbımın beni bağışladığını ve beni ikram edilenlerden kıldığını."},{"n":28,"t":"Ondan sonra kavminin üzerine gökten bir ordu indirmedik, zaten indirecek de değildik."},{"n":29,"t":"Sadece, bir tek çığlık oldu. Ve onlar hemen sönüp gittiler."},{"n":30,"t":"Yazıklar olsun o kullara ki; kendilerine bir peygamber gelmeyedursun onu hemen alaya alırlardı."},{"n":31,"t":"Görmüyorlar mı ki; kendilerinden önce nice nesilleri helak ettik. Ve onlar, bir daha kendilerine dönemezler."},{"n":32,"t":"Hepsi de muhakkak toptan huzurumuza getirileceklerdir."},{"n":33,"t":"Ölü toprak, onlar için bir ayettir. Biz, onu dirilttik ve ondan taneler çıkardık, ondan yemektedirler."},{"n":34,"t":"Ve orada hurmadan, üzümlerden bahçeler var ettik. Orada pınarlar fışkırttık."},{"n":35,"t":"Ki, ürününden ve ellerinin emeğinden yesinler. Hala şükretmezler mi?"},{"n":36,"t":"Yerin bitirdiklerinden, kendi nefislerinden ve daha bilmedikleri şeylerden, bütün çiftleri yaratanı tenzih ederiz."},{"n":37,"t":"Gece de onlar için bir ayettir. Gündüzü ondan sıyırırız da karanlıkta kalıverirler."},{"n":38,"t":"Güneş de kendi yörüngesinde akıp gider. Bu; Aziz, Alim’in takdiridir."},{"n":39,"t":"Ay için de konaklar ta’yin etmişizdir. Sonunda eski hurma dalına döner."},{"n":40,"t":"Güneşe; aya ulaşmak düşmez. Gece de; gündüzü geçecek değildir. Her birisi, bir yörüngede yüzerler."},{"n":41,"t":"Soylarını dolu gemiyle taşımış olmamız da onlar için bir ayettir."},{"n":42,"t":"Ve kendilerine bunun gibi nice binecek şeyler yapmamız da."},{"n":43,"t":"Dilesek; onları suda boğardık da ne kurtaran bulunurdu, ne de kurtulabilirlerdi."},{"n":44,"t":"Ama katımızdan bir rahmet ve bir süreye kadar geçinme başka."},{"n":45,"t":"Onlara önünüzde ve arkanızda bulunanlardan sakının. Belki merhamet olunursunuz, denildiğinde."},{"n":46,"t":"Kendilerine Rabblarının ayetlerinden bir ayet geldiğinde sadece yüz çevirenler olmuşlardır."},{"n":47,"t":"Onlara; Allah’ın size rızık olarak verdiklerinden infak edin, denildiğinde; o küfredenler iman etmiş olanlara dediler ki: Dilediği takdirde Allah’ın doyuracağı kimseyi biz mi doyuralım? Doğrusu siz, ancak apaçık bir sapıklık içerisindesiniz."},{"n":48,"t":"Ve derler ki: Şayet siz sadıklardan iseniz, bu vaad ne zamandır?"},{"n":49,"t":"Onlar; sadece bir tek çığlığı beklerler ki çekişip dururlarken o, ansızın kendilerini yakalayıverir."},{"n":50,"t":"Artık ne vasiyet edebilirler, ne de ailelerine dönebilirler."},{"n":51,"t":"Sur’a üflendi. Bir de bakarsınız ki onlar kabirlerinden koşarak Rabblarına doğru çıkmaktadırlar."},{"n":52,"t":"Derler ki: Yazıklar olsun bize, yattığımız yerden kim kaldırdı bizi? İşte bu, Rahman’ın vaadetmiş olduğudur. Ve peygamberler doğru söylemişlerdi."},{"n":53,"t":"Sadece bir tek çığlık olmuştur. Ve bir de bakarsınız ki; onların hepsi birden huzurumuza getirilmişlerdir."},{"n":54,"t":"Artık bugün, kimseye hiç bir haksızlıkta bulunulmaz. Ve siz, yapar olduklarınızdan başkasıyla cezalandırılmazsınız."},{"n":55,"t":"Muhakkak ki bugün cennet ashabı bir meşguliyet içinde mutlu ve sevinçlidirler."},{"n":56,"t":"Onlar ve eşleri gölgeliklerde, tahtlar üzerinde yaslanmışlardır."},{"n":57,"t":"Orada meyveler onlarındır. Ve her istedikleri kendilerinindir."},{"n":58,"t":"Rahim Rabblarından bir de; selam, sözü."},{"n":59,"t":"Ayrılın bugün, ey suçlular."},{"n":60,"t":"Ey Ademoğulları; Ben, size; şeytana tapmayın, o muhakkak ki sizin apaçık bir düşmanınızdır, diye ahdetmedim mi?"},{"n":61,"t":"Ve; Bana kulluk edersiniz, işte bu, dosdoğru yoldur, diye."},{"n":62,"t":"Andolsun ki; o, sizden birçok nesilleri saptırmıştı. Hala akletmez misiniz?"},{"n":63,"t":"İşte bu, size vaadolunan cehennemdir."},{"n":64,"t":"Küfretmekte olduğunuzdan dolayı bugün girin oraya."},{"n":65,"t":"Bugün, onların ağızlarını mühürleriz. Bizimle elleri konuşur ve yapmakta oldukları şeye ayakları şehadet eder."},{"n":66,"t":"Biz isteseydik; onların gözlerini kör ederdik de yolda koşuşup kalırlardı. Ama nasıl göreceklerdi ki."},{"n":67,"t":"Biz isteseydik; onları oldukları yerde dondururduk da ileri geçmeye güçleri yetmezdi. Geri de dönemezlerdi."},{"n":68,"t":"Kimi de uzun ömürlü yaparsak; onun yaratılışını tersine çeviririz. Hala akletmezler mi?"},{"n":69,"t":"Biz, ona şiir öğretmedik. Zaten ona gerekmezdi de. Bu, ancak bir zikirdir. Ve apaçık bir Kur’an’dır."},{"n":70,"t":"Diri olanları uyarsın ve kafirlerin üzerine söz hak olsun diye."},{"n":71,"t":"Görmezler mi ki; ellerimizin yaptıklarından onlar için hayvanlar yarattık. Kendileri bunlara sahip bulunmaktadırlar."},{"n":72,"t":"Ve onları, kendilerinin buyruğuna verdik. Onlardan kimisi binekleridir, kimisinden de yerler."},{"n":73,"t":"Onlarda kendileri için faydalar ve içecekler vardır. Hala şükretmezler mi?"},{"n":74,"t":"Kendilerine yardımları dokunur diye Allah’tan başka ilahlar edindiler."},{"n":75,"t":"Halbuki onlar, kendilerine yardım edemezler. Sadece kendileri onlar için hazırlanmış askerlerdir."},{"n":76,"t":"Onların sözü seni üzmesin. Şüphesiz ki Biz; onların gizlediklerini de, açıkladıklarını da biliriz."},{"n":77,"t":"İnsan; Bizim kendisini bir damla sudan yarattığımızı görmedi mi ki; şimdi apaçık bir düşmandır."},{"n":78,"t":"Kendi yaratılışını unutarak Bize bir misal getirdi de; çürümüşken kemikleri diriltecek kimdir? dedi."},{"n":79,"t":"De ki: Onları ilk defa yaratan, diriltecektir. O, her yaratmayı bilendir."},{"n":80,"t":"Yemyeşil ağaçtan size ateş çıkartan O’dur. Siz ondan hemen yakıverirsiniz."},{"n":81,"t":"Gökleri ve yeri yaratmış olan, kendileri gibisini yaratmaya kadir olmaz mı? Elbette O; Hallak’tır, Alim’dir."},{"n":82,"t":"Bir şeyi murad ettiği zaman, O’nun emri sadece ona; ol, demektir. O da oluverir."},{"n":83,"t":"Her şeyin hükümranlığı elinde olanı, tesbih ederiz. Ve siz, O’na döndürüleceksiniz."}],[{"n":1,"t":"Andolsun; saf bağlayıp duranlara."},{"n":2,"t":"Haykırıp sürenlere."},{"n":3,"t":"Zikir okumakta olanlara."},{"n":4,"t":"Ki, sizin ilahınız muhakkak ki bir tektir."},{"n":5,"t":"Göklerin, yerin ve ikisinin arasında bulunanların Rabbıdır. Ve doğruların da Rabbıdır."},{"n":6,"t":"Doğrusu Biz; dünya göğünü bir süsle, yıldızlarla süsledik."},{"n":7,"t":"Ve onu inatçı her şeytandan koruduk."},{"n":8,"t":"Onlar Mele-i Ala’yı dinleyemezler ve her yönden sürülerek atılırlar."},{"n":9,"t":"Kovularak. Ve onlar için sürekli bir azab vardır."},{"n":10,"t":"Ancak çalıp çırpan olursa; onu da hemen delip geçen yakıcı bir alev takib eder."},{"n":11,"t":"Onlara sor; yaratış bakımından kendileri mi daha zordur, yoksa bizim yaratmış olduklarımız mı? Doğrusu Biz; onları cıvık bir çamurdan yarattık."},{"n":12,"t":"Hayır, sen; şaşırıp kaldın, onlarsa alay edip duruyorlar."},{"n":13,"t":"Kendilerine öğüt verildiğinde ise öğüt dinlemezler."},{"n":14,"t":"Bir ayet gördüklerinde, onu eğlenceye alırlar."},{"n":15,"t":"Ve derler ki: Bu, ancak apaçık bir büyüdür."},{"n":16,"t":"Öldüğümüzde, toprak ve kemik olduğumuzda mı, biz mi, diriltileceğiz?"},{"n":17,"t":"Veya önceki babalarımız mı?"},{"n":18,"t":"De ki: Evet, hem de hor ve hakir olarak."},{"n":19,"t":"O, sadece bir tek çığlıktır ki onların birden bire gözleri açılıverecektir."},{"n":20,"t":"Ve dediler ki: Vay bize, bu; din günüdür."},{"n":21,"t":"Bu, ayırdetme günüdür ki siz, onu yalanlamıştınız."},{"n":22,"t":"Zulmetmiş olanları ve onların eşlerini toplayın. Onların taptıklarını da;"},{"n":23,"t":"Allah’tan başka. Ve onları cehennem yoluna götürün."},{"n":24,"t":"Durdurun onları. Çünkü onlar sorumludurlar."},{"n":25,"t":"Size ne oldu ki birbirinizle yardımlaşmıyorsunuz?"},{"n":26,"t":"Hayır; onlar bugün, teslim olmuşlardır."},{"n":27,"t":"Bir kısmı bir kısmına dönerek soruştururlar."},{"n":28,"t":"Ve derler ki: Doğrusu siz, bize sağdan gelirdiniz."},{"n":29,"t":"Onlar da derler ki: Hayır, siz zaten iman edenler olmamıştınız."},{"n":30,"t":"Bizim, sizin üstünüzde bir hakimiyetimiz de yoktu. Aksine siz, azgınlar topluluğu oldunuz."},{"n":31,"t":"Bunu için Rabbımızın sözü, üzerimize hak oldu. Doğrusu biz, tadacak olanlarız."},{"n":32,"t":"Sizi azdırdık; çünkü biz de azgınlardan olmuştuk."},{"n":33,"t":"Artık o gün onlar, muhakkak ki azabda ortaktırlar."},{"n":34,"t":"Biz, suçlulara muhakkak böyle yaparız."},{"n":35,"t":"Çünkü onlara; Allah’tan başka ilah yoktur, denildiğinde, büyüklük taslarlardı."},{"n":36,"t":"Ve derlerdi ki: Deli bir şair için mi ilahlarımızı terkedeceğiz?"},{"n":37,"t":"Hayır, O; hakkı getirmiş ve peygamberleri tasdik etmişti."},{"n":38,"t":"Elbette siz, elim azabı tadacaksınız."},{"n":39,"t":"Ve yapmış olduğunuzdan başkasıyla cezalandırılmayacaksınız."},{"n":40,"t":"Ancak Allah’ın ihlasa erdirilmiş kulları müstesna."},{"n":41,"t":"İşte onlar için, ma’lum bir rızık vardır."},{"n":42,"t":"Ve meyveler. Onlar, ikram edilenlerdir;"},{"n":43,"t":"Naim cennetlerinde,"},{"n":44,"t":"Karşılıklı tahtlar üzerinde."},{"n":45,"t":"Kendilerine kaynaktan doldurulmuş kadehler sunulur,"},{"n":46,"t":"Ki bembeyazdır, içenlere zevk verir."},{"n":47,"t":"Başağrısı yoktur onda ve sarhoş da etmez."},{"n":48,"t":"Yanlarında el değmemiş ve bakışlarını yalnız eşlerine çevirmiş iri gözlüler vardır."},{"n":49,"t":"Sanki onlar, saklı bir yumurta gibidirler."},{"n":50,"t":"Bir kısmı bir kısmına dönerek soruştururlar."},{"n":51,"t":"İçlerinden bir sözcü der ki: Benim bir dostum vardı."},{"n":52,"t":"Derdi ki: Sen de mi tasdik edenlerdensin?"},{"n":53,"t":"Öldüğümüz, toprak ve bir yığın kemik olduğumuz zaman mı, biz mi ceza göreceğiz?"},{"n":54,"t":"Siz, onu bilir misiniz? dedi."},{"n":55,"t":"Bir bakar ve onu cehennemin ortasında görmüştür."},{"n":56,"t":"Dedi ki: Allah’a andolsun ki; az kaldı beni de mahvedecektin."},{"n":57,"t":"Rabbımın lutfu olmasaydı, ben de oraya götürülenlerden olacaktım."},{"n":58,"t":"Biz, bir daha ölmeyeceğiz değil mi?"},{"n":59,"t":"Ancak ilk ölümümüz müstesna, ve azablandırılmayacağız da."},{"n":60,"t":"İşte bu, şüphesiz büyük kurtuluştur."},{"n":61,"t":"Çalışanlar bunun gibisi için çalışsınlar."},{"n":62,"t":"Konak yeri olarak bu mu hayırlıdır, yoksa zakkum ağacı mı?"},{"n":63,"t":"Doğrusu Biz, onu; zalimler için bir fitne yaptık."},{"n":64,"t":"O, cehennemin dibinde çıkan bir ağaçtır."},{"n":65,"t":"Tomurcukları şeytanların başları gibidir."},{"n":66,"t":"Onlar muhakkak ondan yiyecekler ve karınlarını onunla dolduracaklardır."},{"n":67,"t":"Sonra onlar için, üzerine kaynar su katılmış içkiler de vardır."},{"n":68,"t":"Sonra onların dönüşü muhakkak, yine cehennemedir."},{"n":69,"t":"Doğrusu onlar, babalarını sapıklar olarak bulmuşlardı."},{"n":70,"t":"Yine de onların izlerinde koşturuluyorlardı."},{"n":71,"t":"Andolsun ki; onlardan önce geçenlerin çoğu da sapıtmıştı."},{"n":72,"t":"Ve andolsun ki; onlara, uyarıcılar göndermiştik."},{"n":73,"t":"Bir bak; uyarılanların akıbeti nice oldu."},{"n":74,"t":"Ancak Allah’ın ihlasa erdirilmiş kulları müstesna."},{"n":75,"t":"Andolsun ki; Nuh, Bize niyaz etmişti. Ne güzel icabet edenleriz Biz."},{"n":76,"t":"Onu ve ailesini büyük sıkıntıdan kurtarmıştık."},{"n":77,"t":"Ve onun soyunu süreklilerin kendisi kıldık."},{"n":78,"t":"Sonrakiler arasında ona da bıraktık."},{"n":79,"t":"Alemler içinde selam olsun Nuh’a."},{"n":80,"t":"Biz, ihsan edenleri; işte böyle mükafatlandırırız."},{"n":81,"t":"Doğrusu o; Bizim inanmış kullarımızdandı."},{"n":82,"t":"Sonra diğerlerini suda boğduk."},{"n":83,"t":"Muhakkak ki İbrahim de onun yolunda olanlardandı."},{"n":84,"t":"Çünkü Rabbına selim bir kalb ile gelmişti."},{"n":85,"t":"Hani babasına ve kavmine demişti ki: Neye ibadet ediyorsunuz?"},{"n":86,"t":"Yalancılık etmek için mi, Allah’tan başka tanrılar mı istiyorsunuz?"},{"n":87,"t":"Alemlerin Rabbı hakkındaki zannınız nedir?"},{"n":88,"t":"Derken yıldızlara bir göz atarak baktı."},{"n":89,"t":"Doğrusu ben, rahatsızım, dedi."},{"n":90,"t":"Bunun üzerine arkalarını dönüp uzaklaştılar."},{"n":91,"t":"O da, tanrılarına yönelip dedi ki: Yemiyor musunuz?"},{"n":92,"t":"Ne o, konuşmuyor musunuz?"},{"n":93,"t":"Nihayet üzerlerine yürüyüp sağıyla vurdu."},{"n":94,"t":"Bunun üzerine koşarak ona geldiler."},{"n":95,"t":"Dedi ki: Yonttuğunuz şeylere mi tapıyorsunuz?"},{"n":96,"t":"Halbuki sizi de, yaptıklarınızı da Allah yaratmıştır."},{"n":97,"t":"Haydin; dediler, onun için bir bina yapın da onu alevli ateşe atın."},{"n":98,"t":"Ona hile yapmak istediler. Biz de onları en aşağılar kıldık."},{"n":99,"t":"O, dedi ki: Doğrusu ben, Rabbıma gidiyorum. O beni hidayete erdirir."},{"n":100,"t":"Rabbım, bana salihlerden ihsan et."},{"n":101,"t":"Biz de ona, hilim sahibi bir oğul müjdeledik."},{"n":102,"t":"O, kendisinin yanısıra yürümeye başlayınca dedi ki: Oğulcuğum; doğrusu ben, rüyada iken seni boğazladığımı görüyorum. Bir bak, ne dersin? O da dedi ki: Babacığım; sana emrolunanı yap. İnşallah beni sabredenlerden bulursun."},{"n":103,"t":"İkisi de teslim olunca, babası; oğlunu alnı üzere yatırdı."},{"n":104,"t":"Biz, ona şöyle seslendik: Ey İbrahim;"},{"n":105,"t":"Sen rü’yayı gerçekleştirdin. Elbette Biz, ihsan edenleri böylece mükafatlandırırız."},{"n":106,"t":"Muhakkak ki bu, apaçık bir imtihandı."},{"n":107,"t":"Ve ona fidye olarak büyük bir kurbanlık verdik."},{"n":108,"t":"Sonrakiler arasında ona da bıraktık."},{"n":109,"t":"Selam olsun İbrahim’e."},{"n":110,"t":"Biz, ihsan edenleri işte böyle mükafatlandırırız."},{"n":111,"t":"Muhakkak ki o, mü’min kullarımızdandı."},{"n":112,"t":"Ona salihlerden bir peygamber olmak üzere İshak’ı müjdeledik."},{"n":113,"t":"Onu da, İshak’ı da mübarek kıldık. O ikisinin soyundan ihsan eden de vardır, kendisine açıkça zulmeden de."},{"n":114,"t":"Andolsun ki; Musa ve Harun’a da lutuf da bulunmuştuk."},{"n":115,"t":"O ikisini de, kavimlerini de büyük bir sıkıntıdan kurtarmıştık."},{"n":116,"t":"Onlara yardım etmiştik de galibler onlar oldu."},{"n":117,"t":"Her ikisine de apaçık anlaşılan kitab vermiştik."},{"n":118,"t":"Ve onları doğru yola hidayet etmiştik."},{"n":119,"t":"Sonrakiler arasında; ikisini de bıraktık."},{"n":120,"t":"Musa ve Harun’a selam olsun."},{"n":121,"t":"Muhakkak ki Biz, ihsan edenleri böyle mükafatlandırırız."},{"n":122,"t":"Doğrusu o ikisi de, mü’min kullarımızdandı."},{"n":123,"t":"Muhakkak ki İlyas da peygamberlerdendi."},{"n":124,"t":"Hani kavmine demişti ki: Siz, hiç korkmaz mısınız?"},{"n":125,"t":"Yaratıcıların en güzelini bırakıp da Ba’l’e mi taparsınız?"},{"n":126,"t":"Sizin de Rabbınız, önceki babalarınızın da Rabbı olan Allah’ı."},{"n":127,"t":"Fakat bunlar, onu yalanlamışlardı. Muhakkak ki onlar da cehenneme götürüleceklerdir."},{"n":128,"t":"Yalnız Allah’ın ihlasa erdirilmiş kulları müstesna."},{"n":129,"t":"Sonrakiler arasında ona da bıraktık."},{"n":130,"t":"Selam olsun İlyas’a."},{"n":131,"t":"İşte Biz, ihsan edenleri böyle mükafatlandırırız."},{"n":132,"t":"Muhakkak ki o, mü’min kullarımızdandı."},{"n":133,"t":"Muhakkak ki Lut da peygamberlerdendi."},{"n":134,"t":"Hani Biz, onu ve ailesini topluca kurtarmıştık."},{"n":135,"t":"Geridekiler arasında kalan bir kocakarı müstesna."},{"n":136,"t":"Sonra diğerlerini yerle bir etmiştik."},{"n":137,"t":"Doğrusu siz, sabahleyin onlara uğrar üzerlerinden geçersiniz."},{"n":138,"t":"Geceleyin de. Hala akletmez misiniz?"},{"n":139,"t":"Muhakkak ki Yunus da peygamberlerdendi."},{"n":140,"t":"Hani o, dolu bir gemiye kaçmıştı."},{"n":141,"t":"Kur’a çekmişti de yenilenlerden olmuştu."},{"n":142,"t":"Yenilgiye uğramışken, bir balık yutmuştu onu."},{"n":143,"t":"Eğer o, tesbih edenlerden olmasaydı."},{"n":144,"t":"Tekrar diriltilecekleri güne kadar onun karnında kalacaktı."},{"n":145,"t":"Rahatsız bir halde iken Biz, onu açıklık bir yere attık."},{"n":146,"t":"Ve onun için geniş yapraklı bir bitki yetiştirdik."},{"n":147,"t":"Onu yüz bin veya daha fazlasına elçi gönderdik."},{"n":148,"t":"Nihayet ona inandılar, Biz de onları bir süreye kadar geçindirdik."},{"n":149,"t":"Şimdi sen, onlara sor, kızlar senin Rabbının da, oğlanlar onların mı?"},{"n":150,"t":"Yoksa, Biz, melekleri dişi olarak yarattık da onlar buna şahid miydiler?"},{"n":151,"t":"İyi bilin ki; gerçekten onlar, iftiralarından ötürü şöyle diyorlar:"},{"n":152,"t":"Allah doğurdu. Hiç şüphesiz onlar yalancılardır."},{"n":153,"t":"Kızları, oğullara tercih mi etmiş?"},{"n":154,"t":"Ne oluyor size, nasıl hükmediyorsunuz?"},{"n":155,"t":"Hiç düşünmüyor musunuz?"},{"n":156,"t":"Yoksa sizin apaçık bir deliliniz mi var?"},{"n":157,"t":"Eğer sadıklardan iseniz kitabınızı getirin."},{"n":158,"t":"O’nunla cinnler arasında bir neseb bağı uydurdular. Andolsun ki; cinnler de, onların götürüleceklerini bilmektedirler."},{"n":159,"t":"Allah, onların nitelendirdiklerinden münezzehtir."},{"n":160,"t":"Allah’ın ihlasa erdirilmiş kulları müstesna."},{"n":161,"t":"Muhakkak ki sizler ve taptıklarınız,"},{"n":162,"t":"O’na karşı hiç fitneleyebilecek değilsiniz."},{"n":163,"t":"Tabii cehenneme girecek olan müstesna."},{"n":164,"t":"Bizim her birimizin belirli bir makamı vardır."},{"n":165,"t":"Ve muhakkak ki biz; saf bağlayıp duranlarız."},{"n":166,"t":"Ve muhakkak ki biz; tesbih edenleriz."},{"n":167,"t":"Onlar her ne kadar şöyle diyor idiyseler de;"},{"n":168,"t":"Öncekilerde olduğu gibi bizde de bir zikir bulunsaydı;"},{"n":169,"t":"Biz de elbet Allah’ın ihlasa erdirilmiş kulları olurduk."},{"n":170,"t":"Sonunda O’na küfrettiler, ama ilerde bileceklerdir."},{"n":171,"t":"Andolsun ki; Bizim, gönderilen kullarımız hakkında sözümüz geçmiştir:"},{"n":172,"t":"Onlar muhakkak yardım görenlerdir."},{"n":173,"t":"Ve şüphesiz ki Bizim askerlerimiz; onlar galiblerdir."},{"n":174,"t":"Sen, bir süreye kadar onlardan yüz çevir."},{"n":175,"t":"Gözetleyiver onları, ilerde göreceklerdir."},{"n":176,"t":"Yoksa azabımızı mı çabucak istiyorlar?"},{"n":177,"t":"Fakat o, yurtlarına indiğinde uyarılanların sabahı ne kötü olur."},{"n":178,"t":"Sen, bir süreye kadar onlardan yüz çevir."},{"n":179,"t":"Gözetleyiver, ilerde göreceklerdir."},{"n":180,"t":"Tenzih ederiz senin izzet sahibi Rabbını, onların nitelemekte olduklarından."},{"n":181,"t":"Selam olsun peygamberlere."},{"n":182,"t":"Hamd olsun, alemlerin Rabbı Allah’a."}],[{"n":1,"t":"Sad. Zikr dolu Kur’an’a yemin olsun."},{"n":2,"t":"Hayır, o küfredenler boş bir gurur ve bir parçalanma içindedirler."},{"n":3,"t":"Kendilerinden önce nice nesilleri helak ettik de onlar, çığlıklar kopardılar. Halbuki kurtulmak vakti değildi."},{"n":4,"t":"Küfredenler içlerinden bir uyarıcının gelmesine şaşırmışlardı da demişlerdi ki: Bu, çok yalancı bir sihirbazdır."},{"n":5,"t":"Tanrıları bir tek tanrı mı kıldı? Doğrusu bu, şaşırtıcı bir şey."},{"n":6,"t":"Onların elebaşlarından bir grup; yürüyün ve tanrılarınız üzerinde direnin. Şüphesiz ki bu; sizden istenen bir şeydir, diyerek çıkıp gittiler."},{"n":7,"t":"Biz, bunu diğer dinde de işitmedik. Bu, ancak bir uydurmadır."},{"n":8,"t":"Aramızdan zikir ona mı indirilmiştir? Hayır, onlar zikrimden şüphededirler. Hayır, onlar henüz azabımı tatmamışlardı."},{"n":9,"t":"Yoksa O Aziz, Vehhab Rabbının rahmet hazineleri onların yanında mıdır?"},{"n":10,"t":"Yahut göklerin, yerin ve ikisinin arasında bulunanların mülkü onların mıdır? Öyleyse sebeblere tevessül etsinler de yükselsinler bakalım."},{"n":11,"t":"Onlar, burada derme çatma gruplardan olma bozguna uğratılmış bir ordudur."},{"n":12,"t":"Onlardan önce, Nuh kavmi, Ad ve kazıklar sahibi Firavun da yalanlamıştı."},{"n":13,"t":"Semud, Lut kavmi ve Eyke halkı da. İşte onlar, ayrı topluluklardı."},{"n":14,"t":"Hepsi de peygamberleri yalanladılar. Ve bu yüzden azabı hak ettiler."},{"n":15,"t":"Bunlar, bir tek çığlık beklemektedirler ki, onun bir an bile gecikmesi yoktur."},{"n":16,"t":"Ve dediler ki: Rabbımız; hesab gününden önce bizim payımızı çabuklaştırıver."},{"n":17,"t":"Onların söylediklerine sabret... Ve güçlü kulunuz Davud’u hatırla. Muhakkak ki o, hep Allah’a yönelirdi."},{"n":18,"t":"Biz, gerçekten dağları onun buyruğuna vermiştik. Sabah ve akşam tesbih ederlerdi."},{"n":19,"t":"Kuşları da toplu olarak. Her biri ona yönelmişti."},{"n":20,"t":"Onun mülkünü pekiştirmiş, kendisine hikmet ve kesin söz söyleme hakkı vermiştik."},{"n":21,"t":"Sana davacıların haberi ulaştı mı? Hani onlar ma’bedin duvarına tırmanmışlardı."},{"n":22,"t":"Davud’un yanına girmişlerdi de o, kendilerinden ürkmüştü. Demişlerdi ki: Korkma, iki davacı; birimiz birimizin hakkına tecavüz etti. Sen, aramızda hak ile hüküm ver. Ve ondan ayrılma. Bizi, doğru yolun ortasına ilet."},{"n":23,"t":"Gerçekten bu, kardeşimdir. Onun doksan dokuz dişi koyunu, benim de bir tek dişi koyunum var. Onu bana ver, dedi ve söyleşmede beni yendi."},{"n":24,"t":"O da dedi ki: Senin dişi koyununu, kendi dişi koyunlarına katmak için istemekle sana zulmetmiştir. Doğrusu ortakçıların çoğu birbirinin hakkına tecavüz eder. Ancak inanmış olup salih ameller işleyenler müstesnadır. Ama onlar pek azdır. Davud, kendisini imtihan ettiğimizi zannederek Rabbından mağfiret diledi. Rukua kapanarak Allah’a yöneldi."},{"n":25,"t":"Bunun üzerine Biz de onu bağışladık. Onun için şüphesiz ki katımızda yüksek bir makam ve güzel bir sonuç vardır."},{"n":26,"t":"Ey Davud; seni gerçekten yeryüzüne halife kıldık. O halde insanlar arasında hak ile hükmet. Heveslere uyma ki bu, seni Allah’ın yolundan saptırır. Şüphesiz ki Allah’ın yolundan sapanlara; onlara hesab gününü unuttuklarından ötürü, şiddetli bir azab vardır."},{"n":27,"t":"Biz; göğü, yeryüzünü ve ikisinin arasında bulunanları boşuna yaratmadık. Bu, küfretmiş olanların zannıdır. Vay o küfretmiş olanlara, cehennem ateşinden."},{"n":28,"t":"Yoksa Biz; iman etmiş ve salih amel işlemiş olanları, yeryüzünde bozgunculuk edenler gibi mi kılarız? Yoksa Biz; muttakileri, facirler gibi mi tutarız?"},{"n":29,"t":"Ayetlerini düşünsünler ve akıl sahibi olanlar öğüt alsınlar diye, sana mübarek bir kitab indirdik."},{"n":30,"t":"Davud’a da Süleyman’ı lutfettik. O ne güzel bir kuldu ve muhakkak ki o, Allah’a yönelirdi."},{"n":31,"t":"Hani ona bir akşam, çalımlı ve cins koşu atları sunulmuştu."},{"n":32,"t":"Demişti ki: Doğrusu ben, Rabbımı zikretmek için mal sevgisine düştüm. Nihayet perdenin arkasına gizlenmişti."},{"n":33,"t":"Onları bana geri getirin, dedi, bacaklarını ve boyunlarını sıvazlamaya başlamıştı."},{"n":34,"t":"Andolsun ki; Biz, Süleyman’ı denemiştik. Tahtının üstüne bir ceset attık. Sonra eski haline döndü."},{"n":35,"t":"Dedi ki: Rabbım; bağışla beni. Ve bana öyle bir mülk ver ki; benden sonra hiç bir kimse ulaşamasın. Muhakkak ki en çok bağışta bulunan Sensin, Sen."},{"n":36,"t":"Bunun üzerine Biz de rüzgarı emrine verdik. Emri ile istediği yere kolayca giderdi."},{"n":37,"t":"Şeytanları da. Her bina ustasını ve dalgıcı da."},{"n":38,"t":"Demir halkalarla bağlı diğerlerini de."},{"n":39,"t":"Bu, bizim bağışımızdır. Artık ister hesabsızca ver, ister tut."},{"n":40,"t":"Doğrusu katımızda onun için yüksek bir makam ve güzel bir netice vardır."},{"n":41,"t":"Kulumuz Eyyub’u da hatırla. Hani Rabbına: Doğrusu şeytan bana yorgunluk ve azab verdi, diye seslenmişti."},{"n":42,"t":"Vur ayağını yere. İşte yıkanacak ve içilecek soğuk bir su."},{"n":43,"t":"Katımızdan bir rahmet, akıl sahipleri için de bir öğüt olmak üzere ona, ailesini ve onlarla birlikte olanların bir mislini lutfettik."},{"n":44,"t":"Eline bir demet sap al da onunla vur ve yemini bozma. Biz, onu gerçekten sabırlı bulmuştuk. Ne iyi kuldu. Muhakkak ki o, Allah’a yönelirdi."},{"n":45,"t":"Kuvvetli ve basiretli kullarımız; İbrahim, İshak ve Ya’kub’u da hatırla."},{"n":46,"t":"Doğrusu Biz, onları ahiret yurdunu samimiyetle düşünen kimseler kıldık."},{"n":47,"t":"Ve gerçekten onlar, katımızda seçkinlerden ve hayırlılardandı."},{"n":48,"t":"İsmail’i, El-Yesa’ı ve Zülkifl’i de hatırla. Hepsi de iyilerdendir."},{"n":49,"t":"Bu bir zikirdir. Ve muhakkak ki muttakiler için güzel bir sonuç vardır."},{"n":50,"t":"Kapıları kendilerine açılmış Adn cennetleri."},{"n":51,"t":"Orada tahtlara yaslanmış olarak birçok meyveler ve içecekler isterler."},{"n":52,"t":"Yanlarında gözlerini yalnız eşlerine dikmiş aynı yaştan güzeller vardır."},{"n":53,"t":"İşte hesab günü için size vaadolunan budur."},{"n":54,"t":"Doğrusu bu, Bizim rızkımızdır, onun için bitip tükenme yoktur."},{"n":55,"t":"Bu böyle. Azgınlar için de sonucun en kötüsü vardır."},{"n":56,"t":"Cehennem. Oraya girerler. Ne kötü bir konaktır."},{"n":57,"t":"İşte şu, kaynar su ve irin. Tatsınlar onu."},{"n":58,"t":"Bunlara benzer daha başkaları da vardır."},{"n":59,"t":"İşte bu topluluk, sizinle beraber göğüs gerenlerdir. Rahat yüzü görmesin onlar. Muhakkak cehenneme gireceklerdir."},{"n":60,"t":"Dediler ki: Hayır, asıl siz rahat yüzü görmeyin. Bizi buraya siz sürdünüz. Ne kötü bir duraktır burası."},{"n":61,"t":"Dediler ki: Rabbımız; bizi buraya kim sürdüyse ona ateşteki azabını kat kat arttır."},{"n":62,"t":"Ve dediler ki: Bizim kendilerini kötülerden saydığımız adamları niçin burada görmüyoruz?"},{"n":63,"t":"Onları alaya almıştık. Yoksa şimdi gözlere görünmez mi oldular?"},{"n":64,"t":"İşte bu, hakkın kendisidir. Cehennem ehlinin birbiriyle tartışması."},{"n":65,"t":"De ki: Ben, sadece bir uyarıcıyım. Vahid, Kahhar olan Allah’tan başka hiç bir ilah yoktur."},{"n":66,"t":"Göklerin, yerin ve ikisinin arasında bulunanların Rabbı Aziz’dir, Gafur’dur."},{"n":67,"t":"De ki: Bu, büyük bir haberdir."},{"n":68,"t":"Ama siz, ondan yüz çeviriyorsunuz."},{"n":69,"t":"Mele-i A’la’da olan tartışmalar hakkında benim bir bilgim yoktur."},{"n":70,"t":"Bana, sadece vahyolunur. Ben, ancak apaçık bir uyarıcıyım."},{"n":71,"t":"Hani Rabbın meleklere demişti ki: Ben, çamurdan bir insan yaratacağım."},{"n":72,"t":"Onu yapıp ruhumdan kendisine üflediğim zaman; derhal secde edin ona."},{"n":73,"t":"Bütün melekler topluca secde ettiler."},{"n":74,"t":"Yalnız İblis, büyüklük tasladı ve kafirlerden oldu."},{"n":75,"t":"Buyurdu ki: Ey İblis, iki elimle yarattığıma secde etmekten seni alıkoyan nedir? Böbürlendin mi, yoksa yücelerden mi oldun?"},{"n":76,"t":"Dedi ki: Ben ondan daha hayırlıyım. Beni ateşten yarattın, onu çamurdan yarattın."},{"n":77,"t":"Buyurdu ki: Çık oradan. Şüphesiz sen, artık kovulmuş birisin."},{"n":78,"t":"Ve muhakkak ki din gününe kadar la’netim senin üzerinedir."},{"n":79,"t":"Dedi ki: Rabbım, diriltilecekleri güne kadar beni ertele."},{"n":80,"t":"Buyurdu ki: Sen, şüphesiz ertelenensin,"},{"n":81,"t":"Belli bir vaktin gününe kadar."},{"n":82,"t":"Dedi ki: Senin izzetine yemin olsun ki ben, onların hepsini muhakkak azdırırım."},{"n":83,"t":"Ancak içlerinden ihlasa erdirilmiş kulların müstesna."},{"n":84,"t":"Buyurdu ki: İşte bu, haktır ve Ben, hakkı söylerim."},{"n":85,"t":"Muhakkak cehennemi seninle ve onlardan sana uyanların hepsiyle dolduracağım."},{"n":86,"t":"De ki: Ben, buna karşı sizden bir ücret istemiyorum ve ben, kendiliğimden bir şey iddia edenlerden de değilim."},{"n":87,"t":"Bu, ancak alemler için bir zikirdir."},{"n":88,"t":"Onun haberini bir müddet sonra öğreneceksiniz."}],[{"n":1,"t":"Kitab’ın indirilmesi; Aziz, Hakim olan Allah katındandır."},{"n":2,"t":"Şüphesiz ki Biz, kitabı sana, hak olarak indirdik. Öyleyse dini Allah için tahsis ederek O’na ibadet et."},{"n":3,"t":"İyi bil ki; halis din, Allah’ındır. O’ndan başka veliler edinenler; onlara, sırf bizi Allah’a yaklaştırsınlar diye ibadet ediyoruz, derler. Doğrusu Allah, ihtilafa düştükleri şeylerde, aralarında hüküm verecektir. Muhakkak ki Allah; yalancı ve kafir olan kimseyi hidayete eriştirmez."},{"n":4,"t":"Şayet Allah, çocuk edinmek isteseydi; yaratıklarından dilediğini elbette seçerdi. Tenzih ederiz O’nu. O; Vahid ve Kahhar Allah’tır."},{"n":5,"t":"Gökleri ve yeri hak ile yaratmıştır. Geceyi gündüzün üzerine dolar; gündüzü de gecenin üzerine dolar. Güneşi ve ayı müsahhar kılmıştır. Her biri belirli bir süreye kadar akıp gitmektedir. İyi bilin ki O; Aziz’ dir, Gaffar’dır."},{"n":6,"t":"Sizi bir tek nefisten yaratmış, sonra ondan eşini var etmiştir. Sizin için, hayvanlardan sekiz çift indirmiştir. Sizi, analarınızın karınlarında üç karanlık içinde, bir yaratılıştan sonra öbür yaratılışa geçirerek yaratmaktadır. İşte bu, Rabbınız olan Allah’tır. Mülk O’nundur. O’ndan başka ilah yoktur. Böyleyken nasıl olup da döndürülüyorsunuz?"},{"n":7,"t":"Eğer küfrederseniz; muhakkak ki Allah, sizden müstağnidir. Fakat O, kulları için küfre rıza göstermez. Eğer şükrederseniz; sizden hoşnud olur. Hiç bir günahkar diğerinin günahını yüklenmez. Sonra dönüşünüz Rabbınızadır. O zaman yaptıklarınızı size haber verir. Muhakkak ki O, göğüslerin özünü bilendir."},{"n":8,"t":"İnsana bir sıkıntı dokunduğu zaman Rabbına yönelerek O’na yalvarır. Sonra O, kendi katından ona bir nimet verince; önceden O’na yalvarmış olduğunu unutuverir. Ve Allah’ın yolundan saptırmak için O’na eşler koşar. De ki: Küfrünle biraz eğlenedur. Muhakkak ki sen, ateş yaranındansın."},{"n":9,"t":"Yoksa o, geceleyin secde ederek, kıyamda durarak itaat eden, ahiretten korkan ve Rabbının rahmetini dileyen kimse gibi midir? De ki: Hiç bilenlerle bilmeyenler bir olur mu? Doğrusu ancak akıl sahipleri öğüt alıp düşünür."},{"n":10,"t":"De ki: Ey iman eden kullarım, Rabbınızdan korkun. Bu dünyada iyilik yapanlara, iyilik vardır. Ve Allah’ın arzı geniştir. Yalnız sabredenlere ecirleri, hesapsız ödenecektir."},{"n":11,"t":"De ki: Ben, dini yalnız Allah’a tahsis ederek ibadet etmekle emrolundum."},{"n":12,"t":"Ve ben, müslümanların ilki olmakla emrolundum."},{"n":13,"t":"De ki: Rabbıma karşı gelirsem; doğrusu büyük günün azabından korkarım."},{"n":14,"t":"De ki: Ben, dinimde muhlis olarak Allah’a ibadet ederim."},{"n":15,"t":"Artık siz de O’ndan başka dilediğinize tapın. De ki: Hüsrana uğrayanlar; kıyamet gününde kendilerini de, ailelerini de hüsrana uğratanlardır. İyi bilin ki; apaçık hüsran işte budur."},{"n":16,"t":"Onların üstlerinde kat kat ateşler, altlarında kat kat ateşler vardır. Allah, kullarını bununla korkutur. Ey kullarım, benden korkun."},{"n":17,"t":"Tağut’a tapmaktan kaçınıp Allah’a yönelenlere; işte onlara müjde vardır. Öyleyse kullarımı müjdele."},{"n":18,"t":"Onlar ki; sözü dinlerler de, en güzeline uyarlar. İşte bunlar; Allah’ın kendilerini hidayete eriştirdiği kimselerdir. Ve işte bunlar; akıl sahiblerinin kendileridir."},{"n":19,"t":"Hakkında azab hükmü gerçekleşmiş kimseyi mi? Ateşte olanı sen mi kurtaracaksın?"},{"n":20,"t":"Fakat Rabblarından korkanlar için, üzerlerine konaklar yapılmış, altlarında ırmaklar akan yüksek menziller vardır. Bu, Allah’ın verdiği sözdür. Allah, verdiği sözden caymaz."},{"n":21,"t":"Görmez misin ki; gerçekten Allah, gökten bir su indirip onu yerdeki kaynaklara yerleştirmiş, sonra da onunla türlü türlü ekinler çıkarmaktadır. Sonra onları kurutur ve sen, onları sararmış görürsün. Sonra da onu çörçöp haline çevirir. Muhakkak ki bunlarda, akıl sahipleri için ibret vardır."},{"n":22,"t":"Allah, kimin göğsünü İslam’a açmışsa; artık o, Rabbından bir nur üzeredir. Allah’ın zikrinden kalbleri katılaşmış olanların vay haline. İşte onlar, apaçık bir sapıklık içindedirler."},{"n":23,"t":"Allah, sözün en güzelini; ahenkli, ikişerli bir kitab halinde indirmiştir. Rabblarından korkanların ondan derileri ürperir. Sonra hem derileri hem de kalbleri Allah’ın zikrine karşı yumuşar. Bu, Allah’ın hidayet rehberidir, onunla istediğini hidayete eriştirir. Allah kimi de saptırırsa; ona bir daha yol gösteren bulunmaz."},{"n":24,"t":"Zalimlere: Kazandıklarınızın karşılığını tadın, denilirken kıyamet günü yüzünü azabın kötüsünden kim koruyacak?"},{"n":25,"t":"Onlardan öncekiler de peygamberleri yalanlamışlardı da hiç farkında olmadıkları bir yönden azab kendilerine çatıvermişti."},{"n":26,"t":"Allah, dünya hayatında onlara rüsvaylığı tattırdı. Ahiret azabı ise daha büyüktür. Keşki bilselerdi."},{"n":27,"t":"Andolsun ki; Biz, bu Kur’an’da insanlara her çeşit misali verdik. Belki öğüt alırlar."},{"n":28,"t":"Eğriliği bulunmayan arabça bir Kur’an’dır. Belki sakınırlar."},{"n":29,"t":"Allah, bir misal verir: Bir adamın, huysuz ve birbirleriyle ortak birkaç efendisi var. Bir adamın da tek bir efendisi var. Bu ikisi bir olur mu hiç? Hamd; Allah’a mahsustur; ama onların çoğu bilmezler."},{"n":30,"t":"Şüphesiz sen de öleceksin, onlar da ölecekler."},{"n":31,"t":"Sonra siz, kıyamet günü Rabbınızın huzurunda duruşmaya çıkacaksınız."},{"n":32,"t":"Allah’a karşı yalan söyleyenden ve kendisine gelmiş olan gerçeği yalan sayandan daha zalim kimdir? Kafirler için cehennemde bir karargah olmaz olur mu?"},{"n":33,"t":"Doğruyu getiren ve onu tasdik edenler; işte onlar muttakilerdir."},{"n":34,"t":"Rabbları katında diledikleri her şey, onlarındır. Bu, ihsan edenlerin mükafatıdır."},{"n":35,"t":"Çünkü Allah; onların yaptıklarının en kötüsünü örtecek ve yapmakta olduklarının en güzeliyle karşılığını verecektir."},{"n":36,"t":"Allah, kuluna kafi değil mi? Seni O’ndan başkalarıyla korkutuyorlar. Allah, kimi saptırırsa; onu hidayete erdirecek yoktur."},{"n":37,"t":"Allah, kimi de hidayete erdirirse; onu saptıracak yoktur. Allah; Aziz, intikam sahibi değil midir?"},{"n":38,"t":"Andolsun ki; onlara: Gökleri ve yeri yaratan kimdir? diye sorsan; muhakkak, Allah’tır, diyecekler. De ki: Öyleyse söyleyin bakalım; Allah, bana bir zarar vermek istese, O’nu bırakıp da taptıklarınız O’nun verdiği zararı giderebilir mi? Yahut bana bir rahmet dilerse, O’nun rahmetini önleyebilir mi? De ki: Allah, bana yeter. Tevekkül edenler O’na tevekkül ederler."},{"n":39,"t":"De ki: Ey kavmim; elinizden geleni yapın. Doğrusu ben de yapacağım. Ve yakında bileceksiniz."},{"n":40,"t":"Kendisine rüsvay edici bir azab gelecek olan kim, üzerine sürekli azab inecek olan kim?"},{"n":41,"t":"Şüphesiz ki Biz; kitabı sana insanlar için hak olarak indirdik. Kim hidayete ererse; bu, kendi lehinedir. Kim de sapıtırsa; kendi aleyhine sapıtmış olur. Ve sen, onların üzerinde vekil değilsin."},{"n":42,"t":"Allah; ölüm anında canları alır. Ölmeyenin ise uykusunda. Ölmelerine hükmettiği kimselerinkini tutar, diğerlerini belli bir süreye kadar salıverir. Doğrusu bunda; düşünen bir kavim için ayetler vardır."},{"n":43,"t":"Yoksa onlar; Allah’tan başka şefaatçılar mı edindiler? De ki: Onlar, hiç bir şeye güç getiremez ve akıl erdiremez olsalar da mı?"},{"n":44,"t":"De ki: Bütün şefaat Allah’ındır. Göklerin ve yerin mülkü O’nundur. Sonra hepiniz O’na döndürüleceksiniz."},{"n":45,"t":"Allah, tek başına anıldığı zaman; ahirete inanmayanların kalbleri tiksinir. Ama O’ndan başkaları anıldığı vakit hemen yüzleri güler."},{"n":46,"t":"De ki: Ey gökleri ve yeri yaratan, görülmeyeni ve görüleni bilen Allah’ım; ayrılığa düştükleri şeyler hakkında kulların arasında Sen hükmedersin."},{"n":47,"t":"Yeryüzünde olanların hepsi ve bir misli daha zalimlerin olsaydı; kıyamet günündeki kötü azab için elbette bunları fidye verirlerdi. Halbuki Allah katından onlara hiç hesablamadıkları şeyler belirmiştir."},{"n":48,"t":"İşledikleri kötülükler onlara belli olmuş, alaya aldıkları şeyler de kendilerini çepeçevre sarmıştır."},{"n":49,"t":"İnsana bir sıkıntı gelince; Bize yalvarır. Sonra katımızdan ona bir nimet verdiğimizde; bu, bana bilgimden dolayı verilmiştir, der. Hayır, bu bir denemedir. Fakat çokları bilmezler."},{"n":50,"t":"Onlardan öncekiler de bunu söylemişlerdi. Ama kazandıkları şey, kendilerine bir fayda vermemişti."},{"n":51,"t":"Böylece kazandıkları kötülükler başlarına geldi. Bunların içinden zulmedenlerin kazandıkları kötülükler de kendilerini çarpacaktır. Ve onlar aciz bırakılacaklar da değillerdir."},{"n":52,"t":"Bilmezler mi ki; Allah, dilediğine rızkı genişletir ve kısar. Doğrusu bunda, inanan kimseler için ayetler vardır."},{"n":53,"t":"De ki: Ey kendi nefislerine karşı aşırı davranan kullarım, Allah’ın rahmetinden ümidinizi kesmeyin. Muhakkak ki Allah; günahları bağışlar. Çünkü O; Gafur’dur, Rahim’dir"},{"n":54,"t":"Ve Rabbınıza yönelin. Size azab gelmeden önce O’na teslim olun. Sonra yardım edilmezsiniz."},{"n":55,"t":"Siz, farkında değilken ansızın azab gelmezden önce Rabbınızdan size indirilen sözün en güzeline uyun."},{"n":56,"t":"Kişinin: Allah’a karşı aşırı gitmemden dolayı vay bana, yazıklar olsun; gerçekten ben, alaya alanlardandım, diyeceği gün gelmezden önce."},{"n":57,"t":"Veya: Allah beni hidayete erdirseydi, ben de muttakilerden olurdum, diyeceği gün."},{"n":58,"t":"Yahut azabı gördüğü vakit: Keşki benim için bir dönüş daha olsaydı da ihsan edenlerden olsaydım, diyeceği gün."},{"n":59,"t":"Hayır, sana ayetlerim gelmişti de, onları yalanlamış, büyüklük taslayarak kafirlerden olmuştun."},{"n":60,"t":"Ve kıyamet günü Allah’a karşı yalan uyduranların yüzlerinin simsiyah olduğunu görürsün. Mütekebbir için cehennemde bir karargah olmaz olur mu?"},{"n":61,"t":"Allah muttakileri, kurtuluşlarına sebep olan ile selamete erdirir. Onlara hiç bir kötülük gelmez ve üzülmezler de."},{"n":62,"t":"Allah; her şeyin yaratanıdır ve O; her şeye vekildir."},{"n":63,"t":"Göklerin ve yerin anahtarları O’nundur. Allah’ın ayetlerine küfredenler; işte onlar hüsrana uğrayanlardır."},{"n":64,"t":"De ki: Bana, Allah’tan başkasına ibadet etmemi mi emredersiniz ey cahiller?"},{"n":65,"t":"Andolsun; sana da, senden öncekilere de vahyolunmuştur ki: Eğer Allah’a ortak koşarsan, şüphesiz amellerin boşa gider ve muhakkak hüsrana uğrayanlardan olursun."},{"n":66,"t":"Hayır, yalnız Allah’a ibadet et ve şükredenlerden ol."},{"n":67,"t":"Onlar Allah’ı şanına yaraşır şekilde takdir edemediler. Halbuki kıyamet günü bütün yeryüzü O’nun avucundadır. Gökler de O’nun sağ eliyle dürülmüştür. O; koştukları ortaklardan münezzehtir, yücedir."},{"n":68,"t":"Ve Sur’a üflenmiştir. Artık Allah’ın dilediği bir yana, göklerde olanlar ve yerde olanlar baygın düşmüştür. Sonra ona bir daha üflenmiş ve bir de bakacaksın ki ayakta bakınıp duruyorlar."},{"n":69,"t":"Yer; Rabbının nuru ile aydınlandı, kitab konuldu, peygamberler ve şahidler getirildi. Onlara haksızlık yapılmadan aralarında hak ile hükmolundu."},{"n":70,"t":"Her kişiye ne yaptıysa eksiksiz ödendi. Ve Allah; onların yaptıklarını en iyi bilendir."},{"n":71,"t":"Küfredenler bölük bölük cehenneme sürüldü. Oraya vardıklarında kapıları açıldı ve bekçileri onlara dediler ki: İçinizden, size Rabbınızın ayetlerini okuyan ve bugüne kavuşacağınızı ihtar eden elçiler gelmedi mi? Onlar da: Evet, dediler. Fakat azab sözü küfredenlerin üzerine hak oldu."},{"n":72,"t":"Onlara denildi ki: İçinde temelli kalacağınız cehennemin kapılarından girin. Büyüklenenlerin durağı ne kötüdür."},{"n":73,"t":"Rabblarından sakınanlar ise fevc fevc cennete götürüldüler. Oraya varıp da kapıları açılınca, bekçileri onlara dediler ki: Selam olsun size. Hoş geldiniz. Temelli olarak girin buraya."},{"n":74,"t":"Onlar da dediler ki: Bize vaadinde sadık olan ve bizi yeryüzüne varis kılan Allah’a hamdolsun. Cennette istediğimiz yerde oturabiliriz. Çalışanların ecri ne de güzeldir."},{"n":75,"t":"Görürsün ki; melekler de Rabblarına hamd ile tesbih ederek Arş’ın etrafını kuşatmışlardır. Artık onların arasında hak ile hükmolunmuştur ve denildi ki: Hamd olsun alemlerin Rabbı Allah’a."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Kitab’ın indirilişi; Aziz, Alim olan Allah’tandır."},{"n":3,"t":"Günahları bağışlayan, tevbeyi kabul eden, cezası şiddetli, lutfu bol olandır. O’ndan başka ilah yoktur, dönüş O’nadır."},{"n":4,"t":"Küfredenlerden başkası Allah’ın ayetleri üzerinde tartışmaya girişmez. Öyleyse onların şehirlerde dönüp dolaşması seni aldatmasın."},{"n":5,"t":"Onlardan önce Nuh kavmi de yalanladı. Arkalarından muhtelif topluluklar da. Her ümmet kendi peygamberlerini yakalamaya yeltendi ve hakkı batılla yok etmek için mücadeleye girişti. En sonunda Ben de onları yakaladım. Azabım nasılmış?"},{"n":6,"t":"Böylece küfredenlerin cehennemlik olduklarına dair Rabbının sözü gerçekleşti."},{"n":7,"t":"Arş’ı taşıyanlar ve çevresinde bulunanlar Rabblarını hamd ile tesbih ederler, O’na inanırlar ve mü’minlerin yarlığanmasını isterler: Rabbımız; ilim ve rahmetle her şeyi kuşattın. Tevbe edip Senin yoluna uyanları bağışla. Ve onları cehennem azabından koru."},{"n":8,"t":"Rabbımız; onları ve babalarından, eşlerinden, soylarından salih olanları kendilerine vaadettiğin Adn cennetlerine girdir. Şüphesiz ki Aziz, Hakim olan Sensin Sen."},{"n":9,"t":"Onları kötülüklerden koru. O gün kötülüklerden kimi korursan; şüphesiz ona rahmet etmiş olursun. En büyük kurtuluş işte budur"},{"n":10,"t":"Muhakkak küfredenlere seslenilir ki: Allah’ın gazabı sizin birbirinize öfkenizden daha büyüktür. Çünkü siz, imana davet olunuyordunuz da küfrediyordunuz."},{"n":11,"t":"Onlar da: Rabbımız; bizi iki defa öldürdün, iki defa dirilttin. Biz de suçlarımızı itiraf ettik. Bir daha çıkmaya yol var mı? derler."},{"n":12,"t":"Bunun sebebi şudur: Yalnız Allah’a dua edildiği zaman inkar ederdiniz de, O’na şirk koşulunca inanırdınız. Artık hüküm; Aliyy, Kebir Allah’ındır."},{"n":13,"t":"Size ayetlerini gösteren ve sizin için gökten rızık indiren O’dur. O’na yönelenden başkası ibret almaz."},{"n":14,"t":"Öyleyse kafirler istemese de, siz dini yalnız O’na halis kılanlar olarak Allah’a dua edin."},{"n":15,"t":"Dereceleri yükselten, Arş’ın sahibi Allah, karşılaşma gününden korkutmak için, kendi emrinden olan ruhu kullarından dilediğine indirir."},{"n":16,"t":"O gün onlar, ortaya çıkarlar. Hiç bir şeyleri Allah’a gizli kalmaz. Kimindir bugün mülk? Vahid, Kahhar olan Allah’ındır."},{"n":17,"t":"Bugün her nefis kazandığı ile karşılık görür. Bugün zulüm yoktur. Muhakkak ki Allah; hesabı çabuk görendir."},{"n":18,"t":"Onları yaklaşan gün ile uyar. O zaman ki; yürekler ağızlara gelecek, tasadan yutkunacaklar. Zalimlerin ne dostu, ne de dinlenecek şefaatçısı olur."},{"n":19,"t":"O; gözlerin hainliğini ve göğüslerin gizlediğini bilir."},{"n":20,"t":"Allah; hak ile hükmeder. O’nu bırakıp da taptıkları ise hiç bir şeye hükmedemez. Şüphesiz ki Allah; Semi’dir, Basir’dir."},{"n":21,"t":"Yeryüzünde gezip dolaşmadılar mı ki; kendilerinden öncekilerin akıbetlerinin nasıl olduğunu görsünler? Onlar; kendilerinden daha kuvvetli ve yeryüzünde daha çok eser bırakan kimselerdi. Allah; onları günahlarıyla yakalayıverdi. Allah’a karşı onları koruyan yoktur."},{"n":22,"t":"Bu; peygamberleri kendilerine apaçık mucizelerle geldiğinde inkar etmelerindendir. Allah da onları yakalayıverdi. Muhakkak ki O; kuvvetlidir, cezalandırması pek şiddetlidir."},{"n":23,"t":"Andolsun ki; Biz, Musa’yı ayetlerimizle ve apaçık burhan ile gönderdik."},{"n":24,"t":"Firavun’a, Haman’a ve Karun’a. Bu, yalancı sihirbazın biridir, dediler."},{"n":25,"t":"O, katımızdan kendilerine hakkı getirince: Onunla beraber iman etmiş olanların oğullarını öldürün, kadınlarını sağ bırakın, dediler. Kafirlerin düzeni hedef olmaktan başka bir şey değildir."},{"n":26,"t":"Firavun demişti ki: Bırakın beni de Musa’yı öldüreyim. O ise Rabbına yalvaradursun. Onun, sizin dininizi değiştirmesinden veya yeryüzünde fesad çıkarmasından korkuyorum."},{"n":27,"t":"Musa da demişti ki: Doğrusu ben, hesab gününe inanmayan her mütekebbirden; benim de Rabbım, sizin de Rabbınız olana sığınırım."},{"n":28,"t":"Firavun hanedanından olup da imanını gizleyen mü’min bir adam da demiştir ki: Rabbım Allah’tır, dedi diye bir kişiyi mi öldüreceksiniz? Halbuki o, size Rabbınızdan ayetlerle gelmiştir. Eğer yalancıysa; yalanı kendisinedir. Eğer doğru sözlü ise; sizi tehdit ettiklerinin bir kısmı başınıza gelebilir. Muhakkak ki Allah; haddi aşan yalancı bir kimseyi hidayete erdirmez."},{"n":29,"t":"Ey kavmim; bugün mülk sizindir. Yeryüzünde galib sizsiniz. Fakat Allah’ ın baskını gelip çatınca, O’na karşı bize kim yardım eder? Firavun dedi ki: Ben, size kendi görüşümden başkasını söylemiyorum. Size doğru yolun tersini de göstermiyorum."},{"n":30,"t":"İnanmış olan dedi ki: Ey kavmim; doğrusu ben, sizin hakkınızda peygamberleri yalanlayan toplulukların uğradıkları bir günün benzerinden korkuyorum."},{"n":31,"t":"Nuh kavminin, Ad, Semud ve onlardan sonra gelenlerin durumu gibi. Allah, kullarına zulüm dilemez."},{"n":32,"t":"Ey kavmim; doğrusu ben, sizin için o feryad gününden endişe ediyorum."},{"n":33,"t":"Arkanıza dönüp kaçacağınız gün, sizi Allah’a karşı koruyan bulunmaz. Allah, kimi saptırırsa; onu doğru yola getirecek yoktur."},{"n":34,"t":"Andolsun ki; daha önce Yusuf da size apaçık burhanlarla gelmişti. O zaman da size getirdiği şeylerden şüphelenip durmuştunuz. Nihayet vefat edince: Allah, bundan sonra hiç bir peygamber göndermez, demiştiniz. İşte Allah; haddi aşan aşırı şüphecileri böyle şaşırtır."},{"n":35,"t":"Onlar ki; kendilerine gelmiş bir huccet bulunmaksızın Allah’ın ayetleri üzerinde tartışırlar. Bu, Allah katında da, iman edenlerin yanında da öfkeyi arttırır. Ve böylece Allah; büyüklük taslayan her zorbanın kalbini mühürler."},{"n":36,"t":"Firavun demişti ki: Ey Haman; bana yüksek bir kule yap. Belki o yollara ulaşabilirim."},{"n":37,"t":"Göklerin yollarına. Musa’nın tanrısını görürüm. Doğrusu ben, onu yalancı sanıyorum. Böylece yaptığı kötü iş Firavun’a güzel gösterildi de doğru yoldan alıkonuldu. Firavun’un düzeni elbette boşa gidecekti."},{"n":38,"t":"İnanmış olan demişti ki: Ey kavmim; bana uyun, sizi doğru yola hidayet edeyim."},{"n":39,"t":"Ey kavmim; şüphesiz dünya hayatı geçici bir geçinmedir. Ahiret ise doğrusu işte o, asıl kalınacak yurd odur."},{"n":40,"t":"Kim, bir kötülük işlerse; ancak onun benzerleriyle ceza görür. Kadın veya erkek her kim de inanarak salih amel işlerse; işte onlar, cennete girerler ve orada hesapsız şekilde rızıklanırlar."},{"n":41,"t":"Ey kavmim; bana ne oluyor ki, sizi kurtuluşa çağırırken, siz beni; ateşe çağırıyorsunuz."},{"n":42,"t":"Siz, beni; Allah’a küfretmem, hiç tanımadığım nesneleri O’na ortak tutmam için çağırıyorsunuz. Ben ise, sizi Aziz ve Gaffar’a çağırıyorum."},{"n":43,"t":"Şüphesiz sizin beni kendisine çağırdığınız; bu dünyada da, ahirette de çağırabilecek kabiliyette değildir. Ve muhakkak dönüşümüz Allah’adır. Elbette müsrifler; işte onlardır cehennem yaranı olanlar."},{"n":44,"t":"Size söylediğimi hatırlayacaksınız. Ben, işimi Allah’a bırakıyorum. Muhakkak ki Allah; kulları görendir."},{"n":45,"t":"Allah; onu, kurmak istedikleri tuzakların fenalıklarından korudu ve Firavun’un adamlarını azabın kötüsü kuşatıverdi."},{"n":46,"t":"Sabah akşam ateşe sunulurlar. Kıyamet koptuğu gün; Firavun’un adamlarını azabın en şiddetlisine sokun, denir."},{"n":47,"t":"Ateşin içinde birbirleriyle tartışırlarken güçsüzler, büyüklük taslayanlara derler ki: Doğrusu biz, size uymuştuk. Şimdi ateşin bir parçasını olsun bizden savabilir misiniz?"},{"n":48,"t":"Büyüklük taslayanlar: Doğrusu hepimiz, onun içindeyiz. Şüphesiz Allah kullar arasında hükmünü vermiştir, derler."},{"n":49,"t":"Ateşte olanlar, cehennemin bekçilerine derler ki: Rabbınıza yalvarın da hiç değilse bir gün olsun azabımızı hafifletsin."},{"n":50,"t":"Onlar da derler ki: Size peygamberleriniz burhanlarla gelmemişler miydi? Evet, derler. Öyleyse kendiniz yalvarın, derler. Kafirlerin yalvarışı şüphesiz boşunadır."},{"n":51,"t":"Şüphesiz ki Biz; peygamberlerimize ve iman etmiş olanlara hem dünya hayatında, hem de şahidlerin şehadet edecekleri günde mutlaka yardım ederiz."},{"n":52,"t":"O gün; mazeretleri zalimlere fayda vermez. La’net onların, yurdun kötüsü de onlarındır."},{"n":53,"t":"Andolsun ki; Biz, Musa’ya hidayeti verdik. İsrailoğullarına da kitabı miras bıraktık"},{"n":54,"t":"Ki o; akıl sahipleri için hidayet ve öğüttür."},{"n":55,"t":"Şimdi sen; sabret, Allah’ın vaadi mutlaka haktır. Günahının yarlığanmasını dile, sabah akşam Rabbını hamd ile tesbih et."},{"n":56,"t":"Kendilerine gelmiş kesin bir delil olmadan Allah’ın ayetleri üzerinde tartışanların göğüslerinde, şüphesiz ki ulaşamayacakları bir büyüklenme vardır. Öyleyse sen, Allah’a sığın. Muhakkak ki O’dur O, Semi, Basir."},{"n":57,"t":"Elbette göklerin ve yerin yaratılması, insanların yaratılmasından daha büyüktür. Ne var ki insanların çoğu bilmezler."},{"n":58,"t":"Körle gören, inanıp salih amel işleyenlerle kötülük yapan bir değildir. Ne de az düşünüyorsunuz."},{"n":59,"t":"Kıyamet günü mutlaka gelecektir. Bunda hiç şüphe yoktur. Ne var ki insanların çoğu inanmazlar."},{"n":60,"t":"Rabbınız: Bana dua edin ki, size icabet edeyim. Bana kulluk etmeyi büyüklüklerine yediremeyenler hor ve hakir olarak cehenneme gireceklerdir, buyurdu."},{"n":61,"t":"Allah O’dur ki; dinlenesiniz diye size geceyi karanlık, gündüzü aydınlık kılmıştır. Şüphesiz ki Allah; insanlara karşı lutufkardır. Ne var ki insanların çoğu şükretmezler."},{"n":62,"t":"İşte Rabbınız olan; her şeyi yaratan Allah, budur. O’ndan başka hiç bir ilah yoktur. O halde nasıl olup da çevriliyorsunuz?"},{"n":63,"t":"Allah’ın ayetlerini bile bile inkar edenler, işte böyle çevriliyorlar."},{"n":64,"t":"Allah, O’dur ki; sizin için yeri bir karargah, göğü bir bina yapmış, size şekil verip şeklinizi güzelleştirmiş ve size temiz şeylerden rızık vermiştir. İşte Rabbınız olan Allah budur. Alemlerin Rabbı olan Allah ne yücedir."},{"n":65,"t":"O; diridir. O’ndan başka hiç bir ilah yoktur. Öyleyse dini yalnızca kendisine halis kılanlar olarak O’na dua edin. Hamd olsun alemlerin Rabbı Allah’a."},{"n":66,"t":"De ki: Rabbımdan bana apaçık deliller geldiği için sizin Allah’tan başka ibadet ettiklerinize ibadet etmekten nehyolundum. Ve alemlerin Rabbına teslim olmakla emrolundum."},{"n":67,"t":"Sizi; topraktan, sonra bir nutfeden, sonra bir kan pıhtısından yaratan, sonra erginlik çağına ulaşmanız, sonra da yaşlanmanız için sizi bebek olarak dünyaya çıkaran O’dur. Kiminiz daha önce öldürülürsünüz. Kiminiz de adı konulmuş bir ecele erişirsiniz. Olur ki böylece aklınızı kullanırsınız."},{"n":68,"t":"Dirilten de öldüren de O’dur. Bir şeye hükmetti mi sadece ona, ol, der, o da oluverir."},{"n":69,"t":"Allah’ın ayetleri üzerinde tartışanları görmez misin? Nasıl da döndürülüyorlar."},{"n":70,"t":"Onlar; kitabı ve peygamberlerimizle gönderdiklerimizi yalanlayanlardır. Yakında bilecekler."},{"n":71,"t":"Hani boyunlarında demir halkalar ve zincirler ile sürüklenirler, Yakında bilecekler. olarak dünyaya çıkaran O’dur. Kiminiz daha önce öldürülürsünüz. Kiminiz de adı konulmuş bir ecele erişirsiniz. Olur ki böylece aklınızı kullanırsınız."},{"n":72,"t":"Kaynar suya. Sonra da ateşte yakılırlar."},{"n":73,"t":"Sonra onlara denilir ki: Nerede şirk koştuklarınız,"},{"n":74,"t":"Allah’tan başka? Derler ki: Bizden uzaklaştılar, hayır zaten biz önceleri hiç bir şeye ibadet etmiyorduk. İşte Allah, kafirleri böylece saptırır."},{"n":75,"t":"Bu; sizin yeryüzünde haksız yere şımarmanız ve böbürlenmenizden ötürüdür."},{"n":76,"t":"İçinde ebediyyen kalıcı olarak cehenneme kapılarından girin. Kibirlenenlerin dönüp gidecekleri yer ne kötüdür."},{"n":77,"t":"Şu halde sen; sabret. Muhakkak ki Allah’ın vaadi haktır. Onlara vaadettiğimiz azabın bir kısmını sana gösteririz veya seni kendimize alırız. Nihayet onların dönüşü ancak Bizedir."},{"n":78,"t":"Andolsun ki; senden önce de peygamberler gönderdik. Onlardan kimini sana anlattık, kimini anlatmadık. Allah’ın izni olmadan hiç bir peygamber herhangi bir ayeti kendiliğinden getiremez. Allah’ın emri geldiği vakit de iş, gerçekten biter. İşte o zaman, batıl işleyenler hüsranda kalırlar."},{"n":79,"t":"Allah O’dur ki; binek olarak kullanasınız ve yiyesiniz diye davarları sizin için yaratmıştır."},{"n":80,"t":"Onlarda sizin için daha nice faydalar vardır. Gönüllerinizdeki arzulara, onlara binerek ulaşırsınız. Onlarla ve gemilerle taşınırsınız."},{"n":81,"t":"Size ayetlerini gösterir. Allah’ın ayetlerinden hangisini inkar edersiniz?"},{"n":82,"t":"Yeryüzünde gezip dolaşmazlar mı ki; kendilerinden öncekilerin akıbetlerinin nasıl olduğunu görsünler. Hem onlar; kendilerinden daha çok, daha kuvvetli ve yeryüzünde daha sağlam eser bırakan kimselerdi. Ama kazandıkları onlara bir fayda sağlamamıştı."},{"n":83,"t":"Peygamberleri kendilerine huccetlerle gelince; kendi yanlarındaki bilgi ile gururlandılar da, alaya aldıkları şey kendilerini kuşatıverdi."},{"n":84,"t":"Baskınımızı görünce: Yalnız Allah’a inandık ve O’na şirk koştuğumuz şeyleri inkar ettik, dediler."},{"n":85,"t":"Ama baskınımızı görüp de öylece inanmaları kendilerine fayda vermedi. Bu; Allah’ın kulları hakkında öteden beri cari olan sünnetidir. Ve işte kafirler burada hüsrana uğramışlardır."}],[{"n":1,"t":"Ha, Mim,"},{"n":2,"t":"Rahman ve Rahim katından indirilmedir."},{"n":3,"t":"Ayetleri uzun uzun açıklanmış bir kitab. Bilen bir kavim için arabça Kur’an."},{"n":4,"t":"Müjdeleyici ve uyarıcı olarak. Ama onların çoğu yüz çevirmiştir, artık onlar işitmezler."},{"n":5,"t":"Bizi, çağırdığın şeye karşı kalblerimiz kapalıdır, kulaklarımızda da bir ağırlık vardır. Seninle bizim aramızda bir perde var. Sen; istediğini yap, biz de yapıcılarız, dediler"},{"n":6,"t":"De ki: Ben de ancak sizin gibi bir beşerim. Yalnız bana tanrınızın tek bir tanrı olduğu vahyediliyor. Artık O’na yönelin ve O’ndan mağfiret dileyin. Müşriklerin vay haline."},{"n":7,"t":"Onlar ki; zekat vermezler. Ve onlar; ahireti inkar edenlerdir."},{"n":8,"t":"Muhakkak ki iman edip salih amel işleyenlere; işte onlara, kesintisiz bir mükafat vardır."},{"n":9,"t":"De ki: Siz mi yeri iki günde yaratanı inkar ediyor ve O’na eşler koşuyorsunuz? Alemlerin Rabbı işte O’dur."},{"n":10,"t":"O; yeryüzüne sabit dağlar yerleştirdi ve orada bereketler yarattı. Ve onda arayanlar için dört beşit gıdalar takdir etti."},{"n":11,"t":"Sonra göğe yöneldi ki; o, duman halindeydi. Ona ve yere dedi ki: İsteyerek veya istemeyerek ikiniz de gelin. İkisi de dediler ki: İsteyerek geldik."},{"n":12,"t":"Böylece iki gün içerisinde yedi gök var etti. Ve her göğün işini kendisine bildirdi. Biz; dünya semasını ışıklarla donattık, koruduk. İşte bu; Aziz, Alim’in takdiridir."},{"n":13,"t":"Eğer yüz çevirecek olurlarsa; Ad ve Semud’un yıldırımına benzer bir yıldırımla sizi uyarırım, de."},{"n":14,"t":"Onlara; Allah’tan başkasına ibadet etmeyin, diye önlerinden ve arkalarından peygamberler geldiğinde demişlerdi ki: Şayet Rabbımız dileseydi; elbette melekler indirirdi. Doğrusu biz, sizinle gönderilen şeyi inkar ederiz."},{"n":15,"t":"Ad’a gelince; yeryüzünde haksız yere büyüklük taslamış ve bizden daha kuvvetli kim var? demişlerdi. Onlar, kendilerini yaratan Allah’ın daha kuvvetli olduğunu görmüyorlar mıydı? Onlar ayetlerimizi bile bile inkar ediyorlardı."},{"n":16,"t":"Böylece uğursuz günlerde dünya hayatında rüsvaylık azabını tattıralım diye Biz de onların üzerine şiddetli bir rüzgar gönderdik. Ahiret azabı ise, elbet daha horlayıcıdır. Onlara yardım da edilmez."},{"n":17,"t":"Semud’a gelince; onlara hidayeti göstermiştik, ama onlar körlüğü hidayete tercih ettiler ve yaptıkları yüzünden onları horlayıcı azabın yıldırımı çarptı."},{"n":18,"t":"İman edip de korkar olanları da kurtardık."},{"n":19,"t":"Allah’ın düşmanları bir araya getirilip toplanacakları gün; onlar, dağıtılırlar."},{"n":20,"t":"Nihayet oraya varınca; kulakları, gözleri ve derileri yapar oldukları şeye aleyhlerinde şehadet ederler."},{"n":21,"t":"Derilerine derler ki: Niçin aleyhimize şahidlik ettiniz? Onlar da: Bizi, her şeyi konuşturan Allah konuşturdu. Sizi önceden yaratan O’dur ve O’na döndürülürsünüz, derler."},{"n":22,"t":"Gözleriniz, kulaklarınız ve derileriniz aleyhinize şahidlik eder diye sakınmadınız. Aksine yapmakta olduklarınızın bir çoğunu Allah’ın bilmediğini sanıyordunuz."},{"n":23,"t":"İşte Rabbınızı böyle sanmanız sizi mahvetti de hüsrana uğrayanlardan oldunuz."},{"n":24,"t":"Şimdi eğer sabredebilirlerse; işte onların durağı ateştir. Eğer dönmek isterlerse; artık onlar hoşnud edilecek değildirler."},{"n":25,"t":"Biz; onlara bir takım yoldaşlar kattık da önlerindekini ve arkalarındakini onlara süslü gösterdiler. Gerek cinnlerden, gerekse insanlardan kendilerinden önce geçmiş ümmetler içinde aleyhlerinde söz hak olmuştur. Doğrusu onlar, hüsrana uğrayanlardı."},{"n":26,"t":"Küfredenler dediler ki: Bu Kur’an’ı dinlemeyin, onun hakkında yaygaralar yapın, belki bastırırsınız."},{"n":27,"t":"O küfredenlere şiddetli bir azabı tattıracağız ve onları yapmakta olduklarının en kötüsü ile cezalandıracağız."},{"n":28,"t":"İşte böyle; Allah’ın düşmanlarının cezası ateştir. Ayetlerimizi bile bile inkar etmelerinin cezası olarak onların temelli kalacakları yer oradadır."},{"n":29,"t":"Ve küfredenler derler ki: Rabbımız; cinnlerden ve insanlardan bizi saptırmış olanları göster, onları ayaklarımızın altına alalım da alçaklar, aşağıların aşağısı olsunlar."},{"n":30,"t":"Muhakkak ki; Rabbımız Allah’tır, deyip sonra dosdoğru bir istikamet tutturanların üzerine melekler iner, onlara: Korkmayın, üzülmeyin size vaad olunan cennetle sevinin, derler."},{"n":31,"t":"Biz; dünya hayatında da, ahirette de sizin dostlarınızız. Burada canlarınızın çektiği şeyler sizedir ve burada size umduğunuz her şey vardır."},{"n":32,"t":"Gafur, Rahim olanın ikramı olarak."},{"n":33,"t":"Muhakkak ki ben müslümanlardanım, diyerek salih amel işleyen ve Allah’a çağıran kimseden daha güzel sözlü kim vardır?"},{"n":34,"t":"İyilikle kötülük bir olmaz. Sen, fenalığı en iyi şekilde sav. O zaman göreceksin ki; seninle arasında düşmanlık bulunan kişi bile yakın bir dost gibi oluvermiştir."},{"n":35,"t":"Bu, ancak sabredenlere vergidir. Ve buna ancak o büyük hazzı tadanlar kavuşturulur."},{"n":36,"t":"Şeytan, seni bir vesvese ile dürtecek olursa; Allah’a sığın. Doğrusu O; Semi, Alim olanın kendisidir."},{"n":37,"t":"Gece ve gündüz, güneş ve ay O’nun ayetlerindendir. Güneşe ve aya secde etmeyin. Eğer O’na ibadet isteyen kimselerseniz; bunları yaratmış olan Allah’a secde edin."},{"n":38,"t":"Eğer büyüklük taslarlarsa; bilsinler ki, Rabbının nezdinde bulunanlar gece gündüz O’nu tesbih eder dururlar ve onlar hiç usanmazlar."},{"n":39,"t":"O’nun ayetlerinden biri de, kupkuru gördüğün yeryüzünün Biz ona su indirdiğimiz zaman harekete geçip kabarmasıdır. Ona can veren Allah, elbette ölüleri de diriltir. Muhakkak ki O; her şeye kadirdir."},{"n":40,"t":"Ayetlerimiz hakkında doğruluktan ayrılıp eğriliğe sapanlar, bize gizli değillerdir. Ateşe atılan mı, yoksa kıyamet günü güven içinde olan mı daha iyidir? Dilediğinizi yapın. Doğrusu O; yaptıklarınızı görendir."},{"n":41,"t":"Kendilerine zikir gelince; onlar onu inkar etmişlerdir. Halbuki o, aziz bir kitabdır."},{"n":42,"t":"Önünden de, ardından da batıl sokulamaz. O, Hakim, Hamid katından indirilmedir."},{"n":43,"t":"Senin için söylenenler, mutlaka senden önceki peygamberler için de söylenmiştir. Elbette ki Rabbın; hem mağfiret sahibidir, hem de elim bir azab sahibidir."},{"n":44,"t":"Biz; onu yabancı bir dil ile ortaya koysaydık diyeceklerdi ki: Ayetleri tafsilatlı olarak açıklamalı değil miydi? Hem yabancı, hem da Arab’a mı hitab etmektedir? De ki: İman edenler için hidayet ve şifadır. İman etmemiş olanların kulaklarında ise bir ağırlık vardır ve bu, onlara kapalıdır. Sanki onlara uzak bir mesafeden sesleniyorlar da anlamıyorlar."},{"n":45,"t":"Andolsun ki; Biz, Musa’ya kitab vermiştik de onda ihtilafa düşülmüştü. Şayet Rabbından bir söz geçmiş olmasaydı; aralarında hüküm verilirdi. Muhakkak ki onlar; bundan şüphe ve endişe içindedirler."},{"n":46,"t":"Kim, salih amel işlerse; kendi lehinedir. Kim de kötülük yaparsa; kendi aleyhinedir. Ve Rabbın; kullarına zulmedici değildir."},{"n":47,"t":"Kıyamet saatının bilgisi, ancak O’na aittir. O’nun ilmi olmadıkça hiç bir meyve tomurcuklarından çıkmaz. Hiç bir dişi gebe kalmaz ve doğurmaz. Onlara: Nerede Benim ortaklarım? diye seslendiği gün derler ki: Bizden hiç bir şahid olmadığını Sana arzederiz."},{"n":48,"t":"Önceden taptıkları şeyler onlardan uzaklaşıp gitmiştir. Ve kendilerinin kaçacak yerleri olmadığını anlamışlardır."},{"n":49,"t":"İnsan; hayır istemekten usanmaz da, kendisine bir kötülük gelince ümitsizliğe düşer, meyus olur."},{"n":50,"t":"Oysa ona dokunan bir sıkıntıdan sonra kendisine katımızdan bir rahmet tattırırsak; muhakkak: Bu, benim hakkımdır, kıyametin kopacağını sanmıyorum. Rabbıma döndürülürsem, muhakkak ki O’nun nezdinde de güzel şeyler bulacağım, der. Andolsun ki; Biz, küfredenlere yaptıklarını muhakkak bildireceğiz. Ve andolsun ki; Biz, onlara muhakkak ağır bir azab tattıracağız."},{"n":51,"t":"İnsana nimet verdiğimiz zaman yüz çevirir, yan çizer. Başına bir fenalık gelince de uzun uzun yalvarır."},{"n":52,"t":"De ki: Şayet o, Allah katından gelmiş ve siz de onu inkar etmişseniz; söyleyin bana: Derin bir çıkmazda bulunan kimseden daha sapık kim vardır?"},{"n":53,"t":"Onun hak olduğunu anlayıncaya kadar ayetlerimizi onlara hem ufuklarda hem de kendi nefislerinde göstereceğiz. Rabbının her şeye şahid olması yetmez mi?"},{"n":54,"t":"İyi bilin ki; onlar, Rabblarına kavuşmaktan şüphededirler. Dikkat edin, muhakkak ki Allah; her şeyi çepeçevre kuşatandır."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Ayn, Sin, Kaf."},{"n":3,"t":"Aziz, Hakim olan Allah sana da, senden öncekilere de böyle vahyeder."},{"n":4,"t":"Göklerde olanlar da, yerde olanlar da O’nundur. O, Aliyy’dir, Azim’dir."},{"n":5,"t":"Nerede ise gökler tepelerinden çatlayacaklar. Melekler de Rabblarını hamd ile tesbih ediyorlar; yeryüzünde bulunanlar için O’ndan bağışlanma diliyorlar. İyi bilin ki; Allah, muhakkak Gafur, Rahim olandır."},{"n":6,"t":"Ondan başka veliler edinenlere gelince; Allah, onların üzerinde daima gözetleyicidir. Sen, onların üzerinde vekil değilsin."},{"n":7,"t":"Şehirlerin anasını ve onun çevresinde bulunanları uyarman ve hakkında hiç bir şüphe bulunmayan o toplanma günüyle korkutman için, sana böyle arabça bir Kur’an vahyettik. Bir fırka cennette, bir fırka da çılgın alevli cehennemdedir."},{"n":8,"t":"Şayet Allah dileseydi; hepsini tek bir ümmet yapardı. Ama O; dilediğini rahmetine sokar. Zalimlere gelince; onlar için ne bir veli vardır, ne de bir yardımcı."},{"n":9,"t":"Yoksa O’ndan başka veliler mi edindiler? İşte Allah; O’dur veli. Ölüleri O, diriltir. Ve O, her şeye kadirdir."},{"n":10,"t":"İhtilafa düştüğünüz herhangi bir şeyde hüküm Allah’ındır. İşte Rabbım Allah budur. Ben, O’na tevekkül ettim ve yalnız O’na yöneldim."},{"n":11,"t":"Göklerin ve yerin yaratanı, size kendinizden eşler yarattı. Davarlardan da çiftler. Bu suretle çoğalmanızı sağlıyor. O’nun benzeri hiç bir şey yoktur. Ve O; Semi’dir, Basir’dir."},{"n":12,"t":"Göklerin ve yerin anahtarları O’nundur. Dilediğinin rızkını genişletir, ve kısar. Muhakkak ki O; her şeyi bilendir."},{"n":13,"t":"Dine bağlı kalın ve onda tefrikaya düşmeyin, diye dinden Nuh’a buyurduğunu, size de teşri buyurdu. Sana vahyettiğimizi ve İbrahim’e, Musa’ya, İsa’ya buyurduğumuzu. Kendilerini çağırdığın bu şey; müşriklere ağır geldi. Allah; dilediğini kendisine seçer. Kendisine yöneleni de hidayete iletir."},{"n":14,"t":"Onlar; kendilerine ilim geldikten sonra aralarındaki ihtiras yüzünden ayrılığa düştüler. Şayet belirli bir süre için Rabbından bir söz geçmiş olmasaydı, aralarında hüküm verilirdi. Onlardan sonra kitaba varis kılınanlar da ondan mutlak bir şüphe ve tereddüt içindedirler."},{"n":15,"t":"Şu halde sen, bunun için davet et ve emrolunduğun şekilde dosdoğru bir istikamet tuttur. Onların heveslerine uyma. Ve de ki: Ben, Allah’ın indirdiği kitaba inandım ve aranızda adalet etmekle emrolundum. Allah; bizim de Rabbımız, sizin de Rabbınızdır. Bizim işlediklerimiz bize, sizin işledikleriniz sizedir. Bizimle sizin aranızda tartışılacak hiç bir şey yoktur. Allah; hepimizi bir araya toplar ve dönüş de O’nadır."},{"n":16,"t":"Kabul ettikten sonra Allah’ın dini hakkında tartışmaya girişenlerin delilleri Rabbları katında boştur. Onların üzerine hem bir gazab, hem de şiddetli bir azab vardır."},{"n":17,"t":"Allah, O’dur ki; kitabı ve mizanı hak ile indirmiştir. Ne bilirsin; belki de o saat yakındır."},{"n":18,"t":"Buna inanmayanlar onun çabucak gelmesini isterler. İman edenler ise, ondan korku ile titrerler ve onun hak olduğunu bilirler. İyi bilin ki; kıyamet günü hakkında tartışanlar derin bir sapıklık içindedirler."},{"n":19,"t":"Allah; kullarına çok lutufkardır. Dilediğini rızıklandırır. O’dur Kavi, Aziz."},{"n":20,"t":"Kim, ahiret ekinini isterse; onun ekinini arttırırız. Kim de dünya ekinini isterse; ona da bundan veririz. Ancak onun ahirette bir nasibi yoktur."},{"n":21,"t":"Yoksa Allah’ın izin vermediği bir şeyi, dinde onlara şeriat kılacak ortakları mı var? Şayet kesin söz bulunmayacak olsaydı; aralarında derhal hüküm verilirdi. Doğrusu zalimlere elim bir azab vardır."},{"n":22,"t":"Göreceksin ki; zalimler yaptıkları şeyler başlarına gelirken korkudan titrerler. İman edip salih amel işleyenler ise cennet bahçelerindedirler. Rabblarının katında onlara diledikleri vardır. İşte bu; büyük lutfun kendisidir."},{"n":23,"t":"İşte Allah’ın iman edip salih ameller işleyen kullarına müjdelediği budur. De ki: Ben, sizden buna karşılık; akrabalıkta sevgiden başka bir ücret istemem. Kim, bir iyilik kazanırsa; Biz onun iyiliğini arttırırız. Muhakkak ki Allah; Gafur’dur, Şekur’dur."},{"n":24,"t":"Yoksa onlar; Allah’a karşı yalan uydurdu mu derler? Allah; dilerse senin kalbini mühürler, batılı yok eder, sözleriyle hakkı yerine getirir. Muhakkak ki O; göğüslerin özünü bilendir."},{"n":25,"t":"O; kullarından tevbeyi kabul eden, kötülükleri bağışlayan ve yaptıklarını bilendir."},{"n":26,"t":"İman edip salih ameller işleyenlerin duasını kabul buyurur ve onlara lutfundan arttırır. Kafirlere gelince; onlar için şiddetli bir azab vardır."},{"n":27,"t":"Şayet Allah kulları için rızkı geniş tutsaydı; yeryüzünde azgınlık ederlerdi. Fakat O; dilediği ölçüde indirir. Muhakkak ki O; kulları için Habir’dir, Basir’dir."},{"n":28,"t":"O’dur ki; ümidlerini kestikten sonra yağmuru indirir ve rahmetini yayar. O; Veli’dir, Hamid’dir."},{"n":29,"t":"Gökleri, yeri ve ikisinde yaydığı canlıları yaratması da O’nun ayetlerindendir. O, dileyince bunları toplamaya da hakkıyla kadirdir."},{"n":30,"t":"Size musibetten ne gelirse, kendi ellerinizin kazandığındandır. Bununla beraber O, çoğunu affeder."},{"n":31,"t":"Yeryüzünde O’nu aciz bırakamazsınız. Ve sizin Allah’tan başka ne bir veliniz vardır, ne de bir yardımcınız."},{"n":32,"t":"Denizde dağlar gibi akıp giden gemiler de O’nun ayetlerindendir."},{"n":33,"t":"Dilerse O; rüzgarı durdurur da denizin yüzünde durakalırlar. Muhakkak ki bunda, sabırlı olan ve çok şükreden kimseler için ayetler vardır."},{"n":34,"t":"Yahut yaptıklarına karşılık onları helak eder. Bir çoğunu da bağışlar."},{"n":35,"t":"Ayetlerimiz üzerinde tartışanlar bilsinler ki; kendileri için kaçacak bir yer yoktur."},{"n":36,"t":"Size verilen herhangi bir şey, yalnızca dünya hayatının bir geçimliliğidir. Allah katında olan ise, hem daha hayırlı, hem de daha bakidir. Bu; iman edenler ve Rabblarına tevekkül edenler içindir."},{"n":37,"t":"Ve büyük günahlardan, hayasızlıktan çekinenler, öfkelendiklerinde bile bağışlayanlar içindir."},{"n":38,"t":"Ve Rabblarına icabet edenler, namaz kılanlar içindir. Onların işleri aralarında şura iledir. Kendilerine verdiğimiz rızıktan da infak ederler."},{"n":39,"t":"Onlar ki; kendilerine zulüm vaki olunca yardımlaşırlar."},{"n":40,"t":"Kötülüğün karşılığı; ona denk bir kötülüktür. Kim, affeder ve ıslah ederse; ecri Allah’a aittir. Muhakkak ki Allah; zalimleri sevmez."},{"n":41,"t":"Kim, zulme uğradıktan sonra hakkını alırsa; aleyhine bir yol yoktur."},{"n":42,"t":"Yol; ancak insanlara zulmedenler ve yeryüzünde haksız yere taşkınlık edenler içindir. İşte onlara elim bir azab vardır."},{"n":43,"t":"Bununla beraber kim de sabreder ve bağışlarsa; işte bu, şüphesiz azmedilmeye değer işlerdendir."},{"n":44,"t":"Kimi de Allah saptırırsa; bundan sonra artık onun için bir veli yoktur. Göreceksin ki; o zalimler, azabı gördükleri zaman: Geri dönecek bir yol yok mudur? diyeceklerdir."},{"n":45,"t":"Ve onları ateşe sunulurken zilletten başları öne eğilmiş, göz ucuyla gizli gizli çevreye bakarken göreceksin. İman etmiş olanlar da derler ki: Hüsranda olanlar; kıyamet günü kendilerini de, ailelerini de hüsranda bırakanlardır. İyi bilin ki; zalimler muhakkak sürekli bir azab içindedirler."},{"n":46,"t":"Onların Allah’tan başka kendilerine yardım edecek velileri de yoktur. Kimi de Allah saptırırsa; artık onun için bir yol yoktur."},{"n":47,"t":"Allah katından, geri çevrilmesi imkansız bir gün gelmezden önce, Rabbınıza icabet edin. O gün; hiç biriniz için sığınacak bir yer yoktur, inkar da edemezsiniz."},{"n":48,"t":"Eğer onlar yine yüz çevirirlerse; Biz, seni onların üzerine bekçi olarak göndermedik. Senin vazifen, sadece tebliğdir. Gerçekten Biz, insana katımızdan bir rahmet tattırırsak; o bununla sevinir. Ama elleriyle işlediklerinden ötürü başlarına bir fenalık gelirse; işte o zaman insan, cidden pek nankördür."},{"n":49,"t":"Göklerin ve yerin mülkü Allah’ındır. Dilediğini yaratır. Dilediğine dişiler bağışlar, dilediğine ne erkekler bağışlar."},{"n":50,"t":"Veya hem dişi, hem erkek olmak üzere çift verir. Dilediğini de kısır bırakır. Muhakkak ki O; Alim’dir, Kadir’dir."},{"n":51,"t":"Bir beşer için Allah’ın kendisiyle konuşması olacak şey değildir. Meğer ki bir vahy ile veya perde arkasından, yahut bir elçi gönderip de izni ile dilediğini vahyetsin. Muhakkak ki O; Aliyy’dir, Hakim’dir."},{"n":52,"t":"İşte böylece Biz; sana da emrimizden bir ruh vahyettik. Sen kitab nedir, iman nedir bilmezdin. Fakat Biz; onu, kullarımızdan dilediğimizi hidayete eriştirdiğimiz bir nur kıldık. Şüphesiz ki sen, dosdoğru bir yolu göstermektesin."},{"n":53,"t":"Göklerde ve yerde olanların kendisine ait olduğu Allah’ın dosdoğru yolunu. İyi bilin ki; bütün işler sonunda Allah’a döner."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Apaçık kitaba andolsun ki;"},{"n":3,"t":"Düşünüp anlayasınız diye gerçekten Biz, onu arabça bir Kur’an kılmışızdır"},{"n":4,"t":"O nezdimizdeki ana kitabdadır. Şanı yücedir, hikmet doludur."},{"n":5,"t":"Haddi aşan bir kavimsiniz diye, sizi o Kur’an’la uyarmaktan vaz mı geçelim?"},{"n":6,"t":"Daha öncekilere nice peygamberler göndermiştik."},{"n":7,"t":"Kendilerine bir peygamber gelmeyedursun mutlaka onunla alay ederlerdi."},{"n":8,"t":"Biz, bunlardan daha güçlü olanları helak ettik. Öncekilerin misali geçti."},{"n":9,"t":"Andolsun ki; onlara: Gökleri ve yeri kim yarattı? diye sorsan, muhakkak: Onları Aziz, Alim yaratmıştır, diyeceklerdir."},{"n":10,"t":"O ki; yeri, sizin için bir beşik kılmış, doğru gidesiniz diye orada yollar var etmiştir."},{"n":11,"t":"O ki; gökten bir ölçüye göre su indirmiştir. İşte Biz, onunla ölü bir memleketi dirilttik, siz de böylece çıkarılacaksınız."},{"n":12,"t":"Ve O ki; bütün çiftleri yaratmıştır. Sizin için bineceğiniz gemiler ve davarlar var etmiştir."},{"n":13,"t":"Ta ki bunların üzerine oturunca, Rabbınızın nimetini anarak: Bunları bize müsahhar kılan ne yücedir, yoksa biz bunlara güç yetiremezdik, diyesiniz."},{"n":14,"t":"Ve biz, şüphesiz Rabbımıza döneceğiz."},{"n":15,"t":"Ama onlar; kullarından bir kısmını, O’nun bir parçası saydılar. İnsan, gerçekten apaçık bir nankördür."},{"n":16,"t":"Yoksa; Allah, yarattıkları arasından kızları kendisine alıp oğulları size mi ayırdı?"},{"n":17,"t":"Ama Rahman’a isnad edilen kız evladla onlardan birisi müjdelenince; yüzü kapkara kesilir de öfkesinden yutkunur durur."},{"n":18,"t":"Yoksa süs içinde yetiştirilip de mücadelede açık olmayanı mı?"},{"n":19,"t":"Onlar; Rahman’ın kulları olan melekleri de dişi saydılar. Yaratılışlarını mı görmüşler. Onların şehadetleri yazılacak ve onlar sorguya çekileceklerdir."},{"n":20,"t":"Ve derler ki: Eğer Rahman dilemiş olsaydı; biz, onlara ibadet etmezdik. Onların bu konuda bir bilgileri yoktur. Onlar, yalnız yalan söyleyip dururlar."},{"n":21,"t":"Yoksa; daha önce onlara bir kitab verdik de ona mı tutunuyorlar?"},{"n":22,"t":"Hayır, dediler ki: Doğrusu biz, atalarımızı bir ümmet üzerinde bulduk ve biz de onların izlerinden gitmekteyiz."},{"n":23,"t":"Senden önce de hangi kasabaya bir uyarıcı gönderdiysek; o kasabanın varlıklıları sadece dediler ki: Doğrusu biz, babalarımızı bir ümmet üzerinde bulduk ve biz de onların izlerine uymaktayız."},{"n":24,"t":"Şayet size atalarınızı üzerinde bulduğunuz şeyden daha doğrusunu getirmişsem; yine mi bana uymazsınız? deyince, dediler ki: Doğrusu sizin gönderildiğiniz şeyi, biz inkar ediyoruz."},{"n":25,"t":"Biz de onlardan intikam aldık. Yalanlayanların sonunun nasıl olduğuna bir bak."},{"n":26,"t":"Hani İbrahim; babasına ve kavmine demişti ki: Şüphesiz ben, sizin taptığınız şeylerden uzağım."},{"n":27,"t":"Beni yaratan müstesna. Şüphesiz ki O; beni hidayete iletecektir."},{"n":28,"t":"Ve onu; belki dönerler diye ardından gelenler için kalıcı bir kelime kıldı."},{"n":29,"t":"Hayır. Ben, onları da, atalarını da hakkı açıklayan bir peygamber gelene kadar geçindirdim."},{"n":30,"t":"Hak kendilerine geldiğinde ise: Bu bir büyüdür. Doğrusu biz, onu inkar ediyoruz, dediler."},{"n":31,"t":"Ve dediler ki: Bu Kur’an, o iki kasabanın birinden büyük bir adama indirilmeli değil miydi?"},{"n":32,"t":"Yoksa Rabbının rahmetini onlar mı paylaştırıyorlar? Dünya hayatında onların geçimlerini aralarında Biz paylaştırdık. Birbirlerine iş gördürebilmeleri için kimini kimine derecelerle üstün kıldık. Rabbının rahmeti, onların biriktirdikleri şeylerden daha hayırlıdır."},{"n":33,"t":"Şayet insanlar, tek bir ümmet haline gelmeyecek olsaydı; Rahman’ı inkar edenlerin evlerinin tavanlarını ve üzerinde yükseldikleri merdivenleri gümüşten yapardık."},{"n":34,"t":"Evlerinin kapılarını ve üzerlerine yaslanacakları kerevetleri de,"},{"n":35,"t":"Altına boğardık. Bunların hepsi sadece dünya hayatının geçimliğidir. Ahiret ise; Rabbının katında müttakiler içindir."},{"n":36,"t":"Kim, Rahman’ın zikrinigörmezlikten gelirse; Biz, ona şeytanı musallat ederiz."},{"n":37,"t":"Şüphesiz ki onlar da bunları yoldan çıkarırlar. Bunlar ise doğru yolda olduklarını sanırlar."},{"n":38,"t":"Nihayet Bize gelince der ki: Keşki benimle senin aranda Doğu ile Batı arasındaki kadar uzaklık olsaydı. Sen, ne kötü arkadaş imişsin."},{"n":39,"t":"Zulmettiğiniz için, bugün pişmanlığın hiç bir faydası yoktur. Muhakkak ki azabda ortaksınız."},{"n":40,"t":"Sen mi duyuracaksın o sağırlara? Körleri ve apaçık sapıklıkta olanları sen mi hidayete eriştireceksin?"},{"n":41,"t":"Seni onlardan uzaklaştırsak da; muhakkak ki Biz, onlardan intikam alırız."},{"n":42,"t":"Yahut da onlara vaadettiğimizi sana gösteririz. Çünkü Biz, onlara karşı gücü yetenleriz."},{"n":43,"t":"Sen; sana vahyolunana sarıl. Muhakkak ki sen, dosdoğru bir yol üzerindesin."},{"n":44,"t":"Doğrusu bu; sana ve kavmine bir öğüttür. Ondan sorguya çekileceksiniz."},{"n":45,"t":"Senden önce gönderdiğimiz peygamberlerimize sor: Biz, Rahman’dan başka ibadet edecek tanrılar kılmış mıyız?"},{"n":46,"t":"Andolsun ki; Biz, Musa’yı da ayetlerimizle Firavun’a ve erkanına göndermiştik. Ve demişti ki: Şüphesiz ben, alemlerin Rabbının elçisiyim."},{"n":47,"t":"Onlara ayetlerimizle varınca, onlar bunlara gülüvermişlerdi."},{"n":48,"t":"Onlara biri diğerinden daha büyük olmayan hiç bir ayet göstermedik. Doğru yola dönmeleri için onları azaba uğrattık."},{"n":49,"t":"Ve dediler ki: Ey sihirbaz; sana verdiği ahde göre Rabbına bizim için dua et. Muhakkak biz, hidayete eriştirilmiş olacağız."},{"n":50,"t":"Azabı üzerlerinden kaldırınca, hemen sözlerinden caydılar."},{"n":51,"t":"Firavun, kavmine seslendi ve dedi ki: Ey kavmim; Mısır mülkü ve altımdan akan şu ırmaklar benim değil mi? Hala görmüyor musunuz?"},{"n":52,"t":"Ben, açıkça söyleyemeyecek derecede zavallı olan şu adamdan daha hayırlı değil miyim?"},{"n":53,"t":"Ona altın bilezikler verilmeli veya beraberinde kendisine yardım edecek melekler gelmeli değil miydi?"},{"n":54,"t":"Firavun, kavmini küçümsedi, ama onlar yine de kendisine itaat ettiler. Çünkü onlar, fasık olan bir kavim idi."},{"n":55,"t":"Bizi öfkelendirince; onlardan intikam aldık ve hepsini suda boğduk."},{"n":56,"t":"Ve onları, sonradan geleceklere bir geçmiş ve örnek kıldık."},{"n":57,"t":"Meryem’in oğlu misal olarak verilince; senin kavmin hemen bağrıştı."},{"n":58,"t":"Ve: Bizim tanrılarımız mı, yoksa o mu daha iyidir? dediler. Sana böyle demeleri, sadece tartışmaya girişmek içindir. Hayır, onlar kavgacı bir kavimdir."},{"n":59,"t":"O; kendisine nimet verdiğimiz ve İsrailoğullarına örnek kıldığımız bir kuldur."},{"n":60,"t":"Şayet dileseydik; sizden, yeryüzünde sizin yerinizi tutacak melekler var ederdik."},{"n":61,"t":"Şüphesiz ki o, saatın bilgisidir. O’ndan hiç şüphe etmeyin ve Bana tabi olun. İşte doğru yol."},{"n":62,"t":"Sakın şeytan sizi çevirmesin. Şüphesiz ki o, size apaçık bir düşmandır."},{"n":63,"t":"İsa huccetlerle gelince; demişti ki: Size hikmetle ve ihtilafa düştüğünüz şeylerin bir kısmını açıklamak için geldim. Öyleyse Allah’tan korkun ve bana itaat edin."},{"n":64,"t":"Muhakkak ki Allah, benim de Rabbımdır, sizin de Rabbınızdır. Öyleyse O’ na ibadet edin. İşte doğru yol."},{"n":65,"t":"Ama aralarında hizibler birbirleriyle ihtilafa düştüler. Acıklı bir günün azabından vay o zulmedenlerin haline."},{"n":66,"t":"Onlar, farkında değillerken kendilerine ansızın o saatın gelmesini mi bekliyorlar?"},{"n":67,"t":"O gün; müttakilerin dışında, dostlar birbirlerine düşman olurlar."},{"n":68,"t":"Ey kullarım; bugün size korku yoktur. Ve siz, üzülecek de değilsiniz."},{"n":69,"t":"Onlar ki; ayetlerimize iman etmiş ve müslüman olmuşlardır."},{"n":70,"t":"Siz ve eşleriniz, ağırlanmış olarak cennete girin."},{"n":71,"t":"Onlara altın kadehler ve tepsiler dolaştırılır. Canların istediği ve gözlerin hoşlandığı her şey oradadır. Ve siz, orada ebediyyen kalacaksınız."},{"n":72,"t":"İşte o cennet, işlediklerinize karşılık size miras kılındı."},{"n":73,"t":"Orada sizin için meyveler vardır. Ve onlardan yersiniz."},{"n":74,"t":"Muhakkak ki mücrimler; ebediyyen kalacakları cehennem azabındadırlar."},{"n":75,"t":"Azablarına ara verilmeyecek ve orada tamamen ümitsiz kalacaklardır."},{"n":76,"t":"Biz onlara zulmetmedik, ama onlar zalimlerin kendileridir."},{"n":77,"t":"Ey nöbetçi; Rabbın hiç olmazsa bizi ölüme mahkum etsin, diye çağırışırlar. O da: Siz, böyle kalacaksınız, der."},{"n":78,"t":"Andolsun ki; size hak ile geldik. Fakat çoğunuz hakkı hoş görmüyordunuz."},{"n":79,"t":"Yoksa bir işe mi karar verdiler? Doğrusu Biz de kararlıyız."},{"n":80,"t":"Yoksa kendilerinin sırlarını ve gizli konuşmalarını işitmiyoruz mu sanıyorlar? Hayır, öyle değil, yanlarındaki elçilerimiz yazmaktadır."},{"n":81,"t":"De ki: Eğer Rahman’ın çocuğu olsaydı; o takdirde ben, kulluk edenlerin ilkiydim."},{"n":82,"t":"Göklerin ve yerin Rabbı, Arş’ın Rabbı onların tavsiflerinden münezzehtir."},{"n":83,"t":"Bırak onları, kendilerine vaadedilen güne ulaşıncaya kadar dalsınlar, oyalanıp dursunlar."},{"n":84,"t":"Gökte de ilah, yerde de ilah O’dur. Ve O; Hakim’dir, Alim’dir."},{"n":85,"t":"Göklerin, yerin ve ikisi arasında bulunanların mülkü kendisine ait olan ne yücedir. Kıyamet saatının bilgisi O’nun katındadır ve O’na döndürüleceksiniz."},{"n":86,"t":"O’ndan başka tapındıkları şeyler, şefaat edemezler. Ancak hak ile şehadet edenler bunun dışındadır ve onlar bilirler."},{"n":87,"t":"Andolsun ki; onlara, kendilerini kimin yarattığını sorsan elbette; Allah, diyeceklerdir. O halde neye çevriliyorlar?"},{"n":88,"t":"Onun: Ey Rabbım, demesi hakkı için, muhakkak ki bunlar inanmayan bir kavimdir."},{"n":89,"t":"Şimdilik sen, onlardan yüz çevir ve; selam, de. Yakında bileceklerdir."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Apaçık kitaba andolsun ki;"},{"n":3,"t":"Gerçekten Biz; onu, mübarek bir gecede indirdik. Doğrusu Biz, uyarıcı idik."},{"n":4,"t":"Ki onda her hikmetli iş ayrılır."},{"n":5,"t":"Katımızdan bir emirle. Muhakkak ki Biz, peygamber gönderenleriz."},{"n":6,"t":"Rabbından bir rahmet olarak. Gerçekten O; Semi, Alim olanın kendisidir."},{"n":7,"t":"Göklerin, yerin ve ikisi arasında bulunanların Rabbından. Şayet kesin olarak inanıyorsanız."},{"n":8,"t":"Ondan başka ilah yoktur. Diriltir ve öldürür. Sizin de Rabbınızdır, sizden önceki atalarınızın da Rabbıdır."},{"n":9,"t":"Hayır, onlar şüphe içinde oynayıp dururlar."},{"n":10,"t":"Öyleyse sen gözle. Göğün açıkça bir duman çıkaracağı gün;"},{"n":11,"t":"İnsanları bürüyecektir. Bu; elim bir azabdır."},{"n":12,"t":"Rabbımız; bu azabı bizden kaldır. Doğrusu biz, artık mü’minleriz."},{"n":13,"t":"Nerede onlarda öğüt almak? Kendilerine gerçeği açıklayan bir peygamber gelmişti."},{"n":14,"t":"Ondan yüz çevirmişler; belletilmiş delinin biri, demişlerdi"},{"n":15,"t":"Biz, az bir süre için azabı kaldıracağız. Ama siz, eski halinize döneceksiniz."},{"n":16,"t":"Onları çarptıkça çarpacağımız gün; şüphesiz intikam alırız."},{"n":17,"t":"Andolsun ki; onlardan önce Firavun kavmini de denemiştik ve onlara kerim bir peygamber gelmişti."},{"n":18,"t":"Allah’ın kullarını bana teslim edin. Doğrusu ben, size gönderilmiş emin bir peygamberim."},{"n":19,"t":"Allah’a karşı yücelik taslamayın. Doğrusu ben, size açık bir burhan getirdim."},{"n":20,"t":"Beni taşlamanızdan ötürü; benim de Rabbım, sizin de Rabbınız olana sığındım."},{"n":21,"t":"Eğer bana inanmazsanız; benden uzaklaşıp gidin."},{"n":22,"t":"Bunlar, suçlu bir kavimdir, diyerek Rabbına dua etti."},{"n":23,"t":"Öyleyse kullarımı geceleyin yürüt, siz muhakkak takip olunacaksınız."},{"n":24,"t":"Denizi sakin iken geride bırak. Doğrusu onlar, suda boğulacak bir ordudur."},{"n":25,"t":"Onlar, nice nice bağları, pınarları bırakmışlardı."},{"n":26,"t":"Ekinleri, muhteşem konakları da."},{"n":27,"t":"Zevk ve safa sürdükleri nimetleri de."},{"n":28,"t":"İşte böyle. Onlara başka kavimleri mirasçı kıldık."},{"n":29,"t":"Gök ve yer onların helakine ağlamadı. Ve onlar, mühlet verilenler de olmadı."},{"n":30,"t":"Andolsun ki; İsrailoğullarını horlayıcı azabdan kurtardık,"},{"n":31,"t":"Firavun’dan. Doğrusu o, azgın bir zorba idi."},{"n":32,"t":"Ve andolsun ki; Biz, onları bile bile alemler üzerinde seçkin kıldık."},{"n":33,"t":"Onlara ayetlerden öylelerini verdik ki; her birinde açıkça bir imtihan vardı."},{"n":34,"t":"Bunlar gerçekten derler ki:"},{"n":35,"t":"O, ilk ölümümüzden başkası değildir. Ve biz, diriltilip kaldırılacaklar da değiliz."},{"n":36,"t":"Doğru sözlüler iseniz; bize babalarımıza getirsenize."},{"n":37,"t":"Bunlar mı daha hayırlı, yoksa Tübba kavmi ile onlardan evvel gelenler mi? Biz, onları helak ettik. Muhakkak ki onlar, mücrimler idiler."},{"n":38,"t":"Biz; gökleri, yeri ve ikisinin arasındakileri oyun ve oyalanma olsun diye yaratmadık."},{"n":39,"t":"Biz; onları, ancak hak ile yarattık. Ne var ki onların çoğu, bilmezler."},{"n":40,"t":"Muhakkak ki ayırdetme günü, hepsinin bir arada bulunacağı vakittir."},{"n":41,"t":"O gün; dostun dosta hiç bir yardımı olmaz, yardım da görmezler."},{"n":42,"t":"Ancak Allah’ın merhamet ettiği müstesna. Muhakkak ki O; Aziz, Rahim olanın kendisidir."},{"n":43,"t":"Doğrusu zakkum ağacı;"},{"n":44,"t":"Günahkarların yiyeceğidir."},{"n":45,"t":"Erimiş maden gibidir. Karınlarında kaynar,"},{"n":46,"t":"Suyun kaynaması gibi."},{"n":47,"t":"Yakalayın onu, cehennemin ortasına sürükleyin."},{"n":48,"t":"Sonra azab olarak başına kaynar su dökün."},{"n":49,"t":"Tad bakalım; hani güçlü olan, değerli olan yalnız sendin?"},{"n":50,"t":"İşte bu; doğrusu şüphelenip durduğunuz şeydir."},{"n":51,"t":"Müttakiler ise; muhakkak ki emin bir makamdadırlar."},{"n":52,"t":"Bahçelerde ve pınar başlarında."},{"n":53,"t":"İnce ipekten ve parlak atlastan giyerler, karşılıklı otururlar."},{"n":54,"t":"İşte böyle. Onları iri siyah gözlülerle evlendiririz."},{"n":55,"t":"Orada emniyet içerisinde her meyveyi isteyebilirler."},{"n":56,"t":"Orada ilk ölümden başka bir ölüm tatmazlar. Ve onları cehennem azabından korumuştur."},{"n":57,"t":"Rabbından bir lutuf olarak. İşte bu, büyük kurtuluşun kendisidir."},{"n":58,"t":"Biz; onu, öğüt alsınlar diye senin dilinde indirerek kolayca anlaşılmasını sağladık."},{"n":59,"t":"Öyleyse bekle, onlar da beklemektedirler."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Kitabın indirilmesi; Aziz, Hakim Allah’tandır."},{"n":3,"t":"Muhakkak ki göklerde ve yerde mü’minler için ayetler vardır."},{"n":4,"t":"Sizin yaratılmanızda ve yeryüzüne yaydığı her canlıda yakinen inanan topluluklar için ayetler vardır."},{"n":5,"t":"Gece ve gündüzün değişmesinde ve Allah’ın gökten indirmiş olduğu rızıkla ölümünden sonra yeri diriltmesinde, rüzgarları yönetmesinde akleden bir kavim için ayetler vardır."},{"n":6,"t":"İşte bunlar; Allah’ın ayetleridir. Onları sana hak ile okuyoruz. Artık Allah’tan ve onun ayetlerinden sonra hangi söze inanırlar."},{"n":7,"t":"Yalancı, günahkar her kişinin vay haline."},{"n":8,"t":"Kendisine okunan Allah’ın ayetlerini dinleyip de sonra onları hiç duymamış gibi büyüklük taslamakta direnir. Ona elim bir azabı müjdele."},{"n":9,"t":"Ayetlerimizden bir şey öğrendiğinde onu alaya alır. İşte onlara, horlayıcı bir azab vardır."},{"n":10,"t":"Arkalarından da cehennem. Kazandıkları şeyler de, Allah’tan başka edindikleri veliler de onlara bir fayda vermez. Ve onlar için, büyük bir azab vardır."},{"n":11,"t":"Bu; hidayettir. Rabblarının ayetlerini inkar edenlere gelince; çetin ve elim bir azab vardır."},{"n":12,"t":"Emri gereğince denizde yüzmek üzere gemileri ve lutfedip verdiği rızkı aramanız için denizi size boyun eğdiren Allah’tır. Umulur ki şükredersiniz."},{"n":13,"t":"Göklerde olanları, yerde olanları, hepsini size musahhar kılmıştır. Elbette ki düşünen bir kavim için bunda ayetler vardır."},{"n":14,"t":"İman edenlere söyle: Allah’ın günlerinin geleceğini ummayan kimseleri bağışlayıp geçsinler. Çünkü Allah, her kavmi yaptıklarıyla cezalandıracaktır."},{"n":15,"t":"Her kim, salih amel işlerse; kendi lehinedir. Kim de kötülük yaparsa; aleyhinedir. Sonra Rabbınıza döndürüleceksiniz."},{"n":16,"t":"Andolsun ki; Biz, İsrailoğullarına kitabı, hükmü ve nübüvveti vermiştik. Onları temiz şeylerden rızıklandırmış ve dünyalara üstün kılmıştık."},{"n":17,"t":"Ve onlara emirden burhanlar verdik. Ama onlar, kendilerine ilim geldikten sonra aralarındaki çekememezlikten dolayı ayrılığa düştüler. Elbette Rabbın; ayrılığa düştükleri şeyler hakkında kıyamet günü aralarında hüküm verecektir."},{"n":18,"t":"Sonra seni de emirden bir şeriat üzere kıldık. Öyleyse sen; ona uy, sakın bilmeyenlerin heveslerine uyma."},{"n":19,"t":"Muhakkak ki onlar; Allah’a karşı sana hiç bir fayda veremezler. Doğrusu zalimler birbirlerinin velileridir. Allah da muttakilerin velisidir."},{"n":20,"t":"Bu; insanlar için açık belgeler, kesin olarak inanan bir kavim için de hidayet ve rahmettir."},{"n":21,"t":"Yoksa; kötülükleri kazananlar, ölümlerinde ve sağlıklarında kendilerini iman edip salih amel işleyen kimseler ile bir tutacağımızı mı sandılar? Ne kötü hüküm veriyorlar."},{"n":22,"t":"Allah, gökleri ve yeri hak ile yaratmıştır. Ta ki her nefis, zulme uğratılmaksızın kazancına göre karşılık görsün."},{"n":23,"t":"Gördün mü, o kimseyi ki; heva ve hevesini kendisine tanrı edinmiş, bilgisi olduğu halde Allah onu şaşırtmış, kulağını, kalbini mühürlemiş ve gözüne perde koymuştur? Allah’tan sonra onu kim hidayete eriştirebilir? Hala düşünmeyecek misiniz?"},{"n":24,"t":"Hayat; ancak bu dünyada yaşadığımızdır. Ölürüz ve yaşarız. Bizi ancak Dehr helak eder, dediler. Oysa onların bu konuda bilgileri yoktur. Başka değil, onlar sadece zannediyorlar."},{"n":25,"t":"Ayetlerimiz onlara açıkça okunduğu zaman; doğru sözlüler iseniz, babalarımızı getirin bakalım, demekten başka bir huccetleri yoktur."},{"n":26,"t":"De ki: Allah diriltir sizi sonra öldürür, sonra hakkında hiç bir şüphe bulunmayan o kıyamet gününde toplar. Fakat insanların pek çoğu bilmezler."},{"n":27,"t":"Göklerin ve yerin mülkü Allah’ındır. Kıyametin kopacağı gün; işte o gün, batıla saplananlar hüsranda kalırlar."},{"n":28,"t":"Her ümmeti dizüstü çökmüş görürsün. Her ümmet kendi kitabına çağrılır. Bugün, size yaptıklarınızın karşılığı verilecektir."},{"n":29,"t":"Bu kitablarımız sizin aleyhinize hak ile konuşuyor. Şüphesiz Biz, yaptıklarınızı bir bir kaydediyorduk."},{"n":30,"t":"İman edip salih amel işlemiş olanlara gelince; Rabbları onları rahmetine girdirir. Apaçık kurtuluş işte budur."},{"n":31,"t":"Küfredenlere gelince; ayetlerimiz size okunmuş, siz de büyüklük taslayıp mücrim bir kavim olmuştunuz, değil mi?"},{"n":32,"t":"Allah’ın vaadi haktır ve kıyamet günü hakkında hiç şüphe yoktur, denildiği zaman; siz demiştiniz ki: Kıyamet nedir? bilmiyoruz, ancak bir takım tahminlerde bulunuyoruz. Onun hakkında kesin bir bilgi elde etmiş değiliz."},{"n":33,"t":"Onlara, yaptıkları işlerin kötülükleri belli oldu ve alaya aldıkları şeyler kendilerini kuşattı."},{"n":34,"t":"Denilir ki: Siz, nasıl bugüne kavuşacağınızı unuttuysanız, Biz de sizi unuttuk. Barınağınız ateştir, yardımcılarınız da yoktur."},{"n":35,"t":"Bunun böyle olmasının sebebi; Allah’ın ayetlerini alaya almanız ve dünya hayatının sizi aldatmış olmasıdır. İşte o gün; oradan çıkarılmayacaklar ve özürleri de dinlenmeyecektir."},{"n":36,"t":"Hamd; göklerin Rabbı, yerin Rabbı ve alemlerin Rabbı olan Allah’a mahsustur."},{"n":37,"t":"Göklerde de, yerde de büyüklük O’nundur. O’dur Aziz, Hakim."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Kitab’ın indirilmesi; Aziz, Hakim Allah’tandır."},{"n":3,"t":"Biz; gköleri, yeri ve ikisinin arasında bulunanları ancak hak üzere ve belirli bir süre için yarattık. Küfredenler ise korkutuldukları şeylerden yüz çevirmektedirler."},{"n":4,"t":"De ki: Allah’tan başka taptığınız şeyleri gördünüz mü? Yeryüzünde ne yaratmışlardır gösteriniz bana? Yoksa onların ortakları göklerde midir? Eğer doğru söyleyenlerden iseniz; size indirilmiş bir kitab veya size intikal etmiş bir bilgi kalıntısı varsa, getirin bana."},{"n":5,"t":"Allah’ı bırakıp da kıyamet gününe kadar cevab veremeyecek şeylere dua edenden daha sapık kimdir. Halbuki bunlar, onların dualarından habersizdirler."},{"n":6,"t":"İnsanlar haşrolundukları zaman; bunlar, onlara düşman kesilirler. Ve onların ibadetlerini inkar ederler."},{"n":7,"t":"Onlara, ayetlerimiz açıkça okunduğu zaman; kendilerine geldiğinde hakkı inkar edenler: Bu, apaçık bir büyüdür, dediler."},{"n":8,"t":"Yoksa: Onu kendiliğinden uydurdu mu diyorlar; De ki: Eğer onu ben uydurmuşsam; Allah tarafından bana gelecek hiçbir şeye sizin gücünüz yetmez. O; yaptığınız taşkınlıkları çok daha iyi bilir. Benimle sizin aranızda şahit olarak Allah, yeter. O; Gafur’dur, Rahim’dir."},{"n":9,"t":"De ki: Ben, peygamberlerden bir ilk değilim. Bana ve size ne yapılacağını da bilmem. Ben, sadece bana vahyolunana uyarım. Ve ben, ancak apaçık bir uyarıcıyım."},{"n":10,"t":"De ki: Şayet Allah katından ise ve siz de onu inkar etmişseniz, İsrailoğullarından birisi de bunu böyle olduğuna dair şehadet edip inandığı halde siz yine de büyüklük taslamışsanız, zulmetmiş olmaz mısınız? Muhakkak ki Allah; zalimler güruhunu hidayete erdirmez."},{"n":11,"t":"O küfredenler, inananlar için: Bu iş, bir hayır olsaydı; onlar bunda bizi geçemezlerdi, dediler. Onlar bununla hidayete ermediklerinden; bu, eski bir uydurmadır, diyeceklerdir."},{"n":12,"t":"Ondan önce de rehber ve rahmet olarak Musa’nın kitabı var. Bu ise zulmedenleri uyarmak ve ihsan edenlere müjde olmak üzere arabça bir dille doğrulayıcı bir kitabdır."},{"n":13,"t":"Muhakkak ki; Rabbımız Allah’tır, deyip de sonra dosdoğru istikamette gidenlere korku yoktur. Ve onlar, üzülecek de değillerdir."},{"n":14,"t":"İşte onlar, cennet ehlidirler. İşlediklerine karşılık olarak orada temelli kalacaklardır."},{"n":15,"t":"Biz; insana, anne ve babasına ihsan etmesini tavsiye ettik. Annesi onu zahmetle taşıdı ve zahmetle doğurdu. Taşınması ve sütten kesilmesi otuz aydır. Nihayet erginlik çağına ulaşınca ve kırk yaşına varınca der ki: Rabbım bana; ana-babama verdiğin nimete şükretmemi ve senin hoşnud olacağın salih amel işlememi ilham et. Bana verdiğin gibi soyuma da salah ver. Doğrusu ben, Sana döndüm. Ve gerçekten ben, müslümanlardanım."},{"n":16,"t":"İşte bunlar, cennetliklerdendirler. Yaptıklarının en iyisini kabul edeceğimiz ve kötülüklerinden vazgeçeceğimiz kimselerdir. Bu; onlara vaadolunan dosdoğru bir vaaddir."},{"n":17,"t":"Anne ve babasına: Of sizden, benden önce nice nesiller gelip geçmişken beni mi tekrar dirilmekle tehdit ediyorsunuz? diyen kimseye, anne ve babası Allah’a sığınarak: Yazıklar olsun sana. İman et, muhakkak ki Allah’ın vaadi haktır dedikleri halde; bu, eskilerin masallarından başka bir şey değildir, der."},{"n":18,"t":"İşte onlar; kendilerinden önce cinnlerden ve insanlardan gelip geçmiş ümmetler içinde üzerlerine söz hak olmuş kimselerdir. Doğrusu onlar, hüsrana uğrayanlardandırlar."},{"n":19,"t":"Herkesin yaptıklarına göre dereceleri vardır. Herkese işlediklerinin karşılığı ödenir. Ve kendilerine zulmedilmez."},{"n":20,"t":"O küfredenlere, ateşe sunuldukları gün: Dünyadaki hayatınızda sizin için temiz olan her şeyi harcadınız, onların zevkini sürdünüz. Bugün ise yeryüzünde haksız yere büyüklük taslamanızdan ve fasıklık etmenizden ötürü alçaltıcı bir azab göreceksiniz, denir."},{"n":21,"t":"Ad’ın kardeşini de hatırla. Hani kavmini; Allah’tan başkasına ibadet etmeyin, diyen nice uyarıcılar gelip geçmişken Ahkaf ile uyarıp; doğrusu ben, sizin için büyük günün azabından korkarım, diye korkutmuştu."},{"n":22,"t":"Onlar da: Sen, bizi tanrılarımızdan döndürmek için mi geldin? Doğru söyleyenlerden isen; haydi taehdit ettiğin şeyi başımıza getir, demişlerdi."},{"n":23,"t":"O da: İlim, ancak Allah katındadır. Ben, size gönderildiğim şeyi tebliğ ediyorum. Ama bakıyorum ki siz, cahil bir kavimsiniz, demişti"},{"n":24,"t":"Onu, vadilerine doğru yayılan bir bulut şeklinde görünce dediler ki: Bu; bize yağmur getirecek büyük bir buluttur. Hayır o, acelece beklediğiniz şey, bir rüzgardır ki içinde elem verici azab vardır."},{"n":25,"t":"Rabbının emri ile her şeyi yıkar. Bunun üzerine onların meskenlerinden başka bir şey görünmez oldu. İşte biz, suçlular güruhunu böylece cezalandırırız."},{"n":26,"t":"Andolsun ki; onları, sizi yerleştirmediğimiz yerlere yerleştirmiştik. Ve kendilerine kulaklar, gözler ve kalbler vermiştik. Ne var ki; kulakları, gözleri ve kalbleri onlara bir fayda sağlamadı. Çünkü onlar; Allah’ın ayetlerini bile bile inkar ediyorlardı. Sonunda onları alay ettikleri şey kuşatıverdi."},{"n":27,"t":"Andolsun ki biz, çevrenizdeki kasabaları da yok ettik. Belki dönerler diye ayetleri takrar tekrar açıkladık."},{"n":28,"t":"Allah’ı bırakarak O’na yakınlık peyda etmek için edindikleri tanrılar kendilerine yardım etmeli değil miydi? Hayır, onlar görünmez oldular. Bu; onların yalanları ve uydurup durdukları şeydir."},{"n":29,"t":"Hani Kur’an dinlesinler diye sana cinlerden bir taife yöneltmiştik. Hazır olunca demişlerdi ki: Susun. Kur’an tamam olunca da her biri birer uyarıcı olarak kavimlerine dönmüşlerdi."},{"n":30,"t":"Ve demişlerdi ki: Ey kavmimiz, doğrusu biz Musa’dan sonra indirilmiş olan ve kendinden öncekileri doğrulayan, hakka ve doğru yola hidayet eden bir kitab dinledik."},{"n":31,"t":"Ey kavmimiz: Allah’ın davetçisine uyun. Ona iman edin ki sizin günahlarınızdan bir kısmını bağışlasın ve sizi elim bir azabdan kurtarsın."},{"n":32,"t":"Allah’ın davetçisine uymayan kimse bilsin ki; yeryüzünde Allah’ı aciz bırakamaz. Ve onun için Allah’tan başka veliler de bulunmaz. İşte onlar apaçık bir sapıklık içindedirler."},{"n":33,"t":"Görmezler mi ki; gökleri ve yeri yaratn ve onları yaratmaktan yorulmayan Allah, ölüleri de diriltmeye kadirdir. Evet O, muhakkak her şeye kadirdir."},{"n":34,"t":"O küfredenler ateşe sunuldukları gün. Nasıl, bu gerçek değil miymiş? denildiğinde: Rabbımıza andolsunki, evet gerçekmiş, derler. O da: Şu halde küfrettiğinizden dolayı tadın azabı, der."},{"n":35,"t":"Peygamberlerden azim sahibi olanların sabrettiği gibi sen de sabret. Onlar için acele etme. Onlar vaad olunduklarını gördükleri gün; sanki dünyada sadece gündüzün bir saatı kadar kaldıklarını sanırlar. Bu bir tebliğdir. Fasıklar güruhundan başkası helak edilir mi hiç?"}],[{"n":1,"t":"Küfredip de Allah yolundan alıkoyanların amellerini Allah, boşa çıkarır."},{"n":2,"t":"İman edip salih ameller işleyenlerin, Muhammed’e indirilene-ki o, Rabblarından olan haktır inananların kötülüklerini örter ve durumlarını ıslah eder."},{"n":3,"t":"İşte böyle. Muhakkak ki o küfredenler, batıla uymuşlar ve iman edenler de Rabblarından gelen hakka uymuşlardır. Böylece Allah, insanlara misallerini anlatır."},{"n":4,"t":"Öyleyse küfredenlerle karşılaştığınızda hemen boyunlarını vurun. Nihayet onları sindirince, bağı sıkı basın. Sonra da ya bir lütuf veya bir fidye. Yeter ki harb hazırlıklarını bıraksın. Eğer Allah, dileseydi; onlardan elbette intikam alırdı. Fakat kiminizi kiminizle denemek ister. Allah yolunda öldürülenlere gelince; Allah onların amellerini asla boşa çıkarmaz."},{"n":5,"t":"Onları hidayete eriştirir ve durumlarını ıslah eder."},{"n":6,"t":"Onları kendilerine tanıttığı cennete sokar."},{"n":7,"t":"Ey iman edenler; siz Allah’a yardım ederseniz, O da size yardım eder ve sebatınızı arttırır."},{"n":8,"t":"Küfredenlere gelince; onların hakkı yüzükoyun kapanmak. Allah, onların yaptıklarını boşa çıkarmıştır."},{"n":9,"t":"İşte böyle. Çünkü onlar, Allah’ın indirdiğini çirkin görmüşlerdir. O da onların amellerini boşa çıkarmıştır."},{"n":10,"t":"Yeryüzünde dolaşmazlar mı, kendilerinden öncekilerin akibetlerinin nasıl olduğuna baksınlar. Allah onları yere batırmıştır. Ve kafirlere de bunun benzeri vardır."},{"n":11,"t":"İşte böyle. Çünkü Allah, imanetmiş olanların Mevla’sıdır. Kafirlere gelince; muhakkak ki onların mevlası yoktur."},{"n":12,"t":"Muhakkak ki Allah iman edip salih amel işleyenleri altlarından ırmaklar akan cennetlere koyar. Küfredenler ise, eğlenirler ve hayvanların yediği gibi yerler. Onları yeri de ateştir."},{"n":13,"t":"Nice kasabaları yok ettik ki; onlar, seni sürüp çıkaran kasabadan daha kuvvetli idiler. Ve onlara yardım eden de bulunmadı."},{"n":14,"t":"Rabbındab apaçık bir burhan üzerinde bulunan kimse; işlediği kötülükleri kendisine güzel gösterilen ve heveslerine uyanlar gibi midir?"},{"n":15,"t":"Muttakilere vaadolunan cennetin misali: İçinde bozulmayan sudan ırmaklar, tadı değişmeyen sütten ırmaklar, içenlere zevk veren şaraptan ırmaklar ve süzme baldan ırmaklar vardır. Orada meyvelerin her çeşidi onlarındır. Ve Rabblarından mağfiret de vardır. Hiç bu; ateşte temelli kalan ve bağırsaklarını parça parça edecek kaynar su içirilen kimseler gibi midir?"},{"n":16,"t":"Onların arasında seni dinleyenler vardır. Nihayet senin yanından çıkınca, kendilerine ilim verilmiş olanlara: Az önce ne demişti? diye sorarlar. İşte bunlar, Allah’ın kalblerini mühürlemiş olduğu ve kendi heveslerine uyan kimselerdir."},{"n":17,"t":"Hidayete erenlere gelince; onların hidayetlerini arttırır ve onlara takvalarını verir."},{"n":18,"t":"Onlar, kıyamet saatının ansızın kendilerine gelip çatmasından başka bir şey mi bekliyorlar? Şüphesiz onun alametleri gelmiştir. Kendilerine gelip çatınca öğüt almaları neye yarar?"},{"n":19,"t":"Bil ki; Allah’tan başk ailah yokturç Hem kendinin, hem de mü’min erkeklerle mü’min kadınların günahlarının bağışlanmasını dile. Allah, dolaştığınız yeri de, barındığınız yeri de bilir."},{"n":20,"t":"İman etmiş olanlar; bir sure indirilmeli değil miydi? derler. Fakat muhkem bir sure indirilip de orada muharebe zikrolununca; kalblerinde hastalık olanların, ölüm korkusundan bayılmış kimselerin bakışları gibi sana baktıklarını görürsün. Bu, onlar için daha evladır."},{"n":21,"t":"İtaat ve güzel söz. Bunun için iş ciddileşince derhal Allah’a sadakat gösterselerdi; elbette kendileri için daha hayırlı olurdu."},{"n":22,"t":"Demek, sizler idareyi ele alırsanız; yeryüzünde fesad çıkaracak, akrabalık bağlarını bile koparacaksınız öyle mi?"},{"n":23,"t":"Allah’ın kendilerini la’netlemiş, sağırlaştırmış ve gözlerini kör etmiş olduğu kimseler işte bunlardır."},{"n":24,"t":"Kur’an’ı düşünmezler mi? Yoksa kalblerin üzerinde kilitleri mi vardır?"},{"n":25,"t":"Muhakkak ki kendilerine hidayet belli olduktan sonra arkalarına dönenleri şeytan aldatmış ve onlara ümit vermiştir."},{"n":26,"t":"İşte böyle. Zira onlar, Allah’ın indirdiğini çirkin karşılayanlara; bazı işlerde size itaat edeceğiz, demişlerdi. Allah, onların gizlediklerini bilir."},{"n":27,"t":"Ya, melekler onların yüzlerine ve sırtlarına vurarak canlarını alırken ne olacak?"},{"n":28,"t":"İşte böyle. Çünkü onlar, gerçekten Allah’ı gazaplandıran şeye uydular ve O’nu hoşnud edecek şeyleri çirkin karşıladılar. Bunun için O da onların amellerini boşa çıkardı."},{"n":29,"t":"Yoksa; kalblerinde hastalık olanlar, kinlerini Allah’ın dışarı vurmayacağını mı sandılar?"},{"n":30,"t":"Şayet isteseydik; Biz, onları sana gösterirdik de sen; onları yüzlerinden tanırdın. Andolsun ki; sen, onları sözlerinin üslubundan da tanırsın. Allah; bütün yaptıklarınızı bilir."},{"n":31,"t":"Andolsun ki; içinizden, cihad edenlerle sabredenleri belirleyinceye ve haberlerinizi açıklayıncaya kadar sizi imtihan edeceğiz."},{"n":32,"t":"Muhakkak ki küfredip de Allah yolundan alıkoyanlar ve kendilerine hidayet belli olduktan sonra peygamberlere karşı gelenler; Allah’a hiç bir zarar veremeyeceklerdir. O; bunların amellerini hep boşa çıkaracaktır."},{"n":33,"t":"Ey iman edenler; Allah’a itaat edin, peygambere itaat edin ve amellerinizi boşa çıkarmayın."},{"n":34,"t":"Muhakkak ki küfredip de Allah yolundan alıkoyanlar, sonra da kafir olarak ölenler; işte onları Allah, asla bağışlamayacaktır."},{"n":35,"t":"Öyleyse sakın gevşemeyin; üstün olduğunuz halde sulha davet etmeyin. Allah, sizinle beraberdir. O; amellerinizi asla eksiltmez."},{"n":36,"t":"Muhakkak ki dünya hayatı, ancak bir oyun ve eğlencedir. Şayet iman eder ve sakınırsanız; O, size hem ecirlerinizi verir, hem de mallarınızı istemez."},{"n":37,"t":"Eğer sizden onları ister ve zorlarsa; cimrilik edeceksiniz. Ve bu da kinlerinizi ortaya çıkaracaktır."},{"n":38,"t":"İşte sizler; Allah yolunda infak etmek için çağrılıyorsunuz. İçinizden kiminiz cimrilik ediyor. Kim cimrilik ederse; ancak kendi nefsine cimrilik etmiş olur. Allah; Gani’dir, siz ise fakirlersiniz. Eğer O’ndan yüz çevirirseniz; yerinize sizden başka bir kavmi getirir. Sonra onlar sizin benzerleriniz olmazlar."}],[{"n":1,"t":"Muhakkak ki Biz; sana, apaçık bir feth ihsan ettik."},{"n":2,"t":"Ta ki Allah; senin geçmiş ve gelecek günahını bağışlasın. Sana olan nimetini tamamlasın ve seni doğru yola eriştirsin."},{"n":3,"t":"Ve Allah; sana çok şerefli bir muzafferiyetle yardım etsin."},{"n":4,"t":"O’dur; mü’minlerin kalblerine sekineti indiren. Ta ki; imanlarını imanla arttırsınlar. Göklerin ve yerin orduları Allah’ındır. Allah; Alim ve Hakim olandır."},{"n":5,"t":"Ta ki; mü’min erkeklerle mü’min kadınları, altlarından ırmaklar akan ve içinde ebedi kalacakları cennetlere koysun ve onların kötülüklerini örtsün. İşte Allah katında en büyük kurtuluş budur."},{"n":6,"t":"Ve Allah hakkındaki kötü zan besleyen münafık erkeklerle münafık kadınlara, müşrik erkeklerle müşrik kadınlara azab etsin. Kötülük onların başlarına dönsün. Allah; onlara gazabetmiş, la’netlemiş ve cehennemi kendileri için hazırlamıştır."},{"n":7,"t":"Göklerin ve yerin orduları Allah’ındır. Allah; Aziz, Hakim olandır."},{"n":8,"t":"Muhakkak ki Biz; seni şahid, müjdeleyici ve uyarıcı olarak gönderdik;"},{"n":9,"t":"Ki; Allah’a ve peygamberine iman edesiniz, O’na yardım edesiniz ve saygı gösteresiniz. Sabah, akşam O’nu tesbih edesiniz."},{"n":10,"t":"Muhakkak ki sana bi’at edenler; ancak Allah’a bi’at etmektedirler. Allah’ ın eli onların elleri üstündedir. Onun için kim, ahdini çözerse; ancak kendi aleyhine çözmüş olur. Kim de Allah’a verdiği ahde vefa gösterirse; ona da Allah büyük bir ecir verecektir."},{"n":11,"t":"Bedevilerden geri bırakılanlar sana diyeceklerdir ki: Mallarımız ve ailelerimiz bizi alıkoydu. Allah’tan bizim bağışlanmamızı dile. Kalblerinde olmayanı dilleriyle söylüyorlar. De ki: Allah, size bir zarar gelmesini dilerse veya bir fayda elde etmenizi isterse; O’na karşı kim engel olabilir? Hayır, Allah yaptıklarınızdan haberdar olandır."},{"n":12,"t":"Hayır, siz; peygamberin ve mü’minlerin, ailelerine bir daha dönemeyeceklerini sanmıştınız. Bu, sizin kalblerinize güzel göründü de kötü zanda bulundunuz. Ve helake mahkum bir kavim oldunuz."},{"n":13,"t":"Kim, Allah’a ve Rasulüne iman etmezse; muhakkak ki Biz; kafirler için çılgın bir ateş hazırlamışızdır."},{"n":14,"t":"Göklerin ve yerin mülkü Allah’ındır. Dilediğini bağışlar, dilediğini azablandırır. Ve Allah Gafur, Rahim olandır."},{"n":15,"t":"Siz, ganimetleri almak için gittiğinizde; geride bırakılanlar diyeceklerdir ki: Bırakın, biz de arkanıza düşelim. Onlar, Allah’ın kelamını değiştirmek isterler. De ki: Bize uymayacaksınız. Allah, daha önce böyle buyurmuştur. Size; hayır, bizi çekemiyorsunuz, diyeceklerdir. Hayır onlar, pek az anlayan kimselerdir."},{"n":16,"t":"Bedevilerden geride bırakılanlara de ki: Siz, yakında zorlu savaşçı olan bir kavme çağrılacaksınız. Onlarla savaşırsınız veya onlar müslüman olurlar. Şayet itaat ederseniz; Allah size güzel bir ecir verir. Ama daha önce döndüğünüz gibi yine dönecek olursanız; sizi, elim bir azabla azablandırır."},{"n":17,"t":"Gözü kör olana vebal yok. Topala da vebal yok, hastaya da vebal yok. Kim, Allah’a ve peygamberine itaat ederse; onu altlarından ırmaklar akan cennetlere sokar. Kim de geri kalırsa; onu elim bir azab ile azablandırır."},{"n":18,"t":"Andolsun ki; sana, o ağacın altında bi’at ederlerken Allah mü’minlerden hoşnud olmuştur. Kalblerinde olanı bilmiş de onlara sekineti indirmiş ve onları pek yakın bir fethle mükafatlandırmıştır."},{"n":19,"t":"Ve alacakları bol ganimetlerle. Allah; Aziz, Hakim olandır."},{"n":20,"t":"Allah; size, ele geçireceğiniz bol ganimetler vaadetmiştir. Bunu size hemen vermiş ve insanların ellerini sizden çekmiştir ki mü’minlere bir ayet olsun ve sizi dosdoğru yola hidayet etsin."},{"n":21,"t":"Bundan başka, sizin gücünüzün yetmediği ama Allah’ın sizin için sakladığı ganimetler de vardır. Ve Allah; her şeye kadir olandır."},{"n":22,"t":"O küfredenler, sizinle savaşa katılsalardı; mutlaka arkalarını dönerlerdi. Sonra bir veli ve yardımcı da bulamazlardı."},{"n":23,"t":"Bu, önceden beri geçmiş olan Allah’ın sünnetidir. Ve sen; Allah’ın sünnetinde asla bir değişiklik bulamazsın."},{"n":24,"t":"Mekke’nin göbeğinde sizi onlara muzaffer kıldıktan sonra, onların ellerini sizden, sizin ellerinizi de onlardan çeken O’dur. Allah; yaptıklarınızı görmekte olandır."},{"n":25,"t":"Onlar; küfretmiş olanlardır. Sizi Mescid-i Haram’ı ziyaretten ve bekletilmekte olan kurbanlıklarınızı da mahalline ulaşmaktan men’edenlerdir. Eğer orada henüz bilmediğiniz mü’min erkekler, mü’min kadınları bilmeyerek ezmek suretiyle üzüntüye kapılmanız ihtimali olmasaydı; Allah, savaşı önlemezdi. Dilediklerine rahmet etmek için Allah, böyle yapmıştır. Eğer onlar birbirinden ayrılmış olsalardı; o küfredenleri elim bir azabla azablandırırdık."},{"n":26,"t":"O küfredenler kalblerinde hamiyyeti, cahiliyyet hamiyyetini ateşlendirdiklerinde Allah; sekinetini peygamberine ve mü’minlerin üzerine indirdi. Ve onları takva sözü üzerinde durdurdu. Onlar, buna daha layık ve ehil kimselerdi. Allah; her şeyi bilmekte olandır."},{"n":27,"t":"Andolsun ki; Allah, Rasulünün gördüğü rü’yanın hak olduğunu tasdik etmiştir. Allah, dilerse; siz güven içinde başlarınızı tıraş etmiş veya saçlarınızı kısaltmış olarak korkmadan Mescid-i Haram’a gireceksiniz. Allah, sizin bilmediğinizi bilir. Bundan başka size yakın bir zamanda bir feth de verecektir."},{"n":28,"t":"O’dur Rasulünü hidayet ve hak din ile gönderen. Bütün dinlerden üstün kılmak üzere. Şahid olarak Allah yeter."},{"n":29,"t":"Muhammed; Allah’ın Rasulüdür. Beraberinde bulunanlar da; kafirlere karşı zorlu, kendi aralarında merhametlidirler. Onları rüku’ edenler, secde edenler olarak görürsün. Allah’tan lutuf ve rıza isterler. Onlar; yüzlerindeki izinden tanınırlar. İşte onların Tevrat’taki vasıfları budur. İncil’de de şöyle vasıflandırılmışlardı: Onlat filizini yarıp çıkarmış, gittikçe onu kuvvetlendirerek kalınlaşmış, gövdesi üzerine dikilmiş bir ekine benzerler ki bu, ekicilerin de hoşuna gider. Allah; böylece onları çoğaltıp kuvvetlendirmekle, kafirleri öfkelendirir. Allah; iman edip salih amel işleyenlere hem mağfiret, hem de büyük bir mükafat vaadetmiştir."}],[{"n":1,"t":"Ey iman edenler; Allah’ın ve Rasulünün huzurunda öne geçmeyin. Allah’tan korkun. Muhakkak ki Allah; Semi’dir, Alim’dir."},{"n":2,"t":"Ey iman edenler; seslerinizi peygamberin sesinden yüksek çıkarmayın. Birbirinize bağırdığınız gibi peygambere bağırmayın. Yoksa siz farkına varmadan amelleriniz boşa gider."},{"n":3,"t":"Peygamberin yanında seslerini kısanlar, muhakkak ki onlar; Allah’ın gönüllerini takva ile imtihan ettiği kimselerdir. Onlar için; mağfiret ve büyük bir mükafat vardır."},{"n":4,"t":"Muhakkak ki sana, hücrelerin ardından seslenenlerin çoğunun akılları ermez."},{"n":5,"t":"Eğer onlar; sen, yanlarından çıkıncaya kadar sabretselerdi; kendileri için elbette daha hayırlı olurdu. Allah; Gafur’dur, Rahim’dir."},{"n":6,"t":"Ey iman edenler; eğer bir fasık size bir haberle gelirse, onu iyice araştırın. Yoksa bilmeden bir kavme sataşırsınız da sonradan ettiğinize pişman olursunuz."},{"n":7,"t":"Hem bilin ki; içinizde Allah’ın peygamberi vardır. Şayet o, birçok işlerde size uymuş olsaydı; şüphesiz ki sıkıntıya düşerdiniz. Ama Allah; size imanı sevdirmiş ve onu kalblerinize ziynet yapmış; küfrü, fasıklığı ve isyanı da size çirkin göstermiştir. Rüşdünü bulanlar, işte onlardır."},{"n":8,"t":"Allah’tan bir lutuf ve nimet olarak. Ve Allah Alim’dir, Hakimdir."},{"n":9,"t":"Eğer mü’minlerden iki taife çarpışacak olursa; aralarını düzeltin. Şayet biri diğeri üzerine saldırırsa; saldıranlarla Allah’ın buyruğuna dönünceye kadar savaşın. Eğer dönerlerse; artık adaletle aralarını bulun ve adil davranın. Şüphesiz ki Allah; adil davrananları sever."},{"n":10,"t":"Mü’minler; ancak kardeştirler. Öyle ise iki kardeşinizin arasını düzeltin ve Allah’tan korkun ki; esirgenesiniz."},{"n":11,"t":"Ey iman etmiş olanlar; bir topluluk diğer topluluk ile alay etmesin. Belki de onlar, kendilerinden daha hayırlıdır. Kadınlar da kadınlarla. Belki onlar kendilerinden daha hayırlıdırlar. Kendi kendinizi ayıplamayın ve birbirinizi kötü lakaplarla çağırmayın. İmandan sonra fasıklık ne kötü addır. Kim de tevbe etmezse; işte onlar zalimlerin kendileridir."},{"n":12,"t":"Ey iman edenler; zannın bir çoğundan kaçının. Çünkü bazı zan günahtır. Birbirinizin kusurunu araştırmayın, kiminiz kiminizi arkasından çekiştirmesin. Hangi biriniz ölü kardeşinin etini yemekten hoşlanır? Bundan tiksindiniz değil mi? Allah’tan korkun, şüphesiz ki Allah; Tevvab’dır, Rahim’dir."},{"n":13,"t":"Ey insanlar; doğrusu Biz, sizi bir erkekle bir dişiden yarattık. Ve birbirinizle tanışasınız diye sizi milletlere ve kabilelere ayırdık. Gerçekten Allah katında en değerliniz; O’ndan en çok korkanınızdır. Şüphesiz ki Allah; Alim’dir, Habir’dir."},{"n":14,"t":"Bedeviler: İman ettik, dediler. De ki: Siz iman etmediniz, ama müslüman olduk, deyin. İman henüz kalblerinize yerleşmedi. Şayet Allah’a ve peygamberine itaat ederseniz; O, amellerinizden hiç bir şey eksiltmez. Muhakkak ki Allah; Gafur’dur, Rahim’dir."},{"n":15,"t":"Mü’minler, ancak onlardır ki; Allah’a ve Rasulüne iman edip sonra şüpheye düşmemiş ve Allah yolunda mallarıyla canlarıyla cihad etmişlerdir. İşte onlar, sadıkların kendileridir."},{"n":16,"t":"De ki: Dininizi Allah’a mı öğretiyorsunuz? Halbuki Allah; göklerde olanları da, yerde olanları da bilir. Allah; her şeyi bilendir."},{"n":17,"t":"Müslüman oldukları için sana minnet ediyorlar. De ki: Müslümanlığınızla bana minnet etmeyin. Bilakis sizi imana erdirdiği için Allah, size minnet eder. Şayet sadıklardan iseniz."},{"n":18,"t":"Muhakkak ki Allah; göklerin ve yerin gaybını bilir. Ve Allah; yaptıklarınızı görendir"}],[{"n":1,"t":"Kaf. O şerefli Kur’an’a andolsun ki;"},{"n":2,"t":"Aralarından bir uyarıcının gelmesine şaştılar da o kafirler: Bu, şaşılacak bir şey, dediler."},{"n":3,"t":"Öldüğümüz ve toprak olduğumuz zaman mı? Bu, uzak bir dönüştür."},{"n":4,"t":"Doğrusu Biz; toprağın onlardan neleri eksilttiğini biliyoruz. Katımızda da her şeyi saklayan bir kitab vardır."},{"n":5,"t":"Hayır, onlar; hak kendilerine gelince onu yalanladılar. Şimdi de şaşırmış bir haldedirler."},{"n":6,"t":"Üstlerindeki göğe hiç bakmazlar mı? Onu nasıl bina etmiş ve nasıl donatmışız? Onda hiç bir çatlak da yoktur."},{"n":7,"t":"Yeryüzünü de döşedik ve ona sabit dağlar koyduk. Orada her türden güzel çiftler yetiştirdik."},{"n":8,"t":"Allah’a yönelen her kula öğüt ve ibret olsun diye."},{"n":9,"t":"Gökten bereketli bir su indirdik de onunla bahçeler ve biçilecek taneler bitirdik."},{"n":10,"t":"Ve birbiri üstüne dizilmiş tomurcuk yüklü yüksek hurma ağaçları."},{"n":11,"t":"Kullara rızık olması için. Ve onunla ölü bir beldeye can verdik. İşte çıkış da böyledir."},{"n":12,"t":"Onlardan önce Nuh kavmi, Ress halkı ve Semud da tekzib etmişti."},{"n":13,"t":"Ad, Firavun kavmi ve Lut’un kardeşleri de."},{"n":14,"t":"Eyke’liler ve Tübba kavmi de. Bunların her biri peygamberlerini yalanlamışlardı da tehdidim üzerlerine hak olmuştu."},{"n":15,"t":"Ya Biz ilk yaratışta güçsüz mü düştük? Hayır, onlar yeni bir yaratılıştan şüphe içindedirler."},{"n":16,"t":"Andolsun ki; insanı, Biz yarattık ve nefsinin kendisine ne fısıldadığını da biliriz. Biz, ona şah damarından daha yakınız."},{"n":17,"t":"Sağında ve solunda onunla beraber oturup amellerini tesbit eden iki de tesbit edici vardır."},{"n":18,"t":"O, bir söz atmaya dursun; mutlaka yanında hazır bir gözcü vardır."},{"n":19,"t":"Ölüm sarhoşluğu gerçekten geldi. İşte bu; senin öteden beri kaçıp durduğun şeydir."},{"n":20,"t":"Sur’a üfürülmüştür. İşte bu; geleceği vaadedilen gündür."},{"n":21,"t":"Her nefis, yanında bir sürücü ve şahidle gelir."},{"n":22,"t":"Andolsun ki; sen, bundan gaflette idin. İşte senin perdeni kaldırdık. Bugün artık görüşün keskindir."},{"n":23,"t":"Ona yakın olan dedi ki: İşte yanımda hazır olan şey."},{"n":24,"t":"Siz ikiniz, atın cehenneme; her inatçı kafiri;"},{"n":25,"t":"Hayra bütün hızıyla engel olan azgın şüpheciyi."},{"n":26,"t":"Ki o; Allah’tan başka bir ilah edinmiştir. Haydi siz ikiniz, onu en şiddetli azabın içine atın."},{"n":27,"t":"Onun yakın dostu dedi ki: Rabbımız; onu ben azdırmadım, fakat kendisi derin bir sapıklıktaydı."},{"n":28,"t":"Buyurdu ki: Benim katımda çekişmeyin. Size önceden tehdid göndermiştim."},{"n":29,"t":"Benim katımda söz değiştirilmez. Ve Ben, kullara asla zulmedici değilim."},{"n":30,"t":"O gün cehenneme: Doldun mu? deriz. O da: Daha var mı? der."},{"n":31,"t":"Cennet de takva sahiplerine yaklaştırılır. Zaten uzakta değildir."},{"n":32,"t":"İşte size vaadolunan budur. Ki o; daima Allah’a yönelen ve buyruklarına riayet eden,"},{"n":33,"t":"Görmediği halde Rahman’dan korkan ve Allah’a yönelik bir kalb ile gelenlere."},{"n":34,"t":"Selemetle girin oraya. İşte bu, ebediyet günüdür."},{"n":35,"t":"Orada diledikleri onlarındır. Katımızda daha fazlası da var."},{"n":36,"t":"Biz; onlardan önce, kendilerinden daha kuvvetli olan ve diyar diyar dolaşan nice nesilleri yok etmişizdir. Kurtuluş var mı?"},{"n":37,"t":"Muhakkak ki bunda; kalbi olan veya hazır bulunup da kulak veren kimseler için elbette bir öğüt vardır."},{"n":38,"t":"Andolsun ki; Biz, gökleri, yeri ve ikisinin arasında bulunanları altı günde yarattık. Ve Bize hiç bir yorgunluk da dokunmadı."},{"n":39,"t":"Ne derlerse sabret sen. Güneşin doğuşundan evvel ve batışından önce Rabbını hamd ile tesbih et."},{"n":40,"t":"Gecenin bir bölümünde ve secdelerinin ardından da O’nu tesbih et."},{"n":41,"t":"Bir münadinin yakın bir yerden çağıracağı güne, kulak ver."},{"n":42,"t":"O gün; bu sayhayı gerçekten işiteceklerdir. İşte bu, çıkış günüdür."},{"n":43,"t":"Muhakkak ki öldürecek de, diriltecek de Biziz Biz. Ve dönüş de ancak Bizedir."},{"n":44,"t":"O gün; yer yarılır, onlar çabucak çıkarlar. İşte bu, Bize göre kolay olan bir haşirdir."},{"n":45,"t":"Biz; onların dediklerini çok iyi biliriz. Sen, onların üstünde bir zorba değilsin. Tehdidimden korkacaklara Kur’an’la öğüt ver."}],[{"n":1,"t":"Esip savuranlara."},{"n":2,"t":"Yükünü yüklenenlere,"},{"n":3,"t":"Kolayca süzülenlere,"},{"n":4,"t":"İşi ayıranlara andolsun ki;"},{"n":5,"t":"Muhakkak size vaadolunan elbette doğrudur."},{"n":6,"t":"Muhakkak ceza elbet vuku bulacaktır."},{"n":7,"t":"Hareli yollara sahip olan göğe andolsun ki;"},{"n":8,"t":"Muhakkak siz, ihtilaflı bir sözdesiniz."},{"n":9,"t":"Ondan döndürülen kimseler döndürülür."},{"n":10,"t":"Kahrolsun o koyu yalancılar."},{"n":11,"t":"Ki onlar; koyu bir cehalet içerisinde kalmış gafillerdir."},{"n":12,"t":"Din günü ne zaman? diye sorarlar."},{"n":13,"t":"O, kendilerinin ateşe sokulacakları gündür."},{"n":14,"t":"Tadın azabınızı, işte acele istediğiniz bu idi."},{"n":15,"t":"Muhakkak ki muttakiler; cennetlerde ve çeşmelerdedirler."},{"n":16,"t":"Rabblarının kendilerine verdiğini almış olarak. Zira onlar bundan önce de ihsan edenlerdendi."},{"n":17,"t":"Onlar gecenin az bir kısmında uyurlardı."},{"n":18,"t":"Seher vakitlerinde de istiğfar ederlerdi."},{"n":19,"t":"Onların mallarında yoksullar ve muhtaçlar için de bir hak vardır."},{"n":20,"t":"Kesin olarak inananlar için yeryüzünde ayetler vardır."},{"n":21,"t":"Kendi nefislerinizde de. Hala görmez misiniz?"},{"n":22,"t":"Rızkınız da, size vaadolunan şeyler de semadadır."},{"n":23,"t":"Göğün ve yerin Rabbına andolsun ki; bu, sizin konuşmanız gibi kesin ve gerçektir."},{"n":24,"t":"Sana, İbrahim’in şerefli misafirlerinin haberi geldi mi?"},{"n":25,"t":"Hani onlar, yanına girip; selam sana, demişlerdi de; selam, demişti. Tanınmamış bir zümre."},{"n":26,"t":"Hemen ailesine giderek semiz bir buzağı ile gelmiş,"},{"n":27,"t":"Onlara yaklaştırıp; yemez misiniz? demişti."},{"n":28,"t":"Derken onlardan endişeye düşmüştü. Korkma; demişler ve onu bilgin bir oğulla müjdelemişlerdi."},{"n":29,"t":"Bunun üzerine zevcesi hayretle seslenerek döndü, yüzünü kapayarak: Kısır bir kocakarı, dedi."},{"n":30,"t":"Onlar: Bu, böyledir, Rabbın buyurdu. Muhakkak ki O; Hakim, Alim olandır, dediler."},{"n":31,"t":"Ey elçiler, işiniz nedir? dedi."},{"n":32,"t":"Dediler ki: Biz, suçlu bir kavme gönderildik,"},{"n":33,"t":"Ki; üzerlerine çamurdan taşlar yağdıralım."},{"n":34,"t":"Ki; aşırı gidenler için Rabbının katında nişanlanmış."},{"n":35,"t":"Bunun üzerine orada bulunan mü’minleri çıkardık."},{"n":36,"t":"Zaten orada bir evden başka müslüman bulamadık."},{"n":37,"t":"Elim azabdan korkanlar için orada bir ayet bıraktık."},{"n":38,"t":"Musa’da da. Hani onu, apaçık bir delille Firavun’a göndermiştik."},{"n":39,"t":"O, erkanı ile birlikte yüz çevirmiş; ya bir büyücü, ya da bir delidir, demişti."},{"n":40,"t":"Sonunda onu da, ordularını da yakalayıp denize attık. O, kınanacak işler yapıp durmaktaydı."},{"n":41,"t":"Ad’da da. Hani onların üzerine kasıp kavuran rüzgarı göndermiştik."},{"n":42,"t":"İsabet ettiği şeyi bırakmayıp toza çeviriyordu."},{"n":43,"t":"Semud’da da. Hani onlara: Bir süreye kadar yararlanın, demişti."},{"n":44,"t":"Onlar ise Rabblarının emrine başkaldırmışlardı, buyruğundan çıkmışlardı. Bunun üzerine kendilerini göz göre göre yıldırım çarpmıştı."},{"n":45,"t":"Ayağa kalkacak güçleri kalmamış, yardım da görmemişlerdi."},{"n":46,"t":"Daha önce de Nuh kavmini. Zira onlar gerçekten fasıklar güruhu idiler."},{"n":47,"t":"Göğü gücümüzle Biz kurduk. Ve muhakkak ki Biz, genişleticiyiz."},{"n":48,"t":"Yeryüzünü Biz, döşedik. Ne güzel döşeyicileriz."},{"n":49,"t":"Ve her şeyden çift çift yarattık ki ibret alasınız."},{"n":50,"t":"Öyleyse Allah’a koşun. Doğrusu ben; size, O’ndan apaçık bir uyarıcıyım."},{"n":51,"t":"Allah ile birlikte başka bir tanrı edinmeyin. Doğrusu ben; size, O’ndan apaçık bir uyarıcıyım."},{"n":52,"t":"İşte böyle. Onlardan öncekilere herhangi bir peygamber geldiğinde sadece; büyücüdür veya delidir, dediler."},{"n":53,"t":"Bunu birbirlerine tavsiye mi ettiler? Hayır, onlar; azgın birer topluluktu."},{"n":54,"t":"Onlardan yüz çevir. Artık sen, kınanacak değilsin."},{"n":55,"t":"Sen, öğüt ver. Çünkü öğüt mü’minlere fayda verir."},{"n":56,"t":"Ben, cinnleri ve insanları ancak Bana kulluk etsinler diye yarattım."},{"n":57,"t":"Ben, onlardan bir rızık istemiyorum. Beni doyurmalarını da istemiyorum."},{"n":58,"t":"Şüphesiz ki rızıklandıran, güç ve kuvvet sahibi olan Allah’tır."},{"n":59,"t":"Muhakkak ki zulmedenlerin, arkadaşlarının suçlarına benzer suçları vardır. Acele etmesinler."},{"n":60,"t":"Kendilerine vaadedilen günlerinden dolayı vay kafirlere."}],[{"n":1,"t":"Andolsun; Tur’a."},{"n":2,"t":"Satır satır dizilmiş kitaba;"},{"n":3,"t":"Yayılmış ince deri üzerine."},{"n":4,"t":"Ma’mur eve."},{"n":5,"t":"Yükseltilmiş tavana."},{"n":6,"t":"Dolan denize."},{"n":7,"t":"Muhakkak Rabbının azabı vuku bulacaktır."},{"n":8,"t":"Onu engelleyecek yoktur."},{"n":9,"t":"O gün; gök, sarsıldıkça sarsılır,"},{"n":10,"t":"Dağlar, yürüdükçe yürür."},{"n":11,"t":"İşte o gün; yalanlayanların vay haline."},{"n":12,"t":"Onlar ki; daldıkları batıl içinde oyalanıp durmaktadırlar."},{"n":13,"t":"O gün; cehennem ateşine itildikçe itilirler."},{"n":14,"t":"Yalanlayıp durduğunuz ateş, işte budur."},{"n":15,"t":"Bu bir büyü müdür, yoksa siz görmüyor musunuz?"},{"n":16,"t":"Girin oraya. Sabretseniz de, sabretmeseniz de artık birdir. Çünkü siz; ancak yapmakta olduklarınızla cezalandırılıyorsunuz."},{"n":17,"t":"Muhakkak ki muttakiler; cennetler ve nimetlerdedirler."},{"n":18,"t":"Rabblarının kendilerine verdikleriyle mutlu olarak. Rabbları onları cehennem azabından da korumuştur."},{"n":19,"t":"İşlediklerinize karşılık afiyetle yeyin, için."},{"n":20,"t":"Sıra sıra dizilmiş tahtlara yaslanarak. Ve onları iri siyah gözlü hurilerle evlendirdik."},{"n":21,"t":"İman edip de soyları da imanda kendilerine tabi olanlar; onlara, soylarını da kattık. Onların işlediklerinden hiç bir şey eksiltmedik. Herkes kazandığı ile bağlıdır."},{"n":22,"t":"Onlara, diledikleri meyve ve etten bol bol vermişizdir."},{"n":23,"t":"Orada öyle bir kadehi devrederler ki; onda, bir saçmalama ve günaha sokma yoktur."},{"n":24,"t":"Sedefleri içinde gizlenmiş inci gibi civanlar da kendileri için etraflarında döner."},{"n":25,"t":"Birbirlerine dönüp sorarlar:"},{"n":26,"t":"Derler ki: Gerçekten biz, bundan önce ailelerimiz arasında korku içindeydik."},{"n":27,"t":"Allah; bize, lutfetti de bizi gözeneklere işleyen o Semum azabından korudu."},{"n":28,"t":"Gerçekten biz, bundan önce de O’na dua ediyorduk. Muhakkak ki O’dur O Berr, Rahim."},{"n":29,"t":"Sen; öğüt ver. Rabbının nimeti sayesinde sen; ne bir kahinsin, ne de bir deli."},{"n":30,"t":"Yoksa derler mi ki: Şairdir, zamanın onun aleyhine dönmesini gözlüyoruz."},{"n":31,"t":"De ki: Gözleyin, doğrusu ben de sizinle beraber gözleyenlerdenim."},{"n":32,"t":"Bunu kendilerine akılları mı buyuruyor, yoksa onlar, azgın bir kavim midirler?"},{"n":33,"t":"Yoksa; onu kendisi uydurdu mu diyorlar? Hayır, onlar iman etmezler."},{"n":34,"t":"Şayet sadıklardan iseler, onun benzeri bir söz getirsinler."},{"n":35,"t":"Onlar; hiç bir şey olmaksızın mı yaratıldılar, yoksa kendileri midir yaratanları?"},{"n":36,"t":"Yoksa, gökleri ve yeri mi yarattılar? Hayır onlar, iyi bilmiyorlar."},{"n":37,"t":"Yoksa, Rabbının hazineleri onların yanında mıdır? Veya işe hakim olanlar onlar mıdır?"},{"n":38,"t":"Yoksa, üzerine çıkıp dinlendikleri bir merdivenleri mi var? Öyleyse dinleyicileri açık bir delil getirsinler."},{"n":39,"t":"Yoksa, kızlar O’nundur da, oğullar sizin öyle mi?"},{"n":40,"t":"Yoksa, sen, kendilerinden bir ücret istiyorsun da onlar ağır bir borç altında mı kalıyorlar?"},{"n":41,"t":"Yahut, gaybı bilmek kendilerine aittir de, onlar mı yazıyorlar?"},{"n":42,"t":"Yoksa, bir tuzak mı kurmak istiyorlar? Ama asıl tuzağa düşecek olanlar küfredenlerdir."},{"n":43,"t":"Yoksa, onların Allah’tan başka bir tanrısı mı var? Allah; onların koşmakta oldukları ortaklardan münezzehtir."},{"n":44,"t":"Gökten bir parçanın düşmekte olduğunu görseler: Birbiri üstüne yığılmış buluttur, derler."},{"n":45,"t":"Artık çarpılacakları günlerine erişinceye kadar bırak onları."},{"n":46,"t":"O gün; tuzakları kendilerine bir fayda vermez, yardım da görmezler."},{"n":47,"t":"Muhakkak ki o zulmedenlere; bundan başka da azab vardır. Ne var ki onların çoğu bilmezler."},{"n":48,"t":"Rabbının hükmüne sabret. Şüphesiz sen, Bizim gözetimimiz altındasın. Kalkacağın zaman da Rabbını hamd ile tesbih et."},{"n":49,"t":"Gecenin bir kısmında ve yıldızların batışından sonra da tesbih et."}],[{"n":1,"t":"Andolsun yıldıza, battığı demde."},{"n":2,"t":"Arkadaşınız sapmamış ve azmamıştır."},{"n":3,"t":"Kendiliğinden konuşmaz o."},{"n":4,"t":"Bu; sadece vahy edilen bir vahiydir."},{"n":5,"t":"Onu müthiş kuvvetli olan öğretti."},{"n":6,"t":"O; akıl ve görüşünde kamildir. Hemen doğruluverdi."},{"n":7,"t":"Ve o; en yüce ufukta idi."},{"n":8,"t":"Sonra yaklaştı, derken sarkıverdi."},{"n":9,"t":"İki yay kadar yahut daha da yakın oldu."},{"n":10,"t":"O vakit kuluna vahyedeceğini etti."},{"n":11,"t":"Onun gördüğünü gönül yalanlamadı."},{"n":12,"t":"Onun gördüğü şey üzerinde de kendisiyle tartışacak mısınız?"},{"n":13,"t":"Andolsun ki; onu, bir de diğer inişte görmüştü."},{"n":14,"t":"Sidret’ül-Münteha’nın yanında."},{"n":15,"t":"Ki Cennet’ül-Me’va da onun yanındadır."},{"n":16,"t":"O zaman Sidre’yi bürümekte olan bürüyordu."},{"n":17,"t":"Göz, ne şaştı ne aştı."},{"n":18,"t":"Andolsun ki; Rabbının, ayetlerinden en büyüğünü gördü."},{"n":19,"t":"Gördünüz mü Lat ve Uzza’yı?"},{"n":20,"t":"Üçüncüsü olan diğer Menat’ı?"},{"n":21,"t":"Demek erkekler sizin, dişiler O’nun mu?"},{"n":22,"t":"Öyleyse bu, insafsız bir paylaşma."},{"n":23,"t":"Bunlar, sizin ve atalarınızın taktığı adlardan başka bir şey değildir. Allah onlara hiç bir güç indirmemiştir. Onlar kuruntudan ve nefislerin arzu ettiği hevadan başkasına uymuyorlar. Halbuki kendilerine Rabblarından hidayet gelmiştir."},{"n":24,"t":"Yoksa, her umduğu şey insanın mıdır?"},{"n":25,"t":"Ahiret de dünya da Allah’ındır."},{"n":26,"t":"Göklerde nice melek vardır ki; Allah, dileyeceği ve razı olacağı kimseler için izin vermedikçe onların şefaatı hiç bir şeye yaramaz."},{"n":27,"t":"Doğrusu ahirete inanmayanlar meleklere dişi adlarını takarlar."},{"n":28,"t":"Halbuki onların bu hususta bilgileri yoktur. Onlar, sadece zanna uyarlar. Zan ise hiç şüphesiz gerçekten bir şey ifade etmez."},{"n":29,"t":"Onun için sen, Bizim zikrimize sırt çeviren ve dünya hayatından başkasını istemeyenlerden yüz çevir."},{"n":30,"t":"Onların bilgiden erişebilecekleri işte budur. Muhakkak ki Rabbın; yolundan sapmış olanı en iyi bilendir. Ve O; hidayete ereni de en iyi bilendir."},{"n":31,"t":"Göklerde olan da, yerde olan da Allah’ındır. Kötülük edenlere yaptıklarının karşılığını vermesi, ihsan edenleri de daha güzeliyle mükafatlandırması içindir."},{"n":32,"t":"Onlar ki; ufak-tefek kusurları dışında günahın büyüklerinden ve hayasızlıktan kaçınırlar. Muhakkak ki Rabbın; mağfireti geniş olandır. Sizi, daha topraktan yarattığı zaman ve henüz analarınızın karınlarında cenin halinde iken sizi en iyi bilen O’dur. Kendinizi temize çıkarmayın. O; takva sahibi olanları da en iyi bilendir."},{"n":33,"t":"Gördün mü o yüz çevireni;"},{"n":34,"t":"Biraz verip sonra vermemekte direneni."},{"n":35,"t":"Gaybın bilgisi onun yanındadır da kendisi mi görüyor?"},{"n":36,"t":"Yoksa kendisine bildirilmedi mi Musa’nın sahifelerinde olanlar?"},{"n":37,"t":"Ve sözünü yerine getiren İbrahim’inkinde de."},{"n":38,"t":"Doğrusu hiç bir günahkar başkasının günah yükünü yüklenmez."},{"n":39,"t":"Gerçekten insan için, çalıştığından başkası yoktur."},{"n":40,"t":"Ve onun çalışması ilerde görülecektir."},{"n":41,"t":"Sonra ona karşılığı tastamam verilecektir."},{"n":42,"t":"Muhakkak ki en son varış, Rabbınadır."},{"n":43,"t":"Gerçekten O’dur güldüren de, ağlatan da."},{"n":44,"t":"Gerçekten O’dur öldüren de, dirilten de."},{"n":45,"t":"Doğrusu O yarattı iki çifti; erkeği de, dişiyi de."},{"n":46,"t":"Atıldığında meniden."},{"n":47,"t":"Muhakkak tekrar diriltmek de O’na aittir."},{"n":48,"t":"Doğrusu muhtaç olmaktan kurtaran da O’dur, sermaye sahibi kılan da."},{"n":49,"t":"Doğrusu O’dur Şi’ra yıldızının Rabbı."},{"n":50,"t":"Ve gerçekten O helak etti evvelki Ad’ı."},{"n":51,"t":"Semud’u da. Geri bırakmadan."},{"n":52,"t":"Daha önce de Nuh kavmini. Çünkü onlar gerçekten çok zalim ve pek azgın idiler."},{"n":53,"t":"Altı üstüne gelen kasabaları da O, yerin dibine geçirdi."},{"n":54,"t":"Onlara giydirdiğini giydirdi."},{"n":55,"t":"Şimdi Rabbının hangi nimetinden şüpheye düşersin?"},{"n":56,"t":"İşte bu; ilk uyarıcılar gibi bir uyarıcıdır."},{"n":57,"t":"Yaklaşan yaklaştı."},{"n":58,"t":"Onu Allah’tan başka ortaya çıkaracak yoktur."},{"n":59,"t":"Bu söze mi şaşıyorsunuz siz?"},{"n":60,"t":"Ve gülüyorsunuz da ağlamıyorsunuz."},{"n":61,"t":"Ve siz, habersiz oyalanmaktasınız."},{"n":62,"t":"Haydi Allah’a secde edin ve ibadet edin."}],[{"n":1,"t":"Saat yaklaştı ve ay yarıldı."},{"n":2,"t":"Onlar, bir ayet görürlerse yüz çevirirler ve; süregelen bir büyüdür, derler."},{"n":3,"t":"Ve yalanlayıp kendi heveslerine uyarlar. Ve her iş kararlaşmıştır."},{"n":4,"t":"Andolsun ki; onlara vazgeçirecek nice önemli haberler gelmiştir."},{"n":5,"t":"Ki bunlar gayesine ermiş bir hikmettir. Fakat uyarılar fayda vermiyor."},{"n":6,"t":"Öyleyse yüz çevir onlardan. O çağıranın, görülmemiş ve tanınmamış bir şeye çağırdığı gün."},{"n":7,"t":"Gözleri hor ve hakir olarak, yaygın çekirgeler gibi kabirlerinden çıkarlar."},{"n":8,"t":"O çağırana koşarak kafirler: Bu, zorlu bir gündür, derler."},{"n":9,"t":"Onlardan önce Nuh kavmi de yalanlamış, kulumuzu tekzib ederek; delidir, demişler ve yolunu kesmişlerdi."},{"n":10,"t":"O da Rabbına yalvarmış: Ben; yenildim, bana yardım et, demişti."},{"n":11,"t":"Bunun üzerine Biz de gök kapılarını boşanan sularla açmıştık."},{"n":12,"t":"Yeryüzünde kaynaklar fışkırttık da su, takdir edilen bir ölçüye göre birleşiverdi."},{"n":13,"t":"Onu tahtadan yapılmış, mıhla çakılmışa bindirdik."},{"n":14,"t":"Küfredilmiş olana mükafat olmak üzere Bizim gözetimimizle yüzüyordu."},{"n":15,"t":"Andolsun ki Biz, onu bir ayet olarak bıraktık. Düşünüp ibret alan var mı?"},{"n":16,"t":"Benim azabım ve tehditlerim nasılmış?"},{"n":17,"t":"Andolsun ki; Biz, Kur’an’ı düşünmek için kolaylaştırdık. Düşünüp öğüt alan var mı?"},{"n":18,"t":"Ad kavmi de tekzib etti. Benim azabım ve tehdidim nasılmış?"},{"n":19,"t":"Nitekim uğursuz günde üzerlerine şiddetli bir rüzgarı devamlı olarak gönderdik."},{"n":20,"t":"İnsanları, sökülmüş hurma kütükleri gibi koparıp yere seriyordu."},{"n":21,"t":"İşte Benim azabım ve tehditlerim nasılmış?"},{"n":22,"t":"Andolsun ki; Biz, Kur’an’ı, düşünmek için kolaylaştırdık. Düşünüp öğüt alan var mı?"},{"n":23,"t":"Semud kavmi de uyarıları yalanladı."},{"n":24,"t":"Dediler ki: İçimizden bir insana mı uyacağız? O zaman biz, sapıklık ve delilik etmiş oluruz."},{"n":25,"t":"Zikir, aramızdan ona mı verilmiş? Hayır o, pek yalancı ve şımarığın biridir."},{"n":26,"t":"Yarın kimin pek yalancı, şımarığın biri olduğunu bileceklerdir."},{"n":27,"t":"Gerçekten onları, imtihan etmek için dişi deveyi gönderen Biziz. Onları gözetle ve sabret."},{"n":28,"t":"Onlara, suyun aralarında taksim olunduğunu da haber ver. Her biri su nöbetinde hazır bulunsun."},{"n":29,"t":"Arkadaşlarını çağırdılar, o da sarılarak onu kesti."},{"n":30,"t":"İşte, Benim azabım ve tehditlerim nasılmış?"},{"n":31,"t":"Nitekim üzerlerine bir tek çığlık gönderdik de ağılcıların kullandığı kurumuş ot gibi oldular."},{"n":32,"t":"Andolsun ki; Biz, Kur’an’ı düşünmek için kolaylaştırdık. Düşünüp öğüt alan var mı?"},{"n":33,"t":"Lut kavmi de uyarıları yalanladı."},{"n":34,"t":"Biz de üzerlerine taş yağdıran bir rüzgar yolladık. Ancak Lut’un ailesi müstesna. Onları seher vakti kurtardık."},{"n":35,"t":"Katımızdan bir nimet olarak. İşte Biz; şükredeni böyle mükafatlandırırız."},{"n":36,"t":"Andolsun ki; onlara, azab ile yakalayacağımızı da haber vermişti. Ama onlar bu uyarıları kuşku ile karşılayarak yalanladılar."},{"n":37,"t":"Andolsun ki; onlar, misafirlerine kötülük yapmayı kasdetmişlerdi. Biz de gözlerini kör ettik. Azabımı ve tehdidimi tadın."},{"n":38,"t":"Andolsun ki; bir sabah erken, önü alınmaz bir azab geldi başlarına."},{"n":39,"t":"Tadın, işte azabımı ve tehditlerimi."},{"n":40,"t":"Andolsun ki; Biz, Kur’an’ı düşünmek için kolaylaştırdık. Düşünüp ibret alan var mı?"},{"n":41,"t":"Andolsun ki; Firavun erkanına da uyarıcılar geldi."},{"n":42,"t":"Onlar, bütün ayetlerimizi yalanladılar. Biz de kendilerini, çok kuvvetli ve kudretli bir yakalayışla yakaladık."},{"n":43,"t":"Sizin kafirleriniz bunlardan daha mı iyidir? Yoksa kitablarda sizin için bir beraat mi vardır?"},{"n":44,"t":"Yoksa onlar: Biz, intikam almaya muktedir bir topluluğuz mu diyorlar?"},{"n":45,"t":"Topluluk yakında dağıtılacak ve onlar arkalarını dönüp kaçacaklar."},{"n":46,"t":"Daha doğrusu onlara vaadolunan asıl saattir. O saat ne belalı, ne acıdır."},{"n":47,"t":"Muhakkak ki suçlular; sapıklık ve çılgın ateşler içindedirler."},{"n":48,"t":"O gün, yüzleri üstü ateşe sürüldüklerinde: Tadın cehennemin tadını, denir."},{"n":49,"t":"Muhakkak ki Biz, her şeyi bir ölçüye göre yaratmışızdır."},{"n":50,"t":"Ve Bizim emrimiz bir tektir; bir göz kırpması gibidir."},{"n":51,"t":"Andolsun ki; Biz, sizin benzerlerinizi hep helak etmişizdir. Şu halde bir düşünen var mı?"},{"n":52,"t":"Yaptıkları her şey kitablarda kayıtlıdır."},{"n":53,"t":"Küçük, büyük her şey satır satırdır."},{"n":54,"t":"Muhakkak ki muttakiler, cennetlerde ve ırmaklardadırlar."},{"n":55,"t":"Doğruluk makamında, güçlü bir hükümdarın katındadırlar."}],[{"n":1,"t":"Rahman."},{"n":2,"t":"Kur’an’ı öğretti."},{"n":3,"t":"İnsanı yarattı."},{"n":4,"t":"Ona beyanı öğretti."},{"n":5,"t":"Güneş de, ay da bir hesab iledir."},{"n":6,"t":"Bitkiler ve ağaçlar da secde ederler."},{"n":7,"t":"Göğü yükseltmiş, mizanı koymuştur."},{"n":8,"t":"Tartıda haksızlık etmeyin."},{"n":9,"t":"Tartıyı doğru yapın, tartılanı eksik yapmayın."},{"n":10,"t":"Yeri de yaratıklar için alçalttı."},{"n":11,"t":"Onda meyveler, salkımlı hurma ağaçları;"},{"n":12,"t":"Yapraklı taneler ve kokulu bitkiler var."},{"n":13,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":14,"t":"İnsanı pişmiş çamur gibi kupkuru bir balçıktan yaratmıştır."},{"n":15,"t":"Cinnleri de yalın bir alevden yaratmıştır."},{"n":16,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":17,"t":"O; hem iki doğunun Rabbı, hem de iki batının Rabbıdır."},{"n":18,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":19,"t":"İki denizi birbirine kavuşmak üzere salıvermiştir."},{"n":20,"t":"Aralarında bir engel vardır, birbirinin sınırını aşamazlar."},{"n":21,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":22,"t":"Her ikisinden de inci ve mercan çıkar."},{"n":23,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":24,"t":"Denizde yüzen koca dağlar gibi gemiler de O’nundur."},{"n":25,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":26,"t":"Onun üzerinde her bulunan fanidir."},{"n":27,"t":"Ancak celal ve ikram sahibi Rabbının zatı baki kalacaktır."},{"n":28,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":29,"t":"Göklerde ve yerde kim varsa hepsi O’ndan ister. O; her gün bir şe’n üzeredir."},{"n":30,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":31,"t":"Ey insanlar ve cinnler; yakında size de yöneleceğiz"},{"n":32,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":33,"t":"Ey cinnler ve insanlar topluluğu; göklerin ve yerin çevresinden geçip gitmeye gücünüz yetiyorsa geçip gidin. Ama üstün bir güç olmadan geçemezsiniz."},{"n":34,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":35,"t":"Üzerinize dumansız bir alev ve ateşsiz bir duman gönderilir de birbirinizi kurtaramaz ve yardımlaşamazsınız."},{"n":36,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":37,"t":"Gök, yarılıp da kırmızı sahtiyan gibi bir gül olduğu zaman,"},{"n":38,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":39,"t":"İşte o gün; insana da, cinne de günahından sorulmaz."},{"n":40,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz. _"},{"n":41,"t":"Suçlular simalarından tanınırlar da perçemlerinden ve ayaklarından tutulurlar."},{"n":42,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":43,"t":"Suçluların yalanladıkları cehennem, işte budur."},{"n":44,"t":"Onlar bununla kaynar su arasında dolaşır dururlar."},{"n":45,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":46,"t":"Rabbının makamından korkana iki cennet vardır."},{"n":47,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":48,"t":"Her ikisi çeşit çeşit ağaçlarla doludur."},{"n":49,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":50,"t":"İkisinde de akmakta olan iki pınar vardır."},{"n":51,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":52,"t":"İkisinde de her tür meyveden çift çift vardır."},{"n":53,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":54,"t":"Hepsi de örtüleri atlastan döşemelere yaslanırlar. İki cennetin meyvelerini de kolayca toplarlar."},{"n":55,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":56,"t":"Oralarda bakışlarını yalnız eşlerine çevirmişler vardır ki, daha önce kendilerine ne bir insan, ne de bir cinn dokunmuştur."},{"n":57,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":58,"t":"Sanki onlar yakut ve mercandırlar."},{"n":59,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":60,"t":"İhsanın karşılığı, ihsandan başkası mıdır?"},{"n":61,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":62,"t":"O ikisinden başka iki cennet daha vardır."},{"n":63,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":64,"t":"Koyu yeşildirler."},{"n":65,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":66,"t":"İkisinde de durmadan fışkıran iki kaynak vardır."},{"n":67,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":68,"t":"İkisinde de meyveler, hurma ve nar vardır."},{"n":69,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":70,"t":"Orada huyları güzel, yüzleri güzel kadınlar vardır."},{"n":71,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":72,"t":"Otağlar içinde korunmuş huriler vardır."},{"n":73,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":74,"t":"Bunlardan önce kendilerine ne bir insan, ne de bir cin dokunmuştur."},{"n":75,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":76,"t":"Yeşil yastıklara ve güzel işlemeli döşeklere yaslanırlar."},{"n":77,"t":"Şu halde Rabbınızın hangi nimetlerini yalan sayabilirsiniz?"},{"n":78,"t":"Celal ve ikram sahibi Rabbının adı ne yücedir."}],[{"n":1,"t":"Kıyamet koptuğu zaman,"},{"n":2,"t":"Onun vukuunu hiç bir yalanlayıcı yoktur."},{"n":3,"t":"O; alçaltıcı, yükselticidir."},{"n":4,"t":"Yer; sarsıldıkça sarsıldığı;"},{"n":5,"t":"Dağlar, ufalandıkça ufalandığı;"},{"n":6,"t":"Dağılmış toz haline geldiği zaman;"},{"n":7,"t":"Siz üç sınıf olmuşsunuzdur:"},{"n":8,"t":"Sağcılar; o sağcılar ne mutludurlar."},{"n":9,"t":"Solcular; o solcular ne bahtsızdırlar."},{"n":10,"t":"Önde olanlar da öncüdürler."},{"n":11,"t":"İşte onlar en çok gözde olanlardır."},{"n":12,"t":"Naim cennetlerindedirler."},{"n":13,"t":"Bir çoğu öncekilerden,"},{"n":14,"t":"Birazı da sonrakilerden."},{"n":15,"t":"Murassa tahtlar üzerindedirler."},{"n":16,"t":"Karşılıklı olarak üzerinde yaslanırlar."},{"n":17,"t":"Ölümsüz civanlar etraflarında dolaşırlar."},{"n":18,"t":"Main’den büyük kaplarla, ibrikler ve kadehlerle."},{"n":19,"t":"Ondan baş ağrısına uğratılmayacakları gibi, akılları da giderilmez."},{"n":20,"t":"Beğenecekleri meyveler,"},{"n":21,"t":"Kuş eti, içlerinin çektiğinden."},{"n":22,"t":"Şahin gözlü huriler de;"},{"n":23,"t":"Saklı inci misali."},{"n":24,"t":"Yapmakta olduklarına karşılık olarak."},{"n":25,"t":"Orada ne boş bir laf, ne de günaha sokacak birşey işitmezler."},{"n":26,"t":"Yalnız selama karşılık; selam, denir."},{"n":27,"t":"Sağcılar; ne bahtiyardır o sağcılar."},{"n":28,"t":"Dikensiz kiraz,"},{"n":29,"t":"Salkımları sarkmış muz ağaçları,"},{"n":30,"t":"Yayılmış gölge,"},{"n":31,"t":"Çağlayan su,"},{"n":32,"t":"Bir çok meyve,"},{"n":33,"t":"Bitip tükenmeyen ve yasaklanmayan."},{"n":34,"t":"Yükseltilmiş döşekler üstündedirler."},{"n":35,"t":"Gerçekten Biz; onları, yeni bir yaratılışla yarattık."},{"n":36,"t":"Ve onları el değmemişler kıldık."},{"n":37,"t":"Eşlerine düşkün hep bir yaşıtlar."},{"n":38,"t":"Sağcılar için."},{"n":39,"t":"Bir çoğu öncekilerden,"},{"n":40,"t":"Bir çoğu da sonrakilerdendir."},{"n":41,"t":"Solcular da. Solcular kimlerdir?"},{"n":42,"t":"Kızgın ateşte, kaynar sulardadırlar."},{"n":43,"t":"Ve kapkara dumandan bir gölge içindedirler."},{"n":44,"t":"Ne serindir, ne de hoştur."},{"n":45,"t":"Çünkü onlar; bundan önce refahla şımarmışlardı."},{"n":46,"t":"Ve büyük günah işlemekte direnip dururlardı."},{"n":47,"t":"Ve derlerdi ki: Öldüğümüzde, toprak ve kemik yığını olduğumuzda mı, gerçekten biz mi yeniden diriltileceğiz?"},{"n":48,"t":"Önce gelmiş geçmiş atalarımız da mı?"},{"n":49,"t":"De ki: Şüphesiz hem öncekiler, hem sonrakiler,"},{"n":50,"t":"Belli bir günün belli bir vaktinde mutlaka toplanacaklardır."},{"n":51,"t":"Sonra gerçekten siz ey sapıklar, yalanlayıcılar;"},{"n":52,"t":"Muhakkak ki yiyeceksiniz zakkum ağacından."},{"n":53,"t":"Karınlarınızı dolduracaksınız hep ondan."},{"n":54,"t":"Üstüne de içeceksiniz o kaynar sudan."},{"n":55,"t":"Susamış develerin suya saldırışı gibi içeceksiniz."},{"n":56,"t":"İşte ceza günü onlara sunulacak ziyafet budur."},{"n":57,"t":"Sizi; Biz, yarattık. Hala tasdik etmez misiniz?"},{"n":58,"t":"Söyleyin öyleyse; dökmekte olduğunuz meni nedir?"},{"n":59,"t":"Onu siz mi yaratıyorsunuz, yoksa yaratanlar Biz miyiz?"},{"n":60,"t":"Biz, takdir ettik aranızda ölümü. Ve Biz, önüne geçilecekler de değiliz."},{"n":61,"t":"Yerinize benzerlerinizi getirmekte ve sizi bilemeyeceğiniz bir yaratılışla tekrar var etmekte."},{"n":62,"t":"Andolsun ki; ilk yaratılışınızı bildiniz. İyice düşünmeli değil misiniz?"},{"n":63,"t":"Şimdi Bana; ekmekte olduğunuzu haber verin."},{"n":64,"t":"Onu, siz mi bitiriyorsunuz, yoksa Biz miyiz, bitirenler?"},{"n":65,"t":"Dilersek Biz, onu çörçöp yaparız da şaşar kalırsınız."},{"n":66,"t":"Doğrusu borç altına girdik,"},{"n":67,"t":"Daha doğrusu biz mahrumlarız."},{"n":68,"t":"Söyleyin Bana şimdi, içmekte olduğunuz suyu;"},{"n":69,"t":"Onu buluttan siz mi indirdiniz, yoksa Biz miyiz indirenler?"},{"n":70,"t":"İsteseydik onu tuzlu bir su kılardık. Öyleyse şükretmeli değil misiniz?"},{"n":71,"t":"Söyleyin bana, şimdi çakmakta olduğunuz ateşi,"},{"n":72,"t":"Onun ağacını siz mi yarattınız, yoksa Biz miyiz yaratanlar?"},{"n":73,"t":"Biz, onu bir ibret ve konaklayanlar için faydalı kıldık."},{"n":74,"t":"Öyleyse Rabbını o büyük adıyla tesbih et."},{"n":75,"t":"Hayır yıldızların yerleri üzerine yemin ederim;"},{"n":76,"t":"Gerçekten bilseniz bu, büyük bir yemindir."},{"n":77,"t":"Şüphesiz o; şerefli bir Kur’an’dır."},{"n":78,"t":"Korunmuş bir kitabdadır."},{"n":79,"t":"Ona arınmış olanlardan başkası dokunamaz."},{"n":80,"t":"Alemlerin Rabbından indirilmedir."},{"n":81,"t":"Siz, bu sözü mü küçümsüyorsunuz?"},{"n":82,"t":"Rızkınızı yalanlamakla mı çıkarıyorsunuz?"},{"n":83,"t":"Hele can boğaza gelince;"},{"n":84,"t":"O vakit görürsünüz siz."},{"n":85,"t":"Biz ona sizden daha yakınız, ama görmezsiniz."},{"n":86,"t":"Madem ki ceza görmeyecekmişsiniz,"},{"n":87,"t":"Onu geri çevirsenize. Şayet sadıklar iseniz."},{"n":88,"t":"Eğer o kişi gözdelerden ise;"},{"n":89,"t":"Rahatlık, güzel rızık ve Naim cenneti."},{"n":90,"t":"Şayet sağcılardan ise;"},{"n":91,"t":"Selem sana sağcılardan."},{"n":92,"t":"Eğer sapık yalanlayıcılardan ise;"},{"n":93,"t":"İşte ona da kaynar sudan bir ziyafet,"},{"n":94,"t":"Ve cehenneme atılış."},{"n":95,"t":"Şüphesiz ki bu; kesin gerçeğin kendisidir."},{"n":96,"t":"Öyleyse Rabbını büyük adıyla tesbih et."}],[{"n":1,"t":"Göklerde ve yerde olanlar Allah’ı tesbih etmektedirler. Ve O; Aziz’dir, Hakim’dir."},{"n":2,"t":"Göklerin ve yerin mülkü O’nundur. Diriltir, öldürür. Ve O; her şeye kadirdir."},{"n":3,"t":"O; hem Evvel’dir, hem Ahir’dir, hem Zahir’dir, hem Batın’dır. Ve O; her şeyi bilendir."},{"n":4,"t":"Gökleri ve yeri altı günde yaratan, sonra da Arş’a hükmeden O’dur. Yere gireni ve ondan çıkanı, gökten ineni ve oraya yükseleni bilir. Nerede olursanız olun, O, sizinle beraberdir. Ve Allah; yaptıklarınızı görmektedir."},{"n":5,"t":"Göklerin ve yerin mülkü O’nundur. Ve bütün işler ancak O’na döndürülür."},{"n":6,"t":"Geceyi gündüze katar, gündüzü de geceye katar. Ve O; göğüslerin özünü bilendir."},{"n":7,"t":"Allah’a ve peygamberine iman edin ve sizi halifeler kıldığı şeylerden de infak edin. Aranızdan iman edip de infak eden kimselere büyük mükafat vardır."},{"n":8,"t":"Peygamber; sizi Rabbınıza iman etmeye çağırdığı halde, niçin Allah’a inanmıyorsunuz? Halbuki O, sizden kesin söz almıştı. Eğer inanacaklardan iseniz."},{"n":9,"t":"Sizi karanlıklardan aydınlığa çıkarmak için kuluna apaçık ayetler indiren O’dur. Doğrusu Allah; size karşı Rauf’tur, Rahim’dir."},{"n":10,"t":"Ne oluyor size ki; Allah yolunda infak etmiyorsunuz? Halbuki göklerin ve yerin mirası Allah’ındır. İçinizden, fetihten önce infak eden ve savaşanlar; daha sonra infak edip savaşanlar elbette bir değildir. Berikiler daha üstün derecededirler. Allah; hepsine de en güzel olanı vaadetmiştir. Allah; yaptıklarınızdan haberdardır."},{"n":11,"t":"Kim, Allah’a güzel bir ödünç verecek olursa; Allah ona karşılığını kat kat verir. Ve ona, çok değerli bir mükafat da vardır."},{"n":12,"t":"O gün; mü’min erkeklerle mü’min kadınların nurları önlerinden ve sağlarından koşarken görürsün. Müjde, bugün altlarından ırmaklar akan ve içinde ebediyyen kalacağınız cennetler sizindir, denilir. İşte bu, büyük kurtuluşun kendisidir."},{"n":13,"t":"O gün; münafık erkeklerle münafık kadınlar, iman edenlere: Bekleyin bizi; ışığınızdan faydalanalım, diyeceklerdir. Onlara: Dönün, arkanıza da bir ışık arayın, denilir. Nihayet onların arasına kapısının içinde rahmet, dışında azab olan bir sur çekilir."},{"n":14,"t":"Onlara: Biz sizinle beraber değil miydik? diye seslenirler. Onlar da: Evet, ama siz kendinizi aldattınız, pusu kurdunuz, şüpheye düştünüz ve kuruntular sizi aldattı. O çok aldatan, sizi Allah’a karşı bile aldattı. Nihayet Allah’ın emri gelip çattı."},{"n":15,"t":"Bugün, sizden ve küfretmiş olanlardan fidye kabul edilmez. Varacağınız yer ateştir. Size yaraşan odur. Ve o, ne kötü dönüş yeridir."},{"n":16,"t":"İman edenlerin, Allah’ı anması ve O’ndan inen gerçek için kalblerinin yumuşaması zamanı hala gelmedi mi? Onlar, daha önce kendilerine kitab verilip de üzerlerinden uzun zaman geçmiş, artık kalbleri katılaşmış bulunanlar gibi olmasınlar. Onlardan bir çoğu fasıklardır."},{"n":17,"t":"Bilin ki; Allah, ölümünden sonra yeryüzünü diriltiyor. Akledesiniz diye, size ayetleri açıkça bildirdik."},{"n":18,"t":"Muhakkak ki sadaka veren erkeklerle, sadaka veren kadınlar ve Allah’a güzel bir ödünç verenlere; işte onlara, kat kat artırılır ve onlara değerli bir mükafat vardır."},{"n":19,"t":"Allah’a ve peygamberlerine iman edenler; işte onlar, Rabbları katında doğrular ve şahidlerdir. Onların hem mükafatları, hem de nurları vardır. Küfredip de ayetlerimizi yalanlayanlara gelince; onlar da cehennem yaranıdırlar."},{"n":20,"t":"Bilin ki; dünya hayatı ancak bir oyun, bir eğlence, bir süs, aranızda bir övünme ve daha çok mal ve evlad sahibi olmak isteğinden ibarettir. Bu; yağmurun bitirdiği, ekicilerin de hoşuna giden bir bitki gibidir ki; sonra kurur da sapsarı olduğunu görürsün. Sonra da çörçöp olur. Ahirette şiddetli azab vardır. Allah’ın rızası ve mağfireti de vardır. Dünya hayatı, aldatıcı bir geçinmeden başka bir şey de değildir."},{"n":21,"t":"Rabbınızdan bir mağfirete, Allah’a ve peygamberlerine iman edenler için hazırlanmış olup da genişliği yerle göğün genişliği kadar olan cennete koşuşun. İşte bu; Allah’ın lutfudur, onu dilediğine verir. Allah büyük lutuf sahibidir."},{"n":22,"t":"Yeryüzüne ve sizin başınıza gelen herhangi bir musibet yoktur ki; Biz onu yaratmadan evvel kitabda bulunmasın. Şüphesiz ki bu; Allah’a göre kolaydır."},{"n":23,"t":"Kaybettiğinize üzülmeyesiniz ve size verdiği nimetlerle şımarmayasınız diye. Allah; kendini beğenip böbürlenenleri sevmez."},{"n":24,"t":"Onlar ki; cimrilik ederler ve insanlara da cimriliği emrederler. Kim, yüz çevirirse; şüphesiz ki Allah; Gani’dir, Hamid’dir."},{"n":25,"t":"Andolsun ki; Biz, peygamberlerimizi açık delillerle gönderdik. Ve insanların adaleti ayakta tutmaları için beraberlerinde kitabı ve mizanı indirdik. Bir de kendisinde çetin bir sertlik ve insanlar için faydalar bulunan demiri indirdik. Allah; kimin, görmeden Allah’a ve peygamberlerine yardım edeceğini bilir. Muhakkak ki Allah; Kavi’dir, Aziz’dir."},{"n":26,"t":"Andolsun ki; Biz, Nuh’u ve İbrahim’i gönderdik. Peygamberliği de, kitabı da onların soyuna verdik. Onlardan kimi doğru yoldadır, içlerinden bir çoğu da fasıklardır."},{"n":27,"t":"Sonra onların izleri üzerinde, peygamberlerimizi ard arda gönderdik. Meryem oğlu İsa’yı da arkalarından gönderdik. Ona İncil’i verdik ve ona uyanların kalblerine bir şefkat ve merhamet koyduk. Onların uydurdukları rehbaniyyete gelince; onu kendilerine Biz, yazmadık. Fakat kendileri Allah’ın rızasını kazanmak için yaptılar. Ama buna da hakkıyla riayet etmediler. Biz de onlardan iman etmiş olanlara ecirlerini verdik. İçlerinden çoğu ise fasıklardır."},{"n":28,"t":"Ey iman edenler; Allah’tan korkun ve peygamberlerine inanın ki, size rahmetini iki kat versin. Size ışığında yürüyeceğiniz bir nur lutfetsin. Ve sizi bağışlasın. Allah; Gafur’dur, Rahim’dir."},{"n":29,"t":"Böylece kitab ehli, Allah’ın lutfundan hiç bir şey elde edemeyeceklerini bilsinler. Muhakkak ki lutuf, bütünüyle Allah’ın elindedir, onu dilediğine verir. Ve Allah; büyük lutuf sahibidir."}],[{"n":1,"t":"Allah, kocası hakkında seninle tartışan ve Allah’a şikayette bulunanın sözünü işitmiştir. Allah; sizin konuşmanızı işitir. Muhakkak ki Allah; Semi’dir, Basir’dir."},{"n":2,"t":"İçinizden zihar yapanların karıları onların anaları değildir. Anaları, ancak kendilerini doğuranlardır. Şüphesiz ki onlar, çirkin ve yalan bir laf söylüyorlar. Ve muhakkak ki Allah; Afüvv’dür, Gafur’dur."},{"n":3,"t":"Karılarından zıhar ile ayrılmak isteyip de sonra dediklerini geri alanların aileleriyle temas etmeden önce bir köle azad etmeleri gerekir. Size böylece öğüt verilmektedir. Allah; yaptıklarınızdan haberdardır."},{"n":4,"t":"Kim de bulamazsa; temas etmezden önce birbiri peşinden iki ay oruç tutmalıdır. Buna da gücü yetmeyen altmış yoksulu doyurur. Bu; Allah’a ve peygamberine iman etmekte olduğunuz içindir. Bunlar, Allah’ın hudududur. Ve kafirler için elim bir azab vardır."},{"n":5,"t":"Allah’a ve Rasulüne muhalefet edenler; kendilerinden öncekiler nasıl alçaltıldı ise öyle alçaltılacaklardır. Halbuki Biz, apaçık ayetler indirmişizdir. Ve küfredenlere horlayıcı bir azab vardır."},{"n":6,"t":"O gün; Allah, onların hepsini diriltecek ve kendilerine işlediklerini haber verecektir. Allah, onları bir bir saymıştır. Ama kendileri unutmuşlardır. Ve Allah; her şeye şahiddir."},{"n":7,"t":"Bilmez misin ki Allah; göklerde olanları da, yerde olanları da bilir. Üç kişinin gizli bulunduğu yerde dördüncü mutlaka O’dur, beş kişinin gizli bulunduğu yerde altıncı mutlaka O’dur. Bundan az veya çok olsunlar ve nerede bulunurlarsa bulunsunlar mutlaka onlarla beraberdir. Sonra, bütün yaptıklarını kıyamet günü kendilerine haber verecektir. Muhakkak ki Allah, her şeyi bilendir."},{"n":8,"t":"Gizli gizli konuşmaktan men’edildikleri halde, men’edildikleri şeyi yapmaya kalkışanlarla günah işlemek, düşmanlık etmek ve Peygambere karşı gelmek konusunda gizlice konuşanları görmedin mi? Sana geldikleri zaman, seni Allah’ın selamladığı bir şeyle selamlarlar. Kendi aralarında da: Söylediklerimiz yüzünden Allah’ın bize azab etmesi gerekmez miydi? derler. Onlara cehennem yeter. Oraya gireceklerdir. Ne kötü dönüş yeridir."},{"n":9,"t":"Ey iman edenler; aranızda gizli konuşacağınız zaman; günahı, düşmanlığı ve Peygambere isyanı fısıldaşmayın. Birr’i, takvayı konuşun ve huzurunda toplanacağınız Allah’tan korkun."},{"n":10,"t":"Gizli konuşmalar, ancak iman edenleri üzmek için şeytandandır. Halbuki Allah’ın izni olmadıkça onlara hiç bir şeyle zarar veremez. Mü’minler, Allah’a tevekkül etsinler."},{"n":11,"t":"Ey iman edenler; size: Meclislerde yer açın, denilince; yer açın ki, Allah da size açsın. Kalkın, denince de kalkın ki, Allah içinizden iman etmiş olanları ve kendilerine ilim verilenleri derecelerle yükseltsin. Allah; yaptıklarınızdan haberdardır."},{"n":12,"t":"Ey iman edenler; Peygamberle mahrem bir şey konuşacağınız vakit, bu konuşmanızdan önce sadaka verin. Bu; sizin için daha hayırlı ve daha temizdir. Eğer bir şey bulamazsanız, şüphesiz ki Allah; Gafur’dur, Rahim’dir."},{"n":13,"t":"Mahrem bir şey konuşmazdan önce, sadaka vermekten korktunuz mu da yerine getirmediniz? Fakat Allah, sizin tevbelerinizi kabul etti. Şu halde namazı kılın, zekatı verin, Allah’a ve Rasulüne itaat edin. Allah; işlediklerinizden haberdardır."},{"n":14,"t":"Bakmaz mısın onlara ki, Allah’ın, kendilerine gazab ettiği bir kavmi dost edinmişlerdir? Onlar; ne sizdendir, ne de onlardan. Ve bile bile yalan yere yemin etmektedirler."},{"n":15,"t":"Allah; onlara şiddetli bir azab hazırlamıştır. Gerçekten onların yaptıkları şey ne kötüdür."},{"n":16,"t":"Onlar; yeminlerini kalkan edindiler de Allah yolundan alıkoydular. İşte onlara, horlayıcı bir azab vardır."},{"n":17,"t":"Onların malları da, oğulları da Allah katında kendilerine bir fayda vermez. Onlar, cehennem ashabıdırlar ve orada ebediyyen kalacaklardır."},{"n":18,"t":"Allah, onların hepsini yeniden dirilteceği gün; size yemin ettikleri gibi, O’na da yemin ederler. Ve gerçekten bir şey üzerinde olduklarını sanırlar. İyi bilin ki; onlar, gerçekten yalancılardır."},{"n":19,"t":"Şeytan onlara baskın gelip Allah’ı anmayı unutturmuştur. İşte onlar, şeytanın taraftarlarıdır. İyi bilin ki; şeytanın taraftarları muhakkak hüsrana uğrayanların kendileridir."},{"n":20,"t":"Allah’a ve Peygamberine muhalefet edenler; işte onlar, en çok zillete düşenlerle beraberdirler."},{"n":21,"t":"Allah: Andolsun ki Ben ve Peygamberlerim elbette galip geleceğiz, diye yazmıştır. Muhakkak ki Allah; Kavi’dir, Aziz’dir."},{"n":22,"t":"Allah’a ve ahiret gününe iman eden bir kavmin; kendi babaları, oğulları, kardeşleri veya akrabaları da olsa Allah ve Peygamberine muhalefet eden kimselere sevgi beslediğini göremezsin. İşte onların kalbine Allah, iman yazmış ve katından bir ruh ile onları desteklemiştir. Onları altlarından ırmaklar akan cennetlere sokacaktır. Bunlar orada ebediyyen kalacaklardır. Allah; onlardan razı olmuştur, onlar da Allah’tan hoşnud olmuşlardır. İşte onlar; Allah’ın hizbidir. Dikkat edin; Allah’ın hizbi, felaha erenlerin kendileridir."}],[{"n":1,"t":"Göklerde olanlar da, yerde olanlar da Allah’ı tesbih eder. Ve O; Aziz’ dir, Hakim’dir."},{"n":2,"t":"O’dur Ehl-i Kitab’tan küfretmiş olanları ilk sürgünde yurtlarından çıkarmış olan. Halbuki siz, onların çıkacaklarını sanmıştınız. Onlar da kalelerinin kendilerini Allah’tan koruyacağını sanmışlardı. Fakat Allah’ ın azabı onlara hesablamadıkları yerden geldi. Ve kalblerine korku saldı. Kendi elleriyle ve inananların elleriyle evlerini yıkıyorlardı. Ey basiret sahipleri ibret alın."},{"n":3,"t":"Şayet Allah, onlara sürülmeyi yazmamış olsaydı, dünyada onları azablandıracaktı ve onlar için ahirette de ateş azabı vardır."},{"n":4,"t":"Bu; onların Allah’a ve Rasulüne karşı gelmelerinden ötürüdür. Her kim Allah’a karşı gelirse; muhakkak ki Allah, azabı şiddetli olandır."},{"n":5,"t":"Herhangi bir hurma ağacını kesmeniz veya kesmeyip gövdeleri üzerinde bırakmanız hep Allah’ın izniyledir. Bir de fasıkları rüsvay etmek içindir."},{"n":6,"t":"Allah’ın peygamberine verdiği fey’e gelince; siz onun için ne bir at, ne de bir deve sürdünüz. Fakat Allah; peygamberine, dilediği kimselere karşı üstünlük verir. Allah; her şeye kadirdir."},{"n":7,"t":"Kasabalar halkından, Allah’ın Rasulüne fey’ olarak verdiği; Allah, peygamber, akrabalar, yetimler, yoksullar ve yolda kalanlar içindir. Ta ki içinizden zenginler arasında elden ele dolaşan bir devlet olmasın. Peygamber, size ne verirse onu alın, neden de nehyederse ondan sakının. Ve Allah’tan korkun. Muhakkak ki Allah; azabı şiddetli olandır."},{"n":8,"t":"Yurtlarından ve mallarından çıkarılmış olan, Allah’tan bir lutuf ve rıza dileyen, Allah’ın dinine ve peygamberine yardım eden fakir muhacirler içindir. İşte bunlar, sadıkların kendileridir."},{"n":9,"t":"Onlardan önce o diyarı yurt edinmiş ve göğüslerine imanı yerleştirmiş olanlar; kendilerine hicret edip gelenleri severler. Ve onlara verilenlerden ötürü içlerinde bir çekememezlik duymazlar. Kendileri zaruret içinde bulunsalar bile onları, kendilerine tercih ederler. Her kim nefsinin tamahkarlığından korunabilmişse; işte onlar, felaha erenlerin kendileridir."},{"n":10,"t":"Onlardan sonra gelenler ise derler ki: Rabbımız, bizi ve bizden önce iman etmiş olan kardeşlerimizi bağışla. Ve iman etmiş olanlar için kalblerimizde kin bırakma. Rabbımız, muhakkak ki Sen; Rauf’sun, Rahim’sin."},{"n":11,"t":"Münafıklık etmiş olanlara bakmadın mı ki; Ehl-i Kitab’dan küfretmiş olan kardeşlerine: Eğer siz çıkarılırsanız andolsun ki; biz de sizinle beraber çıkarız. Ve sizin aleyhinizde asla kimseler itaat etmeyiz. Eğer savaşa tutuşursanız; muhakkak size yardım ederiz, derler. Allah şehadet eder ki; onlar yalancıdırlar."},{"n":12,"t":"Andolsun ki; eğer onlar çıkarılsalar; onlarla beraber çıkmazlar. Eğer onlara savaş açılırsa; yardım etmezler. Yardıma gitseler bile; mutlaka gerisin geri dönerler. Sonra da kendileri yardım görmezler."},{"n":13,"t":"Doğrusu onların kalbine korku salan; Allah’tan çok, sizlersiniz. Çünkü onlar anlamazlar güruhudur."},{"n":14,"t":"Onlar, sizinle topluca savaşı; ancak surla çevrilmiş kasabalarda veya duvarlar arasında kabul ederler. Kendi aralarındaki çekişmeleri şiddetlidir. Sen, onları toplu sanırsın, ama kalbleri darmadağınıktır. Bu; onların akletmez bir kavim olmalarındandır."},{"n":15,"t":"Kendilerinden az önce geçmiş ve işlerin vebalini tatmış olanların durumu gibidir. Onlar için elim bir azab vardır."},{"n":16,"t":"Şeytanın durumu gibi; hani o, insana; küfret, deyip de küfredince; doğrusu ben senden uzağım, çünkü ben; alemlerin Rabbı Allah’tan korkarım, demişti."},{"n":17,"t":"Nihayet ikisinin de akıbeti; içinde ebediyyen kalacakları ateştir. İşte zalimlerin cezası budur."},{"n":18,"t":"Ey iman edenler; Allah’tan korkun. Ve herkes, yarın için ne hazırladığına bir baksın. Allah’tan korkun, şüphesiz ki Allah; işlediklerinizden haberdardır."},{"n":19,"t":"Allah’ı unutanlar gibi olmayın. Nefisleri O’nu kendilerine unutturmuştur. İşte onlar, fasıklardır."},{"n":20,"t":"Cehennem ashabı ile cennet ashabı bir değildir. Cennet ashabı; işte onlardır kurtuluşa erenler."},{"n":21,"t":"Şayet Biz, bu Kur’an’ı bir dağa indirmiş olsaydık; sen, onun Allah’ın haşyetinden baş eğerek parça parça olduğunu görürdün. İşte Biz, bu misalleri insanlara anlatırız, belki düşünürler."},{"n":22,"t":"O, öyle Allah’tır ki; O’ndan başka ilah yoktur. Görülmeyeni ve görüleni bilendir. O, Rahman’dır, Rahim’dir."},{"n":23,"t":"O, öyle Allah’tır ki; O’ndan başka ilah yoktur. Melik, Kuddüs, Selam, Mü’min, Müheymin, Aziz, Cebbar, Mütekebbir’dir. Allah, onların koştukları eşlerden münezzehtir."},{"n":24,"t":"O, öyle Allah’tır ki; Halik, Bari, Musavvir’dir. En güzel isimler O’nundur. Göklerde ve yerde olanlar O’nu tesbih ederler. Ve O; Aziz’dir, Hakim’ dir."}],[{"n":1,"t":"Ey iman edenler; benim de düşmanım, sizin de düşmanınız olanları dost edinmeyin. Onlar, size gelen gerçeği inkar etmişken onlara sevgi gösteriyorsunuz. Halbuki onlar; Rabbınız olan Allah’a inandığınızdan dolayı sizi ve peygamberi yurdunuzdan çıkarıyorlar. Eğer siz, benim yolumda savaşmak ve hoşnudluğumu kazanmak için çıkmışsanız; onlara nasıl sevgi gösterirsiniz? Oysa Ben, sizin gizlediğinizi de, açığa vurduğunuzu da bilirim. İçinizden kim bunu yaparsa; şüphesiz ki doğru yoldan sapmış olur."},{"n":2,"t":"Şayet onlar, sizi ele geçirirlerse; size düşman kesilirler. Kötülükle ellerini ve dillerini uzatırlar. Ve sizin kafir olmanızı isterler."},{"n":3,"t":"Yakınlarınız ve çocuklarınız size asla fayda veremezler. Allah, kıyamet günü onlarla sizin aranızı ayırır. Ve Allah; işlediklerinizi görendir."},{"n":4,"t":"İbrahim’de ve onun beraberinde olanlarda sizin için gerçekten güzel bir örnek vardı. Hani onlar, kavimlerine demişlerdi ki: Biz, sizden ve Allah’ ı bırakıp taptığınız başka şeylerden uzağız. Sizi inkar ediyoruz. Yalnız Allah’a inanıncaya kadar bizimle sizin aranızda ebedi düşmanlık ve öfke belirmiştir. Yalnız İbrahim’in babasına; andolsun ki, senin için mağfiret dileyeceğim. Ama Allah’tan sana gelecek herhangi birşeyi def’etmeye gücüm yetmez, demesi müstesna. Ey Rabbımız; Sana tevekkül ettik ve Sana yöneldik. Dönüş de ancak Sana’dır."},{"n":5,"t":"Ey Rabbımız; bizi, o küfredenler için bir fitne kılma. Bağışla bizi. Ey Rabbımız; doğrusu Aziz, Hakim olan Sensin Sen."},{"n":6,"t":"Andolsun ki; sizlerden, Allah’ı ve ahiret gününü umanlar için onlarda güzel bir örnek vardır. Kim de yüz çevirirse, muhakkak ki Allah; Gani’ dir, Hamid’dir."},{"n":7,"t":"Olur ki Allah; sizinle, onlardan düşman olduğunuz kimseler arasında yakında bir dostluk peyda eder. Allah; Kadir’dir. Ve Allah; Gafur’dur, Rahim’dir."},{"n":8,"t":"Sizinle din uğrunda savaşmayan, sizi yurdunuzdan çıkarmayanlara iyilik yapmanızı ve adil davranmanızı Allah yasaklamaz. Doğrusu Allah; adil olanları sever."},{"n":9,"t":"Allah; sadece sizinle din uğrunda savaşanları, sizi yurtlarınızdan çıkaranları ve çıkarılmanıza yardım edenleri dost edinmenizi yasaklar. Kim onları dost edinirse; işte onlar, zalimlerin kendileridir."},{"n":10,"t":"Ey iman edenler; inanan kadınlar hicret ederek size gelirlerse, onları imtihan edin. Allah, onların imanlarını daha iyi bilir. Fakat siz de onların inanmış kadınlar olduklarını öğrenirseniz; artık onları kafirlere geri göndermeyin. Bunlar onlara helal değildir, onlar da bunlara helal olmazlar. Onların sarfettiklerini kendilerine geri verin. Mehirlerini verdiğiniz zaman onlarla evlenmenizde bir vebal yoktur. Kafir kadınları nikahınızda tutmayın, sarfettiğinizi isteyin. Onlar da sarfettiklerini istesinler. Allah’ın hükmü budur. Aranızda O hükmeder. Ve Allah; Alim’ dir, Hakim’dir."},{"n":11,"t":"Eğer eşlerinizden kafirlere bir şey geçecek olursa ve siz de galib durumda bulunursanız; eşleri gidenlere sarfettikleri kadarını verin. İnandığınız Allah’tan sakının."},{"n":12,"t":"Ey Peygamber; inanmış kadınlar; Allah’a hiç bir şeyi ortak koşmamak, hırsızlık yapmamak, zina etmemek, çocuklarını öldürmemek, elleriyle ayakları arasından bir iftira düzüp getirmemek, ma’rufu işlemekte sana karşı gelmemek üzere biat etmeye geldikleri zaman, biatlarını kabul et. Ve onlar için Allah’tan mağfiret dile. Muhakkak ki Allah; Gafur’dur, Rahim’dir."},{"n":13,"t":"Ey iman edenler; Allah’ın kendilerine gazab ettiği bir kavim ile dost olmayın. Kafirlerin kabirdekilerden ümidlerini kestikleri gibi, onlar da ahiretten ümidlerini kesmişlerdir."}],[{"n":1,"t":"Göklerde ne var, yerde ne varsa; Allah’ı tesbih eder. Ve O; Aziz’dir, Hakim’dir."},{"n":2,"t":"Ey iman edenler; yapmayacağınız şeyi niçin söylersiniz?"},{"n":3,"t":"Yapmayacağınızı söylemeniz; Allah katında büyük bir gazaba sebep olur."},{"n":4,"t":"Muhakkak ki Allah; kendi uğrunda kenetlenmiş bir duvar gibi saf halinde savaşanları sever."},{"n":5,"t":"Hani Musa, kavmine demişti ki: Ey kavmim, niçin bana eziyet verirsiniz? Halbuki benim size gerçekten Allah’ın rasulü olduğumu biliyorsunuz. Fakat onlar yoldan sapınca; Allah da onların kalblerini saptırmıştı. Ve Allah; fasıklar güruhunu hidayete erdirmez."},{"n":6,"t":"Hani Meryem oğlu İsa da demişti ki: Ey İsrailoğulları; muhakkak ki ben, size Allah’ın peygamberiyim. Benden önceki Tevrat’ı doğrulayan ve benden sonra gelecek, adı Ahmed olacak bir peygamberi de müjdeleyenim. Ama o, kendilerine açık burhanlarla gelince; bu, apaçık bir büyüdür, dediler."},{"n":7,"t":"İslama çağrıldığı halde. Allah’a karşı yalan uydurandan daha zalim kimdir? Allah; zalimler güruhunu hidayete erdirmez."},{"n":8,"t":"Onlar, Allah’ın nurunu ağızlarıyla söndürmek isterler. Halbuki kafirler istemeseler de; Allah, nurunu tamamlayacaktır."},{"n":9,"t":"Müşrikler istemeseler de; dinini bütün dinlere üstün kılmak için peygamberlerini hidayet ve hak din ile gönderen O’dur."},{"n":10,"t":"Ey iman edenler; sizi, elim azabtan kurtaracak bir ticareti göstereyim mi size?"},{"n":11,"t":"Allah’a ve peygamberine iman eder, mallarınızla ve canlarınızla Allah yolunda cihad ederseniz. Eğer bilirseniz; bu sizin için çok daha hayırlıdır."},{"n":12,"t":"O; sizin günahlarınızı bağışlar, sizi altlarından ırmaklar akan cennetlere ve Adn cennetlerindeki güzel yerlere koyar. İşte en büyük kurtuluş budur."},{"n":13,"t":"Seveceğiniz başka bir şey daha var; Allah katında yardım ve yakın bir fetih ve mü’minleri müjdele."},{"n":14,"t":"Ey iman edenler; siz Allah’ın yardımcıları olun. Nitekim Meryem oğlu İsa, havarilere: Allah’a giden yolda benim yardımcılarım kimlerdir? deyince, havariler demişlerdi ki: Biziz, Allah’ın yardımcıları. İsrailoğullarının bir takımı böylece inanmış, bir takımı da küfretmişti. Nihayet Biz, o iman edenleri düşmanlarına karşı destekledik de böylece üstün geldiler."}],[{"n":1,"t":"Göklerde ne var, yerde ne varsa; hepsi Melik, Kuddüs, Aziz, Hakim’i tesbih eder."},{"n":2,"t":"Ümmiler arasından, kendilerine O’nun ayetlerini okuyan, onları temizleyen ve onlara kitabı ve hikmeti öğreten bir peygamber gönderen O’dur. Halbuki onlar; daha önceleri gerçekten apaçık bir sapıklık içindeydiler."},{"n":3,"t":"Onlardan başkalarına da. Ki henüz onlara katılmamışlardır. Ve O; Aziz’ dir, Hakim’dir."},{"n":4,"t":"Bu, Allah’ın lutfudur. Onu dilediğine verir. Ve Allah; büyük lutuf sahibidir."},{"n":5,"t":"Kendilerine Tevrat yükletildiği halde onu taşıyamayanların misali; koca koca kitablar taşıyan eşeğin misalidir. Allah’ın ayetlerini yalanlamış olan kavmin durumu ne de kötüdür. Ve Allah; zalimler güruhunu hidayete erdirmez."},{"n":6,"t":"De ki: Ey yahudiler; bütün insanları bir yana bırakarak yalnız kendinizin mi Allah’ın dostları olduğunu iddia ediyorsunuz? Öyleyse bunda samimi iseniz ölümü temenni edin."},{"n":7,"t":"Yaptıklarından dolayı ölümü katiyyen temenni edemezler. Allah; zalimleri bilendir."},{"n":8,"t":"De ki: Gerçekten sizin kaçıp durduğunuz ölüme muhakkak yakalanacaksınız. Sonra da görüleni ve görülmeyeni bilene döndürüleceksiniz. O; size neler yaptığınızı haber verecektir."},{"n":9,"t":"Ey iman edenler; cum’a günü namaz için çağrıldığınız vakit, hemen Allah’ ın zikrine koşun ve alış-verişi bırakın. Bilirseniz bu, sizin için daha hayırlıdır."},{"n":10,"t":"Namaz bitince; yeryüzüne dağılın. Ve Allah’ın lutfundan isteyin. Allah’ı çok zikredin ki felaha eresiniz."},{"n":11,"t":"Onlar bir tidaret veya bir oyun gördükleri zaman; seni ayakta bırakarak oraya yöneldiler. De ki: Allah’ın katında olan; oyun ve ticaretten daha hayırlıdır. Ve Allah; rızık verenlerin en hayırlısıdır."}],[{"n":1,"t":"Münafıklar sana geldiklerinde: Şehadet ederiz ki muhakkak sen, Allah’ın peygamberisin, derler. Allah da bilir ki; sen, elbette kendisinin peygamberisin. Allah; münafıkların şüphesiz yalancılar olduklarına şehadet eder."},{"n":2,"t":"Onlar; yeminlerini kalkan edindiler de Allah’ın yolundan alıkoydular. Gerçekten yaptıkları işler ne kötüdür."},{"n":3,"t":"Bu, önce iman edip sonra küfretmiş olmalarındandır. Bunun üzerine kalbleri mühürlenmiştir, artık hiç anlamazlar."},{"n":4,"t":"Onlara baktığında; gövdeleri hoşuna gider, konuşurlarsa; sözlerini dinlersin. Onlar giydirilmiş odunlar gibidir. Her gürültüyü kendi aleyhlerinde sanırlar. Düşman onlardır, sakın onlardan. Allah, canlarını alsın. Nasıl olup da döndürülüyorlar."},{"n":5,"t":"Onlara; gelin, Allah’ın peygamberi sizin için mağfiret dilesin, denildiği zaman; başlarını çevirdiler. Ve sen, onların büyüklük taslayarak yüz çevirdiklerini görürsün."},{"n":6,"t":"Onlar için mağfiret dilesen de, mağfiret dilemesen de birdir. Allah, onları katiyyen bağışlamayacaktır. Muhakkak ki Allah; fasıklar güruhunu hidayete erdirmez"},{"n":7,"t":"Onlar öyle kimselerdir ki; Allah’ın peygamberinin yanında bulunanlar için hiç bir şey infak etmeyin de dağılıp gitsinler, derler. Halbuki göklerin ve yerin hazineleri Allah’ındır. Ama o münafıklar, bunu anlamazlar."},{"n":8,"t":"Onlar; şayet Medine’ye dönersen, andolsun ki; şerefli ve kuvvetli olanlar, zayıf olanları oradan muhakkak çıkaracaktır, diyorlardı. Oysa izzet Allah’ ın, Peygamberinin ve mü’minlerindir. Fakat münafıklar, bunu bilmezler."},{"n":9,"t":"Ey iman edenler; mallarınız ve çocuklarınız, sizi Allah’ı anmaktan alıkoymasın. Kim bunu yaparsa; onlar, hüsrana uğrayanların kendileridir."},{"n":10,"t":"Birinize ölüm gelip de; Rabbım, beni yakın bir süreye kadar geciktirsen de sadaka versem ve salihlerden olsam, diyeceği zaman gelmezden evvel, size rızık olarak verdiğimizden infak edin."},{"n":11,"t":"Eceli gelince Allah; hiç bir nefsi asla geri bırakmaz. Ve Allah; işlediklerinizden haberdardır."}],[{"n":1,"t":"Göklerde ne var, yerde ne varsa; hepsi Allah’ı tesbih ederler. Mülk O’ nundur, hamd O’na mahsustur. Ve O; her şeye kadirdir."},{"n":2,"t":"Sizi yaratan O’dur. Böyle iken kiminiz kafir, kiminiz de mü’mindir. Allah; yaptıklarınızı görür."},{"n":3,"t":"Gökleri ve yeri hak ile yaratmıştır. Size suret verip suretlerinizi en güzel şekilde yapmıştır. Dönüş, ancak O’nadır."},{"n":4,"t":"Göklerde ve yerde olanları bilir. Gizlediklerinizi ve açığa vurduklarınızı da bilir. Ve Allah; göğüslerin özünü bilendir."},{"n":5,"t":"Daha önce küfredip de yaptıklarının karşılığını tadanların haberi size gelmedi mi? Ve onlara elim bir azab vardır."},{"n":6,"t":"Bunun sebebi şudur: Peygamberleri onlara apaçık deliller getiriyorlardı da onlar; bizi bir beşer mi doğru yola götürecekmiş? diyerek küfredip yüz çevirmişlerdi. Allah ise hiç bir şeye muhtaç olmadığını göstermişti. Allah; Gani’dir, Hamid’dir."},{"n":7,"t":"Küfredenler; öldükten sonra katiyyen diriltilemeyeceklerini ileri sürdüler. De ki: Evet, Rabbıma andolsun ki; muhakkak diriltileceksiniz ve sonra yaptıklarınız size bildirilecektir. Ve bu, Allah’a göre pek kolaydır."},{"n":8,"t":"Şu halde Allah’a, peygamberine ve indirdiğimiz nura iman edin. Allah yaptıklarınızdan haberdardır."},{"n":9,"t":"Sizi toplanma günü için topladığı gün; işte o gün, kimin aldandığının açığa çıkacağı gündür. Kim, Allah’a inanır ve salih amel işlerse; Allah onun kötülüklerini örter ve onu, altından ırmaklar akan, içinde ebediyyen kalacakları cennetlere sokar. İşte büyük kurtuluş budur."},{"n":10,"t":"Küfredip de ayetlerimizi yalanlayanlara gelince; işte onlar, cehennem ashabıdırlar. Orada ebediyyen kalacaklardır. Ne kötü dönüş yeridir."},{"n":11,"t":"Allah’ın izni olmadıkça hiç bir musibet isabet etmez. Kim de Allah’a inanırsa; onun kalbini doğruya götürür. Ve Allah; her şeyi bilendir."},{"n":12,"t":"Allah’a itaat edin, peygambere itaat edin. Şayet yüz çevirecek olursanız; bilin ki peygamberimize düşen, apaçık tebliğdir."},{"n":13,"t":"Allah O’durki; O’ndan başka hiç bir ilah yoktur. Ve mü’minler, yalnız Allah’a tevekkül etsinler."},{"n":14,"t":"Ey iman etmiş olanlar; eşlerinizin ve çocuklarınızın içinde size düşmanlık edenler vardır. Onlardan sakının. Ama affeder, kusurlarını başlarına kakmaz ve örterseniz; şüphesiz ki Allah; Gafur’dur, Rahim’dir."},{"n":15,"t":"Doğrusu mallarınız ve çocuklarınız sizin için bir imtihandır. Allah katında ise büyük bir mükafat vardır."},{"n":16,"t":"Öyleyse, gücünüz yettiğince Allah’tan korkun. Dinleyin, itaat edin ve kendinizin hayrına olarak infak edin. Kim de nefsinin cimriliğinden korunursa; işte onlar, felaha erenlerin kendileridir."},{"n":17,"t":"Eğer Allah’a güzel bir ödünçle ödünç verirseniz; onu sizin için katkat arttırır ve sizi bağışlar. Allah; Şekur’dur, Halim’dir."},{"n":18,"t":"Görüleni ve görülmeyeni bilendir. Aziz’dir, Hakim’dir."}],[{"n":1,"t":"Ey Peygamber; kadınları boşayacağınız zaman, onları iddetleri içinde boşayın. İddeti de sayın. Rabbınız olan Allah’tan korkun. Apaçık bir hayasızlık yapmaları hali bir yana, onları evlerinden çıkarmayın, kendileri de çıkmasınlar. Bunlar Allah’ın hudududur. Kim, Allah’ın hududunu aşarsa; şüphesiz kendine zulmetmiş olur. Bilmezsin belki Allah, bunun ardından bir durum peyda ediverir."},{"n":2,"t":"Sürelerini doldurdukları vakit; onları; ya ma’ruf ile tutun veya onlardan ma’ruf ile ayrılın. İçinizden adalet sahibi iki kişiyi de şahid tutun. Şahidliği, Allah için yapın. İşte bu, Allah’a ve ahiret gününe iman etmekte olanlara verilen öğüttür. Kim, Allah’tan korkarsa; ona bir çıkış yolu ihsan eder."},{"n":3,"t":"Ve ona beklemediği yerden rızık verir. Kim, Allah’a tevekkül ederse; O, kendisine yeter. Şüphesiz ki Allah; emrini yerine getirendir. Gerçekten Allah; her şey için bir ölçü var etmiştir."},{"n":4,"t":"Kadınlarınızdan adetten kesilmiş olanların iddeti eğer şüphe edersenizüç aydır. Henüz adet görmemiş olanlar da böyle. Gebe kadınların süresi ise; yüklerini vaz’etmeleridir. Kim, Allah’tan korkarsa; O, işinde bir kolaylık halkeder."},{"n":5,"t":"Bu, Allah’ın emridir. Onu size indirmiştir. Kim, Allah’tan korkarsa; onun kusurlarını örter ve ecrini büyütür."},{"n":6,"t":"Onları, gücünüzün yettiği kadar ikamet ettiğiniz yerin bir kısmında oturtun. Onları, sıkıntıya sokmak için zarar vermeye kalkışmayın. Eğer hamile iseler, yüklerini koyuncaya kadar nafakalarını verin. Sizin için emzirirlerse; onlara, ücretlerini verin. Aranızda uygun bir şekilde anlaşın. Eğer güçlüğe uğrarsanız; çocuğu bir başka kadın emzirir."},{"n":7,"t":"Eli geniş olan; genişliğine göre nafaka versin. Rızkı kendisine daraltılmış bulunan da, nafakayı Allah’ın kendisine verdiğinden versin. Allah kimseyi, kendisine verdiğinden fazlasıyla yükümlü tutmaz. Allah; güçlüğün ardından bir kolaylık ihsan eder."},{"n":8,"t":"Rabbının ve onun peygamberlerinin emrinden uzaklaşıp azmış nice kasabalar halkı vardır ki; Biz onları şiddetli bir hesaba çekmiş ve görülmemiş azaba çarptırmışızdır."},{"n":9,"t":"Onlar, yaptıklarının karşılığını tatmışlardır. İşlerinin sonu ise hüsran olmuştur"},{"n":10,"t":"Allah, onlar için şiddetli bir azab hazırlamıştır. Ey iman eden akıl sahipleri, Allah’tan korkun. Allah; size gerçekten bir zikir indirmiştir."},{"n":11,"t":"İman edip salih amel işleyenleri karanlıklardan aydınlığa çıkarmak için, size Allah’ın apaçık bildiren ayetlerini okuyan bir peygamber gönderdi. Kim Allah’a inanır ve salih amel işlerse; onu, altlarından ırmaklar akan cennetlere girdirir, orada ebediyyen kalırlar. Allah; ona, gerçekten güzel bir rızık vermiştir."},{"n":12,"t":"Allah; yedi göğü ve yerden de o kadarını yaratmış olandır. Allah’ın buyruğu bunlar arasında iner durur. Ki, Allah’ın gerçekten her şeye kadir olduğunu ve Allah’ın gerçekten her şeyi ilmiyle kuşatmış oşduğunu bilesiniz."}],[{"n":1,"t":"Ey Peygamber; eşlerinin hoşnudluğunu gözeterek Allah’ın sana helal kıldığı şeyi niçin kendine haram ediyorsun? Allah; Gafur’dur, Rahim’dir."},{"n":2,"t":"Allah; yeminlerinizin çözülmesini size meşru kılmıştır. Allah sizin mevlanızdır. Ve O; Alim’dir, Hakim’dir."},{"n":3,"t":"Hani Peygamber; eşlerinden birine, gizlice bir söz söylemişti. O, bunu haber verdi de Allah da bunu ona açıklayınca; bir kısmını bildirmiş, bir kısmından da vazgeçmişti. Artık bunu kendisine söyleyince; eşi: Bunu sana kim bildirdi? demişti. Bana her şeyi bilen, her şeyden haberdar olan Allah haber verdi, demişti."},{"n":4,"t":"Eğer her ikiniz de Allah’a tevbe ederseniz; gerçekten kaymış olan kalbleriniz düzelmiş olur. Şayet ona karşı birbirinize destek olmaya kalkışırsanız; hiç şüphesiz Allah, onun mevlasıdır. Cebrail de, mü’minlerin salih olanı da, bunun ardından bütün melekler de ona yardımcıdırlar."},{"n":5,"t":"Şayet o, sizi boşarsa; Rabbı ona sizden daha hayırlı, kendini Allah’a veren, inanan, boyun eğen, tevbe eden, kulluk eden, oruç tutan dul ve bakire eşler verir."},{"n":6,"t":"Ey iman edenler; kendinizi ve çoluk çocuğunuzu, yakacağı insanlar ve taşlar olan ateşten koruyun. Onun üzerinde iri gövdeli, haşin tabiatlı melekler vardır. Ki onlar; Allah’ın kendilerine emrettiğine katiyyen isyan etmezler. Ve emrolunduklarını yaparlar."},{"n":7,"t":"Ey küfredenler; bugün, özür dilemeyin. Siz, ancak işlediklerinizin karşılığını görmektesiniz."},{"n":8,"t":"Ey iman edenler; Allah’a nasuh tevbesi ile tevbe edin. Umulur ki Rabbınız kötülüklerinizi örter ve sizi altlarından ırmaklar akan cennetlere koyar. O gün, Allah; peygamberini ve onunla beraber olan mü’minleri utandırmayacak. Onların nurları önlerinde ve sağlarında koşacak; Rabbımız, ışığımızı tamamla, bizi bağışla. Şüphesiz ki Sen, her şeye kadirsin, diyecekler."},{"n":9,"t":"Ey peygamber; kafirler ve münafıklarla savaş, onlara karşı çetin ol. Onların varacağı yer cehennemdir. O, ne kötü dönüş yeridir."},{"n":10,"t":"Allah; küfredenlere Nuh’un karısıyla Lut’un karısını misal verdi. Onlar, kullarımızdan iki salih kulun nikahında iken hainlik ettiler de, onları Allah’tan hiç bir şeyle kurtaramadılar. O iki kadına; ateşe girenlerle beraber siz de girin, denildi."},{"n":11,"t":"Allah; iman edenlere de, Firavun’un karısını misal gösterdi. O; Rabbım, bana katında, cennette bir ev yap, beni Firavun’dan ve onun yaptıklarından kurtar ve beni zalimler güruhundan kurtar, demişti."},{"n":12,"t":"Mahrem yerini korumuş olan İmran kızı Meryem’i de. Ona ruhumuzdan üflemiştik de Rabbının sözlerini ve kitablarını tasdik etmişti. Ve o, gönülden itaat edenlerdendi."}],[{"n":1,"t":"Şanı yücedir, bütün mülk elinde olanın. Ve O; her şeye kadirdir."},{"n":2,"t":"Hanginizin daha iyi amel işlediğini denemek için ölümü ve hayatı yaratan O’dur. Ve O; Aziz’dir, Gafur’dur."},{"n":3,"t":"O ki; yedi göğü kat kat yaratmıştır. Sen Rahman’ın yaratmasında bir düzensizlik bulamazsın. Gözünü çevir de bak, bir aksaklık görebilir misin?"},{"n":4,"t":"Sonra gözünü iki kere daha çevir; göz umduğunu bulamayıp bitkin ve yorgun sana dönecektir."},{"n":5,"t":"Andolsun ki; Biz, yere en yakın göğü kandillerle donattık. Onlarla şeytanların taşlanmasını sağladık. Ve onlara, çılgın alevli azabı hazırladık."},{"n":6,"t":"Rabblarına küfredenler için de cehennem azabı vardır. Ne kötü dönüş yeridir."},{"n":7,"t":"Oraya atıldıklarında; onun kaynarken çıkardığı uğultuyu işitirler."},{"n":8,"t":"Nerede ise öfkesinden çatlayacak gibi olur. Her bir topluluk ona atıldığında, bekçileri onlara sorarlar: Size bir uyarıcı gelmedi mi?"},{"n":9,"t":"Onlar: Evet, doğrusu bize bir uyarıcı geldi, ama biz yalanladık ve: Allah, hiç bir şey indirmemiştir. Siz, büyük bir sapıklık içindesiniz, dedik, derler."},{"n":10,"t":"Eğer kulak vermiş veya akletmiş olsaydık, bu çılgın alevli ateş halkı arasında bulunmazdık, derler."},{"n":11,"t":"Böylece günahlarını itiraf ettiler. Yok olsun çılgın alevli cehennem ashabı."},{"n":12,"t":"Muhakkak ki gayb ile Rabblarından korkanlar, işte onlar için, mağfiret ve büyük mükafat vardır."},{"n":13,"t":"Sözünüzü ister gizleyin, ister açığa vurun; muhakkak ki O, göğüslerin özünü bilendir."},{"n":14,"t":"Yaratan bilmez olur mu hiç? Ve O; Latif’tir, Habir’dir."},{"n":15,"t":"Size yeryüzünü boyun eğdiren O’dur. O halde onun sırtlarında yürüyün. O’ nun rızkından yiyin, nihayet dönüş O’nadır."},{"n":16,"t":"Gökte olanın; sizi yerin dibine geçirmesinden emin mi oldunuz? O zaman yer, sarsıldıkça sarsılır."},{"n":17,"t":"Yoksa gökte olanın; başınıza taş göndermesinden emin mi oldunuz? Benim tehdidimin nasıl olduğunu yakında bileceksiniz."},{"n":18,"t":"Andolsun ki; onlardan öncekiler de yalanlamışlardı. Beni inkar nasılmış?"},{"n":19,"t":"Onlar; üzerlerinde kanat çırpan sıra sıra kuşları görmezler mi? Onları Rahman’dan başkası tutmuyor. Muhakkak ki O; her şeyi görendir."},{"n":20,"t":"Rahman’dan başka size yardımda bulunacak ordunuz kimdir? Kafirler sadece gurur içindedirler."},{"n":21,"t":"Eğer O; rızkınızı tutup kesiverecek olursa, size rızık verecek kimdir? Hayır, onlar; azgınlık ve nefret içinde direnip durmaktadırlar."},{"n":22,"t":"Yüzükoyun sürünen mi daha çok hidayettedir, yoksa doğru yolda düpedüz yürüyen mi?"},{"n":23,"t":"De ki: Sizi yaratan ve sizler için kulaklar, gözler ve kalbler var eden O’dur. Ne de az şükrediyorsunuz."},{"n":24,"t":"De ki: Sizi yeryüzünde yaratıp yayan O’dur. Ve O’na toplanıp götürüleceksiniz."},{"n":25,"t":"Derler ki: Doğru sözlüler iseniz, bildirin ne zamandır bu vaad?"},{"n":26,"t":"De ki: Bilgi; ancak Allah katındadır. Ve ben sadece apaçık bir uyarıcıyım."},{"n":27,"t":"Onu yaklaşırken gördükleri vakit, küfredenlerin yüzleri buruştu. Ve: Sizin isteyip durduğunuz işte budur, denildi."},{"n":28,"t":"De ki: Beni ve benimle beraber bulunanları, Allah helak eder veya esirgerse; kafirleri, elim bir azabdan kurtaracak olan kimdir?"},{"n":29,"t":"De ki: O, Rahman’dır. Biz, O’na inandık ve O’na tevekkül ettik. Kimin apaçık bir sapıklıkta olduğunu yakında bileceksiniz."},{"n":30,"t":"De ki: Eğer suyunuz yerin dibine batarsa, söyleyin; size kim temiz bir su kaynağı getirebilir?"}],[{"n":1,"t":"Nun. Kaleme ve onunla yazılanlara andolsun ki;"},{"n":2,"t":"Sen, nimeti sayesinde bir deli değilsin."},{"n":3,"t":"Doğrusu senin için tükenmeyen bir mükafat vardır."},{"n":4,"t":"Muhakkak ki sen; büyük bir ahlak üzerindesin"},{"n":5,"t":"Yakında sen de göreceksin, onlar da görecekler;"},{"n":6,"t":"Hanginizin aklından zoru olduğunu."},{"n":7,"t":"Muhakkak ki senin Rabbın; kendi yolundan sapanları çok iyi bilir. Ve O, hidayete erevleri de en iyi bilendir."},{"n":8,"t":"Öyleyse sen; yalanlayanlara uyma."},{"n":9,"t":"Onlar isterler ki; sen yumuşak davranasın da kendileri de yumuşaklık göstersinler."},{"n":10,"t":"Sen; yemin edip duran, izzet-i nefsi bulunmayana uyma."},{"n":11,"t":"Daima ayıplayan ve laf getirip götürene."},{"n":12,"t":"Durmadan hayra engel olana, haddi aşana, çok günahkara."},{"n":13,"t":"Kaba, haşin ve bunlardan başka da kulağı kesik olana,"},{"n":14,"t":"Mal ve oğullar sahibi olmuş diye."},{"n":15,"t":"Ayetlerimiz ona okunduğu zaman; öncekilerin masalları, der."},{"n":16,"t":"Biz, onun burnunu yakında yere sürteceğiz."},{"n":17,"t":"Biz; vaktiyle o bahçe sahiplerini denediğimiz gibi bunları da denedik. Hani sabah olunca; onu mutlaka devşireceklerine ve biçeceklerine yemin etmişlerdi."},{"n":18,"t":"Bir istisna da yapmıyorlardı."},{"n":19,"t":"Ama onlar, daha uykuda iken; Rabbının katından gönderilen bir salgın onu sardı da,"},{"n":20,"t":"O, kupkuru kesildi."},{"n":21,"t":"Sabah erken birbirlerine seslendiler;"},{"n":22,"t":"Mahsullerinizi devşirecekseniz erkence çıkın, diye."},{"n":23,"t":"Ve gizli gizli konuşarak yürüyorlardı."},{"n":24,"t":"Sakın bugün hiç bir yoksul çıkmasın karşınıza ve oraya girmesin, diye."},{"n":25,"t":"Güçleri yetermiş gibi erkenden gittiler."},{"n":26,"t":"Onu gördüklerinde dediler ki: Herhalde biz yanlış geldik."},{"n":27,"t":"Hayır, belki de biz mahrum bırakıldık."},{"n":28,"t":"Ortancaları dedi ki: Ben size demedim mi? Tesbih etmeli değil miydiniz?"},{"n":29,"t":"Dediler ki: Tesbih ederiz Seni Rabbımız, gerçekten biz, zalimlerden olmuşuz."},{"n":30,"t":"Şimdi birbirlerini yermeye başladılar."},{"n":31,"t":"Dediler ki: Yazıklar olsun bize, doğrusu biz; azgınlardanmışız."},{"n":32,"t":"Belki Rabbımız bize bundan daha iyisini verir. Doğrusu biz; artık Rabbımızdan dilemekteyiz."},{"n":33,"t":"Azab işte böyledir. Fakat ahiret azabı elbet daha büyüktür. Keşki bilmiş olsalardı."},{"n":34,"t":"Muhakkak ki müttakiler için, Rabbları katında Naim cennetleri vardır."},{"n":35,"t":"Biz; müslümanları suçlular gibi tutar mıyız hiç?"},{"n":36,"t":"Ne oluyor size, nasıl hükmediyorsunuz?"},{"n":37,"t":"Yoksa size mahsus bir kitab var da ondan mı okuyorsunuz?"},{"n":38,"t":"Seçtikleriniz herhalde orada olacaktır."},{"n":39,"t":"Yoksa kıyamet gününe kadar sürüp gidecek ahidler mi var aleyhimizde? Muhakkak ki hükmettikleriniz sizin olacaktır."},{"n":40,"t":"Sor onlara; hangisi bunu üzerine alacak?"},{"n":41,"t":"Yoksa onların ortakları mı var? Öyleyse ortaklarını da getirsinler. Eğer sadıklardan iseler."},{"n":42,"t":"O gün; baldırlar açılır ve secdeye çağrılırlar. Ama buna güç yetiremezler."},{"n":43,"t":"Gözleri dönmüş olarak, yğzlerini zillet bürür. Halbuki kendileri sapa sağlam oldukları vakit secdeye çağırılmışlardı."},{"n":44,"t":"Bu sözü yalanlayanları Bana bırak. Biz; onları, kendilerinin bilmeyecekleri bir yönden derece derece azaba yaklaştıracağız."},{"n":45,"t":"Ben; onlara mühlet veriyorum. Benim tuzağım muhakkak sağlamdır."},{"n":46,"t":"Yoksa sen, onlardan bir ücret istiyorsun da ağır bir borç altında mı kalmışlardır?"},{"n":47,"t":"Yoksa gayb kendilerinin katında mıdır da ondan yazıyorlar?"},{"n":48,"t":"Sen; Rabbının hükmüne sabret ve balık sahibi gibi olma. Hani o; gamla dolu olarak, Rabbına seslenmişti."},{"n":49,"t":"Rabbının katında ona bir nimet erişmiş olmasaydı; mutlaka o, kınanmış olarak çıplak bir yere atılacaktı."},{"n":50,"t":"Rabbı, onu seçti de salihlerden kıldı."},{"n":51,"t":"Doğrusu o küfredenler, zikri işittiklerinde, az kalsın seni gözleriyle yiyeceklerdi. Ve o, mutlaka bir delidir, diyorlardı."},{"n":52,"t":"Halbuki o, alemler için öğütten başka bir şey değildir."}],[{"n":1,"t":"Gerçekleşecek olan."},{"n":2,"t":"Nedir o gerçekleşecek olan?"},{"n":3,"t":"Hangi şey bildirdi sana, gerçekleşecek olanın ne olduğunu?"},{"n":4,"t":"Semud ve Ad, tepelerine inecek olanı yalanladılar."},{"n":5,"t":"Bu sebeple Semud, azgın bir sesle helak edildiler."},{"n":6,"t":"Ad’a gelince; onlar da uğultulu, azgın bir fırtına ile helak edildiler."},{"n":7,"t":"Onların kökünü kesmek için, üzerlerine yedi gece sekiz gün, rüzgarı estirdi. Halkın, kökünden sökülmüş hurma kütükleri gibi yere yıkıldığını görürdün."},{"n":8,"t":"Şimdi onlardan geri kalan bir şey görüyor musun?"},{"n":9,"t":"Firavun da, ondan öncekiler de ve altüst olmuş kasabalar da hep suçla gelmişlerdi."},{"n":10,"t":"Rabblarının elçisine isyan etmişlerdi. Bunun üzerine O da kendilerini gittikçe artan bir şiddetle yakalayıverdi."},{"n":11,"t":"Gerçekten su bastığı zaman sizi; Biz, taşıdık gemide."},{"n":12,"t":"Ki bunu sizin için bir öğüt ve ibret yapalım. Ve anlayışlı kulaklar anlasın diye."},{"n":13,"t":"Sur’a bir üfürüldüğünde;"},{"n":14,"t":"Yer ile dağlar kaldırılıp bir vuruşla birbirine çarpıldığında,"},{"n":15,"t":"İşte o gün; olan olmuştur."},{"n":16,"t":"Gök de yarılmış ve o gün bitkin bir hale gelmiştir."},{"n":17,"t":"Melekler ise onun çevresindedirler. Ve o gün; Rabbının Arş’ını, onların da üstünde sekiz tanesi yüklenir."},{"n":18,"t":"O gün; siz, huzura alınırsınız. Ve hiç bir şeyiniz gizli kalmaz."},{"n":19,"t":"Kitabı sağından verilmiş olan der ki: Alın, işte okuyun kitabımı."},{"n":20,"t":"Doğrusu ben, bir hesablaşma ile karşılaşacağımı sanıyordum."},{"n":21,"t":"İşte o, hoş bir hayat içindedir."},{"n":22,"t":"Yüksek bir cennette,"},{"n":23,"t":"Ki, meyveleri sarkmıştır."},{"n":24,"t":"Geçmiş günlerde peşinen işlediklerinize karşılık afiyetle yeyin, için."},{"n":25,"t":"Kitabı solundan verilmiş olana gelince; der ki: Keşki kitabım bana verilmeseydi."},{"n":26,"t":"Hesabımın da ne olduğunu bilmeseydim."},{"n":27,"t":"Keşki bu iş son bulmuş olsaydı."},{"n":28,"t":"Malım hiç fayda vermedi bana."},{"n":29,"t":"Gücüm de yok olup gitti benden."},{"n":30,"t":"Tutun onu da bağlayın."},{"n":31,"t":"Sonra cehenneme salın onu."},{"n":32,"t":"Sonra da onu, boyu yetmiş arşın olan zincire vurun."},{"n":33,"t":"Çünkü o, yüce Allah’a inanmazdı."},{"n":34,"t":"Ve yoksulu doyurmaktan hoşlanmazdı. 69"},{"n":35,"t":"Onun için bugün burada kendisine bir acıyan yoktur."},{"n":36,"t":"Ğıslin’den başka yiyecek de yoktur."},{"n":37,"t":"Onu ancak günahkarlar yer."},{"n":38,"t":"Görebildiğinize yemin ederim ki;"},{"n":39,"t":"Ve göremediklerinize de;"},{"n":40,"t":"Muhakkak o; şerefli bir elçinin kat’i sözüdür."},{"n":41,"t":"Ve o, bir şair sözü değildir. Ne de az inanıyorsunuz?"},{"n":42,"t":"Bir kahin sözü de değildir. Ne de az düşünüyorsunuz?"},{"n":43,"t":"Alemlerin Rabbından indirilmedir."},{"n":44,"t":"Eğer o; bazı sözleri Bize karşı buna katmış olsaydı,"},{"n":45,"t":"Elbette Biz; onu, kuvvetle yakalardık."},{"n":46,"t":"Sonra da, hiç şüphesiz onun şah damarını koparırdık."},{"n":47,"t":"O zaman sizden hiç biriniz de buna engel olamazdınız."},{"n":48,"t":"Doğrusu o; müttakiler için bir öğüttür."},{"n":49,"t":"İçinizde yalanlayanlar bulunduğunu Biz de bilmekteyiz."},{"n":50,"t":"Ve muhakkak ki o; kafirler için bir üzüntüdür."},{"n":51,"t":"Hiç şüphesiz ki o; kesin gerçektir."},{"n":52,"t":"Öyleyse Rabbını, o büyük adıyla tesbih et."}],[{"n":1,"t":"İsteyen birisi, inecek azabı istedi."},{"n":2,"t":"O; kafirler içindir ve onu engelleyecek yoktur."},{"n":3,"t":"Derecelere sahip, Allah katındandır."},{"n":4,"t":"Melekler de, ruh da miktarı ellibin yıl olan bir günde ona yükselip çıkarlar."},{"n":5,"t":"Öyleyse Sen, güzel güzel sabret."},{"n":6,"t":"Doğrusu onlar; bunu uzak görüyorlar."},{"n":7,"t":"Biz ise; onu, yakın görmekteyiz."},{"n":8,"t":"O gün gök, erimiş maden gibi olur."},{"n":9,"t":"Dağlar ise atılmış pamuk gibi."},{"n":10,"t":"Hiç bir yakın bir yakınını sormaz."},{"n":11,"t":"Yalnız birbirine gösterilirler. Suçlu kişi; o günün azabından kurtulmak için oğullarını feda etmek ister."},{"n":12,"t":"Eşini ve kardeşini,"},{"n":13,"t":"Kendisini barındırmış olan sülalesini."},{"n":14,"t":"Ve yeryüzünde bulunan herkesi. Ki nihayet kendisini kurtarsın."},{"n":15,"t":"Fakat ne mümkün, çünkü o; halis alevdir."},{"n":16,"t":"Deriyi soyup kavurandır."},{"n":17,"t":"Yüz çevirip arkasına döneni çağırır."},{"n":18,"t":"Malını toplayıp kap içinde saklayanı da."},{"n":19,"t":"Gerçekten insan; hırsına düşkün yaratılmıştır."},{"n":20,"t":"Başına bir fenalık gelince, feryadı basandır."},{"n":21,"t":"Kendisine bir hayır dokununca da çok cimridir."},{"n":22,"t":"Ancak namaz kılanlar müstesna."},{"n":23,"t":"Onlar ki; namazlarında daimdirler."},{"n":24,"t":"Ve onlar ki; mallarında belirli bir hak vardır;"},{"n":25,"t":"Dilenen ve yoksula."},{"n":26,"t":"Onlar ki; din gününü doğrularlar."},{"n":27,"t":"Ve onlar ki; Rabblarının azabından korkarlar."},{"n":28,"t":"Doğrusu onlar, Rabblarının azabından güvende değildirler."},{"n":29,"t":"Ve onlar ki; mahrem yerlerini korurlar."},{"n":30,"t":"Ancak eşleri ve sağ ellerinin malik oldukları müstesna. Doğrusu onlar, bunun için kınanacak değildirler."},{"n":31,"t":"Kim de bundan ötesini ararsa; işte onlar, haddi aşanların kendileridir."},{"n":32,"t":"Ve onlar ki; emanetlerine ve ahidlerine riayet ederler."},{"n":33,"t":"Ve onlar ki; şahidliklerini gereği gibi yaparlar."},{"n":34,"t":"Ve onlar ki; namazlarını muhafaza ederler."},{"n":35,"t":"İşte bunlar; cennetlerde ikram olunanlardır."},{"n":36,"t":"O küfredenlere ne oluyor ki; gözlerini sana doğru dikip bakmaktadırlar."},{"n":37,"t":"Sağdan ve soldan halka halka olarak."},{"n":38,"t":"Onlardan herkes Naim cennetine konulacağını mı umuyor?"},{"n":39,"t":"Hayır. Doğrusu Biz; onları, bilip durdukları şeyden yarattık."},{"n":40,"t":"Doğuların ve Batıların Rabbına yemin ederim ki, şüphesiz Biz; gücü yetenleriz."},{"n":41,"t":"Ki onların yerine kendilerinden daha iyilerini getirelim. Ve Biz, önüne geçilecekler de değiliz."},{"n":42,"t":"Bırak onları, kendilerine vaadolunan güne kavuşuncaya kadar dalıp oynasınlar."},{"n":43,"t":"O gün; onlar, dikili taşlara doğru koşuyorlarmış gibi, kabirlerden çabuk çabuk çıkarlar."},{"n":44,"t":"Gözleri dönmüş, yüzlerini zillet bürümüş olarak. İşte bu; onlara vaad olunan gündür."}],[{"n":1,"t":"Doğrusu Biz; Nuh’u kavmine gönderdik. Kendilerine elim bir azab gelmezden önce kavmini uyar, diye."},{"n":2,"t":"Dedi ki: Ey kavmim; şüphesiz ben, sizin için apaçık bir uyarıcıyım."},{"n":3,"t":"Allah’a ibadet edesiniz, O’ndan sakınasınız ve bana itaat edin, diye."},{"n":4,"t":"Ta ki, günahlarınızı size bağışlasın ve sizi belli bir süreye kadar geciktirsin. Muhakkak ki Allah’ın süresi gelince geri bırakılmaz. Keşki bilseydiniz."},{"n":5,"t":"Dedi ki: Rabbım; doğrusu ben, kavmimi gece gündüz davet ettim."},{"n":6,"t":"Ne var ki benim davetim; sadece benden uzaklaşmalarını artırdı."},{"n":7,"t":"Doğrusu ben; Senin onları bağışlaman için kendilerini davet ettiğim her seferinde, parmaklarını kulaklarına tıkadılar, elbiselerine büründüler, direndiler ve büyüklendikçe büyüklendiler."},{"n":8,"t":"Sonra ben; onları gerçekten açıkça çağırdım."},{"n":9,"t":"Sonra onlara; açıktan açığa ve gizliden gizliye söyledim."},{"n":10,"t":"Dedim ki: Rabbınızdan mağfiret dileyin. Muhakkak ki O Ğaffar olandır."},{"n":11,"t":"Ta ki size, gökten bol yağmur salıversin."},{"n":12,"t":"Ve sizi mallar ve oğullarla desteklesin, sizin için bahçeler var etsin ve ırmaklar akıtsın."},{"n":13,"t":"Ne oluyorsunuz ki siz, büyüklüğü Alla’a yakıştıramıyorsunuz?"},{"n":14,"t":"Halbuki O; sizi merhalelerden geçirerek yaratmıştır."},{"n":15,"t":"Görmediniz mi, Allah’ın göğü yedi kat olarak nasıl yarattığını?"},{"n":16,"t":"Aralarında aya aydınlık vermiş, güneşi bir kandil kılmıştır."},{"n":17,"t":"Ve Allah; sizi, yerden ot bitirir gibi bitirmiştir."},{"n":18,"t":"Sonra sizi; oraya döndürür ve sizi bir çıkarılışla çıkarır."},{"n":19,"t":"Ve Allah; yeryüzünü sizin için bir döşek kılmıştır."},{"n":20,"t":"Geniş yollarında gezip dolaşasınız, diye."},{"n":21,"t":"Nuh dedi ki: Rabbım doğrusu bunlar, bana isyan ettiler. Malı ve çocuğu kendisine sadece zarar getiren kimseye uydular."},{"n":22,"t":"Büyük büyük düzenler kurdular."},{"n":23,"t":"Ve dediler ki: Sakın tanrılarınızı bırakmayın. Vedd, Süva’, Yeğus, Yeuk ve Nesr’den asla vazgeçmeyin."},{"n":24,"t":"Böylece bir çoğunu saptırdılar. Zalimlere sapıklıktan başka bir şeyi artırma."},{"n":25,"t":"günahlarından dolayı bunlar suda boğuldular, ateşe sokuldular ve Allah’ tan başka yardımcı da bulamadılar."},{"n":26,"t":"Nuh dedi ki: Rabbım; kafirlerden yeryüzünde yurd tutan hiç bir kimse bırakma."},{"n":27,"t":"Çünkü Sen onları bırakırsan; kullarını saptırırlar. Kötüden ve öz kafirden başka da evlat doğurmazlar."},{"n":28,"t":"Rabbım; beni, anamı, babamı, inanmış olarak evime gireni, mü’min erkekleri ve mü’min kadınları bağışla. Zalimlerin de helakinden başka bir şeyini artırma."}],[{"n":1,"t":"De ki: Bana vahyolundu ki; cinnlerden bir topluluk onu dinlemiş ve; doğrusu biz, hayrete düşüren bir Kur’an dinledik, demişlerdir."},{"n":2,"t":"O, doğru yola iletiyor. Biz de ona iman ettik. Ve Rabbımıza hiç bir şeyi şirk koşmayacağız."},{"n":3,"t":"Muhakkak ki Rabbımızın şanı yücedir. O; eş ve çocuk edinmemiştir."},{"n":4,"t":"Doğrusu bizim beyinsizimiz; Allah’a karşı yalanlar söylüyormuş."},{"n":5,"t":"Doğrusu öyle zannettik ki; insanlar ve cinnler Allah’a karşı asla yalan söylemezler."},{"n":6,"t":"Doğrusu insanlardan bazı kimseler; cinnlerden bir takım kimselere sığınırlardı da onların azgınlıklarını artırırlardı."},{"n":7,"t":"Doğrusu onlar da sizin sandığınız gibi, Allah’ın yeniden kimseyi diriltemeyeceğini sandılar."},{"n":8,"t":"Doğrusu biz; göğü yokladık da, onu sert bekçiler ve alevlerle doldurulmuş bulduk."},{"n":9,"t":"Doğrusu biz; göğün dinlenebileceği bir yerinde oturmuştuk; ama şimdi kim onu dinleyecek olursa, kendisini gözetleyen bir alev buluyor."},{"n":10,"t":"Doğrusu biz bilmiyoruz; yeryüzünde onlara kötülük mü dilenmiştir, yoksa Rabbları onlara iyilik mi dilemiştir?"},{"n":11,"t":"Gerçekten aramızda salihler de vardır ve bundan aşağı olanlar da. Biz, türlü türlü yollara ayrılmışız."},{"n":12,"t":"Doğrusu biz, yeryüzünde kalsak da Allah’ı aciz bırakamayacağımızı, kaçsak da O’nu asla aciz bırakamayacağımızı anladık."},{"n":13,"t":"Doğrusu biz, hidayeti işittiğimizde ona inandık. Kim Rabbına iman ederse; o, ecrinin eksiltilmesinden ve kendisine haksızlık edilmesinden korkmaz."},{"n":14,"t":"İçimizden teslim olanlar da vardır, kendilerine yazık edenler de. Kim teslim olursa; işte onlar, doğru yolu aramış olanlardır."},{"n":15,"t":"Kendilerine yazık edenlere gelince; onlar da cehenneme odun oldular."},{"n":16,"t":"Şayet onlar, yol üzerinde istikameti bulmuş olsalardı; onlara bol bol su içirirdik."},{"n":17,"t":"Ki onları bununla tecrübe edelim. Kim Rabbının zikrinden yüz çevirirse; onu, gittikçe artan bir azaba uğratır."},{"n":18,"t":"Muhakkak ki mescidler, Allah içindir. Öyleyse Allah ile beraber başkasına ibadet etmeyin."},{"n":19,"t":"Doğrusu Allah’ın kulu, kalkıp O’na yalvarınca; neredeyse çevresinde keçe gibi oluyorlardı."},{"n":20,"t":"De ki: Ben; ancak Rabbıma yalvarırım. Ve O’na hiç kimseyi ortak koşmam."},{"n":21,"t":"De ki: Ben; size zarar vermeye de, iyilik yapmaya da muktedir değilim."},{"n":22,"t":"De ki: Doğrusu kimse beni, Allah’a karşı savunamaz. Ve ben, O’ndan başka bir sığınak da bulamam."},{"n":23,"t":"Benim vazifem; ancak Allah katından olanı ve O’nun risaletlerini tebliğ etmektir. Kim, Allah’a ve Rasulüne isyan ederse; muhakkak ki onun için, cehennem ateşi vardır. Orada ebediyyen kalacaklardır."},{"n":24,"t":"Nihayet kendilerine vaadedilenleri gördükleri zaman, kimin yardımcısının daha zayıf ve sayıca daha az olduğunu bileceklerdir."},{"n":25,"t":"De ki: Size vaadedilen yakın mıdır, yoksa Rabbım onu uzun süreli mi kılmıştır bilemiyorum."},{"n":26,"t":"Gaybı bilendir. Gaybını kimseye açıklamaz."},{"n":27,"t":"Ancak beğenip seçtiği bir peygamber müstesnadır. Çünkü onun önünden ve ardından gözcüler koyar."},{"n":28,"t":"Ta ki Rabblarının risaletlerini, gerçekten tebliğ etmiş olduklarını bilsin. Onların yaptıklarını kuşatmış ve her şeyi bir sayı ile saymıştır."}],[{"n":1,"t":"Ey örtüsüne bürünen;"},{"n":2,"t":"Gecenin birazı müstesna kalk."},{"n":3,"t":"Yarısından veya ondan biraz eksilt."},{"n":4,"t":"Yahut biraz artır ve Kur’an’ı yavaş yavaş oku."},{"n":5,"t":"Muhakkak ki Biz; sana, ağır bir söz vahyedeceğiz."},{"n":6,"t":"Muhakkak ki gece kalkışı, daha tesirli ve o zaman okumak daha elverişlidir."},{"n":7,"t":"Muhakkak ki gündüzde; seni, uzun uzun alıkoyacak işler vardır."},{"n":8,"t":"Rabbının adını zikret, her şeyi bırakıp yalnız O’na yönel."},{"n":9,"t":"Doğunun ve Batının Rabbıdır. O’ndan başka ilah yoktur. Öyleyse onu vekil edin."},{"n":10,"t":"Onların söylediklerine sabret ve yanlarından güzellikle ayrıl."},{"n":11,"t":"Nimet sahibi olan o yalancıları Bana bırak. Ve onlara biraz mühlet ver."},{"n":12,"t":"Muhakkak ki katımızda, ağır boyunduruklar ve cehennem var."},{"n":13,"t":"Boğazı tıkayan bir yiyecek ve elim bir azab var."},{"n":14,"t":"O gün; yeryüzü ve dağlar sarsılır. Ve dağlar yumuşak kum yığını haline gelir."},{"n":15,"t":"Doğrusu Biz; Firavun’a bir peygamber göndedriğimiz gibi, size de üzerinize şehadet edecek bir peygamber gönderdik."},{"n":16,"t":"Fakat Firavun, o peygambere isyan etti. Biz de onu ağır bir yakalayışla yakaladık."},{"n":17,"t":"Eğer küfrederseniz; gençleri yaşlı kılan bir günden nasıl korunabileceksiniz?"},{"n":18,"t":"Gök, onunla yarılmış ve O’nun vaadi yerini bulmuştur."},{"n":19,"t":"Muhakkak ki bu; bir öğüttür. Dileyen, Rabbına doğru bir yol edinir."},{"n":20,"t":"Şüphesiz ki Rabbın; senin, gecenin üçte ikisi, yarısı ve üçte biri içinde kalktığını bilir. Seninle beraber olan bir topluluğun da. Gece ve gündüzü Allah, takdir eder. Sizin onu sayamayacağınızı bildiğinden tevbenizi kabul etmiştir. Öyleyse Kur’an’dan kolayınıza geleni okuyun. İçinizden hasta olacakları, Allah’ın lutfundan aramak üzere yeryüzünde dolaşacak olanları ve Allah yolunda savaşacak olanları şüphesiz ki Allah bilir. O halde ondan kolayınıza geleni okuyun, namazı kılın, zekatı verin ve Allah’a güzel bir ödünç verin. Kendiniz için hayırdan ne takdim ederseniz; Allah katında onu mükafat bakımından daha büyük ve daha hayırlı olarak bulursunuz. Ve Allah’tan mağfiret dileyin. Muhakkak ki Allah; Gafur’dur, Rahim’dir."}],[{"n":1,"t":"Ey örtüye bürünen;"},{"n":2,"t":"Kalk ve uyar."},{"n":3,"t":"Rabbını da tekbir et."},{"n":4,"t":"Elbiselerini temiz tut."},{"n":5,"t":"Kötü şeylerden ise sakın."},{"n":6,"t":"Çok görerek başa kakma."},{"n":7,"t":"Rabbın için sabret."},{"n":8,"t":"Sur’a üflendiğinde;"},{"n":9,"t":"İşte o gün, zorlu bir gündür."},{"n":10,"t":"Kafirler için hiç de kolay değildir."},{"n":11,"t":"Bırak Beni ve yarattıklarımı tek başına."},{"n":12,"t":"Kendisine bol bol mal verdiğimi,"},{"n":13,"t":"Görülen oğullar verdiğimi,"},{"n":14,"t":"Ve onun için yaydıkça yaydığımı."},{"n":15,"t":"Sonra daha da artırmamı umar o."},{"n":16,"t":"Hayır; çünkü o, ayetlerimize karşı bir inatçı kesildi."},{"n":17,"t":"Ben; onu sarp bir yokuşa sardıracağım."},{"n":18,"t":"Doğrusu o, düşündü ve ölçüp biçti."},{"n":19,"t":"Canı çıkası, nasıl da ölçüp biçti."},{"n":20,"t":"Sonra yine canı çıkası nasıl da öşçüp biçti."},{"n":21,"t":"Sonra baktı."},{"n":22,"t":"Sonra kaşlarını çattı, suratını astı."},{"n":23,"t":"Sonra da sırt çevirip büyüklük tasladı."},{"n":24,"t":"Ve dedi ki: Bu; sadece öğretilegelen bir büyüdür."},{"n":25,"t":"Bu; ancak bir insan sözüdür."},{"n":26,"t":"Ben, onu Sekar’a yaslayacağım."},{"n":27,"t":"Sekar’ın ne olduğunu bilir misin sen?"},{"n":28,"t":"O, ne geri bırakır, ne de azabdan vazgeçer."},{"n":29,"t":"Deriyi kavurandır."},{"n":30,"t":"Onun üzerinde ondokuz vardır."},{"n":31,"t":"Cehennem bekçilerini yalnız meleklerden kıldık. Onların sayılarını da ancak küfretmiş olanlar için bir fitne kıldık. Ki kendilerine kitab verilmiş olanlar, kesin bilgi sahibi olsunlar. İman edenlerin de imanları artsın. Kendilerine kitab verilmiş olanlar ve mü’minler kuşkuya düşmesinler. Bir de kalblerinde hastalık bulunanlarla kafirler: Bununla Allah neyi kasdetmiş? desinler. İşte böyle Allah, dilediğini saptırır, dilediğini hidayete erdirir. Rabbının ordularını ancak kendisi bilir. Bu, ancak insanlara bir öğüttür."},{"n":32,"t":"Hayır, andolsun aya,"},{"n":33,"t":"Dönüp geldiğinde geceye,"},{"n":34,"t":"Ağardığında sabaha,"},{"n":35,"t":"Muhakkak ki o, büyüklerden biridir."},{"n":36,"t":"İnsanlar için uyarıcıdır."},{"n":37,"t":"İçinizden öne geçmek veya geri kalmak isteyenler için."},{"n":38,"t":"Her nefis kazandığı ile bağlıdır."},{"n":39,"t":"Ancak sağcılar müstesna."},{"n":40,"t":"Cennetlerdedirler. Sorarlar,"},{"n":41,"t":"Suçlulara;"},{"n":42,"t":"Nedir sizi Sekar’a sürükleyen?"},{"n":43,"t":"Derler ki: Biz, namaz kılanlardan değildik,"},{"n":44,"t":"Yoksulu doyurmazdık,"},{"n":45,"t":"Dalanlarla birlikte biz de dalardık,"},{"n":46,"t":"Ve din gününü yalanlardık."},{"n":47,"t":"Nihayet ölüm bize gelip çattı."},{"n":48,"t":"Artık onlara, şefaatçıların şefaatı fayda vermez."},{"n":49,"t":"O halde bunlara ne oluyor ki öğütten yüz çeviriyorlar?"},{"n":50,"t":"Ürkek yaban eşekleri gibi;"},{"n":51,"t":"Ürkmüş olan, arslandan."},{"n":52,"t":"Hayır, onlardan her biri, önüne açılıvermiş sahifeler verilmesini ister."},{"n":53,"t":"Hayır, doğrusu onlar, ahiretten korkmuyorlar."},{"n":54,"t":"Hayır, muhakkak ki o, bir öğüttür."},{"n":55,"t":"Kim isterse; ondan öğüt alır."},{"n":56,"t":"Allah dilemedikçe öğüt alamazlar. O, takvaya ehildir, mağfirete ehildir."}],[{"n":1,"t":"Kıyamet gününe yemin ederim."},{"n":2,"t":"Nedamet çeken nefse yemin ederim."},{"n":3,"t":"İnsan zanneder mi ki Biz; onun kemiklerini bir araya toplayamayız?"},{"n":4,"t":"Evet, Biz parmak uçlarını bile düzeltmeye kadiriz."},{"n":5,"t":"Fakat insan, önündekini yalanlamak ister de;"},{"n":6,"t":"Kıyamet günü de ne zamanmış? diye sorar."},{"n":7,"t":"Göz kamaştığında,"},{"n":8,"t":"Ay tutulduğunda,"},{"n":9,"t":"Güneş ve ay bir araya getirildiğinde,"},{"n":10,"t":"O gün, insan; kaçacak yer nerede? der."},{"n":11,"t":"Hayır, hiç bir sığınak yoktur."},{"n":12,"t":"O gün, herkesin duracağı yer, ancak Rabbının huzurudur."},{"n":13,"t":"O gün, önde ve sonda ne yaptıysa insana bildirilir."},{"n":14,"t":"Daha doğrusu insan, kendi kendinin şahididir."},{"n":15,"t":"Ma’zeretlerini sayıp dökse de."},{"n":16,"t":"Onu acele etmen için dilini onunla beraber oynatma."},{"n":17,"t":"Şüphesiz onu toplamak ve okutmak Bize aittir."},{"n":18,"t":"Öyleyse Biz, onu okuduğumuz vakit; sen, onun okunuşunu dinle."},{"n":19,"t":"Sonra şüphesiz onu açıklamak da Bize aittir."},{"n":20,"t":"Hayır, bilakis siz, çabuk geçeni seversiniz."},{"n":21,"t":"Ve ahireti bırakırsınız."},{"n":22,"t":"Bir takım yüzler o gün parlayacak,"},{"n":23,"t":"Rabblarına bakacaklardır."},{"n":24,"t":"Bir takım yüzler de asıktır."},{"n":25,"t":"Belkemiğinin kırılacağını anlar."},{"n":26,"t":"Dikkat edin, köprücük kemiğine bir dayandığı zaman;"},{"n":27,"t":"Çare bulacak kim? denir."},{"n":28,"t":"Ve ayrılık vaktinin geldiğini anlar."},{"n":29,"t":"Bacak da bacağa dolaşır."},{"n":30,"t":"O gün; sevk, yalnız Rabbınadır."},{"n":31,"t":"Tasdik etmemişti, namaz da kılmamıştı."},{"n":32,"t":"Fakat yalanlamış, yüz çevirmişti."},{"n":33,"t":"Sonra da salına salına kendinden yana olanlara gitmişti."},{"n":34,"t":"Yazıklar olsun sana, yazıklar."},{"n":35,"t":"Yine yazıklar olsun sana, yazıklar."},{"n":36,"t":"İnsan kendisinin başıboş bırakılacağını mı sanır?"},{"n":37,"t":"O, akıtılan bir meni damlası değil miydi?"},{"n":38,"t":"Sonra kan pıhtısı olmuş; sonra, onu insan biçimine koyup yaratmış ve düzeltmiştir."},{"n":39,"t":"Ve ondan erkek, dişi iki cins yaratmıştır."},{"n":40,"t":"Şimdi O; ölüleri diriltmeye kadir değil midir?"}],[{"n":1,"t":"İnsanın üzerinden, dehrden bir zaman geçmiştir ki o, henüz anılmaya değer bir şey bile değildi."},{"n":2,"t":"Doğrusu Biz; insanı katışık bir damla sudan yaratmışızdır. Onu deneriz. Bu sebeple onu, işitici ve görücü yaptık."},{"n":3,"t":"Gerçekten Biz; ona yolu gösterdik. Buna kimisi şükreder, kimisi de küfür."},{"n":4,"t":"Gerçekten Biz; kafirler için zincirler, demir halkalar ve alevlendirilmiş bir ateş hazırladık."},{"n":5,"t":"Şüphesiz iyiler, kafur katılmış dolu bir kaseden içerler."},{"n":6,"t":"Bu; yalnız Allah’ın kullarının, taşıra taşıra içebileceği bir pınardır."},{"n":7,"t":"Onlar; adağı yerine getirirler. Ve şerri yaygın olan bir günden korkarlar."},{"n":8,"t":"Onlar; yoksula, yetime ve esire seve seve yemek yedirirler."},{"n":9,"t":"Biz; sizi, ancak Allah rızası için doyuruyoruz. Sizden bir karşılık ve teşekkür beklemiyoruz."},{"n":10,"t":"Doğrusu Biz; suratları astırdıkça astıracak bir günde Rabbımızdan korkarız."},{"n":11,"t":"Allah da onları, o günün şerrinden korumuştur. Ve onlara bir güzellik, bir sevinç vermiştir."},{"n":12,"t":"Sabretmelerine karşılık, onları cennet ve ipekle mükafatlandırmıştır."},{"n":13,"t":"Orada tahtlara yaslanırlar, ne yakıcı sıcak ne de dondurucu soğuk görmezler."},{"n":14,"t":"Meyve ağaçlarının gölgeleri üzerlerine sarkmış ve meyveleri de aşağı eğdirilmiştir."},{"n":15,"t":"Çevrelerinde gümüş kupalar ve billur kaseler dolaştırılır."},{"n":16,"t":"Billurları gümüş gibi parlaktır. Mikdarını onlar takdir etmiştir."},{"n":17,"t":"Orada karışımı zencefil olan bir kadehten de içirilirler."},{"n":18,"t":"Orada bir pınardır ki, Selsebil adı verilir."},{"n":19,"t":"Çevrelerinde ölümsüz gençler dolaşır ki; onları gördüğünde saçılmış bir inci sanırsın."},{"n":20,"t":"Nereye baksan; orada bir nimet ve büyük bir mülk görürsün."},{"n":21,"t":"Üzerlerinde ince, yeşil ipekli ve parlak atlastan elbiseler vardır. Gümüşten bileziklerle süslenmişlerdir. Rabbları onlara tertemiz bir içecek içirmiştir."},{"n":22,"t":"İşte bu, sizin işlediklerinize karşılık oldu. Sa’yiniz meşkur olmuştur."},{"n":23,"t":"Muhakkak ki Kur’an’ı sana indiren Biziz, Biz."},{"n":24,"t":"Öyleyse Rabbının hükmüne sabret ve onlardan hiç bir günahkara veya inkarcıya itaat etme."},{"n":25,"t":"Sabah akşam Rabbının adını zikret."},{"n":26,"t":"Geceleyin O’na secde et. Ve geceleri uzun uzun O’nu tesbih et."},{"n":27,"t":"Doğrusu bunlar; çabucak geçeni severler de, o çetin günün arkalarına bırakırlar."},{"n":28,"t":"Biz yarattık onları ve mafsallarını da Biz pekiştirdik. Dilersek onları benzerleri ile değiştiriveririz."},{"n":29,"t":"Şüphesiz ki bu, bir öğüttür. Dileyen Rabbına bir yol tutar."},{"n":30,"t":"Allah dilemedikçe, siz dileyemezsiniz. Muhakkak ki Allah; Alim, Hakim olandır."},{"n":31,"t":"Dilediğini rahmetine girdirir. Zalimlere, işte onlara; elem verici bir azab hazırlamıştır."}],[{"n":1,"t":"Andolsun birbiri ardınca gönderilenlere,"},{"n":2,"t":"Şiddetle esip koştukça koşanlara,"},{"n":3,"t":"Veya yaydıkça yayanlara."},{"n":4,"t":"Böylece ayırdıkça ayıranlara,"},{"n":5,"t":"Zikri getirenlere,"},{"n":6,"t":"Ma’zeret ve uyarı için."},{"n":7,"t":"Size vaadedilen mutlaka olacaktır."},{"n":8,"t":"Yıldızlar söndürüldüğü zaman,"},{"n":9,"t":"Gök yarıldığı vakit,"},{"n":10,"t":"Dağlar atıldığı zaman,"},{"n":11,"t":"Peygamberlerin vakti geldiği zaman,"},{"n":12,"t":"Hangi güne ertelenmişti?"},{"n":13,"t":"Hüküm gününe,"},{"n":14,"t":"Hüküm gününü hangi şey bildirdi sana?"},{"n":15,"t":"O gün; yalanlayanların vay haline."},{"n":16,"t":"Öncekileri Biz helak etmedik mi?"},{"n":17,"t":"Ardından sonrakileri de onların arkasına takacağız."},{"n":18,"t":"İşte Biz; böylr yaparız suçluları."},{"n":19,"t":"O gün; yalanlayanların vay haline."},{"n":20,"t":"Sizi bayağı bir sudan, Biz yaratmadık mı?"},{"n":21,"t":"Onu sağlam bir yere yerleştirdik."},{"n":22,"t":"Belli bir süreye kadar."},{"n":23,"t":"Bunu Biz takdir ettik, ne güzel takdir edenleriz Biz."},{"n":24,"t":"Vay haline o gün, yalanlayanların."},{"n":25,"t":"Biz; yeryüzünü toplantı mahalli kılmadık mı?"},{"n":26,"t":"Ölülere de, dirilere de."},{"n":27,"t":"Orada yüksek ve sabit dağlar var edip tatlı sular içirmedik mi size?"},{"n":28,"t":"Vay haline o gün, yalanlayanların."},{"n":29,"t":"Varın yalanlayıp durduğunuz şeye gidin."},{"n":30,"t":"Üç kollu gölgeye gidin."},{"n":31,"t":"Gölge yapmaz ve alevden korumaz."},{"n":32,"t":"O; her biri bir saray gibi kıvılcımlar atar."},{"n":33,"t":"Ve her biri sanki birer sarı erkek devedir."},{"n":34,"t":"Vay haline o gün, yalanlayanların."},{"n":35,"t":"Bu; onların konuşamayacakları gündür."},{"n":36,"t":"Onlara izin de verilmez ki özür dilesinler."},{"n":37,"t":"Vay haline o gün, yalanlayanların."},{"n":38,"t":"İşte bu; sizleri ve öncekileri topladığımız hüküm günüdür."},{"n":39,"t":"Eğer Bana karşı bir düzeniniz varsa; onu hemen kurun."},{"n":40,"t":"Vay haline o gün, yalanlayanların."},{"n":41,"t":"Muhakkak ki muttakiler, gölgeliklerde ve pınarlardadırlar."},{"n":42,"t":"Ve canlarının istediğinden meyveler."},{"n":43,"t":"İşlediklerinize karşılık afiyetle yeyin, için."},{"n":44,"t":"Şüphesiz ki Biz; ihsan edenleri böyle mükafatlandırırız."},{"n":45,"t":"Vay haline o gün, yalanlayanların."},{"n":46,"t":"Yeyin ve biraz eğlenin. Doğrusu sizler suçlularsınız."},{"n":47,"t":"Vay haline o gün, yalanlayanların."},{"n":48,"t":"Onlara; rüku edin, denildiği zaman, rüku’a varmazlar."},{"n":49,"t":"Vay haline o gün, yalanlayanların."},{"n":50,"t":"Bundan sonra artık hangi söze inanacaklar?"}],[{"n":1,"t":"Neyi soruşturuyorlar?"},{"n":2,"t":"Büyük haberi mi?"},{"n":3,"t":"Ki onlar, bunun üzerinde ihtilafa düşmektedirler."},{"n":4,"t":"Hayır; ilerde, bileceklerdir."},{"n":5,"t":"Yine hayır; ilerde, bileceklerdir."},{"n":6,"t":"Yeryüzünü bir beşik yapmadık mı?"},{"n":7,"t":"Dağları da birer kazık?"},{"n":8,"t":"Ve sizi çift çift yarattık."},{"n":9,"t":"Uykunuzu dinlenme kıldık."},{"n":10,"t":"Geceyi bir örtü kıldık."},{"n":11,"t":"Gündüzü de maişet vakti kıldık."},{"n":12,"t":"Üstünüzde yedi sağlamı bina ettik."},{"n":13,"t":"Pırıl pırıl parlayan bir kandil astık."},{"n":14,"t":"Sıkıştırılmlşlardan da şarıl şarıl bir su indirdik."},{"n":15,"t":"Ki onunla taneler ve bitkiler çıkaralım."},{"n":16,"t":"Ve sarmaş dolaş bahçeler yetirelim."},{"n":17,"t":"Doğrusu, hüküm günü; ta’yin edilmiş bir vakittir."},{"n":18,"t":"Sur’a üfürüldüğü gün, hepiniz bölük bölük gelirsiniz."},{"n":19,"t":"Gök açılmış, kapı kapı olmuştur."},{"n":20,"t":"Dağlar yürütülmüş, serab olmuştur."},{"n":21,"t":"Şüphesiz ki cehennem; bir gözetleme yeridir."},{"n":22,"t":"Azgınlar için varılacak bir yer."},{"n":23,"t":"Sonsuz devirler boyunca orada kalacaklardır."},{"n":24,"t":"Orada serinlik ve içecekler tadamayacaklardır."},{"n":25,"t":"Sade kaynar bir su ve bir de irinden başka."},{"n":26,"t":"İşlediklerine uygun bir ceza olarak."},{"n":27,"t":"Çünkü onlar hiç bir hesab beklemezlerdi."},{"n":28,"t":"Ve ayetlerimizi yalan sayıp dururlardı."},{"n":29,"t":"Oysa Biz, her şeyi yazıp saymıştık."},{"n":30,"t":"Öyleyse tadınız, bundan böyle size azabdan başka bir şey artırmayız."},{"n":31,"t":"Şüphesiz ki muttakiler için kurtuluş vardır."},{"n":32,"t":"Bahçeler ve bağlar."},{"n":33,"t":"Göğüsleri tomurcuklanmış yaşıt kızlar."},{"n":34,"t":"Ve dolu kaseler."},{"n":35,"t":"Orada yalan ve boş söz işitmezler."},{"n":36,"t":"Rabbından bir mükafat ve bağış olarak."},{"n":37,"t":"Göklerin, yerin ve ikisi arasında bulunanların Rabbı Rahman’dan. O’na hitabda bulunmaya kimse muktadir olamaz."},{"n":38,"t":"O gün; ruh ve melekler, saf halinde duracaklardır. Rahman’ın izin verdiklerinden başkaları konuşamazlar. O da doğruyu söyler."},{"n":39,"t":"İşte bu; hak gündür. Dileyen Rabbına doğru bir yol edinir."},{"n":40,"t":"Biz, sizi yakın bir azabla uyardık. O gün; kişi elleriyle sunduğuna bakacak. Ve kafir: Keşki ben, toprak olsaydım, diyecektir."}],[{"n":1,"t":"Boğulmuş olanları söküp alanlara andolsun."},{"n":2,"t":"Canları kolaylıkla alanlara,"},{"n":3,"t":"Yüzüp yüzüp gidenlere,"},{"n":4,"t":"Yarıştıkça yarışanlara,"},{"n":5,"t":"Ve işleri yönetenlere,"},{"n":6,"t":"O gün; bir sarsıntı sarsar,"},{"n":7,"t":"Ve peşinden bie başkası gelir."},{"n":8,"t":"O gün kalbler titrer,"},{"n":9,"t":"Gözler yere döner."},{"n":10,"t":"Biz, eski halimize mi döndürüleceğiz? derler."},{"n":11,"t":"Ufalanmış kemikler olduğumuz vakit mi?"},{"n":12,"t":"O takdirde bu, zararlı bir dönüştür, derler."},{"n":13,"t":"Doğrusu o, bir tek çığlıktır."},{"n":14,"t":"Ki o zaman, hepsi toprağın yüzüne dökülecektir."},{"n":15,"t":"Musa’nın haberi geldi mi sana?"},{"n":16,"t":"Hani Rabbı ona; mukaddes vadide, Tuva’da şöyle seslenmişti:"},{"n":17,"t":"Firavun’a git; çünkü o, çok azmıştır."},{"n":18,"t":"De ki: temizlenmeye meylin var mı senin."},{"n":19,"t":"Rabbına giden yolu göstereyim de O’ndan korkasın."},{"n":20,"t":"Ve ona en büyük mucizeyi gösterdi."},{"n":21,"t":"Ama o, yalanlayıp isyan etti."},{"n":22,"t":"Sonra arkasını döndü, koşmaya başladı."},{"n":23,"t":"Toplayıp seslendi:"},{"n":24,"t":"Ve sizin en yüce Rabbınız benim, dedi."},{"n":25,"t":"Bunu üzerine Allah, onu dünya ve ahiret azabıyla yakaladı."},{"n":26,"t":"Şüphesiz ki bunda, korkan kimseler için ibret vardır."},{"n":27,"t":"Sizi yaratmak mı daha zordur, yoksa göğü mü? Onu bina etmiştir."},{"n":28,"t":"Boynu yükseltmiş ve ona bir şekil vermiştir."},{"n":29,"t":"Gecesini karanlık yapmış, gündüzünü ortaya çıkarmıştır."},{"n":30,"t":"Bundan sonra yeri döşemiştir."},{"n":31,"t":"Ondan suyunu ve otlağını çıkarmıştır."},{"n":32,"t":"Dağları dikmiştir."},{"n":33,"t":"Sizin ve hayvanlarınızın geçinmesi için."},{"n":34,"t":"Fakat o en büyük bela geldiği zaman;"},{"n":35,"t":"O gün insan, neye çalıştığını anlar."},{"n":36,"t":"Cehennem, bakan herkese apaçık gösterilir."},{"n":37,"t":"Artık kim haddini aşmışsa."},{"n":38,"t":"Ve kim dünya hayatını tercih etmişse;"},{"n":39,"t":"Şüphesiz ki onun varacağı yer; cehennemdir."},{"n":40,"t":"Kim de Rabbının makamından korkup da nefsini heveslerden alıkoyduysa;"},{"n":41,"t":"Şüphesiz ki onun varacağı yer, cennettir."},{"n":42,"t":"Sana kıyametin ne zaman gelip çatacağını soruyorlar."},{"n":43,"t":"Senin neyine onun zamanını bildirmek."},{"n":44,"t":"En sonunda o, ancak Rabbına aittir."},{"n":45,"t":"Sen, ancak O’ndan korkanı uyaransın."},{"n":46,"t":"Ve onlar onu gördükleri gün; sadece bir akşam veya bir kuşluk vakti kalmış gibi olurlar."}],[{"n":1,"t":"Yüzünü asıp çevirdi,"},{"n":2,"t":"Kendisine a’ma geldi diye."},{"n":3,"t":"Ne bilirsin belki de o, temizlenecekti."},{"n":4,"t":"Yahut öğüt alacaktı da bu, kendisine fayda verecekti."},{"n":5,"t":"Ama kendisini müstağni gören."},{"n":6,"t":"İşte sen, onu karşına alıyorsun."},{"n":7,"t":"Halbuki onun temizlenmemesinden sana ne?"},{"n":8,"t":"Ama sana koşarak gelen,"},{"n":9,"t":"Ki o, korkar durumdadır."},{"n":10,"t":"Sen ona aldırmıyor, oyalanıyorsun."},{"n":11,"t":"Sakın; çünkü bu, bir öğüttür."},{"n":12,"t":"Dileyen onu düşünüp öğüy alır."},{"n":13,"t":"O, çok şerefli sahifelerdedir."},{"n":14,"t":"Yüceltilmiş ve temizlenmiştir."},{"n":15,"t":"Katiblerin elleriyle."},{"n":16,"t":"Kıymetli, saygıdeğer."},{"n":17,"t":"Canı çıksın o insanın. Ne de nankördür o."},{"n":18,"t":"Neden yaratmış onu?"},{"n":19,"t":"Meniden yarattı onu da, takdir etti."},{"n":20,"t":"Sonra ona tutacağı yolu kolaylaştırmış."},{"n":21,"t":"Sonra da onu öldürdü, kabre koydu."},{"n":22,"t":"Sonra dilediğinde onu tekrar çıkaracak."},{"n":23,"t":"Hayır; Allah’ın emrettiğini yerine getirmemiştir."},{"n":24,"t":"Öyle ya insan yiyeceğine bir baksın."},{"n":25,"t":"Doğrusu Biz; o suyu, bol bol indirdik."},{"n":26,"t":"Sonra toprağı iyiden iyiye yardık."},{"n":27,"t":"Böylece orada tane bitirdik."},{"n":28,"t":"Üzüm ve yonca,"},{"n":29,"t":"Zeytin ve hurma,"},{"n":30,"t":"Sık ve bol ağaçlı bahçeler."},{"n":31,"t":"Meyve ve mer’a."},{"n":32,"t":"Sizin ve hayvanlarınızın faydalanması için."},{"n":33,"t":"O büyük gürültü geldiği zaman;"},{"n":34,"t":"Kişinin kaçacağı gün; kardeşinden,"},{"n":35,"t":"Anasından ve babasından."},{"n":36,"t":"Eşinden ve oğullarından."},{"n":37,"t":"O gün; herkesin kendisine yeter bir işi vardır."},{"n":38,"t":"O gün; yüzler vardır, parıl parıl parlar."},{"n":39,"t":"Güleç, sevinçli,"},{"n":40,"t":"O gün; yüzler de vardır, tozlanmış,"},{"n":41,"t":"Bir karanlık bürümüştür."},{"n":42,"t":"İşte bunlar; kafirler ve facirlerdir."}],[{"n":1,"t":"Güneş dürüldüğü zaman;"},{"n":2,"t":"Yıldızlar döküldüğü zaman;"},{"n":3,"t":"Dağlar yürütüldüğü zaman;"},{"n":4,"t":"Gebe develer salıverildiği zaman;"},{"n":5,"t":"Vahşi hayvanlar bir araya toplandığı zaman;"},{"n":6,"t":"Denizler kaynatıldığı zaman;"},{"n":7,"t":"Ruhlar çiftleştirildiği zaman;"},{"n":8,"t":"Diri diri gömülen kız çocuğuna sorulduğu zaman;"},{"n":9,"t":"Hangi günahtan dolayı öldürüldüğü,"},{"n":10,"t":"Sayfalar açıldığı zaman;"},{"n":11,"t":"Gök yerinden oynatıldığı zaman;"},{"n":12,"t":"Cehennem kızıştırıldığı zaman;"},{"n":13,"t":"Ve Cennet yaklaştırıldığı zaman;"},{"n":14,"t":"Kişi önceden ne hazırladığını bilecektir."},{"n":15,"t":"Andolsun sinenlere;"},{"n":16,"t":"Akıp akıp yuvalarına girenlere;"},{"n":17,"t":"kararmaya başlayan geceye;"},{"n":18,"t":"Ağarmaya başlayan sabaha;"},{"n":19,"t":"Şüphesiz ki bu; şerefli bir elçinin sözüdür."},{"n":20,"t":"Arş’ın sahibi katında değerlidir ve güçlüdür."},{"n":21,"t":"Kendisine uyulandır, emindir."},{"n":22,"t":"Sizin arkadaşınız asla deli değildir."},{"n":23,"t":"Andolsun ki; onu, apaçık ufukta görmüştür."},{"n":24,"t":"Gaybdan ötürü o, asla suçlu da değildir."},{"n":25,"t":"Bu, kovulmuş şeytanın sözü değildir."},{"n":26,"t":"Böyleyken nereye gidiyorsunuz?"},{"n":27,"t":"O; ancak alemler için bir öğüttür."},{"n":28,"t":"Sizden doğru olmak isteyenler için."},{"n":29,"t":"Alemlerin Rabbı olan Allah dilemedikçe, sizler dileyemezsiniz."}],[{"n":1,"t":"Gök yarıldığı zaman;"},{"n":2,"t":"Yıldızlar saçıldığı zaman;"},{"n":3,"t":"Denizler kaynaştığı zaman;"},{"n":4,"t":"Kabirlerin içi dışına getirildiği zaman;"},{"n":5,"t":"Kişi neyi takdim edip neyi te’hir ettiğini bilir."},{"n":6,"t":"Ey insan; keremi bol Rabbına karşı seni ne aldattı?"},{"n":7,"t":"O ki; seni yaratmış, sana şekil vermiş ve düzeltmiştir."},{"n":8,"t":"Seni istediği şekilde terkib etmiştir."},{"n":9,"t":"Hayır; bilakis siz, dini yalan sayıyorsunuz."},{"n":10,"t":"Halbuki sizin üzerinizde koruyucular vardır."},{"n":11,"t":"Çok şerefli yazıcılar."},{"n":12,"t":"Ne yaptığınızı bilirler."},{"n":13,"t":"Şüphesiz ki iyiler; Cennettedirler."},{"n":14,"t":"Ve şüphesiz ki, kötüler de alevli ateştedirler."},{"n":15,"t":"Din günü oraya girerler."},{"n":16,"t":"Ve orada kaybolacak değildirler."},{"n":17,"t":"Din gününün ne olduğunu sen nereden bileceksin."},{"n":18,"t":"Yine sen nereden bileceksin, din gününün ne olduğunu?"},{"n":19,"t":"O, öyle bir gündür ki; kimse kimseye hiçbir şeyle fayda sağlamaz. Ve o gün, emir Allah’ındır."}],[{"n":1,"t":"Ölçüde ve tartıda hile yapanların vay haline."},{"n":2,"t":"Onlar ki; insanlardan bir şey aldıkları zaman kendileri ölçerek tam alırlar."},{"n":3,"t":"Ama onlara bir şey ölçüp tartarak verdikleri zaman, eksik tutarlar."},{"n":4,"t":"Onlar, kendilerinin diriltileceklerini sanmıyorlar mı?"},{"n":5,"t":"Büyük bir gün için."},{"n":6,"t":"Ki insanlar o gün, alemlerin Rabbının huzurunda duracaklar."},{"n":7,"t":"Doğrusu kötülerin kitabı, muhakkak Siccin’dedir."},{"n":8,"t":"Siccin’in ne olduğunu sen nereden bileceksin?"},{"n":9,"t":"Yazılmış bir kitabtır."},{"n":10,"t":"Vay haline o gün, yalanlayanların."},{"n":11,"t":"Onlar ki; din gününü yalanlarlar."},{"n":12,"t":"Halbuki onu, azgın günahkardan başka kimse yalanlamaz."},{"n":13,"t":"Ona ayetlerimiz okunduğunda; öncekilerin masalları, der."},{"n":14,"t":"Hayır; onların kazandıkları, kalblerini paslandırıp körletmiştir."},{"n":15,"t":"Hayır doğrusu onlar, o gün Rabblarından kesinlikle mahrumdurlar."},{"n":16,"t":"Sonra onlar, muhakkak cehenneme yuvarlanacaklardır."},{"n":17,"t":"Sonra da onlara; yalanlayıp durduğunuz işte budur, denilecektir."},{"n":18,"t":"Doğrusu iyilerin kitabı, İlliyyin’dedir."},{"n":19,"t":"İlliyyin’in ne olduğunu sen nereden bileceksin?"},{"n":20,"t":"Yazılmış bir kitabdır."},{"n":21,"t":"Gözde melekler onu görür."},{"n":22,"t":"Şüphesiz iyiler, Naim’dedirler."},{"n":23,"t":"Tahtlar üzerinde temaşa ederler."},{"n":24,"t":"Sen, o nimetin güzelliğini yüzlerinden tanırsın."},{"n":25,"t":"Onlara mühürlü, halis bir şarabtan içirilir."},{"n":26,"t":"Onun sonu misktir. Öyleyse yarışanlar, bunu için yarışsınlar."},{"n":27,"t":"Onun katkısı yüce kaynaktandır."},{"n":28,"t":"Bir pınar ki; gözdeler ondan içerler."},{"n":29,"t":"Doğrusu suç işlemiş olanlar; mü’minlere, gülerlerdi."},{"n":30,"t":"Yanlarından geçtiklerinde birbirlerine göz kırparlardı."},{"n":31,"t":"Ailelerinin yanına döndüklerinde, eğlenerek dönerlerdi."},{"n":32,"t":"Onları gördükleri vakit; muhakkak bunlar sapıklardır, derlerdi."},{"n":33,"t":"Halbuki onlar, bunların üzerine gözcüler olarak gönderilmemişlerdir."},{"n":34,"t":"İşte bugün de iman edenler, o kafirlere gülerler."},{"n":35,"t":"Tahtlar üzerinde, bakarak,"},{"n":36,"t":"O küfredenler, yapageldiklerinin cezasına çarptırıldılar mı diye?"}],[{"n":1,"t":"Gök yarıldığı zaman;"},{"n":2,"t":"Ve Rabbına boyun eğdiğinde. Ki o, zaten boyun eğecektir."},{"n":3,"t":"Yer düzeltildiği zaman;"},{"n":4,"t":"İçinde olanları dışarı atıp boşaldığı zaman;"},{"n":5,"t":"Ve Rabbına boyun eğdiğinde. Ki o, zaten boyun eğecektir."},{"n":6,"t":"Ey insan; sen Rabbın için çalışıp çabaladın, nihayet O’na kavuşacaksın."},{"n":7,"t":"Kimin kitabı sağından verilirse;"},{"n":8,"t":"Kolayca bir hesab ile muhasebe edilecektir."},{"n":9,"t":"Ve ailesine de sevinçli olarak dönecektir."},{"n":10,"t":"Ama kimin de kitabı arkasından verilirse;"},{"n":11,"t":"Derhal helakini temenni edecektir."},{"n":12,"t":"Ve çılgın aleve girecektir."},{"n":13,"t":"Çünkü o, ailesi içinde iken şımarıktı."},{"n":14,"t":"O, hiç dönmeyeceğini sanmıştı."},{"n":15,"t":"Hayır; muhakkak Rabbı, onu görmekteydi."},{"n":16,"t":"And ederim o şafağa;"},{"n":17,"t":"Geceye ve derleyip topladığı şeye;"},{"n":18,"t":"Ve toplu halde geldiğinde aya;"},{"n":19,"t":"Muhakkak siz; bir durumdan diğerine uğratılacaksınız."},{"n":20,"t":"Öyleyse, ne oluyor onlara da inanmıyorlar?"},{"n":21,"t":"Ve Kur’an okunduğu zaman secde etmiyorlar."},{"n":22,"t":"Bilakis o küfredenler, yalanlıyorlar."},{"n":23,"t":"Halbuki Allah, onların sakındıklarını en iyi bilendir."},{"n":24,"t":"Onlara elim bir azabı müjdele."},{"n":25,"t":"Ancak iman edip salih amel işleyenler müstesna. Onlara bitip tükenmeyen bir ecir vardır."}],[{"n":1,"t":"Andolsun; burçlar dolu semaya."},{"n":2,"t":"Ve vaadolunan güne,"},{"n":3,"t":"Şehadet edene ve şehadet edilene."},{"n":4,"t":"Uhdud ashabının canı çıksın,"},{"n":5,"t":"Tutuşturucu ateşlerle,"},{"n":6,"t":"Hani onlar, onun çevresinde oturmuşlardı."},{"n":7,"t":"Mü’minlere yaptıklarını seyretmekteydiler."},{"n":8,"t":"Onlar; ancak Aziz, Hamid Allah’a inandıkları için mü’minlerden öç almışlardı."},{"n":9,"t":"O ki; göklerin ve yerin mülkü kendisinindir. Ve Allah; her şeye Şahid’dir."},{"n":10,"t":"Şüphesiz ki mü’min erkekleri ve mü’min kadınları belaya uğratanlar sonra da tevbe etmemiş olanlar, işte onlar için cehennem azabı vardır. Ve yakıcı azab da onlaradır."},{"n":11,"t":"Doğrusu iman edip salih amel işlemiş olanlar için, altlarından ırmaklar akan cennetler vardır. İşte büyük kurtuluş budur."},{"n":12,"t":"Doğrusu Rabbının yakalayışı amansızdır."},{"n":13,"t":"Önce yaratıp sonra tekrarlayan O’dur, O."},{"n":14,"t":"O; Ğafur’dur, Vedud’dur."},{"n":15,"t":"Arş’ın sahibidir, Mecid’dir."},{"n":16,"t":"Dilediğini mutlaka yapandır."},{"n":17,"t":"O orduların haberi haberi, sana geldi mi?"},{"n":18,"t":"Firavun ve Semud’un."},{"n":19,"t":"Doğrusu küfredenler, yalanlamadadırlar."},{"n":20,"t":"Allah ise onları arkadan kuşatandır."},{"n":21,"t":"Doğrusu o; şanlı bir Kur’an’dır."},{"n":22,"t":"Levh-i Mahfuz’dadır."}],[{"n":1,"t":"Andolsun göğe ve Tarık’a."},{"n":2,"t":"Nereden bileceksin sen Tarık’ın ne olduğunu?"},{"n":3,"t":"O, delen yıldızdır."},{"n":4,"t":"Hiç bir nefis yoktur ki mutlaka onun üzerinde bir gözeten bulunmasın."},{"n":5,"t":"Şu halde insan bir baksın, neden yaratılmıştır?"},{"n":6,"t":"O, atılıp dökülen bir sudan yaratılmıştır."},{"n":7,"t":"Bel kemiği ile göğüslerin arasından çıkar."},{"n":8,"t":"Şüphe yok ki O, onu yeniden döndürmeye kadirdir."},{"n":9,"t":"O gün, sırlar yoklanıp meydana çıkarılacaktır."},{"n":10,"t":"Artık onun gücü de, yardımcısı da yoktur."},{"n":11,"t":"Andolsun o dönüş yeri olan göğe."},{"n":12,"t":"Ve yarılan yere,"},{"n":13,"t":"Ki doğrusu bu, kesin bir sözdür,"},{"n":14,"t":"Ve o, bir şaka değildir."},{"n":15,"t":"Gerçekten onlar düzen kuruyorlar,"},{"n":16,"t":"Ben de bir düzen kurmaktayım."},{"n":17,"t":"Sen; şimdilik kafirlere mühlet ver, onları biraz geciktir."}],[{"n":1,"t":"Rabbının o çok yüce adını tesbih et."},{"n":2,"t":"Ki O, yaratıp şekil vermiştir."},{"n":3,"t":"Ki O, takdir edip doğru yolu göstermiştir."},{"n":4,"t":"Ki O, yeşilliği çıkarmıştır."},{"n":5,"t":"Sonra da onu kupkuru, siyah bir çöpe çevirmiştir."},{"n":6,"t":"Seni okutacağız da hiç unutmayacaksın."},{"n":7,"t":"Yalnız Allah’ın dilediği başka. Çünkü O, açığı da, gizli olanı da bilir."},{"n":8,"t":"Ve seni kolay olana muvaffak edeceğiz."},{"n":9,"t":"O halde öğüt fayda verecekse, öğüt ver."},{"n":10,"t":"Korkacak olan öğüt alacaktır."},{"n":11,"t":"Bedbaht olan ise ondan kaçınır."},{"n":12,"t":"Ki o, en büyük ateşe girecek olandır."},{"n":13,"t":"O, orada ne ölecek, ne de dirilecektir."},{"n":14,"t":"Doğrusu arınan, felah bulmuştur."},{"n":15,"t":"Rabbının adını anıp namaz kılan."},{"n":16,"t":"Fakat siz, dünya hayatını tercih ediyorsunuz."},{"n":17,"t":"Halbuki ahiret, daha hayırlı ve daha bakidir."},{"n":18,"t":"Şüphesiz ki bu, ilk sahifelerdedir."},{"n":19,"t":"İbrahim’in ve Musa’nın sahifelerinde."}],[{"n":1,"t":"Her şeyi sarıp kaplayacak olanın haberi sana geldi mi?"},{"n":2,"t":"Yüzler vardır ki, o gün zillete bürünmüştür."},{"n":3,"t":"Zor işler altında bitkin düşmüştür."},{"n":4,"t":"Kızgın bir ateşe girerler."},{"n":5,"t":"Kızgın bir kaynaktan içirilecektirler."},{"n":6,"t":"Kötü kokulu, kuru bir dikenden başka yiyecekleri yoktur."},{"n":7,"t":"O, ne semirtir, ne de açlığı giderir."},{"n":8,"t":"Yüzler de vardır ki; o gün, parıl parıldır."},{"n":9,"t":"Çalıştıklarından hoşnuddur."},{"n":10,"t":"Yüksek bir cennettedir."},{"n":11,"t":"Orada boş bir laf işitmezler."},{"n":12,"t":"Orada akan bir pınar vardır."},{"n":13,"t":"Orada yüksek tahtlar,"},{"n":14,"t":"Yerleştirilmiş kaseler,"},{"n":15,"t":"Sıra sıra dizilmiş yastıklar,"},{"n":16,"t":"Serilmiş saçaklı halılar vardır."},{"n":17,"t":"Onlar deveye bakmazlar mı, nasıl yaratılmıştır?"},{"n":18,"t":"Göğe de. Nasıl yükseltilmiştir?"},{"n":19,"t":"Dağlara da. Nasıl dikilmiştir?"},{"n":20,"t":"Yere de. Nasıl yayılmıştır?"},{"n":21,"t":"Öğüt ver, çünkü sen; ancak bir öğütçüsün."},{"n":22,"t":"Onların üzerine zor kullanıcı değilsin."},{"n":23,"t":"Ancak kim yüz çevirir ve küfrederse;"},{"n":24,"t":"Allah, onu en büyük azab ile azablandırır."},{"n":25,"t":"Şüphesiz onların dönüşü, ancak Bizedir."},{"n":26,"t":"Sonra hesablarını görmek de muhakkak Bize düşer."}],[{"n":1,"t":"Andolsun fecre,"},{"n":2,"t":"Ve on geceye,"},{"n":3,"t":"Hem çifte, hem teke."},{"n":4,"t":"Gelip geçeceği demde geceye,"},{"n":5,"t":"Akıl sahipleri için bunların her biri birer yemine değmez mi?"},{"n":6,"t":"Görmez misin, Rabbın nasıl yaptı Ad’a?"},{"n":7,"t":"Sütunlar sahibi İrem’e?"},{"n":8,"t":"Ki o, şehirlerde bir benzeri yaratılmayandı."},{"n":9,"t":"Dağ yamacında kayaları oyan Semud kavmine?"},{"n":10,"t":"Kazıklar sahibi Firavun’a,"},{"n":11,"t":"Ki bunlar, memleketlerde azgınlık etmişlerdi."},{"n":12,"t":"Ve fesadı çoğaltmışlardı."},{"n":13,"t":"Bu sebeple Rabbın onları, azab kırbacından geçirdi."},{"n":14,"t":"Doğrusu Rabbın hep gözetlemekteydi."},{"n":15,"t":"Ama insan; Rabbı kendisini deneyip kerem eder ve nimet verirse: Rabbım beni şerefli kıldı, der."},{"n":16,"t":"Ama onu denemek üzere rızkını daraltırsa: Rabbım beni fakir düşürdü, der."},{"n":17,"t":"Hayır; doğrusu siz, yetime ikram etmezsiniz."},{"n":18,"t":"Yoksulu yedirmek için birbirinizi teşvik etmezsiniz."},{"n":19,"t":"Mirası hak gözetmeden yersiniz."},{"n":20,"t":"Malı da pek çok seversiniz."},{"n":21,"t":"Ama yer; parça parça dağıtıldığında."},{"n":22,"t":"Melekler sıra sıra dizilip Rabbının buyruğu geldiğinde."},{"n":23,"t":"Cehennem o gün getirilir. İnsan o gün, hatırlayacak ama hatırlamadan ona ne?"},{"n":24,"t":"Keşke bu hayatım için önceden bir şey yapsaydım, der."},{"n":25,"t":"O gün O’nun azabı gibi hiç bir kimse azab edemez."},{"n":26,"t":"O’nun vurduğu bağı kimse vuramaz."},{"n":27,"t":"Ey huzur içinde olan can."},{"n":28,"t":"Dön Rabbına. Sen O’ndan hoşnud, O da senden razı olarak."},{"n":29,"t":"Haydi gir kullarımın arasına."},{"n":30,"t":"Gir, cennetime."}],[{"n":1,"t":"Şu beldeye yemin ederim;"},{"n":2,"t":"Sen de bu beldede oturmuşsun."},{"n":3,"t":"Doğurana da, doğurduğuna da andolsun ki;"},{"n":4,"t":"Biz, insanı gerçekten meşakkat içinde yarattık."},{"n":5,"t":"Yoksa o, kimsenin kendisine güç yetiremeyeceğini mi sanıyor?"},{"n":6,"t":"Yığın yığın mal tüketmişimdir, diyor."},{"n":7,"t":"Kimsenin kendisini görmediğini mi sanıyor?"},{"n":8,"t":"Biz; onun için iki göz var etmedik mi?"},{"n":9,"t":"Bir dil ve iki dudak."},{"n":10,"t":"Biz; ona iki de yol gösterdik."},{"n":11,"t":"Ama o, sarp yokuşu aşmaya girişemedi."},{"n":12,"t":"Sarp yokuşun ne olduğunu sen nereden bileceksin?"},{"n":13,"t":"Bir kul azad etmektir."},{"n":14,"t":"Yahut açlık gününde yemek yedirmektir,"},{"n":15,"t":"Yakınlığı olan bir yetime,"},{"n":16,"t":"Yahut yerde sürünen bir yoksula."},{"n":17,"t":"Sonra da iman edenlerden, birbirine sabrı tavsiye, merhameti tavsiye edenlerden olmaktır."},{"n":18,"t":"İşte bunlar, sağcılardır."},{"n":19,"t":"Ayetlerimize küfredenler ise, solcuların kendileridir."},{"n":20,"t":"Onlara sımsıkı kapatılmış bir ateş vardır."}],[{"n":1,"t":"Andolsun güneşe ve aydınlığına."},{"n":2,"t":"Ardından gelmekte olan aya."},{"n":3,"t":"Onu açığa çıkardığında gündüze,"},{"n":4,"t":"Örtüp bürüdüğünde geceye,"},{"n":5,"t":"Göğe ve onu bina edene,"},{"n":6,"t":"Yere ve onu yayana,"},{"n":7,"t":"Nefse ve onu düzenleyene,"},{"n":8,"t":"Sonra da ona, hem kötülüğü hem de takvayı ilham edene,"},{"n":9,"t":"Onu arıtan, gerçekten felaha ermiştir,"},{"n":10,"t":"Ve onu örtüp kirleten ise muhakkak ziyana uğramıştır."},{"n":11,"t":"Semud, azgınlığı yüzünden yalanladı."},{"n":12,"t":"En azgınları ileri tıldığında."},{"n":13,"t":"Allah’ın peygamberi onlara: Allah’ın devesi ve onun su hakkı, demişti."},{"n":14,"t":"Fakat onu yalanladılar ve derken deveyi kestiler. Bunu üzerine günahları sebebiyle Rabbları onları kırıp geçirerek yerle bir etti."},{"n":15,"t":"Bunun sonundan hiç korkmayarak."}],[{"n":1,"t":"Andolsun bürüyüp örttüğü zaman, geceye,"},{"n":2,"t":"Açıldığı zaman gündüze,"},{"n":3,"t":"Erkeği ve dişiyi yaratana."},{"n":4,"t":"Doğrusu sizin çalışmalarınız bölüm bölümdür."},{"n":5,"t":"Kim verir ve sakınırsa;"},{"n":6,"t":"En güzeli de tasdik ederse,"},{"n":7,"t":"Biz de onu en kolaya muvaffak kılarız."},{"n":8,"t":"Ama kim de cimrilik eder ve kendini müstağni sayarsa;"},{"n":9,"t":"Ve en güzeli yalanlarsa,"},{"n":10,"t":"Biz de ona en güç olanı kolaylaştırırız."},{"n":11,"t":"Halbuki düştüğü zaman, malı o kimseye asla fayda vermez."},{"n":12,"t":"Şüphesiz ki, Bizim üzerimizedir hidayet."},{"n":13,"t":"Ve hiç şüphesiz ahiret de, dünya da Bizimdir."},{"n":14,"t":"Sizi alevler saçan ateşle uyardım."},{"n":15,"t":"Oraya ancak en azgın olan girer."},{"n":16,"t":"Yalanlayıp yüz çevirmiş olan,"},{"n":17,"t":"En çok sakınan ise; ondan uzak tutulur."},{"n":18,"t":"Ki o, malını temizlemek için verir."},{"n":19,"t":"O’nun nezdinde, bir kimsenin karşılık olarak verilecek hiç bir nimeti yoktur."},{"n":20,"t":"Ancak yüce Rabbının hoşnudluğunu gözetmek içindir."},{"n":21,"t":"Elbette kendisi de hoşnud olacaktır."}],[{"n":1,"t":"Andolsun, kuşluk vaktine."},{"n":2,"t":"Ve sükuna erdiğinde geceye."},{"n":3,"t":"Rabbın seni ne terk etti, ne de darıldı."},{"n":4,"t":"Ahiret, elbette senin için dünyadan daha hayırlıdır."},{"n":5,"t":"Şüphesiz Rabbın, sana verecek ve sen, hoşnud olacaksın."},{"n":6,"t":"O; seni öksüz bulup da barındırmadı mı?"},{"n":7,"t":"Seni şaşırmış bulup da doğru yola eriştirmedi mi?"},{"n":8,"t":"Seni fakir bulup da zenginleştirmedi mi?"},{"n":9,"t":"O halde sakın yetime kahretme."},{"n":10,"t":"Ve bir şey isteyeni azarlama."},{"n":11,"t":"Rabbının nimetine gelince ondan sözet."}],[{"n":1,"t":"Senin göğsünü açmadık mı?"},{"n":2,"t":"Yükünü üzerinden atmadık mı?"},{"n":3,"t":"Ki o senin belini bükmüştü."},{"n":4,"t":"Ve senin şanını yükseltmedik mi?"},{"n":5,"t":"Muhakkak ki güçlükle beraber bir kolaylık vardır."},{"n":6,"t":"Elbette güçlükle beraber bir kolaylık vardır."},{"n":7,"t":"Öyleyse boş kaldın mı hemen koyul,"},{"n":8,"t":"Ve Rabbına koş."}],[{"n":1,"t":"Andolsun; incire ve zeytine,"},{"n":2,"t":"Sina dağına,"},{"n":3,"t":"Ve şu emin kente,"},{"n":4,"t":"Doğrusu Biz; insanı en güzel biçimde yarattık,"},{"n":5,"t":"Sonra onu, aşağıların aşağısına döndürdük."},{"n":6,"t":"Yalnız iman edip salih amel işleyenler müstesna. Onlara kesintisiz mükafat vardır."},{"n":7,"t":"Öyleyse bundan sonra hangi şey sana dini yalanlatabilir?"},{"n":8,"t":"Allah; hükmedenlerin en iyi hükmedeni değil mi?"}],[{"n":1,"t":"Yaratan Rabbının adıyla oku."},{"n":2,"t":"O; insanı pıhtılaşmış kandan yarattı."},{"n":3,"t":"Oku, Rabbın nihayetsiz kerem sahibidir."},{"n":4,"t":"Ki O, kalemle öğretti."},{"n":5,"t":"İnsana bilmediğini öğretmiştir."},{"n":6,"t":"Hayır; insan azgınlık eder."},{"n":7,"t":"Kendini müstağni gördüğü için."},{"n":8,"t":"Dönüş, şüphesiz ancak Rabbınadır."},{"n":9,"t":"O yasaklayanı gördün mü?"},{"n":10,"t":"Bir kulu, namaz kılarken?"},{"n":11,"t":"Gördün mü; ya o kul doğru yolda ise?"},{"n":12,"t":"Veya takvayı emrettiyse?"},{"n":13,"t":"Gördün mü; ya yalan saydı ve yüz çevirdi ise?"},{"n":14,"t":"Bilmez mi ki; Allah gerçekten görmektedir?"},{"n":15,"t":"Ama bundan vazgeçmezse; andolsun ki; onu alnından tutup sürükleriz."},{"n":16,"t":"Yalancı, günahkar alnından."},{"n":17,"t":"Öyleyse topluluğunu çağırsın dursun."},{"n":18,"t":"Biz de zebanileri çağırırız."},{"n":19,"t":"Sakın, sen ona uyma. Secde et ve yaklaş."}],[{"n":1,"t":"Doğrusu Biz; onu, Kadr gecesinde indirdik."},{"n":2,"t":"Kadr gecesinin ne olduğunu bilir misin sen?"},{"n":3,"t":"Kadr gecesi; bin aydan daha hayırlıdır."},{"n":4,"t":"Melekler ve Ruh, o gece Rabblarının izniyle her iş için iner de iner."},{"n":5,"t":"O, tanyeri ağarıncaya kadar bir selamettir."}],[{"n":1,"t":"Kitab ehlinden ve müşriklerden küfredenler, kendilerine apaçık bir huccet gelinceye kadar vazgeçecek değillerdi."},{"n":2,"t":"Arınmış sayfaları okuyan, Allah katından bir peygamber."},{"n":3,"t":"İçinde en doğru yazılar bulunan."},{"n":4,"t":"Ama kitab verilmiş olanlar, kendilerine apaçık huccetler geldikten sonra ayrılığa düştüler."},{"n":5,"t":"Halbuki onlar; doğruya yönelerek, dini yalnız Allah’a tahsis ederek O’na kulluk etmek, namazı kılmak ve zekatı vermekle emrolunmuşlardı. En doğru din de işte budur."},{"n":6,"t":"Şüphesiz ki kitab ehlinden ve müşriklerden küfredenler, cehennem ateşindedirler. Onlar, orada temelli kalacaklardır. Yaratıkların en kötüsü de işte bunlardır."},{"n":7,"t":"Muhakkak ki iman etmiş olup salih ameller işleyenler; işte onlar da, yaratıkların en hayırlısıdırlar."},{"n":8,"t":"Rabbları katında onların mükafatı; altlarından ırmaklar akan ve orada temelli kalacakları Adn cennetleridir. Allah onlardan hoşnud, onlar da O’ndan razıdırlar. İşte bu, Rabbından korkan kimseye mahsustur."}],[{"n":1,"t":"Yer, sarsıldıkça sarsıldığı zaman;"},{"n":2,"t":"Ve yer, bütün ağırlıklarını çıkardığı zaman;"},{"n":3,"t":"İnsan; buna ne oluyor? dediği zaman,"},{"n":4,"t":"İşte o gün; o, bütün haberlerini anlatacaktır."},{"n":5,"t":"Çünkü Rabbın kendisine vahyetmiştir."},{"n":6,"t":"O gün insanlar, yaptıklarının kendilerine gösterilmesi için bölük bölük dönerler."},{"n":7,"t":"Kim, zerre mikdarı hayır işlerse; onu görür."},{"n":8,"t":"Kim de zerre mikdarı şer işlerse; onu görür."}],[{"n":1,"t":"Andolsun; o koştukça koşanlara,"},{"n":2,"t":"Ve kıvılcımlar saçanlara,"},{"n":3,"t":"Sabah sabah baskın yapanlara,"},{"n":4,"t":"Ve tozu dumana katanlara,"},{"n":5,"t":"Derken bir topluluğun ortasına dalanlara,"},{"n":6,"t":"Gerçekten insan; Rabbına karşı çok nankördür."},{"n":7,"t":"Doğrusu kendisi de buna, hakkıyla şahiddir."},{"n":8,"t":"Gerçekten o, hayır sevgisinde pek şiddetlidir."},{"n":9,"t":"Yoksa bilmez mi kabirdekilerin çıkarılacağı zamanı?"},{"n":10,"t":"Göğüslerde bulunanların derlenip toparlanacağını?"},{"n":11,"t":"Muhakkak ki Rabbları, o gün, onların her şeyinden haberdardır."}],[{"n":1,"t":"Felaket kapısını çalacak olan,"},{"n":2,"t":"Nedir o felaket kapısını çalacak olan?"},{"n":3,"t":"O felaket kapısını çalacak olanın ne olduğunu bilir misin sen?"},{"n":4,"t":"O gün; insanlar yaygın pervaneye dönecekler."},{"n":5,"t":"Dağlar; atılmış renkli yünler gibi olacak."},{"n":6,"t":"Ama kimin tartıları ağır gelirse;"},{"n":7,"t":"O, hoş bir hayat içindedir."},{"n":8,"t":"Ama kimin de tartıları hafif gelirse;"},{"n":9,"t":"Artık onun da durağı Haviye’dir."},{"n":10,"t":"Onun ne olduğunu bilir misin sen?"},{"n":11,"t":"Kızgın bir ateştir."}],[{"n":1,"t":"Çokluk ile böbürlenmeniz, sizi öylesine oyaladı ki;"},{"n":2,"t":"Mezarlıkları bile ziyaret ettiniz,"},{"n":3,"t":"Hayır; ilerde bileceksiniz."},{"n":4,"t":"Yine hayır; ilerde bileceksiniz."},{"n":5,"t":"Hayır; eğer kesin bir bilgi ile bilseydiniz,"},{"n":6,"t":"Andolsun ki; cehennemi muhakkak göreceksiniz."},{"n":7,"t":"Andolsun ki; yine onu gözünüzle kesin olarak göreceksiniz."},{"n":8,"t":"Sonra o gün, andolsun ki; nimetlerden sorulacaksınız."}],[{"n":1,"t":"Asr’a andolsun ki:"},{"n":2,"t":"Muhakkak insan, hüsrandadır."},{"n":3,"t":"Ancak iman edenler ve salih amel işleyenler müstesnadır. Bir de birbirlerine hakkı tavsiye edenler ve sabrı tavsiye edenler"}],[{"n":1,"t":"Diliyle çekiştirip yüzünde de alay edenin vay haline."},{"n":2,"t":"Ki o, mal toplayıp onu sayar."},{"n":3,"t":"Malının kendisini ebedi kılacağını sanır."},{"n":4,"t":"Hayır; andolsun ki o, Hutame’ye atılacaktır."},{"n":5,"t":"Hutame’nin ne olduğunu bilir misin sen?"},{"n":6,"t":"O, Allah’ın tutuşturulmuş bir ateşidir."},{"n":7,"t":"Ki tırmanıp yüreklerin içine işler."},{"n":8,"t":"Bu, onların üzerine kapatılmıştır."},{"n":9,"t":"Uzatılmış sütunlar arasında."}],[{"n":1,"t":"Rabbının; fil sahiplerine ne ettiğini görmedin mi?"},{"n":2,"t":"O; bunların düzenlerini boşa çıkarmadı mı?"},{"n":3,"t":"O; bunların üzerine sürülerle kuşlar gönderdi."},{"n":4,"t":"Ki, onların üzerine pişkin tuğladan taşlar atıyorlardı."},{"n":5,"t":"Nihayet onları, yenik ekin yaprağı gibi yapıverdi."}],[{"n":1,"t":"Kureyş’in alıştırılması için."},{"n":2,"t":"Yaz ve kış yolculuklarına alıştırılmasından dolayı,"},{"n":3,"t":"Bu evin Rabbına ibadet etsinler."},{"n":4,"t":"Ki o, kendilerini açlıktan kurtarmış ve korkudan emin kılmıştır."}],[{"n":1,"t":"Dini yalanlayanı gördün mü?"},{"n":2,"t":"İşte o’dur yetimi şiddetle iten,"},{"n":3,"t":"Yoksulu doyurmaya teşvik etmeyen,"},{"n":4,"t":"Vay o namaz kılanların haline,"},{"n":5,"t":"Ki onlar; kıldıkları namazdan gafildirler."},{"n":6,"t":"Ki onlar; gösteriş yaparlar,"},{"n":7,"t":"Ve zekatı da men’ederler."}],[{"n":1,"t":"Gerçekten Biz; sana, Kevser’i verdik."},{"n":2,"t":"Öyleyse Rabbın için namaz kıl ve kurban kes."},{"n":3,"t":"Sana buğzeden; şüphesiz ki zürriyetsiz olan, işte odur."}],[{"n":1,"t":"De ki: Ey kafirler;"},{"n":2,"t":"Ben, sizin tapmakta olduklarınıza tapmam."},{"n":3,"t":"Benim taptığıma da sizler tapmazsınız."},{"n":4,"t":"Ben de sizin taptıklarınıza, tapacak değilim."},{"n":5,"t":"Benim taptığıma da sizler, tapacak değilsiniz."},{"n":6,"t":"Sizin dininiz size; benim dinim banadır."}],[{"n":1,"t":"Allah’ın nusreti ve fetih geldiğinde,"},{"n":2,"t":"Ve insanların fevc fevc Allah’ın dinine girdiklerini gördüğünde;"},{"n":3,"t":"Hemen Rabbını hamd ile tesbih et ve O’ndan mağfiret dile. Şüphesiz ki O; Tevvab olandır."}],[{"n":1,"t":"İki eli kurusun Ebu Leheb’in ve yok olsun."},{"n":2,"t":"Malı ve kazandığı ona fayda vermedi."},{"n":3,"t":"Alevli ateşe girecektir."},{"n":4,"t":"Karısı da odun taşıyarak;"},{"n":5,"t":"Boynunda bükülmüş bir ip olduğu halde."}],[{"n":1,"t":"De ki: O Allah; bir tektir."},{"n":2,"t":"Allah’tır, Samed’dir."},{"n":3,"t":"Doğurmamış ve doğurulmamıştır."},{"n":4,"t":"Hiçbir şey O’na denk değildir."}],[{"n":1,"t":"De ki: Tan yerini ağartan Rabba sığınırım."},{"n":2,"t":"Yaratıkların şerrinden,"},{"n":3,"t":"Bastırdığı zaman, karanlığın şerrinden,"},{"n":4,"t":"Düğümlere üfürenlerin şerrinden,"},{"n":5,"t":"Hased ettiğinde, hased edenlerin şerrinden."}],[{"n":1,"t":"De ki: İnsanların Rabbına sığınırım,"},{"n":2,"t":"İnsanların malikine,"},{"n":3,"t":"İnsanların Tanrısına,"},{"n":4,"t":"O sinsi şeytanın şerrinden."},{"n":5,"t":"Ki o, insanların kalblerine hep vesvese verir."},{"n":6,"t":"Gerek cinnlerden, gerek insanlardan."}]];
